    get_closest_chest = function()
        local pos = local_player.root_part.Position
        local closest_distance = math.huge

        for _, chest in pairs(workspace.Thrown:GetChildren()) do
            if chest:FindFirstChild('Lid') and chest:FindFirstChild('InteractPrompt') then
                local dist = (chest.Lid.Position - pos).Magnitude
                if (dist <= closest_distance and dist <= 10) then
                    closest_distance = dist
                    return chest
                end
            end
        end

        return nil
    end,

    fire_loot_all = function(remote)
        remote:FireServer("LOOT_ALL")
    end,

    identify_color = function(self, hex_color, tolerance)
        local function hex_to_rgb(hex_color)
            hex_color = hex_color:gsub("#", "")

            local r = tonumber(hex_color:sub(1,2), 16) or 0
            local g = tonumber(hex_color:sub(3,4), 16) or 0
            local b = tonumber(hex_color:sub(5,6), 16) or 0
            
            return math.min(r, 255), math.min(g, 255), math.min(b, 255)
        end

        local function colors_are_similar(color1, color2, tolerance)
            local r1, g1, b1 = hex_to_rgb(color1)
            local r2, g2, b2 = hex_to_rgb(color2)

            local diffR = math.abs(r1 - r2)
            local diffG = math.abs(g1 - g2)
            local diffB = math.abs(b1 - b2)

            return diffR <= tolerance and diffG <= tolerance and diffB <= tolerance
        end

        for name, hex in pairs(self.color_rarities) do
            if colors_are_similar(hex, hex_color, tolerance) then
                return name
            end
        end

        return nil
    end,

    info_loot = function(remote, loot)
        local WEBHOOKEXISTS = false
        if WEBHOOKEXISTS then end

        pcall(function()
            if aztup.flags.notify_on_loot and not notified[loot] then
                notified[loot] = true;
                task.delay(10, function()
                    notified[loot] = nil;
                end);
                if aztup.flags.play_sound_noti then
                    Logger:notify_sound("Looted: " .. loot.Title.Text)
                else
                    Logger:notify("Looted: " .. loot.Title.Text)
                end;
            end;
        end);

        remote:FireServer(loot.Name)
        task.wait(0.01)
    end,

    is_overweight = function()
        local current_carry_load = local_player.character.Humanoid:GetAttribute('CarryLoad')
        local max_carry_load     = local_player.character.Humanoid:GetAttribute('CarryMax')

        local obesity = max_carry_load + (max_carry_load * 0.2)

        return current_carry_load >= obesity
    end,

    chest_check = function(loot_object_container)
        local function options_true(options, specific_option)
            for option, boolean in pairs(options) do

                if specific_option == nil and boolean then
                    return true
                end

                if option == specific_option and boolean then
                    return true
                end
            end

            return false
		end

        local function found_kyrsan_medallion(loot_objects)
            for _, object in pairs(loot_objects) do
                if object:IsA('TextButton') and object.Name:find('Kyrsan Medallion') then
                    return true
                end
            end

            return false
        end

        local loot_all_no_filter            = aztup_options.loot_options.Value['Loot All'] and not options_true(aztup_options.loot_all_rarities.Value)
        local always_loot_krysan_medallions = aztup_options.loot_options.Value['Always Loot Items'] and (aztup_options.always_loot_dropdown.Value['Kyrsan Medallions'])

        return loot_all_no_filter or (always_loot_krysan_medallions and found_kyrsan_medallion(loot_object_container:GetChildren()))
    end,

    is_loot_container = function(choice_prompt)
        local title = choice_prompt:FindFirstChild('ChoiceFrame'):FindFirstChild('Title')
        return title.Text:lower():find('treasure chest') or title.Text:lower():find('loot')
    end
}

function auto_loot:item_loot(remote, loot)
    local item_loot = aztup_options.loot_options.Value['Item Loot']

    local function input_parse(input)
        local item_names = {}

        for segment in string.gmatch(input, "([^;]*)") do
            local trimmed_segment = segment:match("^%s*(.-)%s*$")
            if trimmed_segment ~= "" then
                table.insert(item_names, trimmed_segment)
            end
        end

        return item_names
    end

    if item_loot then
        for _, name in pairs(input_parse(aztup_options.item_loot_input.Value)) do
            if loot.Name:lower():find(name:lower()) then
                self.info_loot(remote, loot)
                return true
            end
        end
    end

    return false
end

function auto_loot:loot_all(remote, loot)
    local selected_rarities = aztup_options.loot_all_rarities.Value
    local item_rarity = self.identify_color(self, loot.BackgroundColor3:ToHex(), 1)

    local function rarities_selected()
        for rarity, boolean in pairs(selected_rarities) do
            if boolean then
                return true
            end
        end

        return false
    end

    local function is_selected_rarity(item_rarity)
        for rarity, boolean in pairs(selected_rarities) do
            if item_rarity:lower() == rarity:lower() and boolean then
                return true
            end
        end

        return false
    end

    if aztup_options.loot_options.Value['Loot All'] and rarities_selected() and is_selected_rarity(item_rarity) then
        self.info_loot(remote, loot)
        return true
    end

    return false
end

function auto_loot:stat_loot(remote, loot)
    local function stat_parse(input, word)
        local function safe_number_convert(str)
            local num = tonumber(str)
            return num ~= nil and num or 0
        end

        local total_value = 0

        if input then
            for value in input:gmatch("%+(%d+)%s*" .. word) do
                total_value = total_value + safe_number_convert(value)
            end

            for value in input:gmatch("%+(%d+)%%%s*" .. word) do
                total_value = total_value + safe_number_convert(value)
            end
        end 

        if word == 'Physical Armor' then
            total_value = total_value + stat_parse(input, 'PHY Armor')
        end

        if word == 'Elemental Armor' then
            total_value = total_value + stat_parse(input, 'ELM Armor')
        end

        return total_value
    end

    local function precise_stats(stats_to_check, stats)
        local all_stats_meet_criteria = true

        for _, stat in ipairs(stats_to_check) do
            local stat_value = stat_parse(stats, stat[1])

            if stat_value < stat[2] then
                all_stats_meet_criteria = false
                break
            end
        end

        return all_stats_meet_criteria
    end

    local function stats(stats_to_check, stats)
        for _, stat in ipairs(stats_to_check) do
            if stat[2] > 0 and stat_parse(stats, stat[1]) >= stat[2] then
                return true
            end
        end

        return false
    end

    local stats_text        = loot:FindFirstChild('Stats') and loot:FindFirstChild('Stats').Text
    local image_rect_offset = 1000

    if loot:FindFirstChild('Icon') then image_rect_offset = loot:FindFirstChild('Icon').ImageRectOffset.X; end

    local item_types = {
        weapons = function(loot)
			local stat_loot_weapons = aztup_options.stat_loot_dropdown.Value['Weapons']
			local stat_loot_weapons_precise = aztup_options.precise_stat_loot.Value['Weapons']
			local stats_to_check = {
				{"PEN", aztup.flags.stat_loot_weapons_penetration},
				{"Weight", aztup.flags.stat_loot_weapons_weight},
				{"Damage", aztup.flags.stat_loot_weapons_damage}
			}

			if stat_loot_weapons and image_rect_offset == self.icon_offsets.weapons then
				if stat_loot_weapons_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end,

		headwear = function(loot)
			local stat_loot_headwear = aztup_options.stat_loot_dropdown.Value['Headwear']
			local stat_loot_headwear_precise = aztup_options.precise_stat_loot.Value['Headwear']
			local stats_to_check = {
				{"HP", aztup.flags.stat_loot_headwear_health},
				{"ETH", aztup.flags.stat_loot_headwear_ether},
				{"Monster DMG", aztup.flags.stat_loot_headwear_monsterdamage},
				{"Physical Armor", aztup.flags.stat_loot_headwear_physicalarmour},
				{"Elemental Armor", aztup.flags.stat_loot_headwear_elementalarmour},
				{"Monster Armor", aztup.flags.stat_loot_headwear_monsterarmour}
			}

			if stat_loot_headwear and image_rect_offset == self.icon_offsets_headwear then
				if stat_loot_headwear_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end,

		facewear = function(loot)
			local stat_loot_facewear = aztup_options.stat_loot_dropdown.Value['Facewear']
			local stat_loot_facewear_precise = aztup_options.precise_stat_loot.Value['Facewear']
			local stats_to_check = {
				{"ETH", aztup.flags.stat_loot_facewear_ether},
				{"SAN", aztup.flags.stat_loot_facewear_sanity},
				{"Monster DMG", aztup.flags.stat_loot_facewear_monsterdamage}
			}

			if stat_loot_facewear and image_rect_offset == self.icon_offsets.facewear then
				if stat_loot_facewear_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end,

		earrings = function(loot)
			local stat_loot_earrings = aztup_options.stat_loot_dropdown.Value['Earrings']
			local stat_loot_earrings_precise = aztup_options.precise_stat_loot.Value['Earrings']
			local stats_to_check = {
				{"ETH", aztup.flags.stat_loot_earrings_ether},
				{"SAN", aztup.flags.stat_loot_earrings_sanity},
				{"Monster DMG", aztup.flags.stat_loot_earrings_monsterdamage}
			}

			if stat_loot_earrings and image_rect_offset == self.icon_offsets.earrings then
				if stat_loot_earrings_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end,

		neckwear = function(loot)
			local stat_loot_neckwear = aztup_options.stat_loot_dropdown.Value['Neckwear']
			local stat_loot_neckwear_precise = aztup_options.precise_stat_loot.Value['Neckwear']
			local stats_to_check = {
				{"HP", aztup.flags.stat_loot_neckwear_health},
				{"ETH", aztup.flags.stat_loot_neckwear_ether},
				{"Monster DMG", aztup.flags.stat_loot_neckwear_monsterdamage}
			}

			if stat_loot_neckwear and image_rect_offset == self.icon_offsets.neckwear then
				if stat_loot_neckwear_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end,

		rings = function(loot)
			local stat_loot_rings = aztup_options.stat_loot_dropdown.Value['Rings']
			local stat_loot_rings_precise = aztup_options.precise_stat_loot.Value['Rings']
			local stats_to_check = {
				{"HP", aztup.flags.stat_loot_rings_health},
				{"ETH", aztup.flags.stat_loot_rings_ether},
				{"SAN", aztup.flags.stat_loot_rings_sanity},
				{"Posture", aztup.flags.stat_loot_rings_posture},
				{"Monster Dmg", aztup.flags.stat_loot_rings_monsterdamage}
			}

			if stat_loot_rings and image_rect_offset == self.icon_offsets.rings or image_rect_offset == self.icon_offsets.treasure or loot.Name:lower():find("ring") or loot.Name:lower():find("band") and not loot.Name:lower():find('bandana') then
				if stat_loot_rings_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end,

		arms = function(loot)
			local stat_loot_arms = aztup_options.stat_loot_dropdown.Value['Arms']
			local stat_loot_arms_precise = aztup_options.precise_stat_loot.Value['Arms']
			local stats_to_check = {
				{"HP", aztup.flags.stat_loot_arms_health},
				{"ETH", aztup.flags.stat_loot_arms_ether},
				{"Monster Dmg", aztup.flags.stat_loot_arms_monsterdamage},
				{"Physical Armor", aztup.flags.stat_loot_arms_physicalarmour},
				{"Elemental Armor", aztup.flags.stat_loot_arms_elementalarmour},
				{"Monster Armor", aztup.flags.stat_loot_arms_monsterarmour}
			}

			if stat_loot_arms and image_rect_offset == self.icon_offsets.arms then
				if stat_loot_arms_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end,

		legs = function(loot)
			local stat_loot_legs = aztup_options.stat_loot_dropdown.Value['Legs']
			local stat_loot_legs_precise = aztup_options.precise_stat_loot.Value['Legs']
			local stats_to_check = {
				{"HP", aztup.flags.stat_loot_arms_health},
				{"ETH", aztup.flags.stat_loot_arms_ether},
				{"Monster DMG", aztup.flags.stat_loot_arms_monsterdamage}
			}

			if stat_loot_legs and image_rect_offset == self.icon_offsets.legs then
				if stat_loot_legs_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end
    }

    for item_type, func in pairs(item_types) do
        if aztup_options.loot_options.Value['Stat Loot'] and func(loot) then
            self.info_loot(remote, loot)
            return true
        end
    end

    return false
end

function auto_loot:always_loot(remote, loot)
    local color = loot.BackgroundColor3

    local function loot_relics(loot)
        local option_selected = aztup_options.always_loot_dropdown.Value['Relics']
        local is_relic_rarity = self.identify_color(self, color:ToHex(), 1):lower() == 'relic'
        return option_selected and is_relic_rarity
    end

    local function loot_enchant_stones(loot)
        local function found_enchant(loot)
            for _, name in pairs(auto_loot.enchants) do
                if loot.Name:find(name) then
                    return true
                end
            end

            return false
        end

        local option_selected = aztup_options.always_loot_dropdown.Value['Enchant Stones']
        local is_legendary_rarity = self.identify_color(self, color:ToHex(), 1):lower() == 'legendary'

        return option_selected and is_legendary_rarity and found_enchant(loot)
    end

    local function loot_legendary_weapons(loot)
        local option_selected = aztup_options.always_loot_dropdown.Value['Legendary Weapons']
		local is_weapon = loot:FindFirstChild('Icon') and loot:FindFirstChild("Icon").ImageRectOffset.X == auto_loot.icon_offsets.weapons
		local is_legendary_rarity = self.identify_color(self, color:ToHex(), 1):lower() == "legendary"
		return option_selected and is_weapon and is_legendary_rarity and not self.is_overweight()
    end

    local function loot_deep_gems(loot)
        local function is_gem(loot)
            if loot:FindFirstChild('Title') then
                local name = loot.Title.Text
                if name:lower():match('gem') and not name:lower():match('vibrant gem') then
                    return true
                end
            end

            return false
        end

        local option_selected = aztup_options.always_loot_dropdown.Value['Deep Gems']
        local is_mythic_rarity = self.identify_color(self, color:ToHex(), 1):lower() == 'mythic'

        return option_selected and is_mythic_rarity and not self.is_overweight() and is_gem(loot)
    end

    if aztup_options.loot_options.Value['Always Loot Items'] and (loot_relics(loot) or loot_enchant_stones(loot) or loot_legendary_weapons(loot) or loot_deep_gems(loot)) then
        self.info_loot(remote, loot)
        return true
    end

    return false
end

function auto_loot:main()
    local choice_prompt = local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt')
    local choice_frame = choice_prompt and choice_prompt:FindFirstChild('ChoiceFrame')
    local options = choice_frame and choice_frame:FindFirstChild('Options')
    local remote = choice_prompt and choice_prompt:FindFirstChild('Choice')

    if not choice_prompt then return end
    if not choice_frame then return end
    if not self.is_loot_container(choice_prompt) then return end

    if not self.chest_check(options) then
        local count = 0

        for _, loot_object in options:GetChildren() do
            if not loot_object:IsA('TextButton') then continue end
            if not loot_object.AutoButtonColor then count += 1; continue end

            if not aztup.flags.auto_loot then break end

            if self:always_loot(remote, loot_object) then count += 1; continue end
            if self.is_overweight() then continue end

            if self:item_loot(remote, loot_object) then count += 1; continue end
            if self:stat_loot(remote, loot_object) then count += 1; continue end
            if self:loot_all(remote, loot_object) then count += 1; continue end
        end

        if not (count == 0) then return end
    else
        self.fire_loot_all(remote)
    end
end

local last_time = 0;
return Feature:new("auto_loot", services.RunService.RenderStepped, function() 
    if tick() - last_time < 1 / 10 then return end
    last_time = tick()
    pcall(function(...)  
        auto_loot:main()
    end)
end)
end)
__bundle_register("@src/features/auto-parry/animation_inspector", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Animation Inspector.
--
-- Окно со списком анимаций, которые указанный персонаж играет ПРЯМО СЕЙЧАС:
-- id ассета, имя с маркетплейса, Priority, Speed, WeightCurrent/Target,
-- Length, TimePosition. Обновление живых полей ~16 Гц.
--
-- Клик по строке кормит Timing Builder (builder:load_track) — тот самый
-- приём, ради которого окно и нужно: увидел анимацию в бою, кликнул,
-- получил id и windup в билдере, дальше Save.
--
-- Портировано из Luma-main/Features/Combat/AnimationInspector.lua. Оттуда
-- взята схема (Animator.AnimationPlayed + GetPlayingAnimationTracks как
-- сид, кап на MAX_ROWS, опрос живых полей). Fade-time через namecall-хук
-- из оригинала не переносил: это единственное, что там требует
-- перехвата __namecall, а пользы для подбора таймингов нет.
--
-- Окно на своём ScreenGui — тот же приём, что в builder.lua: на части
-- исполнителей gethui()/CoreGui скрыт, и окно просто не появляется.

local inspector = {};
inspector.on_close = nil;

local MAX_ROWS = 100;
local UPDATE_INTERVAL = 0.06

local gui, frame, list_frame, status, target_label;
local rows = {};           -- track -> { line }
local row_order = {};      -- track, в порядке появления
local running = false;
local anim_conn = nil;
local char_conn = nil;
local player_conn = nil;
local poll_started = false;
local y = 30;
local target_player = nil;

local function clear_conn(c)
    if c then pcall(function() c:Disconnect() end) end
    return nil
end

local function fmt(v)
    if type(v) ~= "number" then return tostring(v) end
    if v == math.floor(v) and math.abs(v) < 1e9 then return tostring(v) end
    return string.format("%.3f", v)
end

local function get(fn, dflt)
    local ok, v = pcall(fn);
    if not ok or v == nil then return dflt end
    return v;
end

local function anim_id_of(track)
    local anim = get(function() return track.Animation end);
    local raw = get(function() return anim.AnimationId end, "");
    return tostring(raw):match("(%d+)") or "", tostring(raw);
end

------------------------------------------------------------------ строки

local function remove_row(track)
    local row = rows[track];
    if not row then return end;
    rows[track] = nil;
    for i, t in ipairs(row_order) do
        if t == track then table.remove(row_order, i) break end;
    end;
    pcall(function() row.line:Destroy() end);
end

local function clear_rows()
    for track in pairs(rows) do
        pcall(function() rows[track].line:Destroy() end);
    end;
    table.clear(rows);
    table.clear(row_order);
end

local function refresh_row(row)
    local track = row.track;
    if get(function() return track.Parent end, nil) == nil and not get(function() return track.IsPlaying end, false) then
        remove_row(track);
        return;
    end;

    local id = row.id;
    local prio = get(function() return track.Priority.Name end, "?");
    row.line.Text = string.format(
        "%s  %s\n    prio=%s  spd=%s  wc=%s  wt=%s  len=%s  t=%s",
        id, row.name or "?",
        prio,
        fmt(get(function() return track.Speed end, 0)),
        fmt(get(function() return track.WeightCurrent end, 0)),
        fmt(get(function() return track.WeightTarget end, 0)),
        fmt(get(function() return track.Length end, 0)),
        fmt(get(function() return track.TimePosition end, 0))
    );
    row.line.TextColor3 = get(function() return track.IsPlaying end, false)
        and Color3.fromRGB(140, 220, 140)
        or Color3.fromRGB(130, 130, 140);
end

local function add_row(track)
    if rows[track] then refresh_row(rows[track]) return end;
    if not list_frame then return end;
    if #row_order >= MAX_ROWS then
        -- вытесняем самую старую строку, иначе флуд от AP-ломателя
        -- забил бы окно и заблокировал реальные анимации
        remove_row(row_order[1]);
    end;

    local id = anim_id_of(track);
    if id == "" then return end;

    -- имя берём у самого Animation-инстанса: Deepwoken именует их по муву,
    -- в отличие от MarketplaceService, который для анимаций молчит
    local anim_name = get(function() return track.Animation.Name end, nil);
    if anim_name == "" then anim_name = nil end;

    local line = Instance.new("TextButton");
    line.Name = id;
    line.Size = UDim2.new(1, -8, 0, 34);
    line.Position = UDim2.new(0, 4, 0, (#row_order) * 36);
    line.BackgroundTransparency = 1;
    line.BackgroundColor3 = Color3.fromRGB(50, 50, 62);
    line.AutoButtonColor = true;
    line.TextXAlignment = Enum.TextXAlignment.Left;
    line.TextYAlignment = Enum.TextYAlignment.Top;
    line.TextWrapped = true;
    line.TextSize = 11;
    line.Font = Enum.Font.Code;
    line.Text = id;
    line.Parent = list_frame;

    local row = { track = track, line = line, id = id, name = anim_name };

    -- клик по строке -> Timing Builder
    line.MouseButton1Click:Connect(function()
        local builder = getgenv().timing_builder;
        if not builder then
            if status then
                status.TextColor3 = Color3.fromRGB(240, 200, 120);
                status.Text = "timing builder not loaded";
            end;
            return;
        end;
        local entity = target_player and target_player.Character or local_player.character;
        pcall(function() builder:load_track(track, entity) end);
    end);

    rows[track] = row;
    table.insert(row_order, track);
    refresh_row(row);
end

------------------------------------------------------------------ привязка

local function bind_animator(animator)
    anim_conn = clear_conn(anim_conn);
    if not animator then return end;

    pcall(function()
        anim_conn = animator.AnimationPlayed:Connect(function(track)
            if running then add_row(track) end;
        end);
    end);

    -- сид: то, что уже играет
    local playing = get(function() return animator:GetPlayingAnimationTracks() end, nil);
    if type(playing) == "table" then
        for _, track in ipairs(playing) do add_row(track) end;
    end;
end

local function bind_character(character)
    clear_rows();
    if not character then
        if status then status.Text = "target has no character" end;
        return;
    end;

    local humanoid = character:FindFirstChildOfClass("Humanoid");
    local animator = humanoid and humanoid:FindFirstChildOfClass("Animator");
    if animator then
        bind_animator(animator);
        return;
    end;

    -- персонаж только что заспавнился, Animator может быть ещё нет
    task.spawn(function()
        local hum = character:WaitForChild("Humanoid", 5);
        local anim = hum and hum:WaitForChild("Animator", 5);
        if anim and running and target_player and target_player.Character == character then
            bind_animator(anim);
        end;
    end);
end

local function bind_player(player)
    target_player = player;
    char_conn = clear_conn(char_conn);
    if not player then
        clear_rows();
        return;
    end;

    if target_label then
        target_label.Text = "target: " .. tostring(player.DisplayName or player.Name);
    end;

    bind_character(player.Character);
    pcall(function()
        char_conn = player.CharacterAdded:Connect(function(c) bind_character(c) end);
    end);
end

------------------------------------------------------------------ интерфейс

local function poll()
    if not running then return end;
    for track, row in pairs(rows) do refresh_row(row) end;

    local list = get(function() return target_player.Character end, nil);
    if status then
        status.Text = string.format("%d track(s) | target: %s",
            #row_order, list and "in world" or "no character");
    end;
end

local function ensure_gui()
    if gui and gui.Parent then return end;

    gui = Instance.new("ScreenGui");
    gui.Name = "RainAnimInspectorGui";
    gui.ResetOnSpawn = false;
    gui.IgnoreGuiInset = true;
    gui.DisplayOrder = 999;
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling;
    pcall(function() gui.Parent = game:GetService("CoreGui") end);
    if not gui.Parent then
        local ok, pg = pcall(function()
            return game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui", 5)
        end);
        if ok and pg then pcall(function() gui.Parent = pg end) end;
    end;

    frame = Instance.new("Frame");
    frame.Name = "RainAnimInspector";
    frame.Size = UDim2.new(0, 380, 0, 440);
    frame.Position = UDim2.new(0.5, -190, 0.3, -120);
    frame.BackgroundColor3 = Color3.fromRGB(18, 18, 22);
    frame.BorderSizePixel = 0;
    frame.Visible = false;
    frame.Active = true;
    frame.Parent = gui;

    local title = Instance.new("TextLabel");
    title.Size = UDim2.new(1, 0, 0, 28);
    title.BackgroundColor3 = Color3.fromRGB(32, 32, 40);
    title.BorderSizePixel = 0;
    title.Text = "Animation Inspector   — click a row to send it to the Timing Builder";
    title.TextColor3 = Color3.fromRGB(235, 235, 235);
    title.Font = Enum.Font.GothamBold;
    title.TextSize = 11;
    title.TextXAlignment = Enum.TextXAlignment.Left;
    title.Parent = frame;

    do
        local dragging, start_pos, start_input = false, nil, nil;
        title.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                dragging = true; start_pos = frame.Position;
                start_input = input.Position;
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then dragging = false end;
                end);
            end;
        end);
        game:GetService("UserInputService").InputChanged:Connect(function(input)
            if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
                local d = input.Position - start_input;
                frame.Position = UDim2.new(start_pos.X.Scale, start_pos.X.Offset + d.X,
                    start_pos.Y.Scale, start_pos.Y.Offset + d.Y);
            end;
        end);
    end;

    local function button(text, xx, color, cb)
        local b = Instance.new("TextButton");
        b.Size = UDim2.new(0, 116, 0, 24);
        b.Position = UDim2.new(0, xx, 0, y);
        b.BackgroundColor3 = color;
        b.BorderSizePixel = 0;
        b.Text = text;
        b.TextColor3 = Color3.fromRGB(255, 255, 255);
        b.Font = Enum.Font.GothamBold;
        b.TextSize = 11;
        b.Parent = frame;
        b.MouseButton1Click:Connect(cb);
        return b;
    end

    target_label = Instance.new("TextLabel");
    target_label.Size = UDim2.new(1, -16, 0, 20);
    target_label.Position = UDim2.new(0, 8, 0, y);
    target_label.BackgroundTransparency = 1;
    target_label.Text = "target: -";
    target_label.TextColor3 = Color3.fromRGB(190, 190, 200);
    target_label.Font = Enum.Font.Gotham;
    target_label.TextSize = 11;
    target_label.TextXAlignment = Enum.TextXAlignment.Left;
    target_label.Parent = frame;
    y += 24;

    button("Self", 8, Color3.fromRGB(50, 70, 110), function()
        bind_player(game:GetService("Players").LocalPlayer);
    end);

    button("Nearest Enemy", 130, Color3.fromRGB(80, 60, 40), function()
        local best, best_d = nil, math.huge;
        local root = local_player and local_player.root_part;
        if not root then return end;
        for _, obj in workspace:GetDescendants() do
            if obj:IsA("Model") and obj ~= local_player.character then
                local h = obj:FindFirstChildOfClass("Humanoid");
                local r = obj:FindFirstChild("HumanoidRootPart");
                if h and r and h.Health > 0 then
                    local d = (r.Position - root.Position).Magnitude;
                    if d < best_d then
                        best_d = d;
                        best = obj;
                    end;
                end;
            end;
        end;
        if best and best:FindFirstChild("Humanoid") then
            local p = game:GetService("Players"):GetPlayerFromCharacter(best);
            if p then bind_player(p) else bind_character(best) end;
        end;
    end);

    button("Close", 252, Color3.fromRGB(110, 40, 40), function()
        inspector:set_visible(false);
        if inspector.on_close then pcall(inspector.on_close) end;
    end);

    y += 28;

    status = Instance.new("TextLabel");
    status.Size = UDim2.new(1, -16, 0, 18);
    status.Position = UDim2.new(0, 8, 0, y);
    status.BackgroundTransparency = 1;
    status.Text = "";
    status.TextColor3 = Color3.fromRGB(140, 220, 140);
    status.Font = Enum.Font.Gotham;
    status.TextSize = 11;
    status.TextXAlignment = Enum.TextXAlignment.Left;
    status.Parent = frame;
    y += 22;

    list_frame = Instance.new("ScrollingFrame");
    list_frame.Size = UDim2.new(1, -10, 1, -(y + 12));
    list_frame.Position = UDim2.new(0, 5, 0, y);
    list_frame.BackgroundColor3 = Color3.fromRGB(24, 24, 30);
    list_frame.BorderSizePixel = 0;
    list_frame.ScrollBarThickness = 5;
    list_frame.CanvasSize = UDim2.new(0, 0, 0, 0);
    list_frame.AutomaticCanvasSize = Enum.AutomaticSize.Y;
    list_frame.Parent = frame;
end

------------------------------------------------------------------ API

function inspector:set_visible(val)
    if not val then
        running = false;
        if frame then frame.Visible = false end;
        return;
    end;

    ensure_gui();
    if not gui or not frame then return end;

    running = true;
    gui.Enabled = true;
    gui.DisplayOrder = 999;
    frame.Visible = true;

    if not target_player then
        bind_player(game:GetService("Players").LocalPlayer);
    else
        bind_character(target_player.Character);
    end;

    if not poll_started then
        poll_started = true;
        -- общий цикл на всё окно: дёшево, дергается только при running
        task.spawn(function()
            local last = 0;
            while gui and gui.Parent do
                if tick() - last >= UPDATE_INTERVAL then
                    last = tick();
                    poll();
                end;
                task.wait();
            end;
            poll_started = false;
        end);
    end;
end;

function inspector:is_visible()
    return running == true;
end

function inspector:detach()
    running = false;
    clear_rows();
    anim_conn = clear_conn(anim_conn);
    char_conn = clear_conn(char_conn);
    player_conn = clear_conn(player_conn);
    if gui then pcall(function() gui:Destroy() end) end;
    gui, frame, list_frame = nil, nil, nil;
end;

getgenv().anim_inspector = inspector
return inspector
end)
__bundle_register("@src/features/auto-parry/auto-parry", function(require, _LOADED, __bundle_register, __bundle_modules)
local DefendActionManager = require("@src/features/auto-parry/defend-action-manager")
getgenv().DefendActionManager = DefendActionManager
getgenv().Latency = require("@src/utility/latency")

local function checkRange(obj, rangeCheck)
	if not (obj and obj.Position and local_player and local_player.root_part) then
		return false, math.huge
	end
	local distance = (obj.Position - local_player.root_part.Position).Magnitude
	return distance <= rangeCheck, distance
end

local function checkRangeFromPing(obj, rangeCheck, speed)
	if not (obj and obj.Position and local_player and local_player.root_part) then
		return false, math.huge, 0
	end
	local distance = (obj.Position - local_player.root_part.Position).Magnitude
	local ping = (Latency and Latency.get_ping and Latency:get_ping()) or 0
	distance -= (speed or 0) * (ping * 2)
	return distance <= rangeCheck, distance, (speed and speed ~= 0) and (ping / speed) or 0
end

local last_parry_at = tick()

local thrown = workspace:FindFirstChild("Thrown") or workspace:WaitForChild("Thrown", 10)
if thrown then
	aztup.maid:give_task(thrown.ChildAdded:Connect(LPH_NO_VIRTUALIZE(function(part)
		if not (aztup and aztup.flags and aztup.flags.auto_parry) then
			return
		end
		if not (part and part.Parent and local_player and local_player.root_part) then
			return
		end

		local live = workspace:FindFirstChild("Live")
		if not live then
			return
		end

		if part.Name == "ArdourBall2" then
			local nomad
			for _, child in live:GetChildren() do
				if child.Name:match("nomad") then
					nomad = child
					break
				end
			end

			if not nomad then
				return
			end
			local cond = false
			repeat
				task.wait()
				local pos_delta = (part.Position - local_player.root_part.Position)

				if
					math.abs(pos_delta.X) < 15
					and math.abs(pos_delta.Y) < 15
					and math.abs(pos_delta.Z) < 15
					and tick() - last_parry_at >= 0.1
				then
					cond = true
				elseif not part.Parent then
					cond = true
					return
				end
			until cond
			if not part.Parent then
				return
			end

			general:generic_parry_ap_task(nomad)
		elseif part.Name == "SlotBall" then
			repeat
				task.wait()
			until not part.Parent or (part.Position - local_player.root_part.Position).Magnitude < 20
			if not part.Parent then
				return
			end

			local current_angel
			for _, angel in live:GetChildren() do
				if angel.Name:match(".angel") then
					current_angel = angel
					break
				end
			end

			general:generic_parry_ap_task(current_angel)
		elseif part.Name == "BoneSpear" then
			local has_bonekeeper, bk
			for _, child in live:GetChildren() do
				if child.Name:match("boneboy") then
					has_bonekeeper = true
					bk = child
					break
				end
			end

			if has_bonekeeper then
				task.wait(2.15)
			end

			repeat
				task.wait()
			until not part.Parent
				or (part.Position - local_player.root_part.Position).Magnitude
					< (workspace:FindFirstChild("Layer2Floor1") and 30 or 75)
			if not part.Parent then
				return
			end

			if not workspace:FindFirstChild("Layer2Floor1") then
				local w = 0.2 - ((Latency and Latency.get_ping and Latency:get_ping()) or 0)
				if w > 0 then
					task.wait(w)
				end
			end

			general:generic_parry_ap_task(bk or workspace.Live:GetChildren()[2])
		elseif part.Name == "Flamewalker" and aztup.flags.no_rosen_fire then
			part.CanTouch = false

			local touch = part:WaitForChild("TouchInterest", 3.5)
			if touch then
				services.Debris:AddItem(touch, 0)
			end
		elseif part.Name == "Cyclone" then
			local backpack = local_player.instance:FindFirstChild("Backpack")
			if not backpack then
				return
			end
			if backpack:FindFirstChild("Mantra:EruptionBlood{{Scarlet Cyclone}}") then
				return
			end

			local user
			for _, player in services.Players:GetPlayers() do
				if
					player:FindFirstChild("Backpack")
					and player.Backpack:FindFirstChild("Mantra:EruptionBlood{{Scarlet Cyclone}}", true)
				then
					user = player.Character
					break
				end
			end

			if not user then
				return
			end

			repeat
				task.wait()
				local pos_delta = (part.Position - local_player.root_part.Position)

				if math.abs(pos_delta.X) < 12 and math.abs(pos_delta.Y) < 15 and math.abs(pos_delta.Z) < 12 then
					general:generic_parry_ap_task(user)
					break
				end
			until not part.Parent
		elseif part.Name:find("AraneaProjectile") or part.Name:find("SuperArrow") then
			local allowed_targets = aztup_options.allowed_targets.Value
			if not allowed_targets.PVP and not allowed_targets.All then
				return
			end

			local name = part.Name:split("_")[2]
			if not name then
				return
			end
			local user = services.Players:FindFirstChild(name)
			if not user then
				return
			end
			if user == local_player.instance then
				return
			end

			repeat
				task.wait()
				local pos_delta = (part.Position - local_player.root_part.Position)

				if math.abs(pos_delta.X) < 12 and math.abs(pos_delta.Y) < 15 and math.abs(pos_delta.Z) < 12 then
					general:generic_parry_ap_task(user.Character)
					break
				end
			until not part.Parent
		elseif part.Name:find("ShadeArrow") then
			local allowed_targets = aztup_options.allowed_targets.Value
			if not allowed_targets.PVP and not allowed_targets.All then
				return
			end

			local name = part.Name:split("_")[2]
			if not name then
				return
			end
			local user = services.Players:FindFirstChild(name)
			if not user then
				return
			end
			if user == local_player.instance then
				return
			end

			repeat
				task.wait()
				local pos_delta = (part.Position - local_player.root_part.Position)

				if math.abs(pos_delta.X) < 15 and math.abs(pos_delta.Y) < 16 and math.abs(pos_delta.Z) < 15 then
					general:generic_parry_ap_task(user.Character)
					break
				end
			until not part.Parent
		elseif part.Name == "Bullet" and not checkRange(part, 10) then
			local closest_player
			local closest_distance = math.huge
			for _, char in workspace:WaitForChild("Live"):GetChildren() do
				if char and char:FindFirstChild("HumanoidRootPart") then
					local distance = (part.Position - char.HumanoidRootPart.Position).Magnitude
					if distance < closest_distance then
						closest_distance = distance
						closest_player = char
					end
				end
			end

			if closest_distance > 120 then
				return
			end

			repeat
				task.wait()
			until (checkRangeFromPing(part, 20, 20)) or not part.Parent
			if not part.Parent then
				return
			end

			if closest_player and closest_player ~= local_player.character then
				general:generic_parry_ap_task(closest_player)
			end
		elseif part.Name == "SeekerOrb" then
			local closest_player
			local closest_distance = math.huge
			for _, char in workspace:WaitForChild("Live"):GetChildren() do
				if char and char:FindFirstChild("HumanoidRootPart") then
					local distance = (part.Position - char.HumanoidRootPart.Position).Magnitude
					if distance < closest_distance then
