return {
	id = "StrikeIndicator",
	name = "Lightning Strike",

	is = function(part)
		if part.Name ~= "StrikeIndicator" then
			return false
		end

		
		for _, player in game:GetService("Players"):GetPlayers() do
			if player == game:GetService("Players").LocalPlayer then
				continue
			end
			local character = player.Character
			if not character then
				continue
			end
			local animator = character:FindFirstChild("Animator", true)
			if not animator then
				continue
			end
			for _, track in animator:GetPlayingAnimationTracks() do
				local id = track.Animation.AnimationId:match("%d+")
				if id == "8857099063" then 
					return false
				end
			end
		end

		return true
	end,

	run = function(action, part)
		action.type = "Parry"
		action.when = 0.35
		action.name = "Lightning Strike"
		action.ignore_hitbox = false
        action.hitbox = Vector3.new(0, 0, 10)
		action.user = part
		action.allow_parry_to_roll = true
		action:play()

		return action
	end,
}

 end)();
return tbl
end)
__bundle_register("@src/features/auto-parry/data/truth_timings", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Тайминги из Luma-main/Timings/truth.txt, сконвертированы в формат Rain.
-- Источник: дамп таймингов игры — 712 анимационных записей.
-- Взят только пробел: id, которых НЕТ в assets/extra_data.json (455 шт.),
-- настройки Rain не перебиваются. Module-driven записи (umoa, 144 шт.) пропущены:
-- им нужен Modules/*.lua из Luma, это другая архитектура.
--
-- Формат записи идентичен base.lua: ids / action_type / run. Разница —
-- один общий build() на модуль вместо тела функции в каждой записи:
-- run всё равно получает creator, поэтому ipairs(def.actions) корректен.

local function build(def)
	return function(action)
		for _, a in ipairs(def.actions) do
			action.when = a[1];
			if a[2] ~= 0 or a[3] ~= 0 or a[4] ~= 0 then
				action.hitbox = Vector3.new(a[2], a[3], a[4]);
			end
			action.type = a[5];
			action.name = a[6];
			if a[7] then action.ignore_hitbox = true end
			action:push();
		end;
		return action;
	end
end

