    function AnimatorHandler:track_cleanup(track, fn)
        local state = self.running_tracks[track];
        if not state then return end
        table.insert(state.cleanups, fn);
    end

    function AnimatorHandler:track_feint_thread(track, thread)
        local state = self.running_tracks[track];
        if not state then return end
        table.insert(state.feint_threads, thread);
    end

    function AnimatorHandler:untrack_feint_thread(track, thread)
        local state = self.running_tracks[track];
        if not state then return end
        local index = table.find(state.feint_threads, thread);
        if index then
            table.remove(state.feint_threads, index);
        end
    end

    
    
    function AnimatorHandler:cancel_running_track(track)
        local state = self.running_tracks[track];
        if not state then return end
        self.running_tracks[track] = nil;

        for _, cleanup in state.cleanups do
            pcall(cleanup);
        end

        if state.thread and coroutine.status(state.thread) ~= "dead" then
            task.cancel(state.thread);
        end

        for _, thread in state.feint_threads do
            if coroutine.status(thread) ~= "dead" then
                task.cancel(thread);
            end
        end
    end

    
    
    
    
    function AnimatorHandler:cancel_feinted_tracks(playing_tracks)
        self.last_feint_at = tick();

        for _, track in playing_tracks do
            local state = self.running_tracks[track];
            if not state then continue end

            local action = state.action;
            if action and action.ignore_feints then continue end

            if state.action_type == "M1" and aztup.flags.ap_randomization and math.random() * 100 <= aztup.flags.bluff_feint_chance then
                debug_print("[Auto Feint] Bluffing through a detected feint.");
                continue            
end

            self:cancel_running_track(track);
        end
    end

    
    
    function AnimatorHandler:cancel_gale_feinted_tracks(playing_tracks)
        for _, track in playing_tracks do
            local state = self.running_tracks[track];
            if not state or not state.action or not state.action.detect_gale_feint then continue end

            self:cancel_running_track(track);
        end
    end

    function AnimatorHandler:in_hitbox_with_pos(root_pos: CFrame, enemy_pos: CFrame, hitbox: Vector3, offset: CFrame, hidden: boolean?)
        local ok, r = pcall(function()
            return general:in_hitbox_with_pos(root_pos, enemy_pos, hitbox, offset, hidden, self.ball)
        end)
        -- restore: the boot `general` stub answers every method with nil. A nil
        -- result here (not false) means the module never loaded — and every
        -- caller treats nil as "outside hitbox" and SILENTLY skips the action.
        -- Fall back to a generous distance check instead of dropping the parry.
        if ok and r ~= nil then return r end
        local a_ok, a_pos = pcall(function() return root_pos.Position end)
        local b_ok, b_pos = pcall(function() return enemy_pos.Position end)
        if not (a_ok and b_ok and a_pos and b_pos) then return false end
        local reach = 6
        if typeof(hitbox) == "Vector3" then
            reach = math.max(hitbox.X, hitbox.Y, hitbox.Z) * 0.75 + 6
        end
        return (a_pos - b_pos).Magnitude <= reach
    end


    local position_prediction_service = require("@src/features/auto-parry/services/position_prediction_service");
    function AnimatorHandler:in_hitbox(hitbox: Vector3, offset: CFrame, hidden: boolean?, predict, predict_time, predict_rotation, base_predict)  
        -- restore: same stub-nil guard as in_hitbox_with_pos (see above).
        -- Any error/nil from prediction or general => distance fallback.
        local function safe_original()
            local predicted_pos_us = position_prediction_service.our_predicted_position(); 
            local predicted_other_pos, dbg = position_prediction_service.predict(self.player, (Latency:get_ping() + (predict_time and typeof(predict_time) == "number" and predict_time or 0)) + 0.5, {
                predict_rotation = predict_rotation
            })

            local other_pos = predicted_other_pos or self.entity:FindFirstChild("HumanoidRootPart") and self.entity.HumanoidRootPart.CFrame or CFrame.new();

            if not predict then
                return general:in_hitbox_with_pos(local_player.root_part.CFrame, self.entity.HumanoidRootPart.CFrame, hitbox, offset, hidden, self.ball)
            end;

            local predicted = general:in_hitbox_with_pos(predicted_pos_us, other_pos, hitbox, offset, hidden, self.ball, Color3.fromRGB(205, 119, 255), Color3.fromRGB(255, 165, 130));
            local base = base_predict and general:in_hitbox_with_pos(local_player.root_part.CFrame, self.entity.HumanoidRootPart.CFrame, hitbox, offset, hidden, self.ball);

            return base or predicted 
        end
        local ok, r = pcall(safe_original)
        if ok and r ~= nil then return r end
        local lp_rp = local_player and local_player.root_part
        local e_rp = self.entity and self.entity:FindFirstChild("HumanoidRootPart")
        if not (lp_rp and e_rp) then return false end
        local reach = 6
        if typeof(hitbox) == "Vector3" then
            reach = math.max(hitbox.X, hitbox.Y, hitbox.Z) * 0.75 + 6
        end
        return (lp_rp.Position - e_rp.Position).Magnitude <= reach
    end;
    local tasks = 0;

    local action_builder = require("@src/features/auto-parry/data/action")

    
    
    
    
    

    
    
    
    
    







































































































local function create_block_input_task(self, track, action, data, action_type, name, time, alotted, ignore_anim_early_end, blocked_bi, start, in_hitbox)
        if not (data.allow_block_input and not aztup_options.blocked_safe_input_moves.Value["Animations"] and not blocked_bi) then
            return { remove = function() end }        
end

        return BlockInputManager:add_task(
            name,
            self.entity,
            function()
                if not action.ignore_early_end and not track_still_active(track, self.entity) and not ignore_anim_early_end then return end
                if EffectReplicator:FindEffect("Knocked") then return end;

                if not action.ignore_hitbox and not in_hitbox(true) then
                    return                
end;

                if
                    not data.dont_skip_mob_block_break
                    and self.entity:FindFirstChild("MegalodauntBroken", true)
                    and not services.Players:GetPlayerFromCharacter(self.entity)
                    and aztup_options.filters.Value["Dont Parry If Mob Block Broken"]
                then
                    return                
end

                if aztup_options.filters.Value["Dont Parry If Not Mob Target"] and self.entity.Name:sub(1, 1) == "." and self.entity:FindFirstChild("Target") then
                    if self.entity:FindFirstChild("Target").Value ~= local_player.character and not action.ignore_other_target then
                        return                    
end;
                end;

                if EffectReplicator:FindEffect("Knocked") and aztup_options.filters.Value["Dont Parry If Knocked"] then
                    return                
end;

                local type = aztup_options.bi_punishable_type.Value;

                if type == "Custom" then
                    return tick() - start >= (time - alotted) - (aztup.flags.bi_punishable_time / 1000)                
elseif type == "Dynamic" then
                    
                    return tick() - start >= (time - alotted) - (last_mid_attack_delay + (aztup.flags.extra_bi_punishable_time / 1000))                
end

                return true            
end
        )    
end

    
    
    
    
    local function check_action_preconditions_auto_feint(self, track, action, data, action_type, name, index, in_hitbox)
        if not action.ignore_hitbox and not in_hitbox(true) then
            return true        
end;

        if action.cancelled then
            return true        
end

        if
            not data.dont_skip_mob_block_break
            and self.entity:FindFirstChild("MegalodauntBroken", true)
            and not services.Players:GetPlayerFromCharacter(self.entity)
            and aztup_options.filters.Value["Dont Parry If Mob Block Broken"]
        then
            return true        
end

        if aztup_options.filters.Value["Dont Parry If Not Mob Target"] and self.entity.Name:sub(1, 1) == "." and self.entity:FindFirstChild("Target") then
            if self.entity:FindFirstChild("Target").Value ~= local_player.character and not action.ignore_other_target then
                return true            
end;
        end;

        if EffectReplicator:FindEffect("Knocked") and aztup_options.filters.Value["Dont Parry If Knocked"] then
            return true        
end;

        return false    
end

    
    
    
    
    local function check_action_preconditions(self, track, action, data, action_type, name, index, in_hitbox)
        if not action.ignore_hitbox and not in_hitbox(false) then
            return true        
end;

        if action.cancelled then
            debug_print("[%s] skipping action %s due to module-based cancellation", name, action_type);
            return true        
end

        if
            not data.dont_skip_mob_block_break
            and self.entity:FindFirstChild("MegalodauntBroken", true)
            and not services.Players:GetPlayerFromCharacter(self.entity)
            and aztup_options.filters.Value["Dont Parry If Mob Block Broken"]
        then
            debug_print("[%s] Entity is block broken, skipping action %s", name, action_type);
            return true        
end

        if aztup_options.filters.Value["Dont Parry If Not Mob Target"] and self.entity.Name:sub(1, 1) == "." and self.entity:FindFirstChild("Target") then
            if self.entity:FindFirstChild("Target").Value ~= local_player.character and not action.ignore_other_target then
                debug_print("[%s] Mob is targeting someone else, skipping action %s", name, action_type);
                return true            
end;
        end;

        if EffectReplicator:FindEffect("Knocked") and aztup_options.filters.Value["Dont Parry If Knocked"] then
            debug_print("[%s] Knocked, Skipping action %s", name, action_type);
            return true        
end;

        return false    
end

    
    
    
    
    
    local function check_action_situation_filters(self, track, action, action_type, name, index)
        if aztup_options.filters.Value["Dont Parry If Holding Block"] and Keybinds.IsActionHeld("Block") then
            setthreadidentity(8);
            debug_print("[%s] Skipping action, Holding F.", name);
            return "continue"        
end;

        if aztup_options.filters.Value["Dont Parry If In Payback"] and (EffectReplicator:FindEffect("PaybackHealTally") and tick() - last_payback_delay_time > 60 or EffectReplicator:FindEffect("DelayedPayback")) then
            debug_print("[%s] Skipping action, In Payback.", name);
            return "continue"        
end;

        if aztup_options.filters.Value["Dont Parry If Off Roblox"] and not aztup.automation:has_any() then
            if not isrbxactive() then
                debug_print("[%s] Skipping action %i, User is not tabbed in.", name, index);
                return "continue"            
end
        end

        if self.entity:GetAttribute("Owner") and self.entity:GetAttribute("Owner") == local_player.instance.Name then
            debug_print("[%s] Skipping timing due to us owning the entity.", name)
            return "break"        
end;

        if aztup_options.filters.Value["Dont Parry If Off Screen"] and not aztup.automation:has_any() then
            local _, vis = workspace.CurrentCamera:WorldToViewportPoint(self.entity.HumanoidRootPart.Position);
            if not vis then
                debug_print("[%s] Skipping action %i, Entity is off screen.", name, index);
                return "continue"            
end
        end

        if #self.hits > 0 and (
            action_type == "M1" or
            action_type == "Critical" and aztup_options.filters.Value["Dont Parry If Enemy Hit In Criticals"]
        ) then
            debug_print("[%s] Skipping action %i, Enemy hit in %s.", name, index, action_type);
            return "break"        
end

        if aztup_options.filters.Value["Dont Parry If Typing"] and not aztup.automation:has_any() then
            local l_ChatInputBarConfiguration_0 = services.TextChatService:FindFirstChild("ChatInputBarConfiguration");
            if services.UserInputService:GetFocusedTextBox() or l_ChatInputBarConfiguration_0 and l_ChatInputBarConfiguration_0.IsFocused then
                debug_print("[%s] Skipping action %i, Input box is focused.", name, index);
                return "continue"            
end
        end

        return nil    
end

    
    
    
    
    local function check_chime_and_gale(self, track, action, name, index)
        if aztup_options.filters.Value["Dont Parry In Chime Countdown"] and is_chime then
            local simple_prompt = local_player.instance:FindFirstChild("SimplePrompt", true);
            if simple_prompt then
                if simple_prompt:GetAttribute("CurPrompt") and simple_prompt:GetAttribute("CurPrompt") > 1 and simple_prompt:GetAttribute("CurPrompt") < 15 then
                    debug_print("[%s] In chime countdown for %i & %i, skipping action %i", name, simple_prompt:GetAttribute("CurPrompt"), workspace.DistributedGameTime, index);
                    return "continue"                
end
            end
        end

        return nil    
end

    local function fire_feint(hold_time)
        local character_handler = local_player.character:FindFirstChild("CharacterHandler");
        local feint_release = character_handler and character_handler:FindFirstChild("FeintRelease", true);
        local feint_click = KeyHandler:get_key("FeintClick");

        if not feint_release or not feint_click then
            return false        
end;

        feint_click:FireServer({
            A = false,
            Left = false,
            S = false,
            NOAERIALS = false,
            Space = false,
            Right = true,
            W = false,
            D = false
        })

        task.wait(hold_time or 0.05);

        feint_release:FireServer({
            A = false,
            Left = false,
            S = false,
            NOAERIALS = false,
            Space = false,
            Right = false,
            W = false,
            D = false
        })

        return true    
end

    local feint_cooldown_effects = {
        M1 = "FeintCool",
        Spell = "SpellFeintCooldown",
    };

    local function on_feint_cooldown(own_action_type)
        local effect_name = feint_cooldown_effects[own_action_type];
        return effect_name ~= nil and EffectReplicator:FindEffect(effect_name) ~= nil    
end

    local function feint_own_attack_before_parry()
        if not aztup.flags.auto_feint then
            return        
end;

        if not EffectReplicator:FindEffect("LightAttack") and not EffectReplicator:FindEffect("MidAttack") then
            return        
end;

        local own_action_type = self_anim_data.timing and self_anim_data.timing.action_type;
        if not own_action_type or not aztup_options.auto_feint_own_tags.Value[own_action_type] then
            return        
end;

        if on_feint_cooldown(own_action_type) then
            return        
end;

        debug_print("[Auto Feint] Mid-swing while trying to parry, feinting first.");
        fire_feint();
    end

    
    
    
    
    local function execute_resolved_action(self, type, action, data)
        if type == "Parry" then
            feint_own_attack_before_parry();

            if (action.allow_parry_to_roll or data.allow_parry_to_roll) and not aztup_options.filters.Value["Dont Roll"] then
                DefendActionManager:queue_generic_parry_task(self.entity);
            else
                DefendActionManager:queue_generic_parry_task_no_convert(self.entity);
            end;
        elseif type == "Dodge" then
            DefendActionManager:add_action(self.entity, "dodge", tick());
        elseif type == "Forced Full Dodge" then
            DefendActionManager:defend_action_dodge({
                mob = self.entity,
                type = "dodge",
                full = true,
                when = tick()
            });
        elseif type == "Jump" or type == "Legit Jump" and not self.is_player then
            local Safety = require("@src/utility/safety");
            if #services.Players:GetPlayers() == 1 and type ~= "Legit Jump" then
                local_player.character.CharacterHandler.Requests.Jump:FireServer()
                local_player.root_part.CFrame *= CFrame.new(0, 50, 0)
            else
                local jump_func = nil;
                local upvalues = getupvalues(base_require(game:GetService("ReplicatedStorage").Modules.CharacterControllers.Human));

                for _, upvalue in upvalues do
                    if typeof(upvalue) == "table" and rawget(upvalue, "Jump") then
                        jump_func = rawget(upvalue, "Jump");
                    end;
                end;

                if jump_func({
                    Humanoid = local_player.humanoid,
                    RootPart = local_player.root_part,
                    GroundSensor = local_player.root_part:FindFirstChild("GroundSensor")
                }) then
                    local_player.character.CharacterHandler.Requests.Jump:FireServer()

                    local jump_anim = local_player.humanoid:LoadAnimation(local_player.character.CharacterHandler.InputClient.Jump);
                    jump_anim:Play(0.05);

                    task.delay(0.4, function()
                        jump_anim:AdjustSpeed(0.5);
                        jump_anim:Stop(0.1);
                    end);
                end;
            end
        elseif type == "Start Block" then
            DefendActionManager:add_action(self.entity, "block", tick());
            self.blocked = true;
        elseif type == "Crouch" then
            task.spawn(function()
                local_player.character:WaitForChild("CharacterHandler"):WaitForChild("Requests"):WaitForChild("ServerCrouch"):FireServer(true)
                task.wait(1);
                local_player.character:WaitForChild("CharacterHandler"):WaitForChild("Requests"):WaitForChild("ServerCrouch"):FireServer(false);
            end)
        end;
    end

    
    
    
    
    local function lookup_timing_data(id)
        
        local custom, custom_name = custom_timings:lookup(id);
        if custom then
            return custom, custom_name        
end;

        local data, pot_name;
        local index = fast_timing_lookup_table[id];
        local timing = index and timing_data[index];
        if timing and id and typeof(id) == "string" and #id > 0 and timing.ids and table.find(timing.ids, id) then
            data = timing;

            if typeof(index) ~= "number" then
                pot_name = index;
            end;
        end
        return data, pot_name    
end


    
    local function process_actions(self, track, data, pot_name, to_evaluate_actions, action_type, blocked_bi, blocked_af)
        local current_rtt = Latency:get_ping()
        local alotted = 0
        local forced_roll_next

        local track_state = self.running_tracks[track];
        if track_state then
            track_state.action_type = action_type;
        end;

        local root = self.entity:FindFirstChild("HumanoidRootPart")
        if not root then
            return
        end

        local magnitude = (root.Position - local_player.root_part.Position).Magnitude;
        if self.is_player and magnitude > aztup.flags.dont_process_players_over_studs or not self.is_player and magnitude > aztup.flags.dont_process_mobs_over_studs then
            return        
end;

        if self.entity.Name:match("squidward") or self.entity.Name:match("nautilodaunt") and tick() - self.last_feint_at <= 0.5 then
            forced_roll_next = true;
        end;

        table.sort(to_evaluate_actions, function(a, b)
            local a_time = a.when and a.when or 0
            local b_time = b.when and b.when or 0
            return a_time < b_time
        end)

        for index, action in to_evaluate_actions do
            if track_state then
                track_state.action = action;
            end;

            local starting_speed = track.Speed;
            local hitbox = action.hitbox or Vector3.zero;
            local offset = action.offset or CFrame.new();
            local type = action.type or "Parry";
            local ignore_anim_early_end = action.ignore_animation_early_end or data.ignore_animation_early_end;
            local time = action.when or 0;
            local name = action.name or data.name or pot_name or "Unidentified " .. track.Animation.AnimationId;

            if data.ignore_hitbox_check or data.ignore_hitbox or action.ignore_hitbox_check then
                action.ignore_hitbox = true;
            end
            
            if action.half_size_offset then
                offset -= Vector3.new(0, 0, hitbox.Z / 2)
            end;
            
            if type == "End Block" and self.blocked then
                local wait_time = (time - alotted) - current_rtt
                task.wait(wait_time);
                DefendActionManager:add_action(self.entity, "unblock", tick());
                self.blocked = false;
                continue            
end;

            local function in_hitbox(hide)
                local inside;
                if not action.ignore_hitbox then         
                    if aztup.flags.mob_ai_breaker then
                        action.extrapolate = false;
                    end; 
                    
                    self.ball = action.shape == "ball";
                    
                    
                    
                    inside = self:in_hitbox(hitbox, offset or CFrame.new(), hide, action.predict, action.predict_time, action.predict_rotation, action.base_and_predict);
                    
                    self.ball = false;
                end

                return inside            
end;

            if typeof(hitbox) == "table" then
                hitbox = Vector3.new(
                    hitbox.X or 0,
                    hitbox.Y or 0,
                    hitbox.Z or 0
                );
            end;
    
            if typeof(offset) == "table" then
                offset = CFrame.new(
                    offset.X or 0,
                    offset.Y or 0,
                    offset.Z or 0
                );
            end;

            

            if action.delay_until_in_hitbox then
                repeat
                    task.wait();
                until in_hitbox(true) or not action.ignore_early_end and not track_still_active(track, self.entity) and not ignore_anim_early_end;
            end;

            local start = tick();
            local input_task = create_block_input_task(self, track, action, data, action_type, name, time, alotted, ignore_anim_early_end, blocked_bi, start, in_hitbox);
            self:track_cleanup(track, function()
                if not input_task.removed then
                    input_task:remove();
                end;
            end);

            if track.Speed > 50 then
                input_task:remove();
                break            
end;

            local chance_entry = chance_store:get_entry(data.name or pot_name or action.name);
            local continue_with_parry = true;

            local variation_weights = chance_entry and (chance_entry.outcome_weights or chance_entry.fail_weights or chance_entry.fail_actions);
            local variation_result = variation_weights and DefendActionManager:execute_failed_parry_variation(self.entity, variation_weights) or "Parry";
            continue_with_parry = variation_result == "Parry" or variation_result == "Dodge";

            if not continue_with_parry then
                debug_print("[%s] Action %i chance roll -> %s.", name, index, variation_result);
                input_task:remove();
                continue            
end;
            
            if math.random() >= (aztup.flags[self.flag .. "parry_chance"] / 100) then
                if not action.ignore_hitbox and in_hitbox(true) or action.ignore_hitbox then
                    debug_print("[%s] Skipping action %i due to global parry chance.", name, index);
                end;                

                input_task:remove();
                continue            
end;

            local wait_time = (time - alotted) - current_rtt

            local notifs = {};
            if wait_time > 0 and wait_time == wait_time and wait_time < 60000 then
                    task.delay(wait_time - (1 / 15), function()
                        if aztup.flags.auto_feint and not blocked_af then
                            if check_action_preconditions_auto_feint(self, track, action, data, action_type, name, index, in_hitbox) then
                                return                            
end;

                            if check_action_situation_filters(self, track, action, action_type, name, index) then
                                return                            
end;

                            if not action.ignore_early_end and not track_still_active(track, self.entity) and not ignore_anim_early_end then
                                return                            
end

                            if anti_ap_breaker:final_check(self, track) then
                                return                            
end

                            if not EffectReplicator:FindEffect("LightAttack") and not EffectReplicator:FindEffect("MidAttack") then
                                if not notifs.b then
                                    debug_print("[Auto Feint] Skipping because not in a attack.");
                                    notifs.b = true;
                                end;
                                return                            
elseif not notifs.a then
                                notifs.a = true;
                                debug_print("[Auto Feint] Attempting to feint.");
                            end;

                            local own_action_type = self_anim_data.timing and self_anim_data.timing.action_type;
                            if not own_action_type or not aztup_options.auto_feint_own_tags.Value[own_action_type] then
                                return debug_print("[Auto Feint] Skipping, our move type '%s' isn't selected.", tostring(own_action_type))                            
end;

                            if on_feint_cooldown(own_action_type) then
                                return debug_print("[Auto Feint] Skipping, '%s' feint is on cooldown.", own_action_type)                            
end;

                            fire_feint();
                        end;
                    end);

                task.wait(wait_time)
                alotted += wait_time
            elseif wait_time ~= wait_time or wait_time > 0 then
                return debug_print("[%s] Skipping action %i, wait time invalid: %.2f", name, index, wait_time)            
end;

            if not input_task.removed then
                input_task:remove();
            end;

            if anti_ap_breaker:final_check(self, track) then
                tasks = math.max(0, tasks - 1);
                return            
end

            
            
            
            
            

            if not action.ignore_early_end and not track_still_active(track, self.entity) and not ignore_anim_early_end then
                debug_print("[%s] Skipping action %i, animation ended early.", name, index);
                continue            
end

            if type == "RPUE Parry" then
                local blocked = false;
                while action.condition() do
                    if action.should() then
                        blocked = true;
                        DefendActionManager.block:FireServer();
                        task.delay(0, function()
                            DefendActionManager.unblock:FireServer();
                        end)
                    end;
                    action.wait();
                end;

                if blocked then
                    task.wait();
                    DefendActionManager.unblock:FireServer();
                end;
                continue            
end;

            if check_action_preconditions(self, track, action, data, action_type, name, index, in_hitbox) then
                continue            
end;

            if aztup.flags[self.flag .. "roll_if_unequipped"] and not EffectReplicator:FindEffect("Equipped") and type == "Parry" then
                type = "Dodge";
            end;

            if forced_roll_next and type == "Parry" then
                type = "Dodge";
                forced_roll_next = false;
            end;

            if aztup.flags[self.flag .. "auto_equip"] and not EffectReplicator:FindEffect("Equipped") then
                local character_handler = local_player.character:FindFirstChild("CharacterHandler");
                local requests = character_handler and character_handler:FindFirstChild("Requests");
                local equip_weapon = requests and requests:FindFirstChild("DrawWeapon");

                if equip_weapon then
                    task.delay(0.1 + (math.random() / 1000), function()
                        equip_weapon:FireServer(true);
                    end);
                else
                    debug_print("failed to find 'DrawWeapon'");
                end;
            end;

            local situation_skip = check_action_situation_filters(self, track, action, action_type, name, index)
            if situation_skip == "continue" then
                continue            
elseif situation_skip == "break" then
                break            
end;

            local chime_gale_skip = check_chime_and_gale(self, track, action, name, index)
            if chime_gale_skip == "continue" then
                continue            
elseif chime_gale_skip == "return" then
                return            
end;

            if aztup.flags.log_speed_changes then
                if starting_speed == track.Speed then
                    debug_print("[%s] Performing action %i: %s (%.2fs srtt -> %.2fs, %.2f speed)", name, index, type, current_rtt, Latency:get_ping(), starting_speed); 
                else
                    debug_print("[%s] Performing action %i: %s (%.2fs srtt -> %.2fs, %.2f -> %.2f speed)", name, index, type, current_rtt, Latency:get_ping(), starting_speed, track.Speed);
                end
            else
                debug_print("[%s] Performing action %i: %s (%.2fs srtt -> %.2fs)", name, index, type, current_rtt, Latency:get_ping()); 
            end;

            if variation_result ~= "Parry" then
                debug_print("[%s] Action %i chance roll -> %s.", name, index, variation_result);
            end

            if variation_result == "Dodge" then
                type = "Dodge";
                debug_print("[%s] switched action %i to dodge.", name, index);
            end

            if type == "Parry" and (not action.ignore_auto_parry_frames and in_parry_frames) and aztup_options.filters.Value["Dont Parry In AP Frames"] then
                debug_print("[%s] In parry frames. Skipping action %i", name, index);
                continue            
end;

            
            
            
            

            if aztup.flags.ap_randomization and type == "Parry" then
                local chance = aztup.flags["parry_to_dodge_chance_" .. (data.action_type or "undefined"):lower()] or 0
                local can = not aztup.flags.only_convert_dodge_if_possible or aztup.flags.only_convert_dodge_if_possible and local_player.tracker:can_dodge()

                if random:NextNumber() <= chance / 100 and can then
                    type = "Dodge";
                    debug_print("[%s] Randomized action %i to dodge.", name, index);
                end;
            end;

            if action.prefer_dodge and local_player.tracker:can_dodge() then
                type = "Dodge";
                debug_print("[%s] Action %i prefers dodge.", name, index);
            end;

            if (action.allow_parry_to_roll or data.allow_parry_to_roll) and not local_player.tracker:can_parry() then
                if local_player.tracker:can_dodge() then
                    type = "Dodge";
                    debug_print("[%s] Parry on CD, rolling instead.", name);
                end;
            end

            if aztup_options.filters.Value["Dont Roll"] and (type == "Dodge" or type == "Forced Full Dodge") then
                debug_print("[%s] Skipping action %i, Roll is disabled.", name, index);
                continue            
end;

            if aztup_options.filters.Value["Dont Parry If Not In Combat"] and not EffectReplicator:FindEffect("Danger") then
                debug_print("[%s] Skipping action %i, Not in danger.");
                continue            
end;
            
            execute_resolved_action(self, type, action, data);

            if action.no_more_actions then break end
        end
    end
    
    
    
    
    local function log_info_if_enabled(self, track)
        -- restore: fully self-sufficient. Bare `Library`/`lexend` may be stale
        -- snapshots in this chunk's env (same class of bug as EffectReplicator),
        -- and any error here used to kill logging silently inside task.spawn.
        local gg = (typeof(getgenv) == "function" and getgenv()) or _G
        local Lib = (gg and gg.Library) or Library
        if not (aztup.flags.info_logger and self.entity:FindFirstChild("HumanoidRootPart") and self.entity.Name ~= local_player.character.Name) then
            return
        end
        local lp_rp = local_player and local_player.root_part
        if not lp_rp then return end

        local dist = (lp_rp.Position - self.entity.HumanoidRootPart.Position).Magnitude;
        if dist > (aztup.flags.info_logger_range or 100) then
            return
        end

        task.spawn(function()
            local ok_ai, anim_id = pcall(function() return track.Animation.AnimationId end)
            if not ok_ai or not anim_id then return end
            local ok_n, name = pcall(function() return getInfo(tostring(anim_id):match("%d+")).Name end)
            name = (ok_n and name) or ""
            if name:lower():match("parried") then return end
            if name:lower():match("idle") then return end

            local disallowed = false;
            local ok_a, assets = pcall(function() return game:GetService("ReplicatedStorage"):FindFirstChild("Assets") end)
            local mov = ok_a and assets and assets:FindFirstChild("Anims") and assets.Anims:FindFirstChild("Movement")
            if mov then
                for _, anim in mov:GetDescendants() do
                    if anim:IsA("Animation") and anim.AnimationId == anim_id then
                        disallowed = true;
                        break
                    end;
                end
            end

            if disallowed then return end
            if not Lib or not Lib.AddTextToInfoLogger then return end

            local ok_l, err_l = pcall(function()
                Lib:AddTextToInfoLogger(string.format("%s %s %s", name, tostring(tostring(anim_id):match("%d+")), self.entity.Name), tostring(tostring(anim_id):match("%d+")), function()
                    if getgenv().timing_builder then getgenv().timing_builder:load_track(track, self.entity); end;
                end, 60);
            end)
            if not ok_l then
                gg.__rain_loginfo_err = tostring(err_l):sub(1, 120)
            end
        end);
    end

    local asset_id = require("@src/utility/asset_id");
    function AnimatorHandler:run(track: AnimationTrack)
        local ap = aztup.flags.auto_parry
        local breaker = aztup.flags.ap_breaker
        local asc = aztup.features.anim_speed_changer

        if not ap and not breaker and not asc then return end
        if not track or not track.Animation then return end
        if not EffectReplicator then return end
        if not local_player.character then return end

        if self.entity.Name ~= local_player.character.Name and not ap then return end

        local id, err = asset_id.get_id(track.Animation.AnimationId);
        if (self.is_player and mobsAnims[id]) or err or not id then
            return        
end;

        local data, pot_name = lookup_timing_data(id);

        -- restore: animation coverage log (RAIN_ANIMDUMP). Records every enemy
        -- swing: which anim id, from whom, and whether timing data exists.
        do
            local gg = (typeof(getgenv) == "function" and getgenv()) or _G
            gg.RAIN_ANIMS = gg.RAIN_ANIMS or {}
            local key = tostring(id)
            local e = gg.RAIN_ANIMS[key]
            if not e then
                e = { n = 0, has_data = false, who = {}, nm = nil }
                gg.RAIN_ANIMS[key] = e
                -- resolve marketplace name once (tells M1s apart from idles/blocks)
                task.spawn(function()
                    local ok, info = pcall(function()
                        return game:GetService("MarketplaceService"):GetProductInfo(tonumber(tostring(id):match("%d+")) or 0)
                    end)
                    if ok and info and info.Name then e.nm = tostring(info.Name):sub(1, 50) end
                end)
            end
            e.n += 1
            if data then e.has_data = true end
            local en = tostring(self.entity and self.entity.Name or "?")
            if e.who[en] == nil then
                local c = 0 for _ in pairs(e.who) do c += 1 end
                if c < 6 then e.who[en] = true end
            end
        end

        log_info_if_enabled(self, track);

        if not data or tasks >= (aztup.flags.task_concurrency or 25) then
            -- restore: reactive fallback for UNKNOWN enemy animations. Verified by
            -- extracting the bundle's baked timing DB (XOR-42, 698 entries): it
            -- knows only the same 2 of your 34 top anims as the OSS data does.
            -- Current M1 ids exist in NEITHER db, so no id-port can fix this.
            -- Non-looped enemy track in range + can_parry => quick block.
            -- Disable: aztup.flags.parry_unknown_anims = false (console).
            -- Telemetry: every decision lands in RAIN_ANIMS[id].why (see ANIMDUMP).
            if not data and track then
                local gg = (typeof(getgenv) == "function" and getgenv()) or _G
                local why = "queued"
                local function note(r) why = r end
                local fire = true
                -- restore: only Action-priority tracks. Idle/Movement/Core are
                -- locomotion/emotes (incl. mob aggro idles) — never attacks.
                -- This stops blocks "without reason" when a mob just aggros.
                if fire then
                    local ok_p, prio = pcall(function() return track.Priority end)
                    if not ok_p or not prio or prio.Value < Enum.AnimationPriority.Action.Value then
                        fire = false note("not_action_prio")
                    end
                end
                -- restore: skip locomotion ids (walk/run/idle/jump from the game
                -- Movement folder) even if they arrive with Action priority.
                if fire then
                    local num = tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
                    if num and movementAnims[num] then fire = false note("movement_anim") end
                end
                -- restore: mobs expose a Target ObjectValue — react only when it
                -- targets us (or is absent). No more blocks at someone else's fight.
                if fire and self.entity and self.entity.Name:sub(1, 1) == "." then
                    local tgt = self.entity:FindFirstChild("Target")
                    if tgt and tgt.Value and local_player.character
                        and tgt.Value ~= local_player.character then
                        fire = false note("not_targeting_us")
                    end
                end
                if fire and not aztup.flags.auto_parry then fire = false note("flag_off") end
                -- restore: OPT-IN reactive fallback for UNKNOWN enemy animations.
                -- Default OFF (bundle-like: only curated ids parry). The mirror-
                -- blocking of emotes/block-poses ("parrying air") came from this
                -- firing on everything. Enable: parry_unknown_anims = true.
                -- Verified by full extraction: bundle DB (698) + OSS data lack
                -- current anims either way, so no id-port can fix those.
                if fire and aztup.flags.parry_unknown_anims ~= true then fire = false note("fallback_off") end
                if fire and (not self.entity or not local_player.character) then fire = false note("no_char") end
                if fire and self.entity.Name == local_player.character.Name then fire = false note("self") end
                -- restore: parry unavailable (CD/unequipped) => dodge instead of
                -- doing nothing ("dodge if parry on CD" for unknown anims, no
                -- Humanization needed). can_dodge() still required.
                local parry_unavail = false
                if fire then
                    if not local_player.tracker then fire = false note("no_tracker") end
                end
                if fire then
                    local ok_cp, cp = pcall(function() return local_player.tracker:can_parry() end)
                    if not ok_cp or not cp then parry_unavail = true end
                end
                if fire and not TargetFilter.is_allowed(self.entity, aztup_options.allowed_targets.Value) then fire = false note("target_filter") end
                local eroot, lroot, dist, lim
                if fire then
                    if aztup_options.filters.Value["Dont Parry If Guildmate"] then
                        local plr = services.Players:GetPlayerFromCharacter(self.entity)
                        if plr and general:is_teammate(plr) then fire = false note("guildmate") end
                    end
                end
                if fire then
                    eroot = self.entity:FindFirstChild("HumanoidRootPart")
                    lroot = eroot and local_player.root_part
                    if not (eroot and lroot) then fire = false note("no_hrp") end
                end
                if fire then
                    dist = (eroot.Position - lroot.Position).Magnitude
                    lim = self.is_player
                        and (aztup.flags.dont_process_players_over_studs or 60)
                        or (aztup.flags.dont_process_mobs_over_studs or 60)
                    -- restore: fallback is reactive (no windup data), so keep it
                    -- close-range only — distant crowds must not hold your block.
                    if lim > 30 then lim = 30 end
                    if dist > lim then fire = false note(string.format("dist=%.0f>%.0f", dist, lim)) end
                end
                if fire then
                    local er = getgenv().EffectReplicator or EffectReplicator
                    if aztup_options.filters.Value["Dont Parry If Not In Combat"] and not er:FindEffect("Danger") then
                        fire = false note("no_danger")
                    end
                end
                -- restore: post-parry punish window. Right after our successful
                -- parry the enemy plays stagger anims (unknown ids, Action, close,
                -- targeting us) — re-blocking them locks us through the punish
                -- window and we eat the riposte. Skip 0.7s past ParryCool fade.
                if fire then
                    local er0 = getgenv().EffectReplicator or EffectReplicator
                    local ok_pc, pc = pcall(function() return er0:FindEffect("ParryCool") end)
                    if ok_pc and pc then getgenv().__rain_lastpc = tick() end
                    if getgenv().__rain_lastpc and tick() - getgenv().__rain_lastpc < 0.7 then
                        fire = false note("post_parry_window")
                    end
                end
                -- restore: echo suppressions (kill the 2nd press, replication-proof
                -- — none of this waits for ParryCool to replicate).
                -- (a) same (entity, anim) within 1.0s = replay/echo, not a new swing.
                if fire then
                    getgenv().__rain_lastecho = getgenv().__rain_lastecho or {}
                    local ok_dbg, dbg = pcall(function() return self.entity:GetDebugId() end)
                    local ekey = (ok_dbg and tostring(dbg) or tostring(self.entity and self.entity.Name)) .. "|" .. tostring(id)
                    local last_e = getgenv().__rain_lastecho[ekey]
                    if last_e and tick() - last_e < 1.0 then
                        fire = false note("echo")
                    else
                        getgenv().__rain_lastecho[ekey] = tick()
                    end
                end
                -- (b) we queued ANY block <0.45s ago = stagger/mirror noise right
                -- after our press. Real chain continuations arrive later.
                if fire then
                    local lbq = getgenv().__rain_lastblockq
                    if lbq and tick() - lbq < 0.45 then
                        fire = false note("own_block_echo")
                    end
                end
                if fire then
                    -- restore: dodge variation for unknown anims (fixes "only
                    -- parries, never dodges" — the fallback previously knew only
                    -- block). Uses the M1 force-dodge chance + Humanization flag.
                    local queued_how = "block"
                    local want_dodge = parry_unavail
                    if not want_dodge and aztup.flags.ap_randomization then
                        local chance = aztup.flags.parry_to_dodge_chance_m1 or 0
                        if math.random() * 100 < chance then want_dodge = true end
                    end
                    if want_dodge then
                        local can = (not aztup.flags.only_convert_dodge_if_possible)
                            or (local_player.tracker and local_player.tracker:can_dodge())
                        if can then
                            -- restore: roll slightly delayed (0.25s) — a dodge
                            -- queued at windup start wastes i-frames before impact.
                            DefendActionManager:queue_generic_dodge_task(self.entity, 0.25)
                            queued_how = "dodge"
                            why = parry_unavail and "queued_dodge_cd" or "queued_dodge"
                        end
                    end
                    if queued_how == "block" then
                        if parry_unavail then
                            fire = false note("can_parry=false")
                        else
                            DefendActionManager:queue_generic_parry_task(self.entity, 0.75)
                        end
                    end
                    getgenv().__rain_nr = getgenv().__rain_nr or 0
                    if tick() - getgenv().__rain_nr > 3 then
                        getgenv().__rain_nr = tick()
                        pcall(function()
                            setthreadidentity(8)
                            Logger:short_notify(string.format("[AP] react-%s %s %.0f", queued_how, tostring(self.entity and self.entity.Name):sub(1, 14), dist or -1))
                        end)
                    end
                end
                gg.RAIN_FB = gg.RAIN_FB or {}
                gg.RAIN_FB[why] = (gg.RAIN_FB[why] or 0) + 1
                local e2 = gg.RAIN_ANIMS and gg.RAIN_ANIMS[tostring(id)]
                if e2 then e2.why = why end
            end
            return        
end;

        task.wait(1 / 60); 
        if anti_ap_breaker:initial_check(self, track) then 
            tasks = math.max(0, tasks - 1);
            return 
        end
        
        if is_chime then
            local alive = track.IsPlaying or not anti_ap_breaker:is_fully_dead(track, self.entity);
            if track.WeightTarget <= 0.050 and (track.WeightCurrent < 0.050 or not alive) then
                return            
end;
        end;

        if data.enc then
            
            

data = table.clone(data);
            data = process(data);

        end

        local str = pot_name or data.name or data.actions and data.actions[1] and data.actions[1].name;
        if str and aztup_options.blocked_timings.Value[str] then return end
    
        if self.entity.Name == local_player.character.Name then


            local action_type = data.action_type or "Undefined";
            if action_type == "M1" and aztup.features.ap_breaker then
                aztup.features.ap_breaker.last_m1_anim = track.Animation.AnimationId;
            end;
    
            if aztup.features.tester_ap_breaker and aztup.features.tester_ap_breaker.handle and aztup.flags.tester_ap_breaker then
                aztup.features.tester_ap_breaker:handle(track, data);
            end

            if aztup.features.anim_speed_changer then
                aztup.features.anim_speed_changer:handle(track, data);
            end
                
            if aztup_options.aggressive_3_break_on.Value[({
                ["Critical"] = "Criticals",
                ["Untagged"] = "Untagged",
                ["Spell"] = "Spells",
                ["Bell"] = "Bells",
                ["M1"] = "M1s"
            })[action_type] ] then
                break_anims(track, data, action_type, self); 
            end

            self_anim_data = { 
                timing = data,
                track = track,
                when = tick()
            };
            return        
end;
    
        if not TargetFilter.is_allowed(self.entity, aztup_options.allowed_targets.Value) then
            return
        end
    
        if aztup_options.filters.Value["Dont Parry If Guildmate"] then
            local player = services.Players:GetPlayerFromCharacter(self.entity);
            if player and general:is_teammate(player) then
                return            
end
        end

        self.running_tracks[track] = { thread = coroutine.running(), feint_threads = {}, cleanups = {} };

        local actions = action_builder.new({ signal = true })
        local to_evaluate_actions

        tasks += 1;
        task.delay(1, function()
            tasks -= 1;
        end);
        if data.run then
            
            
            
    
            local base_env = getfenv(data.run)
            local signal_actions = {} 
    
            actions:get_signal():connect(function(aid)
                local a = actions.actions[aid]
                if not a then 
                    return 
                end
    
                
                table.insert(signal_actions, a)
    
                
                local single = { a }
    
                local action_type = data.action_type or "Undefined"
                local blocked_bi = aztup_options.blocked_safe_input_moves.Value[action_type]
                local blocked_af = aztup_options.blocked_auto_feint_moves.Value[action_type]
    
                process_actions(self, track, data, pot_name, single, action_type, blocked_bi, blocked_af)
            end)
    
            local fake_env = setmetatable({
                track = track,
                defender = self,
                self = {
                    distance = function()
                        return (local_player.root_part.Position - self.entity.HumanoidRootPart.Position).Magnitude
                    end,
                    is_playing = function()
                        return track_still_active(track, self.entity)
                    end,
                },
                weapon = require("@src/features/auto-parry/data/weapon").data(self.entity) or {},
                mantra = require("@src/features/auto-parry/data/mantra"),
                thrown = workspace:FindFirstChild("Thrown"),
            }, {
                __index = base_env,
            })
            -- restore: setfenv проверяется в первую очередь. Подмена глобалов
            -- принципиально не переживает yield: data.run ждёт внутри себя
            -- (task.wait), и перекрывающий запуск успевает восстановить self
            -- в nil — отсюда "attempt to index nil with 'is_playing'".
            -- Там, где setfenv есть, механизм корректен и гонок нет в принципе.
            -- Фолбэк оставлен для исполнителей без setfenv, но с диагностикой.
            --
            -- NOTE: the holder thread can be killed mid-run (track cancel on
            -- feint/end). Waiters steal the lock instantly when the holder is
            -- dead instead of sitting out a blind deadline (that was the ~1s
            -- post-feint freeze); the short deadline only covers live holders.
            do
                local __me = coroutine.running()
                local __deadline = tick() + 0.25
                while getgenv().__rain_runlock do
                    local __holder = getgenv().__rain_runholder
                    if __holder ~= nil and __holder ~= __me then
                        local __ok_s, __st = pcall(coroutine.status, __holder)
                        if __ok_s and __st == "dead" then break end
                    end
                    if tick() >= __deadline then break end
                    task.wait()
                end
                getgenv().__rain_runlock = true
                getgenv().__rain_runholder = __me
                local __ok, __err

                if __rain_has_setfenv then
                    local __prev = getfenv(data.run)
                    setfenv(data.run, fake_env)
                    __ok, __err = pcall(data.run, actions, self)
                    setfenv(data.run, __prev)
                else
                    local __saved = {}
                    for __k in pairs(fake_env) do
                        __saved[__k] = getgenv()[__k]
                        getgenv()[__k] = fake_env[__k]
                    end
                    if getgenv().thrown == nil then
                        getgenv().thrown = workspace:FindFirstChild("Thrown")
                            or { ChildAdded = { Connect = function() return { Disconnect = function() end } end } }
                    end
                    __ok, __err = pcall(data.run, actions, self)
                    for __k in pairs(fake_env) do getgenv()[__k] = __saved[__k] end
                end

                getgenv().__rain_runlock = nil
                getgenv().__rain_runholder = nil
                if not __ok then
                    -- один лог на класс ошибок, чтобы консоль не засорялась
                    local __kind = tostring(__err):sub(1, 60)
                    if getgenv().__rain_runerr ~= __kind then
                        getgenv().__rain_runerr = __kind
                        -- restore: консольный вывод убран, но warn() пишет в
                        -- коллектор RAIN_ERRORS. Смотри getgenv().RAIN_ERRDUMP().
                        -- Ответ на вопрос "есть ли setfenv в Potassium" лежит здесь.
                        warn("[restore] parry run: " .. tostring(__err))
                        warn("[restore] setfenv=" .. tostring(__rain_has_setfenv)
                            .. " — без него подмена глобалов не переживает yield,"
                            .. " run-тайминги (129) теряют self")
                    end
                end
            end
    
            
            
            
            to_evaluate_actions = actions:get()
            if #to_evaluate_actions > 0 then
                local action_type = data.action_type or "Undefined"
                local blocked_bi = aztup_options.blocked_safe_input_moves.Value[action_type]
                local blocked_af = aztup_options.blocked_auto_feint_moves.Value[action_type]
    
                process_actions(self, track, data, pot_name, to_evaluate_actions, action_type, blocked_bi, blocked_af)
            end

            self.running_tracks[track] = nil;
            return
        else
            for _, action in data.actions do
                actions.pending_action = action
                actions:push()
            end
            to_evaluate_actions = data.actions or actions:get()
        end
    
        local action_type = data.action_type or "Undefined"
        local blocked_bi = aztup_options.blocked_safe_input_moves.Value[action_type]
        local blocked_af = aztup_options.blocked_auto_feint_moves.Value[action_type]
    
        process_actions(self, track, data, pot_name, to_evaluate_actions, action_type, blocked_bi, blocked_af)

        self.running_tracks[track] = nil;
    end;

    local last_mid_attack = tick();
    EffectReplicatorHandler:hook("added", function(effect)
        if effect.Class == "MidAttack" then
            last_mid_attack = tick();
        elseif effect.Class == "DelayedPayback" then
            last_payback_delay_time = tick();
        end;

        return nil    
end);

    EffectReplicatorHandler:hook("removed", function(effect)
        if effect.Class == "MidAttack" then
            last_mid_attack_delay = (tick() - last_mid_attack) - Latency:half_ping()
        end 

        return nil    
end);

    InstanceWatcher.new(workspace:WaitForChild("Live"), function(entity)
        local start = tick();
    
        repeat task.wait() until entity:FindFirstChild("Animator", true) or tick() - start > 5;
        return entity:FindFirstChild("Animator", true)    
end, function(entity)   
        if not entity:IsA("Model") then return end
        AnimatorHandler.new(entity);
    end);
end)()
end)
__bundle_register("@src/features/auto-parry/handlers/anti-ap-breaker", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Anti AP Breaker — evidence-first (server-authoritative) валидация.
--
-- ПОЧЕМУ ТАК
-- Прежняя версия была чисто реактивной: смотрела на свойства AnimationTrack
-- (Speed, Length, Priority, WeightTarget, fadetime, priority hiding). Все эти
-- свойства локальные и подделываются тривиально — достаточно выставить
-- Speed=1, Priority=Core, WeightTarget=1, и трек неотличим от «чистого».
--
-- Новый подход: мы НЕ спрашиваем у трека «похож ли он на настоящий», мы
-- спрашиваем у сервера «ждали ли мы атаку вообще». Источники истины:
--   1) Requests.ClientEffect (RemoteEvent, сервер -> клиент):
--        WeaponTrail      — оружие пошло в замах (m1 / critical / special)
--        CriticalSwirl    — точно крит
--        WeaponTrailOff   — замах отменён
--   2) атрибут персонажа StoredAction == "criticalattack" (реплицируется)
--   3) появление дочернего "Ether" — серверный спавн расхода (мантра/крит)
--
-- Ключевое свойство: легитимная атака ВСЕГДА приходит с серверным evidence.
-- У трека, пришедшего без предсказания, легитимного происхождения быть не
-- может — значит это инъекция. Breaker не может ни подавить серверный
-- RemoteEvent (тогда игра развалится у всех на клиенте), ни подделать его.
-- Единственный способ «не спалиться» — не показывать анимацию вовсе, но
-- тогда и париться нечему. Обход возможен только ценой отказа от атаки.
--
-- Старые эвристики сохранены вторым слоем (cheap-мусор они ловят быстрее),
-- всё по-прежнему гейтится флагами из меню — поведение настраиваемое то же.

local anti_ap_breaker = {}

------------------------------------------------------------------ константы
-- окна задержки (мс) между серверным evidence и появлением анимации.
-- Растягиваются на пинг: медленный пин -> широкие окна, иначе легитимные
-- атаки на быстром пинге начнут отсекаться как инъекции.
local BASE_LATENCY_MIN, BASE_LATENCY_MAX = 0, 340
local CRIT_LATENCY_MIN, CRIT_LATENCY_MAX = 0, 420
local PING_STRETCH = 1.35 -- множитель окна на пинг
local PING_CAP = 260      -- потолок растяжки, мс
local EVIDENCE_TTL_MS = 2600  -- сколько живёт неиспользованное evidence
local RESYNC_GRACE_MS = 450    -- после спавна не судим первые треки
local VERDICT_SETTLE_MS = 250  -- сколько живёт неопознанный вердикт

local FAMILY_M1 = "weapon-m1"
local FAMILY_CRIT = "weapon-critical"
local FAMILY_SPECIAL = "weapon-special"

------------------------------------------------------------------ состояние
local track_seen_at = setmetatable({}, { __mode = "k" })
local priority_cache = {}

-- защитник -> состояние доказательств
local DEFS = setmetatable({}, { __mode = "k" })
-- трек -> вердикт { auth=bool, serial=n, at=ms, grace=bool }
local VERDICT = setmetatable({}, { __mode = "k" })

------------------------------------------------------------------ утилиты
local function now_ms() return os.clock() * 1000 end

local function ping_ms()
    local p = 60
    pcall(function()
        local gg = getgenv()
        local L = gg and (gg.Latency or rawget(gg, "Latency"))
        if L and type(L.get_ping) == "function" then p = L:get_ping() * 1000 end
    end)
    return p
end

local function window(base_min, base_max)
    local stretch = math.min(ping_ms() * PING_STRETCH, PING_CAP)
    return base_min + stretch * 0.5, base_max + stretch
end

------------------------------------------------------------------ публичный API
function anti_ap_breaker:on()
    return aztup.flags.basic_validation
end

function anti_ap_breaker:compatibility()
    return aztup.flags.compatibility_mode_anti_ap_breaker
end

-- фильтры из меню; nil/unset = разрешено по умолчанию (не блокируем проверку)
function anti_ap_breaker:is_filter_on(flag)
    local ok, opts = pcall(function() return aztup_options.validation_filters end)
    if not ok or type(opts) ~= "table" or type(opts.Value) ~= "table" then return true end
    local v = opts.Value[flag]
    if v == nil then return true end
    return v and true or false
end

function anti_ap_breaker:is_filter_log_on(flag)
    local ok, opts = pcall(function() return aztup_options.validation_log_filters end)
    if not ok or type(opts) ~= "table" or type(opts.Value) ~= "table" then return false end
    local v = opts.Value[flag]
    if v == nil then return false end
    return v and true or false
end

function anti_ap_breaker:log(type, ...)
    local debug_on = false
    pcall(function() debug_on = aztup.flags.anti_ap_breaker_debug end)
    if not debug_on then return end
    if not self:is_filter_log_on(type) then return end
    -- args пакуем явно: "..." внутри вложенного closure валиден в Luau, но
    -- не переживает статический разбор (мешает проверке синтаксиса)
    local args = table.pack(...)
    pcall(function()
        setthreadidentity(8)
        Logger:short_notify("[Anti AP]",
            string.format(table.unpack(args, 1, args.n)))
    end)
end

------------------------------------------------------------------ доказательства
local function def_of(defender)
    if not defender then return nil end
    local d = DEFS[defender]
    if not d then
        d = {
            pending = {},       -- неиспользованные доказательства
            serial = 0,
            attached = false,
            conns = {},
            evidenceSeen = 0,
            injections = 0,
            cancel_at = nil,
            grace_until = now_ms() + RESYNC_GRACE_MS,
        }
        DEFS[defender] = d
    end
    return d
end

local function drop_stale(d)
    local t = now_ms()
    for i = #d.pending, 1, -1 do
        if t - d.pending[i].at > EVIDENCE_TTL_MS then
            table.remove(d.pending, i)
        end
    end
end

local function record(d, kind, families, exactFamily, weaponKey, opts)
    opts = opts or {}
    d.evidenceSeen = d.evidenceSeen + 1
    local lo, hi = window(opts.latMin or BASE_LATENCY_MIN, opts.latMax or BASE_LATENCY_MAX)
    d.serial = d.serial + 1
    d.pending[#d.pending + 1] = {
        serial = d.serial,
        kind = kind,
        families = families or {},
        exactFamily = exactFamily or nil,
        bridge = opts.bridge ~= false,
        weaponKey = weaponKey or nil,
        at = now_ms(),
        lo = lo,
        hi = hi,
    }
    drop_stale(d)
end

-- Есть ли доказательство, объясняющее этот трек? Возвращает serial или nil.
local function match_evidence(d, families, weaponKey)
    local t = now_ms()
    local bestIndex, bestScore = nil, math.huge

    for i, ev in ipairs(d.pending) do
        local age = t - ev.at
        -- вне окна задержки — этот evidence не про наш трек
        if age <= ev.hi and age >= ev.lo then
            local ok = false
            if ev.exactFamily then
                for _, f in ipairs(families) do
                    if f == ev.exactFamily then
                        ok = true
                        break
                    end
                    -- крит нередко стартует с m1-подобного трека
                    if ev.bridge and f == FAMILY_M1 then
                        ok = true
                        break
                    end
                end
            else
                for _, f in ipairs(families) do
                    if ev.families[f] then
                        ok = true
                        break
                    end
                end
            end

            -- трек, сыгранный НЕ ТЕМ оружием, не проходит
            if ok and not (ev.weaponKey and weaponKey and ev.weaponKey ~= weaponKey) then
                local score = age
                if ev.exactFamily then score = score - 1000 end -- точное семейство приоритетнее
                if score < bestScore then
                    bestIndex, bestScore = i, score
                end
            end
        end
    end

    if bestIndex then
        local ev = d.pending[bestIndex]
        local serial = ev.serial
        table.remove(d.pending, bestIndex) -- evidence одноразовое
        return serial
    end
    return nil
end

local function families_of()
    return { FAMILY_M1, FAMILY_CRIT, FAMILY_SPECIAL }
end

-- отпечаток оружия: отсекает трек, сыгранный не тем оружием
local function weapon_key(entity)
    local ok, s = pcall(function()
        if not entity then return nil end
        local attr = entity:GetAttribute("StoredToolName")
        if type(attr) == "string" and #attr > 0 then return attr end
        local tool = entity:FindFirstChildOfClass("Tool")
        if tool and tool.Name then return tool.Name end
        return nil
    end)
    if ok then return s end
    return nil
end

-- жив ли ещё защитник (не снят ли контекст)
local function self_alive(d, defender)
    if not d or not defender then return false end
    return DEFS[defender] == d
end

------------------------------------------------------------------ сбор evidence
local function attach(defender)
    local d = def_of(defender)
    if d.attached then return d end
    d.attached = true

    local entity = defender.entity
    if not entity then return d end

    -- 1) Requests.ClientEffect* — главный серверный канал.
    -- Три канала, а не один (сверено с palantir source.lua, RangeTelegraph.init):
    --   ClientEffect       — RemoteEvent/UnreliableRemoteEvent, OnClientEvent
    --   ClientEffectLarge  — то же самое, крупные эффекты
    --   ClientEffectDirect — BindableEvent, у него .Event, а НЕ OnClientEvent
    -- Ловля только первого оставляла дыру: часть реплицируемых эффектов
    -- приходит в Large/Direct, и без них атака выглядит как инъекция.
    pcall(function()
        local rs = game:GetService("ReplicatedStorage")
        local requests = rs:FindFirstChild("Requests")
        if not requests then return end

        local function on_effect(effect, data)
            if not self_alive(d, defender) then return end
            if type(effect) ~= "string" then return end
            local t = now_ms()
            if effect == "WeaponTrailOff" then
                d.pending = {}      -- отмена замаха: ожидания снимаем
                d.cancel_at = t
                return
            end
            local wk = weapon_key(entity)
            if effect == "WeaponTrail" then
                record(d, "replicated-weapon-trail",
                    { [FAMILY_M1] = true, [FAMILY_CRIT] = true, [FAMILY_SPECIAL] = true },
                    nil, wk, { latMax = BASE_LATENCY_MAX })
            elseif effect == "CriticalSwirl" then
                record(d, "replicated-critical-effect",
                    { [FAMILY_CRIT] = true }, FAMILY_CRIT, wk,
                    { latMin = CRIT_LATENCY_MIN, latMax = CRIT_LATENCY_MAX })
            end
        end

        for _, channel in ipairs({ "ClientEffect", "ClientEffectLarge" }) do
            local ev = requests:FindFirstChild(channel)
            if ev and (ev:IsA("RemoteEvent") or ev:IsA("UnreliableRemoteEvent")) then
                d.conns[#d.conns + 1] = ev.OnClientEvent:Connect(on_effect)
            end
        end

        -- Direct — BindableEvent: подписка через .Event
        local direct = requests:FindFirstChild("ClientEffectDirect")
        if direct then
            local bindable = direct:IsA("BindableEvent") and direct
                or (direct:FindFirstChild("Event") and direct:FindFirstChild("Event"))
            if bindable and bindable.Event then
                d.conns[#d.conns + 1] = bindable.Event:Connect(on_effect)
            end
        end
    end)

    -- 2) атрибуты персонажа: StoredAction == criticalattack
    pcall(function()
        d.conns[#d.conns + 1] = entity.AttributeChanged:Connect(function(name)
            if not self_alive(d, defender) then return end
            -- смена оружия инвалидирует доказательства прошлого оружия
            if name == "StoredToolName" or name == "PrimaryWeapon" or name == "Weapon" then
                d.pending = {}
                return
            end
            if name ~= "StoredAction" then return end
            local ok, v = pcall(function() return entity:GetAttribute("StoredAction") end)
            if not ok or type(v) ~= "string" or v:lower() ~= "criticalattack" then return end
            record(d, "replicated-stored-critical",
                { [FAMILY_CRIT] = true }, FAMILY_CRIT, weapon_key(entity),
                { latMin = CRIT_LATENCY_MIN, latMax = CRIT_LATENCY_MAX })
        end)
    end)

    -- 3) DescendantAdded: Ether = серверный спавн расхода
    pcall(function()
        d.conns[#d.conns + 1] = entity.DescendantAdded:Connect(function(inst)
            if not self_alive(d, defender) then return end
            if type(inst) ~= "Instance" then return end
            if inst.Name ~= "Ether" then return end
            d.last_ether = now_ms()
        end)
    end)

    -- 4) сброс на респауне
    pcall(function()
        local h = entity:FindFirstChildOfClass("Humanoid")
        if not h then return end
        d.conns[#d.conns + 1] = h.Died:Connect(function()
            d.pending = {}
            d.grace_until = now_ms() + RESYNC_GRACE_MS
        end)
    end)

    return d
end

------------------------------------------------------------------ проверка
function anti_ap_breaker:initial_check(defender, track)
    if not defender or not self:on() then return false end
    if not defender.is_player then return false end

    local d = attach(defender)
    if not d then return false end

    -- ---- слой 1: серверное evidence. Каждый трек проверяем один раз.
    if VERDICT[track] == nil then
        local t = now_ms()
        local wk = weapon_key(defender.entity)
        local serial = match_evidence(d, families_of(), wk)

        if serial then
            VERDICT[track] = { auth = true, serial = serial, at = t }
        elseif t < (d.grace_until or 0) then
            -- первые мс после спавна: данных ещё нет, не рубим
            VERDICT[track] = { auth = true, serial = 0, at = t, grace = true }
        else
            -- Серверного evidence нет. У настоящей атаки оно обязано быть.
            VERDICT[track] = { auth = false, at = t }
            d.injections = d.injections + 1
            self:log("No Evidence", "Track without server evidence (injections: %d)", d.injections)
        end
    end

    -- ---- слой 2: эвристики (cheap-мусор ловится ими быстрее всего)
    if track.Speed >= aztup.flags.anti_ap_breaker_max_speed
        and self:is_filter_on("S >= X (S = Speed)") then
        self:log("S >= X (S = Speed)", "Speed is too high, Speed: %.1f", track.Speed)
        return true
    end

    if track.Length / track.Speed <= (aztup.flags.anti_ap_breaker_length_ms / 1000)
        and self:is_filter_on("Length <= Xms") then
        self:log("Length <= Xms", "Length is too short, Length: %.1f", track.Length)
        return true
    end

    if track.Priority == Enum.AnimationPriority.Core and self:is_filter_on("Core Priority") then
        self:log("Core Priority", "Track is core priority")
        return true
    end

    if track.Priority == Enum.AnimationPriority.Idle and self:is_filter_on("Idle Priority") then
        self:log("Idle Priority", "Track is idle priority")
        return true
    end

    if track.Speed == 0 and self:is_filter_on("Speed == 0") then
        return self:log("Speed == 0", "Track is frozen")
    end

    track_seen_at[track] = tick()
    priority_cache[track] = track.Priority

    task.delay(30, function()
        priority_cache[track] = nil
        VERDICT[track] = nil
    end)

    return false
end

function anti_ap_breaker:clamp(val, min, max)
    if val < min then return min end
    if val > max then return max end
    return val
end

function anti_ap_breaker:handle_fadetime(track)
    return track.WeightCurrent < self:clamp(
        self:clamp(track.WeightTarget / 2, 1 / 120, tick() - (track_seen_at[track] or 0)), 0, 0.2)
end

local asset_id = require("@src/utility/asset_id")

function anti_ap_breaker:handle_priority_hiding(defender, track)
    local humanoid = defender.entity:FindFirstChild("Humanoid")
    if not humanoid then return false end
    local highest_priority = 1000

    for _, other_track in humanoid:GetPlayingAnimationTracks() do
        if track == other_track then continue end
        if other_track.Priority.Value == 1000 then continue end
        if track.Priority.Value >= other_track.Priority.Value then continue end
        if other_track.WeightCurrent <= track.WeightCurrent / 2 then continue end
        if other_track.WeightTarget <= 0.3 then continue end
        if other_track.Speed == 0 and other_track.TimePosition >= track.Length - 0.01
            or other_track.TimePosition <= 0.01 then continue end
        if not asset_id.get_id(other_track.Animation.AnimationId) then continue end
        if self:final_check(defender, other_track, true) then continue end
        -- учитываем только треки, прошедшие аутентификацию
        local v = VERDICT[other_track]
        if v == nil or v.auth then
            highest_priority = math.min(highest_priority, other_track.Priority.Value)
        end
    end

    return highest_priority ~= 1000 and highest_priority > track.Priority.Value
end

function anti_ap_breaker:final_check(defender, track, skip)
    if not self:on() then return false end

    local alive = self:is_playing(track, defender.entity)

    -- ---- слой 1: серверное evidence
    local v = VERDICT[track]
    if v and not v.auth and not v.grace and not skip and alive then
        -- неопознанный трек, переживший settle-окно, — это инъекция:
        -- сервер об атаке не сообщал, значит атаки не было
        if (now_ms() - v.at) > VERDICT_SETTLE_MS then
            self:log("No Evidence", "Unauthenticated track survived settle window")
            return true
        end
    end

    -- ---- слой 2: эвристики
    if alive and self:handle_fadetime(track) and self:is_filter_on("Fadetime") then
        if not skip then
            self:log("Fadetime", "Track is faded", track.WeightCurrent)
        end
        return true
    end

    if track.WeightTarget <= (aztup.flags.anti_ap_breaker_minimum_wt / 100)
        and self:is_filter_on("WT <= X (WT = WeightTarget)") then
        if track.WeightCurrent < (aztup.flags.anti_ap_breaker_minimum_wt / 100) or not alive then
            if not skip then
                self:log("WT <= X (WT = WeightTarget)",
                    "Track is too lightweight. WT - %.2f, WC - %.2f",
                    track.WeightTarget, track.WeightCurrent)
            end
            return true
        end
    end

    if self:is_filter_on("Priority Hiding") and not skip
        and self:handle_priority_hiding(defender, track) then
        if not skip then
            self:log("Priority Hiding", "Track is hidden behind another anims priority.")
        end
        return true
    end

    return false
end

function anti_ap_breaker:is_fully_dead(track, entity)
    local ok, res = pcall(function()
        return not table.find(entity:FindFirstChild("Humanoid"):GetPlayingAnimationTracks(), track)
    end)
    if ok then return res end
    return false
end

function anti_ap_breaker:is_playing(track, entity)
    if track.IsPlaying then return true end
    local ok, res = pcall(function()
        return table.find(entity:FindFirstChild("Humanoid"):GetPlayingAnimationTracks(), track)
    end)
    if ok then return res end
    return false
end

------------------------------------------------------------------ диагностика
-- Сколько evidence пришло, сколько инъекций отбито.
-- print(getgenv().RAIN_ANTI_AP_STATS())
function anti_ap_breaker:stats()
    local out = {}
    for _, d in pairs(DEFS) do
        out[#out + 1] = ("evidence=%d injections=%d pending=%d")
            :format(d.evidenceSeen, d.injections, #d.pending)
    end
    if #out == 0 then return "anti-ap: нет активных защитников" end
    return "anti-ap: " .. table.concat(out, " | ")
end

_G.RAIN_ANTI_AP_STATS = function()
    return anti_ap_breaker:stats()
end

return anti_ap_breaker

end)
__bundle_register("@src/features/auto-parry/handlers/ap_breaker_controller", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AP Breaker: применение выбранного метода (см. ap_breaker_methods.lua).
--
-- Методы вешаются на Animator каждого персонажа в игре: свои треки видны
-- клиенту только у них, и демонтировать/накрывать анимацию можно только
-- там. Переподключается на респавне и появлении новых NPC.
--
-- Настройки приходят из UI (aztup_options), читаются на каждый вызов
-- apply(), чтобы смена дропдауна подхватывалась без перезапуска скрипта.

local ap_controller = {}

local methods = require("@src/features/auto-parry/handlers/ap_breaker_methods");
local asset_id = require("@src/utility/asset_id");

local installed = {}      -- humanoid -> cleanup
local conns = {}
local enabled = false

local function opts()
    local o = aztup_options or {};
    local method = "Flood (Mask)";
    if type(o.ap_breaker_method) == "table" and o.ap_breaker_method.Value then
        method = o.ap_breaker_method.Value;
    end
    local intensity, hold;
    if type(o.ap_breaker_intensity) == "table" then
        intensity = tonumber(o.ap_breaker_intensity.Value);
    end
    if type(o.ap_breaker_core_hold_ms) == "table" then
        hold = tonumber(o.ap_breaker_core_hold_ms.Value);
    end
    return methods.METHODS[method], {
        method = method,
        intensity = intensity or 500,
        core_hold_ms = hold or 40,
    };
end

--- Ставит метод на один humanoid.
local function bind_humanoid(humanoid)
    if installed[humanoid] then return end

    -- для demotion полезно знать, что анимация вообще атакующая:
    -- без фильтра он снимал бы в Core любую анимацию, включая свои же
    -- маски, и они бы дрались между собой
    local o = {}
    local fn, settings = opts();
    if not fn then return end;

    if settings.method ~= "Flood (Mask)" then
        local filter = ap_controller.animation_filter;
        o.should_break = filter;
    end

    local ok, cleanup = pcall(fn, humanoid, {
        intensity = settings.intensity,
        core_hold_ms = settings.core_hold_ms,
        should_break = o.should_break,
    });

    if ok and type(cleanup) == "function" then
        installed[humanoid] = cleanup;
    end
end

--- Разрешает анимацию: вернуть true, если это атака врага.
--- Заполняется в anti-ap-breaker, у которого есть таблица таймингов.
ap_controller.animation_filter = nil

function ap_controller:rebind_all()
    self:detach_all();
    if not enabled then return end;
    self:bind_all();
end

function ap_controller:bind_all()
    local players = game:GetService("Players");

    for _, plr in ipairs(players:GetPlayers()) do
        local function bind_char(character)
            if not character then return end
            local hum = character:FindFirstChildOfClass("Humanoid");
            if hum then bind_humanoid(hum) end
        end
        bind_char(plr.Character);
        conns[#conns + 1] = plr.CharacterAdded:Connect(bind_char);
    end;

    -- NPC: персонажи без игрока
    local function bind_model(model)
        if not model:IsA("Model") then return end
        if players:GetPlayerFromCharacter(model) then return end
        local hum = model:FindFirstChildOfClass("Humanoid");
        if hum then bind_humanoid(hum) end
    end

    for _, obj in ipairs(workspace:GetDescendants()) do
        pcall(function() bind_model(obj) end);
    end

    conns[#conns + 1] = workspace.DescendantAdded:Connect(function(obj)
        pcall(function() bind_model(obj) end);
    end);
end

function ap_controller:detach_all()
    for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end;
    table.clear(conns);
    for humanoid, cleanup in pairs(installed) do
        pcall(function() cleanup() end);
        installed[humanoid] = nil;
    end
end

function ap_controller:set_enabled(val)
    val = val and true or false;
    if val == enabled then return end;
    enabled = val;
    if enabled then self:bind_all() else self:detach_all() end;
end

function ap_controller:is_enabled()
    return enabled;
end

return ap_controller
end)
__bundle_register("@src/features/auto-parry/handlers/ap_breaker_methods", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AP Breaker: переносимые из Palantir методы ломания.
--
-- Palantir (palantir source.lua, Features/Combat/APBreakerCore) держит три
-- метода и даёт выбор в дропдауне. Все три перенесены сюда как отдельные
-- методы — они принципиально разные и по-разному ведут себя на сервере,
-- поэтому выбор за пользователем.
--
--   Method 1 — Flood / mask.
--     Шесть анимаций-масок грузятся на Animator цели и держатся на
--     Enum.AnimationPriority.Action4. На каждый AnimationPlayed маска
--     переигрывается. Настоящая анимация формально не исчезает, но её
--     вес выдавливает более высокий приоритет. Сервер при этом видит
--     всё как обычно — маска клиентская.
--
--   Method 2 — Priority demotion + Core hold.
--     На AnimationPlayed атакующего трека: все играющие треки кроме
--     Idle/Movement снимаются в Core, сам трек тоже ставится в Core,
--     через core_hold_ms приоритеты возвращаются как были. Это то, что в
--     Palantir названо "Method 2 Fake Anim Time" (ползунок 5..200 мс).
--
--   Method 3 — Method 1 + Method 2 одновременно (в Palantir это Method 3,
--     который зовёт f1266 + f1257 + f1279).
--
-- Про общее ограничение см. шапку anti-ap-breaker.lua: ломание не отменяет
-- серверный RemoteEvent — оно лишь убирает анимацию, то есть фактически
-- отказывается от пари. Методы дают разную цену этому, но не дают большего.

local ap_methods = {}

-- Анимации-маски. Список из Palantir APBreakerCore.
ap_methods.MASK_IDS = {
    "rbxassetid://9149348937",
    "rbxassetid://10880473795",
    "rbxassetid://5778357994",
    "rbxassetid://16873988732",
    "rbxassetid://7620630583",
    "rbxassetid://8378263543",
}

local now_ms = (tick and function() return math.floor(tick() * 1000) end)
    or os.clock
local function now() return now_ms() end

------------------------------------------------------------------ Method 1

--- Flood: маски на Action4, переигрывание на каждой анимации.
---@param humanoid Instance
---@param opts table
---@return function cleanup
function ap_methods.flood(humanoid, opts)
    opts = opts or {};
    local animator = humanoid:FindFirstChildOfClass("Animator");
    if not animator then
        animator = Instance.new("Animator");
        pcall(function() animator.Parent = humanoid end);
    end
    if not animator then return function() end end;

    local tracks = {}          -- mask track -> animation id
    local by_id = {}           -- animation id -> true
    local holding = false

    for _, id in ipairs(ap_methods.MASK_IDS) do
        local anim = Instance.new("Animation");
        anim.AnimationId = id;
        anim.Name = "RAIN_AP_MASK";
        local ok, track = pcall(function() return animator:LoadAnimation(anim) end);
        -- сам Animation не уничтожаем: AnimationTrack на него ссылается,
        -- Destroy() рвёт трек
        if ok and track then
            pcall(function() track.Priority = Enum.AnimationPriority.Action4 end);
            tracks[#tracks + 1] = track;
            by_id[id] = true;
        end
    end

    -- intensity: минимальный интервал между переигрываниями, мс
    local min_interval = math.floor(1000 / math.max(1, opts.intensity or 500))
    local last = 0

    local conn = animator.AnimationPlayed:Connect(function()
        if holding then return end
        local t = now()
        if t - last < min_interval then return end
        last = t;
        holding = true;
        for _, track in ipairs(tracks) do
            pcall(function()
                track:Play(0);
                track.TimePosition = 0;
            end);
        end;
        task.delay(math.max(0.01, (opts.core_hold_ms or 40) / 1000), function()
            holding = false;
        end);
    end)

    return function()
        pcall(function() conn:Disconnect() end);
        for _, track in ipairs(tracks) do
            pcall(function() track:Stop(); track:Destroy() end);
        end;
        table.clear(tracks);
        table.clear(by_id);
    end;
end

------------------------------------------------------------------ Method 2

--- Priority demotion: снять чужие треки в Core, подержать, вернуть.
---@param humanoid Instance
---@param opts table  intensity, core_hold_ms, should_break(track) -> bool
---@return function cleanup
function ap_methods.demote(humanoid, opts)
    opts = opts or {};
    local animator = humanoid:FindFirstChildOfClass("Animator");
    if not animator then return function() end end;

    local holding = false
    local hold_ms = opts.core_hold_ms or 40

    -- intensity ограничивает частоту срабатываний
    local min_interval = math.floor(1000 / math.max(1, opts.intensity or 500))
    local last = 0

    local function apply(track)
        if holding then return end

        -- треки, которые мы сами и так опустили
        if track.Priority == Enum.AnimationPriority.Core then return end
        -- Idle/Movement не трогаем: это перемещение, его демонтаж ломает
        -- визуал персонажа без выигрыша
        if track.Priority == Enum.AnimationPriority.Idle then return end

        -- вызывающий может отфильтровать по тегу/таймингу
        if opts.should_break and not opts.should_break(track) then return end

        local t = now()
        if t - last < min_interval then return end
        last = t;
        holding = true;

        local saved = {}
        for _, other in ipairs(animator:GetPlayingAnimationTracks()) do
            if other ~= track
                and other.Priority ~= Enum.AnimationPriority.Movement
                and other.Priority ~= Enum.AnimationPriority.Idle then
                saved[other] = other.Priority;
                pcall(function() other.Priority = Enum.AnimationPriority.Core end);
            end
        end;

        local own = track.Priority;
        pcall(function() track.Priority = Enum.AnimationPriority.Core end);

        task.delay(hold_ms / 1000, function()
            -- восстанавливаем только то, что ещё играет и не было снято
            for other, prio in pairs(saved) do
                if other.IsPlaying then
                    pcall(function() other.Priority = prio end);
                end
            end
            if track.IsPlaying then
                pcall(function() track.Priority = own end);
            end
            holding = false;
        end);
    end

    local conn = animator.AnimationPlayed:Connect(function(track) apply(track) end);

    return function()
        pcall(function() conn:Disconnect() end);
    end;
end

------------------------------------------------------------------ Method 3

--- Flood + demotion одновременно (Method 3 из Palantir).
function ap_methods.combined(humanoid, opts)
    local a = ap_methods.flood(humanoid, opts);
    local b = ap_methods.demote(humanoid, opts);
    return function()
        a();
        b();
    end;
end

------------------------------------------------------------------ реестр

ap_methods.METHODS = {
    ["Flood (Mask)"] = ap_methods.flood,
    ["Priority Demotion"] = ap_methods.demote,
    ["Flood + Demotion"] = ap_methods.combined,
}

return ap_methods
end)
