        mira_tick(delta_time)
        return
    elseif #mira.pool > 0 or mira.mask then
        mira_teardown()
    end
    if aztup_options.ap_breaker_type.Value == "Aggressive 4 (Blatant)" or aztup_options.ap_breaker_type.Value == "Aggressive 3 (Blatant)" or aztup_options.ap_breaker_type.Value == "Spoof" then return end
    local intensity = aztup.flags.ap_breaker_intensity or 5;
    animation_budget = animation_budget + ((delta_time or 0) * intensity);

    if intensity > 5 and tick() - last_notif_warn > 60 then
        last_notif_warn = tick();
        Logger:long_notify_sound("AP Breaker Intensity over 4 may cause your anims to break.")
    end

    if aztup_options.ap_breaker_type.Value == "Tester Aggressive 1 (Blatant)" then
        if intensity > 20 then
            intensity = 20;
        end;
    end;

    local humanoid = local_player.humanoid;
    if not humanoid then return end;

    local plays_this_frame = 0;
    while animation_budget >= 1 and plays_this_frame < 30 do
        animation_budget = animation_budget - 1;
        plays_this_frame = plays_this_frame + 1;

        local should_proc_aggressive = (aztup_options.ap_breaker_type.Value == "Aggressive" or aztup_options.ap_breaker_type.Value == "Aggressive 3 (Blatant)"  or aztup_options.ap_breaker_type.Value == "Aggressive 4 (Blatant)" or aztup_options.ap_breaker_type.Value == "Aggressive 2 (Blatant)" or aztup_options.ap_breaker_type.Value == "Tester Aggressive 1 (Blatant)") and humanoid.MoveDirection.Magnitude > 0.1;
        local animation_instance = Instance.new("Animation");
        if aztup_options.ap_breaker_type.Value == "Tester Aggressive 1 (Blatant)" then
            animation_instance.AnimationId = subtle_anims[math.random(1, #subtle_anims)];
        else
            animation_instance.AnimationId = should_proc_aggressive and target_anims[math.random(1, #target_anims)] or non_ag_anims[math.random(1, #non_ag_anims)];
        end;

        local ag_time = 0.065;
        if aztup_options.ap_breaker_type.Value == "Aggressive 2 (Blatant)" then
            local anim_id = math.random() > 0.5 and "5828315760" or "10104294736"
            animation_instance.AnimationId = "rbxassetid://" .. anim_id;
            ag_time = 0.01;
            should_proc_aggressive = true;
        elseif aztup_options.ap_breaker_type.Value == "Tester Aggressive 1 (Blatant)" and should_proc_aggressive then
            ag_time = math.random() * 0.15;
        end;

        last_added_track = humanoid:LoadAnimation(animation_instance);
        last_added_track.Priority = Enum.AnimationPriority.Action;
        local rand = Random.new();
        if aztup_options.ap_breaker_type.Value == "Tester Aggressive 1 (Blatant)" and should_proc_aggressive then
            
            local breaker_type = rand:NextInteger(1, 3);
            last_added_track:AddTag("PR_BREAKER_IGNORE")

            if breaker_type == 1 then
                last_added_track.Priority = rand:NextNumber() > 0.5 and Enum.AnimationPriority.Movement or Enum.AnimationPriority.Action;
                last_added_track:Play(rand:NextNumber(0.6, 1), rand:NextNumber(0.4, 0.6), rand:NextNumber(0.5, 0.6));
                task.wait(1 / 15);
                last_added_track.Priority = Enum.AnimationPriority.Core;
                last_added_track:AdjustWeight(rand:NextNumber(0.5, 1), 0)
            elseif breaker_type == 2 then
                last_added_track:Play(rand:NextNumber(0.75, 5), rand:NextNumber(0.4, 0.6), rand:NextNumber(0.25, 5));
            else
                last_added_track:Play(9999999, rand:NextNumber(0.5, 1), rand:NextNumber(0.25, 3));
            end;
            should_proc_aggressive = true;
            
            continue        
elseif should_proc_aggressive then
