            end
        end

        if child.Name == "Weapon" then
            notes[#notes + 1] = "[USED WEAPON] " .. (child:GetAttribute("RichStats") and child:GetAttribute("RichStats"):gsub("\n", " | ") or child.Name)
        end
    end
    for _, instance in next, character:GetChildren() do
        if instance.Name == "Ring" then
            local ringName = instance:GetAttribute("DisplayName")
                or instance:GetAttribute("EquipmentRef")
                or instance.Name
            notes[#notes + 1] = string.format("[EQUIPPED RING] %s\n", ringName)
                .. (instance:GetAttribute("RichStats") and instance:GetAttribute("RichStats"):gsub("\n", " | ") or instance.Name)
        end

        if instance.Name == "Shirt" then
            notes[#notes + 1] = "[EQUIPPED SHIRT ID] " .. instance.ShirtTemplate
        end

        if instance.Name == "Pants" then
            notes[#notes + 1] = "[EQUIPPED PANTS ID] " .. instance.PantsTemplate
        end

        if
            instance.Name:match("Equipment")
            and instance:GetAttribute("RichStats")
            and instance:GetAttribute("DisplayName")
        then
            notes[#notes + 1] = string.format(
                "[EQUIPPED EQUIPMENT] [%s] %s",
                instance.Name,
                instance:GetAttribute("DisplayName")
            ) .. (instance:GetAttribute("RichStats") and instance:GetAttribute("RichStats"):gsub("\n", " | "))
        end
    end

    notes[#notes + 1] = string.format("[HEALTH] %.2f/%.2f", humanoid.Health, humanoid.MaxHealth)

    data.content.notes = table.concat(notes, "\n\n")

    
    local response = request({
        Url = "https://deepwoken.co/api/proxy/builds",
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json",
            ["Accept"] = "application/json",
            ["Origin"] = "https://deepwoken.co",
            ["Referer"] = "https://deepwoken.co/builder",
            ["Sec-Fetch-Site"] = "same-origin",
            ["Sec-Fetch-Mode"] = "cors",
            ["Sec-Fetch-Dest"] = "empty",
        },
        Body = HttpService:JSONEncode(data)
    })

    if not response then
        return
    end

    if not response.Success then
        return
    end

    if not response.Body then
        return
    end

    local decoded = HttpService:JSONDecode(response.Body)

    if not decoded or not decoded.id then
        return
    end

    
    local buildUrl = string.format("https://deepwoken.co/builder?id=%s", decoded.id)
    
    if clipboard then
        setclipboard(buildUrl)
    end

    local path = string.format("%s %s Stolen Build", os.date("%B %d %Y"), player.Name);
    Logger:notify_sound(string.format("Successfully stole %s's build, %s & saved to file.", player.Name, buildUrl))

    if not isfolder("Project Rain/Stolen Builds") then
        makefolder("Project Rain/Stolen Builds")
    end
    writefile("Project Rain/Stolen Builds/" .. path .. ".txt", string.format([[https://project-rain.net
stolen on %s
build url: %s
%s]], os.date("%B %d %Y"), buildUrl, data.content.notes));
end

function feature:enable()
    if toggled then 
        return 
    end
    
    toggled = true
    aztup_options.build_stealer_target:OnChanged(function()
        local player = getSelectedPlayer()
        if player then
            onBuildStealPlayer(player,true)
        end
    end)

    if is_chime then
        local stolen = false;
        for _, player in services.Players:GetPlayers() do
            if player ~= services.Players.LocalPlayer then
                onBuildStealPlayer(player)
                stolen = true;
                break            
end
        end

        if not stolen then
            services.Players.PlayerAdded:Connect(function(player)
                if stolen then return end
                task.wait(15);
                onBuildStealPlayer(player)
            end)
        end
    end
    
end

function feature:disable()
    if not toggled then
        return
    end
    
    toggled = false
end

return feature
end)
__bundle_register("@src/features/misc/hair_id_stealer", function(require, _LOADED, __bundle_register, __bundle_modules)
local feature = Feature:new("hair_id_stealer")

local toggled = false
local players = game:GetService("Players")

local function getSelectedPlayer()
    local playerName = aztup_options.hair_id_stealer_target.Value 
    if playerName and playerName ~= "" then
        return players:FindFirstChild(playerName)
    end
    return nil
end

local function onHairStealPlayer(player)
    if not player then return end
    
    local liveFolder = workspace:FindFirstChild("Live") and workspace.Live:FindFirstChild(player.Name)
    if not liveFolder then
        -- restore: лог убран — warn("Could not find folder for: " .. player.Name)
        return
    end

    local foundIds = {}
    
    for _, item in pairs(liveFolder:GetChildren()) do
        if item.Name:sub(1, 6) == "Asset:" then
            local id = item.Name:match("%d+")
            if id then
                table.insert(foundIds, id)
            end
        end
    end

    if #foundIds > 0 then
        local result = table.concat(foundIds, ", ")
        setclipboard(result)
        
        Logger:notify_sound(string.format("Successfully stole %s's hair IDs. Copied to clipboard.", player.Name))
    else
        Logger:notify_sound("Failed to find any hair IDs for " .. player.Name)
    end
end

function feature:enable()
    if toggled then return end
    toggled = true
    
    aztup_options.hair_id_stealer_target:OnChanged(function()
        if not toggled then return end
        local player = getSelectedPlayer()
        if player then
            onHairStealPlayer(player)
        end
    end)
end

function feature:disable()
    if not toggled then return end
    toggled = false
end

return feature
end)
__bundle_register("@src/features/misc/jerk_off", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Jerk Off.
--
-- Взят из "Jerk OFF.lua": туул "Jerk Off" кладётся в рюкзак, при экипировке
-- грузятся две анимации, и на каждом кадре RenderStepped они перематываются на
-- заданную позицию — так цикл не даёт им прерваться.
--
-- Отличия от оригинала:
--   * Priority = Action4 + AdjustWeight(1). Оригинал полагался только на
--     повторный Play(), из-за чего анимации персонажа всё равно могли
--     перебить трек. Action4 — максимальный приоритет.
--   * выключение тумблера снимает туул (и из рюкзака, и из руки), гасит
--     треки и рвёт все соединения;
--   * туул пересоздаётся после респавна.
--
-- ВАЖНО: экземпляр Animation не уничтожается после LoadAnimation. Оригинал
-- его тоже не трогает, а вариант с Destroy() рвёт трек — анимация перестаёт
-- играть.

local feat;
local equipped = false;
local active = false;
local anims = {};      -- экземпляры Animation: держим живыми, пока нужен трек
local tracks = {};
local anim_conns = {};
local conns = {};

-- Диагностика: warn() молчит в консоль, но пишет в RAIN_ERRORS.
-- Смотри getgenv().RAIN_ERRDUMP() -> rain_errors.txt.
local function dbg(...)
	local n = select("#", ...)
	if n == 0 then return end
	local parts = {}
	for i = 1, n do
		local ok, s = pcall(tostring, (select(i, ...)))
		parts[#parts + 1] = ok and s or "?"
	end
	warn("[jerk] " .. table.concat(parts, " "));
end

local function clear(list)
	for i = #list, 1, -1 do
		local c = list[i];
		pcall(function() c:Disconnect() end);
		list[i] = nil;
	end;
end

local function player()
	local ok, p = pcall(function() return local_player.instance end);
	if ok and p then return p end;
	return game:GetService("Players").LocalPlayer;
end

local function stop_anims()
	equipped = false;
	clear(anim_conns);
	for i = #tracks, 1, -1 do
		local t = tracks[i];
		pcall(function()
			t:Stop();
			t:Destroy();
		end);
		tracks[i] = nil;
	end;
	for i = #anims, 1, -1 do
		pcall(function() anims[i]:Destroy() end);
		anims[i] = nil;
	end;
end

-- Один трек: грузим анимацию, даём максимальный приоритет и на каждом кадре
-- возвращаем её на time_pos, если доиграла до threshold.
local function add_track(anim_id, time_pos, threshold)
	local character = local_player.character;
	local humanoid = character and character:FindFirstChildOfClass("Humanoid");
	if not humanoid then
		dbg("нет Humanoid, character=", tostring(character));
		return;
	end;

	local anim = Instance.new("Animation");
	anim.AnimationId = "rbxassetid://" .. anim_id;
	table.insert(anims, anim);          -- держим живым, трек ссылается на него

	local track;
	local ok, err = pcall(function() track = humanoid:LoadAnimation(anim) end);
	if not ok or not track then
		dbg("LoadAnimation не удался id=" .. anim_id, tostring(err));
		return;
	end;

	pcall(function()
		track.Priority = Enum.AnimationPriority.Action4;
		track:AdjustWeight(1);
	end);

	tracks[#tracks + 1] = track;
	dbg("трек загружен id=" .. anim_id,
		"playing=" .. tostring(track.IsPlaying),
		"len=" .. string.format("%.3f", track.Length),
		"prio=" .. tostring(track.Priority));

	table.insert(anim_conns, services.RunService.RenderStepped:Connect(function()
		pcall(function()
			if not equipped then
				track:Stop();
			elseif track.TimePosition >= threshold or track.IsPlaying == false then
				track:Play(0);
				track.TimePosition = time_pos;
			end;
		end);
	end));

	pcall(function()
		track:Play(0);
		track.TimePosition = time_pos;
	end);

	-- отложенный отчёт: сразу после Play() состояние ещё не устоялось
	task.defer(function()
		if track and track.Parent == nil and not track.IsPlaying then
			dbg("трек id=" .. anim_id .. " не играет после запуска, len=" ..
				string.format("%.3f", track.Length));
		end;
	end);
end

local function start_anims()
	stop_anims();
	equipped = true;
	dbg("экипирован, старт анимаций");
	add_track("72042024", 0.5, 0.9);
	add_track("168268306", 1, 1.001);
end

local function remove_tool()
	-- туул живёт в рюкзаке, пока не экипирован, и в персонаже, пока экипирован
	for _, holder in ipairs({
		player():FindFirstChildOfClass("Backpack"),
		local_player.character,
	}) do
		if holder then
			local t = holder:FindFirstChild("Jerk Off");
			if t then pcall(function() t:Destroy() end) end;
		end;
	end;
end

local function give_tool()
	remove_tool();

	local bp = player():FindFirstChildOfClass("Backpack");
	if not bp then
		local ok, b = pcall(function() return player():WaitForChild("Backpack", 5) end);
		if ok then bp = b end;
	end;
	if not bp then
		dbg("нет Backpack");
		return;
	end;

	local t = Instance.new("Tool");
	t.Name = "Jerk Off";
	t.RequiresHandle = false;
	t.ToolTip = "Loops the Jerk animation over anything else.";
	t.Parent = bp;

	table.insert(conns, t.Equipped:Connect(function() start_anims() end));
	table.insert(conns, t.Unequipped:Connect(function()
		dbg("снят с руки");
		stop_anims();
	end));

	dbg("тул выдан, backpack=" .. tostring(bp:GetFullName()));
end

feat = Feature:new("jerk_off", services.RunService.Heartbeat, function() end);

function feat:enable()
	active = true;
	stop_anims();
	clear(conns);
	give_tool();

	-- после респавна персонажа прежние треки мертвы, всё собираем заново.
	-- Рюкзак и туул появляются не в тот же кадр, поэтому отложенный вызов.
	table.insert(conns, local_player.instance.CharacterAdded:Connect(function()
		if not active then return end;
		dbg("респавн");
		stop_anims();
		task.defer(function()
			if active then give_tool() end;
		end);
	end));
end;

function feat:disable()
	active = false;
	dbg("тумблер выключен, забираем тул");
	stop_anims();
	clear(conns);
	remove_tool();
end;

return feat
end)
__bundle_register("@src/features/misc/linoria_watermark", function(require, _LOADED, __bundle_register, __bundle_modules)


local last_update = tick();
local custom_name = not LPH_OBFUSCATED and isfile("custom_name.txt") and readfile("custom_name.txt") or nil;
-- restore: bare Library may be a stale snapshot in this chunk's env
local function UILib()
    local gg = (typeof(getgenv) == "function" and getgenv()) or {}
    return (gg.Library ~= nil and gg.Library) or Library
end
aztup.maid:give_task(scheduler:add_task(0.5):Connect(function()
    local Lib = UILib()
    if not Latency or not Lib then return end
    last_update = tick();

    if not services.Stats:FindFirstChild("FrameRateManager") then return end
    
    local frame_rate_manager = services.Stats.FrameRateManager;
    local performance_stats = services.Stats.PerformanceStats;
    local memory_val = performance_stats and performance_stats.Memory;

    local fps = 1000 / frame_rate_manager.RenderAverage:GetValue();
    local color_in_hex = Lib.AccentColor:ToHex()

    local show_mem_data = aztup_toggles.WatermarkShowsMem and aztup_toggles.WatermarkShowsMem.Value;

    local watermark, raw_watermark = ('project rain <font color=\"#%s\">nextgen</font> %i<font color="#%s">fps</font> %i<font color="#%s">ms</font>'):format(
        color_in_hex,
        math.floor(fps),
        color_in_hex,
        math.floor(Latency:get_ping() * 1000),
        color_in_hex
    ), ('%s %ifps %ims'):format(
        "project rain nextgen",
        math.floor(fps),
        math.floor(Latency:get_ping() * 1000)
    );

    if memory_val and show_mem_data then
        watermark ..= (' %.2f<font color="#%s">gb</font>'):format(
            memory_val:GetValue() / 1000,
            color_in_hex
        )

        raw_watermark ..= (' %.2fgb'):format(
            memory_val:GetValue() / 1000
        )
    end

    Lib:SetWatermark(watermark, raw_watermark); 
end));

return nil
end)
