__bundle_register("@src/features/spoofing/agility_spoofer", function(require, _LOADED, __bundle_register, __bundle_modules)

local last_update = 0
local feature
local old_agility
local was_on = false
local parser = require("@src/utility/deepwoken/ssv_parser");

feature = Feature:new("agility_spoofer", game:GetService("RunService").Heartbeat, (function()
        if tick() - last_update < (aztup.flags.agility_spoof_health and 0.075 or 1) then return end
        last_update = tick()

        local character = local_player.character
        if not character then return end

        local passive = character:FindFirstChild("PassiveAgility")
        if not passive then return end

        if aztup.flags.agility_spoofer then
            if not was_on then
                old_agility = passive.Value
                was_on = true
            end

            local target_agility = 8 + (aztup.flags.agility_spoof_amount / 10) * 2;
            if aztup.flags.agility_spoof_health then
                target_agility *= 1 + math.clamp((local_player.humanoid.Health / local_player.humanoid.MaxHealth) * aztup.flags.disallow_scaling_multiplier, 0, aztup.flags.disallow_scaling_multiplier);
            end
            

            passive.Value = target_agility;
        elseif was_on then
            passive.Value = old_agility
            was_on = false
        end
    end
))

function feature:enable()
    local character = local_player.character
    if not character then return end

    local passive = character:FindFirstChild("PassiveAgility")
    if passive then
        old_agility = passive.Value
        was_on = true
    end
end

function feature:disable()
    if not was_on then return end

    local character = local_player.character
    if not character then return end

    local passive = character:FindFirstChild("PassiveAgility")
    if passive and old_agility then
        passive.Value = old_agility
    end

    was_on = false
end

return feature

end)
__bundle_register("@src/features/spoofing/captain_etrea_spoof", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Captain Etrea spoof.
--
-- Механика взята из Features/Combat (Ap_Central, строки ~30690 и ~30613):
-- пассивы лежат в EffectReplicator.Passives, и Captain Etrea снимает штраф
-- скорости блока. Спуфер просто выставляет ключ в true, пока тумблер включён,
-- и возвращает nil при выключении — если пассива не было изначально.
-- Механика идентична остальным спуферам проекта (Lightweight, Freestyler's
-- Band, Konga's Clutch Ring), отличается только именем ключа.

local last_update = 0;
local feature;
local passive = "Captain Etrea"


local function get_passives()
	local effect_replicator = getgenv().EffectReplicator;
	if not effect_replicator then
		local success, result = pcall(require, game:GetService("ReplicatedStorage"):WaitForChild("EffectReplicator"));
		if success then
			effect_replicator = result;
		end;
	end;
	return effect_replicator and effect_replicator.Passives
end;

feature = Feature:new("captain_etrea_spoof", game:GetService("RunService").Heartbeat, (function()
	if tick() - last_update < 5 then return end

	last_update = tick();
	local passives = get_passives();
	if not passives then return end;

	-- Держим пассиву, даже если игра её сбросила (серверный ресет).
	if not passives[passive] then
		passives[passive] = true;
		feature.injected = true;
	end;
end));

function feature:enable()
	local passives = get_passives();
	if not passives then return end;

	self.injected = not passives[passive];
	if self.injected then
		passives[passive] = true;
	end;
end;

function feature:disable()
	local passives = get_passives();
	if passives and self.injected then
		passives[passive] = nil;
	end;
	self.injected = false;
end

return feature

end)
