			if #Eyebrows < 1 then
				Eyebrows = GetEyebrowsForRace(LoadedFile.Name)
			end
		else
			Eyebrows = GetEyebrowsForRace(LoadedFile.Name)
		end

		RaceConfig[LoadedFile.Name] = {
