				end

				if v.MarkColor  then
					replacement.MarkColor = Color3.fromHex(v.MarkColor)
				end

				PortedColors[NewKey] = replacement
			end

			for i,v in pairs(OurChoices[LoadedFile.Name].Ornaments) do
