				end

			end

			OurChoices[LoadedFile.Name].CustomColors = PortedColors
			OurChoices[LoadedFile.Name].Ornaments = PortedOrnaments

			if OurChoices[LoadedFile.Name].Face then
				for i,v in pairs(OurFaces.Decals) do
