        end;
    end;
    game:GetService("TweenService"):Create(Music, TweenInfo.new(2), { Volume = 0 }):Play();
    game:GetService("Debris"):AddItem(Music, 2);
    game:GetService("Debris"):AddItem(Converted["_ScreenGui"], 2);
    game.Players.LocalPlayer:Kick("You must accept the Terms of Service to use PR.");
    task.wait()
           
    local roblox_prompt_gui = services.CoreGui:FindFirstChild("RobloxPromptGui")
    if not roblox_prompt_gui then
        return
    end

    roblox_prompt_gui.promptOverlay.ErrorPrompt.TitleFrame.ErrorTitle.TextColor3 = Color3.fromRGB(125, 196, 228)
    roblox_prompt_gui.promptOverlay.ErrorPrompt.TitleFrame.ErrorTitle.Text = "Project Rain"
    roblox_prompt_gui.promptOverlay.ErrorPrompt.MessageArea.ErrorFrame.ErrorMessage.Text = "You must accept the Terms of Service to use PR"
end)

repeat task.wait() until accepted;
task.wait(2);
end)
__bundle_register("@src/ui/ui", function(require, _LOADED, __bundle_register, __bundle_modules)
 
local tab, _ = require("@src/utility/ui/wrapper");

return {
    initialize = function()
        local creation_order = {
            "Main",
            "Visuals",
            "Combat",
            "Automation"
        };
 
        -- restore: было pairs() по массиву — порядок вкладок в UI получался
        -- случайным (AddTab регистрирует их в порядке вызовов). ipairs даёт
        -- детерминированный порядок: Main, Visuals, Combat, Automation.
        for _, tab_name in ipairs(creation_order) do
            aztup.tabs[tab_name] = tab.new(tab_name);
        end
        for _, module in list_modules("ui/tabs/*") do
            -- restore: модуль вкладки отдаёт ДВА значения (func, { name = ... }).
            -- Раньше тут стояло "require(module)" в for-in, где лишнее значение
            -- отбрасывалось, и data.name давал nil -> вкладки оставались пустыми.
            local func, data = require(module)
            if type(func) ~= "function" or type(data) ~= "table" or not data.name then
                -- restore: лог убран — warn("[restore] ui: tab module returned no name :: " .. tostring(module))
                continue
            end
            if not aztup.tabs[data.name] then
                -- ui_only: этот модуль рисуется в UI-вкладке, отдельного слота
                -- у него нет by design — тихо пропускаем, без warn
                if not data.ui_only then
                    -- restore: лог убран — warn("[restore] ui: no tab slot for " .. tostring(data.name) .. " (" .. tostring(module) .. ")")
                end
                continue
            end
            local ok, err = xpcall(func, warn, aztup.tabs[data.name])
            if not ok then
                -- restore: лог убран — warn("[restore] ui: tab " .. tostring(data.name) .. " failed :: " .. tostring(err))
            end
        end

        local ThemeManager = require("@src/utility/librarys/managers/ThemeManager");
        local SaveManager = require("@src/utility/librarys/managers/SaveManager");
        
        aztup.tabs.UI = tab.new("UI");

        SaveManager:SetLibrary(aztup.ui)
        SaveManager:IgnoreThemeSettings() 
        ThemeManager:SetLibrary(aztup.ui);

        SaveManager:SetIgnoreIndexes({
            "fly",
            "noclip",
            "speed",
            "infinite_jump",
            "spotify_redirect_url",
            
        })
        SaveManager:SetFolder('Project Rain/Deepwoken-Config')
        ThemeManager:SetFolder('Project Rain/Deepwoken-Config')
        SaveManager:BuildConfigSection(aztup.tabs.UI.Tab);
        ThemeManager:ApplyToTab(aztup.tabs.UI.Tab);

        task.spawn(pcall, require("@src/ui/config_converter"));
        -- restore: fast-flag кнопки (часть зависит от типа исполнителя) и
        -- ally-фильтры живут внизу вкладки UI. Раньше это шло через
        -- task.spawn(xpcall, require("@src/ui/tabs/ui"), warn, aztup.tabs.UI) —
        -- в task.spawn результат require терялся, поэтому setup уходил в
        -- фон и мог отработать до готовности UI. Теперь вызов прямой и под xpcall.
        local ui_extra = require("@src/ui/tabs/ui")
        if type(ui_extra) == "function" then
            local ok, err = xpcall(ui_extra, warn, aztup.tabs.UI)
            if not ok then
                -- restore: лог убран — warn("[restore] ui: UI extras failed :: " .. tostring(err))
            end
        end

        task.spawn(function()
            aztup_toggles.mod_detector:SetValue(true);
        end);
        
        local start = tick();
        if aztup.automation:has_any() then
            task.spawn(pcall, function()
                SaveManager:LoadAutoloadConfig()
            end);
        else
            SaveManager:LoadAutoloadConfig()
        end;
        local custom_name = not LPH_OBFUSCATED and isfile("custom_name.txt") and readfile("custom_name.txt") or nil;
        Library.PRWindow:SetWindowTitle((function()
		    if custom_name then
		    	return string.format(LPH_ENCSTR("%s"), custom_name:gsub("|ACCENT", "<font color=\"#" .. Library.AccentColor:ToHex() .. "\">"))		    
end
		    return string.format(LPH_ENCSTR("pr <font color=\"#%s\">nextgen</font>"), Library.AccentColor:ToHex())
	    end)())

        aztup.auto_loaded = true;

        -- restore: clickable banner above the main window (src/ui/menu_banner.lua)
        task.spawn(xpcall, function()
            require("@src/ui/menu_banner").initialize()
        end, warn);
    end;
} 
end)
__bundle_register("@src/universal_fallback", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Universal hub: same Rain UI library as the Deepwoken menu, game-agnostic only.
-- Tabs: Main (Movement), Visuals (ESP/World/Camera), UI (Themes/Configs/Menu).
-- Opens on any place outside the Deepwoken allowlist. No Deepwoken modules.
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UIS = game:GetService("UserInputService")
local Lighting = game:GetService("Lighting")
local LP = Players.LocalPlayer

local state = { fly = false, fly_speed = 120, speed = false, speed_val = 175,
    jump_power = 50, noclip = false, infjump = false, esp = false, esp_names = true,
    esp_dist = 1000, esp_enemies = false, fullbright = false,
    fov_on = false, fov = 70, zoom = false, jerk = false }
local bv = nil
local conns = {}
local esp_gui = nil
local saved_fov, saved_zoom = nil, nil

-- restore: jerk-off tool state (mirrors Jerk OFF.lua: u4 run-flag, t1 conns)
local jerk_tool = nil
local jerk_running = false
local jerk_conns = {}
local jerk_char_conn = nil

local function char() return LP.Character end
local function hrp() local c = char() return c and c:FindFirstChild("HumanoidRootPart") end
local function hum() local c = char() return c and c:FindFirstChildOfClass("Humanoid") end
local function same_team(a, b)
    local ok, r = pcall(function()
        return a.Team ~= nil and b.Team ~= nil and a.Team == b.Team
    end)
    return ok and r
end

local function physics_tick()
    local c, r, h = char(), hrp(), hum()
    -- restore: Deepwoken speed.lua — velocity-based, skipped while flying
    if state.speed and not state.fly and r and h then
        pcall(function()
            local dir = Vector3.zero
            if h.MoveDirection.Magnitude > 0 then dir = h.MoveDirection.Unit end
            r.AssemblyLinearVelocity *= Vector3.new(0, 1, 0)
            r.AssemblyLinearVelocity += dir * state.speed_val
        end)
    end
    -- restore: Deepwoken infinite_jump.lua — hold Space to rise
    if state.infjump and not state.fly and r
        and UIS:IsKeyDown(Enum.KeyCode.Space) and not UIS:GetFocusedTextBox() then
        pcall(function()
            r.AssemblyLinearVelocity *= Vector3.new(1, 0, 1)
            r.AssemblyLinearVelocity += Vector3.new(0, state.jump_power, 0)
        end)
    end
    if state.noclip and c then
        for _, p in ipairs(c:GetDescendants()) do
            if p:IsA("BasePart") and p.CanCollide then pcall(function() p.CanCollide = false end) end
        end
    end
    if state.fly and r then
        local cam = workspace.CurrentCamera
        if cam then
            local move = Vector3.zero
            if UIS:IsKeyDown(Enum.KeyCode.W) then move += Vector3.new(0, 0, -1) end
            if UIS:IsKeyDown(Enum.KeyCode.S) then move += Vector3.new(0, 0, 1) end
            if UIS:IsKeyDown(Enum.KeyCode.A) then move += Vector3.new(-1, 0, 0) end
            if UIS:IsKeyDown(Enum.KeyCode.D) then move += Vector3.new(1, 0, 0) end
            if UIS:IsKeyDown(Enum.KeyCode.Space) then move += Vector3.new(0, 1, 0) end
            if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then move += Vector3.new(0, -1, 0) end
            if move.Magnitude > 0 then move = move.Unit end
            if not bv or bv.Parent ~= r then
                pcall(function() if bv then bv:Destroy() end end)
                local b = Instance.new("BodyVelocity")
                b.MaxForce = Vector3.new(9e9, 9e9, 9e9)
                b.Parent = r
                bv = b
            end
            bv.Velocity = cam.CFrame:VectorToWorldSpace(move) * state.fly_speed
        end
    elseif bv then
        pcall(function() bv:Destroy() end)
        bv = nil
    end
    if state.fullbright then
        pcall(function()
            Lighting.Brightness = 2
            Lighting.ClockTime = 14
            Lighting.FogEnd = 100000
        end)
    end
    local cam = workspace.CurrentCamera
    if cam then
        if state.fov_on then
            if saved_fov == nil then saved_fov = cam.FieldOfView end
            pcall(function() cam.FieldOfView = state.fov end)
        elseif saved_fov ~= nil then
            pcall(function() cam.FieldOfView = saved_fov end)
            saved_fov = nil
        end
        if state.zoom then
            if saved_zoom == nil then
                saved_zoom = { cam.MaxZoomDistance, cam.MinZoomDistance }
            end
            pcall(function()
                cam.MaxZoomDistance = 1000
                cam.MinZoomDistance = 0.5
            end)
        elseif saved_zoom ~= nil then
            pcall(function()
                cam.MaxZoomDistance = saved_zoom[1]
                cam.MinZoomDistance = saved_zoom[2]
            end)
            saved_zoom = nil
        end
    end
end

local function esp_tick()
    if not esp_gui then return end
    if not state.esp then
        if #esp_gui:GetChildren() > 0 then esp_gui:ClearAllChildren() end
        return
    end
    local my_rp = hrp()
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character then
            local erp = p.Character:FindFirstChild("HumanoidRootPart")
            if erp then
                local dist = my_rp and (my_rp.Position - erp.Position).Magnitude or 0
                if dist > state.esp_dist then
                    local old1 = esp_gui:FindFirstChild(p.Name)
                    if old1 then old1:Destroy() end
                    local old2 = esp_gui:FindFirstChild(p.Name .. "_tag")
                    if old2 then old2:Destroy() end
                elseif not (state.esp_enemies and same_team(LP, p)) then
                    local box = esp_gui:FindFirstChild(p.Name)
                    if not box then
                        box = Instance.new("Highlight")
                        box.Name = p.Name
                        box.FillColor = Color3.fromRGB(8, 147, 201)
                        box.OutlineColor = Color3.fromRGB(8, 147, 201)
                        box.FillTransparency = 0.6
                        box.Adornee = p.Character
                        box.Parent = esp_gui
                    elseif box.Adornee ~= p.Character then
                        box.Adornee = p.Character
                    end
                    local tag = esp_gui:FindFirstChild(p.Name .. "_tag")
                    if state.esp_names then
                        if not tag then
                            tag = Instance.new("BillboardGui")
                            tag.Name = p.Name .. "_tag"
                            tag.Size = UDim2.new(0, 200, 0, 20)
                            tag.StudsOffset = Vector3.new(0, 3, 0)
                            tag.AlwaysOnTop = true
                            local lab = Instance.new("TextLabel")
                            lab.Size = UDim2.new(1, 0, 1, 0)
                            lab.BackgroundTransparency = 1
                            lab.Font = Enum.Font.GothamBold
                            lab.TextSize = 13
                            lab.TextColor3 = Color3.fromRGB(255, 255, 255)
                            lab.TextStrokeTransparency = 0.5
                            lab.Parent = tag
                            tag.Adornee = erp
                            tag.Parent = esp_gui
                        end
                        tag:FindFirstChildOfClass("TextLabel").Text =
                            p.DisplayName .. " (" .. tostring(math.floor(dist)) .. "m)"
                    elseif tag then
                        tag:Destroy()
                    end
                end
            end
        end
    end
    for _, o in ipairs(esp_gui:GetChildren()) do
        local base = o.Name:gsub("_tag$", "")
        local p = Players:FindFirstChild(base)
        if not p or not p.Character then o:Destroy() end
    end
end

-- restore: Jerk Off tool toggle (mirrors Jerk OFF.lua). ON gives the Tool and
-- wires equip/unequip + respawn; OFF stops tracks, drops the Tool, unwires.
local function jerk_anim_loop(anim_id, time_pos, threshold, slot)
    local c = char()
    local h = c and c:FindFirstChildOfClass("Humanoid")
    if not h then return end
    local anim = Instance.new("Animation")
    anim.AnimationId = "rbxassetid://" .. anim_id
    local track = nil
    pcall(function() track = h:LoadAnimation(anim) end)
    pcall(function() anim:Destroy() end)
    if not track then return end
    jerk_conns[slot] = RunService.RenderStepped:Connect(function()
        pcall(function()
            if not jerk_running then
                track:Stop()
            elseif track.TimePosition >= threshold or track.IsPlaying == false then
                track:Play()
                track.TimePosition = time_pos
            end
        end)
    end)
    pcall(function() track:Play() track.TimePosition = time_pos end)
end

local function jerk_start_anims()
    jerk_anim_loop("72042024", 0.5, 0.9, 1)
    jerk_anim_loop("168268306", 1, 1.001, 2)
    jerk_running = true
end

local function jerk_stop_anims()
    jerk_running = false
    for _, conn in pairs(jerk_conns) do pcall(function() conn:Disconnect() end) end
    table.clear(jerk_conns)
end

local function jerk_give_tool()
    local bp = LP:FindFirstChildOfClass("Backpack")
    if not bp then
        local ok, b = pcall(function() return LP:WaitForChild("Backpack", 5) end)
        if ok then bp = b else return nil end
    end
    local old = bp:FindFirstChild("Jerk Off")
    if old then pcall(function() old:Destroy() end) end
    local tool = Instance.new("Tool")
    tool.Name = "Jerk Off"
    tool.RequiresHandle = false
    tool.Parent = bp
    tool.Equipped:Connect(function() if state.jerk then jerk_start_anims() end end)
    tool.Unequipped:Connect(function() jerk_stop_anims() end)
    return tool
end

local function jerk_stop()
    jerk_stop_anims()
    if jerk_char_conn then
        pcall(function() jerk_char_conn:Disconnect() end)
        jerk_char_conn = nil
    end
    pcall(function()
        local bp = LP:FindFirstChildOfClass("Backpack")
        local t = bp and bp:FindFirstChild("Jerk Off")
        if t then t:Destroy() end
    end)
    jerk_tool = nil
end

local function jerk_start()
    jerk_stop()
    jerk_tool = jerk_give_tool()
    jerk_char_conn = LP.CharacterAdded:Connect(function()
        if not state.jerk then return end
        jerk_tool = jerk_give_tool()
    end)
end

local function unload_all()
    for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
    table.clear(conns)
    if bv then pcall(function() bv:Destroy() end) bv = nil end
    if esp_gui then pcall(function() esp_gui:Destroy() end) esp_gui = nil end
    jerk_stop()
    local Lib = getgenv().Library
    if Lib then
        pcall(function()
            local holder = Lib.PRWindow and Lib.PRWindow.Holder
            local sg = holder and holder:FindFirstAncestorOfClass("ScreenGui")
            if sg then sg:Destroy() end
        end)
    end
    -- restore: лог убран — print("[restore] universal hub unloaded")
end

return { start = function(place_id)
    require("@src/utility/librarys/ui")
    -- restore: keybind toggles need loaded_signal, which the Deepwoken boot
    -- creates after place routing — universal returns earlier, so make it here.
    if not getgenv().loaded_signal then
        local ok, sig = pcall(require, "@src/utility/signal")
        if ok and sig and sig.new then
            getgenv().loaded_signal = sig.new()
        end
    end
    local tab_mod = require("@src/utility/ui/wrapper")
    local Lib = getgenv().Library
    if not (Lib and Lib.PRWindow) then
        return nil
    end
    -- the UI lib instance must exist for Theme/Save managers
    env = getgenv()
    if env.aztup and not env.aztup.ui then
        env.aztup.ui = Lib
    end
    Lib.PRWindow:SetWindowTitle(string.format(
        'universal <font color="#%s">%s</font>', Lib.AccentColor:ToHex(), tostring(place_id)))

    -- Main / Movement
    local main = tab_mod.new("Main")
    local movement = main:newGroupBox("Movement")
    movement:newToggleWithKeybind("u_fly", "Fly", false, "lol, camera direction.",
        function(v)
            state.fly = v
            if not v and bv then pcall(function() bv:Destroy() end) bv = nil end
        end, true)
    movement:newSlider("u_fly_speed", "Fly Speed", 120, 20, 400, 0, true, "st/s",
        function(v) state.fly_speed = v end)
    movement:newToggleWithKeybind("u_speed", "WalkSpeed", false, "Velocity-based, like Deepwoken.",
        function(v) state.speed = v end, true)
    movement:newSlider("u_speed_val", "Speed Value", 175, 1, 250, 0, true, "st/s",
        function(v) state.speed_val = v end)
    movement:newToggleWithKeybind("u_noclip", "Noclip", false, "No collision.",
        function(v) state.noclip = v end, true)
    movement:newToggle("u_infjump", "Infinite Jump", false, "Hold Space to rise, like Deepwoken.",
        function(v) state.infjump = v end)
    movement:newSlider("u_jump_power", "Jump Power", 50, 1, 500, 0, true, "",
        function(v) state.jump_power = v end)

    local fun = main:newGroupBox("Fun")
    fun:newToggle("u_jerk", "Jerk", false, "Gives the Jerk Off tool; removing the toggle takes it back.",
        function(v)
            state.jerk = v
            if v then jerk_start() else jerk_stop() end
        end)

    -- Visuals
    local visuals = tab_mod.new("Visuals")
    local espbox = visuals:newGroupBox("ESP")
    espbox:newToggleWithKeybind("u_esp", "Player ESP", false, "Highlight players.",
        function(v) state.esp = v end, true)
    espbox:newToggle("u_esp_names", "Name Tags + Distance", true, "Billboard nametags.",
        function(v) state.esp_names = v end)
    espbox:newToggle("u_esp_enemies", "Enemies Only", false, "Hide teammates (where Teams exist).",
        function(v) state.esp_enemies = v end)
    espbox:newSlider("u_esp_dist", "ESP Max Distance", 1000, 50, 5000, 0, true, "st",
        function(v) state.esp_dist = v end)
    local world = visuals:newGroupBox("World")
    world:newToggle("u_fullbright", "FullBright", false, "Force daylight, no fog.",
        function(v) state.fullbright = v end)
    local camera = visuals:newGroupBox("Camera")
    camera:newToggle("u_fov_on", "Custom FOV", false, "Lock field of view.",
        function(v) state.fov_on = v end)
    camera:newSlider("u_fov", "FOV Value", 70, 30, 120, 0, true, "deg",
        function(v) state.fov = v end)
    camera:newToggle("u_zoom", "Infinite Zoom", false, "Zoom out up to 1000.",
        function(v) state.zoom = v end)

    -- UI tab: themes, configs, menu controls (same managers as Deepwoken menu)
    local uitab = tab_mod.new("UI")
    local ok_t, ThemeManager = pcall(require, "@src/utility/librarys/managers/ThemeManager")
    local ok_s, SaveManager = pcall(require, "@src/utility/librarys/managers/SaveManager")
    if ok_t and ThemeManager and ThemeManager.SetLibrary then
        pcall(function()
            ThemeManager:SetLibrary(Lib)
            ThemeManager:SetFolder("Project Rain/Universal-Config")
            ThemeManager:ApplyToTab(uitab.Tab)
        end)
    end
    if ok_s and SaveManager and SaveManager.BuildConfigSection then
        pcall(function()
            SaveManager:SetLibrary(Lib)
            SaveManager:IgnoreThemeSettings()
            SaveManager:SetFolder("Project Rain/Universal-Config")
            SaveManager:SetIgnoreIndexes({ "u_fly", "u_noclip", "u_speed", "u_infjump" })
            SaveManager:BuildConfigSection(uitab.Tab)
        end)
    end
    local menubox = uitab:newGroupBox("Menu")
    menubox:newButton("Unload Menu", function()
        unload_all()
    end, false, "Unloads the universal hub (all features off, UI destroyed).")

    local gui_parent = nil
    pcall(function()
        gui_parent = (typeof(gethui) == "function" and gethui()) or game:GetService("CoreGui")
    end)
    if not gui_parent then gui_parent = LP:WaitForChild("PlayerGui") end
    esp_gui = Instance.new("ScreenGui")
    esp_gui.Name = "RainUniversalESP"
    esp_gui.ResetOnSpawn = false
    esp_gui.Parent = gui_parent

    conns[#conns + 1] = RunService.PreSimulation:Connect(physics_tick)
    conns[#conns + 1] = RunService.Heartbeat:Connect(esp_tick)

    -- restore: same clickable banner as the Deepwoken menu (src/ui/menu_banner.lua)
    task.spawn(xpcall, function()
        require("@src/ui/menu_banner").initialize()
    end, warn)

    pcall(function()
        if Lib.Toggled ~= true then Lib:Toggle() end
    end)
    -- restore: лог убран — print("[restore] universal hub (Main/Visuals/UI) for place " .. tostring(place_id))
end }

end)
__bundle_register("@src/utility/asset_id", function(require, _LOADED, __bundle_register, __bundle_modules)









local AssetId = {}


local PROTOCOL = {
    UNKNOWN = 1,
    NULL = 2,
    RBXASSET = 3,
    RBXTEMP = 4,
    RBXASSETID = 5,
    ENCRYPTEDASSETID = 6,
    HTTP = 7,
    FILE = 8,
    RBXHTTP = 9,
    RBXAPP = 10,
    RBXTHUMB = 11,
    RBXGAMEASSET = 12,
    RBXASSETHASH = 13,
    RBXRUNTIME = 14,
}

AssetId.PROTOCOL = PROTOCOL



local function compare_eq(str: string, pos: number, len: number, s: string): boolean
    return string.sub(str, pos + 1, pos + len) == s
end



function AssetId.classify(str: string): number
    local len = #str

    if len == 0 then
        return PROTOCOL.NULL
    end

    if len < 10 then
        if len < 5 then
            return PROTOCOL.UNKNOWN
        end
    elseif compare_eq(str, 0, 3, "rbx") then
        local c = string.byte(str, 4)

        if c == 116 then 
            if compare_eq(str, 4, 6, "emp://") then
                return PROTOCOL.RBXTEMP
            end

            return compare_eq(str, 4, 7, "humb://") and PROTOCOL.RBXTHUMB or PROTOCOL.UNKNOWN
        end

        if c == 97 then 
            if compare_eq(str, 4, 11, "ssethash://") then
                return PROTOCOL.RBXASSETHASH
            elseif compare_eq(str, 4, 7, "sset://") then
                return PROTOCOL.RBXASSET
            elseif compare_eq(str, 4, 9, "ssetid://") then
                return PROTOCOL.RBXASSETID
            end

            return compare_eq(str, 4, 5, "pp://") and PROTOCOL.RBXAPP or PROTOCOL.UNKNOWN
        end

        if len < 23 then
            if len == 10 then
                return PROTOCOL.UNKNOWN
            end
        elseif compare_eq(str, 3, 19, "encryptedassetid://") then
            return PROTOCOL.ENCRYPTEDASSETID
        end

        if compare_eq(str, 3, 7, "http://") then
            return PROTOCOL.RBXHTTP
        end

        if len < 16 then
            if len < 14 then
                return PROTOCOL.UNKNOWN
            end
        elseif compare_eq(str, 3, 12, "gameasset://") then
            return PROTOCOL.RBXGAMEASSET
        end

        return compare_eq(str, 3, 10, "runtime://") and PROTOCOL.RBXRUNTIME or PROTOCOL.UNKNOWN
    end

    
    if compare_eq(str, 0, 4, "http") then
        return PROTOCOL.HTTP
    end

    if len >= 8 and compare_eq(str, 0, 7, "file://") then
        return PROTOCOL.FILE
    end

    return PROTOCOL.UNKNOWN
end



local function parse_id_at(str: string, offset: number): (string?, string?)
    if #str < offset + 1 then
        return nil, "<error:  missing assetid>"
    end

    local first = string.byte(str, offset + 1)
    if first < 48 or first > 57 then
        return nil, "<error:  assetid does not start with a number>"
    end

    
    local window = string.sub(str, offset + 1, offset + 19)
    local digits = string.match(window, "^[0-9]+") :: string

    return digits, nil
end


local function ascii_lower(str: string): string
    return (string.gsub(str, "[A-Z]", function(c: string)
        return string.char(string.byte(c) + 32)
    end))
end


function AssetId.get_id(str: string): (string?, string?)
    local protocol = AssetId.classify(str)

    if protocol == PROTOCOL.RBXASSETID then
        return parse_id_at(str, 13)
    end

    if protocol == PROTOCOL.HTTP or protocol == PROTOCOL.RBXHTTP then
        
        local head = ascii_lower(string.sub(str, 1, 128))
        local found = string.find(head, "id=", 1, true)

        if not found then
            return nil, "<error: id not found in first 128 char for http AssetId>"
        end

        return parse_id_at(head, (found - 1) + 3)
    end

    if protocol == PROTOCOL.FILE then
        return nil, "<error: file:// not allowed>"
    elseif protocol == PROTOCOL.RBXTEMP then
        return nil, "<error: rbxtemp:// not allowed>"
    elseif protocol == PROTOCOL.RBXASSET then
        return nil, "<error: rbxasset:// file not found>"
    elseif protocol == PROTOCOL.NULL then
        return nil, "<error: null id>"
    end

    return nil, "<error: unknown AssetId protocol>"
end


function AssetId.normalize(str: string): string
    local id, err = AssetId.get_id(str)
    return id and ("rbxassetid://" .. id) or (err :: string)
end

return AssetId

end)
__bundle_register("@src/utility/bindablefunction", function(require, _LOADED, __bundle_register, __bundle_modules)




export type Callback = (...any) -> ...any

export type BindableFunction = {
    _connect: RBXScriptConnection?,
    _target: any?,
    _method: Callback?,
    __call: (BindableFunction,...any) -> ...any,
    bind: (BindableFunction, target: any, method: Callback?) -> Callback,
    disconnect: (BindableFunction) -> (),
}

local BindableFunction = {}
BindableFunction.__index = BindableFunction

function BindableFunction.new(callback: Callback?)
    local self = setmetatable({
        _connect = nil,
        _target = nil,
        _method = callback,
    }, BindableFunction)

    return self
end





function BindableFunction:bind(target: any, method: Callback?): Callback
    self._target = target
    if method then
        self._method = method
    end

    local function boundCallback(...: any)
        if not self._method then
            return
        end
        return self._method(self._target, ...)
    end

    return boundCallback
end

function BindableFunction:__call(...: any): ...any
    if not self._method then
        return
    end
    return self._method(self._target, ...)
end

return BindableFunction
end)
__bundle_register("@src/utility/chunk_dumper", function(require, _LOADED, __bundle_register, __bundle_modules)
local Settings = {
	folder = "Project Rain/Dump",
	stealth = false,
	keepGoing = true,
	writeManifest = true,
	skipIfUnchanged = true,
	chunkCap = 200000,
	stopOnFirstError = false,
	hookLoad = true,
	hookGetgenvLoadstring = true,
	hookRequireString = true,
};

local state = {
	index = 0,
	entries = {},
	busy = false,
	dead = false,
};

local safeWrite = function(path, body)
	local ok, err = pcall(writefile, path, body);
	return ok, err;
end

local ensureFolder = function()
	local ok = pcall(function()
		if not isfolder(Settings.folder) then
			makefolder(Settings.folder);
		end;
	end);
	return ok;
end

local sanitize = function(s)
	s = tostring(s or "");
	s = s:gsub("[^%w_%-%. ]", "_");
	if #s == 0 then return "chunk" end;
	if #s > 80 then s = s:sub(1, 80) end;
	return s;
end

local hashOf = function(s)
	local h = 5381;
	local step = math.max(1, math.floor(#s / 512));
	local i = 1;
	local n = #s;
	while i <= n do
		h = (h * 33 + s:byte(i)) % 0xFFFFFFFF;
		i = i + step;
	end;
	return string.format("%08x", h);
end

local lastHash = {};

local extractName = function(chunk, nameArg)
	local candidate = nameArg;
	if type(candidate) ~= "string" or candidate == "" then
		local m = string.match(chunk, "%-%-%s*@module%s*%(?([^%)]+)%)?") or string.match(chunk, "%-%-%-%s*%[([^%]]+)%]");
		if m and m ~= "" then candidate = m end;
	end;
	if type(candidate) ~= "string" or candidate == "" then
		candidate = state.entries[#state.entries + 1] and state.entries[#state.entries].name or "chunk";
	end;
	return sanitize(candidate:gsub("^=", ""));
end

local record = function(chunk, nameArg, vector)
	if state.busy then return end;
	if type(chunk) ~= "string" then return end;
	if #chunk == 0 then return end;
	if #chunk > Settings.chunkCap then return end;
	if #chunk < 4 then return end;

	state.busy = true;
	pcall(function()
		state.index = state.index + 1;
		local id = state.index;
		local name = extractName(chunk, nameArg);
		local hash = hashOf(chunk);

		local entry = {
			i = id,
			name = name,
			len = #chunk,
			hash = hash,
			via = vector,
			file = nil,
		};

		if Settings.skipIfUnchanged and lastHash[hash] then
			entry.file = lastHash[hash];
			entry.dup = true;
		else
			ensureFolder();
			local fname = string.format("%04d_%s_%s.lua", id, name, hash);
			local path = Settings.folder .. "/" .. fname;
			local ok, err = safeWrite(path, chunk);
			if ok then
				entry.file = path;
				lastHash[hash] = path;
			else
				entry.err = tostring(err);
			end;
		end;

		state.entries[#state.entries + 1] = entry;

		if Settings.writeManifest then
			local lines = {};
			for _, e in ipairs(state.entries) do
				lines[#lines + 1] = string.format(
					"%04d  %-9s %-34s %-28s %s%s",
					e.i,
					tostring(e.len),
					e.name,
					tostring(e.via),
					tostring(e.file or ("ERR:" .. tostring(e.err))),
					e.dup and "  [dup]" or ""
				);
			end;
			safeWrite(Settings.folder .. "/_manifest.txt", table.concat(lines, "\n"));
		end;
	end);
	state.busy = false;
end

local makeHook = function(original, vector)
	return function(chunk, ...)
		local nameArg = select(2, ...);
		record(chunk, nameArg, vector);
		return original(chunk, ...);
	end;
end

local wrap = function(fn, vector)
	if type(fn) ~= "function" then return nil end;
	local proxy = makeHook(fn, vector);
	if type(newcclosure) == "function" then
		local ok, wrapped = pcall(newcclosure, proxy);
		if ok and type(wrapped) == "function" then return wrapped end;
	end;
	return proxy;
end;

local env = getgenv();
local saved = {
	loadstring = rawget(env, "loadstring"),
	load = rawget(env, "load"),
	require = type(require) == "function" and require or nil,
};

local installed = {};

local install = function(name, target, key)
	local original = rawget(env, name);
	if type(original) ~= "function" then return end;
	local wrapped = wrap(original, name);
	if not wrapped then return end;
	rawset(env, name, wrapped);
	installed[name] = { key = key, original = original };
end

install("loadstring", env, "loadstring");

if Settings.hookLoad and type(rawget(env, "load")) == "function" then
	install("load", env, "load");
end;

if Settings.hookGetgenvLoadstring then
	install("loadstring", env, "loadstring");
end;

if Settings.hookRequireString then
	local originalRequire = saved.require;
	if type(originalRequire) == "function" then
		local wrapped = wrap(originalRequire, "require");
		if wrapped then
			env.require = wrapped;
			installed.require = { key = "require", original = originalRequire };
		end;
	end;
end;

local Control = {};

function Control.stats()
	local total, bytes, dups = 0, 0, 0;
	for _, e in ipairs(state.entries) do
		total = total + 1;
		bytes = bytes + e.len;
		if e.dup then dups = dups + 1 end;
	end;
	return { total = total, bytes = bytes, dups = dups };
end

function Control.entries()
	return state.entries;
end

function Control.reset()
	state.entries = {};
	state.index = 0;
	lastHash = {};
end

function Control.stop()
	for name, data in pairs(installed) do
		pcall(function() rawset(env, name, data.original) end);
	end;
	installed = {};
	state.dead = true;
	return true;
end

function Control.resume()
	if not state.dead then return false end;
	state.dead = false;
	install("loadstring", env, "loadstring");
	if Settings.hookLoad then install("load", env, "load") end;
	if Settings.hookRequireString and saved.require then
		local wrapped = wrap(saved.require, "require");
		if wrapped then
			env.require = wrapped;
			installed.require = { key = "require", original = saved.require };
		end;
	end;
	return true;
end

function Control.settings()
	return Settings;
end

function Control.set(key, value)
	if Settings[key] == nil then return false end;
	Settings[key] = value;
	if key == "stealth" and value and getgenv().Library then
		pcall(function() getgenv().Library:Notify("Dump: stealth on", 3) end);
	end;
	return true;
end

function Control.manifest()
	ensureFolder();
	local lines = {};
	for _, e in ipairs(state.entries) do
		lines[#lines + 1] = string.format(
			"%04d  %-9s %-34s %-12s %s%s",
			e.i, tostring(e.len), e.name, tostring(e.via),
			tostring(e.file or ("ERR:" .. tostring(e.err))), e.dup and "  [dup]" or "");
	end;
	safeWrite(Settings.folder .. "/_manifest.txt", table.concat(lines, "\n"));
	return #lines;
end

env.RainDump = Control;

return Control
end)
__bundle_register("@src/utility/custom_font", function(require, _LOADED, __bundle_register, __bundle_modules)
local custom_font = {}




function custom_font.make_lexend_font()
    local font_custom_asset = getcustomasset("Project Rain/fonts/Lexend.ttf")
    local font_custom_asset_bold = getcustomasset("Project Rain/fonts/Lexend-Bold.ttf")
    local font_custom_asset_medium = getcustomasset("Project Rain/fonts/Lexend-Medium.ttf")

    writefile("Project Rain/fonts/Lexend.json", game:GetService("HttpService"):JSONEncode({
        name = "Lexend",
        faces = {
            {
                name = "Regular",
                weight = 400,      
                style = "normal",
                assetId = font_custom_asset
            },
            {
                name = "Medium",
                weight = 500,
                style = "normal",
                assetId = font_custom_asset_medium
            },
            {
                name = "Bold",
                weight = 700,
                style = "normal",
                assetId = font_custom_asset_bold
            }
        }
    }))

    local path_asset = getcustomasset("Project Rain/fonts/Lexend.json");
    local fonts = {
        regular = Font.new(
            path_asset,
            Enum.FontWeight.Regular,
            Enum.FontStyle.Normal
        ),
        medium = Font.new(
            path_asset,
            Enum.FontWeight.Medium,
            Enum.FontStyle.Normal
        ),
        bold = Font.new(
            path_asset,
            Enum.FontWeight.Bold,
            Enum.FontStyle.Normal
        )
    };

    
    
    local done = 0;
    for _, font in pairs(fonts) do
        task.spawn(function()
            local params = Instance.new("GetTextBoundsParams")
            params.Text = "Preload"
            params.Font = font
            params.Size = 16
            game:GetService("TextService"):GetTextBoundsAsync(params)
            params:Destroy()
            done += 1;
        end)
    end

    repeat task.wait() until done == 3;
    return fonts
end

return custom_font.make_lexend_font()
end)
__bundle_register("@src/utility/deepwoken/action_tracker", function(require, _LOADED, __bundle_register, __bundle_modules)
local tracker = {};
tracker.__index = tracker;

-- restore: resolve the LIVE EffectReplicator at call time. The boot stub is
-- replaced by the real game module after replication; chunks may hold a stale
-- global snapshot, so never use the load-time global directly.
local function live_er()
    local gg = (typeof(getgenv) == "function" and getgenv()) or _G
    local er = gg and gg.EffectReplicator or nil
    if type(er) == "table" then return er end
    return EffectReplicator
end

function tracker:can_parry()
	local er = live_er()
	if not er:FindEffect("Equipped") then
		return false
	end

	return not er:FindEffect("ParryCool")
end


function tracker:can_dodge()
	local er = live_er()
	if er:HasAny("NoRoll", "PreventRoll", "Stun") then
		return false
	end

	return true
end

function tracker:activate_request(mantra)
	self.on_mantra_request:Fire(mantra);
end

function tracker.new(player_data)
    local self = setmetatable({}, tracker);
	self.on_mantra_request = Instance.new("BindableEvent");
	self.last_equip_call = false;

	player_data.character_added:connect(function()
		tracker.last_equip_call = false;
	end);

    return self
end

return tracker
end)
