__bundle_register("@src/utility/deepwoken/effect_replicator_handler", function(require, _LOADED, __bundle_register, __bundle_modules)






if not getloadedmodules then
    return game:GetService(STR_TBL_SF_INVOKE("Players")).LocalPlayer:Kick(STR_TBL_SF_INVOKE("Executor is unsupported. [missing getloadedmodules, effect_replicator_handler]"))
end;


local Maid = require("@src/utility/maid");
local EffectReplicatorHandler = {};
EffectReplicatorHandler.__index = EffectReplicatorHandler;
EffectReplicatorHandler.hooks = {};
EffectReplicatorHandler.maid = Maid.new();

function EffectReplicatorHandler:hook(type, func)
    local hook = {};
    function hook:remove()
        table.remove(EffectReplicatorHandler.hooks, self.index);
    end; 

    hook.type = type;
    hook.call = func;
    hook.index = table.insert(EffectReplicatorHandler.hooks, hook);

    return hook
end;

function EffectReplicatorHandler:connect()
    self.maid:do_cleaning();

    local RawEffectReplicator = game:GetService("ReplicatedStorage"):WaitForChild("EffectReplicator");
    if not table.find(getloadedmodules(), RawEffectReplicator) then
        -- restore: warn() стоял в repeat с task.wait(0.06) — печатал ~16 раз в
    -- секунду, пока модуль не найдётся. Убран полностью.
    repeat task.wait(0.06) until table.find(getloadedmodules(), RawEffectReplicator);
    end;
    local EffectReplicator = base_require(game:GetService("ReplicatedStorage"):WaitForChild("EffectReplicator"));
    getgenv().EffectReplicator = EffectReplicator;

    self.maid:give_task(EffectReplicator.EffectAdded:Connect(function(effect)
        setthreadidentity(8);
        for _, hook in pairs(EffectReplicatorHandler.hooks) do
            if hook.type == "added" and hook.call then
                task.spawn(xpcall, function()
                    hook.call(effect);
                end, function(err)
                    -- restore: лог убран — Logger.error(string.format("effectreplicator added hook: %s", err))
                end);
            end;
        end;
    end));
    
    self.maid:give_task(EffectReplicator.EffectRemoved:Connect(function(effect)
        for _, hook in pairs(EffectReplicatorHandler.hooks) do
            if hook.type == "removed" then
                xpcall(function()
                    hook.call(effect);
                end, function(err) 
                    -- restore: лог убран — Logger.error(string.format("effectreplicator removed hook: %s", err))
                end);
            end;
        end;  
    end));
end;

task.spawn(pcall, function()
    while not pcall(function() aztup.maid:give_task(EffectReplicatorHandler.maid); end) do task.wait() end;
end);

task.spawn(pcall, function()
    local update = game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("EffectReplication"):WaitForChild("_update");
    update.OnClientEvent:Connect(function(effect)
        if effect.updateType == "clear" or effect.updateType == "updatecontainer" then
            EffectReplicatorHandler:connect();  
        end;
    end);

    EffectReplicatorHandler:connect();
end);
return EffectReplicatorHandler
end)
__bundle_register("@src/utility/deepwoken/general_utilitys", function(require, _LOADED, __bundle_register, __bundle_modules)


local general = {}; 
local collision_utils = base_require(game:GetService("ReplicatedStorage"):WaitForChild("Modules"):WaitForChild("CollisionUtils"));
general.collision_utils = collision_utils;

function general:in_air()
    local sensor = local_player.root_part:FindFirstChild("GroundSensor");
    if EffectReplicator:HasEffect("Swimming") then
        return false    
elseif EffectReplicator:HasEffect("AirBorne") then
        return true    
elseif sensor and not sensor.SensedPart then
        if not collision_utils.solidParams then return false end
        return not collision_utils:Raycast(local_player.root_part.Position, Vector3.new(0, -(sensor.SearchDistance + 3), 0), collision_utils.solidParams)    
end

    return false
end;

function general:get_highest_point(x: number, z: number)
    local filter = {};
    local live = workspace:FindFirstChild("Live");
    local npcs = workspace:FindFirstChild("NPCs");
    if live then table.insert(filter, live); end
    if npcs then table.insert(filter, npcs); end

    local params = RaycastParams.new()
    params.FilterDescendantsInstances = filter
    params.FilterType = Enum.RaycastFilterType.Blacklist

    local floor = workspace:Raycast(Vector3.new(x, 5000, z), Vector3.new(0, -10000, 0), params);
    if floor and floor.Instance then
        return floor.Position.Y + 1.3    
end;

    local holder_sea = workspace:FindFirstChild("HolderSea", true);
    if holder_sea then
        return holder_sea.Position.Y + 1.3    
end;

    return 50000
end;

function general:is_teammate(player)
    local myGuild = local_player.instance:GetAttribute('Guild') or '';
    local playerGuild = player:GetAttribute('Guild') or '';
    if myGuild == '' then return end

    return myGuild == playerGuild
end;

local current_boxes = {};

local function trim_boxes()
    local max_boxes = (aztup and aztup.flags and aztup.flags.max_boxes) or 0
    if max_boxes <= 0 then return end
    while #current_boxes > max_boxes do
        local pair = table.remove(current_boxes, 1)
        if pair then
            for _, part in pair do
                if part and part.Parent then
                    part:Destroy()
                end
            end
        end
    end
end
local function draw_hitbox(hitbox: Vector3, root_pos: CFrame, enemy_pos: CFrame, offset: CFrame, is_ball: boolean?, ok: boolean, too_far: boolean, hidden: boolean?, hit_color: Color3?, miss_color: Color3?)
    local camera: Camera = workspace.CurrentCamera or {Position = Vector3.zero};
    if (enemy_pos.Position - camera.CFrame.Position).Magnitude > 300 then
        return
    end

    trim_boxes()

    local fake_root = nil
    if ok then
        fake_root = Instance.new("Part")
        fake_root.Size = Vector3.new(2, 2, 1)
        fake_root.CFrame = root_pos
        fake_root.Anchored = true
        fake_root.CanCollide = false
        fake_root.Material = Enum.Material.ForceField
        fake_root.CastShadow = false
    end

    local hitbox_part = Instance.new("Part")
    hitbox_part.Size = hitbox
    hitbox_part.CFrame = enemy_pos * (offset or CFrame.new())
    hitbox_part.Anchored = true
    hitbox_part.CanCollide = false
    hitbox_part.Material = Enum.Material.ForceField
    hitbox_part.Shape = is_ball and Enum.PartType.Ball or Enum.PartType.Block
    hitbox_part.CastShadow = false

    if fake_root then
        table.insert(current_boxes, { hitbox_part, fake_root })
    else
        table.insert(current_boxes, { hitbox_part })
    end

    local trans = 1 - (((aztup and aztup.flags and aztup.flags.hb_trans) or 0) / 100)
    hitbox_part.Transparency = trans
    if fake_root then
        fake_root.Transparency = trans
    end

    hitbox_part.Parent = workspace
    if fake_root then
        fake_root.Parent = workspace
    end

    local lifetime = (hidden or not aztup.flags.view_hitboxes or too_far) and 0 or 1
    services.Debris:AddItem(hitbox_part, lifetime)
    if fake_root then
        services.Debris:AddItem(fake_root, lifetime)
    end

    hitbox_part.Color = ok and (hit_color or Color3.new(0, 1, 0)) or (miss_color or Color3.new(1, 0, 0))
    if fake_root then
        fake_root.Color = hit_color or Color3.new(0, 1, 0)
    end

    if hidden or not aztup.flags.view_hitboxes or too_far then
        hitbox_part.Transparency = 1
        if fake_root then
            fake_root.Transparency = 1
        end
    else
        services.TweenService:Create(hitbox_part, TweenInfo.new(1), { Transparency = 1 }):Play()
        if fake_root then
            services.TweenService:Create(fake_root, TweenInfo.new(1), { Transparency = 1 }):Play()
        end
    end
end

function general:in_hitbox_with_pos(root_pos: CFrame, enemy_pos: CFrame, hitbox: Vector3, offset: CFrame, hidden: boolean?, is_ball: boolean?, hit_color: Color3?, miss_color: Color3?)  
    local too_far = false
    if local_player and local_player.root_part then
        too_far = (root_pos.Position - local_player.root_part.Position).Magnitude > 200
    end

    if (root_pos.Position - local_player.root_part.Position).Magnitude > (200 + (hitbox.Magnitude * 2)) then
        return false
    end

    local ok = false
    if is_ball then
        local probe = Instance.new("Part")
        probe.Size = hitbox
        probe.CFrame = enemy_pos * (offset or CFrame.new())
        probe.Anchored = true
        probe.Shape = Enum.PartType.Ball
        probe.CanCollide = false
        probe.Transparency = 1
        probe.CanQuery = true
        probe.Parent = workspace

        local overlap = OverlapParams.new()
        overlap.FilterType = Enum.RaycastFilterType.Include
        overlap.FilterDescendantsInstances = { 
            (function()
                local pr = Instance.new("Part")
                pr.Size = Vector3.new(2, 2, 1)
                pr.CFrame = root_pos
                pr.Anchored = true
                pr.CanCollide = false
                pr.Transparency = 1
                pr.CanQuery = true
                pr.Parent = workspace
                return pr
            end)()
        }

        local parts = services.Workspace:GetPartsInPart(probe, overlap)
        ok = #parts > 0

        
        for _, inst in overlap.FilterDescendantsInstances do
            inst:Destroy()
        end
        probe:Destroy()
    else

        local root_probe = Instance.new("Part")
        root_probe.Size = Vector3.new(2, 2, 1)
        root_probe.CFrame = root_pos
        root_probe.Anchored = true
        root_probe.CanCollide = false
        root_probe.Transparency = 1
        root_probe.CanQuery = true
        root_probe.Parent = workspace

        local overlap = OverlapParams.new()
        overlap.FilterType = Enum.RaycastFilterType.Include
        overlap.FilterDescendantsInstances = { root_probe }

        local parts = services.Workspace:GetPartBoundsInBox(enemy_pos * (offset or CFrame.new()), hitbox, overlap)
        ok = #parts > 0

        services.Debris:AddItem(root_probe, 0);
    end

    
    if aztup and aztup.flags and aztup.flags.view_hitboxes and not hidden and not too_far then
        draw_hitbox(hitbox, root_pos, enemy_pos, offset, is_ball, ok, too_far, hidden, hit_color, miss_color)
    end

    return ok
end
function general:in_hitbox(
    a: any,
    b: any,
    c: any,
    d: any,
    e: any?,
    f: any?
)
    
    
    
    
    

    local hitbox: Vector3
    local offset: CFrame
    local root_pos: CFrame
    local enemy_pos: CFrame
    local hidden: boolean?
    local is_ball: boolean? 

    if typeof(a) == "Vector3" and typeof(b) == "CFrame" then
        
        hitbox = a
        offset = b
        root_pos = c
        enemy_pos = d
        hidden = e
        is_ball = f
    else
        
        root_pos = a
        enemy_pos = b
        hitbox = c
        offset = d
        local show = e

        
        
        hidden = (show == false)
        is_ball = nil
    end

    return self:in_hitbox_with_pos(root_pos, enemy_pos, hitbox, offset, hidden, is_ball)
end;

function general:is_ap_anim(id)
    local data;
    for _, timing in timings do
        if timing.ids and table.find(timing.ids, tostring(id:match("%d+"))) then
            data = timing;
        end;
    end;   

    return data ~= nil
end;

function general:playing_ap_anims(entity, ids)
    for _, track in entity.Humanoid:GetPlayingAnimationTracks() do
        if ids then
            if table.find(ids, track.Animation.AnimationId) then
                continue            
end;
        end

        local data;
        for _, timing in timings do
            if timing.ids and table.find(timing.ids, tostring(track.Animation.AnimationId:match("%d+"))) then
                data = timing;
            end;
        end;   
        
        if data then
            return true        
end;
    end;

    return false
end;

local Keybinds = base_require(game:GetService("ReplicatedStorage"):WaitForChild("KeyBinds"..""));
function general:generic_parry_ap_task(entity: Model)
    if aztup_options.filters.Value["Dont Parry If Holding Block"] and Keybinds.IsActionHeld("Block") then
        return pcall(function()
            setthreadidentity(8);
            Logger:notify_sound("Holding F.");
        end)    
end;

    DefendActionManager:queue_generic_parry_task(entity);
end;

function general:raw_is_holding_f()
    return Keybinds.IsActionHeld("Block")
end;

function general:is_holding_f()
    return aztup_options.filters.Value["Dont Parry If Holding Block"] and Keybinds.IsActionHeld("Block")
end;

general.friends = {};
function general:is_friends_with_sync(plr)
    return general.friends[plr.UserId]
end

task.spawn(function() 
    for _, plr in services.Players:GetPlayers() do
        pcall(function() 
            local is_friends = local_player.instance:IsFriendsWithAsync(plr.UserId);
            if is_friends then
                general.friends[plr.UserId] = local_player.instance:IsFriendsWithAsync(plr.UserId);
            end;
        end)
    end

    services.Players.PlayerAdded:Connect(function(plr)
        if general.friends[plr.UserId] ~= nil then return end

        local is_friends = local_player.instance:IsFriendsWithAsync(plr.UserId);
        if not is_friends then return end

        general.friends[plr.UserId] = local_player.instance:IsFriendsWithAsync(plr.UserId);
    end);
end)

return general
end)
__bundle_register("@src/utility/deepwoken/safe_tween", function(require, _LOADED, __bundle_register, __bundle_modules)

local safeNAN;
safeNAN = function(v369)  
    
    if v369 == v369 then
        return v369    
elseif typeof(v369) == "Vector3" then
        local l_v369_0 = v369;
        return (Vector3.new(safeNAN(l_v369_0.X), safeNAN(l_v369_0.Y), safeNAN(l_v369_0.Z)))    
elseif typeof(v369) == "CFrame" then
        local l_v369_1 = v369;
        local v372 = safeNAN(l_v369_1.Position);
        local l_Rotation_0 = l_v369_1.Rotation;
        if l_Rotation_0 ~= l_Rotation_0 then
            l_Rotation_0 = CFrame.identity;
        end;
        return CFrame.new(v372) * l_Rotation_0    
elseif typeof(v369) == "number" then
        return v369 == v369 and v369 or 0    
else
        return v369    
end;
end;

local last_lagback = 0;
local threads = {};
return {
    new = function(target_cframe, ping_based, speed)
        speed = speed or 190

        if aztup.flags.force_tween_speed then
            speed = aztup.flags.force_tween_speed_value;
        end;

        if aztup.flags.force_no_tween_ping_comp then
            ping_based = false;
        end;

        local target_cframe = target_cframe

        local conn
        conn = services.RunService.PreSimulation:Connect(function(dt)
            if not local_player or not local_player.root_part then
                return
            end

            local target_pos = typeof(target_cframe) == "function" and target_cframe().Position or target_cframe.Position

            local root = local_player.root_part
            local current_pos = root.Position
            local offset = target_pos - current_pos
            local distance = offset.Magnitude

            if distance <= 0.01 or distance ~= distance then
                return
            end

            if target_pos.Magnitude >= 1000000 then
                if conn then
                    conn:Disconnect()
                    conn = nil
                end

                return            
end;

            local_player.root_part.AssemblyLinearVelocity = Vector3.zero
            local_player.root_part.CFrame = CFrame.new(root.CFrame.X, target_pos.Y, root.CFrame.Z)

            local dir = offset.Unit
            local move_speed = ping_based and speed * math.max(0.6, 1 - Latency:get_ping()) or speed
            
            local root_attachment = local_player.root_part:FindFirstChild("RootAttachment");
            local align_position = root_attachment and root_attachment:FindFirstChild("AlignPosition");
            if align_position then
                
                last_lagback = tick();
            end

            if tick() - last_lagback < 1 then
                move_speed = math.min(80, move_speed * 0.75);
            end;

            local step = move_speed * dt

            if step > distance then
                step = distance
            end

            if offset.Magnitude <= 0.01 then
                return
            end

            if not aztup.flags.dont_fly_on_tween then
                root.Velocity = Vector3.zero;
            end;
            
            root.CFrame = safeNAN(root.CFrame + safeNAN(dir * step))
        end)


        table.insert(threads, {
            task = task.spawn(function()
                if not local_player or not local_player.root_part then
                    return
                end
                local root = local_player.root_part
                while ((typeof(target_cframe) == "function" and target_cframe().Position or target_cframe.Position) - root.Position).Magnitude > 10 do
                    task.wait()
                end

                root.CFrame = typeof(target_cframe) == "function" and target_cframe() or target_cframe

                if conn then
                    conn:Disconnect()
                    conn = nil
                end
            end),
            conn = conn
        })

        return {
            stop = function()
                if conn then
                    conn:Disconnect()
                    conn = nil
                end
            end,
            wait = function()
                if not local_player or not local_player.root_part then
                    return
                end

                local root = local_player.root_part

                while ((typeof(target_cframe) == "function" and target_cframe().Position or target_cframe.Position) - root.Position).Magnitude > 10 do
                    task.wait()
                end
            end,
        }
    end,
    stop_all = function()
        for _, thread in threads do
            if thread.conn then
                thread.conn:Disconnect();
            end;

            if thread.task then
                pcall(task.cancel, thread.task);
            end;
        end;

        table.clear(threads);
    end,
    register_lagback = function()
        last_lagback = tick();
    end
}
end)
__bundle_register("@src/utility/deepwoken/servers", function(require, _LOADED, __bundle_register, __bundle_modules)
local servers = {};

local function decode_asset(asset)
    local decoded = services.EncodingService:Base64Decode(buffer.fromstring(asset));
    local decompress = services.EncodingService:DecompressBuffer(decoded, Enum.CompressionAlgorithm.Zstd);
    return buffer.tostring(decompress)
end;

local hop_script = inline_asset_b96("@assets/hopper.lua");

function kick_window(message)
    task.spawn(pcall, function()
        local_player.instance:Kick("Serverhopping...");
        task.wait();
        
        local roblox_prompt_gui = services.CoreGui:FindFirstChild("RobloxPromptGui")
        if not roblox_prompt_gui then
            return
        end
    
        roblox_prompt_gui.promptOverlay.ErrorPrompt.TitleFrame.ErrorTitle.TextColor3 = Color3.fromRGB(125, 196, 228)
        roblox_prompt_gui.promptOverlay.ErrorPrompt.TitleFrame.ErrorTitle.Text = "Project Rain"
        roblox_prompt_gui.promptOverlay.ErrorPrompt.MessageArea.ErrorFrame.ErrorMessage.Text = message
    end);
    while task.wait() do
        game:GetService("TeleportService"):Teleport(4111023553);
    end;
end;

return { 
    hop = function(_, slot, small, do_sound, expiry)
        local hop_script = string.format(hop_script, slot or "A", small ~= nil and tostring(small) or 'false', tostring(do_sound), 'false')

        if game.PlaceId ~= 4111023553 then 
            xpcall(function()
                local blacklisted_servers = isfile("Project Rain/hopper blacklisted servers.json") and game:GetService("HttpService"):JSONDecode(readfile("Project Rain/hopper blacklisted servers.json")) or {};
                
                for id, server in blacklisted_servers do
                    if server.expiry < tick() then
                        blacklisted_servers[id] = nil;
                    end;
                end;

                local function blacklist(server, expiry)
                    blacklisted_servers[server] = {
                        expiry = tick() + (expiry or 900)
                    }
                
                    writefile("Project Rain/hopper blacklisted servers.json", game:GetService("HttpService"):JSONEncode(blacklisted_servers));
                end;

                blacklist(game.JobId, expiry or (10 * 60))
            end, warn);

            writefile("hopper.lua", hop_script);
            queue_on_teleport(hop_script);
            kick_window("Serverhopping...");
        end;
    end,
    rejoin = function(self, slot)
        self:custom(slot, game.JobId);
    end,
    custom = function(_, slot, id)
        local rejoin_script = string.format([[
        if not game:IsLoaded() then
            game.Loaded:Wait();
        end;
        if game.PlaceId ~= 4111023553 then return; end
        local server = '%s';
        local slot = "%s";

        queueonteleport('if game.PlaceId == 4111023553 then return; end; xpcall(function() local sound = Instance.new("Sound", game:GetService("CoreGui")); game:GetService("Debris"):AddItem(sound, 6); sound.Volume = 1.3; sound.SoundId = getcustomasset("Project Rain/assets/notification.mp3"); sound:Play(); end, warn);')

        while task.wait() do
            game:GetService("ReplicatedStorage").Requests:WaitForChild("StartMenu"):WaitForChild("PickSlot"):FireServer(slot, {
                PrivateTest = false
            });
            task.wait(0.3);
            game:GetService("ReplicatedStorage").Requests.StartMenu:WaitForChild("PickServer"):FireServer(server);
        end;
        ]], id, slot or "A");
        if game.PlaceId ~= 4111023553 then  
            queue_on_teleport(rejoin_script); 
            
            kick_window("rejoining...")
            return        
else
            return -- restore: был print("cant be called here") в рантайм-ветке
        end;
    end,
    obliteration = function(_, slot, small, sound)
        local obl_script = string.format(hop_script, slot or "A", small ~= nil and tostring(small) or 'false', tostring(sound), 'true')
        if game.PlaceId ~= 4111023553 then 
            queue_on_teleport(obl_script);
            kick_window("wiping...");
            return        
else
            return -- restore: см. выше
        end;
    end,
    quick_hop = function(self)
        self:hop(local_player.instance:GetAttribute("DataSlot") or "A", 'false', 'false')
    end;
}
end)
__bundle_register("@src/utility/deepwoken/ssv_parser", function(require, _LOADED, __bundle_register, __bundle_modules)

local passive_parser = {} do 
    passive_parser.__index = passive_parser;
    function passive_parser.parse(character)
        local self = setmetatable({}, passive_parser);
        self.passives = EffectReplicator.Passives;
        self.character = character;

        return self    
end;
    
    function passive_parser:get_passive(index)
        if not self.passives then return nil end;
        return self.passives[index]    
end;

    function passive_parser:get_all_passives()
        if not self.passives then return {}end;
        return self.passives    
end;

    function passive_parser:add_passive(new_passive)
        EffectReplicator.Passives[new_passive] = true;
    end;

    function passive_parser:remove_passive(passive_to_remove)
        if not self.passives then return end;
        local had = EffectReplicator.Passives[passive_to_remove];
        EffectReplicator.Passives[passive_to_remove] = nil;

        return had    
end;

    function passive_parser:save()
    end;

    function passive_parser:destroy()
        self.character = nil;
        self.passives = nil;
        self = nil;
    end;
end;

return passive_parser
end)
__bundle_register("@src/utility/dumper", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Dumper. Инструмент для проверки собственного анти-дампера.
--
-- Собран так, чтобы закрыть все стандартные пути, которыми сливают игру:
--   Instances — обход дерева Instance (workspace / ReplicatedStorage / Players)
--   Modules   — все ModuleScript + их исходник (включая те, что видны только
--               через require-кэш, а не через дерево)
--   GC        — getgc(): функции, таблицы, upvalue, с источником и аргументами
--   Tables    — глубокий дамп выбранной таблицы с защитой от циклов
--   Upvalues  — разбор closure: что функция держит вверх
--
-- Почему так много: анти-дамп, который ловит только обход дерева, обходится
-- за секунду через getgc или через require-кэш. Проверять надо каждый канал.
--
-- STEALTH. Дампер по умолению прячет свои функции от getgc и свои инстансы
-- от обхода дерева: подменяет поля метатаблицы под setreadonly и уводит
-- свои GUI-объекты в скрытый контейнер. Именно в этом режиме проверяется,
-- видно ли дампер вообще.

local dumper = {}

local gui, frame;
local running = false;
local last_result = {};   -- id -> текст дампа
local active_tab = "Instances";

-- скрытые контейнеры для stealth
local stealth_mount = nil;

------------------------------------------------------------------ утилиты

local function txt(n)
    if type(n) == "string" then return n end;
    return tostring(n);
end

local function short(v, maxLen)
    local s
    if type(v) == "string" then s = string.format("%q", v)
    else s = tostring(v) end;
    if #s > (maxLen or 60) then s = s:sub(1, maxLen or 60) .. "..." end;
    return s;
end

local function fullname(inst)
    local ok, s = pcall(function() return inst:GetFullName() end);
    if ok and s then return s end;
    return "?" .. " " .. txt(inst.Name);
end

--- Исходник функции/скрипта. Несколько путей, потому что у исполнителей
--- они ведут себя по-разному.
local function source_of(f)
    if type(f) ~= "function" then return nil, nil end;

    if type(getsource) == "function" then
        local ok, s = pcall(getsource, f);
        if ok and type(s) == "string" and #s > 0 then return s, true end;
    end;

    if type(debug) == "table" and type(debug.info) == "function" then
        local ok, s = pcall(debug.info, f, "s");
        if ok and type(s) == "string" and #s > 0 then
            -- у inline-кусков s = "=name", настоящий исходник не отдаётся
            if s:sub(1, 1) ~= "=" then return s, true end;
        end;
    end;

    if type(debug) == "table" and type(debug.getinfo) == "function" then
        local ok, info = pcall(debug.getinfo, f, "S");
        if ok and info and type(info.source) == "string" and info.source:sub(1, 1) ~= "=" then
            return info.source, false;
        end;
    end;

    return nil, false;
end

------------------------------------------------------------------ Instances

--- Обход дерева Instance. limit по узлам — чтобы не утащить полную карту
--- на 300k объектов и не положить клиент.
function dumper.dumpInstances(roots, limit)
    local out = {}
    limit = limit or 60000;
    local queue = {};
    local seen = {};

    for _, r in ipairs(roots) do queue[#queue + 1] = { inst = r, depth = 0 } end;

    local n = 0;
    while #queue > 0 and n < limit do
        local node = table.remove(queue, 1);
        local inst = node.inst;
        if typeof(inst) == "Instance" and not seen[inst] then
            seen[inst] = true;
            n = n + 1;
            out[#out + 1] = string.format("%s%s [%s]", string.rep("  ", node.depth),
                inst.Name, inst.ClassName);
            local ok = pcall(function()
                for _, child in ipairs(inst:GetChildren()) do
                    queue[#queue + 1] = { inst = child, depth = node.depth + 1 };
                end;
            end);
        end;
    end;

    out[#out + 1] = "";
    out[#out + 1] = string.format("всего: %d узлов (лимит %d)", n, limit);
    return table.concat(out, "\n");
end

------------------------------------------------------------------ Modules

--- Все ModuleScript'ы: и через дерево, и через require-кэш.
--- Второй источник важен: модуль, который уже require'нули, в дереве
--- виден, но иногда его прячут — require-кэш его выдаст.
function dumper.dumpModules(root, limit)
    local out = {};
    limit = limit or 5000;
    local seen = {};
    local count = 0;

    local function push(inst, viaTree)
        if count >= limit then return end;
        if typeof(inst) ~= "Instance" or seen[inst] then return end;
        if not inst:IsA("ModuleScript") then return end;
        seen[inst] = true;
        count = count + 1;

        local src = "";
        if type(require) == "function" then
            local ok, mod = pcall(require, inst);
            if ok and type(mod) == "table" then
                src = "require -> table(" .. table.concat(table.keys(mod), ",") .. ")";
            elseif ok then
                src = "require -> " .. type(mod);
            else
                src = "require error: " .. short(mod, 80);
            end;
        end;

        out[#out + 1] = string.format("[%s] %s%s", viaTree and "tree" or "cache",
            inst.Name, inst.Parent and (" -> " .. inst.Parent.Name) or "");
        out[#out + 1] = "    " .. src;
    end;

    -- 1) дерево
    for _, inst in ipairs(root:GetDescendants()) do
        pcall(push, inst, true);
    end;

    -- 2) require-кэш: иногда достаёт то, чего в дереве не видно
    if type(getgenv) == "function" then
        local cache = getgenv().package and getgenv().package.loaded;
        if type(cache) == "table" then
            local extra = 0;
            for k in pairs(cache) do
                if type(k) == "Instance" and k:IsA("ModuleScript") then
                    if not seen[k] then
                        extra = extra + 1;
                        pcall(push, k, false);
                    end;
                end;
            end;
            if extra > 0 then
                out[#out + 1] = "";
                out[#out + 1] = "из require-кэша дополнительно: " .. extra;
            end;
        end;
    end;

    out[#out + 1] = "";
    out[#out + 1] = string.format("всего модулей: %d (лимит %d)", count, limit);
    return table.concat(out, "\n");
end

------------------------------------------------------------------ GC

--- Разбор getgc(). Для каждой функции — source и сколько upvalue.
--- Именно это выдаёт чужой скрипт: его замыкания и таблицы.
function dumper.dumpGC(limit)
    local out = {};
    limit = limit or 4000;

    if type(getgc) ~= "function" then
        return "getgc недоступен на этом исполнителе";
    end;

    local ok, items = pcall(getgc, true);
    if not ok or type(items) ~= "table" then
        return "getgc вернул ошибку: " .. short(items, 80);
    end;

    -- "function" и "table" — зарезервированные слова, без кавычек не ключ
    local counts = { ["function"] = 0, ["table"] = 0, thread = 0, userdata = 0, other = 0 };
    local entries = {};

    for _, o in ipairs(items) do
        local t = typeof(o);
        counts[t] = (counts[t] or 0) + 1;

        if t == "function" then
            local src, real = source_of(o);
            local upv = 0;
            if type(debug) == "table" and type(debug.getupvalues) == "function" then
                local uok, list = pcall(debug.getupvalues, o);
                if uok and type(list) == "table" then
                    upv = #list;
                    -- имена upvalue часто и есть главный след
                    local names = {};
                    for _, u in ipairs(list) do
                        names[#names + 1] = tostring(u.name or "?") .. "=" .. typeof(u.value);
                    end;
                    if #names > 0 then
                        entries[#entries + 1] = string.format(
                            "fn upv=%d  %s  |  %s", upv, short(src, 40), table.concat(names, ", "));
                    end;
                end;
            end;
        end;
    end;

    out[#out + 1] = "=== СВОДКА getgc ===";
    for _, k in ipairs({ ["function"], ["table"], "thread", "userdata", "other" }) do
        out[#out + 1] = string.format("  %-9s %d", k, counts[k]);
    end;
    out[#out + 1] = "";
    out[#out + 1] = "=== ФУНКЦИИ С UPVALUE (главный след чужого кода) ===";

    local shown = 0;
    for _, line in ipairs(entries) do
        if shown >= limit then
            out[#out + 1] = "... обрезано на " .. limit;
            break;
        end;
        out[#out + 1] = "  " .. line;
        shown = shown + 1;
    end;

    return table.concat(out, "\n");
end

------------------------------------------------------------------ таблица

--- Глубокий дамп таблицы: depth ограничен, циклы помечаются.
function dumper.dumpTable(t, name, maxDepth)
    local out = {};
    local seen = {};
    maxDepth = maxDepth or 4;

    if type(t) ~= "table" then
        return short(t) .. " (" .. type(t) .. ") — не таблица";
    end;

    local function walk(v, path, depth)
        if depth > maxDepth then
            out[#out + 1] = path .. "  ... (глубже " .. maxDepth .. ")";
            return;
        end;
        if type(v) ~= "table" then
            out[#out + 1] = string.rep("  ", depth) .. path .. " = " .. short(v, 90);
            return;
        end;
        if seen[v] then
            out[#out + 1] = string.rep("  ", depth) .. path .. " -> <цикл>";
            return;
        end;
        seen[v] = true;

        local keys = {};
        for k in pairs(v) do keys[#keys + 1] = k end;
        table.sort(keys, function(a, b) return tostring(a) < tostring(b) end);

        for _, k in ipairs(keys) do
            local path2 = path .. "." .. tostring(k);
            local val = v[k];
            if type(val) == "function" then
                local s = source_of(val);
                out[#out + 1] = string.rep("  ", depth + 1)
                    .. path2 .. " = fn " .. short(s, 50);
            else
                walk(val, path2, depth + 1);
            end;
        end;
        seen[v] = nil;
    end;

    out[#out + 1] = "=== " .. (name or "таблица") .. " (" .. type(t) .. ") ===";
    walk(t, name or "t", 0);
    return table.concat(out, "\n");
end

------------------------------------------------------------------ upvalues

--- Разбор конкретной функции: источник, аргументы, upvalue.
function dumper.dumpFunction(f)
    local out = {};
    if type(f) ~= "function" then return "не функция" end;

    local src, real = source_of(f);
    out[#out + 1] = "=== функция ===";
    out[#out + 1] = "  источник : " .. short(src, 120) .. (real and "  [реальный исходник]" or ""));
    if type(debug) == "table" and type(debug.info) == "function" then
        pcall(function()
            local info = debug.info(f, "nSln");
            if info then
                out[#out + 1] = "  имя      : " .. tostring(info.name);
                out[#out + 1] = "  строка   : " .. tostring(info.linedefined) .. " -> " .. tostring(info.lastlinedefined);
                out[#out + 1] = "  параметры: " .. tostring(info.nparams);
            end;
        end);
    end;

    out[#out + 1] = "  upvalue  :";
    local n = 0;
    if type(debug) == "table" and type(debug.getupvalues) == "function" then
        local ok, list = pcall(debug.getupvalues, f);
        if ok and type(list) == "table" then
            for _, u in ipairs(list) do
                n = n + 1;
                if type(u.value) == "function" then
                    out[#out + 1] = string.format("    [%d] %s = fn %s", n,
                        tostring(u.name or "?"), short(source_of(u.value), 50));
                else
                    out[#out + 1] = string.format("    [%d] %s = %s", n,
                        tostring(u.name or "?"), short(u.value, 70));
                end;
            end;
        end;
    end;
    if n == 0 then out[#out + 1] = "    (нет или getupvalues недоступен)" end;
    return table.concat(out, "\n");
end

------------------------------------------------------------------ stealth

--- Прячет дампер от стандартных каналов дампа.
--- Это и есть смысл режима: проверить, ловит ли твой анти-дамп скрытый
--- дампер, а не только явный.
function dumper.setStealth(on)
    on = on and true or false;

    if on then
        -- 1) свои функции прячем в таблицу: getgc по ссылке на таблицу
        --    находит таблицу, но не разворачивает её содержимое
        local box = {};
        rawset(box, "dumpInstances", dumper.dumpInstances);
        rawset(box, "dumpModules", dumper.dumpModules);
        rawset(box, "dumpGC", dumper.dumpGC);
        rawset(box, "dumpTable", dumper.dumpTable);
        rawset(box, "dumpFunction", dumper.dumpFunction);

        -- 2) GUI уводим в контейнер с непривычным именем и в ReplicatedFirst,
        --    чтобы обход workspace его не находил
        if not stealth_mount then
            stealth_mount = Instance.new("Folder");
            stealth_mount.Name = "_" .. tostring(os.clock()):gsub("%.", "");
            pcall(function() stealth_mount.Parent = game:GetService("ReplicatedFirst") end);
        end;
        if gui and gui.Parent then pcall(function() gui.Parent = stealth_mount end) end;
        if frame then frame.Visible = false end;

        dumper._box = box;
        return true;
    end;

    if gui then
        pcall(function()
            gui.Parent = game:GetService("CoreGui");
            frame.Visible = true;
        end);
    end;
    dumper._box = nil;
    return false;
end

------------------------------------------------------------------ интерфейс

local TAB_LIST = { "Instances", "Modules", "GC", "Table", "Function" };

local function do_dump(which, out_box, status)
    local ok, res = pcall(function()
        if which == "Instances" then
            return dumper.dumpInstances({
                game:GetService("Workspace"),
                game:GetService("ReplicatedStorage"),
                game:GetService("Players"),
                game:GetService("ServerStorage"),
            });
        elseif which == "Modules" then
            local root = game:GetService("ReplicatedStorage"):FindFirstChild("Modules")
                or game:GetService("ReplicatedStorage");
            return dumper.dumpModules(root);
        elseif which == "GC" then
            return dumper.dumpGC();
        end;
        return "выбери цель: таблица из getgc или функция из поля внизу";
    end);

    if ok and type(res) == "string" then
        last_result[which] = res;
        out_box.Text = res;
        local lines = select(2, res:gsub("\n", ""));
        status.Text = string.format("%s — готово, %d строк, %d символов",
            which, lines, #res);
        return true;
    end;

    status.Text = string.format("%s — ошибка: %s", which, short(res, 80));
    out_box.Text = "";
    return false;
end

local function ensure_gui()
    if gui and gui.Parent then return true end;

    gui = Instance.new("ScreenGui");
    gui.Name = "RainDumper";
    gui.ResetOnSpawn = false;
    gui.IgnoreGuiInset = true;
    gui.DisplayOrder = 950;
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling;
    pcall(function() gui.Parent = game:GetService("CoreGui") end);
    if not gui.Parent then
        local ok, pg = pcall(function()
            return game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui", 5)
        end);
        if ok and pg then pcall(function() gui.Parent = pg end) end;
    end;
    if not gui.Parent then return false end;

    frame = Instance.new("Frame");
    frame.Name = "RainDumperFrame";
    frame.Size = UDim2.new(0, 520, 0, 620);
    frame.Position = UDim2.new(0.5, -260, 0.5, -310);
    frame.BackgroundColor3 = Color3.fromRGB(16, 16, 20);
    frame.BorderSizePixel = 0;
    frame.Parent = gui;

    local title = Instance.new("TextLabel");
    title.Size = UDim2.new(1, 0, 0, 26);
    title.BackgroundColor3 = Color3.fromRGB(34, 34, 42);
    title.BorderSizePixel = 0;
    title.Text = "Dumper — проверка анти-дампера";
    title.TextColor3 = Color3.fromRGB(240, 240, 240);
    title.Font = Enum.Font.GothamBold;
    title.TextSize = 13;
    title.Parent = frame;

    do
        local dragging, start_pos, start_input = false, nil, nil;
        title.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                dragging = true; start_pos = frame.Position;
                start_input = input.Position;
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then dragging = false end;
                end);
            end;
        end;
        game:GetService("UserInputService").InputChanged:Connect(function(input)
            if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
                local d = input.Position - start_input;
                frame.Position = UDim2.new(start_pos.X.Scale, start_pos.X.Offset + d.X,
                    start_pos.Y.Scale, start_pos.Y.Offset + d.Y);
            end;
        end);
    end;

    local y = 30;

    -- переключатель режимов
    local tab_row = Instance.new("Frame");
    tab_row.Size = UDim2.new(1, -12, 0, 24);
    tab_row.Position = UDim2.new(0, 6, 0, y);
    tab_row.BackgroundTransparency = 1;
    tab_row.Parent = frame;

    local buttons = {};
    for i, name in ipairs(TAB_LIST) do
        local b = Instance.new("TextButton");
        b.Size = UDim2.new(0, 100, 0, 24);
        b.Position = UDim2.new(0, (i - 1) * 102, 0, 0);
        b.BackgroundColor3 = (name == active_tab)
            and Color3.fromRGB(60, 100, 70) or Color3.fromRGB(40, 40, 50);
        b.BorderSizePixel = 0;
        b.Text = name;
        b.TextColor3 = Color3.fromRGB(240, 240, 240);
        b.Font = Enum.Font.Gotham;
        b.TextSize = 11;
        b.Parent = tab_row;
        b.MouseButton1Click:Connect(function()
            active_tab = name;
            for nm, btn in pairs(buttons) do
                btn.BackgroundColor3 = (nm == active_tab)
                    and Color3.fromRGB(60, 100, 70) or Color3.fromRGB(40, 40, 50);
            end;
        end);
        buttons[name] = b;
    end;
    y += 28;

    -- строка поиска
    local search = Instance.new("TextBox");
    search.Name = "Search";
    search.PlaceholderText = "фильтр по тексту дампа...";
    search.Size = UDim2.new(1, -12, 0, 24);
    search.Position = UDim2.new(0, 6, 0, y);
    search.BackgroundColor3 = Color3.fromRGB(34, 34, 42);
    search.BorderSizePixel = 0;
    search.Text = "";
    search.TextColor3 = Color3.fromRGB(240, 240, 240);
    search.Font = Enum.Font.Code;
    search.TextSize = 11;
    search.ClearTextOnFocus = false;
    search.Parent = frame;
    y += 28;

    local function mkbtn(text, xx, color, cb)
        local b = Instance.new("TextButton");
        b.Size = UDim2.new(0, 124, 0, 24);
        b.Position = UDim2.new(0, xx, 0, y);
        b.BackgroundColor3 = color;
        b.BorderSizePixel = 0;
        b.Text = text;
        b.TextColor3 = Color3.fromRGB(255, 255, 255);
        b.Font = Enum.Font.GothamBold;
        b.TextSize = 11;
        b.Parent = frame;
        b.MouseButton1Click:Connect(cb);
        return b;
    end

    local out_box, status;

    mkbtn("Dump", 6, Color3.fromRGB(50, 90, 140), function()
        out_box.Text = "дамп выполняется...";
        status.Text = "работаю...";
        task.defer(function() do_dump(active_tab, out_box, status) end);
    end);

    mkbtn("Save File", 134, Color3.fromRGB(50, 110, 60), function()
        local body = last_result[active_tab];
        if not body then status.Text = "сначала сделай дамп" return end;
        pcall(function()
            if not isfolder("Project Rain") then makefolder("Project Rain") end;
            writefile("Project Rain/dump_" .. active_tab .. ".txt", body);
            status.Text = "записано в Project Rain/dump_" .. active_tab .. ".txt";
        end);
    end);

    mkbtn("Clipboard", 262, Color3.fromRGB(70, 70, 100), function()
        local body = last_result[active_tab];
        if not body then status.Text = "сначала сделай дамп" return end;
        pcall(function()
            if setclipboard then setclipboard(body) end;
            status.Text = "скопировано в буфер (" .. #body .. " символов)";
        end);
    end);

    mkbtn("Clear", 390, Color3.fromRGB(90, 50, 50), function()
        last_result[active_tab] = nil;
        out_box.Text = "";
        status.Text = "очищено";
    end);

    mkbtn("Close", 458, Color3.fromRGB(110, 40, 40), function()
        dumper.close();
    end);
    y += 28;

    status = Instance.new("TextLabel");
    status.Size = UDim2.new(1, -12, 0, 20);
    status.Position = UDim2.new(0, 6, 0, y);
    status.BackgroundTransparency = 1;
    status.Text = "";
    status.TextColor3 = Color3.fromRGB(150, 200, 150);
    status.Font = Enum.Font.Gotham;
    status.TextSize = 11;
    status.TextXAlignment = Enum.TextXAlignment.Left;
    status.Parent = frame;
    y += 24;

    out_box = Instance.new("TextBox");
    out_box.Name = "Output";
    out_box.Size = UDim2.new(1, -12, 1, -(y + 10));
    out_box.Position = UDim2.new(0, 6, 0, y);
    out_box.BackgroundColor3 = Color3.fromRGB(10, 10, 14);
    out_box.BorderSizePixel = 0;
    out_box.Text = "";
    out_box.MultiLine = true;
    out_box.ReadOnly = false;
    out_box.ScrollableY = true;
    out_box.Font = Enum.Font.Code;
    out_box.TextSize = 11;
    out_box.TextColor3 = Color3.fromRGB(200, 220, 200);
    out_box.TextXAlignment = Enum.TextXAlignment.Left;
    out_box.TextYAlignment = Enum.TextYAlignment.Top;
    out_box.ClearTextOnFocus = false;
    out_box.Parent = frame;

    -- живой фильтр: печатаешь — выход фильтруется
    search.Changed:Connect(function()
        local q = search.Text;
        local body = last_result[active_tab];
        if not body then return end;
        if q == "" then out_box.Text = body return end;
        local kept = {};
        for line in (body .. "\n"):gmatch("(.-)\n") do
            if line:lower():find(q:lower(), 1, true) then kept[#kept + 1] = line end;
        end;
        out_box.Text = table.concat(kept, "\n");
    end);

    -- поля для ручной цели (Table / Function)
    local target = Instance.new("TextBox");
    target.Name = "Target";
    target.PlaceholderText = "индекс getgc() для Table, номер строки GC для Function...";
    target.Size = UDim2.new(1, -12, 0, 22);
    target.Position = UDim2.new(0, 6, 1, -28);
    target.BackgroundColor3 = Color3.fromRGB(34, 34, 42);
    target.BorderSizePixel = 0;
    target.Text = "";
    target.TextColor3 = Color3.fromRGB(240, 240, 240);
    target.Font = Enum.Font.Code;
    target.TextSize = 10;
    target.ClearTextOnFocus = false;
    target.Visible = false;
    target.Parent = frame;

    -- режимы Table/Function используют поле цели
    for _, b in pairs(buttons) do end
    buttons.Table.MouseButton1Click:Connect(function() target.Visible = true end);
    buttons.Function.MouseButton1Click:Connect(function() target.Visible = true end);
    buttons.Instances.MouseButton1Click:Connect(function() target.Visible = false end);
    buttons.Modules.MouseButton1Click:Connect(function() target.Visible = false end);
    buttons.GC.MouseButton1Click:Connect(function() target.Visible = false end);

    dumper._target_box = target;
    return true;
end

function dumper.open()
    if not ensure_gui() then return false end;
    pcall(function() gui.Parent = game:GetService("CoreGui") end);
    frame.Visible = true;
    frame.Active = true;
    running = true;
    return true;
end

function dumper.close()
    running = false;
    if frame then frame.Visible = false end;
end

--- Ручной дамп цели по индексу getgc().
function dumper.dumpTarget(kind, index)
    if type(getgc) ~= "function" then return "getgc недоступен" end;
    local ok, items = pcall(getgc, true);
    if not ok then return "getgc: " .. short(items, 60) end;
    local o = items[index];
    if o == nil then return "нет объекта по индексу " .. tostring(index) end;
    if kind == "Function" then return dumper.dumpFunction(o) end;
    return dumper.dumpTable(o, "getgc[" .. index .. "]");
end

getgenv().rain_dumper = dumper
return dumper
end)
__bundle_register("@src/utility/fflags", function(require, _LOADED, __bundle_register, __bundle_modules)
local fflags = {} do
    fflags.current = isfile("Project Rain/fflags.txt") and readfile("Project Rain/fflags.txt") or "{}";

    function fflags:get_main()
        if not self.cached then
            self.cached = services.HttpService:JSONDecode(self.current or "{}");
        end
        return self.cached    
end

    function fflags:get(flag)
        return self:get_main()[flag]    
end;

    function fflags:set(flag, value)
        local decoded = services.HttpService:JSONDecode(self.current);
        decoded[flag] = value;
        self.current = services.HttpService:JSONEncode(decoded);
        self.cached = services.HttpService:JSONDecode(self.current or "{}");
        writefile("Project Rain/fflags.txt", self.current);
    end;
end

return fflags 
end)
__bundle_register("@src/utility/freecam", function(require, _LOADED, __bundle_register, __bundle_modules)
fcRunning = false
local Camera = workspace.CurrentCamera
workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
	local newCamera = workspace.CurrentCamera
	if newCamera then
		Camera = newCamera
	end
end)

local INPUT_PRIORITY = Enum.ContextActionPriority.High.Value

local cameraPos = Vector3.new()
local cameraRot = Vector2.new()

NAV_KEYBOARD_SPEED = Vector3.new(1, 1, 1)

Input = {} do

	keyboard = {
		W = 0,
		A = 0,
		S = 0,
		D = 0,
		E = 0,
		Q = 0,
		Up = 0,
		Down = 0,
		LeftShift = 0,
	}

	mouse = {
		Delta = Vector2.new(),
	}

	PAN_MOUSE_SPEED = Vector2.new(1, 1)*(math.pi/64)
	NAV_ADJ_SPEED = 0.75
	NAV_SHIFT_MUL = 0.25

	navSpeed = 2

	function Input.Vel(dt)
		navSpeed = math.clamp(navSpeed + dt*(keyboard.Up - keyboard.Down)*NAV_ADJ_SPEED, 0.01, 4)

		local kKeyboard = Vector3.new(
			keyboard.D - keyboard.A,
			keyboard.E - keyboard.Q,
			keyboard.S - keyboard.W
		)*NAV_KEYBOARD_SPEED

		local shift = services.UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)

		return (kKeyboard)*(navSpeed*(shift and NAV_SHIFT_MUL or 1))
	end

	function Input.Pan(dt)
		local kMouse = mouse.Delta*PAN_MOUSE_SPEED
		mouse.Delta = Vector2.new()
		return kMouse
	end

	do
		function Keypress(action, state, input)
			keyboard[input.KeyCode.Name] = state == Enum.UserInputState.Begin and 1 or 0
			return Enum.ContextActionResult.Sink
		end

		function MousePan(action, state, input)
			local delta = input.Delta
			mouse.Delta = Vector2.new(-delta.y, -delta.x)
			return Enum.ContextActionResult.Sink
		end

		function Zero(t)
			for k, v in pairs(t) do
				t[k] = v*0
			end
		end

		function Input.StartCapture()
			services.ContextActionService:BindActionAtPriority("FreecamKeyboard",Keypress,false,INPUT_PRIORITY,
				Enum.KeyCode.W,
				Enum.KeyCode.A,
				Enum.KeyCode.S,
				Enum.KeyCode.D,
				Enum.KeyCode.E,
				Enum.KeyCode.Q,
				Enum.KeyCode.Up,
				Enum.KeyCode.Down
			)
			services.ContextActionService:BindActionAtPriority("FreecamMousePan",MousePan,false,INPUT_PRIORITY,Enum.UserInputType.MouseMovement)
		end

		function Input.StopCapture()
			navSpeed = 1
			Zero(keyboard)
			Zero(mouse)
			services.ContextActionService:UnbindAction("FreecamKeyboard")
			services.ContextActionService:UnbindAction("FreecamMousePan")
		end
	end
end

function GetFocusDistance(cameraFrame)
	local znear = 0.1
	local viewport = Camera.ViewportSize
	local projy = 2*math.tan(70/2)
	local projx = viewport.x/viewport.y*projy
	local fx = cameraFrame.rightVector
	local fy = cameraFrame.upVector
	local fz = cameraFrame.lookVector

	local minVect = Vector3.new()
	local minDist = 512

	for x = 0, 1, 0.5 do
		for y = 0, 1, 0.5 do
			local cx = (x - 0.5)*projx
			local cy = (y - 0.5)*projy
			local offset = fx*cx - fy*cy + fz
			local origin = cameraFrame.p + offset*znear
			local _, hit = workspace:FindPartOnRay(Ray.new(origin, offset.unit*minDist))
			local dist = (hit - origin).magnitude
			if minDist > dist then
				minDist = dist
				minVect = offset.unit
			end
		end
	end

	return fz:Dot(minVect)*minDist
end

local function StepFreecam(dt)
	
	local vel = Input.Vel(dt)
	local pan = Input.Pan(dt)

	local zoomFactor = math.sqrt(math.tan(math.rad(70/2))/math.tan(math.rad(70/2)))

	cameraRot = cameraRot + pan*Vector2.new(0.75, 1)*8*(dt/zoomFactor)
	cameraRot = Vector2.new(math.clamp(cameraRot.x, -math.rad(90), math.rad(90)), cameraRot.y%(2*math.pi))

	local cameraCFrame = CFrame.new(cameraPos)*CFrame.fromOrientation(cameraRot.x, cameraRot.y, 0)*CFrame.new(vel*Vector3.new(1, 1, 1)*64*dt)
	cameraPos = cameraCFrame.p

	Camera.CFrame = cameraCFrame
	Camera.Focus = cameraCFrame*CFrame.new(0, 0, -GetFocusDistance(cameraCFrame))
end

local PlayerState = {} do
	mouseBehavior = ""
	mouseIconEnabled = ""
	cameraType = ""
	cameraFocus = ""
	cameraCFrame = ""

	function PlayerState.Push()

		cameraType = Camera.CameraType
		Camera.CameraType = Enum.CameraType.Custom

		cameraCFrame = Camera.CFrame
		cameraFocus = Camera.Focus

		mouseIconEnabled = services.UserInputService.MouseIconEnabled
		services.UserInputService.MouseIconEnabled = true

		mouseBehavior = services.UserInputService.MouseBehavior
		services.UserInputService.MouseBehavior = Enum.MouseBehavior.Default
	end

	function PlayerState.Pop()

		Camera.CameraType = cameraType
		cameraType = nil

		Camera.CFrame = cameraCFrame
		cameraCFrame = nil

		Camera.Focus = cameraFocus
		cameraFocus = nil

		services.UserInputService.MouseIconEnabled = mouseIconEnabled
		mouseIconEnabled = nil

		services.UserInputService.MouseBehavior = mouseBehavior
		mouseBehavior = nil
	end
end

function StartFreecam(pos)
	if fcRunning then
		StopFreecam()
	end
	local cameraCFrame = Camera.CFrame
	if pos then
		cameraCFrame = pos
	end
	cameraRot = Vector2.new()
	cameraPos = cameraCFrame.p

	PlayerState.Push()
	services.RunService:BindToRenderStep("Freecam", Enum.RenderPriority.Camera.Value, StepFreecam)
	Input.StartCapture()
	fcRunning = true
end

function StopFreecam()
	if not fcRunning then return end
	Input.StopCapture()
	services.RunService:UnbindFromRenderStep("Freecam")
	PlayerState.Pop()
	fcRunning = false
end

return {
	exit = StopFreecam,
	enter = StartFreecam,
	set_speed = function(speed)
		NAV_KEYBOARD_SPEED = speed
	end
}

end)
__bundle_register("@src/utility/game_dumper", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Game Script Dumper. Слив исходников скриптов ИГРЫ (Deepwoken).
--
-- Задача узкая и отличается от дампа Place: нужен не список инстансов и не
-- обход getgc, а ТЕКСТ игровых скриптов. Поэтому ядро здесь одно —
-- дойти до каждого ModuleScript/LocalScript и вытащить его Source.
--
-- Как достаётся исходник (три канала, потому что у исполнителей доступен
-- не всегда один):
--   1) getscript(inst).Source   — прямой источник, самый полный
--   2) require(inst) -> функции -> debug.info(f, "S")/getsource(f)
--      даёт текст для модулей, у которых getscript не сработал
--   3) inst.Source              — если экземпляр сам Script
--
-- Где искать: ReplicatedStorage.Modules (основное хранилище Deepwoken),
-- но обход идёт по ВСЕМУ ReplicatedStorage + PlayerGui + PlayerScripts,
-- потому что часть модулей лежит вне Modules.
--
-- Для теста анти-дампера важен STEALTH: дампер уводит свои GUI-объекты в
-- скрытый контейнер и прячет функции, чтобы проверить, ловит ли анти-дамп
-- неявный слив, а не только явный обход дерева.

local dumper = {}

local gui, frame, log_box, status, progress_bar;
local running = false;
local stealth_mount = nil;
local found = {};        -- { inst = ModuleScript, name = string }
local dumped = 0;

------------------------------------------------------------------ helpers

local function line_out(s)
    if not log_box then return end;
    log_box.Text = log_box.Text .. s .. "\n";
    pcall(function() log_box.Position = UDim2.new(0, 6, 0, math.max(0, log_box.AbsoluteCanvasSize.Y)) end);
end

local function set_status(s)
    if status then status.Text = s end;
end

local function set_progress(cur, total)
    if not progress_bar then return end;
    local r = (total and total > 0) and (cur / total) or 0;
    pcall(function()
        progress_bar.Size = UDim2.new(math.clamp(r, 0, 1), 0, 1, 0);
    end);
end

------------------------------------------------------------------ поиск

--- Собирает все скриптовые инстансы игры. Обход шире, чем просто Modules:
--- часть модулей лежит в ReplicatedStorage/PlayerGui/PlayerScripts.
function dumper.scan(limit)
    local out = {};
    local seen = {};
    limit = limit or 5000;

    local roots = {
        game:GetService("ReplicatedStorage"),
        game:GetService("Players"):GetPlayers()[1]
            and game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui") or nil,
        game:GetService("Players"):GetPlayers()[1]
            and game:GetService("Players").LocalPlayer:FindFirstChild("PlayerScripts") or nil,
    };

    for _, root in ipairs(roots) do
        if root and typeof(root) == "Instance" then
            local ok, list = pcall(function() return root:GetDescendants() end);
            if ok then
                for _, inst in ipairs(list) do
                    if #out >= limit then break end;
                    local ct = inst.ClassName;
                    if (ct == "ModuleScript" or ct == "LocalScript" or ct == "Script")
                        and not seen[inst] then
                        seen[inst] = true;
                        out[#out + 1] = inst;
                    end;
                end;
            end;
        end;
    end;

    return out;
end

------------------------------------------------------------------ извлечение

--- Текст исходника одного инстанса. nil, если достать не удалось.
function dumper.getSource(inst)
    if typeof(inst) ~= "Instance" then return nil end;

    -- 1) getscript — самый полный канал
    if type(getscript) == "function" then
        local ok, sc = pcall(getscript, inst);
        if ok and sc and type(sc) == "Instance" then
            local sok, s = pcall(function() return sc.Source end);
            if sok and type(s) == "string" and #s > 0 then return s, "getscript" end;
        end;
    end;

    -- 2) собственный Source (если это Script/LocalScript)
    local dok, d = pcall(function() return inst.Source end);
    if dok and type(d) == "string" and #d > 0 then return d, "Source" end;

    -- 3) через require: берём функции из модуля и спрашиваем у них исходник
    local rok, mod = pcall(require, inst);
    if rok and type(mod) == "table" then
        local pieces = {};
        for _, v in pairs(mod) do
            if type(v) == "function" then
                local src = nil;
                if type(getsource) == "function" then
                    local gok, g = pcall(getsource, v);
                    if gok and type(g) == "string" and #g > 0 then src = g end;
                end;
                if not src and type(debug) == "table" and type(debug.info) == "function" then
                    local iok, info = pcall(debug.info, v, "S");
                    if iok and type(info) == "string" and info:sub(1, 1) ~= "=" then src = info end;
                end;
                if src then pieces[#pieces + 1] = "-- [" .. tostring(v) .. "]\n" .. src end;
            end;
        end;
        if #pieces > 0 then return table.concat(pieces, "\n\n"), "require" end;
    end;

    return nil;
end

------------------------------------------------------------------ дамп

--- Основной слив. Пишет каждый модуль отдельным файлом + один сводный.
---@param dir string  папка внутри воркспейса
---@return table  статистика
function dumper.run(dir)
    dir = dir or "GameDump";

    if running then return { error = "уже выполняется" } end;
    running = true;
    dumped = 0;

    if log_box then log_box.Text = "" end;
    set_status("сканирую игру...");

    local insts = dumper.scan();
    found = insts;
    set_progress(0, #insts);
    line_out(string.format("найдено скриптов: %d", #insts));

    local ok_folder = pcall(function()
        if not isfolder(dir) then makefolder(dir) end;
    end);
    if not ok_folder then
        set_status("не смог создать папку " .. dir);
        running = false;
        return { error = "folder" };
    end;

    local combined = {};
    local stats = { total = #insts, got = 0, failed = 0, bytes = 0 };

    for i, inst in ipairs(insts) do
        local src, via = dumper.getSource(inst);

        if src then
            stats.got = stats.got + 1;
            stats.bytes = stats.bytes + #src;
            dumped = dumped + 1;

            local fname = string.gsub(inst.Name, "[^%w_%-%.]", "_");
            pcall(function() writefile(dir .. "/" .. fname .. ".lua", src) end);

            combined[#combined + 1] = string.format(
                "\n\n-- ======================================================================\n"
                .. "-- FILE: %s (%s)\n-- VIA : %s\n"
                .. "-- ======================================================================\n%s",
                inst.Name, inst.ClassName, via, src);
        else
            stats.failed = stats.failed + 1;
        end;

        set_progress(i, #insts);
        if i % 25 == 0 then
            set_status(string.format("обработано %d/%d, слито %d", i, #insts, stats.got));
            task.wait();
        end;
    end;

    pcall(function() writefile(dir .. "/_ALL.lua", table.concat(combined)) end);

    running = false;
    set_progress(1, 1);
    set_status(string.format("готово: слито %d из %d, %d КБ, в папку %s",
        stats.got, stats.total, math.floor(stats.bytes / 1024), dir));
    line_out("");
    line_out(string.format("=== ГОТОВО === %d файлов, ошибок/недоступно: %d", stats.got, stats.failed));

    return stats;
end

------------------------------------------------------------------ stealth

--- Прячет дампер. Для проверки: ловит ли анти-дамп неявный слив.
function dumper.setStealth(on)
    on = on and true or false;

    if on then
        if not stealth_mount then
            stealth_mount = Instance.new("Folder");
            stealth_mount.Name = "_" .. tostring(math.floor(os.clock() * 1000));
            -- ReplicatedFirst не обходится обычным дампом workspace
            pcall(function() stealth_mount.Parent = game:GetService("ReplicatedFirst") end);
        end;
        if gui then pcall(function() gui.Parent = stealth_mount end) end;
        if frame then frame.Visible = false end;
        return true;
    end;

    if gui then
        pcall(function() gui.Parent = game:GetService("CoreGui") end);
        if frame then frame.Visible = true end;
    end;
    return false;
end

function dumper.isStealth()
    return stealth_mount ~= nil and gui ~= nil and gui.Parent == stealth_mount;
end

------------------------------------------------------------------ интерфейс

local function ensure_gui()
    if gui and gui.Parent then return true end;

    gui = Instance.new("ScreenGui");
    gui.Name = "RainGameDumper";
    gui.ResetOnSpawn = false;
    gui.IgnoreGuiInset = true;
    gui.DisplayOrder = 960;
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling;
    pcall(function() gui.Parent = game:GetService("CoreGui") end);
    if not gui.Parent then
        local ok, pg = pcall(function()
            return game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui", 5)
        end);
        if ok and pg then pcall(function() gui.Parent = pg end) end;
    end;
    if not gui.Parent then return false end;

    frame = Instance.new("Frame");
    frame.Name = "RainGameDumperFrame";
    frame.Size = UDim2.new(0, 560, 0, 560);
    frame.Position = UDim2.new(0.5, -280, 0.5, -280);
    frame.BackgroundColor3 = Color3.fromRGB(16, 16, 20);
    frame.BorderSizePixel = 0;
    frame.Parent = gui;

    local title = Instance.new("TextLabel");
    title.Size = UDim2.new(1, 0, 0, 28);
    title.BackgroundColor3 = Color3.fromRGB(34, 34, 42);
    title.BorderSizePixel = 0;
    title.Text = "Game Script Dumper — слив исходников СКРИПТОВ ИГРЫ";
    title.TextColor3 = Color3.fromRGB(240, 240, 240);
    title.Font = Enum.Font.GothamBold;
    title.TextSize = 13;
    title.Parent = frame;

    do
        local dragging, sp, si = false, nil, nil;
        title.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                dragging = true; sp = frame.Position; si = input.Position;
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then dragging = false end;
                end);
            end;
        end);
        game:GetService("UserInputService").InputChanged:Connect(function(input)
            if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
                local d = input.Position - si;
                frame.Position = UDim2.new(sp.X.Scale, sp.X.Offset + d.X,
                    sp.Y.Scale, sp.Y.Offset + d.Y);
            end;
        end);
    end

    local y = 32;
    local dir_box = Instance.new("TextBox");
    dir_box.Size = UDim2.new(0, 200, 0, 24);
    dir_box.Position = UDim2.new(0, 8, 0, y);
    dir_box.BackgroundColor3 = Color3.fromRGB(34, 34, 42);
    dir_box.BorderSizePixel = 0;
    dir_box.Text = "Project Rain/GameDump";
    dir_box.TextColor3 = Color3.fromRGB(240, 240, 240);
    dir_box.Font = Enum.Font.Gotham;
    dir_box.TextSize = 11;
    dir_box.ClearTextOnFocus = false;
    dir_box.Parent = frame;

    local stealth_btn;
    local function mkbtn(text, xx, color, cb)
        local b = Instance.new("TextButton");
        b.Size = UDim2.new(0, 130, 0, 24);
        b.Position = UDim2.new(0, xx, 0, y);
        b.BackgroundColor3 = color;
        b.BorderSizePixel = 0;
        b.Text = text;
        b.TextColor3 = Color3.fromRGB(255, 255, 255);
        b.Font = Enum.Font.GothamBold;
        b.TextSize = 11;
        b.Parent = frame;
        b.MouseButton1Click:Connect(cb);
        return b;
    end

    mkbtn("СЛИТЬ ВСЁ", 214, Color3.fromRGB(50, 95, 140), function()
        if running then set_status("уже выполняется") return end;
        set_status("запуск...");
        task.spawn(function() dumper.run(dir_box.Text) end);
    end);

    mkbtn("Только сканировать", 350, Color3.fromRGB(60, 60, 80), function()
        local insts = dumper.scan();
        if log_box then log_box.Text = "" end;
        line_out("найдено: " .. #insts);
        local by_class = {};
        for _, i in ipairs(insts) do
            by_class[i.ClassName] = (by_class[i.ClassName] or 0) + 1;
        end;
        for c, n in pairs(by_class) do line_out("  " .. c .. ": " .. n) end;
        line_out("");
        for idx, i in ipairs(insts) do
            if idx <= 400 then line_out(string.format("%4d  %-14s %s", idx, i.ClassName, i.Name)) end;
        end;
        if #insts > 400 then line_out("... и ещё " .. (#insts - 400)) end;
        set_status("сканирование завершено");
    end);

    y += 30;

    progress_bar = Instance.new("Frame");
    progress_bar.Size = UDim2.new(0, 0, 0, 4);
    progress_bar.Position = UDim2.new(0, 8, 0, y);
    progress_bar.BackgroundColor3 = Color3.fromRGB(90, 190, 120);
    progress_bar.BorderSizePixel = 0;
    progress_bar.Parent = frame;
    y += 10;

    status = Instance.new("TextLabel");
    status.Size = UDim2.new(1, -16, 0, 20);
    status.Position = UDim2.new(0, 8, 0, y);
    status.BackgroundTransparency = 1;
    status.Text = "";
    status.TextColor3 = Color3.fromRGB(150, 200, 150);
    status.Font = Enum.Font.Gotham;
    status.TextSize = 11;
    status.TextXAlignment = Enum.TextXAlignment.Left;
    status.Parent = frame;
    y += 24;

    log_box = Instance.new("TextBox");
    log_box.Size = UDim2.new(1, -16, 1, -(y + 8));
    log_box.Position = UDim2.new(0, 8, 0, y);
    log_box.BackgroundColor3 = Color3.fromRGB(10, 10, 14);
    log_box.BorderSizePixel = 0;
    log_box.Text = "";
    log_box.MultiLine = true;
    log_box.ReadOnly = true;
    log_box.ScrollableY = true;
    log_box.Font = Enum.Font.Code;
    log_box.TextSize = 11;
    log_box.TextColor3 = Color3.fromRGB(200, 220, 200);
    log_box.TextXAlignment = Enum.TextXAlignment.Left;
    log_box.TextYAlignment = Enum.TextYAlignment.Top;
    log_box.ClearTextOnFocus = false;
    log_box.Parent = frame;

    stealth_btn = mkbtn("Stealth", 8, Color3.fromRGB(70, 50, 90), function()
        local on = dumper.setStealth(not dumper.isStealth());
        stealth_btn.Text = on and "Stealth: ВКЛ" or "Stealth: выкл";
        if not on then set_status("stealth выключен") end;
    end);
    stealth_btn.Position = UDim2.new(0, 8, 1, -28);
    stealth_btn.Size = UDim2.new(0, 150, 0, 24);

    local close_btn = mkbtn("Закрыть", 400, Color3.fromRGB(110, 40, 40), function()
        dumper.close();
    end);
    close_btn.Position = UDim2.new(1, -140, 1, -28);
    close_btn.Size = UDim2.new(0, 130, 0, 24);

    return true;
end

function dumper.open()
    if not ensure_gui() then return false end;
    pcall(function() gui.Parent = game:GetService("CoreGui") end);
    frame.Visible = true;
    running = running or false;
    return true;
end

function dumper.close()
    if frame then frame.Visible = false end;
    if dumper.isStealth() then dumper.setStealth(false) end;
end

getgenv().rain_game_dumper = dumper
return dumper
end)
__bundle_register("@src/utility/instancewatcher", function(require, _LOADED, __bundle_register, __bundle_modules)


local InstanceWatcher = {} do 
    InstanceWatcher.__index = InstanceWatcher;

    function InstanceWatcher.new(parent_instance, match_function, callback_function, should_wait): InstanceWatcher
        local self = setmetatable({}, InstanceWatcher);

        self.parent_instance = parent_instance;
        self.match_function = match_function;
        self.callback_function = callback_function;

        aztup.maid:give_task(self.parent_instance.ChildAdded:Connect(function(child_instance)
            if self.match_function(child_instance) then
                self.callback_function(child_instance)
            else
                task.delay(0.1, function()
                    if child_instance.Parent and self.match_function(child_instance) then
                        self.callback_function(child_instance)
                    end
                end)
            end
        end));

        task.spawn(function() 
            for _, child_instance in parent_instance:GetChildren() do
                task.spawn(function() 
                    if self.match_function(child_instance) then
                        self.callback_function(child_instance)
                    end
                end)

                if should_wait then
                    task.wait();
                end;
            end
        end);
        
        return self
    end
end

getgenv().InstanceWatcher = InstanceWatcher
return InstanceWatcher
end)
__bundle_register("@src/utility/irc", function(require, _LOADED, __bundle_register, __bundle_modules)
local irc = {}
irc.__index = irc




local function toWsUrl(server, port)
	
	if type(server) == "string" and (server:sub(1, 5) == "ws://" or server:sub(1, 6) == "wss://") then
		return server
	end
	return ("ws://%s:%d"):format(tostring(server), tonumber(port) or 80)
end

local function normalizeIrcLine(s)
	
	s = tostring(s or "")
	if s:sub(-2) ~= "\r\n" then
		s = s .. "\r\n"
	end
	return s
end

function irc.new(server, port, nickname)
	local self = setmetatable({}, irc)
	self.server = server
	self.port = port
	self.nickname = nickname
	self.connection = nil

	self._inbuf = ""
	self._queue = {}
	self._closed = false

	return self
end

function irc:connect()
	local url = toWsUrl(self.server, self.port)
	self.connection = WebSocket.connect(url)

	self._closed = false
	self._inbuf = ""
	self._queue = {}

	
	self.connection.OnMessage:Connect(function(payload)
		if self._closed then
			return
		end

		self._inbuf ..= tostring(payload)

		while true do
			local i, j = self._inbuf:find("\r\n", 1, true)
			if not i then
				break
			end
			local line = self._inbuf:sub(1, i - 1)
			table.insert(self._queue, line)
			self._inbuf = self._inbuf:sub(j + 1)
		end
	end)

	self.connection.OnClose:Connect(function()
		self._closed = true
	end)

	
	self.connection:Send(normalizeIrcLine("NICK " .. self.nickname))
	self.connection:Send(normalizeIrcLine("USER " .. self.nickname .. " 0 * :" .. self.nickname))
end

function irc:sendMessage(channel, message)
	if self.connection and not self._closed then
		self.connection:Send(normalizeIrcLine("PRIVMSG " .. channel .. " :" .. message))
	end
end

function irc:receiveMessage()
	
	if #self._queue > 0 then
		return table.remove(self._queue, 1)
	end
	return nil
end

function irc:disconnect()
	if self.connection then
		if not self._closed then
			
			pcall(function()
				self.connection:Send(normalizeIrcLine("QUIT"))
			end)
		end
		pcall(function()
			self.connection:Close()
		end)
		self.connection = nil
		self._closed = true
	end
end

return irc

end)
__bundle_register("@src/utility/latency", function(require, _LOADED, __bundle_register, __bundle_modules)
local latency = {};

-- restore: resolve the stat lazily on every call. The old code cached it at
-- require time (often before Stats replicated) and then returned 0 forever,
-- which shifted every parry timing late by a full RTT.
local function get_ping_stat()
    local ok, stats = pcall(function() return services.Stats end)
    if not ok or not stats then return nil end
    local ok2, item = pcall(function()
        return stats.Network.ServerStatsItem["Data Ping"]
    end)
    if ok2 and item then return item end
    local ok3, found = pcall(function() return stats:FindFirstChild("Data Ping", true) end)
    if ok3 then return found end
    return nil
end

function latency:get_ping()
    local ok, item = pcall(get_ping_stat)
    if ok and item then
        local ok2, val = pcall(function()
            local old = getthreadidentity();
            setthreadidentity(8);
            local v = item:GetValue();
            setthreadidentity(old);
            return v
        end)
        if ok2 and type(val) == "number" then return val / 1000 end
    end
    return 0
end;

function latency:half_ping()
    return latency:get_ping() / 2
end;

-- restore: present so rebinding bare Latency to this module never breaks
-- callers of the old boot stub (fly lag-bypass, currently a no-op).
function latency:force_lag(_) end

return latency
end)
__bundle_register("@src/utility/librarys/components/button", function(require, _LOADED, __bundle_register, __bundle_modules)




return function(Library, context)
	local Component = {}

	local function processButtonParams(target, ...)
		local props = select(1, ...)
		if type(props) == 'table' then
			target.Text = props.Text
			target.Func = props.Func
			target.DoubleClick = props.DoubleClick
			target.Tooltip = props.Tooltip
		else
			target.Text = select(1, ...)
			target.Func = select(2, ...)
		end

		assert(type(target.Func) == 'function', 'AddButton: `Func` callback is missing.')
	end

	local function createBaseButton(button)
		local outer = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(1, -4, 0, 20);
			ZIndex = 5;
		})

		local inner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 6;
			Parent = outer;
		})

		local label = Library:CreateLabel({
			Size = UDim2.new(1, 0, 1, 0);
			TextSize = 14;
			Text = button.Text;
			ZIndex = 6;
			Parent = inner;
		})

		
		
		
		
		
		
		
		

		Library:AddToRegistry(outer, { BorderColor3 = 'Black' })
		Library:AddToRegistry(inner, { BackgroundColor3 = 'MainColor'; BorderColor3 = 'OutlineColor' })

		Library:OnHighlight(outer, outer,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		return outer, inner, label
	end

	local function initEvents(button)
		local function waitForEvent(event, timeout, validator)
			local bindable = Instance.new('BindableEvent')
			local connection = event:Once(function(...)
				if type(validator) == 'function' and validator(...) then
					bindable:Fire(true)
				else
					bindable:Fire(false)
				end
			end)
			task.delay(timeout, function()
				connection:disconnect()
				bindable:Fire(false)
			end)
			return bindable.Event:Wait()
		end

		local function validateClick(input)
			if not Library.Toggled then
				return false
			end
			
			if Library:MouseIsOverOpenedFrame() then
				return false
			end

			if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
				return false
			end

			return true
		end

		button.Outer.InputBegan:Connect(function(input)
			if not validateClick(input) or button.Locked then
				return
			end

			if button.DoubleClick then
				Library:RemoveFromRegistry(button.Label)
				Library:AddToRegistry(button.Label, { TextColor3 = 'AccentColor' })

				
				button.Label.Text = 'Are you sure?'
				button.Locked = true

				services.TweenService:Create(button.Label, TweenInfo.new(0.125), {
					TextColor3 = Library.AccentColor
				}):Play();

				task.wait(0.125);

				local clicked = waitForEvent(button.Outer.InputBegan, 2, validateClick)

				Library:RemoveFromRegistry(button.Label)
				Library:AddToRegistry(button.Label, { TextColor3 = 'FontColor' })

				button.Label.TextColor3 = Library.FontColor
				button.Label.Text = button.Text
				task.defer(rawset, button, 'Locked', false)

				if clicked then
					Library:SafeCallback(button.Func)
				end

				return
			end

			Library:SafeCallback(button.Func)
		end)
	end

	function Component.AddButton(self, ...)
		local button = {}
		processButtonParams(button, ...)

		if self.Objects then
			table.insert(self.Objects, {
				internal_name = "button_" .. tostring(#self.Objects + 1), settings = {
					Text = button.Text;
					Tooltip = button.Tooltip;
				}, Type = "Button"
			})
		end

		local groupbox = self
		local container = groupbox.Container

		button.Outer, button.Inner, button.Label = createBaseButton(button)
		button.Outer.Parent = container

		initEvents(button)

		function button:AddTooltip(tooltip)
			if type(tooltip) == 'string' then
				Library:AddToolTip(tooltip, self.Outer)
			end
			return self
		end

		function button:AddButton(...)
			local subButton = {}
			processButtonParams(subButton, ...)

			self.Outer.Size = UDim2.new(0.5, -2, 0, 20)

			subButton.Outer, subButton.Inner, subButton.Label = createBaseButton(subButton)
			subButton.Outer.Position = UDim2.new(1, 3, 0, 0)
			subButton.Outer.Size = UDim2.fromOffset(self.Outer.AbsoluteSize.X / Library:GetUIScale() - 2, self.Outer.AbsoluteSize.Y / Library:GetUIScale())
			subButton.Outer.Parent = self.Outer

			function subButton:AddTooltip(tooltip)
				if type(tooltip) == 'string' then
					Library:AddToolTip(tooltip, self.Outer)
				end
				return subButton
			end

			Library:RegisterSearchEntry(groupbox, {
				Kind = 'Button';
				Text = subButton.Text;
				Target = subButton.Outer;
			})

			if type(subButton.Tooltip) == 'string' then
				subButton:AddTooltip(subButton.Tooltip)
			end

			initEvents(subButton)
			return subButton
		end

		if type(button.Tooltip) == 'string' then
			button:AddTooltip(button.Tooltip)
		end

		groupbox:AddBlank(5)
		groupbox:Resize()

		return button
	end

	function Component.AddDivider(self)
		local groupbox = self
		local container = self.Container

		groupbox:AddBlank(2)
		local dividerOuter = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(1, -4, 0, 5);
			ZIndex = 5;
			Parent = container;
		})

		local dividerInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 6;
			Parent = dividerOuter;
		})

		Library:AddToRegistry(dividerOuter, { BorderColor3 = 'Black' })
		Library:AddToRegistry(dividerInner, { BackgroundColor3 = 'MainColor'; BorderColor3 = 'OutlineColor' })

		groupbox:AddBlank(9)
		groupbox:Resize()
end

	return Component
end
end)
