    end;

    function Logger.log(...)
        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        -- restore: консольный вывод убран полностью. Сообщение уходит только
        -- в инфо-логгер меню (Library) — он в консоль не пишет.
        if Library then
            Library:AddTextToInfoLogger("[I]: " .. message, "[I]: " .. message, nil)
