__bundle_register("@src/utility/queue", function(require, _LOADED, __bundle_register, __bundle_modules)
local queue = {} do
    queue.__index = queue;

    function queue.new()
        local self = setmetatable({}, queue);

        self.tasks = {};

        return self    
end

    function queue:push(task)
        table.insert(self.tasks, task);
    end

    function queue:pop()
        return table.remove(self.tasks, 1)    
end

    function queue:empty()
        return #self.tasks == 0    
end
end

return queue
end)
__bundle_register("@src/utility/safety", function(require, _LOADED, __bundle_register, __bundle_modules)

local Safety = {};

function Safety:MobsNear(part : BasePart | CFrame, distance): number
    if not distance then distance = 200; end

    local players_near = 0;
    for _, mob in workspace.Live:GetChildren() do
        if not mob:FindFirstChild("HumanoidRootPart") then continue end;
        
        local mob_distance = (part.Position - mob:GetPivot().Position).Magnitude;
        if mob_distance <= distance then
            players_near = players_near + 1;
        end;
    end;
    
    return players_near
end;

function Safety:PlayersNear(part : BasePart | CFrame, distance): number
    if not distance then distance = 200; end

    local players_near = 0;
    for _, player in services.Players:GetPlayers() do
        if player == local_player.instance then continue end;
        if not player.Character then continue end;
        
        local player_distance = (part.Position - player.Character:GetPivot().Position).Magnitude;
        if player_distance <= distance then
            players_near = players_near + 1;
        end;
    end;
    
    return players_near
end;

function Safety:PlayerNear(magnitude): boolean
    if not magnitude then magnitude = 300; end
    
    for _, player in services.Players:GetPlayers() do
        if player == local_player.instance then continue end
        if not player.Character then continue end
        
        local dist = (local_player.root_part.Position - player.Character:GetPivot().Position).Magnitude
        if dist <= magnitude then
            return true
        end
    end
    
    return false
end

function Safety:PlayerSafeTween(cf, speed, ylevel)
    local function serverhop()
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, 'any', true)
    end

    if not speed then speed = 250; end
    
    if self:PlayerNear() then
        serverhop()
        while task.wait() do end
    end
    
    if not ylevel then
        ylevel = math.random(8000, 10000)
    end
    
    local_player.root_part.CFrame = local_player.root_part.CFrame + Vector3.new(0, local_player.root_part.CFrame.Y + ylevel, 0)
    
    Tween.new(cf + Vector3.new(0, cf.Y + ylevel, 0), true, speed).wait()
    
    
    if self:PlayersNear(cf, 200) > 0 then
        serverhop()
        while task.wait() do end
    end
    
    
    local_player.root_part.CFrame = cf
end

function Safety:InDanger(): boolean
    return (local_player.humanoid:GetAttribute("DangerExpiration") and local_player.humanoid:GetAttribute("DangerExpiration") > 0)
end

return Safety
end)
__bundle_register("@src/utility/safe_hooks", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Безопасная установка хуков метаметодов.
--
-- Часть исполнителей умеет ставить хук в параллельную фазу
-- (parallel_hooks_allowed). Часть — нет, и там вызов hookmetamethod может
-- быть отдан Actor-параллельному потоку. Это недопустимый cross-phase вызов,
-- на котором ядро паникует (Kernel panic) — то есть падает не хук, а клиент.
--
-- Поэтому: если parallel_hooks_allowed не объявлен, __newindex ставится
-- подменой поля метатаблицы под setreadonly. Это обычный table-патч, он
-- синхронный и параллельной фазе не подвержен.
--
-- Взято из Luma-main/Features/Combat/ForceAutoRotate.lua — там же на нём
-- держится установка хука на __newindex.

local safe_hooks = {}

-- true, если хук метаметода можно ставить обычным способом
function safe_hooks.can_use_hookmetamethod()
    if parallel_hooks_allowed ~= nil then
        return parallel_hooks_allowed == true
    end
    return type(hookmetamethod) == "function"
end

--- Ставит хук на метаметод.
---@param target table
---@param method string  "__index" / "__newindex" / ...
---@param hook function
---@return function|nil original  nil, если хук не поставился
function safe_hooks.set(target, method, hook)
    if type(target) ~= "table" and typeof(target) ~= "table" then
        return nil
    end

    -- обычный путь
    if safe_hooks.can_use_hookmetamethod() and type(hookmetamethod) == "function" then
        local ok, original = pcall(hookmetamethod, target, method, hook)
        if ok then return original end
    end

    -- запасной путь: патч метатаблицы под setreadonly
    local ok_mt, mt = pcall(getrawmetatable, target)
    if not ok_mt or type(mt) ~= "table" then return nil end

    local original = rawget(mt, method)

    local ok = pcall(function()
        if type(setreadonly) == "function" then setreadonly(mt, false) end
        rawset(mt, method, hook)
        if type(setreadonly) == "function" then setreadonly(mt, true) end
    end)

    -- если setreadonly/патч не сработали — не оставляем объект в грязи
    if not ok then
        pcall(function()
            if type(setreadonly) == "function" then setreadonly(mt, false) end
            rawset(mt, method, original)
            if type(setreadonly) == "function" then setreadonly(mt, true) end
        end)
        return nil
    end

    return original
end

--- Снимает хук, поставленный safe_hooks.set.
---@param target table
---@param method string
---@param original any  то, что вернул set
function safe_hooks.remove(target, method, original)
    if original == nil then return end
    if safe_hooks.can_use_hookmetamethod() and type(hookmetamethod) == "function" then
        pcall(hookmetamethod, target, method, original)
        return
    end
    local ok, mt = pcall(getrawmetatable, target)
    if ok and type(mt) == "table" then
        pcall(function()
            if type(setreadonly) == "function" then setreadonly(mt, false) end
            rawset(mt, method, original)
            if type(setreadonly) == "function" then setreadonly(mt, true) end
        end)
    end
end

return safe_hooks
end)
__bundle_register("@src/utility/scheduler", function(require, _LOADED, __bundle_register, __bundle_modules)

local scheduler = {};
local tasks = {};

function scheduler:add_task(every)
    local task = {
        event = Instance.new("BindableEvent"),
        every = every,
        last_run = 0
    };
    table.insert(tasks, task);

    return task.event.Event
end

function scheduler.run()
    local current_time = tick();
    for _, task in tasks do
        if current_time - task.last_run >= task.every then
            task.event:Fire();
            task.last_run = current_time;
        end
    end
end

aztup.maid:give_task(services.RunService.Heartbeat:Connect(scheduler.run))

return scheduler
end)
