local m1Hold
local struct = nil
local maid = Maid.new()

local screenGui, elapsedLabel = nil, nil

-- =========================================================================================================
-- Accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end

local function character()
	local lp = localPlayer()
	return lp and lp.Character
end

local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end

local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end

local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end

local function isRunning()
	return running
end

function AutoAuthority.inValidPlace()
	return game.PlaceId == AUTHORITY_PLACE_ID
end

local function getEffectReplicator()
	local ok, mod = pcall(function()
		return require(replicatedStorage:WaitForChild("EffectReplicator"))
	end)
	return ok and mod or nil
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end

local function mk(class, props, parent)
	local instance = Instance.new(class)
	for key, value in pairs(props) do
		instance[key] = value
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end

local function buildOverlay()
	if screenGui then
		return
	end
	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "LumaAutoAuthorityOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999
	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })

	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Authority",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })

	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })

	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoAuthority.stop()
	end)

	pcall(function()
		Library:MakeDraggable(outer)
	end)
end

local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end

-- Stage text was removed; kept as a no-op so the many callers don't need changing.
local function setStage(_) end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("authoritydata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Movement.
-- =========================================================================================================
local function setSpeed(value)
	value = (Options and Options.AuthorityTweenSpeed and Options.AuthorityTweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end

---Blocking tween to a CFrame (PR's Tween.new(cf, true, speed).wait()).
local function tweenTo(cframe, speed, deadline, continueWhile)
	while running and safetyHold do
		if deadline and os.clock() >= deadline then
			return false
		end
		if continueWhile and not continueWhile() then
			return false
		end
		task.wait()
	end
	if not running then
		return false
	end

	setSpeed(speed or TWEEN_SPEED)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		if deadline and os.clock() >= deadline then
			Tweening.stop(MOVE_ID)
			return false
		end
		if continueWhile and not continueWhile() then
			Tweening.stop(MOVE_ID)
			return false
		end
		if safetyHold then
			Tweening.stop(MOVE_ID)
			repeat
				if deadline and os.clock() >= deadline then
					return false
				end
				task.wait()
			until not running or not safetyHold
			if not running then
				return false
			end
			Tweening.goal(MOVE_ID, cframe, false)
		end
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 4 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
	return running
end

local function serverHop()
	local ok, err = pcall(function()
		ServerHop.hop(currentSlot(), true)
	end)
	if not ok then
		Logger.warn("Auto Authority server hop failed:", tostring(err))
	end
	return ok
end

-- =========================================================================================================
-- Captain Trist interaction + mission identification.
-- =========================================================================================================
local sendDialogue = nil
local dialogueOpen = false -- PR's `got`
local dialogueFires = 0 -- PR's `fc`

local function connectDialogueListener()
	if sendDialogue then
		return
	end
	pcall(function()
		sendDialogue = replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue")
		maid:mark(sendDialogue.OnClientEvent:Connect(function(v)
			dialogueOpen = not (v and v.exit)
			dialogueFires = dialogueFires + 1
		end))
	end)
end

local function fireDialogue(payload)
	if sendDialogue and not safetyHold then
		pcall(function()
			sendDialogue:FireServer(payload)
		end)
	end
end

---Tween to Captain Trist and fire his prompt until the dialogue opens.
local function reachTrist(deadline, continueWhile)
	setStage("talking to Captain Trist")
	repeat
		if not tweenTo(TRIST_HIGH, TWEEN_SPEED, deadline, continueWhile)
			or not tweenTo(TRIST_LOW, TWEEN_SPEED, deadline, continueWhile)
		then
			return false
		end
		local npcs = workspace:FindFirstChild("NPCs")
		local trist = npcs and npcs:FindFirstChild("Captain Trist")
		local prompt = trist and trist:FindFirstChild("InteractPrompt")
		if prompt and prompt:IsA("ProximityPrompt") and not safetyHold then
			Prompt.fire(prompt)
		end
		task.wait(MISSION_SCAN_INTERVAL)
	until dialogueOpen or not running or (deadline and os.clock() >= deadline)
		or (continueWhile and not continueWhile())
	return dialogueOpen and running and (not continueWhile or continueWhile())
end

---Close any open dialogue (fire exit until the DialogueGui closes).
local function exitDialogue()
	local start = tick()
	repeat
		fireDialogue({ exit = true })
		task.wait(0.5)
	until not (playerGui() and playerGui():FindFirstChild("DialogueGui") and playerGui().DialogueGui.Enabled)
		or not running
		or tick() - start > 8
end

---Identify the accepted job by scanning Terrain for the JobTrackerGui attachment. Returns jobType, cframe.
local function identifyJob()
	local terrain = workspace:FindFirstChild("Terrain")
	if not terrain then
		return nil, nil
	end
	local deadline = os.clock() + 8
	repeat
		for _, entity in next, terrain:GetDescendants() do
			if entity:IsA("Attachment") then
				local jobTracker = entity:FindFirstChild("JobTrackerGui")
				local textLabel = jobTracker and jobTracker:FindFirstChild("TextLabel")
				if textLabel then
					local text = textLabel.Text
					local jobType = (text:find("Hostage") and "hostage")
						or (text:lower():find("secure") and "secure")
						or (text:find("Armanent Sabotage") and "barrels")
					if jobType then
						return jobType, entity.CFrame
					end
				end
			end
		end
		task.wait(JOB_SCAN_INTERVAL)
	until os.clock() >= deadline or not running
	return nil, nil
end

local function wantsJob(jobType)
	local map = {
		hostage = { "AuthorityHostage", "hostage" },
		barrels = { "AuthorityBarrels", "barrels" },
		secure = { "AuthoritySecure", "secure" },
	}
	local toggle = map[jobType]
	if not toggle then
		return false
	end
	local control = Toggles and Toggles[toggle[1]]
	if control then
		return control.Value == true
	end
	local saved = PersistentData.get("authorityMissionToggles")
	return type(saved) ~= "table" or saved[toggle[2]] ~= false
end

m1Hold = function(state)
	if state and safetyHold then
		state = false
	end
	local feat = struct and struct.active_features and struct.active_features["m1_hold"]
	if feat then
		feat.held = state
	end
end

-- =========================================================================================================
-- Missions.
-- =========================================================================================================
local function splashSaysReportBack()
	local gui = playerGui() and playerGui():FindFirstChild("SplashGui")
	local frame = gui and gui:FindFirstChild("TimeFrame")
	local label = frame and frame:FindFirstChild("TimeText")
	return label ~= nil and label.Text:lower():find("report back") ~= nil
end

local function missionHostage(object)
	setStage("mission: hostage")
	local deadline = os.clock() + HOSTAGE_MISSION_TIMEOUT

	local function shouldAbort()
		if os.clock() >= deadline then
			return "timed out after " .. HOSTAGE_MISSION_TIMEOUT .. " seconds"
		end
		local humanoid = character() and character():FindFirstChildOfClass("Humanoid")
		if humanoid and humanoid.MaxHealth > 0
			and humanoid.Health <= humanoid.MaxHealth * HOSTAGE_LOW_HEALTH_RATIO
		then
			return "health dropped below 25%"
		end
		return nil
	end

	local function abort(reason)
		m1Hold(false)
		if reason == "health dropped below 25%" then
			Tweening.stop(MOVE_ID)
			local currentRoot = root()
			if currentRoot then
				currentRoot.CFrame = CFrame.new(
					currentRoot.Position.X,
					3000,
					currentRoot.Position.Z
				)
			end
		end
		Logger.warn("Auto Authority hostage mission aborted:", reason)
		serverHop()
		return false
	end

	exitDialogue()

	local abortReason = shouldAbort()
	if abortReason then
		return abort(abortReason)
	end

	if not tweenTo(object * CFrame.new(0, 2000, 0), TWEEN_SPEED, deadline)
		or not tweenTo(object, TWEEN_SPEED, deadline)
	then
		if not running then
			return false
		end
		abortReason = shouldAbort()
		return abort(abortReason or "movement interrupted")
	end

	local live = workspace:FindFirstChild("Live")
	local hostage
	repeat
		local abortReason = shouldAbort()
		if abortReason then
			return abort(abortReason)
		end
		for _, entity in next, (live and live:GetChildren() or {}) do
			if entity.Name:find("%.hostage") and entity:FindFirstChild("HumanoidRootPart") then
				if (entity.HumanoidRootPart.Position - (root() and root().Position or Vector3.zero)).Magnitude <= 1000 then
					if not tweenTo(entity.HumanoidRootPart.CFrame, TWEEN_SPEED, deadline) then
						local abortReason = shouldAbort()
						if abortReason then
							return abort(abortReason)
						end
						return false
					end
					hostage = entity
					break
				end
			end
		end
		task.wait(MISSION_SCAN_INTERVAL)
	until hostage or not running
	if not hostage then
		return false
	end

	if not tweenTo(hostage.HumanoidRootPart.CFrame, TWEEN_SPEED, deadline) then
		local abortReason = shouldAbort()
		if abortReason then
			return abort(abortReason)
		end
		return false
	end

	local er = getEffectReplicator()
	local lastCarryRequest = 0
	local function carryingOrDelivered()
		return dialogueOpen or (er and er:FindEffect("Carrying") ~= nil)
	end
	while running do
		local abortReason = shouldAbort()
		if abortReason then
			return abort(abortReason)
		end
		local carrying = er and er:FindEffect("Carrying")
		if carrying then
			local currentRoot = root()
			if currentRoot and currentRoot.Position.Y < 1996 then
				if not tweenTo(
					CFrame.new(currentRoot.Position.X, 2000, currentRoot.Position.Z),
					TWEEN_SPEED,
					deadline,
					carryingOrDelivered
				) then
					abortReason = shouldAbort()
					if abortReason then
						return abort(abortReason)
					end
				end
			end
			if carryingOrDelivered() and reachTrist(deadline, carryingOrDelivered) then
				return true
			end
		else
			local hostageRoot = hostage and hostage.Parent and hostage:FindFirstChild("HumanoidRootPart")
			if hostageRoot then
				local currentRoot = root()
				if currentRoot and (currentRoot.Position - hostageRoot.Position).Magnitude > 10 then
					if not tweenTo(hostageRoot.CFrame, TWEEN_SPEED, deadline) then
						abortReason = shouldAbort()
						if abortReason then
							return abort(abortReason)
						end
					end
				end
			end
			local handler = character() and character():FindFirstChild("CharacterHandler")
			local requests = handler and handler:FindFirstChild("Requests")
			local carry = requests and requests:FindFirstChild("Carry")
			local now = tick()
			if carry and now - lastCarryRequest >= 4 then
				lastCarryRequest = now
				if not safetyHold then
					pcall(function()
						carry:FireServer()
					end)
				end
			end
		end
		task.wait(MISSION_SCAN_INTERVAL)
	end
	return false
end

local function missionBarrels(object)
	setStage("mission: barrels")
	exitDialogue()

	if not safetyHold then
		pcall(function()
			character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
		end)
	end
	tweenTo(object * CFrame.new(0, 1500, 0), TWEEN_SPEED)
	tweenTo(object * CFrame.new(0, 200, 0), TWEEN_SPEED)

	local destructibles = workspace:FindFirstChild("Destructibles")
	while running do
		if splashSaysReportBack() then
			break
		end
		local crates = {}
		local crateDistances = {}
		local rp = root() and root().Position or Vector3.zero
		if destructibles then
			for _, crate in next, destructibles:GetChildren() do
				if crate.Name:find("KhanCrate") and crate:IsA("Model") then
					local pivot = crate:GetPivot().Position
					local distance = (Vector3.new(pivot.X, 0, pivot.Z) - Vector3.new(rp.X, 0, rp.Z)).Magnitude
					if distance < 1200 then
						table.insert(crates, crate)
						crateDistances[crate] = distance
					end
				end
			end
		end
		table.sort(crates, function(a, b)
			return crateDistances[a] < crateDistances[b]
		end)
		for _, crate in ipairs(crates) do
			while running and crate:GetAttribute("StructureHealth") and crate:GetAttribute("StructureHealth") > 0 do
				m1Hold(true)
				tweenTo(CFrame.new((crate:GetPivot() * CFrame.new(0, -5, 0)).Position) * CFrame.Angles(math.rad(90), 0, 0), TWEEN_SPEED)
				task.wait(MISSION_SCAN_INTERVAL)
			end
			m1Hold(false)
		end
		task.wait(MISSION_SCAN_INTERVAL)
	end
	m1Hold(false)

	reachTrist()
end

local function missionSecure(object)
	setStage("mission: secure")

	tweenTo(object * CFrame.new(0, 1500, 0), TWEEN_SPEED)
	tweenTo(object, TWEEN_SPEED)

	local banner
	repeat
		for _, model in next, workspace:GetChildren() do
			if model.Name == "Authority Checkpoint" and model:IsA("Model") then
				local pivot = model:GetPivot().Position
				local rp = root() and root().Position or Vector3.zero
				if (Vector3.new(pivot.X, 0, pivot.Z) - Vector3.new(rp.X, 0, rp.Z)).Magnitude < 1200 then
					banner = model
				end
			end
		end
		task.wait(MISSION_SCAN_INTERVAL)
	until banner or not running
	if not banner then
		return
	end

	-- PR's 3-phase capture loop: sit on the banner (0-35s), fly high above it (35-125s), sit again
	-- (125-155s), each phase bailing out the moment the objective completes ("report back").
	while running do
		tweenTo(banner:GetPivot() * CFrame.new(0, 8, 0), TWEEN_SPEED)
		local start = tick()
		local stop = false

		repeat
			task.wait(MISSION_SCAN_INTERVAL)
			if splashSaysReportBack() then
				stop = true
				break
			end
		until tick() - start > 35 or not running
		if stop then
			break
		end

		repeat
			task.wait(MISSION_SCAN_INTERVAL)
			if splashSaysReportBack() then
				stop = true
				break
			end
			tweenTo(banner:GetPivot() * CFrame.new(0, 3000, 0), TWEEN_SPEED)
		until tick() - start > 90 + 35 or not running
		if stop then
			break
		end

		repeat
			task.wait(MISSION_SCAN_INTERVAL)
			if splashSaysReportBack() then
				stop = true
				break
			end
			tweenTo(banner:GetPivot() * CFrame.new(0, 8, 0), TWEEN_SPEED)
		until tick() - start > 120 + 35 or not running
		if stop then
			break
		end

		if splashSaysReportBack() then
			break
		end
	end

	reachTrist()
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local function runPlayerSafeWatch()
	-- Pause mission activity while a nearby player is a threat, then hop after Danger clears or they leave.
	maid:mark(task.spawn(function()
		local er = getEffectReplicator()
		local radius = math.max(PLAYER_SAFE_RADIUS, AutoLog.get("auto_authority"))

		local function nearbyPlayer()
			local r = root()
			if not r then
				return nil
			end
			local position = Vector3.new(r.Position.X, 0, r.Position.Z)
			for _, player in ipairs(players:GetPlayers()) do
				if player ~= localPlayer() then
					local otherRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
					if otherRoot then
						local otherPosition = Vector3.new(otherRoot.Position.X, 0, otherRoot.Position.Z)
						if (position - otherPosition).Magnitude <= radius then
							return player
						end
					end
				end
			end
			return nil
		end

		while running do
			if nearbyPlayer() then
				safetyHold = true
				m1Hold(false)
				Tweening.stop(MOVE_ID)
				if er and er:HasEffect("Danger") then
					repeat
						local r = root()
						if r then
							r.CFrame = CFrame.new(r.CFrame.X, 3000, r.CFrame.Z)
						end
						task.wait(0.1)
					until not running or not nearbyPlayer() or not (er and er:HasEffect("Danger"))
				end
				if not running then
					return
				end
				if not serverHop() then
					safetyHold = false
					task.wait(1)
				else
					return
				end
			end
			task.wait(MISSION_SCAN_INTERVAL)
		end
	end))
end

local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "continuation", from = "_check_area", to = "_check_area" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			if game.PlaceId ~= AUTHORITY_PLACE_ID then
				return
			end

			pcall(function()
				replicatedStorage:WaitForChild("Requests"):WaitForChild("UpdateUXSettings"):FireServer("FriendlyFire", true)
			end)

			connectDialogueListener()

			-- Talk to Captain Trist + accept the job.
			reachTrist()
			if not running then
				return
			end

			-- Advance past the intro with "Yes, Sir." until the dialogue state moves on.
			setStage("accepting job")
			local startFires = dialogueFires
			repeat
				fireDialogue({ choice = "Yes, Sir." })
				task.wait(MISSION_SCAN_INTERVAL)
			until startFires ~= dialogueFires or not running

			-- Background: keep the conversation closed once accepted.
			maid:mark(task.spawn(function()
				while running and dialogueOpen do
					fireDialogue({ exit = true })
					task.wait(MISSION_SCAN_INTERVAL)
				end
			end))

			-- Figure out which job we accepted.
			setStage("identifying job")
			local jobType, object = identifyJob()

			if not jobType or not object or not wantsJob(jobType) then
				-- Rejoining is faster than doing an unwanted job.
				serverHop()
				return
			end

			if jobType == "hostage" then
				if not missionHostage(object) then
					return
				end
			elseif jobType == "barrels" then
				missionBarrels(object)
			elseif jobType == "secure" then
				missionSecure(object)
			end

			exitDialogue()
			self:continuation()
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_authority",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"fly",
			"noclip",
			"no_fall",
			"no_kill_bricks",
			"m1_hold",
			"no_fire",
			"auto_equip_weapon",
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoAuthority.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	if not AutoAuthority.inValidPlace() then
		return Logger.notify("Auto Authority: not in the Eastern Luminant.")
	end

	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Authority: no data slot found.")
	end

	local data = PersistentData.get("authoritydata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("authoritydata", data)

	running = true
	safetyHold = false
	dialogueOpen = false
	dialogueFires = 0
	buildOverlay()
	AntiAFK.start("AutoAuthority")

	maid:mark(task.spawn(runElapsed))
	runPlayerSafeWatch()

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoAuthority.stop()
	if not running then
		return
	end
	running = false

	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end

	Tweening.stop(MOVE_ID)
	pcall(function()
		AntiAFK.stop("AutoAuthority")
	end)

	maid:clean()
	sendDialogue = nil
	destroyOverlay()

	PersistentData.set("authoritydata", nil)
end

return AutoAuthority

end)
__bundle_register("@luma/Features/Automation/AutoBuilder", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Builder: fetch + parse a deepwoken.co build link into a normalized table the automation can
-- act on. deepwoken.co is a Nuxt app that proxies its API through its own origin
-- (`/api/proxy/builds/<id>`), so no auth token is needed -- just browser-ish headers or it 403s.

---@module Utility.JSON
local JSON = require("@luma/Utility/JSON")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Utility.Signal
local Signal = require("@luma/Utility/Signal")

---@module Features.Visuals.Objects.BuilderData
local BuilderData = require("@luma/Features/Visuals/Objects/BuilderData")

---@module Utility.PersistentData
local PersistentData = require("@luma/Utility/PersistentData")

local players = game:GetService("Players")
local runService = game:GetService("RunService")

local AutoBuilder = {}

local PROXY_BASE = "https://deepwoken.co/api/proxy/builds/"
local GAMEDATA_URL = "https://deepwoken.co/api/proxy/get?type=all"

-- The proxy rejects requests without a browser-looking Origin/Referer/User-Agent.
local USER_AGENT = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
	.. "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"

-- The most recently loaded + parsed build, and which stat/talent set the script targets.
---@type table?
AutoBuilder.current = nil
---@type "pre"|"post"
AutoBuilder.target = "pre"

-- When true, the picking loop clicks talent/mantra cards as they appear.
AutoBuilder.picking = false

-- The id of the currently loaded build (used to persist + resume across server hops).
AutoBuilder.loadedId = nil

---The player's current data slot, or nil.
---@return any
function AutoBuilder.currentSlot()
	local localPlayer = players.LocalPlayer
	return localPlayer and localPlayer:GetAttribute("DataSlot")
end

-- Persist the active state (link + target + slot) so a server hop resumes it on the same character.
local function persist()
	PersistentData.set("abdata", {
		active = AutoBuilder.picking and true or false,
		id = AutoBuilder.loadedId,
		target = AutoBuilder.target,
		slot = AutoBuilder.currentSlot(),
	})
end

-- Fire the UI state-changed hook (refreshes the Start/Stop button), if one is registered.
local function notifyState()
	if AutoBuilder.onStateChanged then
		pcall(AutoBuilder.onStateChanged)
	end
end

---Resolve the executor's HTTP request function across the common names.
---@return function?
local function getRequester()
	if type(request) == "function" then
		return request
	elseif type(http_request) == "function" then
		return http_request
	elseif syn and type(syn.request) == "function" then
		return syn.request
	elseif http and type(http.request) == "function" then
		return http.request
	end

	return nil
end

---Pull the build id out of anything the user might paste: a full builder URL, a share URL, or the
---raw id on its own.
---@param input string
---@return string?
function AutoBuilder.extractId(input)
	if type(input) ~= "string" then
		return nil
	end

	input = input:gsub("%s+", "")

	if input == "" then
		return nil
	end

	local id = input:match("[?&]id=([%w%-_]+)")
		or input:match("/builds/([%w%-_]+)")
		or input:match("/builder/([%w%-_]+)")

	-- A bare id (no URL wrapping) -- accept it as-is.
	if not id and input:match("^[%w%-_]+$") then
		id = input
	end

	return id
end

---Fetch a URL and return the decoded JSON table (or nil, err). Sends browser-ish headers because the
---deepwoken.co proxy 403s without them.
---@param url string
---@param referer string
---@return table?, string?
local function httpGetJson(url, referer)
	local requester = getRequester()
	if not requester then
		return nil, "This executor has no HTTP request function."
	end

	local ok, response = pcall(requester, {
		Url = url,
		Method = "GET",
		Headers = {
			["Accept"] = "application/json",
			["Origin"] = "https://deepwoken.co",
			["Referer"] = referer,
			["User-Agent"] = USER_AGENT,
		},
	})

	if not ok or not response then
		return nil, "Request failed (network/executor error)."
	end

	local status = response.StatusCode or response.Status or 0
	if status == 404 then
		return nil, "Not found (404)."
	elseif status ~= 200 then
		return nil, string.format("Server returned %s.", tostring(status))
	end

	local body = response.Body
	if not body or body == "" then
		return nil, "Empty response body."
	end

	local decodeOk, decoded = pcall(JSON.decode, body)
	if not decodeOk or type(decoded) ~= "table" then
		return nil, "Couldn't parse JSON."
	end

	return decoded, nil
end

-- The raw master game-data dump (talents/mantras/etc.), fetched once and cached.
AutoBuilder.gameDump = nil

---Fetch (once, cached) deepwoken's master data dump (the `get?type=all` payload).
---@return table?, string?
function AutoBuilder.fetchGameData()
	if AutoBuilder.gameDump then
		return AutoBuilder.gameDump, nil
	end

	local dump, err = httpGetJson(GAMEDATA_URL, "https://deepwoken.co/builder")
	if not dump then
		return nil, err
	end

	AutoBuilder.gameDump = dump

	return dump, nil
end

---Fetch the raw build JSON by id. Returns (buildJson, nil) or (nil, errorMessage).
---@param id string
---@return table?, string?
function AutoBuilder.fetch(id)
	if not id or id == "" then
		return nil, "No build id."
	end

	local build, err = httpGetJson(PROXY_BASE .. id, "https://deepwoken.co/builder?id=" .. id)
	if not build then
		if err == "Not found (404)." then
			return nil, "Invalid link"
		end
		return nil, err
	end

	return build, nil
end

---Load a build from anything the user pasted (URL or id), store it as the current build, and return
---(build, nil) or (nil, errorMessage). Notifies the user either way.
---@param input string
---@return table?, string?
function AutoBuilder.load(input)
	-- Nothing pasted (e.g. an empty box restored by a config load) -> do nothing, silently. We only
	-- complain when there's actual text that failed to parse.
	if type(input) ~= "string" or input:gsub("%s+", "") == "" then
		return nil, "Empty."
	end

	local id = AutoBuilder.extractId(input)
	if not id then
		Logger.notify("Auto Builder: couldn't find a build id in that link.")
		return nil, "No id."
	end

	local buildJson, err = AutoBuilder.fetch(id)
	if not buildJson then
		Logger.notify("Auto Builder: " .. tostring(err))
		return nil, err
	end

	local dump, dumpErr = AutoBuilder.fetchGameData()
	if not dump then
		Logger.notify("Auto Builder: " .. tostring(dumpErr))
		return nil, dumpErr
	end

	-- Reuse Build Assistance's data objects: BuilderData wraps DeepwokenData (ddata) plus the pre/post
	-- AttributeData spreads, cleaned talent/mantra lists, and traits.
	local bdata = BuilderData.new(buildJson, dump)

	local stats = buildJson.stats or {}
	local meta = stats.meta or {}

	local build = {
		id = id,
		name = stats.buildName or "Unnamed Build",
		meta = {
			Origin = meta.Origin or "None",
			Oath = meta.Oath or "None",
		},
		pre = bdata.pre, -- AttributeData: .base / .weapon / .attunement
		post = bdata.post,
		talents = bdata.talents,
		mantras = bdata.mantras,
		traits = bdata.traits,
		bdata = bdata,
	}

	AutoBuilder.current = build
	AutoBuilder.loadedId = id

	local classified = AutoBuilder.classify(build)
	AutoBuilder.classified = classified

	-- If we're mid-run (e.g. a reload while active), keep the persisted state current.
	if AutoBuilder.picking then
		persist()
	end

	Logger.notify(
		string.format(
			"Auto Builder: loaded \"%s\" (%d talents, %d mantras).",
			build.name,
			#build.talents,
			#build.mantras
		)
	)

	return build, nil
end

---@param target "pre"|"post"
function AutoBuilder.setTarget(target)
	if target ~= "pre" and target ~= "post" then
		return
	end

	AutoBuilder.target = target

	if AutoBuilder.picking then
		persist()
	end

	notifyState()
end

---Start the automation (picking + investment) and persist it for server-hop resume.
function AutoBuilder.startPicking()
	AutoBuilder.picking = true
	persist()
	notifyState()
end

---Stop the automation and clear the persisted resume state.
function AutoBuilder.stopPicking()
	AutoBuilder.picking = false
	PersistentData.set("abdata", nil)
	notifyState()
end

---Resume a persisted Auto Builder session after a server hop. Only resumes if it was active and on
---the same data slot. Returns the reloaded build, or nil.
---@return table?
function AutoBuilder.resume()
	local data = PersistentData.get("abdata")
	if type(data) ~= "table" or not data.active or not data.id then
		return nil
	end

	-- Only resume on the same slot it was started on (a different character shouldn't inherit it).
	local slot = AutoBuilder.currentSlot()
	if data.slot ~= nil and slot ~= nil and slot ~= data.slot then
		return nil
	end

	AutoBuilder.setTarget(data.target == "post" and "post" or "pre")

	local build = AutoBuilder.load(data.id)
	if not build then
		return nil
	end

	AutoBuilder.startPicking()

	return build
end

-- ============================================================================================
-- Preshrine / postshrine split.
--
-- Uses Build Assistance's obtainability check (bdata.ddata:possible(name, spread)), which resolves
-- each talent/mantra's requirements against an AttributeData spread. A talent belongs to the
-- preshrine column when it's obtainable at the pre-shrine spread but NOT at the post-shrine spread
-- (you'd lose access after the Shrine of Order, so grab it first). Everything else is postshrine.
-- ============================================================================================

---Split the loaded build's talents + mantras into preshrine/postshrine columns.
---@param build table
---@return table? { pre = { talents = {}, mantras = {} }, post = { talents = {}, mantras = {} } }
function AutoBuilder.classify(build)
	local bdata = build and build.bdata
	if not bdata then
		return nil
	end

	local result = {
		pre = { talents = {}, mantras = {} },
		post = { talents = {}, mantras = {} },
	}

	local function place(bucket, name)
		local canPre = bdata.ddata:possible(name, bdata.pre)
		local canPost = bdata.ddata:possible(name, bdata.post)

		if canPre and not canPost then
			table.insert(result.pre[bucket], name)
		else
			table.insert(result.post[bucket], name)
		end
	end

	for _, talent in ipairs(bdata.talents) do
		place("talents", talent)
	end

	for _, mantra in ipairs(bdata.mantras) do
		place("mantras", mantra)
	end

	return result
end

-- ============================================================================================
-- Talent / mantra card picking.
--
-- The game shows talent/mantra cards as TextButtons under PlayerGui.TalentGui.ChoiceFrame, each named
-- after the talent/mantra it grants. Rather than clicking, we fire the exact remote the game's own
-- TalentClient fires on a card click:
--     ReplicatedStorage.Requests.TalentChoice:InvokeServer(cardName, isSpecial)
-- where isSpecial is true only for a "special" hand (resonance/foretold gift). We still read the card
-- buttons to know what's on offer and apply the build's priority: preshrine, then postshrine, then a
-- random real card.
-- ============================================================================================

local replicatedStorage = game:GetService("ReplicatedStorage")

local renderStepped = Signal.new(runService.RenderStepped)
local pickMaid = Maid.new()
local pickCooldownUntil = 0
local pickBusy = false
local investCooldownUntil = 0
local investBusy = false

---@return Instance? PlayerGui.TalentGui
local function getTalentGui()
	local playerGui = players.LocalPlayer and players.LocalPlayer:FindFirstChild("PlayerGui")
	return playerGui and playerGui:FindFirstChild("TalentGui")
end

---@return Instance? ReplicatedStorage.Requests.TalentChoice
local function getTalentChoiceRemote()
	local requests = replicatedStorage:FindFirstChild("Requests")
	return requests and requests:FindFirstChild("TalentChoice")
end

-- ============================================================================================
-- Point investment.
--
-- Each +1 to an attribute fires ReplicatedStorage.Requests.IncreaseAttribute:InvokeServer(<arg>),
-- where <arg> is the character attribute name minus the "Stat_" prefix (e.g. "Agility",
-- "WeaponMedium", "ElementWind"). We read the current value from the character's Stat_* attribute and
-- fire one increment at a time toward the target spread, so the server validates each point and we
-- never overshoot.
-- ============================================================================================

-- Ordered invest targets: { stat = <character attribute>, arg = <remote argument>, group, key }.
local INVEST_TARGETS = {
	-- Weapons + attunements first (they gate the most talents), then base attributes.
	{ group = "weapon", key = "Light Wep.", stat = "Stat_WeaponLight", arg = "WeaponLight" },
	{ group = "weapon", key = "Medium Wep.", stat = "Stat_WeaponMedium", arg = "WeaponMedium" },
	{ group = "weapon", key = "Heavy Wep.", stat = "Stat_WeaponHeavy", arg = "WeaponHeavy" },

	{ group = "attunement", key = "Flamecharm", stat = "Stat_ElementFire", arg = "ElementFire" },
	{ group = "attunement", key = "Frostdraw", stat = "Stat_ElementIce", arg = "ElementIce" },
	{ group = "attunement", key = "Thundercall", stat = "Stat_ElementLightning", arg = "ElementLightning" },
	{ group = "attunement", key = "Galebreathe", stat = "Stat_ElementWind", arg = "ElementWind" },
	{ group = "attunement", key = "Shadowcast", stat = "Stat_ElementShadow", arg = "ElementShadow" },
	{ group = "attunement", key = "Ironsing", stat = "Stat_ElementMetal", arg = "ElementMetal" },
	{ group = "attunement", key = "Bloodrend", stat = "Stat_ElementBlood", arg = "ElementBlood" },

	{ group = "base", key = "Strength", stat = "Stat_Strength", arg = "Strength" },
	{ group = "base", key = "Fortitude", stat = "Stat_Fortitude", arg = "Fortitude" },
	{ group = "base", key = "Agility", stat = "Stat_Agility", arg = "Agility" },
	{ group = "base", key = "Intelligence", stat = "Stat_Intelligence", arg = "Intelligence" },
	{ group = "base", key = "Willpower", stat = "Stat_Willpower", arg = "Willpower" },
	{ group = "base", key = "Charisma", stat = "Stat_Charisma", arg = "Charisma" },
}

---@return Instance? ReplicatedStorage.Requests.IncreaseAttribute
local function getIncreaseAttributeRemote()
	local requests = replicatedStorage:FindFirstChild("Requests")
	return requests and requests:FindFirstChild("IncreaseAttribute")
end

---The spread the script is currently working toward (pre or post), or nil if no build is loaded.
---@return table?
local function targetSpread()
	local build = AutoBuilder.current
	if not build then
		return nil
	end
	return AutoBuilder.target == "post" and build.post or build.pre
end

-- Attributes we recently couldn't raise (not enough XP): [stat] = os.clock() deadline to retry.
local investBlockedUntil = {}

---Invest a single point toward the target spread. Walks the attributes in order; for the first one
---below its goal that isn't temporarily blocked, it fires one increment and waits for the stat to
---actually rise (confirming the point landed before we ever fire again -- no overshoot). If the stat
---doesn't rise in time (can't afford it), that attribute is blocked for a while and we move on to the
---next one. Returns true if a point was successfully invested.
---@return boolean
function AutoBuilder.investOnce()
	local spread = targetSpread()
	if not spread then
		return false
	end

	local character = players.LocalPlayer and players.LocalPlayer.Character
	if not character then
		return false
	end

	local remote = getIncreaseAttributeRemote()
	if not remote then
		return false
	end

	for _, entry in ipairs(INVEST_TARGETS) do
		local goal = tonumber(spread[entry.group] and spread[entry.group][entry.key]) or 0
		if goal <= 0 then
			continue
		end

		local before = tonumber(character:GetAttribute(entry.stat)) or 0
		if before >= goal then
			continue
		end

		-- Skip attributes we recently failed to raise (retry only after the block expires).
		local blockedUntil = investBlockedUntil[entry.stat]
		if blockedUntil and os.clock() < blockedUntil then
			continue
		end

		-- Fire one increment and confirm it landed before returning.
		pcall(function()
			remote:InvokeServer(entry.arg)
		end)

		local deadline = os.clock() + 0.75
		while os.clock() < deadline do
			local now = tonumber(character:GetAttribute(entry.stat)) or 0
			if now > before then
				investBlockedUntil[entry.stat] = nil
				return true
			end
			task.wait(0.05)
		end

		-- Didn't rise -> can't afford it right now. Block it briefly and move on to the next attribute.
		investBlockedUntil[entry.stat] = os.clock() + 8
	end

	return false
end

-- ============================================================================================
-- Shrine progress (used by Auto Prog). Mirrors PR's ab_builder:shrine_ready / finished -- purely
-- attribute-based: compare the character's current Stat_* values to a target spread.
-- ============================================================================================

---Sum of still-unmet attribute points for a spread, plus the total wanted. Returns (missing, wanted).
---@param spread table?
---@return number, number
function AutoBuilder.missingForSpread(spread)
	local character = players.LocalPlayer and players.LocalPlayer.Character
	if not spread or not character then
		return 0, 0
	end

	local missing, wanted = 0, 0
	for _, entry in ipairs(INVEST_TARGETS) do
		local goal = tonumber(spread[entry.group] and spread[entry.group][entry.key]) or 0
		if goal > 0 then
			wanted = wanted + goal
			local current = tonumber(character:GetAttribute(entry.stat)) or 0
			missing = missing + math.max(0, goal - current)
		end
	end

	return missing, wanted
end

---Whether the preshrine attribute spread is fully invested (ready for the Shrine of Order).
---@return boolean
function AutoBuilder.shrineReady()
	local build = AutoBuilder.current
	if not build then
		return false
	end

	local missing, wanted = AutoBuilder.missingForSpread(build.pre)
	return wanted > 0 and missing == 0
end

---Whether the postshrine (final) attribute spread is fully invested -- the build is complete.
---@return boolean
function AutoBuilder.finished()
	local build = AutoBuilder.current
	if not build then
		return false
	end

	local missing, wanted = AutoBuilder.missingForSpread(build.post)
	return wanted > 0 and missing == 0
end

---Whether the current pending choice is a "special" hand (matches the game's u1 == "special"): the
---replicated SpecialChoice has a Type and a non-empty Selection.
---@return boolean
local function isSpecialChoice()
	local info = replicatedStorage:FindFirstChild("Info")
	local dataReplication = info and info:FindFirstChild("DataReplication")
	if not dataReplication then
		return false
	end

	local ok, module = pcall(require, dataReplication)
	if not ok or type(module) ~= "table" or type(module.GetData) ~= "function" then
		return false
	end

	local gotData, data = pcall(module.GetData)
	if not gotData or type(data) ~= "table" then
		return false
	end

	local special = data.SpecialChoice
	return type(special) == "table"
		and special.Type ~= nil
		and type(special.Selection) == "table"
		and #special.Selection > 0
end

---Fire the game's TalentChoice remote for a card by name. Returns true if the remote was invoked.
---@param name string
---@return boolean
local function chooseCard(name)
	local remote = getTalentChoiceRemote()
	if not remote then
		return false
	end

	local special = isSpecialChoice()

	return pcall(function()
		remote:InvokeServer(name, special)
	end)
end

---All TextButton descendants of PlayerGui.TalentGui.ChoiceFrame (the talent/mantra cards).
---@return table
local function getChoiceButtons()
	local talentGui = getTalentGui()
	local choiceFrame = talentGui and talentGui:FindFirstChild("ChoiceFrame")

	local buttons = {}
	if not choiceFrame then
		return buttons
	end

	for _, descendant in next, choiceFrame:GetDescendants() do
		if descendant:IsA("TextButton") then
			buttons[#buttons + 1] = descendant
		end
	end

	return buttons
end

---Pick a single card according to the priority (preshrine wanted > postshrine wanted > random real
---card) by firing the TalentChoice remote. Returns true if a card was chosen.
---@return boolean
function AutoBuilder.pickOnce()
	local buttons = getChoiceButtons()
	if #buttons == 0 then
		return false
	end

	-- "Only Roll 2 For Mantras": the special "Roll 2" card only appears in a Mantra Hand (it grants 2
	-- Talents instead of a mantra). When the toggle is on, always take it before considering any card --
	-- so mantra hands never pick a mantra. Talent hands have no Roll 2 card, so they fall through.
	if Toggles and Toggles.AutoBuilderOnlyRoll2 and Toggles.AutoBuilderOnlyRoll2.Value then
		for _, button in ipairs(buttons) do
			if button.Name == "Roll 2" then
				return chooseCard("Roll 2")
			end
		end
	end

	local classified = AutoBuilder.classified
	local bdata = AutoBuilder.current and AutoBuilder.current.bdata

	-- Build the wanted-name sets (talents + mantras) for each column.
	local wantedPre, wantedPost = {}, {}
	if classified then
		for _, name in ipairs(classified.pre.talents) do
			wantedPre[name] = true
		end
		for _, name in ipairs(classified.pre.mantras) do
			wantedPre[name] = true
		end
		for _, name in ipairs(classified.post.talents) do
			wantedPost[name] = true
		end
		for _, name in ipairs(classified.post.mantras) do
			wantedPost[name] = true
		end
	end

	-- 1) A preshrine pick that's on offer.
	for _, button in ipairs(buttons) do
		if wantedPre[button.Name] then
			return chooseCard(button.Name)
		end
	end

	-- 2) A postshrine pick that's on offer.
	for _, button in ipairs(buttons) do
		if wantedPost[button.Name] then
			return chooseCard(button.Name)
		end
	end

	-- 3) None of the wanted cards are here -- pick a random real talent/mantra card. We use ddata to
	-- confirm each button's name is an actual talent/mantra (avoids firing on non-card buttons). If
	-- ddata isn't available, fall back to any button.
	local cards = {}
	for _, button in ipairs(buttons) do
		if bdata and bdata.ddata:get(button.Name) ~= nil then
			cards[#cards + 1] = button
		end
	end
	if #cards == 0 then
		cards = buttons
	end

	return chooseCard(cards[math.random(1, #cards)].Name)
end

---Register the picking loop (guarded by AutoBuilder.picking). Call once at startup.
function AutoBuilder.init()
	pickMaid:add(renderStepped:connect("AutoBuilderPick_OnRender", function()
		if not AutoBuilder.picking then
			return
		end

		-- Point investment toward the selected spread. The remote yields, so run it off-thread with a
		-- busy guard to avoid overlapping invokes.
		if not investBusy and os.clock() >= investCooldownUntil then
			investBusy = true
			task.spawn(function()
				-- investOnce self-paces (it confirms each point), so retry immediately after a success
				-- and back off when there's nothing to do / everything's blocked.
				local fired = AutoBuilder.investOnce()
				investCooldownUntil = os.clock() + (fired and 0 or 1.0)
				investBusy = false
			end)
		end

		-- Card picking: paced by a cooldown, off-thread (the TalentChoice remote yields too). Picks as
		-- soon as cards are present (no wait for the list to "settle").
		if not pickBusy and os.clock() >= pickCooldownUntil then
			pickBusy = true
			task.spawn(function()
				local fired = AutoBuilder.pickOnce()
				pickCooldownUntil = os.clock() + (fired and 1.0 or 0.25)
				pickBusy = false
			end)
		end
	end))

	if not LPH_OBFUSCATED or (shared.Luma and shared.Luma.verbose) then
		Logger.warn("Auto Builder initialized.")
	end
end

function AutoBuilder.detach()
	pickMaid:clean()
end

return AutoBuilder

end)
__bundle_register("@luma/Features/Automation/AutoDuke", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Duke: a luma port of project-rain-oss's `auto_duke.lua`, on the ported AutomationStruct +
-- StateMachine framework and the shared General/Teleports substrate. Refills food in the Etrean Luminant,
-- opens the Erisia manor (Manor Key), clears the brainsuckers/cultists, rides the elevator into the Duke
-- dungeon, then fights the golems + the Duke (with attack-pattern dodging + optional void mode) and loots.
--
-- Public surface:
--   AutoDuke.start()        -- menu Start + Luma.lua resume
--   AutoDuke.stop()
--   AutoDuke.inValidPlace() -- resume gate (Etrean/Eastern main-game or the Duke dungeon)
-- Persistence key: "dukedata" { slot, startedAt }.
-- Menu toggles read here: DukeVoids (use void mode on the Duke).
local AutoDuke = {}

---@module Utility.PersistentData
local PersistentData = require("@luma/Utility/PersistentData")

---@module Utility.Prompt
local Prompt = require("@luma/Utility/Prompt")

---@module Game.ServerHop
local ServerHop = require("@luma/Game/ServerHop")

---@module Features.Game.Tweening
local Tweening = require("@luma/Features/Game/Tweening")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module GUI.Library
local Library = require("@luma/GUI/Library")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("@luma/Utility/CoreGuiManager")

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Game.AntiAFK
local AntiAFK = require("@luma/Game/AntiAFK")

---@module Game.KeyHandling
local KeyHandling = require("@luma/Game/KeyHandling")

---@module Features.Automation.Objects.StateMachine
local StateMachine = require("@luma/Features/Automation/Objects/StateMachine")

---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("@luma/Features/Automation/Objects/AutomationStruct")

---@module Features.Automation.Objects.General
local General = require("@luma/Features/Automation/Objects/General")

---@module Features.Automation.Objects.Teleports
local Teleports = require("@luma/Features/Automation/Objects/Teleports")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")
local collectionService = game:GetService("CollectionService")

local MAIN_GAME_PLACE_ID = 6032399813 -- overworld (Etrean Luminant / Erisia manor).
local EASTERN_PLACE_ID = 6473861193 -- Eastern Luminant.
local DEPTHS_PLACE_ID = 5735553160 -- The Depths (should never be here; stop if we are).

local MOVE_ID = "AutoDuke_Move"
local DUKE_NAME = ".theduke11"

local running = false
local struct = nil
local maid = Maid.new()

local screenGui, elapsedLabel = nil, nil

-- =========================================================================================================
-- Accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end
local function character()
	local lp = localPlayer()
	return lp and lp.Character
end
local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end
local function humanoid()
	local c = character()
	return c and c:FindFirstChildOfClass("Humanoid")
end
local function backpack()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("Backpack")
end
local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end
local function isRunning()
	return running
end

function AutoDuke.inValidPlace()
	if game.PlaceId == MAIN_GAME_PLACE_ID or game.PlaceId == EASTERN_PLACE_ID then
		return true
	end
	-- Also valid if we're inside the Duke dungeon (resume mid-fight).
	local dungeon = localPlayer() and localPlayer():GetAttribute("Dungeon")
	return dungeon ~= nil and tostring(dungeon):match("Duke") ~= nil
end

local function getEffectReplicator()
	local ok, mod = pcall(function()
		return require(replicatedStorage:WaitForChild("EffectReplicator"))
	end)
	return ok and mod or nil
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for k, v in pairs(props) do
		instance[k] = v
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end
local function buildOverlay()
	if screenGui then
		return
	end
	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "LumaAutoDukeOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999
	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Duke",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })
	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })
	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoDuke.stop()
	end)
	pcall(function()
		Library:MakeDraggable(outer)
	end)
end
local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end
-- Stage text was removed; kept as a no-op so the many callers don't need changing.
local function setStage(_) end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("dukedata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Movement + helpers.
-- =========================================================================================================
local function setSpeed(value)
	value = (Options and Options.DukeTweenSpeed and Options.DukeTweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end

---Blocking tween (PR Tween.new(cf, true, speed).wait()).
local function tempTween(cframe, speed)
	setSpeed(speed or 250)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 4 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end

---Non-blocking tween goal (used inside tight fight loops so we don't stall on arrival).
local function tweenGoal(cframe, speed)
	setSpeed(speed or 250)
	Tweening.goal(MOVE_ID, cframe, false)
end

local function playerNear()
	local origin = root() and root().Position
	if not origin then
		return false
	end
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (origin - player.Character:GetPivot().Position).Magnitude <= 1000 then
				return true
			end
		end
	end
	return false
end

local function serverHop()
	pcall(function()
		ServerHop.hop(currentSlot(), true)
	end)
end

---PR's player_safe_tween: hop if anyone near, else go up to altitude, travel, drop.
local function playerSafeTween(cf, speed)
	if playerNear() then
		serverHop()
		while task.wait() do
		end
		return
	end
	local r = root()
	if not r then
		return
	end
	local y = math.random(8000, 10000)
	r.CFrame = r.CFrame + Vector3.new(0, y, 0)
	tempTween(cf + Vector3.new(0, y, 0), speed)
	if playerNear() then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
	task.wait(1)
end

local function m1Hold(state)
	local feat = struct and struct.active_features and struct.active_features["m1_hold"]
	if feat then
		feat.held = state
	end
end

local function readyWeapon()
	pcall(function()
		character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
	end)
end

-- =========================================================================================================
-- Loot.
-- =========================================================================================================
local function playerGuiHasChoice()
	local lp = localPlayer()
	local gui = lp and lp:FindFirstChildOfClass("PlayerGui")
	return gui and gui:FindFirstChild("ChoicePrompt") ~= nil
end

local function grabChests()
	local looted = false
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return false
	end
	for _, chest in next, thrown:GetChildren() do
		if not running then
			break
		end
		if chest:FindFirstChild("Lid") and not collectionService:HasTag(chest, "looted") then
			tempTween(chest.Lid.CFrame, 170)
			local t = tick()
			repeat
				task.wait(1)
				pcall(function()
					Prompt.interact(chest:FindFirstChildWhichIsA("ProximityPrompt"))
				end)
				pcall(function()
					tempTween(chest.Lid.CFrame, 170)
				end)
			until (playerGuiHasChoice()) or not running or tick() - t > 3
			if playerGuiHasChoice() then
				looted = true
			end
			local t2 = tick()
			repeat
				task.wait(1)
			until not playerGuiHasChoice() or not running or tick() - t2 > 3
			if playerGuiHasChoice() then
				looted = true
				pcall(function()
					localPlayer().PlayerGui.ChoicePrompt.Choice:FireServer("EXIT")
				end)
			end
			collectionService:AddTag(chest, "looted")
		end
	end
	return looted
end

-- =========================================================================================================
-- Refill food (Etrean ingredients).
-- =========================================================================================================
local function refill()
	setStage("refill food")
	local char = character()
	if not char then
		return
	end
	local water = char:FindFirstChild("Water")
	if not water then
		return
	end

	local function isSatiated()
		return water.Value >= (water.MaxValue * 0.5)
	end

	local passives = char:GetAttribute("ssv_Passives")
	if passives and tostring(passives):find("Carnivore") then
		return
	end

	local function closestIngredient(namePart)
		local closest
		local folder = workspace:FindFirstChild("Ingredients")
		if not folder then
			return nil
		end
		for _, ing in next, folder:GetChildren() do
			if ing.Name:match(namePart) then
				if not closest then
					closest = ing
				elseif (root().Position - ing.Position).Magnitude < (root().Position - closest.Position).Magnitude then
					closest = ing
				end
			end
		end
		return closest
	end

	local function collect(ing)
		playerSafeTween(ing.CFrame, 200)
		local cf = ing.CFrame
		repeat
			tempTween(cf, 200)
			pcall(function()
				Prompt.interact(ing:FindFirstChildOfClass("ProximityPrompt"))
			end)
			task.wait()
		until ing.Parent == nil or not running
	end

	local function eat(foodName)
		local item = backpack() and backpack():FindFirstChild(foodName)
		if not item then
			return
		end
		humanoid():EquipTool(item)
		item:Activate()
		task.wait(0.5)
		humanoid():UnequipTools()
	end

	local start = tick()
	while running and not isSatiated() and tick() - start <= 45 do
		local ing = closestIngredient("Dentifilo") or closestIngredient("Calabash")
		if not ing then
			break
		end
		local name = ing.Name
		collect(ing)
		eat(name)
		task.wait()
	end
end

-- =========================================================================================================
-- Create instance (open manor, clear adds, ride elevator into the Duke dungeon).
-- =========================================================================================================
local function createInstance()
	setStage("opening manor")
	local bp = backpack()
	if not bp then
		return
	end
	local manorKey = bp:WaitForChild("Manor Key", 10) or (character() and character():WaitForChild("Manor Key", 10))
	if not manorKey then
		Logger.notify("Auto Duke: need a Manor Key.")
		return
	end
	manorKey.Parent = character()
	local handle = manorKey:WaitForChild("Handle", 10)
	if not handle then
		return
	end

	-- The key has to be "charged" (handle turns white) before it works. If it isn't, wait up to 10s for it
	-- to change; if it still isn't white, this slot's key is spent -> hop to a fresh server.
	if handle.Color.R < 0.99 or handle.Color.G < 0.99 or handle.Color.B < 0.99 then
		local start = tick()
		local old = handle.Color
		repeat
			task.wait()
		until handle.Color ~= old or tick() - start > 10 or not running
		if handle.Color.R < 0.99 or handle.Color.G < 0.99 or handle.Color.B < 0.99 then
			return serverHop()
		end
	end

	playerSafeTween(CFrame.new(1460, 74, 3069), 200)

	local started = false
	task.delay(20, function()
		if not started and running then
			serverHop()
		end
	end)

	maid:mark(workspace.Live.ChildAdded:Connect(function(entity)
		if (entity.Name:find("brainsucker") or entity.Name:find("dukecultist")) then
			if (entity:GetPivot().Position - (root() and root().Position or Vector3.zero)).Magnitude <= 400 then
				started = true
			end
		end
	end))

	setStage("entering manor")
	while running and not started do
		if sethiddenproperty and humanoid() then
			pcall(function()
				sethiddenproperty(humanoid(), "MoveDirectionInternal", Vector3.one)
			end)
		end
		pcall(function()
			Prompt.interact(workspace.Doors.ErisiaDungeonGate.Main.InteractPrompt)
		end)
		task.wait()
	end

	readyWeapon()
	m1Hold(true)

	setStage("clearing adds")
	local done = false
	while running and not done do
		done = true
		for _, entity in next, workspace.Live:GetChildren() do
			if entity.Name:find("brainsucker") or entity.Name:find("dukecultist") then
				if (entity:GetPivot().Position - (root() and root().Position or Vector3.zero)).Magnitude <= 900 then
					local hum = entity:FindFirstChildOfClass("Humanoid")
					while running and hum and hum.Health > 0 and entity:FindFirstChild("HumanoidRootPart") do
						if playerNear() then
							serverHop()
							while task.wait() do
							end
							return
						end
						m1Hold(true)
						tweenGoal(entity.HumanoidRootPart.CFrame * CFrame.new(0, 0, 3), 250)
						task.wait()
					end
					done = false
				end
			end
		end
	end
	m1Hold(false)
	Tweening.stop(MOVE_ID)

	task.delay(30, function()
		if running then
			serverHop()
		end
	end)

	setStage("riding elevator")
	playerSafeTween(CFrame.new(1470, 84, 3586), 200)
	for _ = 1, 300 do
		if not running then
			break
		end
		if playerNear() then
			serverHop()
			while task.wait() do
			end
			return
		end
		tempTween(CFrame.new(1470, 84, 3586), 250)
		pcall(function()
			Prompt.interact(workspace.ErisiaElevator.Switch.InteractPrompt)
		end)
		task.wait(0.1)
	end
end

-- =========================================================================================================
-- Kill the Duke.
-- =========================================================================================================
local function killDuke()
	setStage("fighting duke")
	readyWeapon()
	m1Hold(true)

	-- Dodge the golem laser (GolemLaserFire client effect).
	local nopeTfOut = false
	local clientEffect
	repeat
		clientEffect = replicatedStorage:FindFirstChild("ClientEffect", true)
		if not clientEffect then
			task.wait()
		end
	until clientEffect or not running
	if clientEffect then
		maid:mark(clientEffect.OnClientEvent:Connect(function(effectName)
			if effectName == "GolemLaserFire" then
				nopeTfOut = true
				task.delay(0.4, function()
					nopeTfOut = false
				end)
			end
		end))
	end

	-- Phase 1: clear the prime golems / remaining cultists (Z > 2000, i.e. in the arena).
	local done = false
	while running and not done do
		done = true
		for _, entity in next, workspace.Live:GetChildren() do
			if not running then
				break
			end
			if (entity.Name:find("prime_golem") or entity.Name:find("dukecultist")) then
				if (entity:GetPivot().Position - (root() and root().Position or Vector3.zero)).Magnitude <= 900 and entity:GetPivot().Z >= 2000 then
					local hum = entity:FindFirstChildOfClass("Humanoid")
					while running and hum and hum.Health > 0 do
						m1Hold(true)
						if not entity:FindFirstChild("HumanoidRootPart") then
							break
						end
						if not nopeTfOut then
							tweenGoal(
								entity.HumanoidRootPart.CFrame
									* (entity.Name:find("prime_golem") and CFrame.new(0, 5, 0.35) or CFrame.new(0, 2, 3)),
								250
							)
						else
							tweenGoal(entity.HumanoidRootPart.CFrame * CFrame.new(0, 100, 10), 250)
						end
						task.wait()
					end
					done = false
				end
			end
		end
	end
	m1Hold(false)
	if not running then
		return
	end

	-- Phase 2: start the Duke dialogue -- fire the interact prompt on .theduke11 until dialogue opens.
	local sendDialogue = replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue")
	local got = false
	maid:mark(sendDialogue.OnClientEvent:Connect(function(v)
		got = not (v and v.exit)
	end))

	local vim = Instance.new("VirtualInputManager")
	repeat
		local duke = workspace.Live:FindFirstChild(DUKE_NAME)
		if duke and duke:FindFirstChild("HumanoidRootPart") then
			tempTween(duke.HumanoidRootPart.CFrame * CFrame.new(0, 0, 3), 250)
			pcall(function()
				Prompt.interact(duke.InteractPrompt)
			end)
		end
		pcall(function()
			vim:SendKeyEvent(true, Enum.KeyCode.One, false, game)
			task.wait()
			vim:SendKeyEvent(false, Enum.KeyCode.One, false, game)
		end)
		task.wait()
	until got or not running
	-- Spam the accept key while the dialogue is open.
	while running and got do
		pcall(function()
			vim:SendKeyEvent(true, Enum.KeyCode.One, false, game)
			task.wait()
			vim:SendKeyEvent(false, Enum.KeyCode.One, false, game)
		end)
		task.wait()
	end

	-- Wait for the Duke to actually target us (fight starts).
	repeat
		task.wait()
		local duke = workspace.Live:FindFirstChild(DUKE_NAME)
		if duke and duke:FindFirstChild("Target") and duke.Target.Value then
			break
		end
	until not running
	readyWeapon()

	-- Detect the Duke's dangerous animations.
	task.delay(5, function()
		local duke = workspace.Live:FindFirstChild(DUKE_NAME)
		if duke and duke:FindFirstChildOfClass("Humanoid") then
			maid:mark(duke.Humanoid.AnimationPlayed:Connect(function(anim)
				local id = anim.Animation.AnimationId
				if id:find("8275408994") or id:find("8290899374") or id:find("8294560344") then
					nopeTfOut = true
					task.delay(id:find("8294560344") and 7.5 or 2.5, function()
						nopeTfOut = false
					end)
				end
			end))
		end
	end)

	-- Void mode?
	local voidingMode = Toggles and Toggles.DukeVoids and Toggles.DukeVoids.Value == true
	if Toggles and Toggles.VoidMobs then
		Toggles.VoidMobs:SetValue(voidingMode)
	end

	-- Main Duke loop.
	local duke = workspace.Live:FindFirstChild(DUKE_NAME)
	while running and workspace.Live:FindFirstChild(DUKE_NAME) do
		task.wait()
		duke = workspace.Live:FindFirstChild(DUKE_NAME)
		m1Hold(not General.playing_ap_anims(duke))

		if not duke:FindFirstChild("HumanoidRootPart") or not duke:FindFirstChild("Humanoid") or not duke.Parent or duke.Humanoid.Health <= 0 then
			break
		end

		-- Void mode: cast Frost Grab while safe.
		if voidingMode and not nopeTfOut and not General.playing_ap_anims(duke) then
			local frost = backpack() and backpack():FindFirstChild("Mantra:ChokeIce{{Frost Grab}}")
			if frost then
				pcall(function()
					character().CharacterHandler.Requests.ActivateMantra:FireServer(frost)
				end)
			end
		end

		local hrp = duke.HumanoidRootPart
		if hrp.CFrame.Y <= -1000 then
			continue -- void can fail; don't chase into the void
		end

		local x, y, z = hrp.CFrame:GetComponents()
		local xSin = math.sin(tick() * 2) * 30
		local zCos = math.cos(tick() * 2) * 30

		if General.playing_ap_anims(duke, { "rbxassetid://8085349676" }) or nopeTfOut then
			local critical = KeyHandling.getRemote("CriticalClick")
			if critical then
				pcall(function()
					critical:FireServer({ S = false, NOAERIALS = false, Space = false, Right = false, W = false, Left = true }, false)
				end)
			end
			tweenGoal(CFrame.new(x + xSin, y < 70 and math.random(175, 250) or math.random(0, 10), z + zCos), 250)
		elseif General.playing_ap_anims(duke) then
			tweenGoal(CFrame.new(x + xSin, y < 70 and math.random(175, 250) or math.random(0, 10), z + zCos), 250)
		else
			tweenGoal(hrp.CFrame * CFrame.new(0, -6, 0) * CFrame.Angles(math.rad(90), 0, 0), 250)
		end
	end
	m1Hold(false)
	Tweening.stop(MOVE_ID)
	if not running then
		return
	end

	-- Wait out danger, then loot the chests and respawn out.
	setStage("looting")
	task.delay(60 * 5, function()
		if not running then
			return
		end
		local er = getEffectReplicator()
		repeat
			task.wait()
			tempTween(CFrame.new(2495, 139, 1926), 160)
		until not (er and er:FindEffect("Danger")) or not running
		General.respawn()
	end)

	while running do
		local ok, res = pcall(grabChests)
		if ok and res then
			break
		end
		task.wait(1)
	end

	local er = getEffectReplicator()
	repeat
		task.wait()
		tempTween(CFrame.new(2495, 139, 1926), 160)
	until not (er and er:FindEffect("Danger")) or not running
	General.respawn()
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "refill", from = "_check_area", to = "_refill" },
		{ name = "initiate", from = "_check_area", to = "_initiate" },
		{ name = "initiate", from = "_refill", to = "_initiate" },
		{ name = "kill", from = "_check_area", to = "_kill" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")

			-- Somehow ended up in the Depths -> stop (PR kicks here).
			if game.PlaceId == DEPTHS_PLACE_ID then
				Logger.notify("Auto Duke: ended up in the Depths -- stopping.")
				return AutoDuke.stop()
			end

			local dungeon = localPlayer() and localPlayer():GetAttribute("Dungeon")
			if dungeon and tostring(dungeon):match("Duke") then
				return self:kill()
			end

			if game.PlaceId == EASTERN_PLACE_ID then
				-- Wrong region -- teleport back to the Etrean Luminant (manor is there).
				Teleports.etrean()
				return
			end

			if game.PlaceId == MAIN_GAME_PLACE_ID then
				self:refill()
				self:initiate()
				return
			end
		end,
		onenter_refill = function(self)
			if not running then
				return
			end
			refill()
			self:initiate()
		end,
		onenter_initiate = function(self)
			if not running then
				return
			end
			createInstance()
		end,
		onenter_kill = function(self)
			if not running then
				return
			end
			killDuke()
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_duke",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"no_kill_bricks",
			"mod_detector",
			"fly",
			"m1_hold",
			"auto_wisp",
			"auto_equip_weapon",
			"auto_log",
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoDuke.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	if not AutoDuke.inValidPlace() then
		return Logger.notify("Auto Duke: not in the Etrean/Eastern Luminant.")
	end
	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Duke: no data slot found.")
	end

	local data = PersistentData.get("dukedata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("dukedata", data)

	running = true
	buildOverlay()
	AntiAFK.start("AutoDuke")

	maid:mark(task.spawn(runElapsed))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoDuke.stop()
	if not running then
		return
	end
	running = false
	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end
	Tweening.stop(MOVE_ID)
	pcall(function()
		AntiAFK.stop("AutoDuke")
	end)
	maid:clean()
	destroyOverlay()
	PersistentData.set("dukedata", nil)
end

return AutoDuke

end)
