local function handleObelisks()
	setStage("floor 2: obelisks")
	repeat
		local obelisk = getNearest(collectionService:GetTagged("BuzzObelisk"), function(o)
			return o.Name:match("Buzz") ~= nil
		end)
		if obelisk then
			tempTween(obelisk.CFrame, 175)
			pcall(function()
				fireProx(obelisk.InteractPrompt)
			end)
		end
		task.wait()
	until #collectionService:GetTagged("BuzzObelisk") == 0 or not running
end

local function handleKrysanChests()
	if not cfg("L2LootChests", true) then
		return
	end

	setStage("floor 2: kyrsan chests")
	local gui = playerGui()
	local currency = gui and gui:FindFirstChild("CurrencyGui")
	local medallions = currency and currency.CurrencyFrame:FindFirstChild("KyrsanMedallions")
	local amount = medallions and medallions:FindFirstChild("Amount")
	if amount and amount.Text == "250" then
		return
	end

	local chests = {}
	for _, chest in next, thrownChildren() do
		if chest:FindFirstChild("Lid") then
			table.insert(chests, chest)
		end
	end
	while running and #chests > 0 do
		local r = root()
		local closest, idx = nil, nil
		for i, chest in ipairs(chests) do
			if not chest.Parent or not chest:FindFirstChild("Lid") then
				continue
			end
			if not closest or (r.Position - chest.Lid.Position).Magnitude < (r.Position - closest.Lid.Position).Magnitude then
				closest, idx = chest, i
			end
		end
		if not closest then
			break
		end
		tempTween(closest.Lid.CFrame, 175)
		grabChest(closest)
		table.remove(chests, idx)
		task.wait()
	end
end

local function handleEthironSpawn()
	setStage("floor 2: summon ethiron")
	tempTween(CFrame.new(787.787598, 1311.22559, 7324.95801), 175)
	pcall(function()
		tempTween(workspace.NPCs.EthironSummonPodium:GetPivot(), 175)
	end)
	repeat
		pcall(function()
			fireProx(workspace.NPCs.EthironSummonPodium.InteractPrompt)
		end)
		task.wait(0.5)
	until dialogueOpen() or not running
	sendDialogue("[Resist it]")
	sendDialogue("[Resist further]")
	sendDialogue("[Resist with all that you are]")
	sendDialogue("[Breathe out]")
end

local function handleEthironFight()
	setStage("floor 2: ethiron gauntlet")
	local ultimateDetected = false
	local boneTweenActive = false
	local ethironStunned = false

	maid:mark(workspace.DescendantAdded:Connect(function(descendant)
		if not running then
			return
		end
		if descendant.Name:lower():find("bombcharge") then
			if not avatarExists() then
				return
			end
			ultimateDetected = true
			while boneTweenActive do
				task.wait()
			end
			tempTween(CFrame.new(787.787598, 1380, 7324.95801), 175)
			detectBombFullyCharged()
			detectBombFired()
			tempTween(CFrame.new(774.600281, 2000, 7465.85791), 175)
			ultimateDetected = false
		end
	end))

	local avatar = nil
	repeat
		for _, v in next, liveChildren() do
			if v.Name:find("%.avatar") then
				avatar = v
				break
			end
		end
		task.wait()
	until avatar or not running
	if not avatar then
		return
	end

	local initHeadCF = nil
	repeat
		pcall(function()
			initHeadCF = avatar:FindFirstChild("Head").CFrame
		end)
		task.wait()
	until initHeadCF or not running

	pcall(function()
		avatar.Humanoid.Animator.AnimationPlayed:Connect(function(anim)
			if anim.Animation.AnimationId:match("rbxassetid://10880826811") then
				ethironStunned = true
			elseif anim.Animation.AnimationId:match("rbxassetid://10978735338") then
				ethironStunned = false
			end
		end)
	end)

	local function hp()
		local h = humanoid()
		return h and h.Health or 0, h and h.MaxHealth or 1
	end

	repeat
		xpcall(function()
			repeat
				local bonespear = getNearestBoneSpear()
				local bonealtar = getNearestAltar()
				local health, maxHealth = hp()

				if health <= maxHealth * 0.25 then
					repeat
						if not ultimateDetected then
							tempTween(CFrame.new(774.600281, 1380, 7465.85791), 175)
						end
						task.wait()
						health = hp()
					until health >= maxHealth * 0.25 or not running
				elseif ultimateDetected then
					task.wait()
				elseif (bonespear and bonealtar and not foundFlyingBoneSpear())
					or (bonealtar and character():FindFirstChild("BoneSpear")) then
					-- Grab a spear.
					if not ultimateDetected and not character():FindFirstChild("BoneSpear") and hp() > maxHealth * 0.40 then
						boneTweenActive = true
						repeat
							pcall(function()
								tempTween(bonespear.CFrame, 175)
							end)
							pcall(function()
								fireProx(bonespear.InteractPrompt)
							end)
							task.wait()
						until bonespear == nil or bonespear.Parent == nil or character():FindFirstChild("BoneSpear") or ultimateDetected or hp() <= maxHealth * 0.40 or not running
					end
					-- Plant it on an altar.
					if not ultimateDetected and character():FindFirstChild("BoneSpear") and hp() > maxHealth * 0.40 then
						boneTweenActive = true
						repeat
							pcall(function()
								tempTween(bonealtar:GetPivot(), 175)
							end)
							pcall(function()
								fireProx(bonealtar.InteractPrompt)
							end)
							task.wait()
						until not character():FindFirstChild("BoneSpear") or ultimateDetected or hp() <= maxHealth * 0.40 or not running
					end
					boneTweenActive = false
				elseif ethironStunned and not foundFlyingBoneSpear() then
					repeat
						boneTweenActive = true
						tempTween(avatar.Head.CFrame * CFrame.new(0, -5, 0), 175)
						boneTweenActive = false
						autoM1(true)
						task.wait()
					until not ethironStunned or hp() <= maxHealth * 0.40 or not running
					autoM1(false)
				else
					boneTweenActive = true
					tempTween(initHeadCF * CFrame.new(0, 150, 0), 175)
					boneTweenActive = false
				end
				task.wait()
			until avatar.Parent == nil or not running
		end, function(err)
			Logger.notify("Auto L2 ethiron error: %s", tostring(err))
		end)
		task.wait()
	until avatar.Parent == nil or not running
	autoM1(false)
end

local function handleEthironChest()
	if not cfg("L2LootChests", true) then
		return
	end

	setStage("floor 2: ethiron chest")
	tempTween(CFrame.new(791.660889, 563.343811, 7120.29248), 175)
	grabNearestChest()
end

local function floorTwo()
	drawWeapon()
	handleObelisks()
	handleKrysanChests()
	handleEthironSpawn()
	handleEthironFight()
	handleEthironChest()

	-- Light-hook escape.
	tempTween(CFrame.new(944.20166, 850.517029, 4173.19775), 175)
	local hook = workspace:FindFirstChild("InGameLightHook")
	if hook then
		for _ = 1, 2 do
			pcall(firetouchinterest, root(), hook, 0)
			pcall(firetouchinterest, root(), hook, 1)
		end
	end
end

-- =========================================================================================================
-- Void dive into Layer 2.
-- =========================================================================================================
local function nearestKillPlane()
	local r = root()
	if not r then
		return nil
	end
	local best, bestDist = nil, math.huge
	for _, item in ipairs(collectionService:GetTagged("KillPlane")) do
		if item:IsA("BasePart") and item:IsDescendantOf(workspace) then
			local d = (item.Position - r.Position).Magnitude
			if d < bestDist then
				best, bestDist = item, d
			end
		end
	end
	return best
end

local function inLayer2()
	local d = dungeon()
	if d and tostring(d):match("Layer2") then
		return true
	end
	local a = currentArea()
	return a ~= nil and tostring(a):match("Layer2") ~= nil
end

---Dive into the void to enter Layer 2 (PR go_to_layer_two). Drops kill-brick immunity + fly so we fall.
local function goToLayerTwo()
	setStage("diving into layer 2")
	disableStructFeature("no_kill_bricks")

	local hum = humanoid()
	if hum and hum.Health <= hum.MaxHealth / 2 then
		-- PR kicks here; we just hop to a fresh server + retry instead of booting the user.
		return serverHop()
	end

	if currentArea() and tostring(currentArea()):match("Fragments of Self") then
		-- We got wiped -- stop cleanly rather than loop.
		AutoLayer2.stop()
		return
	end

	disableStructFeature("fly")

	local startedAt = tick()
	local plane = nearestKillPlane()
	repeat
		plane = nearestKillPlane()
		task.wait()
	until plane or tick() - startedAt > 15 or not running or inLayer2()

	maid:mark(task.spawn(function()
		while running do
			if playerCheck(PLAYER_SAFE_RADIUS) then
				serverHop()
				return
			end
			task.wait()
		end
	end))

	while running and tick() - startedAt < 60 do
		if inLayer2() then
			break
		end
		if not plane then
			plane = nearestKillPlane()
		end
		if plane and plane.Parent then
			setSpeed(200)
			Tweening.goal(MOVE_ID, plane.CFrame, false)
		end
		local r = root()
		if r then
			r.AssemblyLinearVelocity = Vector3.new(0, -999, 0)
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "dive", from = "_check_area", to = "_to_layer_two_floor_one" },
		{ name = "floorone", from = "_check_area", to = "_floor_one" },
		{ name = "floortwo", from = "_check_area", to = "_floor_two" },
		{ name = "continuation", from = "_floor_one", to = "_check_area" },
		{ name = "continuation", from = "_floor_two", to = "_check_area" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")

			local deadline = os.clock() + 25
			repeat
				local d = dungeon()
				if d and tostring(d):match("Layer2Floor1") then
					return self:floorone()
				end
				if d and tostring(d):match("Layer2Floor2") then
					return self:floortwo()
				end
				local area = currentArea()
				if area and tostring(area):match("Fragments of Self") then
					-- Wiped out of a run; stop.
					AutoLayer2.stop()
					return
				end
				if area or game.PlaceId == DEPTHS_PLACE_ID or game.PlaceId == EASTERN_PLACE_ID then
					return self:dive()
				end
				task.wait()
			until os.clock() >= deadline or not running
		end,

		onenter_to_layer_two_floor_one = function(self)
			if not running then
				return
			end
			-- First entry always dives in. On a loop re-entry (already cleared once) only continue if the
			-- user wants loops; otherwise finish cleanly.
			local data = PersistentData.get("l2data")
			if data and data.clearedOnce and not cfg("L2AllowLoops", false) then
				Logger.notify("Auto L2: run finished (loops off).")
				AutoLayer2.stop()
				return
			end
			goToLayerTwo()
			self:continuation()
		end,

		onenter_floor_one = function(self)
			if not running then
				return
			end
			floorOne()
			if not running then
				return
			end
			PersistentData.stf("l2data", "clearedOnce", true)
			self:continuation()
		end,

		onenter_floor_two = function(self)
			if not running then
				return
			end
			floorTwo()
			PersistentData.stf("l2data", "clearedOnce", true)
			self:continuation()
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_layer2",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"no_kill_bricks",
			"mod_detector",
			"fly",
			"m1_hold",
			"auto_equip_weapon",
		},
		character_creator_handler_used = false,
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoLayer2.start()
	local lp = localPlayer()
	if not lp or running then
		return
	end

	if not PersistentData.get("l2data") then
		PersistentData.set("l2data", { active = true })
	end

	running = true
	startedAt = os.time()
	lastChaserSpikeAt = 0
	lastChaserBloodwaveAt = 0
	maid:mark(workspace.DescendantAdded:Connect(trackChaserSpikeSignal))
	for _, descendant in next, workspace:GetDescendants() do
		trackChaserSpikeSignal(descendant)
	end
	buildOverlay()
	AntiAFK.start("AutoLayer2")
	maid:mark(task.spawn(runElapsed))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoLayer2.stop()
	if not running then
		return
	end
	running = false

	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end

	Tweening.stop(MOVE_ID)
	setVoidMobs(false)
	setChaserFling(true)
	pcall(function()
		AntiAFK.stop("AutoLayer2")
	end)

	maid:clean()
	destroyOverlay()
	PersistentData.set("l2data", nil)
	Logger.notify("Auto L2: stopped.")
end

---@return boolean
function AutoLayer2.isRunning()
	return running
end

return AutoLayer2

end)
__bundle_register("@luma/Features/Automation/AutoLoot", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Utility.JSON
local JSON = require("@luma/Utility/JSON")

---@module Utility.Table
local Table = require("@luma/Utility/Table")

---@module Utility.Signal
local Signal = require("@luma/Utility/Signal")

---@module Utility.Configuration
local Configuration = require("@luma/Utility/Configuration")

---@module Features.Automation.Objects.AutoLootOptions
local AutoLootOptions = require("@luma/Features/Automation/Objects/AutoLootOptions")

local AutoLoot = { ignore = false }

local lastTimestamp = os.clock()

local autoLootMaid = Maid.new()

local choiceRemote = nil

local currentPrompt = nil

local currentChoice = nil

local lootQueue = {}

local lootAll = false

local players = game:GetService("Players")
local runService = game:GetService("RunService")

---@param options ScrollingFrame
---@param remote RemoteEvent
local function waitForChoiceDeletion(options, remote)
	local choiceObject = options:FindFirstChild(currentChoice)

	remote:FireServer(currentChoice)

	if choiceObject and choiceObject.Parent then
		return
	end

	if lootQueue[1] ~= currentChoice then
		error("We assumed that the current choice was the first in the queue, was the queue modified?")
	end

	table.remove(lootQueue, 1)

	currentChoice = nil
end

local function resetAutoLoot()
	choiceRemote = nil
	lootQueue = {}
	currentChoice = nil
	currentPrompt = nil
	lootAll = false
end

---@param descendant Instance
local function onPlayerGuiDescendantAdded(descendant)
	if descendant.Name ~= "ChoicePrompt" then
		return
	end

	if AutoLoot.ignore then
		return
	end

	if not Configuration.expectToggleValue("AutoLoot") then
		return
	end

	descendant:WaitForChild("ChoiceFrame"):WaitForChild("Options")

	if AutoLoot.ignore or not Configuration.expectToggleValue("AutoLoot") then
		return
	end

	AutoLoot.process(
		descendant,
		AutoLootOptions.new(
			Configuration.expectOptionValue("AutoLootStarsMin") or 0,
			Configuration.expectOptionValue("AutoLootStarsMax") or 0,
			Configuration.expectOptionValues("ItemNameList") or {},
			Configuration.expectToggleValue("AutoLootAll") or false
		)
	)
end

---@param prompt ScreenGui
---@param remote RemoteEvent
---@param param string
local function waitForPromptDeletion(prompt, remote, param)
	repeat
		remote:FireServer(param)

		task.wait()
	until not prompt.Parent

	resetAutoLoot()
end

---@return boolean
function AutoLoot.active()
	return choiceRemote ~= nil and currentPrompt ~= nil and #lootQueue > 0
end

function AutoLoot.update()
	if os.clock() - lastTimestamp <= 0.15 then
		return
	end

	lastTimestamp = os.clock()

	if AutoLoot.ignore or not Configuration.expectToggleValue("AutoLoot") then
		return resetAutoLoot()
	end

	if not choiceRemote or not choiceRemote.Parent then
		return resetAutoLoot()
	end

	if not currentPrompt or not currentPrompt.Parent then
		return resetAutoLoot()
	end

	local choiceFrame = currentPrompt:FindFirstChild("ChoiceFrame")
	local options = choiceFrame and choiceFrame:FindFirstChild("Options")
	if not options then
		return resetAutoLoot()
	end

	if lootAll then
		return waitForPromptDeletion(currentPrompt, choiceRemote, "LOOT_ALL")
	end

	if currentChoice then
		return waitForChoiceDeletion(options, choiceRemote)
	end

	local itemToLoot = lootQueue[1]
	if not itemToLoot then
		return waitForPromptDeletion(currentPrompt, choiceRemote, "EXIT")
	end

	currentChoice = itemToLoot

	choiceRemote:FireServer(itemToLoot)
end

---@param prompt ScreenGui The choice prompt to process.
---@param options AutoLootOptions The options to use.
function AutoLoot.process(prompt, options)
	local remote = prompt:FindFirstChild("Choice")
	if not remote or not remote:IsA("RemoteEvent") then
		return
	end

	local jsonLootData = prompt:GetAttribute("LootData")
	if typeof(jsonLootData) ~= "string" then
		return
	end

	local lootData = JSON.decode(jsonLootData)
	if typeof(lootData) ~= "table" then
		return
	end

	resetAutoLoot()

	currentPrompt = prompt
	choiceRemote = remote
	lootAll = options.lall

	for _, item in next, lootData do
		local rich = item.rich:gsub("%$%S*", "")
		local text = item.text

		if not text then
			continue
		end

		-- Always-loot list: matched items are queued regardless of the star filter.
		local alwaysWanted, _ = Table.find(options.always or {}, function(value, _)
			return rich:match(value)
		end)
		if alwaysWanted then
			lootQueue[#lootQueue + 1] = text
			continue
		end

		local matched = text:match("★")
		local stars = matched and #matched or 0

		if stars < options.smin or stars > options.smax then
			continue
		end

		local wanted, _ = Table.find(options.wanted, function(value, _)
			return rich:match(value)
		end)

		if not wanted then
			continue
		end

		lootQueue[#lootQueue + 1] = text
	end
end

function AutoLoot.init()
	local localPlayer = players.LocalPlayer
	local playerGui = localPlayer:WaitForChild("PlayerGui")

	local preRender = Signal.new(runService.PreRender)
	local playerGuiDescendantAdded = Signal.new(playerGui.DescendantAdded)

	autoLootMaid:mark(playerGuiDescendantAdded:connect("AutoLoot_PlayerGuiDescendantAdded", onPlayerGuiDescendantAdded))
	autoLootMaid:mark(preRender:connect("AutoLoot_PreRender", AutoLoot.update))
end

function AutoLoot.detach()
	autoLootMaid:clean()
end

return AutoLoot

end)
__bundle_register("@luma/Features/Automation/AutoMooneyrie", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Mooneyrie: a luma port of project-rain-oss's `auto_mooneyrie.lua`, on the AutomationStruct +
-- StateMachine framework. In the Eastern Luminant: heal at a campfire if low, travel to Moon's Eyrie, open
-- the Moon door, kill the Moon Knight(s), loot, then hide/hop. Runs the fight with m1_hold + a kick-anim
-- dodge (attach behind the knight, fly up when he winds up a kick).
--
-- Public surface:
--   AutoMooneyrie.start() / .stop() / .inValidPlace()  (Eastern Luminant)
-- Persistence key: "mooneyriedata" { slot, startedAt }.
local AutoMooneyrie = {}

---@module Utility.PersistentData
local PersistentData = require("@luma/Utility/PersistentData")
---@module Game.ServerHop
local ServerHop = require("@luma/Game/ServerHop")
---@module Features.Game.Tweening
local Tweening = require("@luma/Features/Game/Tweening")
---@module Utility.Prompt
local Prompt = require("@luma/Utility/Prompt")
---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")
---@module GUI.Library
local Library = require("@luma/GUI/Library")
---@module Utility.CoreGuiManager
local CoreGuiManager = require("@luma/Utility/CoreGuiManager")
---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")
---@module Game.AntiAFK
local AntiAFK = require("@luma/Game/AntiAFK")
---@module Features.Automation.Objects.StateMachine
local StateMachine = require("@luma/Features/Automation/Objects/StateMachine")
---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("@luma/Features/Automation/Objects/AutomationStruct")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local EASTERN_PLACE_ID = 6473861193 -- Eastern Luminant (Moon's Eyrie).
local DEPTHS_PLACE_ID = 5735553160 -- The Depths (should never be here; stop if we are).
local MOVE_ID = "AutoMooneyrie_Move"

local running = false
local struct = nil
local maid = Maid.new()
local screenGui, elapsedLabel = nil, nil

-- =========================================================================================================
-- Accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end
local function character()
	local lp = localPlayer()
	return lp and lp.Character
end
local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end
local function humanoid()
	local c = character()
	return c and c:FindFirstChildOfClass("Humanoid")
end
local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end
local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end
local function isRunning()
	return running
end
function AutoMooneyrie.inValidPlace()
	return game.PlaceId == EASTERN_PLACE_ID
end
local function getEffectReplicator()
	local ok, mod = pcall(function()
		return require(replicatedStorage:WaitForChild("EffectReplicator"))
	end)
	return ok and mod or nil
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for k, v in pairs(props) do
		instance[k] = v
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end
local function buildOverlay()
	if screenGui then
		return
	end
	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "LumaAutoMooneyrieOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999
	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()
	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Mooneyrie",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })
	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })
	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoMooneyrie.stop()
	end)
	pcall(function()
		Library:MakeDraggable(outer)
	end)
end
local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end
-- Stage text was removed; kept as a no-op so the many callers don't need changing.
local function setStage(_) end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("mooneyriedata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Helpers.
-- =========================================================================================================
local function setSpeed(value)
	value = (Options and Options.MooneyrieTweenSpeed and Options.MooneyrieTweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end
local function tempTween(cframe, speed)
	setSpeed(speed or 170)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 4 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end
local function playerNear()
	local origin = root() and root().Position
	if not origin then
		return false
	end
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (origin - player.Character:GetPivot().Position).Magnitude <= 200 then
				return true
			end
		end
	end
	return false
end
local function playersNear(target, mag)
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (target - player.Character:GetPivot().Position).Magnitude <= mag then
				return true
			end
		end
	end
	return false
end
local function serverHop()
	pcall(function()
		ServerHop.hop(currentSlot(), true)
	end)
end
local function playerSafeTween(cf, speed)
	if playerNear() then
		serverHop()
		while task.wait() do
		end
		return
	end
	local r = root()
	if not r then
		return
	end
	local y = math.random(8000, 10000)
	r.CFrame = r.CFrame + Vector3.new(0, y, 0)
	tempTween(cf + Vector3.new(0, y, 0), speed)
	if playersNear(cf.Position, 200) then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
	task.wait(1)
end
local function readyWeapon()
	pcall(function()
		character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
	end)
end
local function m1Hold(state)
	local feat = struct and struct.active_features and struct.active_features["m1_hold"]
	if feat then
		feat.held = state
	end
end
local function healthCheck(percent)
	local hum = humanoid()
	return hum ~= nil and hum.Health <= (hum.MaxHealth * percent)
end
local function inDanger()
	local hum = humanoid()
	return hum ~= nil and hum:GetAttribute("DangerExpiration") and hum:GetAttribute("DangerExpiration") > 0
end
local function getClosestMob(name, mag)
	local closest
	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil
	end
	for _, mob in next, live:GetChildren() do
		if mob:IsA("Model") and mob.Name:find(name) and mob:FindFirstChild("HumanoidRootPart") then
			local dist = (root().Position - mob.HumanoidRootPart.Position).Magnitude
			if not closest then
				if not mag or dist < mag then
					closest = mob
				end
			elseif dist < (root().Position - closest.HumanoidRootPart.Position).Magnitude then
				closest = mob
			end
		end
	end
	return closest
end
local function getClosestCampfire()
	local closest
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return nil
	end
	for _, campfire in next, thrown:GetChildren() do
		if campfire.Name:match("Campfire") and campfire:IsA("Model") then
			local part = campfire:FindFirstChildOfClass("Part")
			if part then
				if not closest then
					closest = part
				elseif (root().Position - part.Position).Magnitude < (root().Position - closest.Position).Magnitude then
					closest = part
				end
			end
		end
	end
	return closest
end
local function grabChest()
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return
	end
	for _, chest in next, thrown:GetChildren() do
		if chest:FindFirstChild("Lid") then
			tempTween(chest.Lid.CFrame, 170)
			local t = tick()
			repeat
				task.wait(0.5)
				pcall(function()
					Prompt.interact(chest:FindFirstChildWhichIsA("ProximityPrompt"))
				end)
				pcall(function()
					tempTween(chest.Lid.CFrame, 170)
				end)
			until (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or tick() - t > 3 or playerNear()
			if playerNear() then
				break
			end
			local t2 = tick()
			repeat
				task.wait(1)
			until not (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or tick() - t2 > 3 or playerNear()
			break
		end
	end
end

-- =========================================================================================================
-- Kill a Moon Knight: attach behind it, m1, dodge its kick (fly up when the kick anim plays), then vacuum
-- nearby LootDrops.
-- =========================================================================================================
local function killTarget(target)
	if playerNear() or not target or not target:IsA("Model") then
		return false
	end
	if target.Name:match(localPlayer().Name) then
		return false
	end

	readyWeapon()
	if target:FindFirstChild("HumanoidRootPart") then
		tempTween(target.HumanoidRootPart.CFrame, 170)
	end
	if playerNear() then
		return false
	end

	local foundKick = false
	local animator = target:FindFirstChild("Animator", true)
	local kickConn
	if animator then
		kickConn = animator.AnimationPlayed:Connect(function(track)
			local id = track.Animation.AnimationId
			if (id:match("106711913879378") or id:match("111024000122473")) and not foundKick then
				foundKick = true
				task.delay(2, function()
					foundKick = false
				end)
			end
		end)
	end

	-- Attach behind the knight (fly up when it winds up a kick).
	local attach = task.spawn(function()
		while running and not playerNear() do
			if not target.Parent or not target:FindFirstChild("HumanoidRootPart") then
				break
			end
			local r = root()
			if r then
				r.AssemblyLinearVelocity = Vector3.zero
				r.CFrame = target.HumanoidRootPart.CFrame
					* CFrame.new(0, foundKick and 60 or 10, 0)
					* CFrame.Angles(math.rad(-90), 0, 0)
			end
			task.wait()
		end
	end)

	-- Track health stalls (bail if no damage for 20s).
	local healthTick = tick()
	local lastHealth = nil
	local status = task.spawn(function()
		while running do
			pcall(function()
				local hp = target.Humanoid.Health
				if lastHealth == nil or lastHealth ~= hp then
					healthTick = tick()
					lastHealth = hp
				end
			end)
			task.wait()
		end
	end)

	m1Hold(true)
	repeat
		task.wait()
	until not running
		or not target
		or target.Parent == nil
		or playerNear()
		or healthCheck(0.35)
		or (tick() - healthTick >= 20)

	pcall(function()
		if kickConn then
			kickConn:Disconnect()
		end
	end)
	pcall(function()
		task.cancel(attach)
	end)
	pcall(function()
		task.cancel(status)
	end)
	m1Hold(false)

	-- Vacuum LootDrops.
	if running and not playerNear() then
		task.wait(2)
		local thrown = workspace:FindFirstChild("Thrown")
		for _, drop in next, (thrown and thrown:GetChildren() or {}) do
			if drop:IsA("Model") and drop:FindFirstChild("LootDrop") then
				if (root().Position - drop.LootDrop.Position).Magnitude <= 100 and not playersNear(drop.LootDrop.Position, 200) then
					tempTween(drop.LootDrop.CFrame, 120)
					local t = tick()
					repeat
						pcall(function()
							firetouchinterest(drop.LootDrop, root(), 0)
							firetouchinterest(drop.LootDrop, root(), 1)
						end)
						task.wait()
					until drop.Parent == nil or playerNear() or not running or tick() - t >= 3
					if drop.Parent ~= nil then
						pcall(function()
							drop:Destroy()
						end)
					end
				end
			end
		end
		task.wait(0.2)
	end

	if healthCheck(0.35) then
		return false
	end
	if playerNear() or not running then
		return true
	end
	return false
end

-- =========================================================================================================
-- Main handle: heal if low, go to Moon's Eyrie, open the door, kill knights + loot.
-- =========================================================================================================
local function handle()
	-- Heal at a campfire if we're low.
	if healthCheck(0.35) then
		setStage("resting at campfire")
		playerSafeTween(
			CFrame.new(-7632.27881, 980.369873, 421.907501, -0.95457083, 0, 0.297984123, 0, 1, 0, -0.297984123, 0, -0.95457083),
			170
		)
		task.wait(1)
		local campfire = getClosestCampfire()
		local er = getEffectReplicator()
		if campfire then
			repeat
				local r = root()
				if r then
					r.CFrame = campfire.CFrame * CFrame.new(0, 1, 0)
				end
				task.wait(1)
				pcall(function()
					Prompt.interact(campfire.Parent.InteractPrompt)
				end)
				task.wait(1)
			until (er and er:FindEffect("Resting")) or not running
			repeat
				task.wait()
			until (humanoid() and humanoid().Health >= humanoid().MaxHealth * 0.5) or not running
			-- Stand up (E).
			local vim = Instance.new("VirtualInputManager")
			pcall(function()
				vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
				task.wait(0.1)
				vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
			end)
			task.wait(1)
			vim:Destroy()
		end
	end

	if not running then
		return
	end

	-- Travel to Moon's Eyrie.
	setStage("traveling to Moon's Eyrie")
	local marker = replicatedStorage:FindFirstChild("MarkerWorkspace")
	local location = marker
		and marker.AreaMarkers
		and marker.AreaMarkers:FindFirstChild("Moon's Eyrie")
		and marker.AreaMarkers["Moon's Eyrie"].AreaMarker.CFrame
	if not location then
		return
	end
	playerSafeTween(location, 170)

	local door
	repeat
		task.wait()
		door = workspace:FindFirstChild("MoonseyeDoor")
	until door or not running
	if not running then
		return
	end

	readyWeapon()
	playerSafeTween(door.CFrame * CFrame.new(0, -5, 0), 170)

	-- Open the Moon door.
	setStage("opening Moon door")
	repeat
		pcall(function()
			local moonDoor = workspace.NPCs:FindFirstChild("MoonDoor")
			if moonDoor then
				Prompt.interact(moonDoor:FindFirstChild("InteractPrompt"))
			end
		end)
		task.wait(0.5)
	until (playerGui() and playerGui():FindFirstChild("DialogueGui") and playerGui().DialogueGui.Enabled) or not running
	pcall(function()
		replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({ choice = "[Interact]" })
	end)

	tempTween(door.CFrame * CFrame.new(0, 0, -100), 170)

	-- Wait for a Moon Knight to appear.
	local waited = 0
	repeat
		task.wait(0.1)
		waited = waited + 0.1
	until waited > 3 or playerNear() or getClosestMob("moonknight", 60) or not running
	if playerNear() or not running then
		return
	end

	setStage("fighting Moon Knight")
	local knight = getClosestMob("moonknight", 60)
	local knightWasNil = knight == nil

	killTarget(knight)

	if running and not playerNear() and not healthCheck(0.35) and not knightWasNil then
		task.wait(0.5)
		grabChest()
	end

	-- A second knight may be further out.
	local knight2 = getClosestMob("moonknight", 3000)
	if knight2 then
		killTarget(knight2)
	end
end

local function toSafety()
	setStage("hiding")
	repeat
		local r = root()
		if r then
			r.CFrame = r.CFrame * CFrame.new(0, math.random(8000, 10000), 0)
		end
		task.wait()
	until not inDanger() or not running
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "moons", from = "_check_area", to = "_moonseyrie" },
		{ name = "hide", from = "_check_area", to = "_hide" },
		{ name = "hide", from = "_moonseyrie", to = "_hide" },
		{ name = "hop", from = "_moonseyrie", to = "_hop" },
		{ name = "hop", from = "_hide", to = "_hop" },
		{ name = "continuation", from = "_hide", to = "_moonseyrie" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")
			if game.PlaceId == DEPTHS_PLACE_ID then
				Logger.notify("Auto Mooneyrie: ended up in the Depths -- stopping.")
				return AutoMooneyrie.stop()
			end
			if game.PlaceId == EASTERN_PLACE_ID then
				return self:moons()
			end
		end,
		onenter_moonseyrie = function(self)
			if not running then
				return
			end
			handle()
			if playerNear() or inDanger() then
				return self:hide()
			end
			self:hop()
		end,
		onenter_hide = function(self)
			if not running then
				return
			end
			toSafety()
			self:hop()
		end,
		onenter_hop = function(self)
			if not running then
				return
			end
			serverHop()
			while task.wait() do
			end
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_mooneyrie",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"fly",
			"no_fire",
			"m1_hold",
			"no_stun",
			"fast_swing",
			"auto_equip_weapon",
			"auto_log",
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoMooneyrie.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	if not AutoMooneyrie.inValidPlace() then
		return Logger.notify("Auto Mooneyrie: not in the Eastern Luminant.")
	end
	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Mooneyrie: no data slot found.")
	end

	local data = PersistentData.get("mooneyriedata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("mooneyriedata", data)

	running = true
	buildOverlay()
	AntiAFK.start("AutoMooneyrie")

	maid:mark(task.spawn(runElapsed))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoMooneyrie.stop()
	if not running then
		return
	end
	running = false
	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end
	Tweening.stop(MOVE_ID)
	pcall(function()
		AntiAFK.stop("AutoMooneyrie")
	end)
	maid:clean()
	destroyOverlay()
	PersistentData.set("mooneyriedata", nil)
end

return AutoMooneyrie

end)
__bundle_register("@luma/Features/Automation/AutoNotes", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Notes (Ministry note farm): a luma port of project-rain-oss's `ministry_notefarm.lua`, on the
-- AutomationStruct + StateMachine framework. Creates an Etris character, shares Knowledge with the
-- Soothsayer, deposits Notes at the bank (or a guild base + treasury), then wipes and repeats. Stops once
-- the bank is full ("max notes").
--
-- Public surface:
--   AutoNotes.start() / .stop() / .inValidPlace()  (overworld / character creation / fragments)
-- Persistence key: "notesdata" { slot, startedAt, maxNotes }.
-- Menu toggle read here: NotesUseGuild.
local AutoNotes = {}

---@module Utility.PersistentData
local PersistentData = require("@luma/Utility/PersistentData")
---@module Game.ServerHop
local ServerHop = require("@luma/Game/ServerHop")
---@module Game.Wipe
local Wipe = require("@luma/Game/Wipe")
---@module Features.Game.Tweening
local Tweening = require("@luma/Features/Game/Tweening")
---@module Utility.Prompt
local Prompt = require("@luma/Utility/Prompt")
---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module Utility.SafeClick
local safeClick = require("@luma/Utility/SafeClick")
---@module GUI.Library
local Library = require("@luma/GUI/Library")
---@module Utility.CoreGuiManager
local CoreGuiManager = require("@luma/Utility/CoreGuiManager")
---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")
---@module Game.AntiAFK
local AntiAFK = require("@luma/Game/AntiAFK")
---@module Features.Automation.Objects.StateMachine
local StateMachine = require("@luma/Features/Automation/Objects/StateMachine")
---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("@luma/Features/Automation/Objects/AutomationStruct")
---@module Features.Automation.Objects.General
local General = require("@luma/Features/Automation/Objects/General")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local MAIN_GAME_PLACE_ID = 6032399813 -- overworld (Etrean Luminant) + character creation.
local MOVE_ID = "AutoNotes_Move"

local running = false
local struct = nil
local maid = Maid.new()
local screenGui, elapsedLabel = nil, nil

-- =========================================================================================================
-- Accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end
local function character()
	local lp = localPlayer()
	return lp and lp.Character
end
local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end
local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end
local function backpack()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("Backpack")
end
local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end
local function currentArea()
	local lp = localPlayer()
	return lp and lp:GetAttribute("CurrentArea")
end
local function isRunning()
	return running
end
function AutoNotes.inValidPlace()
	return game.PlaceId == MAIN_GAME_PLACE_ID
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for k, v in pairs(props) do
		instance[k] = v
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end
local function buildOverlay()
	if screenGui then
		return
	end
	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "LumaAutoNotesOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999
	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()
	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Notes",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })
	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })
	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoNotes.stop()
	end)
	pcall(function()
		Library:MakeDraggable(outer)
	end)
end
local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end
-- Stage text was removed; kept as a no-op so the many callers don't need changing.
local function setStage(_) end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("notesdata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Helpers.
-- =========================================================================================================
local function setSpeed(value)
	value = (Options and Options.NotesTweenSpeed and Options.NotesTweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end
local function tempTween(cframe, speed)
	setSpeed(speed or 250)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 4 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end
local function playerCheck(mag, custom)
	local origin = custom or (root() and root().Position)
	if not origin then
		return false
	end
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (origin - player.Character.HumanoidRootPart.Position).Magnitude <= mag then
				return true
			end
		end
	end
	return false
end
local function playersNear(target, mag)
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (player.Character.HumanoidRootPart.Position - target.Position).Magnitude <= mag then
				return true
			end
		end
	end
	return false
end
local function serverHop()
	pcall(function()
		ServerHop.hop(currentSlot(), true)
	end)
end
local function playerSafeTween(cf, speed, level)
	if playerCheck(200) then
		serverHop()
		while task.wait() do
		end
		return
	end
	local yLevel = level or -20
	local r = root()
	if not r then
		return
	end
	r.CFrame = r.CFrame + Vector3.new(0, yLevel, 0)
	tempTween(cf + Vector3.new(0, yLevel, 0), speed)
	if playerCheck(200, cf.Position) then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
end
local function dialogueChoice(value)
	pcall(function()
		replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({ choice = value })
	end)
end
local function dialogueExit()
	pcall(function()
		replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({ exit = true })
	end)
end
local function click(btn)
	if btn then
		-- safeClick (handler .Function call) instead of firesignal -- firesignal is a native-crash risk pcall
		-- can't catch (see Utility/SafeClick).
		safeClick(btn)
		task.wait(0.2)
	end
end
local function dialogueOpen()
	local gui = playerGui()
	local dg = gui and gui:FindFirstChild("DialogueGui")
	return dg ~= nil and dg.Enabled
end
local function currencyText(name)
	local gui = playerGui()
	local frame = gui and gui:FindFirstChild("CurrencyGui")
	frame = frame and frame:FindFirstChild("CurrencyFrame")
	local entry = frame and frame:FindFirstChild(name)
	local amount = entry and entry:FindFirstChild("Amount")
	return amount and amount.Text or ""
end
local function currentNotes()
	return tonumber((currencyText("Notes"):gsub("%D", ""))) or 0
end
local function hasKnowledge()
	local k = tonumber(currencyText("ShrinePoints"))
	return k ~= nil and k > 0
end

-- =========================================================================================================
-- Banking.
-- =========================================================================================================
local function setBankAmountAndConfirm(amount)
	local gui = playerGui()
	repeat
		task.wait(0.1)
		gui = playerGui()
	until (gui and gui:FindFirstChild("ChoicePrompt")) or not running
	local cp = gui and gui:FindFirstChild("ChoicePrompt")
	if not cp then
		return false
	end
	local slider = cp:FindFirstChild("ChoiceFrame", true)
	slider = slider and slider:FindFirstChild("DescSheet", true)
	slider = slider and slider:FindFirstChild("SliderSheet", true)
	if not slider then
		return false
	end
	local gen = slider:FindFirstChild("GenericSlider")
	local numberBox = gen and gen:FindFirstChild("Number")
	if numberBox and numberBox:IsA("TextBox") then
		numberBox.Text = tostring(amount)
		task.wait(0.2)
		pcall(function()
			numberBox:CaptureFocus()
			task.wait(0.1)
			numberBox:ReleaseFocus()
		end)
		task.wait(0.2)
	end
	local buttons = slider:FindFirstChild("Buttons")
	local submit = buttons and buttons:FindFirstChild("Submit")
	if submit then
		click(submit)
		return true
	end
	return false
end
local function depositAllNotes()
	local notes = currentNotes()
	if notes == 0 then
		return false
	end
	local bankGui = playerGui() and playerGui():FindFirstChild("BankGui")
	if not bankGui then
		return false
	end
	pcall(function()
		bankGui:WaitForChild("Choice"):FireServer("notes_deposit")
	end)
	task.wait(1)
	return setBankAmountAndConfirm(notes)
end
local function closeBankGui()
	local bankGui = playerGui() and playerGui():FindFirstChild("BankGui")
	if bankGui then
		click(bankGui:FindFirstChild("Close"))
	end
end
local function openBankAndDeposit()
	local banker = workspace.NPCs:FindFirstChild("Banker")
	if not banker then
		return false
	end
	pcall(function()
		replicatedStorage.Requests.InteractPrompt:FireServer(banker.InteractPrompt)
	end)
	task.wait(1)
	repeat
		task.wait(0.1)
	until dialogueOpen() or not running
	dialogueChoice("Can I access my account?")
	task.wait(1)
	repeat
		task.wait(0.5)
	until (playerGui() and playerGui():FindFirstChild("BankGui")) or not running
	task.wait(1)
	local success = depositAllNotes()
	closeBankGui()
	dialogueExit()
	return success
end

-- =========================================================================================================
-- Overworld: share knowledge, deposit notes.
-- =========================================================================================================
local function shareKnowledge()
	if not hasKnowledge() then
		return
	end
	setStage("sharing knowledge")
	local npcCF = CFrame.new(-541.776306, 935.564697, -7180.49707, 0.850063145, 0, 0.526680827, 0, 1, 0, -0.526680827, 0, 0.850063145)
	playerSafeTween(npcCF, 250)

	local soothsayer
	repeat
		soothsayer = workspace.NPCs:FindFirstChild("Soothsayer")
		task.wait()
	until soothsayer or not running
	if not soothsayer then
		return
	end
	repeat
		pcall(function()
			Prompt.interact(soothsayer:FindFirstChildOfClass("ProximityPrompt"))
		end)
		task.wait(0.5)
	until dialogueOpen() or not running
	task.wait(1)
	dialogueChoice("[Share your Knowledge]")
	task.wait(0.5)
	dialogueChoice(tonumber(currencyText("ShrinePoints")))
	task.wait(0.5)
	dialogueExit()
	task.wait(0.5)
end

local function depositNotesAtBank()
	if currentNotes() <= 0 then
		return
	end
	if PersistentData.get("notesdata") and PersistentData.get("notesdata").maxNotes then
		AutoNotes.stop()
		return
	end

	setStage("banking notes")
	local bankerCF = CFrame.new(1563.5769, 164.524414, -4312.33643, -0.104543328, 0, -0.994520426, 0, 1, 0, 0.994520426, 0, -0.104543328)
	playerSafeTween(bankerCF * CFrame.new(0, -5, 0), 170, math.random(10000, 30000))

	local banker
	repeat
		for _, npc in next, workspace.NPCs:GetChildren() do
			if npc.Name:match("Banker") and npc:FindFirstChild("HumanoidRootPart") then
				if not banker then
					banker = npc
				elseif (root().Position - npc.HumanoidRootPart.Position).Magnitude < (root().Position - banker.HumanoidRootPart.Position).Magnitude then
					banker = npc
				end
			end
		end
		task.wait()
	until banker or not running

	openBankAndDeposit()
	task.wait(3.5)
	if currentNotes() > 0 then
		-- Still holding notes -> bank is full.
		PersistentData.stf("notesdata", "maxNotes", true)
		AutoNotes.stop()
	end
end

local function useGuild()
	return Toggles and Toggles.NotesUseGuild and Toggles.NotesUseGuild.Value == true
end

local GUILD_PLACEMENTS = {
	CFrame.new(-996.915771, 998.557617, -7053.39062, 0.20362483, 0, -0.979048967, 0, 1, 0, 0.979048967, 0, 0.20362483),
	CFrame.new(-376.312347, 1109.97266, -6917.1875, 0.830629528, 0, 0.556825459, 0, 1, 0, -0.556825459, 0, 0.830629528),
	CFrame.new(237.318726, 1135.56323, -7003.09619, 0.981070876, 0, 0.193649009, 0, 1, 0, -0.193649009, 0, 0.981070876),
}

---Place the guild base door (Chime of Dwelling) at the first free spot and enter it.
local function placeGuildDoor()
	setStage("placing guild door")
	for _, location in ipairs(GUILD_PLACEMENTS) do
		local near = false
		for _, door in next, workspace:GetChildren() do
			if door:IsA("Part") and door.Name:find("Guild") then
				if (location.Position - door.Position).Magnitude <= 50 or playersNear(location, 400) then
					near = true
					break
				end
			end
		end
		if not near then
			playerSafeTween(location, 250)
			break
		end
	end

	task.wait(1)
	local bp = backpack()
	local chime = bp and bp:FindFirstChild("Chime of Dwelling")
	if chime then
		chime.Parent = character()
		pcall(function()
			character()["Chime of Dwelling"]:Activate()
		end)
	end

	local closest
	repeat
		for _, door in next, workspace:GetChildren() do
			if door:IsA("Part") and door.Name:find("GuildDoor") and door:FindFirstChild("InteractPrompt") then
				if root() and (root().Position - door.Position).Magnitude <= 5 then
					closest = door
					break
				end
			end
		end
		task.wait()
	until closest or not running
	if not closest then
		return
	end

	repeat
		pcall(function()
			Prompt.interact(closest:FindFirstChild("InteractPrompt"))
		end)
		task.wait(0.5)
	until (currentArea() and tostring(currentArea()):find("Base")) or not running
	task.wait(1)
end

---Deposit at the guild bank, then push the overflow into the guild treasury.
local function depositNotesAtGuild()
	placeGuildDoor()
	if not running then
		return
	end

	local guildAttr = localPlayer():GetAttribute("Guild")
	if not guildAttr then
		return
	end
	local guildName = tostring(guildAttr)
		:lower()
		:gsub("%s*%[.-%]%s*", " ")
		:gsub("^%d+", "")
		:gsub("z%w+divider", "")
		:gsub("[^%a%d]", "")

	local banker, treasurer
	for _, npc in next, workspace.NPCs:GetChildren() do
		if banker and treasurer then
			break
		end
		if npc:IsA("Model") and npc:GetAttribute("Guild") and tostring(npc:GetAttribute("Guild")):match(guildName) then
			if npc.Name:match("Banker") then
				banker = npc
			elseif npc.Name:match("Treasurer") then
				treasurer = npc
			end
		end
	end

	local data = PersistentData.get("notesdata")
	if banker and banker:FindFirstChild("HumanoidRootPart") and not (data and data.maxNotes) then
		setStage("guild bank")
		tempTween(banker.HumanoidRootPart.CFrame * CFrame.new(5, 0, 0), 170)
		openBankAndDeposit()
		task.wait(3.5)
		if currentNotes() > 0 then
			PersistentData.stf("notesdata", "maxNotes", true)
		end
	end

	if currentNotes() > 0 and treasurer and treasurer:FindFirstChild("HumanoidRootPart") then
		setStage("guild treasury")
		tempTween(treasurer.HumanoidRootPart.CFrame * CFrame.new(5, 0, 0), 170)
		repeat
			pcall(function()
				Prompt.interact(treasurer:FindFirstChildOfClass("ProximityPrompt"))
			end)
			task.wait(0.5)
		until dialogueOpen() or not running
		dialogueChoice("I'd like to add money to the treasury. [Add to Treasury]")
		task.wait(0.5)
		dialogueChoice(20000)
		task.wait(0.5)
		dialogueExit()
	end
end

local function overworld()
	repeat
		task.wait()
	until character() or not running
	shareKnowledge()
	if not running then
		return
	end
	if currentNotes() > 0 then
		if useGuild() then
			depositNotesAtGuild()
		else
			depositNotesAtBank()
		end
	end
end

-- =========================================================================================================
-- Fragments cash-in (Self [The End]) -- same shape as Echo, no echo counting needed here.
-- =========================================================================================================
local function handleFragments()
	setStage("fragments")
	local self_npc
	local deadline = os.clock() + 40
	repeat
		local npcs = workspace:FindFirstChild("NPCs")
		self_npc = npcs and npcs:FindFirstChild("Self")
		task.wait()
	until self_npc or os.clock() >= deadline or not running
	if not self_npc then
		serverHop()
		return
	end

	local tpLocation = (self_npc:GetPivot() - Vector3.new(0, 15.7, 0))
		* CFrame.Angles(math.rad(180), math.rad(90), math.rad(180))
	if playerCheck(200, tpLocation.Position) then
		serverHop()
		while task.wait() do
		end
		return
	end

	local sendDialogue = replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue")
	local prompt = self_npc:WaitForChild("InteractPrompt", 10)
	local start = tick()
	repeat
		local r = root()
		if r then
			r.CFrame = tpLocation
		end
		if prompt then
			Prompt.interact(prompt)
		end
		pcall(function()
			sendDialogue:FireServer({ choice = "[The End]" })
		end)
		task.wait(0.25)
	until (workspace:FindFirstChild("CharacterCreator") and character() and character().Parent == workspace.CharacterCreator)
		or not (currentArea() and tostring(currentArea()):match("Fragments of Self"))
		or not running
		or tick() - start > 20
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local function isCharacterCreation()
	local cc = workspace:FindFirstChild("CharacterCreator")
	local c = character()
	return cc ~= nil and c ~= nil and c.Parent == cc
end

local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "overworld", from = "_check_area", to = "_overworld" },
		{ name = "fragments", from = "_check_area", to = "_handle_fragments" },
		{ name = "die", from = "_check_area", to = "_die" },
		{ name = "cc", from = "_check_area", to = "_create_character" },
		{ name = "continuation", from = "_create_character", to = "_check_area" },
		{ name = "continuation", from = "_handle_fragments", to = "_check_area" },
		{ name = "continuation", from = "_overworld", to = "_check_area" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")

			local area = currentArea()
			if area and tostring(area):match("Fragments of Self") then
				return self:fragments()
			end

			if isCharacterCreation() then
				return self:cc()
			end

			if area and tostring(area):match("The Depths") then
				return self:die()
			end

			if game.PlaceId == MAIN_GAME_PLACE_ID then
				-- If we're in a guild base, respawn to the Inn first.
				if area and tostring(area):find("Base") then
					General.respawn()
					repeat
						task.wait()
					until (playerGui() and playerGui():FindFirstChild("SpawnPrompt")) or not running
					pcall(function()
						playerGui().SpawnPrompt.Choice:FireServer("Inn")
					end)
					repeat
						task.wait()
					until character() or not running
				end
				return self:overworld()
			end
		end,
		onenter_create_character = function(self)
			if not running then
				return
			end
			setStage("create character")
			struct:create_character()
			self:continuation()
		end,
		onenter_handle_fragments = function(self)
			if not running then
				return
			end
			handleFragments()
			self:continuation()
		end,
		onenter_overworld = function(self)
			if not running then
				return
			end
			setStage("overworld")
			overworld()
			if not running then
				return
			end
			-- Wipe and reroll.
			local slot = currentSlot() or (PersistentData.get("notesdata") and PersistentData.get("notesdata").slot)
			pcall(function()
				Wipe.invoke(slot)
			end)
		end,
		onenter_die = function(self)
			if not running then
				return
			end
			local slot = currentSlot() or (PersistentData.get("notesdata") and PersistentData.get("notesdata").slot)
			pcall(function()
				Wipe.invoke(slot)
			end)
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_notes",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"mod_detector",
			"fly",
			"auto_equip_weapon",
			"auto_log",
		},
		character_creator_handler_used = true,
		character_creator_handler_opts = {
			origin = "Etris",
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================

---Menu Start: wipe the current character first (like Echo Farm), then Luma's resume (notesdata) drops us
---into a fresh farm cycle.
function AutoNotes.invoke()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Notes: no data slot found.")
	end

	PersistentData.set("notesdata", {
		slot = slot,
		startedAt = os.time(),
	})

	-- Wipe the current character on start; the wipe teleports us out and the resume brings us back in.
	pcall(function()
		Wipe.invoke(slot)
	end)
end

function AutoNotes.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Notes: no data slot found.")
	end

	local data = PersistentData.get("notesdata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("notesdata", data)

	running = true
	buildOverlay()
	AntiAFK.start("AutoNotes")

	maid:mark(task.spawn(runElapsed))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoNotes.stop()
	if not running then
		return
	end
	running = false
	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end
	Tweening.stop(MOVE_ID)
	pcall(function()
		AntiAFK.stop("AutoNotes")
	end)
	maid:clean()
	destroyOverlay()
	PersistentData.set("notesdata", nil)
end

return AutoNotes

end)
__bundle_register("@luma/Features/Automation/AutoProg", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Prog: PR's auto progression, luma-native. Ties the Auto Builder (invest attribute points +
-- pick talent/mantra cards toward the pre/post spread) together with a farm (Auto Ferryman or Auto
-- Saramed) that earns the points, with a small state machine:
--
--   DOING_PRESHRINE  -- farm + build the pre spread; when the pre attributes are met, KICK to shrine.
--   DOING_POSTSHRINE -- farm + build the post spread; when the final attributes are met, KICK (done).
--
-- No persistence: after the kick, rejoin, re-execute luma, and press "Start Postshrine" (or "Start
-- Preshrine") to continue. The in-progress build + farm resume across the farm's own server hops via
-- their own MemStorage state.
--
-- Omits PR's Trial of One / Brutus fortitude / depths escape / rejoin-slot machinery (PR-only infra).

---@module Features.Automation.AutoBuilder
local AutoBuilder = require("@luma/Features/Automation/AutoBuilder")

---@module Features.Automation.AutoFerryman
local AutoFerryman = require("@luma/Features/Automation/AutoFerryman")

---@module Features.Automation.AutoSaramed
local AutoSaramed = require("@luma/Features/Automation/AutoSaramed")

---@module Utility.Configuration
local Configuration = require("@luma/Utility/Configuration")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Utility.Signal
local Signal = require("@luma/Utility/Signal")

local players = game:GetService("Players")
local runService = game:GetService("RunService")

local AutoProg = {}

local CHECK_INTERVAL = 1.0

-- In-memory only: "NULL" | "DOING_PRESHRINE" | "DOING_POSTSHRINE".
local state = "NULL"

local progMaid = Maid.new()
local lastCheck = 0

local function farmMethod()
	return Configuration.expectOptionValue("AutoProgFarmMethod") or "Ferryman"
end

local function startFarm()
	-- Each farm self-guards on location (teleports/hops if we're not there) and is idempotent.
	if farmMethod() == "Saramed" then
		AutoSaramed.start()
	else
		AutoFerryman.start()
	end
end

local function stopFarms()
	pcall(AutoFerryman.stop)
	pcall(AutoSaramed.stop)
end

---Aim the builder at a spread, start building (invest + pick), and run the farm.
---@param phase "pre"|"post"
local function runPhase(phase)
	AutoBuilder.setTarget(phase)
	AutoBuilder.startPicking()
	startFarm()
end

---Stop everything and kick with a message.
---@param message string
local function endRun(message)
	state = "NULL"
	AutoBuilder.stopPicking()
	stopFarms()

	pcall(function()
		players.LocalPlayer:Kick(message)
	end)
end

---Start a phase from the UI.
---@param phase "pre"|"post"
---@return boolean
function AutoProg.start(phase)
	if phase ~= "pre" and phase ~= "post" then
		return false
	end

	if not AutoBuilder.current then
		Logger.notify("Auto Prog: load a build first.")
		return false
	end

	state = phase == "post" and "DOING_POSTSHRINE" or "DOING_PRESHRINE"
	runPhase(phase)

	Logger.notify(
		string.format(
			"Auto Prog: %s started (farming %s).",
			phase == "post" and "postshrine" or "preshrine",
			farmMethod()
		)
	)

	return true
end

---@return boolean
function AutoProg.startPreshrine()
	return AutoProg.start("pre")
end

---@return boolean
function AutoProg.startPostshrine()
	return AutoProg.start("post")
end

function AutoProg.stop()
	state = "NULL"
	AutoBuilder.stopPicking()
	stopFarms()
	Logger.notify("Auto Prog: stopped.")
end

---@return boolean
function AutoProg.isRunning()
	return state == "DOING_PRESHRINE" or state == "DOING_POSTSHRINE"
end

-- The state-machine watcher: kicks to shrine when preshrine is done, and kicks when the build is
-- finished. Armed once at init.
function AutoProg.init()
	local renderStepped = Signal.new(runService.RenderStepped)

	progMaid:add(renderStepped:connect("AutoProg_Watch", function()
		if os.clock() - lastCheck < CHECK_INTERVAL then
			return
		end
		lastCheck = os.clock()

		if state == "DOING_PRESHRINE" then
			if AutoBuilder.shrineReady() then
				endRun(
					'Auto Prog: preshrine done. shrine, then rejoin and press "Start Postshrine".'
				)
			end
		elseif state == "DOING_POSTSHRINE" then
			if AutoBuilder.finished() then
				endRun("Auto Prog: build finished. :)")
			end
		end
	end))

	if not LPH_OBFUSCATED or (shared.Luma and shared.Luma.verbose) then
		Logger.warn("Auto Prog initialized.")
	end
end

function AutoProg.detach()
	progMaid:clean()
end

return AutoProg

end)
__bundle_register("@luma/Features/Automation/AutoSaramed", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto Saramed: a luma port of project-rain-oss's `auto_saramed.lua`, on the AutomationStruct +
-- StateMachine framework. Enters the Saramed deepdrill dungeon (via Malisae in the Eastern Luminant),
-- clears the mobs, mines the magma ore, deposits it into the drill, loots, then resets the dungeon and
-- repeats. Keeps hunger/thirst topped up (gather + craft bread, drink at the well).
--
-- Public surface:
--   AutoSaramed.start() / .stop() / .inValidPlace()  (Eastern Luminant or the Saramed dungeon)
-- Persistence key: "sarameddata" { slot, startedAt }.
local AutoSaramed = {}

---@module Utility.PersistentData
local PersistentData = require("@luma/Utility/PersistentData")
---@module Utility.Prompt
local Prompt = require("@luma/Utility/Prompt")
---@module Game.ServerHop
local ServerHop = require("@luma/Game/ServerHop")
---@module Features.Game.Tweening
local Tweening = require("@luma/Features/Game/Tweening")
---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")
---@module GUI.Library
local Library = require("@luma/GUI/Library")
---@module Utility.CoreGuiManager
local CoreGuiManager = require("@luma/Utility/CoreGuiManager")
---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")
---@module Game.AntiAFK
local AntiAFK = require("@luma/Game/AntiAFK")
---@module Features.Automation.Objects.StateMachine
local StateMachine = require("@luma/Features/Automation/Objects/StateMachine")
---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("@luma/Features/Automation/Objects/AutomationStruct")
---@module Features.Automation.Objects.General
local General = require("@luma/Features/Automation/Objects/General")
---@module Features.Automation.Objects.Teleports
local Teleports = require("@luma/Features/Automation/Objects/Teleports")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local SARAMED_PLACE_ID = 8668476218 -- the deepdrill (Saramed) dungeon.
local EASTERN_PLACE_ID = 6473861193 -- Eastern Luminant (Malisae, the dungeon entrance).
local MAIN_GAME_PLACE_ID = 6032399813 -- Etrean overworld (route back to Eastern from here).
local DEPTHS_PLACE_ID = 5735553160 -- The Depths (should never be here; stop if we are).

local MOVE_ID = "AutoSaramed_Move"
local MIN_HEALTH = 0.5 -- retreat/bail on the fight at or below this health fraction (raised from PR's 0.25 -- retreat earlier, at half HP).
local ATTACH_DISTANCE = 8 -- studs above the mob's torso when attaching (PR default: 8).

local running = false
local struct = nil
local maid = Maid.new()
local screenGui, elapsedLabel = nil, nil
local autoDepositThread = nil
local disconnectHandlerSet = false
local previousAutoDefense = nil -- EnableAutoDefense state before the run, restored on stop

local function isSaramed()
	return game.PlaceId == SARAMED_PLACE_ID
end

-- =========================================================================================================
-- Accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end
local function character()
	local lp = localPlayer()
	return lp and lp.Character
end
local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end
local function humanoid()
	local c = character()
	return c and c:FindFirstChildOfClass("Humanoid")
end
local function backpack()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("Backpack")
end
local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end
local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end
local function isRunning()
	return running
end
function AutoSaramed.inValidPlace()
	return game.PlaceId == SARAMED_PLACE_ID or game.PlaceId == EASTERN_PLACE_ID or game.PlaceId == MAIN_GAME_PLACE_ID
end
local function getEffectReplicator()
	local ok, mod = pcall(function()
		return require(replicatedStorage:WaitForChild("EffectReplicator"))
	end)
	return ok and mod or nil
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for k, v in pairs(props) do
		instance[k] = v
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end
local function buildOverlay()
	if screenGui then
		return
	end
	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "LumaAutoSaramedOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999
	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()
	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })
	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Saramed",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })
	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })
	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoSaramed.stop()
	end)
	pcall(function()
		Library:MakeDraggable(outer)
	end)
end
local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end
-- Stage text was removed; kept as a no-op so the many callers don't need changing.
local function setStage(_) end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("sarameddata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Movement + helpers.
-- =========================================================================================================
local function setSpeed(value)
	value = (Options and Options.SaramedTweenSpeed and Options.SaramedTweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end
local function tempTween(cframe, speed)
	setSpeed(speed or 170)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 4 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end
local function tweenGoal(cframe, speed)
	setSpeed(speed or 100)
	Tweening.goal(MOVE_ID, cframe, false)
end
local function playerCheck(mag, custom)
	local origin = custom or (root() and root().Position)
	if not origin then
		return false
	end
	for _, player in next, players:GetPlayers() do
		if player ~= localPlayer() and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			if (origin - player.Character.HumanoidRootPart.Position).Magnitude <= mag then
				return true
			end
		end
	end
	return false
end
local function serverHop()
	pcall(function()
		ServerHop.hop(currentSlot(), true)
	end)
end
local function playerSafeTween(cf, speed)
	if playerCheck(200) then
		serverHop()
		while task.wait() do
		end
		return
	end
	local r = root()
	if not r then
		return
	end
	local y = math.random(10000, 30000)
	r.CFrame = r.CFrame + Vector3.new(0, y, 0)
	tempTween(cf + Vector3.new(0, y, 0), speed)
	if playerCheck(200, cf.Position) then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
	task.wait(0.3)
end
local function readyWeapon()
	pcall(function()
		character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
	end)
end
local function m1Hold(state)
	local feat = struct and struct.active_features and struct.active_features["m1_hold"]
	if feat then
		feat.held = state
	end
end
local function healthCheck(percent)
	local hum = humanoid()
	return hum ~= nil and hum.Health <= (hum.MaxHealth * percent)
end
local function statValue(name)
	local c = character()
	return c and c:FindFirstChild(name)
end
local function clampCFrame(cf)
	return CFrame.new(Vector3.new(cf.Position.X, math.clamp(cf.Position.Y, 0, 1000), cf.Position.Z))
end

-- (Food/water refill removed -- hunger and thirst upkeep both dropped.)

-- =========================================================================================================
-- Combat + mining.
-- =========================================================================================================
local function foundMobs()
	for _, mob in next, workspace:WaitForChild("Live"):GetChildren() do
		if mob:GetAttribute("MOB_rich_name") then
			return true
		end
	end
	return false
end

local function closestMob()
	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil
	end
	local closest, shortest = nil, math.huge
	for _, model in next, live:GetChildren() do
		if model:IsA("Model") and model ~= character() and model.Name:sub(1, 1) == "." then
			local r = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
			local hum = model:FindFirstChildOfClass("Humanoid")
			if r and hum and hum.Health > 0 then
				local torso = model:FindFirstChild("Torso")
				if not (torso and torso:FindFirstChild("RagdollAttach")) then
					local dist = (r.Position - (root() and root().Position or Vector3.zero)).Magnitude
					if dist < shortest then
						shortest = dist
						closest = model
					end
				end
			end
		end
	end
	return closest
end

local function killTarget(target)
	if not target or not target:IsA("Model") then
		return
	end
	if target.Name:match(localPlayer().Name) then
		return
	end

	readyWeapon()
	if target:FindFirstChild("HumanoidRootPart") then
		tempTween(target.HumanoidRootPart.CFrame, 170)
	end

	local attach = task.spawn(function()
		local activeTween = false
		while running do
			if not target.Parent then
					break
				end
				local hrp = target:FindFirstChild("HumanoidRootPart")
				if not hrp then
					task.wait()
					continue
				end
				local cf
			if target.Name:lower():find("buncle") or target.Name:lower():find("knight") then
				cf = clampCFrame(hrp.CFrame) * CFrame.new(0, -ATTACH_DISTANCE, 0) * CFrame.Angles(math.rad(90), 0, 0)
			else
				cf = clampCFrame(hrp.CFrame) * CFrame.new(0, ATTACH_DISTANCE, 0) * CFrame.Angles(math.rad(-90), 0, 0)
			end
			local r = root()
			if r then
				r.AssemblyLinearVelocity = Vector3.zero
				if (r.Position - cf.Position).Magnitude > 30 then
					tweenGoal(cf, 100)
					activeTween = true
				else
					if activeTween then
						Tweening.stop(MOVE_ID)
						activeTween = false
					end
					r.CFrame = cf
				end
			end
			task.wait()
		end
		Tweening.stop(MOVE_ID)
	end)

	m1Hold(true)
	local startedAt = tick()
	repeat
		task.wait()
		m1Hold(true)
		local hum = target:FindFirstChildOfClass("Humanoid")
	until healthCheck(MIN_HEALTH) or target.Parent == nil or (hum and hum.Health <= 0) or (tick() - startedAt > 20) or not running
	pcall(function()
		task.cancel(attach)
	end)
	m1Hold(false)
	Tweening.stop(MOVE_ID)
	return healthCheck(MIN_HEALTH)
end

local function closestOre()
	local closest
	for _, ore in next, workspace:GetDescendants() do
		if ore:IsA("MeshPart") and ore.Name:match("MagmaOre") and ore:FindFirstChild("InteractPrompt") then
			if not closest then
				closest = ore
			elseif (root().Position - ore.Position).Magnitude < (root().Position - closest.Position).Magnitude then
				closest = ore
			end
		end
	end
	return closest
end

local function mineOre(target)
	if not target or target.Parent == nil or not target:IsA("MeshPart") or not target.Name:match("MagmaOre") then
		return false
	end
	tempTween(target.CFrame, 170)
	local r = root()
	if r then
		r.CFrame = target.CFrame
	end
	xpcall(function()
		for _ = 1, 60 do
			if not running then
				break
			end
			if root() then
				root().CFrame = target.CFrame
			end
			pcall(function()
				local prompt = target:FindFirstChild("InteractPrompt")
				if prompt then
					Prompt.interact(prompt)
				end
			end)
			task.wait()
		end
		local debounce = tick()
		repeat
			task.wait()
		until not target:FindFirstChild("InteractPrompt") or tick() - debounce > 5 or not running
	end, function() end)
	return true
end

local function depositOre()
	local deepdrill = workspace:FindFirstChild("Deepdrill")
	local dungeondrill = deepdrill and deepdrill:FindFirstChild("DungeonDrill")
	local fuelport = dungeondrill and dungeondrill:FindFirstChild("FuelPort")
	local hit = fuelport and fuelport:FindFirstChild("Hit")
	if hit then
		tempTween(hit.CFrame, 170)
		task.wait(1)
	end
end

local function grabChest()
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return
	end
	for _, chest in next, thrown:GetChildren() do
		if chest:FindFirstChild("Lid") then
			tempTween(chest.Lid.CFrame, 170)
			local t = tick()
			repeat
				task.wait(0.1)
				pcall(function()
					Prompt.interact(chest:FindFirstChildWhichIsA("ProximityPrompt"))
				end)
				pcall(function()
					tempTween(chest.Lid.CFrame, 170)
				end)
			until (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or tick() - t > 5
			local t2 = tick()
			repeat
				task.wait(0.1)
			until not (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or tick() - t2 > 5
			break
		end
	end
end

-- =========================================================================================================
-- Stages.
-- =========================================================================================================
local function pathToSaramed()
	if isSaramed() then
		return
	end
	if game.PlaceId == EASTERN_PLACE_ID then
		setStage("entering Saramed")
		local malisaeCF = CFrame.new(-2835.7998046875, 136.5481414794922, 3442.84814453125, 0.541101158, 0, -0.840957522, 0, 1, 0, 0.840957522, 0, 0.541101158)
		playerSafeTween(malisaeCF, 170)
		task.wait(0.5)
		repeat
			task.wait()
		until workspace.NPCs:FindFirstChild("Malisae") or not running
		pcall(function()
			Prompt.interact(workspace.NPCs.Malisae.InteractPrompt)
		end)
		task.wait(3)
		pcall(function()
			replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({ choice = "Enter alone." })
		end)
		task.wait(5)
	end
end

local function checkPlayerStatus()
	-- Food/water upkeep removed; nothing to do here now. Kept as a no-op so the _status state's call to it
	-- stays valid.
end

local function startDungeon()
	if not isSaramed() then
		return
	end
	repeat
		task.wait()
	until character() or not running

	if not (backpack() and backpack():FindFirstChild("Pickaxe")) and not (character() and character():FindFirstChild("Pickaxe")) then
		Logger.notify("[Auto Saramed] Please buy a pickaxe.")
		repeat
			task.wait()
		until (backpack() and backpack():FindFirstChild("Pickaxe"))
			or (character() and character():FindFirstChild("Pickaxe"))
			or not running
	end

	local deepdrill = workspace:FindFirstChild("Deepdrill")
	if not deepdrill then
		return
	end
	local drillSwitch = deepdrill.DungeonDrill.Switch.Case
	local evatorSwitch = deepdrill.Drillevator.Switch.Case
	local drillDist = (drillSwitch.Position - (root() and root().Position or Vector3.zero)).Magnitude
	local evatorDist = (evatorSwitch.Position - (root() and root().Position or Vector3.zero)).Magnitude

	setStage("starting dungeon")
	-- Use the nearer switch (DungeonDrill vs Drillevator).
	local useDrill = drillDist < evatorDist
	local switchCase = useDrill and drillSwitch or evatorSwitch
	local switchObj = useDrill and deepdrill.DungeonDrill.Switch or deepdrill.Drillevator.Switch
	-- Keep pressing it until the drill actually starts (mobs spawn). A single press sometimes misses -- the
	-- tween hasn't landed or the prompt is briefly out of range -- and nothing retried, so completeDungeon
	-- then waited forever on mobs that never came and the farm just stopped. Re-tween + re-press each pass.
	repeat
		if root() then
			root().CFrame = CFrame.new(root().CFrame.X, switchCase.CFrame.Y, root().CFrame.Z)
		end
		-- Nudge the stand spot 2 studs right (+X) and 1 stud forward (-Z, the lever's LookVector) relative
		-- to the lever, so we land on the interactable side instead of on top of the Case.
		tempTween(switchCase.CFrame * CFrame.new(2, 0, -1), 170)
		task.wait(1)
		pcall(function()
			Prompt.interact(switchObj.InteractPrompt)
		end)
		task.wait(2)
	until foundMobs() or not running
end

local function completeDungeon()
	if not isSaramed() then
		return
	end
	setStage("clearing mobs")
	repeat
		task.wait()
	until foundMobs() or not running

	repeat
		pcall(function()
			killTarget(closestMob())
		end)
		if healthCheck(MIN_HEALTH) or not running then
			break
		end
		task.wait()
	until not foundMobs()

	if not running or healthCheck(MIN_HEALTH) then
		return
	end

	setStage("mining ore")
	for _ = 0, 5 do
		local ore
		repeat
			ore = closestOre()
			task.wait()
		until ore ~= nil or not running
		if not running then
			break
		end
		mineOre(ore)
	end
	if not running then
		return
	end

	depositOre()

	-- Keep mining until the fuel bar is full (green).
	local function fuelFull()
		local ok, full = pcall(function()
			local bar = workspace.Deepdrill.DungeonDrill.FuelPort.Display.SurfaceGui.Bar
			return bar.BackgroundColor3:ToHex() == Color3.fromRGB(141, 239, 112):ToHex()
		end)
		return ok and full
	end
	if not fuelFull() then
		repeat
			for _, ore in next, workspace:GetDescendants() do
				if ore:IsA("MeshPart") and ore.Name:match("MagmaOre") then
					if not running then
						break
					end
					mineOre(ore)
					break
				end
			end
			depositOre()
			task.wait()
		until fuelFull() or not running
	end

	if not running then
		return
	end
	setStage("looting")
	grabChest()
end

local function resetDungeon()
	if not isSaramed() or not running then
		return
	end
	setStage("resetting dungeon")
	local deepdrill = workspace:FindFirstChild("Deepdrill")
	local dungeondrill = deepdrill and deepdrill:FindFirstChild("DungeonDrill")
	local radio = dungeondrill and dungeondrill:FindFirstChild("Radio")
	local destructibles = workspace:FindFirstChild("Destructibles")
	if not radio or not destructibles then
		return
	end

	-- Retreat uses the radio (workspace.Deepdrill.DungeonDrill.Radio), NOT the lever -- the lever is for
	-- going deeper, the radio is for retreating. Tween onto the RADIO itself (GetPivot handles part-or-model)
	-- and press E on it (same as every other interaction) until the retreat ChoicePrompt shows, then confirm.
	tempTween(radio:GetPivot(), 170)
	local vim = Instance.new("VirtualInputManager")
	repeat
		task.wait()
		pcall(function()
			vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
			task.wait(0.1)
			vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
		end)
		tempTween(radio:GetPivot(), 170)
	until (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running
	vim:Destroy()
	pcall(function()
		playerGui().ChoicePrompt.Choice:FireServer(true)
	end)

	local campfire = destructibles:FindFirstChild("Campfire")
	if not campfire then
		return
	end
	local dist = math.huge
	repeat
		task.wait()
		local part = campfire:FindFirstChildWhichIsA("Part")
		if part then
			dist = (part.Position - (root() and root().Position or Vector3.zero)).Magnitude
		end
	until dist <= 150 or not running

	if not healthCheck(0.7) then
		return
	end

	local er = getEffectReplicator()
	repeat
		tempTween(campfire.Part.CFrame, 170)
		if root() then
			root().CFrame = campfire.Part.CFrame * CFrame.new(0, 1, 0)
		end
		task.wait(1)
		pcall(function()
			Prompt.interact(campfire.InteractPrompt)
		end)
		task.wait(1)
	until (er and er:FindEffect("Resting")) or not running
	repeat
		task.wait()
	until (humanoid() and humanoid().Health >= humanoid().MaxHealth * 0.7) or not running
	local vim = Instance.new("VirtualInputManager")
	pcall(function()
		vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)
		task.wait(0.1)
		vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)
	end)
	task.wait(1)
	vim:Destroy()
end

-- On a Roblox disconnect (kick), keep the slot in MemStorage and server-hop to reconnect (PR resilience).
local function setupDisconnectHandler()
	if disconnectHandlerSet then
		return
	end
	disconnectHandlerSet = true
	local guiService = game:GetService("GuiService")
	maid:mark(guiService.ErrorMessageChanged:Connect(function()
		local ok, code = pcall(function()
			return guiService:GetErrorCode().Value
		end)
		if ok and code and code >= Enum.ConnectionError.DisconnectErrors.Value then
			pcall(function()
				local memStorage = game:GetService("MemStorageService")
				memStorage:SetItem("DataSlot", localPlayer():GetAttribute("DataSlot"))
			end)
			while task.wait() do
				pcall(serverHop)
			end
		end
	end))
end

-- Auto-deposit any MagmaOre we're carrying (runs the whole time we're in the dungeon).
local function startAutoDeposit()
	if autoDepositThread then
		return
	end
	autoDepositThread = task.spawn(function()
		while running do
			if isSaramed() and character() and character():FindFirstChild("MagmaOre") then
				pcall(function()
					local hit = workspace.Deepdrill.DungeonDrill.FuelPort.Hit
					firetouchinterest(character().MagmaOre, hit, 0)
					firetouchinterest(character().MagmaOre, hit, 1)
				end)
			end
			task.wait(0.2)
		end
	end)
	maid:mark(autoDepositThread)
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "path", from = "_check_area", to = "_path" },
		{ name = "status", from = "_path", to = "_status" },
		{ name = "dungeonStart", from = "_status", to = "_start_dungeon" },
		{ name = "dungeonComplete", from = "_start_dungeon", to = "_complete_dungeon" },
		{ name = "dungeonContinuation", from = "_complete_dungeon", to = "_start_dungeon" },
		{ name = "dungeonReset", from = "_complete_dungeon", to = "_reset_dungeon" },
		{ name = "fullReset", from = "_reset_dungeon", to = "_check_area" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")
			setupDisconnectHandler()
			startAutoDeposit()

			-- Somehow ended up in the Depths -> stop (PR kicks here).
			if game.PlaceId == DEPTHS_PLACE_ID then
				Logger.notify("Auto Saramed: ended up in the Depths -- stopping.")
				return AutoSaramed.stop()
			end

			-- Etrean overworld -> route to Eastern.
			if game.PlaceId == MAIN_GAME_PLACE_ID then
				Teleports.eastern()
				return
			end

			self:path()
		end,
		onenter_path = function(self)
			if not running then
				return
			end
			pathToSaramed()
			self:status()
		end,
		onenter_status = function(self)
			if not running then
				return
			end
			checkPlayerStatus()
			self:dungeonStart()
		end,
		onenter_start_dungeon = function(self)
			if not running then
				return
			end
			startDungeon()
			self:dungeonComplete()
		end,
		onenter_complete_dungeon = function(self)
			if not running then
				return
			end
			completeDungeon()

			-- Keep diving unless we're low or hit the bottom (2.00 depth).
			local atBottom = false
			pcall(function()
				atBottom = workspace.Deepdrill.DungeonDrill.DepthDisplay.SurfaceGui.TextLabel.Text:find("2.00") ~= nil
			end)
			if not healthCheck(MIN_HEALTH) and not atBottom then
				task.defer(function()
					self:dungeonContinuation()
				end)
			else
				task.defer(function()
					self:dungeonReset()
				end)
			end
		end,
		onenter_reset_dungeon = function(self)
			if not running then
				return
			end
			resetDungeon()
			self:fullReset()
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_saramed",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"fly",
			"no_fire",
			"no_stun",
			"fast_swing",
			"m1_hold",
			"auto_equip_weapon",
			"auto_log",
		},
	})
end

-- Force Auto Defense (the parry/block engine) on for the run, remembering its previous state so stopping
-- the farm puts it back to whatever it was. Auto Saramed fights the dungeon mobs, so it wants defense up.
local function applyAutoDefense()
	if not Toggles or not Toggles.EnableAutoDefense then
		return
	end
	previousAutoDefense = Toggles.EnableAutoDefense.Value
	Toggles.EnableAutoDefense:SetValue(true)
end

local function restoreAutoDefense()
	if previousAutoDefense ~= nil and Toggles and Toggles.EnableAutoDefense then
		Toggles.EnableAutoDefense:SetValue(previousAutoDefense)
	end
	previousAutoDefense = nil
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoSaramed.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	if not AutoSaramed.inValidPlace() then
		return Logger.notify("Auto Saramed: not in the Eastern Luminant or the Saramed dungeon.")
	end
	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Saramed: no data slot found.")
	end

	local data = PersistentData.get("sarameddata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("sarameddata", data)

	running = true
	applyAutoDefense()
	buildOverlay()
	AntiAFK.start("AutoSaramed")

	maid:mark(task.spawn(runElapsed))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoSaramed.stop()
	if not running then
		return
	end
	running = false
	restoreAutoDefense()
	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end
	Tweening.stop(MOVE_ID)
	pcall(function()
		AntiAFK.stop("AutoSaramed")
	end)
	maid:clean()
	autoDepositThread = nil
	disconnectHandlerSet = false
	destroyOverlay()
	PersistentData.set("sarameddata", nil)
end

return AutoSaramed

end)
__bundle_register("@luma/Features/Automation/AutoTitus", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AutoTitus (RELICS farm): a luma port of project-rain-oss's `titus_relicfarm.lua`, built on the ported
-- AutomationStruct + StateMachine framework. Constructs a struct with PR's relic feature set and drives the
-- same state machine: create character -> (bank relics / refill food) -> enter the Titus dungeon -> break
-- Titus (mob_ai_breaker) -> loot the relic chest -> respawn out -> repeat. Relics held in stacks of >= 25
-- get deposited at the Banker.
--
-- NOTE: faithful to PR, the relic farm does NOT run the `jesus` anti-water feature (only the echo farm does
-- in PR). It also keeps its character between cycles (no wipe) so relics accumulate for banking.
--
-- Public surface kept identical for luma's menu + resume wiring:
--   AutoTitus.start()        -- menu Start + Luma.lua resume
--   AutoTitus.stop()         -- stop + cleanup
--   AutoTitus.inValidPlace() -- resume gate (merit hub or Titus dungeon)
-- Persistence key: "titusdata" { slot, startedAt }.
local AutoTitus = {}

---@module Utility.PersistentData
local PersistentData = require("@luma/Utility/PersistentData")

---@module Features.Automation.Objects.AutoLog
local AutoLog = require("@luma/Features/Automation/Objects/AutoLog")

---@module Game.ServerHop
local ServerHop = require("@luma/Game/ServerHop")

---@module Features.Game.Tweening
local Tweening = require("@luma/Features/Game/Tweening")

---@module Utility.Prompt
local Prompt = require("@luma/Utility/Prompt")

---@module Features.Automation.AutoLoot
local AutoLoot = require("@luma/Features/Automation/AutoLoot")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module GUI.Library
local Library = require("@luma/GUI/Library")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("@luma/Utility/CoreGuiManager")

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Game.AntiAFK
local AntiAFK = require("@luma/Game/AntiAFK")

---@module Game.InputClient
local InputClient = require("@luma/Game/InputClient")

---@module Features.Automation.Objects.StateMachine
local StateMachine = require("@luma/Features/Automation/Objects/StateMachine")

---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("@luma/Features/Automation/Objects/AutomationStruct")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")

local EASTERN_PLACE_ID = 6473861193 -- Fort Merit hub.
local DUNGEON_PLACE_ID = 8668476218 -- The Titus (Detainment) dungeon.

local MOVE_ID = "AutoTitus_Move"
local ENTRANCE = CFrame.new(-6875.86, 336.2, 2827.95)
local ENTRANCE_SPEED = 50
local PLAYER_SAFE_RADIUS = 200
local APPROACH_Y = 288
local ATTACH_DISTANCE = 35
local BANK_THRESHOLD = 25
local BANK_COOLDOWN = 45

local running = false
local struct = nil
local maid = Maid.new()
local lastBank = 0
local actionStartedAt = 0 -- os.clock() when the current stage began (0 = disarmed); per-action watchdog.
local ACTION_TIMEOUT = 60 -- a stage stalling longer than this REJOINS (server-hops) to reset the cycle.
local VOID_TIMEOUT = 45 -- shorter cap for the Titus voiding phase ("fighting titus") specifically.
local currentActionTimeout = ACTION_TIMEOUT -- active timeout for the current stage (set per-stage in setStage).

local screenGui, elapsedLabel = nil, nil

-- =========================================================================================================
-- Local-player accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end

local function character()
	local lp = localPlayer()
	return lp and lp.Character
end

local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end

local function humanoid()
	local c = character()
	return c and c:FindFirstChildOfClass("Humanoid")
end

local function backpack()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("Backpack")
end

local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end

local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end

local function currentArea()
	local lp = localPlayer()
	return lp and lp:GetAttribute("CurrentArea")
end

local function isRunning()
	return running
end

function AutoTitus.inValidPlace()
	return game.PlaceId == EASTERN_PLACE_ID or game.PlaceId == DUNGEON_PLACE_ID
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end

local function mk(class, props, parent)
	local instance = Instance.new(class)
	for key, value in pairs(props) do
		instance[key] = value
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end

local function buildOverlay()
	if screenGui then
		return
	end

	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "LumaAutoTitusOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999

	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 78),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })

	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = "Auto Titus (Relics)",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })

	elapsedLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 16),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Elapsed: 0s",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(elapsedLabel, { TextColor3 = "FontColor" })

	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		AutoTitus.stop()
	end)

	pcall(function()
		Library:MakeDraggable(outer)
	end)
end

local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	elapsedLabel = nil
end

-- Stage text was removed, but setStage now re-arms the per-action watchdog on every stage change (the void
-- phase, "fighting titus", gets the shorter VOID_TIMEOUT cap). Same mechanism as the echo farm.
local function setStage(name)
	actionStartedAt = os.clock()
	currentActionTimeout = (name == "fighting titus") and VOID_TIMEOUT or ACTION_TIMEOUT
end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

local function runElapsed()
	while running do
		local data = PersistentData.get("titusdata")
		if elapsedLabel and data then
			elapsedLabel.Text = "Elapsed: " .. formatDuration(math.max(0, os.time() - (data.startedAt or os.time())))
		end
		task.wait(0.5)
	end
end

-- =========================================================================================================
-- Movement primitives (ported from PR's autotitus table).
-- =========================================================================================================
local function setSpeed(value, force)
	-- Normally the per-automation Tween Speed slider wins; `force` lets a specific move (the dungeon-door
	-- travel) pin an exact speed regardless of the slider.
	if not force then
		value = (Options and Options.TitusTweenSpeed and Options.TitusTweenSpeed.Value) or 100
	end
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end

---When `force` is set (the dungeon-door travel), step the root toward the goal at an EXACT studs/second
---ourselves instead of going through the shared Tween Speed slider. That slider is clamped (Min) and shared
---across every automation, so it can't reliably pin a speed at runtime -- this keeps the door approach at
---the speed we actually ask for (e.g. 50 studs/s) no matter what the slider says.
local function tempTween(cframe, speed, force)
	if force then
		Tweening.stop(MOVE_ID) -- make sure the engine isn't also driving us toward a stale goal
		local targetPos = cframe.Position
		local studsPerSecond = speed or 150
		local dt = task.wait()
		while running do
			local r = root()
			if not r then
				return
			end
			r.AssemblyLinearVelocity = Vector3.zero
			local pos = r.Position
			local toTarget = targetPos - pos
			local dist = toTarget.Magnitude
			if dist <= 1 then
				break
			end
			local stepDist = studsPerSecond * dt
			if stepDist >= dist then
				r.CFrame = CFrame.new(targetPos)
				break
			end
			r.CFrame = CFrame.new(pos + (toTarget / dist) * stepDist)
			dt = task.wait()
		end
		return
	end

	setSpeed(speed or 150, force)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 10 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end

local function playerCheck(mag, position)
	local origin = position or (root() and root().Position)
	if not origin then
		return false
	end
	for _, other in next, players:GetPlayers() do
		if other == localPlayer() or not other.Character then
			continue
		end
		local hrp = other.Character:FindFirstChild("HumanoidRootPart")
		if hrp and (origin - hrp.Position).Magnitude <= mag then
			return true
		end
	end
	return false
end

local function serverHop()
	-- currentSlot() reads the live DataSlot attribute, which is often absent inside the Titus dungeon;
	-- fall back to the farm's persisted slot so the rejoin resolves a real save slot instead of no-opping
	-- on nil.
	local data = PersistentData.get("titusdata")
	local slot = currentSlot() or (data and data.slot)
	pcall(function()
		ServerHop.hop(slot, true)
	end)
end

---Per-action watchdog (same mechanism as the echo farm): if a stage stalls past its cap -- the Titus void
---("fighting titus") gets VOID_TIMEOUT, everything else ACTION_TIMEOUT -- server-hop to rejoin a fresh server
---and re-enter (titusdata resume brings the farm back). Unlike the echo farm this REJOINS rather than wiping:
---a relic-farm character must survive, so it never obliterates.
local function runActionWatchdog()
	while running do
		if actionStartedAt > 0 and os.clock() - actionStartedAt > currentActionTimeout then
			actionStartedAt = 0 -- disarm so we only fire once
			serverHop()
			return
		end
		task.wait(0.25)
	end
end

---Player-safe tween: hop if anyone is near, else fly there at altitude and snap down (PR relic version).
---@param groundLevel boolean? when true, travel at ground level (no altitude lift) instead of high up.
local function playerSafeTween(cf, speed, groundLevel, force)
	if playerCheck(PLAYER_SAFE_RADIUS) then
		serverHop()
		while task.wait() do
		end
		return
	end
	local r = root()
	if not r then
		return
	end
	if groundLevel then
		-- Match the dungeon door's Y: snap to the target's height, then tween horizontally across to it at
		-- that same Y level (no altitude lift).
		r.CFrame = CFrame.new(r.Position.X, cf.Position.Y, r.Position.Z)
		tempTween(cf, speed, force)
	else
		local y = math.random(8000, 10000)
		r.CFrame = r.CFrame + Vector3.new(0, y, 0)
		tempTween(cf + Vector3.new(0, y, 0), speed, force)
	end
	if playerCheck(PLAYER_SAFE_RADIUS, cf.Position) then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
end

-- =========================================================================================================
-- Relic helpers.
-- =========================================================================================================
local function countItem(name)
	local bp = backpack()
	if not bp then
		return 0
	end
	local qty = 0
	for _, item in next, bp:GetChildren() do
		if item.Name == name then
			qty = qty + 1
		end
	end
	return qty
end

local function bankItems()
	-- luma menu dropdown "TitusBankItems" -> a set { [name] = true }.
	if Options and Options.TitusBankItems then
		return Options.TitusBankItems.Value or {}
	end
	return {}
end

local function needFood()
	local c = character()
	if not c then
		return false
	end
	local water = c:FindFirstChild("Water")
	local stomach = c:FindFirstChild("Stomach")
	if not water or not stomach then
		return false
	end
	return (water.Value <= (water.MaxValue * 0.3)) and (stomach.Value <= (stomach.MaxValue * 0.3))
end

local function refillFood()
	setStage("refill food")
	local c = character()
	local water = c and c:FindFirstChild("Water")
	if not water then
		return
	end

	local function nearestWell()
		local closest
		local terrain = workspace:FindFirstChild("Terrain")
		local waterFolder = terrain and terrain:FindFirstChild("Water")
		if not waterFolder then
			return nil
		end
		for _, well in next, waterFolder:GetChildren() do
			if well.Name:match("DrinkingWater") then
				if not closest then
					closest = well
				else
					local cd = (root().Position - closest:GetPivot().Position).Magnitude
					local d = (root().Position - well:GetPivot().Position).Magnitude
					if d < cd then
						closest = well
					end
				end
			end
		end
		return closest
	end

	if not (water.Value >= (water.MaxValue * 0.75)) then
		local well = nearestWell()
		if not well then
			return
		end
		playerSafeTween(well:GetPivot(), 250)
		repeat
			well = nearestWell()
			task.wait()
		until well or not running
		repeat
			pcall(function()
				Prompt.interact(well.InteractPrompt)
			end)
			task.wait(0.2)
		until (water.Value >= (water.MaxValue * 0.75)) or not running
	end
end

-- =========================================================================================================
-- Dungeon flow.
-- =========================================================================================================
local function enterDungeon()
	setStage("enter dungeon")
	-- Force noclip on for the trip to the dungeon door so geometry can't snag us on the way in.
	pcall(function()
		if Toggles and Toggles.NoClip then
			Toggles.NoClip:SetValue(true)
		end
	end)
	pcall(function()
		replicatedStorage.Requests.UpdateUXSettings:FireServer("FriendlyFire", true)
	end)

	-- Keep noclip enforced for the WHOLE trip to the door (not just once we're there): re-assert the NoClip
	-- toggle and brute-force every character part CanCollide=false each frame while we travel, so geometry
	-- can't snag us on the way in.
	local travelNoclip = runService.Heartbeat:Connect(function()
		if Toggles and Toggles.NoClip and not Toggles.NoClip.Value then
			Toggles.NoClip:SetValue(true)
		end
		local c = character()
		if c then
			for _, part in next, c:GetDescendants() do
				if part:IsA("BasePart") and part.CanCollide then
					part.CanCollide = false
				end
			end
		end
	end)

	playerSafeTween(ENTRANCE, ENTRANCE_SPEED, true, true) -- ground level (y=0) to the door; force 50 studs/s regardless of the Tween Speed slider
	pcall(function()
		travelNoclip:Disconnect()
	end)
	pcall(function()
		replicatedStorage.Requests.UpdateUXSettings:FireServer("FriendlyFire", true)
	end)

	local entry = workspace:WaitForChild("Map", 10)
	entry = entry and entry:WaitForChild("MeritEntry", 10)

	local holdConn = runService.Heartbeat:Connect(function()
		local r = root()
		if r then
			r.CFrame = ENTRANCE
		end
		-- Brute-force noclip for the door approach: force every character part CanCollide=false each frame so
		-- geometry can't snag us (doesn't rely on the NoClip toggle / Movement loop).
		local c = character()
		if c then
			for _, part in next, c:GetDescendants() do
				if part:IsA("BasePart") and part.CanCollide then
					part.CanCollide = false
				end
			end
		end
	end)

	local start = tick()
	repeat
		-- Keep noclip ON for the whole door approach (re-assert each pass -- a one-shot set can get cleared by
		-- the fresh-character spawn / feature management, same reason the no-fall loop re-asserts).
		if Toggles and Toggles.NoClip and not Toggles.NoClip.Value then
			Toggles.NoClip:SetValue(true)
		end
		if playerCheck(PLAYER_SAFE_RADIUS, ENTRANCE.Position) then
			if holdConn then
				holdConn:Disconnect()
			end
			serverHop()
			while task.wait() do
			end
			return
		end
		if entry and entry:FindFirstChild("InteractPrompt") then
			Prompt.interact(entry.InteractPrompt)
		end
		task.wait(0.1)
	until tick() - start > 30 or game.PlaceId ~= EASTERN_PLACE_ID or not running

	if holdConn then
		holdConn:Disconnect()
	end
end

-- Old pathfind (mob_ai) breaker, baked straight into the Titus fight (no toggle). Every Heartbeat we
-- snapshot the root's real velocity, then slam it straight down (0, -9e11, 0); we restore the snapshot
-- BEFORE the next physics step so we never actually fall -- the slam lives for one tick, just long enough
-- to replicate the fling. The restore runs on PreRender AND PreSimulation: PreRender covers the focused
-- case, PreSimulation also fires while the window is UNFOCUSED (PreRender doesn't), so an AFK/tabbed-out
-- session can't skip the restore and let the slam rocket us into the void / null zone.
local titusBreakerHB = nil
local titusBreakerPR = nil
local titusBreakerPS = nil
local titusBreakerLastVel = nil

local function stopTitusBreaker()
	if titusBreakerHB then
		pcall(function()
			titusBreakerHB:Disconnect()
		end)
		titusBreakerHB = nil
	end
	if titusBreakerPR then
		pcall(function()
			titusBreakerPR:Disconnect()
		end)
		titusBreakerPR = nil
	end
	if titusBreakerPS then
		pcall(function()
			titusBreakerPS:Disconnect()
		end)
		titusBreakerPS = nil
	end
	if titusBreakerLastVel then
		local r = root()
		if r then
			pcall(function()
				r.AssemblyLinearVelocity = titusBreakerLastVel
			end)
		end
		titusBreakerLastVel = nil
	end
end

local function startTitusBreaker()
	stopTitusBreaker()

	-- Restore the pre-slam velocity. Runs on every pre-physics tick so the slam is always undone before
	-- physics integrates it (otherwise -9e11 would carry us straight into the void).
	local function restoreBreakerVelocity()
		if not titusBreakerLastVel then
			return
		end
		local r = root()
		if r then
			r.AssemblyLinearVelocity = titusBreakerLastVel
		end
		titusBreakerLastVel = nil
	end

	titusBreakerHB = runService.Heartbeat:Connect(function()
		local r = root()
		if not r then
			return
		end
		titusBreakerLastVel = r.AssemblyLinearVelocity
		r.AssemblyLinearVelocity = Vector3.new(0, -9e11, 0)
	end)

	-- PreRender restores while the window is focused; PreSimulation (falling back to Stepped) also fires
	-- when it's unfocused, so the restore can never be skipped and let the slam fling us to the null zone.
	titusBreakerPR = runService.PreRender:Connect(restoreBreakerVelocity)
	local preSim = runService.PreSimulation or runService.Stepped
	if preSim then
		titusBreakerPS = preSim:Connect(restoreBreakerVelocity)
	end
end

local function attachToTitus()
	setStage("fighting titus")

	local titus
	repeat
		for _, ent in next, workspace.Live:GetChildren() do
			if ent.Name:lower():find("titus") and ent.Name:find("%.") then
				titus = ent
				break
			end
		end
		task.wait()
	until titus or not running
	if not titus then
		return
	end

	local torso = titus:WaitForChild("Torso")
	if not torso then
		return
	end

	local playerRoot = root()
	if not playerRoot then
		return
	end

	maid:mark(task.spawn(function()
		while titus and titus.Parent and running do
			pcall(function()
				InputClient.dodge({ direct = true })
			end)
			task.wait(0.35)
		end
	end))

	local targetCF = CFrame.new(torso.CFrame.X, APPROACH_Y, torso.CFrame.Z)
	playerRoot.AssemblyLinearVelocity = Vector3.zero
	tempTween(targetCF, 250)
	task.wait(0.5)
	tempTween(targetCF, 250)

	-- Kill by ramming up and down THROUGH Titus's torso: oscillate between his torso and a point VOID_SWING
	-- studs above it (position-only target -- a straight vertical lookAt is degenerate and NaNs the CFrame).
	-- The pathfind breaker does the damage; this just drives the motion. Done when he dies, or hop if he
	-- somehow gets flung up off the map.
	startTitusBreaker()
	-- Ram hard and FAST through Titus's torso at a fixed, slider-independent speed (the shared Tween Speed
	-- slider can't be trusted to hold a value at runtime, and the old setSpeed(200) was non-force so it
	-- silently ran at the ~100 slider default). Step the root straight between his torso and VOID_SWING studs
	-- above it, flipping the instant we reach an end, slamming the whole time via the breaker.
	local VOID_SWING = 100
	local RAM_SPEED = 900
	-- If Titus gets flung farther than this from us, stop chasing him. He's on his way out (flung/voiding),
	-- and gliding across the map after his torso is exactly the bug we're fixing. Hold position instead and
	-- keep swinging; he dies or comes back, and the per-action watchdog server-hops if the fight truly stalls.
	local MAX_RAM_DISTANCE = 10000
	local voidGoingIn = true
	local dt = task.wait()
	while running do
		if not titus or not titus.Parent or not torso.Parent then
			break
		end
		if torso.Position.Y > 2000 then
			stopTitusBreaker()
			serverHop()
			return
		end

		playerRoot = root()
		if playerRoot then
			playerRoot.AssemblyLinearVelocity = Vector3.zero

			local ramPos = torso.Position + Vector3.new(0, voidGoingIn and VOID_SWING or 0, 0)
			local toTarget = ramPos - playerRoot.Position
			local dist = toTarget.Magnitude
			-- Only ram/move while he's close. Flung too far -> don't chase; lift up to Y=1000 and wait him out.
			if dist <= MAX_RAM_DISTANCE then
				local stepDist = RAM_SPEED * dt
				if dist <= stepDist or dist < 3 then
					playerRoot.CFrame = CFrame.new(ramPos)
					voidGoingIn = not voidGoingIn
				else
					playerRoot.CFrame = CFrame.new(playerRoot.Position + (toTarget / dist) * stepDist)
				end
			else
				-- Titus flung past MAX_RAM_DISTANCE: sit at Y=1000 (keep our X/Z) instead of gliding after him.
				local pos = playerRoot.Position
				playerRoot.CFrame = CFrame.new(pos.X, 1000, pos.Z)
			end
			pcall(function()
				character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
			end)
		end

		dt = task.wait()
	end
	stopTitusBreaker()
	Tweening.stop(MOVE_ID)
end

---Loot the relic chest (relic: open + force LOOT_ALL, then EXIT).
local function grabChest()
	setStage("looting chest")

	-- Find the chest (wait for it to spawn after the kill).
	local chest
	local findStart = tick()
	repeat
		local thrown = workspace:FindFirstChild("Thrown")
		if thrown then
			for _, object in next, thrown:GetChildren() do
				if object:FindFirstChild("Lid") then
					chest = object
					break
				end
			end
		end
		if not chest then
			task.wait()
		end
	until chest or not running or (tick() - findStart > 15)
	if not chest then
		return
	end

	local previousAutoLootIgnore = AutoLoot.ignore
	AutoLoot.ignore = true
	local ok, err = xpcall(function()
		-- Chest appeared: snap straight onto it and hold there. After the post-kill teleport we're ~1300 studs
		-- up, so don't rely on a slow descend tween -- lock onto the chest position immediately, then the
		-- re-tween loop below keeps us glued to it while we open + loot.
		do
			local rr = root()
			if rr then
				rr.AssemblyLinearVelocity = Vector3.zero
				rr.CFrame = CFrame.new(chest.Lid.CFrame.Position)
			end
		end

		-- The farm sends LOOT_ALL itself; keep generic AutoLoot from closing this prompt with EXIT.
		tempTween(chest.Lid.CFrame, 170)
		local promptStart = tick()
		repeat
			task.wait(0.1)
			pcall(function()
				Prompt.interact(chest:FindFirstChildWhichIsA("ProximityPrompt"))
			end)
			pcall(function()
				tempTween(chest.Lid.CFrame, 170)
			end)
		until (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or (tick() - promptStart > 15)

		if not (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) then
			return
		end

		-- Force Loot All while the ChoicePrompt is up, then EXIT to close.
		local time = tick()
		repeat
			task.wait()
			local gui = playerGui()
			local cp = gui and gui:FindFirstChild("ChoicePrompt")
			if cp then
				pcall(function()
					cp:FindFirstChild("Choice"):FireServer("LOOT_ALL")
				end)
			end
		until not (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or (tick() - time >= 3)

		local gui = playerGui()
		local cp = gui and gui:FindFirstChild("ChoicePrompt")
		if cp then
			pcall(function()
				cp:FindFirstChild("Choice"):FireServer("EXIT")
			end)
		end
		-- Intentionally NOT tweening back down to Y=0 -- stay at altitude after looting.
	end, debug.traceback)
	AutoLoot.ignore = previousAutoLootIgnore
	if not ok then
		error(err, 0)
	end
end

---Deposit relic stacks (>= BANK_THRESHOLD) at the Banker.
local function bankRelics()
	setStage("banking relics")

	local npcs = workspace:FindFirstChild("NPCs")
	local banker = npcs and npcs:WaitForChild("Banker", 10)
	if not banker then
		return
	end

	pcall(function()
		playerSafeTween(banker.HumanoidRootPart.CFrame * CFrame.new(0, -6, 0), 150)
	end)
	pcall(function()
		local r = root()
		if r then
			r.CFrame = banker.HumanoidRootPart.CFrame * CFrame.new(0, -6, 0)
		end
	end)

	local sendDialogue = replicatedStorage.Requests.SendDialogue
	local dl = tick()
	repeat
		local dg = playerGui() and playerGui():FindFirstChild("DialogueGui")
		if dg and dg.Enabled then
			pcall(function()
				sendDialogue:FireServer({ choice = "Can I access my account?" })
			end)
		else
			pcall(function()
				Prompt.interact(banker.InteractPrompt)
			end)
		end
		task.wait(0.5)
	until (playerGui() and playerGui():FindFirstChild("BankGui")) or tick() - dl > 15 or not running

	local bankGui = playerGui() and playerGui():FindFirstChild("BankGui")
	if not bankGui then
		return
	end

	local function bankFull()
		local cp = playerGui() and playerGui():FindFirstChild("ChoicePrompt")
		if not cp then
			return false
		end
		local ds = cp:FindFirstChild("DescSheet", true)
		if not ds or not ds:FindFirstChild("Ok") then
			return false
		end
		local dc = ds:FindFirstChild("Desc", true)
		return dc ~= nil and dc.Text == "You don't have any bank slots free."
	end

	local function confirmMax()
		local cp = playerGui() and playerGui():FindFirstChild("ChoicePrompt")
		if not cp then
			return false
		end
		local mx = cp:GetAttribute("Max")
		local ch = cp:FindFirstChild("Choice")
		if mx and ch then
			task.spawn(function()
				pcall(function()
					ch:InvokeServer(mx)
				end)
			end)
			return true
		end
		return false
	end

	for name, selected in pairs(bankItems()) do
		if selected and countItem(name) >= BANK_THRESHOLD then
			local n = 0
			while countItem(name) > 0 and n < 6 and running do
				n = n + 1
				local before = countItem(name)
				local deposit = {}
				for _, item in next, backpack():GetChildren() do
					if item.Name == name then
						deposit[#deposit + 1] = item
					end
				end
				if #deposit == 0 then
					break
				end
				pcall(function()
					bankGui:WaitForChild("Choice"):FireServer("deposit", deposit)
				end)
				local bt = tick()
				repeat
					if bankFull() then
						Logger.notify("Bank full -- Auto Titus stopped.")
						AutoTitus.stop()
						return
					end
					confirmMax()
					task.wait(0.3)
				until countItem(name) < before or tick() - bt > 8 or not running
			end
		end
	end
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local function isCharacterCreation()
	local cc = workspace:FindFirstChild("CharacterCreator")
	local c = character()
	return cc ~= nil and c ~= nil and c.Parent == cc
end

---Tap a key once via VirtualInputManager (input-only; no remote).
local function pressKey(keyCode)
	pcall(function()
		local vim = Instance.new("VirtualInputManager")
		vim:SendKeyEvent(true, keyCode, false, game)
		vim:SendKeyEvent(false, keyCode, false, game)
	end)
end

---Blow through the loading screen and wait for our character to spawn into workspace.Live. While the
---LoadingGui is up, spams A to click through it (input-only -- the old Requests.StartMenu.Start remote
---is an anticheat honeypot, firing it = instant ban). Skipped in character creation.
local function requestStart()
	local deadline = os.clock() + 25
	repeat
		if isCharacterCreation() then
			return
		end
		local c = character()
		if c and c.Parent and c.Parent.Name == "Live" then
			return
		end
		local pg = players.LocalPlayer and players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
		if pg and pg:FindFirstChild("LoadingGui") then
			pressKey(Enum.KeyCode.A)
		end
		task.wait(0.2)
	until not running or os.clock() >= deadline
end

-- Kept the name (callers unchanged); tears down the inline pathfind breaker (the Titus kill mechanism).
local function disableBreaker()
	stopTitusBreaker()
end

-- Ferryman-style auto log: throughout the entire farm, hop the moment another player comes within the
-- per-automation auto-log distance (adjustable 0-2000 in the menu; 0 = off). Saved per automation.
local function watchForPlayers()
	while running do
		task.wait(1)
		if not running then
			break
		end
		-- Don't hop mid-creation (lobby players would softlock the character creator).
		if isCharacterCreation() then
			continue
		end
		local dist = AutoLog.get("auto_titus")
		if dist > 0 and playerCheck(dist) then
			serverHop()
			return
		end
	end
end

local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "continuation", from = "_create_character", to = "_check_area" },
		{ name = "continuation", from = "_bank_relics", to = "_check_area" },
		{ name = "bank", from = "_check_area", to = "_bank_relics" },
		{ name = "cc", from = "_check_area", to = "_create_character" },
		{ name = "enter", from = "_check_area", to = "_enter_dungeon" },
		{ name = "run", from = "_check_area", to = "_run_dungeon" },
		{ name = "exit", from = "_run_dungeon", to = "_exit" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")

			-- Merit / dungeon: existing character here, so it's safe to blow through the loading screen.
			if game.PlaceId == EASTERN_PLACE_ID then
				requestStart()
				-- Bank first if we're holding a full stack of any selected relic (cooldown-gated).
				for name, selected in pairs(bankItems()) do
					if selected and countItem(name) >= BANK_THRESHOLD and tick() - lastBank > BANK_COOLDOWN then
						lastBank = tick()
						return self:bank()
					end
				end
				-- No wipe: turn the breaker off in the hub, refill food if low, then enter.
				disableBreaker()
				if needFood() then
					refillFood()
				end
				return self:enter()
			end

			if game.PlaceId == DUNGEON_PLACE_ID then
				requestStart()
				return self:run()
			end

			-- Anywhere else (lobby / character creator): DO NOT fire StartMenu.Start -- that would rush the
			-- character creator and roll the wrong character. Wait patiently for the creator to come up.
			local deadline = os.clock() + 20
			repeat
				if isCharacterCreation() then
					return self:cc()
				end
				task.wait()
			until os.clock() >= deadline or not running
		end,

		onenter_create_character = function(self)
			if not running then
				return
			end
			setStage("create character")
			struct:create_character()
			self:continuation()
		end,

		onenter_enter_dungeon = function(self)
			if not running then
				return
			end
			enterDungeon()
		end,

		onenter_run_dungeon = function(self)
			if not running then
				return
			end
			setStage("run dungeon")

			local startTime = tick()
			repeat
				task.wait(0.2)
			until (currentArea() and tostring(currentArea()):match("Detainment")) or not running

			task.wait(1)
			attachToTitus()

			-- Re-arm the watchdog off the shorter void cap now the fight's over, so the exit-wait + loot get a
			-- fresh ACTION_TIMEOUT instead of inheriting "fighting titus"'s 45s.
			setStage("boss defeated")

			-- Titus is down: reset the 30s DungeonExitFinal cap to measure from the KILL, not the dungeon-run
			-- start, so a slow fight can't eat the window the run gets to wait for the exit to spawn.
			startTime = tick()

			local hum = humanoid()
			if hum then
				hum.Died:Connect(function()
					serverHop()
				end)
			end

			local finished = false
			local core = workspace:WaitForChild("DetainmentCore", 10)
			local conn
			if core then
				conn = core.ChildAdded:Connect(function(child)
					if child.Name == "DungeonExitFinal" then
						finished = true
					end
				end)
			end

			repeat
				task.wait(0.2)
				if tick() - startTime > 30 then
					if conn then
						conn:Disconnect()
					end
					serverHop()
					while task.wait() do
					end
					return
				end
			until finished or not running

			if conn then
				conn:Disconnect()
			end

			task.wait(0.5)

			disableBreaker()

			local r = root()
			if r then
				r.CFrame = r.CFrame * CFrame.new(0, 1300, 0)
			end

			xpcall(function()
				grabChest()
			end, function(err)
				Logger.notify("AutoTitus loot error: %s", tostring(err))
			end)

			task.wait(2)

			r = root()
			if r then
				r.CFrame = r.CFrame * CFrame.new(0, 1300, 0)
			end

			local hum2 = humanoid()
			if hum2 and hum2:GetAttribute("DangerExpiration") and hum2:GetAttribute("DangerExpiration") > 0 then
				repeat
					task.wait()
				until not (hum2:GetAttribute("DangerExpiration") and hum2:GetAttribute("DangerExpiration") > 0)
					or not running
			end

			self:exit()
		end,

		onenter_bank_relics = function(self)
			if not running then
				return
			end
			bankRelics()
			self:continuation()
		end,

		onenter_exit = function(self)
			if not running then
				return
			end
			setStage("respawn")
			-- Fast way out: replicate the Kill signal, then void ourselves if we somehow survived.
			if replicatesignal then
				pcall(function()
					replicatesignal(localPlayer().Kill)
				end)
				task.delay(1, function()
					local hum = humanoid()
					if hum and hum.Health <= 1 then
						return
					end
					local r = root()
					if r then
						r.CFrame = r.CFrame * CFrame.new(0, 9e9, 0)
					end
				end)
			else
				local r = root()
				if r then
					r.CFrame = r.CFrame * CFrame.new(0, 9e9, 0)
				end
			end
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "auto_titus",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"fly",
			"auto_loot",
			"auto_equip_weapon",
		},
		character_creator_handler_used = true,
		character_creator_handler_opts = {
			origin = "Merit",
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function AutoTitus.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end
	if not AutoTitus.inValidPlace() then
		return Logger.notify("Auto Titus: Not in Eastern Luminant")
	end

	local slot = currentSlot()
	if not slot then
		return Logger.notify("Auto Titus: no data slot found.")
	end

	local data = PersistentData.get("titusdata") or {}
	data.slot = slot
	data.startedAt = data.startedAt or os.time()
	PersistentData.set("titusdata", data)

	running = true
	buildOverlay()
	AntiAFK.start("AutoTitus")

	maid:mark(task.spawn(runElapsed))

	-- Keep No Fall Damage forced on for the entire farm (respawns / new characters can drop it).
	maid:mark(task.spawn(function()
		while running do
			if Toggles and Toggles.NoFallDamage and not Toggles.NoFallDamage.Value then
				Toggles.NoFallDamage:SetValue(true)
			end
			task.wait(0.25)
		end
	end))

	-- Ferryman-style auto log: hop if any player comes within 1000 studs.
	maid:mark(task.spawn(watchForPlayers))

	-- Per-action watchdog: rejoin if a stage (esp. the Titus void) stalls past its cap.
	maid:mark(task.spawn(runActionWatchdog))

	stateMachine.current = "idle"
	stateMachine.asyncState = StateMachine.NONE
	stateMachine.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function AutoTitus.stop()
	if not running then
		return
	end
	running = false

	stopTitusBreaker()

	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end

	Tweening.stop(MOVE_ID)

	pcall(function()
		AntiAFK.stop("AutoTitus")
	end)

	maid:clean()
	destroyOverlay()

	PersistentData.set("titusdata", nil)
end

return AutoTitus

end)
__bundle_register("@luma/Features/Automation/AutoTo1", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto To1: Trial of One automation. Started with a button (like Auto Ferryman), shows a status
-- overlay, and persists across server hops (resumes on re-execute). Only operates in the Etrean
-- Luminant.
--
-- Step 1: enable No Fall Damage and teleport to the Trial of One (reusing the script's teleport).
-- Further steps are appended to the step machine.
local AutoTo1 = { running = false }

---@module GUI.Library
local Library = require("@luma/GUI/Library")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("@luma/Utility/CoreGuiManager")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module Utility.Configuration
local Configuration = require("@luma/Utility/Configuration")

---@module Utility.PersistentData
local PersistentData = require("@luma/Utility/PersistentData")

---@module Features.Game.Teleport
local Teleport = require("@luma/Features/Game/Teleport")

---@module Features.Game.Tweening
local Tweening = require("@luma/Features/Game/Tweening")

---@module Game.InputClient
local InputClient = require("@luma/Game/InputClient")

---@module Features.Combat.Defense
local Defense = require("@luma/Features/Combat/Defense")

---@module Features.Automation.Objects.General
local General = require("@luma/Features/Automation/Objects/General")

local players = game:GetService("Players")
local runService = game:GetService("RunService")
local replicatedStorage = game:GetService("ReplicatedStorage")

local fastSwingConn = nil

local localPlayer = players.LocalPlayer

-- The Etrean Luminant place (where the Trial of One entrance / teleport is available).
local ETREAN_LUMINANT_PLACE_ID = 6032399813

-- The Trial of One arena (dungeon place). After the teleport in the Etrean Luminant, we land here.
local TRIAL_ARENA_PLACE_ID = 8668476218
local ARENA_TWEEN_ID = "AutoTo1_Arena"
local LIVE_FOLDER = "Live"
-- How far below OneTrigger's Y level to sit while swinging up at the enemy.
local ENEMY_UNDER_OFFSET = 12
-- Swing interval while fighting (matches Auto Ferryman).
local SWING_INTERVAL = 0.3
-- Auto Defense filter turned off for the run (so defense works when the window isn't focused).
local WINDOW_FILTER = "Disable When Window Not Active"
-- Force a very fast tween speed for the run so movement is effectively instant.
local TWEEN_SPEED = 150
-- Tween speed while travelling to OneTrigger.
local ONETRIGGER_TWEEN_SPEED = 50

-- ============================================================================================
-- All Auto To1 text -- edit these to change the on-screen action text and notifications.
-- Entries with %s / %d are format strings (the values are filled in at runtime).
-- ============================================================================================
local TEXT = {
	-- Overlay
	overlayTitle = "Auto To1",
	actionPrefix = "Current Action: ", -- prepended to every action; the empty form is below
	actionPrefixEmpty = "Current Action:",
	elapsed = "Elapsed: %02d:%02d",
	stopButton = "Stop",

	-- Notifications
	notInPlace = "Auto To1: not in the Etrean Luminant or Trial of One.",

	-- Current action text
	teleportingToTrial = "teleporting",
	waitingForOneTrigger = "loading...",
	tweeningToOneTrigger = "tweening",
	waitingForEnemy = "manually invest your points or use auto builder",
	fightingEnemy = "fighting enemy",
	waitingForTrial = "loading...",
	completing = "Trial of One complete, kicking...",

	-- Kick message shown after the trial is finished (alpha killed).
	kickMessage = "Trial of One complete",
}

local screenGui, actionLabel, timerLabel = nil, nil, nil
local timerConnection, stepConnection, characterAddedConnection, weaponConnection = nil, nil, nil, nil

-- Set true once we've reached OneTrigger; from then on we keep the weapon drawn.
local weaponWanted = false

-- Step machine + run state.
local step = 0
local previousNoFall = nil
local previousFly = nil
local previousPathfind = nil
local previousAutoDefense = nil
local previousBlockInput = nil
local previousAutoFeint = nil
local previousVoidMobs = nil
local previousTweenSpeed = nil
local removedWindowFilter = false
local startClock = 0

-- Trial completion: track whether an "alpha" enemy has been present, and when it's gone start a 5s
-- countdown before kicking the player out.
local alphaWasPresent = false
local completeAt = nil

-- ============================================================================================
-- Helpers
-- ============================================================================================

---@return boolean
function AutoTo1.inEtreanLuminant()
	return game.PlaceId == ETREAN_LUMINANT_PLACE_ID
end

---@return boolean
function AutoTo1.inArena()
	return game.PlaceId == TRIAL_ARENA_PLACE_ID
end

---Whether we're somewhere the automation can operate (start / resume).
---@return boolean
function AutoTo1.inValidPlace()
	return AutoTo1.inEtreanLuminant() or AutoTo1.inArena()
end

---@return Instance?
local function guiParent()
	local ok, coreGui = pcall(function()
		return game:GetService("CoreGui")
	end)
	if ok and coreGui then
		return coreGui
	end
	return localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
end

---@param class string
---@param props table
---@param parent Instance?
---@return Instance
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for key, value in pairs(props) do
		instance[key] = value
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end

---@param seconds number
---@return string
local function formatElapsed(seconds)
	local minutes = math.floor(seconds / 60)
	local secs = math.floor(seconds % 60)
	return string.format(TEXT.elapsed, minutes, secs)
end

---@return any
local function currentSlot()
	return localPlayer and localPlayer:GetAttribute("DataSlot")
end

---Persist the resume flag + slot so the automation survives a server hop.
local function saveState()
	PersistentData.set("to1data", { active = true, slot = currentSlot() })
end

---@param text string?
local function setAction(text)
	if not actionLabel then
		return
	end
	actionLabel.Text = (text and text ~= "") and (TEXT.actionPrefix .. text) or TEXT.actionPrefixEmpty
end

---Force a toggle to a value, returning its previous value (or nil if the toggle doesn't exist).
---@param name string
---@param value boolean
---@return boolean?
local function setToggle(name, value)
	if not Toggles or not Toggles[name] then
		return nil
	end
	local previous = Toggles[name].Value
	Toggles[name]:SetValue(value)
	return previous
end

---Force a toggle on, returning its previous value.
---@param name string
---@return boolean?
local function forceToggle(name)
	return setToggle(name, true)
end

---Set the global tween speed (only writes when it actually changes, to avoid callback spam).
---@param value number
local function setTweenSpeed(value)
	value = (Options and Options.To1TweenSpeed and Options.To1TweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end

---The user's normal tween speed captured at start (fallback 200).
---@return number
local function normalTweenSpeed()
	return previousTweenSpeed or 200
end

---Restore a toggle to a remembered value (no-op if nil).
---@param name string
---@param previous boolean?
local function restoreToggle(name, previous)
	if previous ~= nil and Toggles and Toggles[name] then
		Toggles[name]:SetValue(previous)
	end
end

---Turn off the "Disable When Window Not Active" Auto Defense filter for the run (so defense/block
---input still work when the Roblox window isn't focused), remembering whether it was on.
local function applyDefenseFilter()
	local option = Options and Options.AutoDefenseFilters
	if not option then
		return
	end

	local current = option.Value or {}
	removedWindowFilter = current[WINDOW_FILTER] == true
	if not removedWindowFilter then
		return
	end

	local newValue = {}
	for key, value in pairs(current) do
		newValue[key] = value
	end
	newValue[WINDOW_FILTER] = nil
	option:SetValue(newValue)
end

local function restoreDefenseFilter()
	local option = Options and Options.AutoDefenseFilters
	if option and removedWindowFilter then
		local newValue = {}
		for key, value in pairs(option.Value or {}) do
			newValue[key] = value
		end
		newValue[WINDOW_FILTER] = true
		option:SetValue(newValue)
	end
	removedWindowFilter = false
end

---Turn on the run's toggles: No Fall Damage, Fly, Auto Defense + Block Input + Auto Feint + Void Mobs
---(and remove the window filter) -- mirrors Auto Ferryman's combat setup.
local function applyToggles()
	if previousNoFall == nil then
		previousNoFall = forceToggle("NoFallDamage")
	end
	if previousFly == nil then
		previousFly = forceToggle("Fly")
	end
	-- Pathfind Breaker must be OFF for this automation.
	if previousPathfind == nil then
		previousPathfind = setToggle("Fling", false)
	end
	if previousAutoDefense == nil then
		previousAutoDefense = forceToggle("EnableAutoDefense")
	end
	if previousBlockInput == nil then
		previousBlockInput = forceToggle("BlockInput")
	end
	if previousAutoFeint == nil then
		previousAutoFeint = forceToggle("AutoFeint")
	end
	if previousVoidMobs == nil then
		previousVoidMobs = forceToggle("VoidMobs")
	end

	-- Remember the user's tween speed so we can flip to a fast speed only while fighting.
	if previousTweenSpeed == nil and Options and Options.TweenStudsPerSecond then
		previousTweenSpeed = Options.TweenStudsPerSecond.Value
	end

	-- Fast swing: strip attack cooldowns so m1s aren't rate-limited during the fight.
	if not fastSwingConn then
		fastSwingConn = General.connectFastSwing()
	end

	applyDefenseFilter()
end

local function restoreToggles()
	if fastSwingConn then
		pcall(function()
			fastSwingConn:Disconnect()
		end)
		fastSwingConn = nil
	end
	restoreToggle("NoFallDamage", previousNoFall)
	restoreToggle("Fly", previousFly)
	restoreToggle("Fling", previousPathfind)
	restoreToggle("EnableAutoDefense", previousAutoDefense)
	restoreToggle("BlockInput", previousBlockInput)
	restoreToggle("AutoFeint", previousAutoFeint)
	restoreToggle("VoidMobs", previousVoidMobs)
	if previousTweenSpeed ~= nil and Options and Options.TweenStudsPerSecond then
		Options.TweenStudsPerSecond:SetValue(previousTweenSpeed)
	end
	previousTweenSpeed = nil
	previousNoFall = nil
	previousFly = nil
	previousPathfind = nil
	previousAutoDefense = nil
	previousBlockInput = nil
	previousAutoFeint = nil
	previousVoidMobs = nil

	restoreDefenseFilter()
end

---Press a key (used to blow through the loading screen).
---@param keyCode Enum.KeyCode
local function pressKey(keyCode)
	pcall(function()
		local vim = Instance.new("VirtualInputManager")
		vim:SendKeyEvent(true, keyCode, false, game)
		vim:SendKeyEvent(false, keyCode, false, game)
	end)
end

---Whether the character + backpack have replicated in.
---@return boolean
local function requirementsMet()
	local character = localPlayer and localPlayer.Character
	if not character then
		return false
	end
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	return backpack ~= nil and #backpack:GetChildren() > 0
end

---Whether the weapon is currently drawn (the "Equipped" effect is present).
---@return boolean
local function isWeaponDrawn()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local module = effectReplicator and require(effectReplicator)
	if not module then
		return false
	end
	local ok, has = pcall(function()
		return module:HasEffect("Equipped")
	end)
	return ok and has == true
end

---Draw the weapon by firing the game's DrawWeapon remote.
local function drawWeapon()
	local character = localPlayer and localPlayer.Character
	local handler = character and character:FindFirstChild("CharacterHandler")
	local requests = handler and handler:FindFirstChild("Requests")
	local drawEvent = requests and requests:FindFirstChild("DrawWeapon")
	if not drawEvent then
		return
	end
	pcall(function()
		drawEvent:FireServer(true)
	end)
end

---The first live entity in workspace.Live that isn't our own character (an enemy), or nil.
---@return Instance?
local function findEnemyInLive()
	local live = workspace:FindFirstChild(LIVE_FOLDER)
	if not live then
		return nil
	end

	local myCharacter = localPlayer and localPlayer.Character

	for _, entity in next, live:GetChildren() do
		if entity == myCharacter then
			continue
		end

		-- Skip anything with "hostage" in the name so we never target the trial hostages.
		if string.find(string.lower(entity.Name), "hostage", 1, true) then
			continue
		end

		local humanoid = entity:FindFirstChildWhichIsA("Humanoid")
		local root = entity:FindFirstChild("HumanoidRootPart")
		if humanoid and root and humanoid.Health > 0 then
			return entity
		end
	end

	return nil
end

---Whether any live entity in workspace.Live has "alpha" in its name (the trial's final boss).
---@return boolean
local function alphaEnemyPresent()
	local live = workspace:FindFirstChild(LIVE_FOLDER)
	if not live then
		return false
	end

	local myCharacter = localPlayer and localPlayer.Character

	for _, entity in next, live:GetChildren() do
		if entity == myCharacter then
			continue
		end
		if not string.find(string.lower(entity.Name), "alpha", 1, true) then
			continue
		end

		local humanoid = entity:FindFirstChildWhichIsA("Humanoid")
		if humanoid and humanoid.Health > 0 then
			return true
		end
	end

	return false
end

-- ============================================================================================
-- Status overlay
-- ============================================================================================

local function buildOverlay()
	if screenGui then
		return
	end

	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "LumaAutoTo1Overlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999

	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 120),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })

	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = TEXT.overlayTitle,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })

	actionLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 34),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		TextWrapped = true,
		Text = TEXT.actionPrefixEmpty,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(actionLabel, { TextColor3 = "FontColor" })

	timerLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 66),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = formatElapsed(0),
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(timerLabel, { TextColor3 = "FontColor" })

	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = TEXT.stopButton,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})

	stopButton.MouseButton1Click:Connect(function()
		AutoTo1.stop()
	end)

	pcall(function()
		Library:MakeDraggable(outer)
	end)

	screenGui.Enabled = false
end

-- ============================================================================================
-- Step machine
-- ============================================================================================

local function runStep()
	-- ---- Etrean Luminant: teleport to the Trial of One (toggles already applied on start) ----
	if AutoTo1.inEtreanLuminant() then
		if step == 0 then
			setAction(TEXT.teleportingToTrial)
			Teleport.start("TrialOfOne")
			step = 1
		end
		return
	end

	-- ---- Trial arena (8668476218): go to workspace.One.OneTrigger, then fight enemies ----
	if AutoTo1.inArena() then
		local character = localPlayer.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end

		-- Trial completion: once an "alpha" enemy that was present is gone, wait 5s then kick out.
		if alphaEnemyPresent() then
			alphaWasPresent = true
		elseif alphaWasPresent and completeAt == nil then
			completeAt = os.clock() + 5
		end

		if completeAt then
			setAction(TEXT.completing)
			if os.clock() >= completeAt then
				-- Clear the resume flag so it doesn't restart, then kick.
				PersistentData.set("to1data", nil)
				pcall(function()
					localPlayer:Kick(TEXT.kickMessage)
				end)
			end
			return
		end

		-- Resolve workspace.One.OneTrigger's position (part or model).
		local one = workspace:FindFirstChild("One")
		local trigger = one and one:FindFirstChild("OneTrigger")
		if not trigger then
			setAction(TEXT.waitingForOneTrigger)
			return
		end

		local triggerPos = trigger:IsA("BasePart") and trigger.Position or trigger:GetPivot().Position

		if step == 0 then
			-- Slow tween speed + Pathfind Breaker off while travelling to OneTrigger.
			setTweenSpeed(ONETRIGGER_TWEEN_SPEED)
			setToggle("Fling", false)
			setAction(TEXT.tweeningToOneTrigger)
			Tweening.goal(ARENA_TWEEN_ID, CFrame.new(triggerPos), false)

			if (root.Position - triggerPos).Magnitude <= 3 then
				-- Reached OneTrigger: draw the weapon and keep it drawn from here on, then wait for an
				-- enemy (no wait timer).
				weaponWanted = true
				drawWeapon()
				step = 2
			end
			return
		end

		if step == 2 then
			-- Normal tween speed + Pathfind Breaker off while holding + waiting for an enemy.
			setTweenSpeed(normalTweenSpeed())
			setToggle("Fling", false)
			Tweening.goal(ARENA_TWEEN_ID, CFrame.new(triggerPos), false)
			setAction(TEXT.waitingForEnemy)

			if findEnemyInLive() then
				step = 3
			end
			return
		end

		-- Step 3: fight -- fast-tween onto the enemy and m1 until it's gone, then wait for the next.
		local enemy = findEnemyInLive()
		if not enemy then
			-- Enemy dead / despawned: back to normal speed, Pathfind Breaker off, wait for more enemies.
			setTweenSpeed(normalTweenSpeed())
			setToggle("Fling", false)
			step = 2
			return
		end

		local ok, enemyCFrame = pcall(function()
			return enemy:GetPivot()
		end)
		if ok then
			local enemyPos = enemyCFrame.Position
			local targetCFrame

			local lowerName = string.lower(enemy.Name)
			local isEnforcer = string.find(lowerName, "enforcer", 1, true) ~= nil

			-- Fling stays OFF for this automation (never flings, even on enforcers).
			setToggle("Fling", false)

			setAction(TEXT.fightingEnemy)

			if string.find(lowerName, "stoneknight", 1, true) or isEnforcer then
				-- Stoneknight / Enforcer: stay 5 studs behind it and 8 studs above it, facing it.
				local behind = enemyPos - (enemyCFrame.LookVector * 5) + Vector3.new(0, 8, 0)
				targetCFrame = CFrame.lookAt(behind, enemyPos)
			else
				-- Track the enemy horizontally but hold the Y under OneTrigger, facing up at it (small
				-- nudge keeps CFrame.lookAt stable when directly overhead).
				local underPos = Vector3.new(enemyPos.X + 0.1, triggerPos.Y - ENEMY_UNDER_OFFSET, enemyPos.Z)
				targetCFrame = CFrame.lookAt(underPos, enemyPos)
			end

			-- Fast tween speed ONLY while fighting, so positioning onto the enemy is effectively instant.
			setTweenSpeed(TWEEN_SPEED)
			Tweening.goal(ARENA_TWEEN_ID, targetCFrame, false)

			-- Respect Block Input: don't swing while it wants to hold our M1 (block/punish window).
			if not Defense.shouldBlockInput("M1s") then
				local aim = CFrame.new(root.Position, enemyPos)
				pcall(function()
					InputClient.left(aim, true)
				end)
			end
		end
		return
	end

	-- Neither place yet -- wait.
	setAction(TEXT.waitingForTrial)
end

-- ============================================================================================
-- Start / stop
-- ============================================================================================

local function teardown()
	AutoTo1.running = false

	if timerConnection then
		pcall(function()
			timerConnection:Disconnect()
		end)
		timerConnection = nil
	end
	if stepConnection then
		pcall(function()
			stepConnection:Disconnect()
		end)
		stepConnection = nil
	end
	if characterAddedConnection then
		pcall(function()
			characterAddedConnection:Disconnect()
		end)
		characterAddedConnection = nil
	end
	if weaponConnection then
		pcall(function()
			weaponConnection:Disconnect()
		end)
		weaponConnection = nil
	end

	weaponWanted = false

	pcall(function()
		Tweening.stop(ARENA_TWEEN_ID)
	end)
	pcall(Teleport.stop)
	restoreToggles()

	if screenGui then
		screenGui.Enabled = false
	end
end

function AutoTo1.start()
	if AutoTo1.running then
		return
	end

	if not AutoTo1.inValidPlace() then
		return Logger.notify(TEXT.notInPlace)
	end

	-- If the loading screen (LoadingGui) is up (e.g. we just resumed after a place teleport), fire the
	-- StartMenu.Start remote to blow through it until the character + backpack have replicated (10s cap).
	local playerGui = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
	if playerGui and playerGui:FindFirstChild("LoadingGui") then
		local deadline = os.clock() + 10
		while not requirementsMet() and os.clock() < deadline do
			General.fireStartMenu()
			task.wait(0.25)
		end
	end

	step = 0
	weaponWanted = false
	alphaWasPresent = false
	completeAt = nil
	startClock = os.clock()
	AutoTo1.running = true

	-- Resume flag: survives server hops (MemStorage), so it restarts on the next server.
	saveState()

	-- No Fall Damage + Fly + Auto Defense/Block Input/Auto Feint + Void Mobs on for the run.
	applyToggles()

	buildOverlay()
	setAction(nil)
	if timerLabel then
		timerLabel.Text = formatElapsed(0)
	end
	if screenGui then
		screenGui.Enabled = true
	end

	-- Re-run current step if we respawn mid-automation.
	characterAddedConnection = localPlayer.CharacterAdded:Connect(function()
		if not AutoTo1.running then
			return
		end
		task.wait(0.2)
	end)

	-- Elapsed timer.
	timerConnection = runService.Heartbeat:Connect(function()
		if not AutoTo1.running then
			return
		end
		if timerLabel then
			timerLabel.Text = formatElapsed(os.clock() - startClock)
		end
	end)

	-- Keep the weapon drawn: once we've reached OneTrigger, continuously check if it's not drawn and
	-- fire the DrawWeapon remote if so.
	weaponConnection = runService.Heartbeat:Connect(function()
		if not AutoTo1.running or not weaponWanted then
			return
		end
		if not isWeaponDrawn() then
			drawWeapon()
		end
	end)

	-- Step machine (throttled).
	local lastStepAt = 0
	stepConnection = runService.Heartbeat:Connect(function()
		if not AutoTo1.running then
			return
		end
		if os.clock() - lastStepAt < 0.25 then
			return
		end
		lastStepAt = os.clock()
		runStep()
	end)
end

function AutoTo1.stop()
	if not AutoTo1.running and not PersistentData.get("to1data") then
		return
	end

	teardown()

	-- Manual stop: clear the resume flag so a re-execute doesn't restart it.
	PersistentData.set("to1data", nil)
end

function AutoTo1.init()
	if not LPH_OBFUSCATED or (shared.Luma and shared.Luma.verbose) then
		Logger.warn("Auto To1 initialized.")
	end
end

return AutoTo1

end)
__bundle_register("@luma/Features/Automation/AutoVoI", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Auto VoI: automation for the Voice of Insanity area. Started with a button, shows an Auto-Ferryman
-- style status overlay (title / current action / elapsed / timeout / stop) and persists across server
-- hops (resumes on re-execute). Only operates in the VoI place.
--
-- Step 1: if the player is within range of the VoI point, pathfind (walk) to it. Further steps are
-- appended to the routine.
local AutoVoI = { running = false }

---@module GUI.Library
local Library = require("@luma/GUI/Library")

---@module Utility.CoreGuiManager
