	"DialogueGui",
	"DialogueExtents",
	"ShopFrame",
	"Category_Recollection",
	"Items",
	"Power Recall",
	"ContextFrame",
	"Buy",
}

-- After spending notes: go to the Golden Rat boundary and fight the Rat King (same as the shogun).
local GOLDENRAT_BOUNDARY_NAME = "GoldenRatBoundary"
-- Hold here while waiting for the Golden Rat boundary to load.
local GOLDENRAT_WAIT_POS = Vector3.new(-2828.678466796875, 65.59410095214844, -3287.2890625)
-- The Rat King shares the boss arena (ARENA_PLACE_ID); its Live entity name contains this.
local RATKING_ENEMY_MATCH = "ratking"

-- Enmity is an arena-only boss (ARENA_PLACE_ID); its Live entity name contains this. It spawns
-- "enforcer" adds -- any OTHER live enemy in the arena -- which we clear first before the boss.
local ENMITY_ENEMY_MATCH = "enmity"
local ENMITY_BEHIND = 15 -- Studs behind the boss while following.
local ENMITY_ABOVE = 10 -- Studs above the boss while following.
local ENMITY_ENFORCER_BEHIND = 3 -- Studs behind an enforcer while following.
local ENMITY_ENFORCER_ABOVE = 3 -- Studs above an enforcer while following.

-- Boss fight: tween in front of any Live entity whose name contains the match and M1.
local SHOGUN_ENEMY_MATCH = "shogun"
local FIGHT_TWEEN_ID = "AutoVoI_Fight"
local FIGHT_TWEEN_SPEED = 50
-- How far in front of the boss to stand.
local FIGHT_FRONT_OFFSET = 5
-- Rat King ownership-void (same as mira's Titus farm): stand INSIDE it with Pathfind Breaker + Void
-- Mobs forced on to steal network ownership, then the void-mobs pipeline drops it through the map.
-- Rat King fight: stay behind + above it with normal Pathfind Breaker, holding m1.
local RATKING_BEHIND = 7 -- Studs behind the boss.
local RATKING_ABOVE = 3 -- Studs above the boss.
local RATKING_TWEEN_SPEED = 10 -- Normal follow speed (matches the far-crawl speed, so it's always 10).
local RATKING_FAR_DISTANCE = 500 -- Beyond this the boss has blinked away...
local RATKING_FAR_SPEED = 10 -- ...so crawl instead of flinging across the map.
local RATKING_DODGE_ABOVE = 500 -- Snap this far above it while it plays an Action-priority move.
local SHOGUN_DODGE_ABOVE = 500 -- Same, for the shogun.
local VOID_Y_THRESHOLD = -2000 -- Below this Y we count as "in the void".
local VOID_LIFT_STUDS = 10000 -- How high above the safe spot to hold during void self-recovery.
local WEAPON_NAME = "Weapon"

-- Character highlight while running (same as Auto Ferryman).
local HIGHLIGHT_FILL = Color3.fromRGB(0, 120, 255)
local HIGHLIGHT_OUTLINE = Color3.fromRGB(120, 190, 255)

-- Timeout (seconds) -- every action re-arms this.
local DEFAULT_TIMEOUT = 5 * 60

-- ============================================================================================
-- All Auto VoI text -- edit these to change the on-screen action text and notifications.
-- ============================================================================================
local TEXT = {
	overlayTitle = "Auto VoI",
	actionPrefix = "Current Action: ",
	actionPrefixEmpty = "Current Action:",
	elapsed = "Elapsed: %02d:%02d",
	timeout = "Timeout: %02d:%02d",
	timeoutNone = "Timeout: --",
	stopButton = "Stop",

	notInPlace = "Auto VoI: not in the VoI place.",
	timedOut = "Auto VoI: timed out.",

	checkingDistance = "checking distance to VoI",
	tooFar = "too far from VoI (idle)",
	firing = "entering VoI",
	remoteMissing = "choice remote not found",
	tweening = "flying to the boundary",
	dropping = "descending",
	teleportingCrossing = "teleporting near the boundary",
	waitingShogun = "waiting for ShogunBoundary",
	teleportingShogun = "teleporting to ShogunBoundary",
	waitingForBoss = "waiting for the boss",
	waitingForShogun = "waiting for the shogun",
	fightingShogun = "fighting the shogun",
	waitingDungeonExit = "waiting for DungeonExit",
	teleportingDungeonExit = "teleporting to DungeonExit",
	waitingTemple = "waiting for Temple of Mur",
	teleportingTemple = "teleporting to Temple of Mur",
	waitingHandler = "waiting for the handler",
	interacting = "talking to the handler",
	buying = "buying Power Recall",
	waitingGoldenRat = "waiting for GoldenRatBoundary",
	teleportingGoldenRat = "teleporting to GoldenRatBoundary",
	waitingForRatKing = "waiting for the rat king",
	fightingRatKing = "fighting the rat king",
	waitingForEnmity = "waiting for Enmity",
	fightingEnmity = "fighting Enmity",
	fightingEnforcers = "clearing enforcers",
	notInArena = "Auto VoI: Start Enmity only works in the boss arena.",
	done = "done",
}

local screenGui, actionLabel, timerLabel, timeoutLabel = nil, nil, nil, nil
local timerConnection, characterAddedConnection, noclipConnection = nil, nil, nil
local highlight = nil

local startClock = 0
local timeoutDeadline = nil
local previousTweenSpeed = nil
local previousPathfind = nil
local previousAggressive = nil
local previousFly = nil
local previousNoFall = nil
local previousVoidMobs = nil
local previousAutoDefense = nil
local previousBlockInput = nil
local previousAutoFeint = nil
local previousM1Hold = nil
local m1Held = false

-- Which boss this run targets ("shogun" or "ratking"). Persisted so it survives the place teleport
-- into the arena.
local currentTarget = nil

-- ============================================================================================
-- Helpers
-- ============================================================================================

---@return boolean
function AutoVoI.inPlace()
	return game.PlaceId == VOI_PLACE_ID
end

---@return boolean
function AutoVoI.inArena()
	return game.PlaceId == ARENA_PLACE_ID
end

---Whether we're somewhere the automation can operate (start / resume).
---@return boolean
function AutoVoI.inValidPlace()
	return AutoVoI.inPlace() or AutoVoI.inArena()
end

---@return Instance?
local function guiParent()
	local ok, coreGui = pcall(function()
		return game:GetService("CoreGui")
	end)
	if ok and coreGui then
		return coreGui
	end
	return localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
end

---@param class string
---@param props table
---@param parent Instance?
---@return Instance
local function mk(class, props, parent)
	local instance = Instance.new(class)
	for key, value in pairs(props) do
		instance[key] = value
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end

---@param seconds number
---@return string
local function formatClock(fmt, seconds)
	local minutes = math.floor(seconds / 60)
	local secs = math.floor(seconds % 60)
	return string.format(fmt, minutes, secs)
end

---@return any
local function currentSlot()
	return localPlayer and localPlayer:GetAttribute("DataSlot")
end

local function saveState()
	PersistentData.set("voidata", {
		active = true,
		slot = currentSlot(),
		target = currentTarget,
	})
end

---Arm the action timeout to `seconds` from now (nil clears it).
---@param seconds number?
local function armTimeout(seconds)
	timeoutDeadline = seconds and (os.clock() + seconds) or nil
end

---Set the "Current Action" line. Each call counts as progress, so it re-arms the default timeout.
---@param text string?
local function setAction(text)
	if actionLabel then
		actionLabel.Text = (text and text ~= "") and (TEXT.actionPrefix .. text) or TEXT.actionPrefixEmpty
	end
	armTimeout(DEFAULT_TIMEOUT)
end

---@return Model?, Humanoid?, BasePart?
local function characterParts()
	local character = localPlayer and localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local root = character and character:FindFirstChild("HumanoidRootPart")
	return character, humanoid, root
end

---Set the global tween speed (only writes when it actually changes).
---@param value number
local function setTweenSpeed(value)
	value = (Options and Options.VoITweenSpeed and Options.VoITweenSpeed.Value) or 100
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end

---Auto Ferryman's custom noclip: every frame drop CanCollide on all character parts, force the
---AirController so the ground can't hold us, and zero velocity so physics can't fight teleports.
local function applyNoClip()
	if noclipConnection then
		return
	end

	noclipConnection = runService.Stepped:Connect(function()
		if not AutoVoI.running then
			return
		end

		local character = localPlayer and localPlayer.Character
		if not character then
			return
		end

		for _, part in next, character:GetDescendants() do
			if part:IsA("BasePart") then
				pcall(function()
					if part.CanCollide then
						part.CanCollide = false
					end
					part.AssemblyLinearVelocity = Vector3.zero
					part.AssemblyAngularVelocity = Vector3.zero
				end)
			end
		end

		local controllerManager = character:FindFirstChild("ControllerManager")
		local airController = controllerManager and controllerManager:FindFirstChild("AirController")
		if controllerManager and airController then
			pcall(function()
				controllerManager.ActiveController = airController
			end)
		end
	end)
end

local function restoreNoClip()
	if noclipConnection then
		pcall(function()
			noclipConnection:Disconnect()
		end)
		noclipConnection = nil
	end
end

---Whether a position is inside the void kill volume.
---@param position Vector3
---@return boolean
local function isVoidPosition(position)
	return position.Y <= VOID_Y_THRESHOLD
end

---Is our roll off cooldown right now (mirrors mira's isRollReady)?
---@return boolean
local function isRollReady()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local module = effectReplicator and require(effectReplicator)
	if not module then
		return false
	end
	local ok, blocked = pcall(function()
		return module:HasEffect("Dodge")
			or module:HasEffect("Dodged")
			or module:HasEffect("NoRoll")
			or module:HasEffect("PreventRoll")
	end)
	return ok and not blocked
end

---Fire a direct roll the instant it's off cooldown (to survive while standing in the boss).
local function spamRoll()
	if not isRollReady() then
		return
	end
	local options = DodgeOptions.new()
	options.direct = true
	pcall(function()
		InputClient.dodge(options)
	end)
end

---Hold / release the left mouse button (drives Defense's M1 Hold, which respects block input + feint).
---@param down boolean
local function holdM1(down)
	if m1Held == down then
		return
	end
	m1Held = down
	pcall(function()
		virtualInputManager:SendMouseButtonEvent(0, 0, 0, down, game, 0)
	end)
end

---Whether a model is currently playing an Action-priority animation track.
---@param model Instance
---@return boolean
local function isPlayingActionAnim(model)
	local animator = model:FindFirstChildWhichIsA("Animator", true)
	if not animator then
		return false
	end
	local ok, tracks = pcall(function()
		return animator:GetPlayingAnimationTracks()
	end)
	if not ok or not tracks then
		return false
	end
	for _, track in ipairs(tracks) do
		if track.IsPlaying and track.Priority == Enum.AnimationPriority.Action then
			return true
		end
	end
	return false
end

---Do we currently have network ownership of a part?
---@param part BasePart
---@return boolean
local function weOwn(part)
	if not isnetworkowner then
		return false
	end
	local ok, owned = pcall(isnetworkowner, part)
	return ok and owned == true
end

---Keep physics from sleeping so we don't lose ownership of held parts.
local function keepAwake()
	pcall(function()
		settings().Physics.AllowSleep = false
	end)
end

---Max out the simulation radius so we can take/keep network ownership of the boss from any distance.
local function maxSimulationRadius()
	pcall(function()
		if setsimulationradius then
			setsimulationradius(math.huge, math.huge)
		else
			sethiddenproperty(localPlayer, "MaxSimulationRadius", 9e9)
			sethiddenproperty(localPlayer, "SimulationRadius", 9e9)
		end
	end)
end

---Force Fly on for the run, remembering its previous state.
local function applyFly()
	if Toggles and Toggles.Fly then
		if previousFly == nil then
			previousFly = Toggles.Fly.Value
		end
		Toggles.Fly:SetValue(true)
	end
end

---Press a key (used to blow through the loading screen).
---@param keyCode Enum.KeyCode
local function pressKey(keyCode)
	pcall(function()
		local vim = Instance.new("VirtualInputManager")
		vim:SendKeyEvent(true, keyCode, false, game)
		vim:SendKeyEvent(false, keyCode, false, game)
	end)
end

---Whether the character + backpack have replicated in.
---@return boolean
local function requirementsMet()
	local character = localPlayer and localPlayer.Character
	if not character then
		return false
	end
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	return backpack ~= nil and #backpack:GetChildren() > 0
end

---Whether the weapon is currently drawn (the "Equipped" effect is present).
---@return boolean
local function isWeaponDrawn()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local module = effectReplicator and require(effectReplicator)
	if not module then
		return false
	end
	local ok, has = pcall(function()
		return module:HasEffect("Equipped")
	end)
	return ok and has == true
end

---Draw the weapon (fire DrawWeapon remote, fall back to EquipTool).
local function drawWeapon()
	local character = localPlayer and localPlayer.Character
	local handler = character and character:FindFirstChild("CharacterHandler")
	local requests = handler and handler:FindFirstChild("Requests")
	local drawEvent = requests and requests:FindFirstChild("DrawWeapon")
	if drawEvent then
		pcall(function()
			drawEvent:FireServer(true)
		end)
		return
	end

	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	local tool = backpack and backpack:FindFirstChild(WEAPON_NAME)
	if humanoid and tool and tool:IsA("Tool") then
		pcall(function()
			humanoid:EquipTool(tool)
		end)
	end
end

---The first live entity in workspace.Live whose name contains `match`, or nil.
---@param match string
---@return Instance?
local function findLiveEnemyMatching(match)
	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil
	end

	local myCharacter = localPlayer and localPlayer.Character

	for _, entity in next, live:GetChildren() do
		if entity == myCharacter then
			continue
		end
		if not string.find(string.lower(entity.Name), match, 1, true) then
			continue
		end

		local humanoid = entity:FindFirstChildWhichIsA("Humanoid")
		local root = entity:FindFirstChild("HumanoidRootPart")
		if humanoid and root and humanoid.Health > 0 then
			return entity
		end
	end

	return nil
end

---Highlight the local character while running (re-adorns if it already exists).
local function applyHighlight()
	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	if highlight and highlight.Parent then
		highlight.Adornee = character
		highlight.Parent = character
		return
	end

	highlight = CoreGuiManager.imark(Instance.new("Highlight"))
	highlight.Name = "LumaAutoVoIHighlight"
	highlight.FillColor = HIGHLIGHT_FILL
	highlight.OutlineColor = HIGHLIGHT_OUTLINE
	highlight.FillTransparency = 0.5
	highlight.OutlineTransparency = 0
	highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
	highlight.Adornee = character
	highlight.Parent = character
end

local function removeHighlight()
	if highlight then
		pcall(function()
			highlight:Destroy()
		end)
		highlight = nil
	end
end

-- ============================================================================================
-- Status overlay
-- ============================================================================================

local function buildOverlay()
	if screenGui then
		return
	end

	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "LumaAutoVoIOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999

	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 300, 0, 150),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })

	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = TEXT.overlayTitle,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })

	actionLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 30),
		Size = UDim2.new(1, -16, 0, 34),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		TextWrapped = true,
		Text = TEXT.actionPrefixEmpty,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(actionLabel, { TextColor3 = "FontColor" })

	timerLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 68),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = formatClock(TEXT.elapsed, 0),
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(timerLabel, { TextColor3 = "FontColor" })

	timeoutLabel = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 90),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = TEXT.timeoutNone,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(timeoutLabel, { TextColor3 = "FontColor" })

	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = TEXT.stopButton,
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})

	stopButton.MouseButton1Click:Connect(function()
		AutoVoI.stop()
	end)

	pcall(function()
		Library:MakeDraggable(outer)
	end)

	screenGui.Enabled = false
end

-- ============================================================================================
-- Routine
-- ============================================================================================

---Find the "Choice" RemoteEvent. It lives in PlayerGui (a sibling of the ChoiceFrame prompt), so we
---search there; getnilinstances is a fallback.
---@return Instance?
local function getChoiceRemote()
	-- PlayerGui (where the choice prompt UI + its Choice remote live).
	local playerGui = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
	if playerGui then
		for _, object in ipairs(playerGui:GetDescendants()) do
			if object.Name == CHOICE_REMOTE_NAME and object:IsA("RemoteEvent") then
				return object
			end
		end
	end

	-- Fallback: parentless instances.
	if getnilinstances then
		local ok, nils = pcall(getnilinstances)
		if ok and nils then
			for _, object in next, nils do
				local nameOk = pcall(function()
					return object.Name
				end)
				if nameOk and object.Name == CHOICE_REMOTE_NAME and object:IsA("RemoteEvent") then
					return object
				end
			end
		end
	end

	return nil
end

---Teleport to a CFrame and wiggle around it a bit so the server registers the touch/arrival, then
---settle back on it.
---@param cframe CFrame
local function jitterTeleport(cframe)
	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	pcall(function()
		character:PivotTo(cframe)
	end)

	for _ = 1, 6 do
		if not AutoVoI.running then
			break
		end
		local offset = Vector3.new(math.random(-2, 2), math.random(-1, 1), math.random(-2, 2))
		pcall(function()
			character:PivotTo(cframe + offset)
		end)
		task.wait(0.1)
	end

	pcall(function()
		character:PivotTo(cframe)
	end)
end

---Teleport the character onto workspace.NexusExit (1 stud above), wiggling so the touch registers.
---@return boolean
local function teleportToNexusExit()
	local nexusExit = workspace:FindFirstChild("NexusExit")
	if not nexusExit then
		return false
	end

	local ok, pivot = pcall(function()
		return nexusExit:GetPivot()
	end)
	if not ok then
		return false
	end

	jitterTeleport(pivot + Vector3.new(0, 1, 0))
	return true
end

---Tween (fly) to a world position, Auto-Ferryman style (Y snaps to the goal Y, moves horizontally).
---Blocks until we arrive horizontally or the automation stops.
---@param goalPos Vector3
local function tweenTo(goalPos)
	-- Force a fast tween speed for the crossing, restoring the user's afterwards.
	local prevSpeed
	if Options and Options.TweenStudsPerSecond then
		prevSpeed = Options.TweenStudsPerSecond.Value
		setTweenSpeed(TWEEN_SPEED)
	end

	Tweening.goal(TWEEN_ID, CFrame.new(goalPos), false)

	while AutoVoI.running do
		local _, _, hrp = characterParts()
		if hrp then
			local dx = goalPos.X - hrp.Position.X
			local dz = goalPos.Z - hrp.Position.Z
			setAction(TEXT.tweening) -- re-arms the timeout while we travel
			if math.sqrt(dx * dx + dz * dz) <= ARRIVE_DISTANCE then
				break
			end
		end
		task.wait()
	end

	Tweening.stop(TWEEN_ID)

	if prevSpeed ~= nil and Options and Options.TweenStudsPerSecond then
		Options.TweenStudsPerSecond:SetValue(prevSpeed)
	end
end

---Snap the character to a given Y level, keeping the current X/Z.
---@param y number
local function setYLevel(y)
	local character = localPlayer and localPlayer.Character
	local _, _, hrp = characterParts()
	if character and hrp then
		pcall(function()
			character:PivotTo(CFrame.new(hrp.Position.X, y, hrp.Position.Z))
		end)
	end
end

---Poll for a part (by name) to load in, showing `actionText` while waiting.
---@param name string
---@param actionText string?
---@return Instance?
local function waitForPart(name, actionText)
	while AutoVoI.running do
		if actionText then
			setAction(actionText)
		end
		local part = workspace:FindFirstChild(name, true)
		if part then
			return part
		end
		task.wait(0.2)
	end
	return nil
end

---A part/model's CFrame.
---@param part Instance
---@return CFrame
local function partCFrame(part)
	return part:IsA("BasePart") and part.CFrame or part:GetPivot()
end

---Whether we've arrived: within `radius` of `pos` (nil pos = never "arrived").
---@param pos Vector3?
---@param radius number?
---@return boolean
local function arrivedNear(pos, radius)
	if not pos then
		return false
	end
	local _, _, root = characterParts()
	return root ~= nil and (root.Position - pos).Magnitude <= (radius or WITHIN_DISTANCE)
end

---Continuously teleport onto a part (by name). When the part is present we jitter-teleport onto it;
---when it isn't we hold at `holdPos` (to stream it in). Exits when we arrive near `arrivePos`, the
---automation stops, or -- for non-persistent teleports -- the part despawns (we moved on).
---
---`persistent` = true means it NEVER stops on the part despawning; use it for boundaries that change
---the place id (the place change / VM reset ends the loop).
---@param name string
---@param waitText string?
---@param teleportText string?
---@param holdPos Vector3?
---@param arrivePos Vector3?
---@param arriveRadius number?
---@param persistent boolean?
local function teleportToPartContinuously(name, waitText, teleportText, holdPos, arrivePos, arriveRadius, persistent)
	local seen = false

	while AutoVoI.running do
		if arrivedNear(arrivePos, arriveRadius) then
			break
		end

		local part = workspace:FindFirstChild(name, true)
		if part then
			seen = true
			if teleportText then
				setAction(teleportText)
			end
			jitterTeleport(partCFrame(part))
		else
			-- Part not present. If we'd already used it and this isn't a persistent teleport, we've
			-- moved on. Otherwise keep waiting (holding at holdPos to stream it in).
			if seen and not persistent then
				break
			end
			if waitText then
				setAction(waitText)
			end
			if holdPos then
				local character = localPlayer and localPlayer.Character
				if character then
					pcall(function()
						character:PivotTo(CFrame.new(holdPos))
					end)
				end
			end
		end

		task.wait(0.3)
	end
end

---The player's current Notes, read from the currency UI (PlayerGui.CurrencyGui.CurrencyFrame.Notes),
---or nil if it can't be read.
---@return number?
local function getNotes()
	local playerGui = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
	local currencyGui = playerGui and playerGui:FindFirstChild("CurrencyGui")
	local currencyFrame = currencyGui and currencyGui:FindFirstChild("CurrencyFrame")
	local notesLabel = currencyFrame and currencyFrame:FindFirstChild("Notes")
	local amount = notesLabel and notesLabel:FindFirstChild("Amount")
	if not amount then
		return nil
	end

	-- Strip commas / non-digits from the displayed amount.
	local digits = tostring(amount.Text or ""):gsub("[^%d]", "")
	if digits == "" then
		return nil
	end
	return tonumber(digits)
end

---The player's current Power level, or nil if it can't be read.
---@return number?
local function getPower()
	local character = localPlayer and localPlayer.Character
	if not character then
		return nil
	end
	return tonumber(character:GetAttribute("Power"))
end

---The handler NPC in workspace.NPCs, or nil.
---@return Instance?
local function findHandlerNpc()
	local npcs = workspace:FindFirstChild(NPCS_FOLDER)
	return npcs and npcs:FindFirstChild(HANDLER_NPC_NAME)
end

---Fire the NPC's InteractPrompt (same as Auto Ferryman).
---@param npc Instance
local function fireInteract(npc)
	Prompt.interact(npc:FindFirstChild(INTERACT_PROMPT_NAME, true))
end

---Resolve the Power Recall Buy TextButton under PlayerGui, or nil.
---@return Instance?
local function findBuyButton()
	local node = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
	for _, name in ipairs(BUY_BUTTON_PATH) do
		node = node and node:FindFirstChild(name)
	end
	if node and node:IsA("TextButton") then
		return node
	end
	return nil
end

---Click a TextButton by firing its MouseButton1Click connections.
---@param button Instance
local function clickButton(button)
	-- conn:Fire() on a getconnections object is the mac/macsploit NULL+0x28 SIGSEGV (native, pcall can't catch).
	-- safeClick invokes each handler's .Function directly instead -- same click, no native crash.
	safeClick(button)
end

---Exit the current dialogue (ReplicatedStorage.Requests.SendDialogue) so we can re-interact to rebuy.
local function exitDialogue()
	local requests = replicatedStorage:FindFirstChild("Requests")
	local sendDialogue = requests and requests:FindFirstChild("SendDialogue")
	if sendDialogue then
		pcall(function()
			sendDialogue:FireServer({ exit = true })
		end)
	end
end

---Generic boss fight (same logic as Auto Ferryman): Pathfind Breaker + Aggressive on, keep the weapon
---drawn, stand in front of any Live entity matching `match` and M1 it. Returns true once the boss was
---present and is gone (defeated), false if the automation stopped first.
---In-front melee boss fight (same logic as Auto Ferryman): Pathfind Breaker + Aggressive on, keep the
---weapon drawn, stand in front of any Live entity matching `match` and M1 it. Returns true once the
---boss was present and is gone (defeated), false if the automation stopped first.
---@param match string
---@param waitText string
---@param fightText string
---@return boolean
local function bossFight(match, waitText, fightText)
	-- Remember Pathfind Breaker + Aggressive Mode prior states so we can restore them after the fight.
	if Toggles and Toggles.AggressiveMode and previousAggressive == nil then
		previousAggressive = Toggles.AggressiveMode.Value
	end
	if Toggles and Toggles.NoFallDamage and previousNoFall == nil then
		previousNoFall = Toggles.NoFallDamage.Value
	end

	applyFly()
	applyNoClip()

	local bossWasPresent = false
	local dodgingAbove = false

	while AutoVoI.running do
		if Toggles and Toggles.AggressiveMode then
			Toggles.AggressiveMode:SetValue(true)
		end
		if Toggles and Toggles.NoFallDamage then
			Toggles.NoFallDamage:SetValue(true)
		end
		if Toggles and Toggles.Fly then
			Toggles.Fly:SetValue(true)
		end

		if not isWeaponDrawn() then
			drawWeapon()
		end

		local enemy = findLiveEnemyMatching(match)
		if not enemy then
			if bossWasPresent then
				break
			end
			setAction(waitText)
			Tweening.stop(FIGHT_TWEEN_ID)
			task.wait(0.3)
		else
			bossWasPresent = true

			-- Pin the boss's velocity so our fast tween into it can't fling it around.
			for _, part in next, enemy:GetDescendants() do
				if part:IsA("BasePart") then
					pcall(function()
						part.AssemblyLinearVelocity = Vector3.zero
						part.AssemblyAngularVelocity = Vector3.zero
					end)
				end
			end

			local ok, enemyCFrame = pcall(function()
				return enemy:GetPivot()
			end)
			if ok then
				local enemyPos = enemyCFrame.Position
				local character = localPlayer and localPlayer.Character
				local _, _, hrp = characterParts()

				if isPlayingActionAnim(enemy) then
					-- Shogun is doing an Action-priority move: snap 1000 studs directly above it (keeping our
					-- X/Z) and don't m1 until it's done.
					dodgingAbove = true
					Tweening.stop(FIGHT_TWEEN_ID)
					if character and hrp then
						pcall(function()
							character:PivotTo(
								CFrame.new(hrp.Position.X, enemyPos.Y + SHOGUN_DODGE_ABOVE, hrp.Position.Z)
							)
						end)
					end
				else
					-- Animation ended: snap back down to the fight spot, then resume normal following.
					if dodgingAbove then
						dodgingAbove = false
						local snapBack = (enemyCFrame * CFrame.new(0, 0, -FIGHT_FRONT_OFFSET)).Position
						if character then
							pcall(function()
								character:PivotTo(CFrame.lookAt(snapBack, enemyPos))
							end)
						end
					end

					setAction(fightText)
					setTweenSpeed(FIGHT_TWEEN_SPEED)

					local frontPos = (enemyCFrame * CFrame.new(0, 0, -FIGHT_FRONT_OFFSET)).Position
					Tweening.goal(FIGHT_TWEEN_ID, CFrame.lookAt(frontPos, enemyPos), false)

					local aim = hrp and CFrame.new(hrp.Position, enemyPos) or CFrame.new(enemyPos)
					pcall(function()
						InputClient.left(aim, true)
					end)
				end
			end
			task.wait(0.3)
		end
	end

	Tweening.stop(FIGHT_TWEEN_ID)
	return AutoVoI.running and bossWasPresent
end

---Rat King fight: normal Pathfind Breaker on, stay 5 studs behind + 3 above it holding m1 (Auto Defense
---+ Block Input + Auto Feint). Follows at 150 speed; if it blinks >500 studs away, crawl at 10 instead
---of flinging across the map. Returns true once it's present-then-gone (killed).
---@param match string
---@param waitText string
---@param fightText string
---@return boolean
local function ratKingFight(match, waitText, fightText)
	-- Remember toggles we force so we can restore them.
	if Toggles and Toggles.NoFallDamage and previousNoFall == nil then
		previousNoFall = Toggles.NoFallDamage.Value
	end
	if Toggles and Toggles.EnableAutoDefense and previousAutoDefense == nil then
		previousAutoDefense = Toggles.EnableAutoDefense.Value
	end
	if Toggles and Toggles.BlockInput and previousBlockInput == nil then
		previousBlockInput = Toggles.BlockInput.Value
	end
	if Toggles and Toggles.AutoFeint and previousAutoFeint == nil then
		previousAutoFeint = Toggles.AutoFeint.Value
	end
	if Toggles and Toggles.Fly and previousFly == nil then
		previousFly = Toggles.Fly.Value
	end

	-- Custom noclip on (CanCollide off + AirController + zero our velocity). Fly off -- movement is via
	-- tweening.
	applyNoClip()

	local bossWasPresent = false
	local dodgingAbove = false

	while AutoVoI.running do
		-- Just normal Pathfind Breaker + the combat toggles.
		if Toggles and Toggles.NoFallDamage then
			Toggles.NoFallDamage:SetValue(true)
		end
		if Toggles and Toggles.Fly then
			Toggles.Fly:SetValue(false)
		end
		if Toggles and Toggles.EnableAutoDefense then
			Toggles.EnableAutoDefense:SetValue(true)
		end
		if Toggles and Toggles.BlockInput then
			Toggles.BlockInput:SetValue(true)
		end
		if Toggles and Toggles.AutoFeint then
			Toggles.AutoFeint:SetValue(true)
		end

		if not isWeaponDrawn() then
			drawWeapon()
		end

		local _, _, localRoot = characterParts()
		if not localRoot then
			task.wait()
			continue
		end

		local enemy = findLiveEnemyMatching(match)
		if not enemy then
			if bossWasPresent then
				break
			end
			setAction(waitText)
			Tweening.stop(FIGHT_TWEEN_ID)
			task.wait(0.3)
		else
			bossWasPresent = true

			-- Anti body-part velocity: zero the boss's velocity so our tween near it can't fling it.
			for _, part in next, enemy:GetDescendants() do
				if part:IsA("BasePart") then
					pcall(function()
						part.AssemblyLinearVelocity = Vector3.zero
						part.AssemblyAngularVelocity = Vector3.zero
					end)
				end
			end

			local targetRoot = enemy:FindFirstChild("HumanoidRootPart") or enemy.PrimaryPart
			if targetRoot then
				local character = localPlayer and localPlayer.Character

				if isPlayingActionAnim(enemy) then
					-- Rat king is doing an Action-priority move: snap 500 studs directly above it (keeping
					-- our X/Z) and don't m1 until it's done.
					dodgingAbove = true
					Tweening.stop(FIGHT_TWEEN_ID)
					if character then
						pcall(function()
							character:PivotTo(
								CFrame.new(localRoot.Position.X, targetRoot.Position.Y + RATKING_DODGE_ABOVE, localRoot.Position.Z)
							)
						end)
					end
				else
					-- Animation ended: snap back down to the fight spot, then resume normal following.
					if dodgingAbove then
						dodgingAbove = false
						local snapBack = (targetRoot.CFrame * CFrame.new(0, RATKING_ABOVE, RATKING_BEHIND)).Position
						if character then
							pcall(function()
								character:PivotTo(CFrame.lookAt(snapBack, targetRoot.Position))
							end)
						end
					end

					-- Normal 150 speed; crawl at 10 if it's blinked far away (so we don't fling ourselves).
					local dist = (localRoot.Position - targetRoot.Position).Magnitude
					setTweenSpeed(dist > RATKING_FAR_DISTANCE and RATKING_FAR_SPEED or RATKING_TWEEN_SPEED)

					-- Stay 5 studs behind it and 3 studs above, facing it.
					local behindPos = (targetRoot.CFrame * CFrame.new(0, RATKING_ABOVE, RATKING_BEHIND)).Position
					Tweening.goal(FIGHT_TWEEN_ID, CFrame.lookAt(behindPos, targetRoot.Position), false)

					setAction(fightText)

					-- Spam m1 like Auto Ferryman (respect block input so blocks/punishes still land).
					if not Defense.shouldBlockInput("M1s") then
						local aim = CFrame.new(localRoot.Position, targetRoot.Position)
						pcall(function()
							InputClient.left(aim, true)
						end)
					end
				end
			end
			task.wait()
		end
	end

	Tweening.stop(FIGHT_TWEEN_ID)
	return AutoVoI.running and bossWasPresent
end

---Pick Enmity's fight targets: the boss (Live entity whose name contains ENMITY_ENEMY_MATCH) and the
---nearest "enforcer" (any OTHER live, alive, non-self entity in workspace.Live). Enforcers are killed
---first, so the caller fights the enforcer when one exists and only falls back to the boss once they're
---all cleared.
---@return Instance? boss, Instance? nearestEnforcer
local function findEnmityTargets()
	local live = workspace:FindFirstChild("Live")
	if not live then
		return nil, nil
	end

	local myCharacter = localPlayer and localPlayer.Character
	local _, _, localRoot = characterParts()

	local boss = nil
	local nearestEnforcer, nearestDist = nil, math.huge

	for _, entity in next, live:GetChildren() do
		if entity == myCharacter then
			continue
		end

		local humanoid = entity:FindFirstChildWhichIsA("Humanoid")
		local root = entity:FindFirstChild("HumanoidRootPart") or entity.PrimaryPart
		if not (humanoid and root and humanoid.Health > 0) then
			continue
		end

		if string.find(string.lower(entity.Name), ENMITY_ENEMY_MATCH, 1, true) then
			boss = entity
		else
			-- An enforcer / other enemy: track the nearest one so we clear it first.
			local dist = localRoot and (localRoot.Position - root.Position).Magnitude or 0
			if dist < nearestDist then
				nearestDist = dist
				nearestEnforcer = entity
			end
		end
	end

	return boss, nearestEnforcer
end

---Enmity fight (arena-only). Normal Pathfind Breaker on, custom noclip, always stay ENMITY_BEHIND studs
---behind + ENMITY_ABOVE up the target holding m1 (no dodge). ALWAYS spams m1 (no block-input gate), and
---prioritizes killing Enmity's enforcers (any other Live enemy) before the boss. Completion is tracked on
---the boss specifically, so enforcers spawning/dying never ends the run. Returns true once the boss was
---present and is gone (killed).
---@param waitText string
---@param fightText string
---@return boolean
local function enmityFight(waitText, fightText)
	-- Remember toggles we force so we can restore them.
	if Toggles and Toggles.NoFallDamage and previousNoFall == nil then
		previousNoFall = Toggles.NoFallDamage.Value
	end
	if Toggles and Toggles.EnableAutoDefense and previousAutoDefense == nil then
		previousAutoDefense = Toggles.EnableAutoDefense.Value
	end
	if Toggles and Toggles.BlockInput and previousBlockInput == nil then
		previousBlockInput = Toggles.BlockInput.Value
	end
	if Toggles and Toggles.AutoFeint and previousAutoFeint == nil then
		previousAutoFeint = Toggles.AutoFeint.Value
	end
	if Toggles and Toggles.Fly and previousFly == nil then
		previousFly = Toggles.Fly.Value
	end

	applyNoClip()

	local bossWasPresent = false

	while AutoVoI.running do
		if Toggles and Toggles.NoFallDamage then
			Toggles.NoFallDamage:SetValue(true)
		end
		if Toggles and Toggles.Fly then
			Toggles.Fly:SetValue(false)
		end
		if Toggles and Toggles.EnableAutoDefense then
			Toggles.EnableAutoDefense:SetValue(true)
		end
		if Toggles and Toggles.BlockInput then
			Toggles.BlockInput:SetValue(true)
		end
		if Toggles and Toggles.AutoFeint then
			Toggles.AutoFeint:SetValue(true)
		end

		if not isWeaponDrawn() then
			drawWeapon()
		end

		local _, _, localRoot = characterParts()
		if not localRoot then
			task.wait()
			continue
		end

		local boss, enforcer = findEnmityTargets()
		if boss then
			bossWasPresent = true
		end

		-- Enforcers first; only fight the boss once they're all cleared.
		local enemy = enforcer or boss
		if not enemy then
			-- No boss and no enforcers left: if the boss had been here, it's dead -> done.
			if bossWasPresent then
				break
			end
			setAction(waitText)
			Tweening.stop(FIGHT_TWEEN_ID)
			task.wait(0.3)
		else
			-- Anti body-part velocity: zero the target's velocity so our tween near it can't fling it.
			for _, part in next, enemy:GetDescendants() do
				if part:IsA("BasePart") then
					pcall(function()
						part.AssemblyLinearVelocity = Vector3.zero
						part.AssemblyAngularVelocity = Vector3.zero
					end)
				end
			end

			local targetRoot = enemy:FindFirstChild("HumanoidRootPart") or enemy.PrimaryPart
			if targetRoot then
				-- Follow speed; crawl if it's blinked far away so we don't fling ourselves.
				local dist = (localRoot.Position - targetRoot.Position).Magnitude
				setTweenSpeed(dist > RATKING_FAR_DISTANCE and RATKING_FAR_SPEED or RATKING_TWEEN_SPEED)

				-- Stay behind + above the target, facing it: enforcers 3/3, the boss 15/10.
				local behindOff = enforcer and ENMITY_ENFORCER_BEHIND or ENMITY_BEHIND
				local aboveOff = enforcer and ENMITY_ENFORCER_ABOVE or ENMITY_ABOVE
				local behindPos = (targetRoot.CFrame * CFrame.new(0, aboveOff, behindOff)).Position
				Tweening.goal(FIGHT_TWEEN_ID, CFrame.lookAt(behindPos, targetRoot.Position), false)

				setAction(enforcer and TEXT.fightingEnforcers or fightText)

				-- ALWAYS spam m1 (no block-input gate).
				local aim = CFrame.new(localRoot.Position, targetRoot.Position)
				pcall(function()
					InputClient.left(aim, true)
				end)
			end
			task.wait()
		end
	end

	Tweening.stop(FIGHT_TWEEN_ID)
	return AutoVoI.running and bossWasPresent
end

local function routine()
	-- In the boss arena: fight the run's target, then end the automation.
	if AutoVoI.inArena() then
		if currentTarget == "enmity" then
			enmityFight(TEXT.waitingForEnmity, TEXT.fightingEnmity)
		elseif currentTarget == "ratking" then
			ratKingFight(RATKING_ENEMY_MATCH, TEXT.waitingForRatKing, TEXT.fightingRatKing)
		else
			bossFight(SHOGUN_ENEMY_MATCH, TEXT.waitingForShogun, TEXT.fightingShogun)
		end

		-- Boss defeated (or stopped) -> end the automation.
		setAction(TEXT.done)
		AutoVoI.stop()
		return
	end

	-- Enmity is arena-only; there's no VoI-side path to it, so idle out here (start guards this).
	if currentTarget == "enmity" then
		setAction(TEXT.waitingForEnmity)
		return
	end

	-- In the VoI: teleport to the target boss's boundary (place change into the arena ends this).
	if currentTarget == "ratking" then
		teleportToPartContinuously(
			GOLDENRAT_BOUNDARY_NAME,
			TEXT.waitingGoldenRat,
			TEXT.teleportingGoldenRat,
			GOLDENRAT_WAIT_POS,
			nil,
			nil,
			true -- persistent: never stops (place change ends it)
		)
	else
		setAction(TEXT.teleportingCrossing)
		teleportToPartContinuously(
			SHOGUN_PART_NAME,
			TEXT.waitingShogun,
			TEXT.teleportingShogun,
			Vector3.new(CROSSING_X, DROP_Y, CROSSING_Z),
			nil,
			nil,
			true -- persistent: never stops (place change ends it)
		)
	end
end

-- ============================================================================================
-- Start / stop
-- ============================================================================================

local function teardown()
	AutoVoI.running = false

	if timerConnection then
		pcall(function()
			timerConnection:Disconnect()
		end)
		timerConnection = nil
	end
	if characterAddedConnection then
		pcall(function()
			characterAddedConnection:Disconnect()
		end)
		characterAddedConnection = nil
	end

	restoreNoClip()
	removeHighlight()
	holdM1(false)

	timeoutDeadline = nil

	pcall(function()
		Tweening.stop(TWEEN_ID)
		Tweening.stop(FIGHT_TWEEN_ID)
	end)

	-- Restore anything the run forced.
	if previousTweenSpeed ~= nil and Options and Options.TweenStudsPerSecond then
		Options.TweenStudsPerSecond:SetValue(previousTweenSpeed)
	end
	if previousAggressive ~= nil and Toggles and Toggles.AggressiveMode then
		Toggles.AggressiveMode:SetValue(previousAggressive)
	end
	if previousFly ~= nil and Toggles and Toggles.Fly then
		Toggles.Fly:SetValue(previousFly)
	end
	if previousVoidMobs ~= nil and Toggles and Toggles.VoidMobs then
		Toggles.VoidMobs:SetValue(previousVoidMobs)
	end
	if previousNoFall ~= nil and Toggles and Toggles.NoFallDamage then
		Toggles.NoFallDamage:SetValue(previousNoFall)
	end
	if previousAutoDefense ~= nil and Toggles and Toggles.EnableAutoDefense then
		Toggles.EnableAutoDefense:SetValue(previousAutoDefense)
	end
	if previousBlockInput ~= nil and Toggles and Toggles.BlockInput then
		Toggles.BlockInput:SetValue(previousBlockInput)
	end
	if previousAutoFeint ~= nil and Toggles and Toggles.AutoFeint then
		Toggles.AutoFeint:SetValue(previousAutoFeint)
	end
	if previousM1Hold ~= nil and Toggles and Toggles.M1Hold then
		Toggles.M1Hold:SetValue(previousM1Hold)
	end
	previousTweenSpeed = nil
	previousPathfind = nil
	previousAggressive = nil
	previousFly = nil
	previousNoFall = nil
	previousVoidMobs = nil
	previousAutoDefense = nil
	previousBlockInput = nil
	previousAutoFeint = nil
	previousM1Hold = nil

	if screenGui then
		screenGui.Enabled = false
	end
end

---@param target string? "shogun" or "ratking" for a manual start; nil = server-hop resume (read the
---persisted target).
function AutoVoI.start(target)
	if AutoVoI.running then
		return
	end

	if not AutoVoI.inValidPlace() then
		return Logger.notify(TEXT.notInPlace)
	end

	-- Resolve the target: a manual Start passes it; a resume reads the persisted one.
	if target then
		currentTarget = target
	else
		local existing = PersistentData.get("voidata")
		currentTarget = existing and existing.target
	end
	if not currentTarget then
		return
	end

	-- Enmity is an arena-only boss -- it can only be started from inside the boss arena.
	if currentTarget == "enmity" and not AutoVoI.inArena() then
		return Logger.notify(TEXT.notInArena)
	end

	-- If the loading screen (LoadingGui) is up (e.g. we just resumed after a place teleport), spam A to
	-- blow through it until the character + backpack have replicated (10s cap) -- same as Auto Ferryman.
	local playerGui = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
	if playerGui and playerGui:FindFirstChild("LoadingGui") then
		local deadline = os.clock() + 10
		while not requirementsMet() and os.clock() < deadline do
			pressKey(Enum.KeyCode.A)
			task.wait(0.25)
		end
	end

	startClock = os.clock()
	AutoVoI.running = true

	-- Capture the user's tween speed so we can restore it after the run.
	if Options and Options.TweenStudsPerSecond then
		previousTweenSpeed = Options.TweenStudsPerSecond.Value
	end

	-- Resume flag: survives server hops (MemStorage).
	saveState()

	buildOverlay()
	setAction(nil)
	if timerLabel then
		timerLabel.Text = formatClock(TEXT.elapsed, 0)
	end
	if timeoutLabel then
		timeoutLabel.Text = TEXT.timeoutNone
	end
	if screenGui then
		screenGui.Enabled = true
	end

	-- Fly + custom noclip for the run.
	applyFly()
	applyNoClip()

	-- Highlight the character, and re-apply it (+ noclip via its connection) if we respawn mid-run.
	applyHighlight()
	characterAddedConnection = localPlayer.CharacterAdded:Connect(function()
		if not AutoVoI.running then
			return
		end
		task.wait(0.2)
		applyHighlight()
		applyFly()
	end)

	-- Tick the elapsed timer + the timeout countdown (and enforce the timeout).
	timerConnection = runService.Heartbeat:Connect(function()
		if not AutoVoI.running then
			return
		end

		if timerLabel then
			timerLabel.Text = formatClock(TEXT.elapsed, os.clock() - startClock)
		end

		if timeoutLabel then
			if timeoutDeadline then
				timeoutLabel.Text = formatClock(TEXT.timeout, math.max(0, timeoutDeadline - os.clock()))
			else
				timeoutLabel.Text = TEXT.timeoutNone
			end
		end

		if timeoutDeadline and os.clock() >= timeoutDeadline then
			Logger.notify(TEXT.timedOut)
			AutoVoI.stop()
		end
	end)

	-- Run the routine off-thread so pathfinding can block.
	task.spawn(routine)
end

function AutoVoI.stop()
	if not AutoVoI.running and not PersistentData.get("voidata") then
		return
	end

	teardown()

	-- Clear the target + resume flag so a re-execute doesn't restart it.
	currentTarget = nil
	PersistentData.set("voidata", nil)
end

function AutoVoI.init()
	if not LPH_OBFUSCATED or (shared.Luma and shared.Luma.verbose) then
		Logger.warn("Auto VoI initialized.")
	end
end

return AutoVoI

end)
__bundle_register("@luma/Features/Automation/CharismaFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
local CharismaFarm = {}

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Utility.Signal
local Signal = require("@luma/Utility/Signal")

---@module Utility.Attributes
local Attributes = require("@luma/Utility/Attributes")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module Utility.Throttle
local throttle = require("@luma/Utility/Throttle")

local players = game:GetService("Players")
local runService = game:GetService("RunService")

local renderStepped = Signal.new(runService.RenderStepped)

local autoCharismaMaid = Maid.new()

local updateCharisma = LPH_NO_VIRTUALIZE(function()
	local charismaFarm = Toggles["AutoCharisma"]
	if not charismaFarm or not charismaFarm.Value then
		return
	end

	local charismaFarmCap = Options["CharismaCap"]
	if not charismaFarmCap then
		return
	end

	local localPlayer = players.LocalPlayer
	local localPlayerCharacter = localPlayer.Character
	if not localPlayerCharacter then
		return
	end

	if not Attributes.isNotAtCap(localPlayerCharacter, "Stat_Charisma", charismaFarmCap.Value - 1) then
		Logger.longNotify("Charisma AutoFarm is automatically stopping.")
		return charismaFarm:SetValue(false)
	end

	local humanoid = localPlayerCharacter:FindFirstChild("Humanoid")
	if not humanoid then
		return
	end

	local backpack = localPlayer:FindFirstChild("Backpack")
	if not backpack then
		return
	end

	local characterBook = localPlayerCharacter:FindFirstChild("How to Make Friends")
	local backpackBook = backpack:FindFirstChild("How to Make Friends")

	if not characterBook and backpackBook then
		return humanoid:EquipTool(backpackBook)
	end

	local choicePrompt = localPlayer.PlayerGui:FindFirstChild("ChoicePrompt")
	if not choicePrompt then
		return characterBook and characterBook:Activate()
	end

	local choiceFrame = choicePrompt:FindFirstChild("ChoiceFrame")
	if not choiceFrame then
		return
	end

	local chatChoice = choicePrompt:FindFirstChild("ChatChoice")
	if not chatChoice then
		return
	end

	local description = choiceFrame:FindFirstChild("Desc")
	if not description then
		return
	end

	local text = description.Text:split("\n")
	local charismaLine = text[2]:sub(2, -2)

	chatChoice:InvokeServer(charismaLine)
end)

function CharismaFarm.init()
	autoCharismaMaid:add(renderStepped:connect("AttributeFarmCharisma_OnPreRender", throttle(1 / 10, updateCharisma)))

	if not LPH_OBFUSCATED or shared.Luma.verbose then
		Logger.warn("Charisma Farm initialized.")
	end
end

function CharismaFarm.detach()
	autoCharismaMaid:clean()

	Logger.warn("Charisma Farm detached.")
end

return CharismaFarm

end)
__bundle_register("@luma/Features/Automation/EchoFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
-- EchoFarm (Titus): a luma port of project-rain-oss's `titus_echofarm.lua`, built on the ported
-- AutomationStruct + StateMachine framework. Constructs a struct with PR's echo feature set and drives the
-- same state machine: create character -> enter the Titus dungeon -> break Titus (mob_ai_breaker) -> loot
-- the chest -> enchant -> wipe -> cash the run's echoes in at Fragments of Self -> repeat.
--
-- Public surface kept identical for luma's menu + resume wiring:
--   EchoFarm.invoke() -- menu Start (bootstraps efdata, then start)
--   EchoFarm.start()  -- resume entry (Luma.lua calls this when efdata survives a hop/teleport)
--   EchoFarm.stop()   -- menu Stop
-- Persistence key: "efdata" { slot, startedAt, echoes, cycles }.
local EchoFarm = {}

-- Set true ONLY while we're flinging the chaser into the void. The pre-wired hooks in Exploits
-- (Fling on the chaser) and OwnershipWatcher (own the chaser instead of dropping it) read this
-- field, so it must live on the module table, not a local.
EchoFarm.voiding = false

---@module Utility.PersistentData
local PersistentData = require("@luma/Utility/PersistentData")

---@module Game.ServerHop
local ServerHop = require("@luma/Game/ServerHop")

---@module Game.Wipe
local Wipe = require("@luma/Game/Wipe")

---@module Features.Game.Tweening
local Tweening = require("@luma/Features/Game/Tweening")

---@module Utility.Prompt
local Prompt = require("@luma/Utility/Prompt")

---@module Features.Automation.AutoLoot
local AutoLoot = require("@luma/Features/Automation/AutoLoot")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module GUI.Library
local Library = require("@luma/GUI/Library")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("@luma/Utility/CoreGuiManager")

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Game.AntiAFK
local AntiAFK = require("@luma/Game/AntiAFK")

---@module Game.InputClient
local InputClient = require("@luma/Game/InputClient")

---@module Features.Automation.Objects.StateMachine
local StateMachine = require("@luma/Features/Automation/Objects/StateMachine")

---@module Features.Automation.Objects.AutomationStruct
local AutomationStruct = require("@luma/Features/Automation/Objects/AutomationStruct")

---@module Features.Automation.Objects.AutoLog
local AutoLog = require("@luma/Features/Automation/Objects/AutoLog")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")

local EASTERN_PLACE_ID = 6473861193 -- Fort Merit hub (dungeon entered from here).
local DUNGEON_PLACE_ID = 8668476218 -- The Titus (Detainment) dungeon.
local LOBBY_PLACE_ID = 4111023553
local DEPTHS_PLACE_ID = 5735553160
local CHIME_LOBBY_PLACE_ID = 12559711136

local MOVE_ID = "EchoFarm_Move"
local ENTRANCE = CFrame.new(-6875.86, 336.2, 2827.95)
local ENTRANCE_SPEED = 40
local PLAYER_SAFE_RADIUS = 200
local APPROACH_Y = 288
local ATTACH_DISTANCE = 35

local running = false
local struct = nil
local maid = Maid.new()
local getScoreConn = nil -- persistent GetScore.OnClientEvent listener (echo counting).
local actionStartedAt = 0 -- os.clock() when the current stage began (0 = disarmed); per-action watchdog.
local ACTION_TIMEOUT = 60 -- if a single stage stalls longer than this, wipe to reset the whole cycle.
local VOID_TIMEOUT = 45 -- shorter cap for the Titus voiding phase ("fighting titus") specifically.
local currentActionTimeout = ACTION_TIMEOUT -- active timeout for the current stage (set per-stage in setStage).

local screenGui, stageLabel, echoLabel, timeLabel, epmLabel = nil, nil, nil, nil, nil

-- =========================================================================================================
-- Local-player accessors.
-- =========================================================================================================
local function localPlayer()
	return players.LocalPlayer
end

local function character()
	local lp = localPlayer()
	return lp and lp.Character
end

local function root()
	local c = character()
	return c and c:FindFirstChild("HumanoidRootPart")
end

local function humanoid()
	local c = character()
	return c and c:FindFirstChildOfClass("Humanoid")
end

local function playerGui()
	local lp = localPlayer()
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end

local function currentSlot()
	local lp = localPlayer()
	return lp and lp:GetAttribute("DataSlot")
end

local function currentArea()
	local lp = localPlayer()
	return lp and lp:GetAttribute("CurrentArea")
end

local function isRunning()
	return running
end

-- =========================================================================================================
-- Overlay.
-- =========================================================================================================
local function guiParent()
	return (gethui and gethui()) or game:GetService("CoreGui")
end

local function mk(class, props, parent)
	local instance = Instance.new(class)
	for key, value in pairs(props) do
		instance[key] = value
	end
	if parent then
		instance.Parent = parent
	end
	return instance
end

local function buildOverlay()
	if screenGui then
		return
	end

	screenGui = CoreGuiManager.imark(Instance.new("ScreenGui"))
	screenGui.Name = "LumaEchoFarmOverlay"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	screenGui.DisplayOrder = 9999

	local protectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(protectGui, screenGui)
	screenGui.Parent = guiParent()

	local outer = mk("Frame", {
		Name = "Outer",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 46),
		Size = UDim2.new(0, 320, 0, 130),
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		ZIndex = 200,
	}, screenGui)
	Library:AddToRegistry(outer, { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" })

	local efMode = (PersistentData.get("efdata") and PersistentData.get("efdata").mode) or "Titus"
	local title = mk("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 8, 0, 6),
		Size = UDim2.new(1, -16, 0, 20),
		FontFace = Library.Font,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Library.AccentColor,
		Text = (efMode == "Layer2") and "Layer 2 Echo Farm" or "Titus Echo Farm",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(title, { TextColor3 = "AccentColor" })

	local function statLabel(y, text)
		local label = mk("TextLabel", {
			BackgroundTransparency = 1,
			Position = UDim2.new(0, 8, 0, y),
			Size = UDim2.new(1, -16, 0, 16),
			FontFace = Library.Font,
			TextSize = 14,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
			Text = text,
			ZIndex = 201,
		}, outer)
		Library:AddToRegistry(label, { TextColor3 = "FontColor" })
		return label
	end

	echoLabel = statLabel(30, "Echoes: 0")
	timeLabel = statLabel(50, "Elapsed: 0s")
	epmLabel = statLabel(70, "Echoes/min: 0.00")

	local stopButton = mk("TextButton", {
		Position = UDim2.new(0, 8, 1, -30),
		Size = UDim2.new(1, -16, 0, 22),
		AutoButtonColor = true,
		BackgroundColor3 = Library:GetDarkerColor(Library.MainColor),
		BorderColor3 = Library.OutlineColor,
		BorderSizePixel = 1,
		FontFace = Library.Font,
		TextSize = 15,
		TextColor3 = Library.FontColor or Color3.new(1, 1, 1),
		Text = "Stop",
		ZIndex = 201,
	}, outer)
	Library:AddToRegistry(stopButton, {
		BackgroundColor3 = function()
			return Library:GetDarkerColor(Library.MainColor)
		end,
		BorderColor3 = "OutlineColor",
		TextColor3 = "FontColor",
	})
	stopButton.MouseButton1Click:Connect(function()
		EchoFarm.stop()
	end)

	pcall(function()
		Library:MakeDraggable(outer)
	end)
end

local function destroyOverlay()
	if screenGui then
		pcall(function()
			screenGui:Destroy()
		end)
		screenGui = nil
	end
	stageLabel, echoLabel, timeLabel, epmLabel = nil, nil, nil, nil
end

local function setStage(name)
	-- Re-arm the per-action watchdog on every stage change. The Titus voiding phase gets a shorter cap.
	actionStartedAt = os.clock()
	currentActionTimeout = (name == "fighting titus") and VOID_TIMEOUT or ACTION_TIMEOUT
	if stageLabel then
		stageLabel.Text = "Stage: " .. tostring(name)
	end
end

local function formatDuration(seconds)
	seconds = math.floor(seconds)
	if seconds < 60 then
		return seconds .. "s"
	end
	local minutes = math.floor(seconds / 60)
	if seconds < 3600 then
		return minutes .. "m " .. (seconds % 60) .. "s"
	end
	return math.floor(minutes / 60) .. "h " .. (minutes % 60) .. "m"
end

---Connect a PERSISTENT GetScore.OnClientEvent listener: whenever the server pushes the run score, fold its
---.Echoes into efdata. Idempotent. This is what actually counts echoes -- the fragments wipe itself is
---handled by luma's Wipe module (which bypasses our state machine), so counting can't live only there.
local function connectScoreListener()
	if getScoreConn then
		return
	end
	pcall(function()
		local remote = replicatedStorage:WaitForChild("Requests"):WaitForChild("GetScore")
		getScoreConn = remote.OnClientEvent:Connect(function(v)
			local gained = (typeof(v) == "table" and tonumber(v.Echoes)) or 0
			if gained and gained > 0 then
				local data = PersistentData.get("efdata")
				if data then
					PersistentData.stf("efdata", "echoes", (data.echoes or 0) + gained)
				end
			end
		end)
		maid:mark(getScoreConn)
	end)
end

---End of a cycle: bump the cycle count and request the run score ONCE (the persistent listener folds the
---returned .Echoes into the total). A single fire so we don't double-count the same run.
local function recordCycle()
	local data = PersistentData.get("efdata")
	if data then
		PersistentData.stf("efdata", "cycles", (data.cycles or 0) + 1)
	end
	connectScoreListener()
	pcall(function()
		replicatedStorage:WaitForChild("Requests"):WaitForChild("GetScore"):FireServer()
	end)
end

local function runStats()
	while running do
		-- Keep No Fall Damage forced on for the entire farm (respawns / new characters can drop it).
		if Toggles and Toggles.NoFallDamage and not Toggles.NoFallDamage.Value then
			Toggles.NoFallDamage:SetValue(true)
		end

		local data = PersistentData.get("efdata")
		if data then
			local startedAt = data.startedAt or os.time()
			local elapsed = math.max(0, os.time() - startedAt)
			local echoes = data.echoes or 0
			if echoLabel then
				echoLabel.Text = "Echoes: " .. echoes
			end
			if timeLabel then
				timeLabel.Text = "Elapsed: " .. formatDuration(elapsed)
			end
			if epmLabel then
				epmLabel.Text = string.format("Echoes/min: %.2f", echoes / math.max(1 / 60, elapsed / 60))
			end
		end
		task.wait(0.25)
	end
end

---Per-action watchdog: if a single stage stalls longer than ACTION_TIMEOUT, run the wipe loop to reset the
---whole cycle from a fresh character (Luma's resume brings us back in afterward).
local function runActionWatchdog()
	while running do
		if actionStartedAt > 0 and os.clock() - actionStartedAt > currentActionTimeout then
			actionStartedAt = 0 -- disarm so we only fire once
			-- Titus voiding stage ("fighting titus" is the only stage on VOID_TIMEOUT): do NOT wipe --
			-- wiping nukes the character + the run's echoes. Server-hop to rejoin a fresh server instead
			-- (Luma's resume re-enters and continues), matching the relic farm. Every other stage wipes.
			if currentActionTimeout == VOID_TIMEOUT then
				-- Rejoin instead of wiping. Resolve the slot with the efdata fallback (same as the wipe
				-- path): in the dungeon the live DataSlot attribute is often missing, and serverHop() /
				-- ServerHop.hop no-ops on a nil slot -- which made the timeout look like it did nothing.
				local data = PersistentData.get("efdata")
				local slot = currentSlot() or (data and data.slot)
				setStage("titus voiding timed out -- rejoining")
				pcall(function()
					ServerHop.hop(slot, true)
				end)
				return
			end
			local data = PersistentData.get("efdata")
			local slot = currentSlot() or (data and data.slot)
			if slot then
				setStage("action timed out -- wiping")
				pcall(function()
					Wipe.invoke(slot)
				end)
			end
			return
		end
		task.wait(0.25)
	end
end

-- =========================================================================================================
-- Movement primitives (ported from PR's autotitus table).
-- =========================================================================================================
local function setSpeed(value, force)
	-- Normally the per-automation Tween Speed slider wins; `force` lets a specific move (the dungeon-door
	-- travel) pin an exact speed regardless of the slider.
	if not force then
		value = (Options and Options.EchoFarmTweenSpeed and Options.EchoFarmTweenSpeed.Value) or 100
	end
	if Options and Options.TweenStudsPerSecond and Options.TweenStudsPerSecond.Value ~= value then
		Options.TweenStudsPerSecond:SetValue(value)
	end
end

---Blocking tween to a CFrame at `speed` (PR's Tween.new(cf, true, speed).wait()).
---When `force` is set (the dungeon-door travel), step the root toward the goal at an EXACT studs/second
---ourselves instead of going through the shared Tween Speed slider. That slider is clamped (Min) and shared
---across every automation, so it can't reliably pin a slow speed -- this keeps the door approach at the
---speed we actually ask for (e.g. 10 studs/s) no matter what the slider says.
local function tempTween(cframe, speed, force)
	if force then
		Tweening.stop(MOVE_ID) -- make sure the engine isn't also driving us toward a stale goal
		local targetPos = cframe.Position
		local studsPerSecond = speed or 150
		local dt = task.wait()
		while running do
			local r = root()
			if not r then
				return
			end
			r.AssemblyLinearVelocity = Vector3.zero
			local pos = r.Position
			local toTarget = targetPos - pos
			local dist = toTarget.Magnitude
			if dist <= 1 then
				break
			end
			local stepDist = studsPerSecond * dt
			if stepDist >= dist then
				r.CFrame = CFrame.new(targetPos)
				break
			end
			r.CFrame = CFrame.new(pos + (toTarget / dist) * stepDist)
			dt = task.wait()
		end
		return
	end

	setSpeed(speed or 150, force)
	Tweening.goal(MOVE_ID, cframe, false)
	local goalPos = cframe.Position
	while running do
		local r = root()
		if r and (r.Position - goalPos).Magnitude <= 10 then
			break
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end

---True if another player is within `mag` of `position` (defaults to our root).
local function playerCheck(mag, position)
	local origin = position or (root() and root().Position)
	if not origin then
		return false
	end
	for _, other in next, players:GetPlayers() do
		if other == localPlayer() or not other.Character then
			continue
		end
		local hrp = other.Character:FindFirstChild("HumanoidRootPart")
		if hrp and (origin - hrp.Position).Magnitude <= mag then
			return true
		end
	end
	return false
end

local function serverHop()
	-- currentSlot() reads the live DataSlot attribute, which is often absent inside dungeons (e.g. the
	-- Titus dungeon); fall back to the farm's persisted slot so the hop resolves a real save slot instead
	-- of no-opping on nil. Makes every hop -- auto-log, exit hop, the voiding rejoin -- work in the dungeon.
	local data = PersistentData.get("efdata")
	local slot = currentSlot() or (data and data.slot)
	pcall(function()
		ServerHop.hop(slot, true)
	end)
end

-- Player-proximity "auto log" hop, gated by the per-automation auto-log distance (echo_farm slider). 0 = off,
-- so NOTHING in the farm hops on nearby players -- including the Fragments of Self cash-in.
local function shouldLogHop(position)
	local dist = AutoLog.get("echo_farm")
	if dist <= 0 then
		return false
	end
	return playerCheck(dist, position)
end

---Player-safe tween: hop away if anyone is near us/the target, else fly there at altitude and snap down
---(matches Auto Titus -- travel high above the map so nothing along the way can interrupt us).
---@param groundLevel boolean? when true, travel at ground level (no altitude lift) instead of high up.
local function playerSafeTween(cf, speed, groundLevel, force)
	if shouldLogHop() then
		serverHop()
		while task.wait() do
		end
		return
	end
	local r = root()
	if not r then
		return
	end
	if groundLevel then
		-- Match the dungeon door's Y: snap to the target's height, then tween horizontally across to it at
		-- that same Y level (no altitude lift).
		r.CFrame = CFrame.new(r.Position.X, cf.Position.Y, r.Position.Z)
		tempTween(cf, speed, force)
	else
		local y = math.random(8000, 10000)
		r.CFrame = r.CFrame + Vector3.new(0, y, 0)
		tempTween(cf + Vector3.new(0, y, 0), speed, force)
	end
	if shouldLogHop(cf.Position) then
		serverHop()
		while task.wait() do
		end
		return
	end
	r = root()
	if r then
		r.CFrame = cf
	end
end

-- =========================================================================================================
-- Dungeon flow (ported from PR titus_echofarm).
-- =========================================================================================================
local function enterDungeon()
	setStage("enter dungeon")
	-- Force noclip on for the trip to the dungeon door so geometry can't snag us on the way in.
	pcall(function()
		if Toggles and Toggles.NoClip then
			Toggles.NoClip:SetValue(true)
		end
	end)
	pcall(function()
		replicatedStorage.Requests.UpdateUXSettings:FireServer("FriendlyFire", true)
	end)

	-- Keep noclip enforced for the WHOLE trip to the door (not just once we're there): re-assert the NoClip
	-- toggle and brute-force every character part CanCollide=false each frame while we travel, so geometry
	-- can't snag us on the way in.
	local travelNoclip = runService.Heartbeat:Connect(function()
		if Toggles and Toggles.NoClip and not Toggles.NoClip.Value then
			Toggles.NoClip:SetValue(true)
		end
		local c = character()
		if c then
			for _, part in next, c:GetDescendants() do
				if part:IsA("BasePart") and part.CanCollide then
					part.CanCollide = false
				end
			end
		end
	end)

	playerSafeTween(ENTRANCE, ENTRANCE_SPEED, true, true) -- ground level (y=0) to the door; force 40 studs/s regardless of the Tween Speed slider
	pcall(function()
		travelNoclip:Disconnect()
	end)
	pcall(function()
		replicatedStorage.Requests.UpdateUXSettings:FireServer("FriendlyFire", true)
	end)

	local entry = workspace:WaitForChild("Map", 10)
	entry = entry and entry:WaitForChild("MeritEntry", 5)

	-- Pin us to the entrance while firing the prompt so nothing nudges us off the door.
	local holdConn = runService.Heartbeat:Connect(function()
		local r = root()
		if r then
			r.CFrame = ENTRANCE
		end
		-- Brute-force noclip for the door approach: force every character part CanCollide=false each frame so
		-- geometry can't snag us (doesn't rely on the NoClip toggle / Movement loop).
		local c = character()
		if c then
			for _, part in next, c:GetDescendants() do
				if part:IsA("BasePart") and part.CanCollide then
					part.CanCollide = false
				end
			end
		end
	end)

	local start = tick()
	repeat
		-- Keep noclip ON for the whole door approach (re-assert each pass -- a one-shot set can get cleared by
		-- the fresh-character spawn / feature management, same reason the no-fall loop re-asserts).
		if Toggles and Toggles.NoClip and not Toggles.NoClip.Value then
			Toggles.NoClip:SetValue(true)
		end
		if shouldLogHop(ENTRANCE.Position) then
			if holdConn then
				holdConn:Disconnect()
			end
			serverHop()
			while task.wait() do
			end
			return
		end
		if entry and entry:FindFirstChild("InteractPrompt") then
			Prompt.interact(entry.InteractPrompt)
		end
		task.wait(0.1)
	until tick() - start > 15 or game.PlaceId ~= EASTERN_PLACE_ID or not running

	if holdConn then
		holdConn:Disconnect()
	end
end

-- Old pathfind (mob_ai) breaker, baked straight into the Titus fight (no toggle). Every Heartbeat we
-- snapshot the root's real velocity, then slam it straight down (0, -9e11, 0); we restore the snapshot
-- BEFORE the next physics step so we never actually fall -- the slam lives for one tick, just long enough
-- to replicate the fling. The restore runs on PreRender AND PreSimulation: PreRender covers the focused
-- case, PreSimulation also fires while the window is UNFOCUSED (PreRender doesn't), so an AFK/tabbed-out
-- session can't skip the restore and let the slam rocket us into the void / null zone.
local titusBreakerHB = nil
local titusBreakerPR = nil
local titusBreakerPS = nil
local titusBreakerLastVel = nil

local function stopTitusBreaker()
	if titusBreakerHB then
		pcall(function()
			titusBreakerHB:Disconnect()
		end)
		titusBreakerHB = nil
	end
	if titusBreakerPR then
		pcall(function()
			titusBreakerPR:Disconnect()
		end)
		titusBreakerPR = nil
	end
	if titusBreakerPS then
		pcall(function()
			titusBreakerPS:Disconnect()
		end)
		titusBreakerPS = nil
	end
	if titusBreakerLastVel then
		local r = root()
		if r then
			pcall(function()
				r.AssemblyLinearVelocity = titusBreakerLastVel
			end)
		end
		titusBreakerLastVel = nil
	end
end

local function startTitusBreaker()
	stopTitusBreaker()

	-- Restore the pre-slam velocity. Runs on every pre-physics tick so the slam is always undone before
	-- physics integrates it (otherwise -9e11 would carry us straight into the void).
	local function restoreBreakerVelocity()
		if not titusBreakerLastVel then
			return
		end
		local r = root()
		if r then
			r.AssemblyLinearVelocity = titusBreakerLastVel
		end
		titusBreakerLastVel = nil
	end

	titusBreakerHB = runService.Heartbeat:Connect(function()
		local r = root()
		if not r then
			return
		end
		titusBreakerLastVel = r.AssemblyLinearVelocity
		r.AssemblyLinearVelocity = Vector3.new(0, -9e11, 0)
	end)

	-- PreRender restores while the window is focused; PreSimulation (falling back to Stepped) also fires
	-- when it's unfocused, so the restore can never be skipped and let the slam fling us to the null zone.
	titusBreakerPR = runService.PreRender:Connect(restoreBreakerVelocity)
	local preSim = runService.PreSimulation or runService.Stepped
	if preSim then
		titusBreakerPS = preSim:Connect(restoreBreakerVelocity)
	end
end

---Ram up and down through Titus's torso; the inline pathfind breaker does the actual killing.
local function attachToTitus()
	setStage("fighting titus")

	local titus
	repeat
		for _, ent in next, workspace.Live:GetChildren() do
			if ent.Name:lower():find("titus") and ent.Name:find("%.") then
				titus = ent
				break
			end
		end
		task.wait()
	until titus or not running
	if not titus then
		return
	end

	local torso = titus:WaitForChild("Torso")
	if not torso then
		return
	end

	local playerRoot = root()
	if not playerRoot then
		return
	end

	-- Dodge spam (PR's VIM Q loop -> luma InputClient.dodge).
	maid:mark(task.spawn(function()
		while titus and titus.Parent and running do
			pcall(function()
				InputClient.dodge({ direct = true })
			end)
			task.wait(0.35)
		end
	end))

	local targetCF = CFrame.new(torso.CFrame.X, APPROACH_Y, torso.CFrame.Z)
	playerRoot.AssemblyLinearVelocity = Vector3.zero
	tempTween(targetCF, 250)
	task.wait(0.5)
	tempTween(targetCF, 250)

	-- Kill by ramming up and down THROUGH Titus's torso: oscillate between his torso and a point VOID_SWING
	-- studs above it (position-only target -- a straight vertical lookAt is degenerate and NaNs the CFrame).
	-- The pathfind breaker does the damage; this just drives the motion. Done when he dies, or hop if he
	-- somehow gets flung up off the map.
	startTitusBreaker()
	-- Ram hard and FAST through Titus's torso at a fixed, slider-independent speed (the shared Tween Speed
	-- slider can't be trusted to hold a value at runtime, and the old setSpeed(200) was non-force so it
	-- silently ran at the ~100 slider default). Step the root straight between his torso and VOID_SWING studs
	-- above it, flipping the instant we reach an end, slamming the whole time via the breaker.
	local VOID_SWING = 100
	local RAM_SPEED = 900
	-- If Titus gets flung farther than this from us, stop chasing him. He's on his way out (flung/voiding),
	-- and gliding across the map after his torso is exactly the bug we're fixing. Hold position instead and
	-- keep swinging; he dies or comes back, and the per-action watchdog server-hops if the fight truly stalls.
	local MAX_RAM_DISTANCE = 10000
	local voidGoingIn = true
	local dt = task.wait()
	while running do
		if not titus or not titus.Parent or not torso.Parent then
			break
		end
		if torso.Position.Y > 2000 then
			stopTitusBreaker()
			serverHop()
			return
		end

		playerRoot = root()
		if playerRoot then
			playerRoot.AssemblyLinearVelocity = Vector3.zero

			local ramPos = torso.Position + Vector3.new(0, voidGoingIn and VOID_SWING or 0, 0)
			local toTarget = ramPos - playerRoot.Position
			local dist = toTarget.Magnitude
			-- Only ram/move while he's close. Flung too far -> don't chase; lift up to Y=1000 and wait him out.
			if dist <= MAX_RAM_DISTANCE then
				local stepDist = RAM_SPEED * dt
				if dist <= stepDist or dist < 3 then
					playerRoot.CFrame = CFrame.new(ramPos)
					voidGoingIn = not voidGoingIn
				else
					playerRoot.CFrame = CFrame.new(playerRoot.Position + (toTarget / dist) * stepDist)
				end
			else
				-- Titus flung past MAX_RAM_DISTANCE: sit at Y=1000 (keep our X/Z) instead of gliding after him.
				local pos = playerRoot.Position
				playerRoot.CFrame = CFrame.new(pos.X, 1000, pos.Z)
			end
			pcall(function()
				character().CharacterHandler.Requests.DrawWeapon:FireServer(true)
			end)
		end

		dt = task.wait()
	end
	stopTitusBreaker()
	Tweening.stop(MOVE_ID)
end

---Loot the boss chest (echo: force Loot All).
local function grabChest()
	setStage("looting chest")

	-- Find the chest (wait for it to spawn after the kill).
	local chest
	local findStart = tick()
	repeat
		local thrown = workspace:FindFirstChild("Thrown")
		if thrown then
			for _, object in next, thrown:GetChildren() do
				if object:FindFirstChild("Lid") then
					chest = object
					break
				end
			end
		end
		if not chest then
			task.wait()
		end
	until chest or not running or (tick() - findStart > 15)
	if not chest then
		return
	end

	local previousAutoLootIgnore = AutoLoot.ignore
	AutoLoot.ignore = true
	local ok, err = xpcall(function()
		-- Chest appeared: snap straight onto it and hold there. After the post-kill teleport we're ~1300 studs
		-- up, so don't rely on a slow descend tween -- lock onto the chest position immediately, then the
		-- re-tween loop below keeps us glued to it while we open + loot.
		do
			local rr = root()
			if rr then
				rr.AssemblyLinearVelocity = Vector3.zero
				rr.CFrame = CFrame.new(chest.Lid.CFrame.Position)
			end
		end

		-- The farm sends LOOT_ALL itself; keep generic AutoLoot from closing this prompt with EXIT.
		tempTween(chest.Lid.CFrame, 170)
		local promptStart = tick()
		repeat
			task.wait(0.1)
			pcall(function()
				Prompt.interact(chest:FindFirstChildWhichIsA("ProximityPrompt"))
			end)
			pcall(function()
				tempTween(chest.Lid.CFrame, 170)
			end)
		until (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or not running or (tick() - promptStart > 15)

		local gui = playerGui()
		if not (gui and gui:FindFirstChild("ChoicePrompt")) then
			return
		end

		local time = tick()
		repeat
			task.wait()
			gui = playerGui()
			local cp = gui and gui:FindFirstChild("ChoicePrompt")
			if cp then
				pcall(function()
					cp:FindFirstChild("Choice"):FireServer("LOOT_ALL")
				end)
			end
		until not (gui and gui:FindFirstChild("ChoicePrompt")) or not running or (tick() - time >= 3)

		gui = playerGui()
		local cp = gui and gui:FindFirstChild("ChoicePrompt")
		if cp then
			pcall(function()
				cp:FindFirstChild("Choice"):FireServer("EXIT")
			end)
		end
		-- Intentionally NOT tweening back down to Y=0 -- stay at altitude after looting.
	end, debug.traceback)
	AutoLoot.ignore = previousAutoLootIgnore
	if not ok then
		error(err, 0)
	end
end

---Idol relief-from-flaws + weapon enchant (PR echo getechoes).
local function getEchoes()
	setStage("enchant / idol")

	local lp = localPlayer()
	local backpack = lp and lp:FindFirstChildOfClass("Backpack")
	local char = character()
	if not backpack or not char then
		return
	end
	local hum = humanoid()

	local function equipWeapon(weaponName)
		if not weaponName then
			return false
		end
		for _, tool in ipairs(backpack:GetChildren()) do
			if tool:IsA("Tool") and tool.Name:match(weaponName) then
				hum:EquipTool(tool)
				task.wait(0.1)
				tool:Activate()
				return true
			end
		end
		return false
	end

	-- Idol of Yun'Shul -> relief from flaws.
	local idol = backpack:FindFirstChild("Idol of Yun'Shul")
	if idol and running then
		hum:EquipTool(idol)
		task.wait(0.3)
		for _ = 1, 3 do
			idol:Activate()
			task.wait(0.1)
			if playerGui() and playerGui():FindFirstChild("ChoicePrompt") then
				break
			end
		end
		local prompt = playerGui() and playerGui():WaitForChild("ChoicePrompt", 5)
		if prompt and prompt:FindFirstChild("Choice") then
			prompt.Choice:FireServer("Give me relief from my Flaws.")
			local start = tick()
			repeat
				task.wait(0.1)
			until not (playerGui() and playerGui():FindFirstChild("ChoicePrompt")) or tick() - start > 5
		end
	end

	-- Enchant the main weapon.
	local enchantStone
	for _, tool in ipairs(backpack:GetChildren()) do
		if tool:IsA("Tool") and tool.Name:match("Enchant") then
			enchantStone = tool
			break
		end
	end

	if enchantStone and running then
		local weaponHolder = backpack:FindFirstChild("Weapon")
		local currentWeapon = weaponHolder and weaponHolder:FindFirstChild("Weapon") and weaponHolder.Weapon.Value
		pcall(function()
			replicatedStorage:WaitForChild("Requests"):WaitForChild("Unequip"):InvokeServer("Weapon", true)
		end)
		task.wait(0.5)

		equipWeapon(currentWeapon)

		hum:EquipTool(enchantStone)
		task.wait(0.5)
		enchantStone:Activate()

		local prompt = playerGui() and playerGui():WaitForChild("ChoicePrompt", 5)
		local choice = prompt and prompt:WaitForChild("Choice", 5)
		if choice then
			choice:FireServer(true)
			task.wait(1)
		end
	end

	-- Report whether the chest actually yielded enchant stones -- the run-dungeon flow uses this to
	-- decide between banking (wipe) and retrying for another chest.
	return enchantStone ~= nil
end

-- =========================================================================================================
-- State machine.
-- =========================================================================================================
local function isCharacterCreation()
	local cc = workspace:FindFirstChild("CharacterCreator")
	local c = character()
	return cc ~= nil and c ~= nil and c.Parent == cc
end

-- Ferryman-style auto log: throughout the entire farm, hop the moment another player comes within the
-- per-automation auto-log distance (adjustable 0-2000 in the menu; 0 = off). Saved per automation.
local function watchForPlayers()
	while running do
		task.wait(1)
		if not running then
			break
		end
		-- Don't hop mid-creation (lobby players would softlock the character creator).
		if isCharacterCreation() then
			continue
		end
		-- Never auto-log in Fragments of Self: it's the shared cash-in hub where other players are ALWAYS
		-- present, so proximity-hopping there just interrupts banking echoes over and over. Skip the area
		-- entirely regardless of the distance setting -- this is the "autologs in Fragments of Self" report.
		local area = currentArea()
		if area and tostring(area):match("Fragments of Self") then
			continue
		end
		local dist = AutoLog.get("echo_farm")
		if dist > 0 and playerCheck(dist) then
			serverHop()
			return
		end
	end
end

---Blow through the game's start / loading screen by firing Requests.StartMenu.Start until our character
---loads into workspace.Live. Skipped in character creation (that's its own flow). PR's framework fires this
---during init; luma has to do it per session since each cycle spans multiple joins.
---Tap a key once via VirtualInputManager (input-only; no remote).
local function pressKey(keyCode)
	pcall(function()
		local vim = Instance.new("VirtualInputManager")
		vim:SendKeyEvent(true, keyCode, false, game)
		vim:SendKeyEvent(false, keyCode, false, game)
	end)
end

local function requestStart()
	-- Blow through the loading screen by spamming A while the LoadingGui is up (input-only -- the old
	-- Requests.StartMenu.Start remote is an anticheat honeypot, firing it = instant ban). Wait for the
	-- character to spawn into workspace.Live. Skipped in character creation.
	local deadline = os.clock() + 25
	repeat
		if isCharacterCreation() then
			return
		end
		local c = character()
		if c and c.Parent and c.Parent.Name == "Live" then
			return
		end
		local pg = players.LocalPlayer and players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
		if pg and pg:FindFirstChild("LoadingGui") then
			pressKey(Enum.KeyCode.A)
		end
		task.wait(0.2)
	until not running or os.clock() >= deadline
end

local stateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "continuation", from = "_create_character", to = "_check_area" },
		{ name = "continuation", from = "_handle_fragments", to = "_check_area" },
		{ name = "die", from = "_check_area", to = "_die" },
		{ name = "die", from = "_run_dungeon", to = "_die" },
		{ name = "fragments", from = "_check_area", to = "_handle_fragments" },
		{ name = "cc", from = "_check_area", to = "_create_character" },
		{ name = "enter", from = "_check_area", to = "_enter_dungeon" },
		{ name = "run", from = "_check_area", to = "_run_dungeon" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")

			-- Merit / dungeon: we always have an existing character here, so it's safe to blow through the
			-- start/loading screen with StartMenu.Start before routing.
			if game.PlaceId == EASTERN_PLACE_ID then
				requestStart()
				return self:enter()
			end
			if game.PlaceId == DUNGEON_PLACE_ID then
				requestStart()
				return self:run()
			end

			-- Anywhere else (lobby / character creator / fragments / depths): DO NOT fire StartMenu.Start --
			-- that would rush the character creator and roll the wrong character. Wait patiently to classify.
			local deadline = os.clock() + 20
			repeat
				if isCharacterCreation() then
					return self:cc()
				end
				local area = currentArea()
				if area and tostring(area):match("Fragments of Self") then
					return self:fragments()
				end
				if area and tostring(area):match("The Depths") then
					return self:die()
				end
				task.wait()
			until os.clock() >= deadline or not running
		end,

		onenter_create_character = function(self)
			if not running then
				return
			end
			setStage("create character")
			struct:create_character()
			self:continuation()
		end,

		onenter_enter_dungeon = function(self)
			if not running then
				return
			end
			enterDungeon()
		end,

		onenter_run_dungeon = function(self)
			if not running then
				return
			end
			setStage("run dungeon")

			local startTime = tick()
			repeat
				task.wait(0.2)
			until (currentArea() and tostring(currentArea()):match("Detainment")) or not running

			task.wait(1)
			attachToTitus()

			-- Titus is down: re-arm the watchdog so the post-kill exit-wait + fly-up + loot/enchant each get
			-- a fresh ACTION_TIMEOUT. The "fighting titus" cap was armed back when the FIGHT started and is
			-- shorter (VOID_TIMEOUT); leaving it armed lets it expire mid-transition and wipe the run before
			-- the idol + enchant stones are used.
			setStage("boss defeated")

			-- Reset the 30s DungeonExitFinal cap to measure from the KILL, not the dungeon-run start, so a
			-- slow fight can't eat the window the run gets to wait for the exit to spawn.
			startTime = tick()

			local hum = humanoid()
			if hum then
				hum.Died:Connect(function()
					serverHop()
				end)
			end

			local finished = false
			local core = workspace:WaitForChild("DetainmentCore", 10)
			local conn
			if core then
				conn = core.ChildAdded:Connect(function(child)
					if child.Name == "DungeonExitFinal" then
						finished = true
					end
				end)
			end

			repeat
				task.wait(0.2)
				if tick() - startTime > 30 then
					if conn then
						conn:Disconnect()
					end
					serverHop()
					while task.wait() do
					end
					return
				end
			until finished or not running

			if conn then
				conn:Disconnect()
			end

			task.wait(0.5)

			-- Tear the pathfind breaker down before looting so velocity is normal for the chest interaction.
			stopTitusBreaker()

			-- Fly up out of the arena, then loot + enchant.
			local r = root()
			if r then
				r.CFrame = r.CFrame * CFrame.new(0, 1300, 0)
			end

			local gotEnchant = false
			xpcall(function()
				grabChest()
				gotEnchant = getEchoes() == true
			end, function(err)
				Logger.notify("EchoFarm loot error: %s", tostring(err))
			end)

			-- No enchant stones in the chest: do NOT wipe (that banks + resets the run for nothing). Rejoin
			-- to re-run the dungeon for another chest instead, keeping the character + its echoes. Only a run
			-- that actually pulled enchant stones proceeds to the wipe (banking at Fragments of Self).
			if not gotEnchant then
				setStage("no enchant stones -- retrying")
				serverHop()
				while task.wait() do
				end
				return
			end

			-- Count this run's echoes (request the score; the persistent listener folds it in) + bump cycle.
			recordCycle()

			task.wait(3.75)

			-- Wait out any lingering danger, then wipe (obliteration) to bank echoes at Fragments of Self.
			local hum2 = humanoid()
			if hum2 and hum2:GetAttribute("DangerExpiration") and hum2:GetAttribute("DangerExpiration") > 0 then
				repeat
					task.wait()
				until not (hum2:GetAttribute("DangerExpiration") and hum2:GetAttribute("DangerExpiration") > 0)
					or not running
			end

			self:die()
		end,

		onenter_handle_fragments = function(self)
			if not running then
				return
			end
			setStage("fragments cash-in")

			local self_npc
			local deadline = os.clock() + 40
			repeat
				local npcs = workspace:FindFirstChild("NPCs")
				self_npc = npcs and npcs:FindFirstChild("Self")
				task.wait()
			until self_npc or os.clock() >= deadline or not running
			if not self_npc then
				serverHop()
				return
			end

			-- Count this run once via the persistent listener, then interact to finalize.
			recordCycle()

			local tpLocation = (self_npc:GetPivot() - Vector3.new(0, 15.7, 0))
				* CFrame.Angles(math.rad(180), math.rad(90), math.rad(180))

			-- No auto-log here: the cash-in happens IN Fragments of Self, a shared hub that's always full of
			-- other players, so a proximity hop would abort the bank-in on practically every run. Just cash in.

			local sendDialogue = replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue")
			-- NPCs expose the prompt either as a child named "InteractPrompt" or just a ProximityPrompt.
			local prompt = self_npc:FindFirstChild("InteractPrompt")
				or self_npc:FindFirstChildWhichIsA("ProximityPrompt", true)

			-- True while Self's dialogue window is up.
			local function dialogueOpen()
				local gui = playerGui()
				local dlg = gui and gui:FindFirstChild("DialogueGui")
				return dlg ~= nil and dlg.Enabled ~= false
			end

			-- Advance Self's dialogue by firing the choices it ACTUALLY presents. Each choice button carries
			-- a "ChoiceID" attribute -- that ID is what the game sends to the server, NOT the display text --
			-- so the old hardcoded "[The End]" string silently matched nothing once the dialogue changed.
			-- Fire every non-exit choice the live dialogue offers (the cash-in is short, so this walks it to
			-- the end); fall back to the old string if no choices are readable.
			local function advanceDialogue()
				local gui = playerGui()
				local scroll = gui and gui:FindFirstChild("DialogueGui")
				scroll = scroll and scroll:FindFirstChild("DialogueFrame")
				scroll = scroll and scroll:FindFirstChild("DialogueContainer")
				scroll = scroll and scroll:FindFirstChild("ChoiceSheet")
				scroll = scroll and scroll:FindFirstChild("ChoiceScroll")
				local firedAny = false
				if scroll then
					for _, choice in ipairs(scroll:GetChildren()) do
						local id = choice:GetAttribute("ChoiceID")
						if id ~= nil and id ~= "EXIT" then
							pcall(function()
								sendDialogue:FireServer({ choice = id })
							end)
							firedAny = true
							task.wait(0.15)
						end
					end
				end
				if not firedAny then
					pcall(function()
						sendDialogue:FireServer({ choice = "[The End]" })
					end)
				end
			end

			local start = tick()
			repeat
				local r = root()
				if r then
					r.CFrame = tpLocation
				end
				-- Open the dialogue: press the interact key like a human, and if it still isn't up, force the
				-- prompt directly (distance/LOS-independent) so bad positioning can't block the cash-in.
				if prompt then
					Prompt.interact(prompt)
					if not dialogueOpen() then
						Prompt.fire(prompt)
					end
				end
				if dialogueOpen() then
					advanceDialogue()
				end
				task.wait(0.25)
			until isCharacterCreation() or not (currentArea() and tostring(currentArea()):match("Fragments of Self")) or not running or (tick() - start > 20)

			self:continuation()
		end,

		onenter_die = function(self)
			if not running then
				return
			end
			setStage("wipe")
			local slot = currentSlot() or (PersistentData.get("efdata") and PersistentData.get("efdata").slot)
			pcall(function()
				Wipe.invoke(slot)
			end)
		end,
	},
})

-- =========================================================================================================
-- Struct.
-- =========================================================================================================
local function buildStruct()
	return AutomationStruct.construct({
		id = "echo_titus",
		state_machine = stateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"fly",
			"auto_loot",
			"auto_equip_weapon",
		},
		character_creator_handler_used = true,
		character_creator_handler_opts = {
			origin = "Merit",
			-- Select the Merit spawn (Authority Ensign origin), verified against DataReplication.Origin. If it
			-- doesn't apply within 10s, server-hop and retry on a fresh server instead of kicking the player.
			origin_button = {
				category = "Authority Ensign",
				spawn = "Merit",
				timeout = 10,
				on_fail = function()
					serverHop()
				end,
			},
			weapon = "Sword",
			-- "All" enables every meta modifier; then toggle "OneBit" (the can't-swim flaw) back off.
			modifiers = { "All", "OneBit" },
		},
	})
end

-- =========================================================================================================
-- Layer 2 (Chaser) echo farm -- a luma port of project-rain-oss's `auto_echo_layer2.lua`. Reuses every
-- helper above (overlay, stats, watchdog, score listener, fragments cash-in, wipe, server-hop safety); only
-- the route differs: dive into the void -> key/door -> bonekeeper -> generator -> chaser -> void it -> wipe.
--
-- The chaser kill uses luma's own void path: EchoFarm.voiding = true makes OwnershipWatcher own the chaser
-- (instead of dropping it like the trash mobs) and runs Fling on it -- the pre-wired `.voiding`
-- hooks in Exploits / OwnershipWatcher -- and we fling its owned root up past the destroy height.
--
-- NOTE: the waypoint CFrames below are PR's and are dungeon-layout-specific; if Deepwoken moves the Layer 2
-- geometry they'll need re-capturing. The chaser-void physics can't be bench-tested here, so expect to tune.
-- =========================================================================================================
local L2_BONEKEEPER = CFrame.new(-5747, 459, -6357)
local L2_BONEKEEPER_APPROACH = CFrame.new(-5889, 459, -6308)
local L2_BONEKEEPER_WATCH = CFrame.new(-5788, 563, -6351)
local L2_GENERATOR = CFrame.new(-5555, 529, -6475)
local L2_CHASER_HIGH = CFrame.new(-5361, 5000, -4801)
local L2_CHASER_DOWN = CFrame.new(-5361, 285, -4801)
local L2_CHASER_ANGLE = CFrame.new(-5224.36523, 194.26561, -4633.03223, -0.803056717, 0, -0.595902622, 0, 1, 0, 0.595902622, 0, -0.803056717)
local L2_VOID_Y = 2500 -- chaser root above this = voided.

---Fire Requests.SendDialogue with a choice (or exit), matching PR's send_dialogue.
local function sendDialogue(textOrNil, exit)
	pcall(function()
		local send = replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue")
		if exit then
			send:FireServer({ exit = true })
		else
			send:FireServer({ choice = textOrNil })
		end
	end)
	if not exit then
		task.wait(0.5)
	end
end

---Disable + forget a struct feature mid-run (same pattern EchoFarm uses to drop mob_ai_breaker before loot).
local function disableStructFeature(name)
	pcall(function()
		local feat = struct and struct.active_features and struct.active_features[name]
		if feat then
			feat:disable()
			struct.active_features[name] = nil
		end
	end)
end

local function liveChildren()
	local live = workspace:FindFirstChild("Live")
	return live and live:GetChildren() or {}
end

local function nearestKillPlane()
	local r = root()
	if not r then
		return nil
	end
	local best, bestDist = nil, math.huge
	for _, item in ipairs(game:GetService("CollectionService"):GetTagged("KillPlane")) do
		if item:IsA("BasePart") and item:IsDescendantOf(workspace) then
			local d = (item.Position - r.Position).Magnitude
			if d < bestDist then
				best, bestDist = item, d
			end
		end
	end
	return best
end

local function inLayer2()
	local lp = localPlayer()
	local dungeon = lp and lp:GetAttribute("Dungeon")
	if dungeon and tostring(dungeon):match("Layer2") then
		return true
	end
	local area = currentArea()
	return area ~= nil and tostring(area):match("Layer2") ~= nil
end

---Dive into the void so the server routes us into Layer 2: drop kill-brick immunity + fly so we actually
---fall, then slam downward velocity into the nearest kill plane until the area flips to Layer 2.
local function enterVoid()
	if currentArea() and tostring(currentArea()):match("Fragments of Self") then
		return
	end
	setStage("entering the void")
	disableStructFeature("no_kill_bricks")
	disableStructFeature("fly")

	local startedAt = tick()
	local plane = nearestKillPlane()
	repeat
		plane = nearestKillPlane()
		task.wait()
	until plane or tick() - startedAt > 15 or not running or inLayer2()

	while running and tick() - startedAt < 60 do
		if inLayer2() then
			break
		end
		if playerCheck(300) then
			serverHop()
			while task.wait() do
			end
			return
		end
		local r = root()
		if r then
			r.AssemblyLinearVelocity = Vector3.new(0, -999, 0)
		end
		if plane and plane.Parent then
			-- Void physics need the full dive speed (slowing this broke the dive); keep it at 200 even though
			-- the L2 travel tweens are slower.
			setSpeed(200)
			Tweening.goal(MOVE_ID, plane.CFrame, false)
		else
			plane = nearestKillPlane()
		end
		task.wait()
	end
	Tweening.stop(MOVE_ID)
end

---Tween to an NPC under workspace.NPCs, fire its prompt until the dialogue opens, then pick `choice` (if any)
---and/or exit. Shared by the key/door/generator steps.
local function tweenToNpcAndTalk(npcName, choice, exitAfter)
	local npc
	local findStart = tick()
	repeat
		local npcs = workspace:FindFirstChild("NPCs")
		npc = npcs and npcs:FindFirstChild(npcName)
		task.wait()
	until npc or tick() - findStart > 20 or not running
	if not npc then
		return false
	end

	local start = tick()
	repeat
		pcall(function()
			tempTween(npc:GetPivot(), 150)
		end)
		local prompt = npc:FindFirstChild("InteractPrompt")
		if prompt then
			Prompt.interact(prompt)
		end
		task.wait(0.5)
		local gui = playerGui()
		if gui and gui:FindFirstChild("DialogueGui") and gui.DialogueGui.Enabled then
			break
		end
	until tick() - start > 20 or not running

	if choice then
		sendDialogue(choice, false)
	end
	if exitAfter then
		sendDialogue(nil, true)
	end
	return true
end

local function getKey()
	setStage("key / door")
	tweenToNpcAndTalk("TheKey", nil, true)
	tweenToNpcAndTalk("TheDoor", nil, true)
end

---Bonekeeper encounter: enable VoidMobs (clears trash mobs), wait for the keeper to spawn + its bridge
---barrier to drop (PR spawn_keeper).
local function spawnKeeper()
	setStage("bonekeeper")
	tempTween(L2_BONEKEEPER, 150)
	pcall(function()
		if Toggles and Toggles.VoidMobs then
			Toggles.VoidMobs:SetValue(true)
		end
	end)

	local keeper
	local startedAt = tick()
	repeat
		if not keeper then
			pcall(function()
				tempTween(L2_BONEKEEPER_APPROACH, 100)
			end)
		end
		for _, ent in next, liveChildren() do
			if ent ~= character() and ent.Name:find("%.boneboy") then
				keeper = ent
			end
		end
		task.wait()
	until keeper or tick() - startedAt > 40 or not running

	-- Wait for the boneboy to disappear (bridge barrier drops), hovering 100 studs directly above it the whole
	-- time. Tweened toward keeper.Position + 100Y every frame (tweening both axes is anticheat-safe); once the
	-- keeper is gone we just hold and keep watching the barrier.
	local bridgeStart = tick()
	repeat
		if keeper and keeper.Parent then
			local kp = keeper:GetPivot().Position
			setSpeed(150)
			Tweening.goal(MOVE_ID, CFrame.new(kp.X, kp.Y + 100, kp.Z), false)
		end
		task.wait()
		local triggers = workspace:FindFirstChild("EncounterTriggers")
		local bridge = triggers and (triggers:FindFirstChild("BonekeeperBridge") or triggers:FindFirstChild("BoneKeeperBridge"))
		if not bridge or not bridge:FindFirstChild("Barrier") then
			break
		end
	until tick() - bridgeStart > 40 or not running
	Tweening.stop(MOVE_ID)
end

---Restart the generator (PR go_to_generator), then stop clearing trash mobs.
local function goToGenerator()
	setStage("generator")
	local start = tick()
	repeat
		pcall(function()
			tempTween(L2_GENERATOR, 150)
		end)
		task.wait(0.5)
		pcall(function()
			local npcs = workspace:FindFirstChild("NPCs")
			local gen = npcs and npcs:FindFirstChild("TheGenerator")
			if gen and gen:FindFirstChild("InteractPrompt") then
				Prompt.interact(gen.InteractPrompt)
			end
		end)
		local gui = playerGui()
		if gui and gui:FindFirstChild("DialogueGui") and gui.DialogueGui.Enabled then
			break
		end
	until tick() - start > 20 or not running

	sendDialogue("[Restart it]", false)
	sendDialogue(nil, true)
	pcall(function()
		if Toggles and Toggles.VoidMobs then
			Toggles.VoidMobs:SetValue(false)
		end
	end)
end

local function drawWeapon()
	pcall(function()
		local char = character()
		if char and char:FindFirstChild("CharacterHandler") then
			char.CharacterHandler.Requests.DrawWeapon:FireServer(true)
		end
	end)
end

---Find + engage the chaser (PR chaser_route). Returns the chaser model (or nil).
local function chaserRoute()
	setStage("finding chaser")
	tempTween(L2_CHASER_HIGH, 150)

	local chaser
	local startedAt = tick()
	repeat
		pcall(function()
			tempTween(L2_CHASER_DOWN, 150)
		end)
		for _, ent in next, liveChildren() do
			if ent ~= character() and ent.Name:find("chaser") then
				chaser = ent
				break
			end
		end
		if not chaser then
			pcall(function()
				tempTween(L2_CHASER_ANGLE, 150)
			end)
		end
		task.wait()
	until chaser or tick() - startedAt > 40 or not running
	if not chaser then
		return nil
	end

	-- Last approach before the fight. The anticheat flags HORIZONTAL (X/Z) position snaps but not VERTICAL
	-- ones, so horizontal travel must be tweened and only Y may be snapped. Snap UP to Y=20000, TWEEN
	-- horizontally to directly above the chaser at that altitude, then snap straight DOWN onto it.
	do
		local r = root()
		if r then
			r.CFrame = CFrame.new(r.Position.X, 20000, r.Position.Z)
		end
		local cp = chaser:GetPivot().Position
		tempTween(CFrame.new(cp.X, 20000, cp.Z), 150)
		r = root()
		if r then
			-- Vertical-only snap down onto the chaser (keep our tweened X/Z, drop Y to the chaser's).
			r.CFrame = CFrame.new(r.Position.X, chaser:GetPivot().Position.Y, r.Position.Z)
		end
	end

	local talkStart = tick()
	repeat
		-- Hold on the chaser by TWEENING (never a horizontal snap) while we fire the prompt.
		pcall(function()
			tempTween(chaser:GetPivot(), 150)
		end)
		local prompt = chaser:FindFirstChild("InteractPrompt")
		if prompt then
			Prompt.interact(prompt)
		end
		task.wait(0.5)
		local gui = playerGui()
		if gui and gui:FindFirstChild("DialogueGui") and gui.DialogueGui.Enabled then
			break
		end
	until tick() - talkStart > 20 or not running

	drawWeapon()
	-- PR's dialogue chain that starts the fight.
	sendDialogue("Ethiron's Wake?", false)
	sendDialogue("What happened here?", false)
	sendDialogue("They mutinied?", false)
	sendDialogue("The City?", false)
	return chaser
end

---Void the chaser: EchoFarm.voiding engages luma's chaser hooks (own-not-drop + Fling), we extend
---our simulation radius + fling its owned root up, and orbit it to keep it owned. Done when it's gone or
---flung past L2_VOID_Y.
local function voidChaser(chaser)
	if not chaser then
		return
	end
	setStage("voiding chaser")
	EchoFarm.voiding = true
	pcall(function()
		sethiddenproperty(localPlayer(), "MaxSimulationRadius", 5000)
		sethiddenproperty(localPlayer(), "SimulationRadius", 5000)
	end)

	local startedAt = tick()
	while running and chaser.Parent do
		drawWeapon()
		local hrp = chaser:FindFirstChild("HumanoidRootPart")
		if hrp then
			if hrp.Position.Y > L2_VOID_Y then
				break
			end
			-- Orbit just above its root to keep it owned + in range (void physics -- keep full speed)...
			setSpeed(200)
			Tweening.goal(MOVE_ID, CFrame.new(hrp.Position) * CFrame.new(0, 6, 0), false)
			-- ...and fling it straight up (works once we're its network owner; harmless otherwise).
			pcall(function()
				hrp.AssemblyLinearVelocity = Vector3.new(0, 12500, 0)
			end)
		end
		if tick() - startedAt > ACTION_TIMEOUT then
			break
		end
		task.wait()
	end

	Tweening.stop(MOVE_ID)
	EchoFarm.voiding = false
end

-- Layer 2 state machine. Mirrors the Titus one's shared states (check_area / create_character / fragments /
-- die), but routes by Layer 2 geography and runs the void + chaser route instead of the Titus dungeon.
local l2StateMachine = StateMachine.create({
	initial = "idle",
	events = {
		{ name = "start", from = "idle", to = "_check_area" },
		{ name = "continuation", from = "_create_character", to = "_check_area" },
		{ name = "continuation", from = "_handle_fragments", to = "_check_area" },
		{ name = "continuation", from = "_enter_void", to = "_check_area" },
		{ name = "die", from = "_check_area", to = "_die" },
		{ name = "die", from = "_run_void", to = "_die" },
		{ name = "fragments", from = "_check_area", to = "_handle_fragments" },
		{ name = "cc", from = "_check_area", to = "_create_character" },
		{ name = "enter_void", from = "_check_area", to = "_enter_void" },
		{ name = "run_void", from = "_check_area", to = "_run_void" },
	},
	callbacks = {
		onenter_check_area = function(self)
			if not running then
				return
			end
			setStage("check area")

			-- Blow through the start/loading screen so the character actually spawns before we classify
			-- (skipped automatically during character creation so we don't rush the creator).
			if not isCharacterCreation() then
				requestStart()
			end

			local deadline = os.clock() + 25
			repeat
				if isCharacterCreation() then
					return self:cc()
				end
				if inLayer2() then
					return self:run_void()
				end
				local area = currentArea()
				if area and tostring(area):match("Fragments of Self") then
					return self:fragments()
				end
				-- Have a spawned character in the overworld (not creating, not in Layer 2, not at Fragments)
				-- -> dive into the void. Gate on the character being in Live, NOT on CurrentArea being set:
				-- right after creation the area attribute is often still nil, which previously left this
				-- stuck here (never diving) until it timed out.
				local c = character()
				if c and c.Parent and c.Parent.Name == "Live" then
					return self:enter_void()
				end
				task.wait()
			until os.clock() >= deadline or not running
		end,

		onenter_create_character = function(self)
			if not running then
				return
			end
			setStage("create character")
			struct:create_character()
			self:continuation()
		end,

		onenter_enter_void = function(self)
			if not running then
				return
			end
			enterVoid()
			self:continuation()
		end,

		onenter_run_void = function(self)
			if not running then
				return
			end
			setStage("run layer 2")

			local startTime = tick()
			repeat
				task.wait(0.2)
			until inLayer2() or not running or tick() - startTime > 30

			getKey()
			spawnKeeper()
			goToGenerator()
			local chaser = chaserRoute()
			voidChaser(chaser)

			recordCycle()
			task.wait(2)
			self:die()
		end,

		onenter_handle_fragments = function(self)
			if not running then
				return
			end
			setStage("fragments cash-in")

			local self_npc
			local deadline = os.clock() + 40
			repeat
				local npcs = workspace:FindFirstChild("NPCs")
				self_npc = npcs and npcs:FindFirstChild("Self")
				task.wait()
			until self_npc or os.clock() >= deadline or not running
			if not self_npc then
				serverHop()
				return
			end

			recordCycle()

			local tpLocation = (self_npc:GetPivot() - Vector3.new(0, 15.7, 0))
				* CFrame.Angles(math.rad(180), math.rad(90), math.rad(180))

			if shouldLogHop(tpLocation.Position) then
				serverHop()
				while task.wait() do
				end
				return
			end

			local sendDlg = replicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue")
			local prompt = self_npc:WaitForChild("InteractPrompt", 10)

			local start = tick()
			repeat
				local r = root()
				if r then
					r.CFrame = tpLocation
				end
				if prompt then
					Prompt.interact(prompt)
				end
				pcall(function()
					sendDlg:FireServer({ choice = "[The End]" })
				end)
				task.wait(0.25)
			until isCharacterCreation() or not (currentArea() and tostring(currentArea()):match("Fragments of Self")) or not running or (tick() - start > 20)

			self:continuation()
		end,

		onenter_die = function(self)
			if not running then
				return
			end
			setStage("wipe")
			local slot = currentSlot() or (PersistentData.get("efdata") and PersistentData.get("efdata").slot)
			pcall(function()
				Wipe.invoke(slot)
			end)
		end,
	},
})

local function buildL2Struct()
	return AutomationStruct.construct({
		id = "echo_layer2",
		state_machine = l2StateMachine,
		is_running = isRunning,
		features = {
			"no_fall",
			"noclip",
			"fly",
			"no_kill_bricks",
			"mob_ai_breaker",
			"auto_equip_weapon",
		},
		character_creator_handler_used = true,
		character_creator_handler_opts = {
			-- PR's throwaway Layer 2 character: Diluvian Mechanism origin, every meta modifier on.
			origin = "DiluvianMechanism",
			-- Select the origin via the real UI button (click until selected, kick if it never takes).
			-- DiluvianMechanism lives under the Deepbound origin category.
			origin_button = {
				category = "Deepbound",
				spawn = "DiluvianMechanism",
				timeout = 10,
				kick_message = "Need diluvian mechanism origin",
			},
			modifiers = { "All" },
		},
	})
end

-- =========================================================================================================
-- Public interface.
-- =========================================================================================================
function EchoFarm.start()
	local lp = localPlayer()
	if not lp then
		return
	end
	local data = PersistentData.get("efdata")
	if not data or not data.slot then
		return
	end
	if running then
		return
	end

	running = true
	buildOverlay()
	setStage("starting")
	AntiAFK.start("EchoFarm")

	maid:mark(task.spawn(runStats))

	-- Per-action 60s watchdog: wipe-reset the cycle if a stage stalls.
	maid:mark(task.spawn(runActionWatchdog))

	-- Ferryman-style auto log: hop if any player comes within 1000 studs.
	maid:mark(task.spawn(watchForPlayers))

	-- Persistent echo counter for this session.
	connectScoreListener()

	-- Layer 2 echo farm was removed -- only the Titus farm runs now (force it even if stale efdata says Layer2).
	local sm = stateMachine
	sm.current = "idle"
	sm.asyncState = StateMachine.NONE
	sm.currentTransitioningEvent = nil

	struct = buildStruct()
	struct:run()
end

function EchoFarm.invoke(mode)
	local lp = localPlayer()
	if not lp then
		return
	end
	if running then
		return
	end

	local slot = currentSlot()
	if not slot then
		return Logger.notify("EchoFarm: no data slot found.")
	end

	-- Fresh run stats. Layer 2 echo farm was removed -- always Titus regardless of the passed mode.
	PersistentData.set("efdata", {
		slot = slot,
		mode = "Titus",
		startedAt = os.time(),
		echoes = 0,
		cycles = 0,
	})

	-- Wipe the current character on start; the wipe teleports us out, and Luma's resume (efdata) brings us
	-- back into a fresh farm cycle (character creation -> enter -> fight -> ...).
	pcall(function()
		Wipe.invoke(slot)
	end)
end

function EchoFarm.stop()
	if not running then
		return
	end
	running = false

	-- Clear the chaser-void flag so the Exploits / OwnershipWatcher hooks don't keep running after a stop.
	EchoFarm.voiding = false
	stopTitusBreaker()

	if struct then
		pcall(function()
			struct:stop()
		end)
		struct = nil
	end

	Tweening.stop(MOVE_ID)

	pcall(function()
		AntiAFK.stop("EchoFarm")
	end)

	maid:clean()
	getScoreConn = nil
	destroyOverlay()

	PersistentData.set("efdata", nil)
end

return EchoFarm

end)
__bundle_register("@luma/Features/Automation/FishFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
local FishFarm = {}

---@module Game.AntiAFK
local AntiAFK = require("@luma/Game/AntiAFK")

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Utility.Signal
local Signal = require("@luma/Utility/Signal")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module Utility.Configuration
local Configuration = require("@luma/Utility/Configuration")

local players = game:GetService("Players")
local runService = game:GetService("RunService")

local renderStepped = Signal.new(runService.RenderStepped)

local fishFarmMaid = Maid.new()

local fishFarmTimestamp = os.clock()

local wasActivated = false

local updateFishFarm = LPH_NO_VIRTUALIZE(function()
	if os.clock() - fishFarmTimestamp < 0.1 then
		return
	end

	fishFarmTimestamp = os.clock()

	AntiAFK.stop("FishFarm")

	if not Configuration.expectToggleValue("AutoFish") then
		return
	end

	AntiAFK.start("FishFarm")

	local localPlayer = players.LocalPlayer
	local localPlayerCharacter = localPlayer.Character
	if not localPlayerCharacter then
		return
	end

	local humanoid = localPlayerCharacter:FindFirstChild("Humanoid")
	if not humanoid then
		return
	end

	local backpack = localPlayer:FindFirstChild("Backpack")
	if not backpack then
		return
	end

	local characterRod = localPlayerCharacter:FindFirstChild("Fishing Rod")
	local backpackRod = backpack:FindFirstChild("Fishing Rod")

	if not characterRod then
		return backpackRod and humanoid:EquipTool(backpackRod)
	end

	local handle = characterRod:FindFirstChild("Handle")
	local rod = handle and handle:FindFirstChild("Rod")
	local bobby = rod and rod:FindFirstChild("bobby")
	if not bobby then
		return
	end

	local addBait = characterRod:FindFirstChild("AddBait")
	if not addBait then
		return
	end

	---@todo: add fish meat lol
	local baitTable = {
		"Plumfruit",
		"Pomar",
		"Gobletto",
		"Squid",
		"Dentifilo",
		"Seaweed Bundle",
		"Urchin",
		"Browncap",
		"Chum",
		"Calabash",
		"Pufferfish",
		"Redd",
	}

	for _, baitName in next, baitTable do
		local bait = backpack:FindFirstChild(baitName)
		if not bait then
			continue
		end

		if bobby:FindFirstChild("bait") then
			break
		end

		return addBait:FireServer(bait)
	end

	local hook = bobby:FindFirstChild("hook")
	if not hook then
		return
	end

	if hook.Transparency ~= 1.0 then
		wasActivated = not wasActivated
		return wasActivated and characterRod:Deactivate() or characterRod:Activate()
	end

	local inputUpdate = characterRod:FindFirstChild("InputUpdate")
	if not inputUpdate then
		return
	end

	local playerGui = localPlayer:FindFirstChild("PlayerGui")
	if not playerGui then
		return
	end

	local fishingGui = playerGui:FindFirstChild("FishingGui")
	if not fishingGui or not fishingGui.Enabled then
		return
	end

	local mainFrame = fishingGui:FindFirstChild("MainFrame")
	if not mainFrame then
		return
	end

	local holdA = mainFrame:FindFirstChild("HoldA")
	local holdS = mainFrame:FindFirstChild("HoldS")
	local holdD = mainFrame:FindFirstChild("HoldD")
	if not holdA or not holdS or not holdD then
		return
	end

	inputUpdate:FireServer({
		a = holdA.Visible,
		s = holdS.Visible,
		d = holdD.Visible,
	})
end)

function FishFarm.init()
	fishFarmMaid:add(renderStepped:connect("FishFarm_RenderStepped", updateFishFarm))

	if not LPH_OBFUSCATED or shared.Luma.verbose then
		Logger.warn("Fish Farm initialized.")
	end
end

function FishFarm.detach()
	fishFarmMaid:clean()

	Logger.warn("Fish Farm detached.")
end

return FishFarm

end)
__bundle_register("@luma/Features/Automation/InteligenceFarm", function(require, _LOADED, __bundle_register, __bundle_modules)
local InteligenceFarm = {}

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Utility.Signal
local Signal = require("@luma/Utility/Signal")

---@module Utility.Attributes
local Attributes = require("@luma/Utility/Attributes")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module Utility.Throttle
local throttle = require("@luma/Utility/Throttle")

local players = game:GetService("Players")
local runService = game:GetService("RunService")

local renderStepped = Signal.new(runService.RenderStepped)

local autoIntelligenceMaid = Maid.new()

local updateInteligence = LPH_NO_VIRTUALIZE(function()
	local inteligenceFarm = Toggles["AutoIntelligence"]
	if not inteligenceFarm or not inteligenceFarm.Value then
		return
	end

	local inteligenceFarmCap = Options["IntelligenceCap"]
	if not inteligenceFarmCap then
		return
	end

	local localPlayer = players.LocalPlayer
	local localPlayerCharacter = localPlayer.Character
	if not localPlayerCharacter then
		return
	end

	if not Attributes.isNotAtCap(localPlayerCharacter, "Stat_Intelligence", inteligenceFarmCap.Value - 1) then
		Logger.longNotify("Intelligence AutoFarm is automatically stopping.")
		return inteligenceFarm:SetValue(false)
	end

	local humanoid = localPlayerCharacter:FindFirstChild("Humanoid")
	if not humanoid then
		return
	end

	local backpack = localPlayer:FindFirstChild("Backpack")
	if not backpack then
		return
	end

	local characterBook = localPlayerCharacter:FindFirstChild("Math Textbook")
	local backpackBook = backpack:FindFirstChild("Math Textbook")

	if not characterBook and backpackBook then
		return humanoid:EquipTool(backpackBook)
	end

	local choicePrompt = localPlayer.PlayerGui:FindFirstChild("ChoicePrompt")
	if not choicePrompt then
		return characterBook and characterBook:Activate()
	end

	local choiceRemote = choicePrompt:FindFirstChild("Choice")
	if not choiceRemote then
		return
	end

	local choiceFrame = choicePrompt:FindFirstChild("ChoiceFrame")
	if not choiceFrame then
		return
	end

	local descSheet = choiceFrame:FindFirstChild("DescSheet")
	local description = descSheet and descSheet:FindFirstChild("Desc")
	if not description then
		return
	end

	local options = choiceFrame:FindFirstChild("Options")
	if not options then
		return
	end

	local answers = {}

	for _, instance in next, options:GetChildren() do
		if not instance:IsA("TextButton") then
			continue
		end

		local number = tonumber(instance.Name)
		if not number then
			continue
		end

		table.insert(answers, number)
	end

	local descriptionText = tostring(description.Text)
	local parsedDescription = descriptionText:gsub("What is", ""):gsub(" ", ""):gsub("?", ""):gsub("by", "")

	local operation = nil

	if parsedDescription:match("divided") then
		operation = "divided"
	end

	if parsedDescription:match("times") then
		operation = "times"
	end

	if parsedDescription:match("plus") then
		operation = "plus"
	end

	if parsedDescription:match("minus") then
		operation = "minus"
	end

	if not operation then
		return
	end

	local parsedNumbers = parsedDescription:split(operation)
	local firstNumber = tonumber(parsedNumbers[1] or "")
	local secondNumber = tonumber(parsedNumbers[2] or "")
	if not firstNumber or not secondNumber then
		return
	end

	local answer = nil

	if operation == "divided" then
		answer = firstNumber / secondNumber
	end

	if operation == "times" then
		answer = firstNumber * secondNumber
	end

	if operation == "plus" then
		answer = firstNumber + secondNumber
	end

	if operation == "minus" then
		answer = firstNumber - secondNumber
	end

	local closestAnswer = nil
	local closestDifference = nil

	for _, possible in next, answers do
		local delta = math.abs(answer - possible)

		if closestDifference and delta > closestDifference then
			continue
		end

		closestAnswer = possible
		closestDifference = delta
	end

	if not closestAnswer then
		return
	end

	choiceRemote:FireServer(tostring(closestAnswer))
end)

function InteligenceFarm.init()
	autoIntelligenceMaid:add(renderStepped:connect("AttributeFarmIntelligence_OnPreRender", throttle(1 / 10, updateInteligence)))

	if not LPH_OBFUSCATED or shared.Luma.verbose then
		Logger.warn("Inteligence Farm initialized.")
	end
end

function InteligenceFarm.detach()
	autoIntelligenceMaid:clean()

	Logger.warn("Inteligence Farm detached.")
end

return InteligenceFarm

end)
__bundle_register("@luma/Features/Automation/Objects/AutoLog", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AutoLog: per-automation auto-log (server-hop-when-a-player-is-near) distance store. Saved to disk per
-- automation id -- deliberately NOT part of luma's config saves, so the distance is a persistent per-
-- automation setting that survives config switches and rejoins. The menu sliders in AutomationTab read/write
-- it here; the automations (AutomationFeatures.auto_log + AutoTitus/EchoFarm/AutoFerryman watchers) read it.
local AutoLog = {}

---@module Utility.Filesystem
local Filesystem = require("@luma/Utility/Filesystem")

---@module Utility.JSON
local JSON = require("@luma/Utility/JSON")

local storage = Filesystem.new("Luma/Automation")
local FILE = "autolog.json"

-- Default range preserves the old hardcoded behaviour (1000 studs) for any automation never adjusted.
AutoLog.DEFAULT = 1000

local cache = nil

local function load()
	if cache then
		return cache
	end
	local data
	pcall(function()
		if storage:file(FILE) then
			local ok, decoded = pcall(JSON.decode, storage:read(FILE))
			if ok and type(decoded) == "table" then
				data = decoded
			end
		end
	end)
	cache = data or {}
	return cache
end

---Current auto-log distance for an automation id (DEFAULT if never set).
---@param id string?
---@return number
function AutoLog.get(id)
	if id == nil then
		return AutoLog.DEFAULT
	end
	local v = load()[tostring(id)]
	if type(v) ~= "number" then
		return AutoLog.DEFAULT
	end
	return v
end

---Persist a new auto-log distance for an automation id (writes to disk immediately).
---@param id string
---@param distance number
function AutoLog.set(id, distance)
	if id == nil then
		return
	end
	local c = load()
	c[tostring(id)] = tonumber(distance) or AutoLog.DEFAULT
	pcall(function()
		storage:write(FILE, JSON.encode(c))
	end)
end

return AutoLog

end)
__bundle_register("@luma/Features/Automation/Objects/AutoLootOptions", function(require, _LOADED, __bundle_register, __bundle_modules)
