__bundle_register("@luma/Features/Automation/Objects/AutomationFeatures", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AutomationFeatures: luma-native implementations of project-rain-oss's feature system, used by
-- AutomationStruct. Each feature is created with `AutomationFeatures.create(name, struct)` and exposes
-- `:enable()`, `:disable()`, and (where relevant) `.current_connection`, matching how the PR task files
-- reach into `struct.active_features['mob_ai_breaker'].current_connection`.
--
-- Per the port decision: features that luma already ships as menu toggles (fly, noclip, no_fall, auto_loot)
-- just drive those toggles (captured + restored). The rest (mob_ai_breaker, jesus, no_one_bit,
-- auto_equip_weapon) are implemented natively here, faithful to PR's behavior.
local AutomationFeatures = {}

---@module Game.InputClient
local InputClient = require("@luma/Game/InputClient")

---@module Game.ServerHop
local ServerHop = require("@luma/Game/ServerHop")

---@module GUI.Library
local Library = require("@luma/GUI/Library")

---@module Utility.Finder
local Finder = require("@luma/Utility/Finder")

---@module Features.Automation.Objects.AutoLog
local AutoLog = require("@luma/Features/Automation/Objects/AutoLog")

local players = game:GetService("Players")
local runService = game:GetService("RunService")
local replicatedStorage = game:GetService("ReplicatedStorage")

local EASTERN_PLACE_ID = 6473861193
local TITUS_PLACE_ID = 8668476218

-- Cached require of the game's EffectReplicator (HasEffect / FindEffect / CreateEffect / .Passives).
local effectReplicator = nil
local function getER()
	if effectReplicator then
		return effectReplicator
	end
	pcall(function()
		effectReplicator = require(replicatedStorage:WaitForChild("EffectReplicator"))
		if effectReplicator and effectReplicator.WaitForContainer then
			pcall(function()
				effectReplicator:WaitForContainer()
			end)
		end
	end)
	return effectReplicator
end

local function char()
	return players.LocalPlayer and players.LocalPlayer.Character
end

local function root()
	local c = char()
	return c and c:FindFirstChild("HumanoidRootPart")
end

-- ---------------------------------------------------------------------------------------------------------
-- Toggle-mapped features. enable() captures the user's current value then forces true; disable() restores.
-- ---------------------------------------------------------------------------------------------------------

---@param toggleName string
local function makeToggleFeature(toggleName)
	return function(_name, struct)
		local feat = { name = _name, _prev = nil }

		function feat:enable()
			local deadline = os.clock() + 30
			local toggle
			repeat
				toggle = Toggles and Toggles[toggleName]
				if toggle or (struct and not struct:has_any()) then
					break
				end
				task.wait(0.1)
			until os.clock() >= deadline

			if not toggle then
				if not struct or struct:has_any() then
					warn(string.format("[AutomationStruct] toggle %s was unavailable after 30 seconds", toggleName))
				end
				return
			end
			self._prev = toggle.Value
			toggle:SetValue(true)
		end

		function feat:disable()
			local toggle = Toggles and Toggles[toggleName]
			if toggle and self._prev ~= nil then
				toggle:SetValue(self._prev)
			end
			self._prev = nil
		end

		return feat
	end
end

-- ---------------------------------------------------------------------------------------------------------
-- mob_ai_breaker: PR's Titus kill mechanism. Every Heartbeat, slam the root's velocity straight down
-- (Vector3.new(0, -9e9, 0)); every PreRender, restore the pre-slam velocity so the character doesn't
-- actually fall. This desyncs / breaks the boss's AI + physics targeting. NOT an m1 farm.
-- ---------------------------------------------------------------------------------------------------------
local function makeMobAiBreaker(name, struct)
	local feat = { name = name, current_connection = nil, pre_ren = nil }
	local lastVel = nil

	function feat:enable()
		self.current_connection = runService.Heartbeat:Connect(function()
			local r = root()
			if not r then
				return
			end
			lastVel = r.AssemblyLinearVelocity
			r.AssemblyLinearVelocity = Vector3.new(0, -9e9, 0)
		end)

		self.pre_ren = runService.PreRender:Connect(function()
			if lastVel then
				local r = root()
				if r then
					r.AssemblyLinearVelocity = lastVel
				end
				lastVel = nil
			end
		end)
	end

	function feat:disable()
		if self.current_connection then
			pcall(function()
				self.current_connection:Disconnect()
			end)
			self.current_connection = nil
		end
		if self.pre_ren then
			pcall(function()
				self.pre_ren:Disconnect()
			end)
			self.pre_ren = nil
		end
		if lastVel then
			local r = root()
			if r then
				r.AssemblyLinearVelocity = lastVel
			end
			lastVel = nil
		end
	end

	return feat
end

-- ---------------------------------------------------------------------------------------------------------
-- jesus: anti-water-death. Parents an invisible 2048x2048 floor at Y=-3 under the player and keeps the
-- "NoSwim" effect applied so the game never forces a swim/drown state. Only active in the merit + dungeon
-- places (the phases where the farm skims over water), matching PR's is_eastern/is_etrean gate.
-- ---------------------------------------------------------------------------------------------------------
local function makeJesus(name, struct)
	local feat = { name = name, current_connection = nil, part = nil }

	function feat:enable()
		if not self.part then
			self.part = Instance.new("Part")
			self.part.Transparency = 1
			self.part.Size = Vector3.new(2048, 1, 2048)
			self.part.Anchored = true
			self.part.CanCollide = false
			self.part.Position = Vector3.new(0, 0, 0)
			self.part.Name = "FakeWater"
		end

		self.current_connection = runService.Heartbeat:Connect(function()
			local placeId = game.PlaceId
			if placeId ~= EASTERN_PLACE_ID and placeId ~= TITUS_PLACE_ID then
				if self.part.Parent then
					self.part.Parent = nil
				end
				return
			end
			local r = root()
			if not r then
				return
			end
			if self.part.Parent ~= workspace then
				self.part.Parent = workspace
			end
			self.part.CFrame = CFrame.new(r.Position.X, -3, r.Position.Z)

			pcall(function()
				local er = getER()
				if er and not er:HasEffect("NoSwim") then
					er:CreateEffect("NoSwim")
				end
			end)
		end)
	end

	function feat:disable()
		if self.current_connection then
			pcall(function()
				self.current_connection:Disconnect()
			end)
			self.current_connection = nil
		end
		if self.part then
			pcall(function()
				self.part:Destroy()
			end)
			self.part = nil
		end
		pcall(function()
			local er = getER()
			if er and er.FindEffect then
				local effect = er:FindEffect("NoSwim")
				if effect and effect.Debris then
					effect:Debris(0.1)
				end
			end
		end)
	end

	return feat
end

-- ---------------------------------------------------------------------------------------------------------
-- no_one_bit: strips the "OneBit" passive (the flaw that one-shots you when you'd otherwise survive a
-- lethal hit) from EffectReplicator.Passives so a freshly-rolled character can't die to it. PR does this
-- via an ssv_parser that just mutates EffectReplicator.Passives[name]; ported directly.
-- ---------------------------------------------------------------------------------------------------------
local function makeNoOneBit(name, struct)
	local feat = { name = name, running = false, removed = false }

	function feat:enable()
		self.running = true
		task.spawn(function()
			while self.running do
				pcall(function()
					local er = getER()
					if er and er.Passives then
						if er.Passives["OneBit"] then
							self.removed = true
						end
						er.Passives["OneBit"] = nil
					end
				end)
				task.wait(1)
			end
		end)
	end

	function feat:disable()
		self.running = false
		if self.removed then
			pcall(function()
				local er = getER()
				if er and er.Passives then
					er.Passives["OneBit"] = true
				end
			end)
			self.removed = false
		end
	end

	return feat
end

-- ---------------------------------------------------------------------------------------------------------
-- auto_equip_weapon: keeps the weapon drawn. Whenever the "Equipped" effect is absent, fire the
-- CharacterHandler DrawWeapon remote. Faithful to PR's poll loop (its EffectReplicatorHandler:hook is a
-- latency optimization luma has no equivalent for; the 1s poll is the core behavior).
-- ---------------------------------------------------------------------------------------------------------
local function makeAutoEquipWeapon(name, struct)
	local feat = { name = name, running = false }

	local function isUsingUtilityTool()
		local c = char()
		if not c then
			return false
		end
		return c:FindFirstChildOfClass("Tool") ~= nil
	end

	local function drawWeapon()
		if isUsingUtilityTool() then
			return
		end
		local c = char()
		local handler = c and c:FindFirstChild("CharacterHandler")
		local requests = handler and handler:FindFirstChild("Requests")
		local remote = requests and requests:FindFirstChild("DrawWeapon")
		if remote then
			pcall(function()
				remote:FireServer(true)
			end)
		end
	end

	function feat:enable()
		self.running = true
		task.spawn(function()
			while self.running do
				local er = getER()
				if not (er and er:FindEffect("Equipped")) then
					drawWeapon()
				end
				task.wait(1)
			end
		end)
	end

	function feat:disable()
		self.running = false
	end

	return feat
end

-- ---------------------------------------------------------------------------------------------------------
-- m1_hold: PR's held-m1 feature. While `.held` is true, repeatedly throw a left-click (m1) via luma's
-- InputClient. Tasks flip `struct.active_features.m1_hold.held` on/off around the moments they want to swing.
-- ---------------------------------------------------------------------------------------------------------
local function makeM1Hold(name, struct)
	local feat = { name = name, held = false, running = false }

	function feat:enable()
		self.running = true
		task.spawn(function()
			while self.running do
				if self.held then
					local c = char()
					local r = c and c:FindFirstChild("HumanoidRootPart")
					if r then
						pcall(function()
							-- ignoreChecks + forceGround: PR's m1_hold swings on cooldown with no_aerials on.
							InputClient.left(r.CFrame, true, true)
						end)
					end
				end
				task.wait(0.1)
			end
		end)
	end

	function feat:disable()
		self.running = false
		self.held = false
	end

	return feat
end

-- ---------------------------------------------------------------------------------------------------------
-- mod_detector: hop away if a Deepwoken Staff member joins the server. PR checks a static member map first;
-- here we do PR's live fallback (GetRankInGroup on the staff group) for every player, which needs no data.
-- ---------------------------------------------------------------------------------------------------------
local STAFF_GROUP_ID = 5212858
local function makeModDetector(name, struct)
	local feat = { name = name, running = false, conn = nil }

	local function check(player)
		if player == players.LocalPlayer then
			return
		end
		task.spawn(function()
			local rank = 0
			pcall(function()
				rank = player:GetRankInGroup(STAFF_GROUP_ID)
			end)
			if rank and rank > 0 and feat.running then
				pcall(function()
					if Library and Library.NotifyWithSound then
						Library:NotifyWithSound(string.format("%s is in the Deepwoken Staff group -- hopping.", player.Name), 15)
					end
				end)
				if struct:has_any() then
					local slot = players.LocalPlayer and players.LocalPlayer:GetAttribute("DataSlot")
					pcall(function()
						ServerHop.hop(slot, true)
					end)
				end
			end
		end)
	end

	function feat:enable()
		self.running = true
		self.conn = players.PlayerAdded:Connect(check)
		task.delay(0.25, function()
			for _, p in ipairs(players:GetPlayers()) do
				check(p)
			end
		end)
	end

	function feat:disable()
		self.running = false
		if self.conn then
			pcall(function()
				self.conn:Disconnect()
			end)
			self.conn = nil
		end
	end

	return feat
end

-- ---------------------------------------------------------------------------------------------------------
-- fast_swing: remove the attack-cooldown effects (LightAttack/HeavyAttack/etc.) the instant they're added,
-- so swings aren't rate-limited client-side. Direct port of PR's fast_swing (EffectReplicator "added" hook
-- -> effect:Remove(true)).
-- ---------------------------------------------------------------------------------------------------------
local FAST_SWING_CLASSES = { "OffhandAttack", "HeavyAttack", "MediumAttack", "LightAttack", "UsingSpell" }
local function makeFastSwing(name, struct)
	local feat = { name = name, running = false, conn = nil }

	function feat:enable()
		self.running = true
		task.spawn(function()
			local er = getER()
			if not self.running or not er or not er.EffectAdded then
				return
			end
			self.conn = er.EffectAdded:Connect(function(effect)
				if effect and effect.Class and table.find(FAST_SWING_CLASSES, effect.Class) then
					task.defer(function()
						pcall(function()
							effect:Remove(true)
						end)
					end)
				end
			end)
		end)
	end

	function feat:disable()
		self.running = false
		if self.conn then
			pcall(function()
				self.conn:Disconnect()
			end)
			self.conn = nil
		end
	end

	return feat
end

-- ---------------------------------------------------------------------------------------------------------
-- auto_log: Ferryman-style anti-detection. Hop the moment another player comes within the automation's
-- auto-log distance (per-automation AutoLog store, adjustable 0-2000 in the menu; 0 = off). Skipped during
-- character creation (lobby players would softlock the creator).
-- ---------------------------------------------------------------------------------------------------------
local function makeAutoLog(name, struct)
	local feat = { name = name, running = false }

	function feat:enable()
		self.running = true
		task.spawn(function()
			while self.running do
				task.wait(1)
				if not self.running then
					break
				end
				local cc = workspace:FindFirstChild("CharacterCreator")
				local c = char()
				if cc and c and c.Parent == cc then
					-- character creation; don't hop
				else
					local r = c and c:FindFirstChild("HumanoidRootPart")
					local dist = AutoLog.get(struct and struct.id)
					if r and dist > 0 and Finder.pnear(r.Position, dist) then
						if struct:has_any() then
							local slot = players.LocalPlayer and players.LocalPlayer:GetAttribute("DataSlot")
							pcall(function()
								ServerHop.hop(slot, true)
							end)
						end
						return
					end
				end
			end
		end)
	end

	function feat:disable()
		self.running = false
	end

	return feat
end

-- ---------------------------------------------------------------------------------------------------------
-- Registry.
-- ---------------------------------------------------------------------------------------------------------
local constructors = {
	fly = makeToggleFeature("Fly"),
	noclip = makeToggleFeature("NoClip"),
	no_fall = makeToggleFeature("NoFallDamage"),
	auto_loot = makeToggleFeature("AutoLoot"),
	no_kill_bricks = makeToggleFeature("NoKillBricks"),
	no_fire = makeToggleFeature("AutoExtinguishFire"),
	no_stun = makeToggleFeature("NoStun"),
	fast_swing = makeFastSwing,
	mob_ai_breaker = makeMobAiBreaker,
	jesus = makeJesus,
	no_one_bit = makeNoOneBit,
	auto_equip_weapon = makeAutoEquipWeapon,
	m1_hold = makeM1Hold,
	mod_detector = makeModDetector,
	auto_log = makeAutoLog,
	-- auto_wisp maps to luma's AutoWisp toggle.
	auto_wisp = makeToggleFeature("AutoWisp"),
}

---Create a feature object for `name`, bound to `struct`. Returns nil if the name is unknown.
---@param name string
---@param struct table
---@return table?
function AutomationFeatures.create(name, struct)
	local ctor = constructors[name]
	if not ctor then
		return nil
	end
	return ctor(name, struct)
end

return AutomationFeatures

end)
__bundle_register("@luma/Features/Automation/Objects/AutomationStruct", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AutomationStruct: a luma port of project-rain-oss's `src/automation/struct.lua`. Bundles a state machine
-- with a set of features (see AutomationFeatures) and a character-creation routine. `construct` builds one;
-- `run` enables the features and starts the state machine; `stop` tears the features back down.
--
-- PR's global `aztup.automation:has_any()` (is any automation still running) is provided per-struct via the
-- `is_running` option -- a function the caller passes so features + state callbacks can bail when stopped.
local AutomationStruct = {}
AutomationStruct.__index = AutomationStruct

---@module Features.Automation.Objects.AutomationFeatures
local AutomationFeatures = require("@luma/Features/Automation/Objects/AutomationFeatures")

---@module Features.Automation.Objects.General
local General = require("@luma/Features/Automation/Objects/General")

---@module Utility.SafeClick
local safeClick = require("@luma/Utility/SafeClick")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local function localPlayer()
	return players.LocalPlayer
end

local function character()
	local lp = localPlayer()
	return lp and lp.Character
end

---@param opts table
---@return table
function AutomationStruct.construct(opts)
	local obj = setmetatable({}, AutomationStruct)

	obj.id = opts.id
	obj.state_machine = opts.state_machine
	obj.features = opts.features or {}
	obj.on_run = opts.on_run
	obj.is_running = opts.is_running or function()
		return true
	end

	obj.character_creator_handler_used = opts.character_creator_handler_used or false
	obj.character_creator_handler_opts = opts.character_creator_handler_opts or {}

	obj.active_features = {}
	obj.threads = {}

	return obj
end

---True while the owning automation is still running (PR's aztup.automation:has_any()).
---@return boolean
function AutomationStruct:has_any()
	return self.is_running() == true
end

---Enable every feature, then start the state machine.
function AutomationStruct:run()
	self.active_features = {}

	-- Blow through the start/loading screen so the character actually spawns before we route (every farm
	-- needs this on a fresh join; skipped automatically during character creation).
	General.requestStart(function()
		return self:has_any()
	end)

	for _, name in ipairs(self.features) do
		local feat = AutomationFeatures.create(name, self)
		if feat then
			task.spawn(function()
				local ok, err = pcall(function()
					feat:enable()
				end)
				if not ok then
					warn(string.format("[AutomationStruct] feature %s enable failed: %s", tostring(name), tostring(err)))
				end
			end)
			self.active_features[name] = feat
		end
	end

	if self.on_run then
		task.spawn(self.on_run)
	end

	table.insert(
		self.threads,
		task.spawn(function()
			self.state_machine:start()
		end)
	)
end

---Disable every active feature and cancel any in-flight character-creation helper threads.
function AutomationStruct:stop()
	for _, feat in pairs(self.active_features) do
		pcall(function()
			feat:disable()
		end)
	end
	self.active_features = {}

	if self._creation_threads then
		for _, thread in ipairs(self._creation_threads) do
			pcall(function()
				task.cancel(thread)
			end)
		end
		self._creation_threads = {}
	end
end

---Character creation. Direct port of PR's automation_struct.create_character (luma-native requires).
function AutomationStruct:create_character()
	local options = self.character_creator_handler_opts
	local lp = localPlayer()

	local requests = replicatedStorage:WaitForChild("Requests")
	local characterCreator = requests:WaitForChild("CharacterCreator")
	local pickSpawn = characterCreator:WaitForChild("PickSpawn")
	local changeWeapon = characterCreator:WaitForChild("ChangeWeapon")
	local finishCreation = characterCreator:WaitForChild("FinishCreation")
	local toggleMetaModifier = requests:WaitForChild("ToggleMetaModifier", 20)
	local playerGui = lp:WaitForChild("PlayerGui")
	local characterGui = playerGui:WaitForChild("CharacterCreator")
	local suc

	-- Re-resolve the PickSpawn remote fresh each pick -- the game can replace the CharacterCreator remotes
	-- between invocations, and a cached reference would go stale (InvokeServer on a destroyed remote no-ops).
	local function getPickSpawn()
		local cc = requests:FindFirstChild("CharacterCreator")
		return (cc and cc:FindFirstChild("PickSpawn")) or pickSpawn
	end

	-- Origin selection. The PickSpawn return value is NOT a reliable confirmation -- it echoes the requested
	-- spawn even when the origin never actually applies (the "script thinks it picked but it didn't" bug). The
	-- authoritative current origin is what the creator client itself reads: `DataReplication.GetData().Origin`
	-- (line 1851 of the decompiled creator -- defaults to "Castaway"). So we fire PickSpawn, then verify the
	-- REAL server-synced origin equals our target category (Titus = "Authority Ensign", L2 = "Deepbound"),
	-- retrying until it does or `timeout` seconds pass -> kick. cfg = { category, spawn, timeout, kick_message };
	-- `category` is the origin whose presence in DataReplication.Origin we verify.
	local function clickOriginButton(cfg)
		local deadline = os.clock() + (cfg.timeout or 10)

		local function currentOrigin()
			local origin
			pcall(function()
				origin = require(replicatedStorage:WaitForChild("Info"):WaitForChild("DataReplication")).GetData().Origin
			end)
			return origin
		end

		repeat
			-- Already the right origin (server-synced)? done.
			if cfg.category and currentOrigin() == cfg.category then
				return true
			end
			-- Fire the spawn pick (what the real button does), then re-check the real origin.
			pcall(function()
				getPickSpawn():InvokeServer(cfg.spawn)
			end)
			task.wait(0.25)
			if cfg.category and currentOrigin() == cfg.category then
				return true
			end
		until os.clock() >= deadline

		-- Couldn't get the origin to apply in time. Prefer the automation's on_fail handler (e.g. server-hop +
		-- retry on a fresh server) over kicking, so the farm just tries again instead of dropping the player.
		if cfg.on_fail then
			pcall(cfg.on_fail)
		else
			pcall(function()
				lp:Kick(cfg.kick_message or "Need authority origin")
			end)
		end
		return false
	end

	-- Select the Standard gamemode by CLICKING its button -- NOT just firing ChangeGamemode. The decompiled
	-- creator shows the button handler does MORE than the remote: after ChangeGamemode:InvokeServer it sets the
	-- client's `u40` flag and calls refreshGamemode(), which is what hides the gamemode screen and REVEALS the
	-- origin / creation UI. Firing the remote alone leaves the client stuck on the gamemode screen, so the
	-- origin never applies (that was the "origin never chosen" bug). We confirm by the GameMode frame going
	-- invisible -- exactly what refreshGamemode does once a mode is chosen.
	do
		local deadline = os.clock() + 10
		local function standardElement()
			local gm = characterGui:FindFirstChild("GameMode")
			local opts = gm and gm:FindFirstChild("Options")
			local std = opts and opts:FindFirstChild("Standard")
			return std and std:FindFirstChild("Element")
		end
		local function gamemodeChosen()
			local gm = characterGui:FindFirstChild("GameMode")
			return gm ~= nil and gm.Visible == false
		end
		repeat
			if gamemodeChosen() then
				break
			end
			local el = standardElement()
			if el then
				-- safeClick instead of firesignal (native-crash risk pcall can't catch -- see Utility/SafeClick).
				safeClick(el)
			end
			task.wait(0.25)
			if gamemodeChosen() then
				break
			end
		until os.clock() >= deadline
	end

	-- Pick the origin UP FRONT, before weapon/modifiers/boons/flaws. Deepwoken keys the rest of creation off
	-- the chosen origin, so those picks (and FinishCreation) must happen with an origin already set -- otherwise
	-- the character commits before the origin applies. It's re-asserted again as the last write below to beat
	-- the Standard gamemode's async default-origin overwrite.
	if options.origin_button then
		-- Button path: wait for + click the real UI origin button (kicks the player if it never appears).
		if not clickOriginButton(options.origin_button) then
			return
		end
	elseif options.origin then
		for _ = 1, 10 do
			suc = getPickSpawn():InvokeServer(options.origin)
			task.wait(0.1)
		end
	end

	if options.weapon then
		for _ = 1, 10 do
			suc = changeWeapon:InvokeServer(options.weapon)
			if suc then
				break
			end
			task.wait(0.1)
		end
	end

	if options.modifiers and toggleMetaModifier then
		for _, modifier in ipairs(options.modifiers) do
			toggleMetaModifier:FireServer(modifier)
			if #options.modifiers == 1 then
				break
			end
			task.wait(1)
		end
	end

	local pickBoon = characterCreator:WaitForChild("PickBoon")
	local pickFlaw = characterCreator:WaitForChild("PickFlaw")
	local dataReplication =
		require(replicatedStorage:WaitForChild("Info"):WaitForChild("DataReplication")).GetData()

	for _, flaw in next, dataReplication.Flaws do
		pickFlaw:InvokeServer(tostring(flaw))
	end

	for _, boon in next, dataReplication.Boons do
		pickBoon:InvokeServer(tostring(boon))
	end

	pickBoon:InvokeServer("Autodidact")
	task.wait(1.5)
	pickFlaw:InvokeServer("Obvious")

	if not self:has_any() then
		return
	end

	-- Settle FIRST, BEFORE the final origin lock. The Standard gamemode applies its own default origin
	-- (Authority) asynchronously, and it can land a beat after our picks. Previously this wait happened AFTER
	-- the final origin write, which gave the async default a 2s window to deselect our origin again right
	-- before FinishCreation -- committing the wrong origin (button showing the wrong colour). Waiting here,
	-- before the lock, lets that default land first so our lock below is the genuine last word.
	task.wait(2)

	-- FINAL origin lock -- the very last thing before committing, with NO wait after it, so nothing can
	-- overwrite the origin before FinishCreation. clickOriginButton invokes PickSpawn and only returns once the
	-- server echoes back our spawn (authoritative), so this is the definitive last origin write.
	if options.origin_button then
		if not clickOriginButton(options.origin_button) then
			return
		end
	elseif options.origin then
		for _ = 1, 10 do
			getPickSpawn():InvokeServer(options.origin)
			task.wait(0.1)
		end
	end

	-- Finish creation ONCE, then confirm the "create this character?" prompt. Both helper threads are
	-- tracked on the struct (cancelled by :stop) and time-bounded, so a failed/stopped attempt can't leave a
	-- zombie confirm thread that later fires Choice:FireServer(true) on the NEXT run's prompt -- that is what
	-- intermittently rolled the wrong character. (PR's framework gets a fresh session each cycle, so it never
	-- hits this; luma persists in-session, so we have to guard it.)
	self._creation_threads = self._creation_threads or {}
	table.insert(
		self._creation_threads,
		task.spawn(function()
			pcall(function()
				finishCreation:InvokeServer()
			end)
		end)
	)
	table.insert(
		self._creation_threads,
		task.spawn(function()
			local choicePrompt = playerGui:WaitForChild("ChoicePrompt", 30)
			local choice = choicePrompt and choicePrompt:WaitForChild("Choice", 5)
			if choice and self:has_any() then
				pcall(function()
					choice:FireServer(true)
				end)
			end
		end)
	)

	-- Wait for the character to spawn into Live (30s cap so a failed creation can't hang forever -- the caller
	-- re-checks and retries instead).
	local waitStart = os.clock()
	repeat
		task.wait()
		local c = character()
		if c and c.Parent and c.Parent.Name == "Live" then
			break
		end
	until not self:has_any() or os.clock() - waitStart > 30

	local c = character()
	if c and c.Parent and c.Parent.Name == "Live" then
		c:WaitForChild("HumanoidRootPart")
		c:WaitForChild("Humanoid")
	end
end

return AutomationStruct

end)
__bundle_register("@luma/Features/Automation/Objects/General", function(require, _LOADED, __bundle_register, __bundle_modules)
-- General: luma port of project-rain-oss's `general_utilitys` helpers used by the automation tasks.
-- The notable one is playing_ap_anims -- "is this entity currently in an attack-pattern animation" -- which
-- PR backs with its own 4.5k-line timing DB. Here it's backed by luma's OWN timing database
-- (SaveManager.as:index), so there's no duplicated data and it tracks luma's timings.
local General = {}

---@module Game.Timings.SaveManager
local SaveManager = require("@luma/Game/Timings/SaveManager")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local FAST_SWING_CLASSES = { "OffhandAttack", "HeavyAttack", "MediumAttack", "LightAttack", "UsingSpell" }

---Tap a key once via VirtualInputManager (pure client input; no remote).
---@param keyCode Enum.KeyCode
function General.pressKey(keyCode)
	pcall(function()
		local vim = Instance.new("VirtualInputManager")
		vim:SendKeyEvent(true, keyCode, false, game)
		vim:SendKeyEvent(false, keyCode, false, game)
	end)
end

---Spam the A key to click through the game's loading screen (LoadingGui) until it disappears or the
---character spawns (10s cap). Input-only: the old Requests.StartMenu.Start remote is an anticheat
---honeypot (instant ban), so we drive the menu the way a player would instead of firing anything.
function General.clickThroughLoadingGui()
	-- Poll (up to 10s) for the loading screen OR the character being in -- not WaitForChild, so a character
	-- that loads in mid-wait bails immediately instead of stalling the full timeout.
	local loadingGui
	local findDeadline = os.clock() + 10
	repeat
		if players.LocalPlayer and players.LocalPlayer.Character then
			return
		end
		local pg = players.LocalPlayer and players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
		loadingGui = pg and pg:FindFirstChild("LoadingGui")
		if loadingGui then
			break
		end
		task.wait()
	until os.clock() >= findDeadline
	if not loadingGui then
		return
	end
	local deadline = os.clock() + 10
	repeat
		General.pressKey(Enum.KeyCode.A)
		task.wait(0.2)
	until not loadingGui.Parent or (players.LocalPlayer and players.LocalPlayer.Character) or os.clock() >= deadline
end

---Blow through the loading screen (was: fire Requests.StartMenu.Start). Now spams A through the
---LoadingGui instead -- the StartMenu remote is an AC honeypot. Kept under the same name so callers work.
function General.fireStartMenu()
	General.clickThroughLoadingGui()
end

---Fast swing: remove the attack-cooldown effects (LightAttack/HeavyAttack/etc.) the instant they're added,
---so swings aren't rate-limited client-side (PR's fast_swing). Returns the connection to disconnect, or nil.
function General.connectFastSwing()
	local er
	pcall(function()
		er = require(replicatedStorage:WaitForChild("EffectReplicator", 5))
	end)
	if not er or not er.EffectAdded then
		return nil
	end
	return er.EffectAdded:Connect(function(effect)
		if effect and effect.Class and table.find(FAST_SWING_CLASSES, effect.Class) then
			task.defer(function()
				pcall(function()
					effect:Remove(true)
				end)
			end)
		end
	end)
end

---Blow through the game's loading screen and wait for our character to spawn into workspace.Live.
---While the LoadingGui is up, spams A to click through it (input-only -- the old StartMenu.Start
---remote is an anticheat honeypot). Skipped for character creation (that's its own flow).
---@param isRunning function? returns false to bail early
function General.requestStart(isRunning)
	-- Already in-game (char in Live) or in the character creator? nothing to click through.
	local function inGame()
		local char = players.LocalPlayer and players.LocalPlayer.Character
		local creator = workspace:FindFirstChild("CharacterCreator")
		return (creator and char and char.Parent == creator)
			or (char and char.Parent and char.Parent.Name == "Live") and true
			or false
	end

	-- Wait (up to 10s) for EITHER the loading screen to appear OR the character to already be in. This is a
	-- poll, not WaitForChild, on purpose: WaitForChild blocks, so if the character loads in mid-wait it would
	-- stall the full timeout before returning (that was the "stalls a few seconds after the character loads"
	-- bug). Polling lets inGame() bail us out the instant the character is in. Called very early, so it also
	-- resolves PlayerGui here.
	local loadingGui
	local findDeadline = os.clock() + 10
	repeat
		if isRunning and not isRunning() then
			return
		end
		if inGame() then
			return
		end
		local pg = players.LocalPlayer and players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
		loadingGui = pg and pg:FindFirstChild("LoadingGui")
		if loadingGui then
			break
		end
		task.wait()
	until os.clock() >= findDeadline

	local deadline = os.clock() + 25
	repeat
		if isRunning and not isRunning() then
			return
		end
		if inGame() then
			return
		end
		-- Loading screen still up? spam A to click through it.
		if loadingGui and loadingGui.Parent then
			General.pressKey(Enum.KeyCode.A)
		end
		task.wait(0.2)
	until os.clock() >= deadline
end

---True if `entity` is currently playing any animation luma recognises as an attack timing. `ids` is an
---optional list of AnimationIds to ignore (PR passes specific ids it wants to treat as "safe").
---@param entity Instance
---@param ids table? list of AnimationId strings to skip
---@return boolean
function General.playing_ap_anims(entity, ids)
	if not entity then
		return false
	end
	local humanoid = entity:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return false
	end
	local as = SaveManager and SaveManager.as
	if not as then
		return false
	end

	local ok, playing = pcall(function()
		return humanoid:GetPlayingAnimationTracks()
	end)
	if not ok or not playing then
		return false
	end

	for _, track in next, playing do
		local full = tostring(track.Animation.AnimationId)
		if not (ids and table.find(ids, full)) then
			local digits = full:match("%d+")
			local matched = false
			pcall(function()
				matched = as:index(full) ~= nil or (digits ~= nil and as:index(digits) ~= nil)
			end)
			if matched then
				return true
			end
		end
	end
	return false
end

---Respawn / leave via the fastest route: replicate the Kill signal, then void ourselves if we somehow
---survived. Direct port of PR's `buttons/respawn`.
function General.respawn()
	local lp = players.LocalPlayer
	if not lp then
		return
	end
	if replicatesignal then
		pcall(function()
			replicatesignal(lp.Kill)
		end)
		task.delay(1, function()
			local char = lp.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if hum and hum.Health <= 1 then
				return
			end
			local root = char and char:FindFirstChild("HumanoidRootPart")
			if root then
				root.CFrame = root.CFrame * CFrame.new(0, 9e9, 0)
			end
		end)
	else
		local char = lp.Character
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if root then
			root.CFrame = root.CFrame * CFrame.new(0, 9e9, 0)
		end
	end
end

return General

end)
__bundle_register("@luma/Features/Automation/Objects/StateMachine", function(require, _LOADED, __bundle_register, __bundle_modules)
-- StateMachine: a faithful port of project-rain-oss's `src/utility/statemachine.lua`.
-- An event/callback finite state machine. Events declare from->to transitions; firing an event named
-- `foo` (via `fsm:foo(...)`) runs onbefore<foo> / onleave<from> / onenter<to> / onafter<foo> callbacks.
-- Transitions are synchronous unless a leave/enter handler returns StateMachine.ASYNC.
local StateMachine = {}
StateMachine.__index = StateMachine

local NONE = "none"
local ASYNC = "async"

local unpack = table.unpack or unpack

local function callHandler(handler, params)
	if not handler then
		return
	end
	return handler(unpack(params))
end

local function createTransition(name)
	local can, to, from, params

	local function transition(self, ...)
		if self.asyncState == NONE then
			can, to = self:can(name)
			from = self.current
			params = { self, name, from, to, ... }

			if not can then
				self.currentTransitioningEvent = nil
				return false
			end

			self.currentTransitioningEvent = name
			local beforeReturn = callHandler(self["onbefore" .. name], params)
			local leaveReturn = callHandler(self["onleave" .. from], params)

			if not self["onleave" .. from] and self.dexit then
				leaveReturn = self.dexit()
			end

			if beforeReturn == false or leaveReturn == false then
				self.currentTransitioningEvent = nil
				return false
			end

			self.asyncState = name .. "WaitingOnLeave"

			if leaveReturn ~= ASYNC then
				return transition(self, ...)
			end

			return true
		elseif self.asyncState == name .. "WaitingOnLeave" then
			self.current = to

			local enterReturn = callHandler(self["onenter" .. to] or self["on" .. to], params)

			self.asyncState = name .. "WaitingOnEnter"

			if enterReturn ~= ASYNC then
				return transition(self, ...)
			end

			return true
		elseif self.asyncState == name .. "WaitingOnEnter" then
			callHandler(self["onafter" .. name] or self["on" .. name], params)
			callHandler(self["onstatechange"], params)
			self.asyncState = NONE
			self.currentTransitioningEvent = nil
			return true
		else
			if string.find(self.asyncState, "WaitingOnLeave") or string.find(self.asyncState, "WaitingOnEnter") then
				self.asyncState = NONE
				return transition(self, ...)
			end
		end

		self.currentTransitioningEvent = nil
		return false
	end

	return transition
end

local function addToMap(map, event)
	if type(event.from) == "string" then
		map[event.from] = event.to
	else
		for _, from in ipairs(event.from) do
			map[from] = event.to
		end
	end
end

function StateMachine.create(options)
	assert(options.events)

	local fsm = {}
	setmetatable(fsm, StateMachine)

	fsm.options = options
	fsm.current = options.initial or "none"
	fsm.asyncState = NONE
	fsm.events = {}
	fsm.dexit = options.dexit

	for _, event in ipairs(options.events or {}) do
		local name = event.name
		fsm[name] = fsm[name] or createTransition(name)
		fsm.events[name] = fsm.events[name] or { map = {} }
		addToMap(fsm.events[name].map, event)
	end

	for name, callback in pairs(options.callbacks or {}) do
		fsm[name] = callback
	end

	return fsm
end

function StateMachine:is(state)
	return self.current == state
end

function StateMachine:can(e)
	local event = self.events[e]
	local to = event and event.map[self.current] or event.map["*"]
	return to ~= nil, to
end

function StateMachine:cannot(e)
	return not self:can(e)
end

function StateMachine:transition(event)
	if self.currentTransitioningEvent == event then
		return self[self.currentTransitioningEvent](self)
	end
end

function StateMachine:cancelTransition(event)
	if self.currentTransitioningEvent == event then
		self.asyncState = NONE
		self.currentTransitioningEvent = nil
	end
end

StateMachine.NONE = NONE
StateMachine.ASYNC = ASYNC

return StateMachine

end)
__bundle_register("@luma/Features/Automation/Objects/Teleports", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Teleports: luma port of project-rain-oss's `generic_teleport` + the region teleport buttons
-- (etrean / eastern / depths). Each teleport forces NoClip, streams the destination in, then repeatedly
-- snaps to the destination and fires its RealmTeleport TouchInterest until the place change happens.
local Teleports = {}

local players = game:GetService("Players")
local runService = game:GetService("RunService")

local function localPlayer()
	return players.LocalPlayer
end

local function root()
	local lp = localPlayer()
	local char = lp and lp.Character
	return char and char:FindFirstChild("HumanoidRootPart")
end

local function humanoid()
	local lp = localPlayer()
	local char = lp and lp.Character
	return char and char:FindFirstChildOfClass("Humanoid")
end

-- ---------------------------------------------------------------------------------------------------------
-- Generic teleport (port of generic_teleport.lua).
-- ---------------------------------------------------------------------------------------------------------
local GenericTeleport = {}
GenericTeleport.__index = GenericTeleport

function GenericTeleport.new(destination, destinationPartGetter, stopCondition)
	return setmetatable({
		lastStreamRequest = 0,
		destination = destination,
		destinationPartGetter = destinationPartGetter,
		stopCondition = stopCondition,
		conn = nil,
	}, GenericTeleport)
end

function GenericTeleport:requestStreamAroundDestination()
	if not workspace.StreamingEnabled then
		return
	end
	if tick() - self.lastStreamRequest > 1 / 30 then
		self.lastStreamRequest = tick()
		pcall(function()
			localPlayer():RequestStreamAroundAsync(self.destination.Position)
		end)
	end
end

function GenericTeleport:run()
	-- Force NoClip on for the trip (restore it if we turned it on).
	local setForUser = false
	if Toggles and Toggles.NoClip and not Toggles.NoClip.Value then
		setForUser = true
		Toggles.NoClip:SetValue(true)
	end

	self.conn = runService.PostSimulation:Connect(function()
		self:requestStreamAroundDestination()

		if self.stopCondition and self:stopCondition() then
			if self.conn then
				self.conn:Disconnect()
				self.conn = nil
			end
			if setForUser and Toggles and Toggles.NoClip then
				Toggles.NoClip:SetValue(false)
			end
			return
		end

		local r = root()
		local destinationPart = self.destinationPartGetter()
		if r and destinationPart and destinationPart:FindFirstChild("TouchInterest") then
			r.AssemblyLinearVelocity = Vector3.one * (math.random() / 100)
			r.CFrame = self.destination * CFrame.new(math.random() / 100, math.random() / 100, math.random() / 100)
			xpcall(function()
				firetouchinterest(r, destinationPart, true)
				firetouchinterest(r, destinationPart, false)
			end, function() end)
		end

		local hum = humanoid()
		if hum and sethiddenproperty then
			pcall(function()
				sethiddenproperty(hum, "MoveDirectionInternal", Vector3.one)
			end)
		end
	end)

	return self
end

function GenericTeleport:stop()
	if self.conn then
		self.conn:Disconnect()
		self.conn = nil
	end
end

Teleports.GenericTeleport = GenericTeleport

-- ---------------------------------------------------------------------------------------------------------
-- Region teleports. Each returns the GenericTeleport instance (so callers can :stop() it if needed).
-- ---------------------------------------------------------------------------------------------------------
local function valleyRealmTeleport()
	local exit = workspace:FindFirstChild("ValleyExit")
	return exit and exit:FindFirstChild("RealmTeleport")
end

---Etrean Luminant.
function Teleports.etrean()
	return GenericTeleport.new(CFrame.new(-528.434814, 704.674194, -4760.4292), valleyRealmTeleport):run()
end

---Eastern Luminant.
function Teleports.eastern()
	return GenericTeleport.new(
		CFrame.new(-2637.4563, 721.632935, -6722.51953, -0.757481456, 0, -0.652856648, 0, 1, 0, 0.652856648, 0, -0.757481456),
		valleyRealmTeleport
	):run()
end

---The Depths (via the Mod Office pit).
function Teleports.depths()
	return GenericTeleport.new(CFrame.new(39911.3672, 39980.9375, 39708.3203), function()
		local modOffice = workspace:FindFirstChild("ModOffice")
		return modOffice and modOffice:FindFirstChild("OfficePit")
	end):run()
end

return Teleports

end)
__bundle_register("@luma/Features/Combat/AnimationInspector", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Animation Inspector -- a live window listing every animation a selected player is CURRENTLY playing.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local MarketplaceService = game:GetService("MarketplaceService")

---@module Utility.CoreGuiManager
local CoreGuiManager = require("@luma/Utility/CoreGuiManager")
---@module GUI.Library
local Library = require("@luma/GUI/Library")
---@module Utility.Configuration
local Configuration = require("@luma/Utility/Configuration")

local AnimationInspector = {}

-- Theme (pulled from the Luma Library so the window matches the menu).
local ACCENT  = Library.AccentColor     or Color3.fromRGB(243, 168, 214)
local MAIN    = Library.MainColor       or Color3.fromRGB(40, 32, 50)
local BG      = Library.BackgroundColor or Color3.fromRGB(28, 22, 36)
local FG      = Library.FontColor       or Color3.fromRGB(245, 238, 250)
local OUTLINE = Library.OutlineColor    or Color3.fromRGB(110, 86, 132)
local RISK    = Library.RiskColor       or Color3.fromRGB(255, 96, 128)
local MUTED   = Color3.fromRGB(168, 156, 182)

local MAX_ROWS = 100         -- hard cap so an AP-break flood can't spawn thousands
local UPDATE_INTERVAL = 0.06 -- ~16 Hz live-prop refresh
local LOG_FILE = "luma_animlog.txt"
local LOG_FLUSH_INTERVAL = 1.0

-- State
local running = false
local targetPlayer = nil
local targetName = nil

local screenGui, mainFrame, titleLabel, subLabel, listFrame, emptyLabel

local rows = {}          -- track -> { frame, nameLabel, propLabel, assetId, stoppedConn }
local rowCount = 0

local animatorConn = nil
local charAddedConn = nil
local charRemovingConn = nil
local updateConn = nil
local updateAccum = 0

-- Namecall-hook capture (fade time isn't exposed on AnimationTrack any other way).
local playArgs = setmetatable({}, { __mode = "k" })
local hookActive = false
local oldNamecall = nil

-- Asset-name resolution.
local nameCache = {}     -- assetId -> name | false
local namePending = {}
local nameQueue = {}
local resolverRunning = false

-- File logging (name / id / priority and any changes to them).
local logBuffer = {}
local logFlushAccum = 0
local logSessionStart = 0

-- Small helpers
local function mk(class, props, parent)
	local inst = Instance.new(class)
	for key, value in pairs(props) do
		inst[key] = value
	end
	if parent then
		inst.Parent = parent
	end
	return inst
end

local function fmtNum(value, digits)
	if type(value) ~= "number" then
		return "?"
	end
	return string.format("%." .. (digits or 2) .. "f", value)
end

local function safeGet(fn, fallback)
	local ok, value = pcall(fn)
	if ok and value ~= nil then
		return value
	end
	return fallback
end

-- The real asset behind an AnimationId.
local function assetIdOf(animationId)
	local text = tostring(animationId or "")
	local viaQuery = text:match("[?&]id=(%d+)")
	if viaQuery then
		return tonumber(viaQuery)
	end
	return tonumber(text:match("(%d+)"))
end

-- Query junk (a `?` AND an `&`) beyond a plain asset reference = id-spoof tell.
local function isMutatedId(animationId)
	local text = tostring(animationId or "")
	return text:find("?", 1, true) ~= nil and text:find("&", 1, true) ~= nil
end

local function lookupName(assetId)
	local ok, info = pcall(function()
		return MarketplaceService:GetProductInfo(assetId, Enum.InfoType.Asset)
	end)
	local resolved = (ok and info and info.Name) or false
	nameCache[assetId] = resolved
	namePending[assetId] = nil
	return resolved
end

local function queueName(assetId)
	if not assetId or nameCache[assetId] ~= nil or namePending[assetId] then
		return
	end
	namePending[assetId] = true
	nameQueue[#nameQueue + 1] = assetId
end

-- One background worker chews through lookups (GetProductInfo yields + rate-limits).
local function startResolver()
	if resolverRunning then
		return
	end
	resolverRunning = true
	task.spawn(function()
		while running do
			local assetId = table.remove(nameQueue, 1)
			if assetId then
				lookupName(assetId)
				task.wait(0.3)
			else
				task.wait(0.25)
			end
		end
		resolverRunning = false
	end)
end

-- GUI parenting (exploit-safe: gethui -> CoreGui -> PlayerGui)
local function guiParent()
	local ok, hui = pcall(function()
		return gethui and gethui()
	end)
	if ok and hui then
		return hui
	end
	local ok2, cg = pcall(function()
		return game:GetService("CoreGui")
	end)
	if ok2 and cg then
		return cg
	end
	local lp = Players.LocalPlayer
	return lp and lp:FindFirstChildOfClass("PlayerGui")
end

-- Window
local function buildWindow()
	if screenGui then
		return
	end

	screenGui = Instance.new("ScreenGui")
	screenGui.Name = "LumaAnimInspect"
	screenGui.ResetOnSpawn = false
	screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	screenGui.DisplayOrder = 9999
	CoreGuiManager.imark(screenGui)

	local ProtectGui = protectgui or (syn and syn.protect_gui) or function() end
	pcall(ProtectGui, screenGui)
	screenGui.Parent = guiParent()

	mainFrame = mk("Frame", {
		Name = "Window",
		Size = UDim2.fromOffset(360, 420),
		Position = UDim2.fromOffset(120, 120),
		BackgroundColor3 = BG,
		BorderSizePixel = 0,
	}, screenGui)
	mk("UICorner", { CornerRadius = UDim.new(0, 6) }, mainFrame)
	mk("UIStroke", { Color = OUTLINE, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, mainFrame)

	-- Title bar.
	local titleBar = mk("Frame", {
		Name = "TitleBar",
		Size = UDim2.new(1, 0, 0, 34),
		BackgroundColor3 = MAIN,
		BorderSizePixel = 0,
	}, mainFrame)
	mk("UICorner", { CornerRadius = UDim.new(0, 6) }, titleBar)
	-- Square off the bottom corners of the title bar.
	mk("Frame", {
		Size = UDim2.new(1, 0, 0, 8),
		Position = UDim2.new(0, 0, 1, -8),
		BackgroundColor3 = MAIN,
		BorderSizePixel = 0,
	}, titleBar)

	local accentBar = mk("Frame", {
		Size = UDim2.new(0, 3, 1, -8),
		Position = UDim2.fromOffset(8, 4),
		BackgroundColor3 = ACCENT,
		BorderSizePixel = 0,
	}, titleBar)
	mk("UICorner", { CornerRadius = UDim.new(1, 0) }, accentBar)

	titleLabel = mk("TextLabel", {
		Name = "Title",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(18, 3),
		Size = UDim2.new(1, -54, 0, 16),
		Font = Enum.Font.GothamBold,
		Text = "Animation Inspector",
		TextColor3 = FG,
		TextSize = 13,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, titleBar)

	subLabel = mk("TextLabel", {
		Name = "Sub",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(18, 18),
		Size = UDim2.new(1, -54, 0, 13),
		Font = Enum.Font.Gotham,
		Text = "no target",
		TextColor3 = MUTED,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, titleBar)

	local closeBtn = mk("TextButton", {
		Name = "Close",
		BackgroundColor3 = MAIN,
		Position = UDim2.new(1, -28, 0, 6),
		Size = UDim2.fromOffset(22, 22),
		Font = Enum.Font.GothamBold,
		Text = "X",
		TextColor3 = RISK,
		TextSize = 13,
		AutoButtonColor = true,
	}, titleBar)
	mk("UICorner", { CornerRadius = UDim.new(0, 4) }, closeBtn)
	closeBtn.MouseButton1Click:Connect(function()
		-- Flip the menu toggle off; its OnChanged calls stop().
		local ok = pcall(function()
			local toggles = getgenv and getgenv().Toggles
			if toggles and toggles.AnimationInspector then
				toggles.AnimationInspector:SetValue(false)
				return true
			end
			return false
		end)
		if not ok then
			AnimationInspector.stop()
		end
	end)

	-- Scrolling list of live rows.
	listFrame = mk("ScrollingFrame", {
		Name = "List",
		Position = UDim2.fromOffset(6, 40),
		Size = UDim2.new(1, -12, 1, -46),
		BackgroundColor3 = MAIN,
		BorderSizePixel = 0,
		ScrollBarThickness = 4,
		ScrollBarImageColor3 = ACCENT,
		CanvasSize = UDim2.new(0, 0, 0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
	}, mainFrame)
	mk("UICorner", { CornerRadius = UDim.new(0, 4) }, listFrame)
	mk("UIListLayout", {
		FillDirection = Enum.FillDirection.Vertical,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 3),
	}, listFrame)
	mk("UIPadding", {
		PaddingTop = UDim.new(0, 4),
		PaddingBottom = UDim.new(0, 4),
		PaddingLeft = UDim.new(0, 4),
		PaddingRight = UDim.new(0, 4),
	}, listFrame)

	emptyLabel = mk("TextLabel", {
		Name = "Empty",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 40),
		Font = Enum.Font.Gotham,
		Text = "no animations playing",
		TextColor3 = MUTED,
		TextSize = 12,
	}, listFrame)

	pcall(function()
		Library:MakeDraggable(mainFrame, 34)
	end)
end

-- Rows
local function updateEmptyState()
	if emptyLabel then
		emptyLabel.Visible = rowCount == 0
	end
	if subLabel then
		local who = targetName or "no target"
		subLabel.Text = string.format("%s  ·  %d playing", who, rowCount)
	end
end

-- File logging -- name / id / priority, and any change to them, appended to a txt in the executor's workspace folder for later reading.
local function loggingEnabled()
	return Configuration.expectToggleValue("AnimInspectLogToFile") == true
end

local function writeLog(text)
	pcall(function()
		if appendfile then
			appendfile(LOG_FILE, text)
		elseif writefile and readfile and isfile then
			local existing = isfile(LOG_FILE) and readfile(LOG_FILE) or ""
			if #existing < 5 * 1024 * 1024 then
				writefile(LOG_FILE, existing .. text)
			end
		end
	end)
end

local function flushLog()
	if #logBuffer == 0 then
		return
	end
	local text = table.concat(logBuffer, "\n") .. "\n"
	logBuffer = {}
	writeLog(text)
end

local function logLine(text)
	if not loggingEnabled() then
		return
	end
	logBuffer[#logBuffer + 1] = string.format("[%8.2f] %s", os.clock() - logSessionStart, text)
	if #logBuffer >= 400 then
		flushLog()
	end
end

local function updateRow(row)
	local track = row.track
	local anim = safeGet(function() return track.Animation end)
	local animationId = anim and tostring(anim.AnimationId) or nil
	local mutated = isMutatedId(animationId)

	local assetId = row.assetId
	local resolved = assetId and nameCache[assetId] or nil
	local displayName = resolved or (anim and anim.Name ~= "" and anim.Name) or "?"
	if displayName == "Animation" and assetId then
		displayName = "id:" .. tostring(assetId)
	end

	local priorityName = tostring(safeGet(function() return track.Priority.Name end, "?"))

	row.nameLabel.Text = string.format("%s   ·   %s", displayName, priorityName)
	row.nameLabel.TextColor3 = mutated and RISK or FG

	local args = playArgs[track]
	local fade = args and fmtNum(args.fade) or "?"

	row.propLabel.Text = string.format(
		"spd %s · wt %s/%s · len %s · t %s · fade %s%s",
		fmtNum(safeGet(function() return track.Speed end)),
		fmtNum(safeGet(function() return track.WeightCurrent end)),
		fmtNum(safeGet(function() return track.WeightTarget end)),
		fmtNum(safeGet(function() return track.Length end)),
		fmtNum(safeGet(function() return track.TimePosition end)),
		fade,
		mutated and "  · MUTATED" or ""
	)

	row.idLabel.Text = "id " .. (animationId or "?")
	row.idLabel.TextColor3 = mutated and RISK or ACCENT

	-- Peak WeightCurrent across this track's life. WeightCurrent is ~0 for EVERY
	-- animation the instant it starts (they all ramp up from 0), so a single play-time
	-- read tells you nothing -- the tell for a 0-weight flood bait is that it NEVER
	-- ramps. Sample the peak here every update and log it on stop.
	row.peakWC = math.max(row.peakWC or 0, safeGet(function() return track.WeightCurrent end, 0) or 0)

	-- File log: one line on first sight, then any change to name / id / priority.
	local idStr = animationId or "?"
	if row.loggedId == nil then
		row.loggedName = displayName
		row.loggedId = idStr
		row.loggedPriority = priorityName
		logLine(string.format('[+] name="%s" id=%s priority=%s wt=%s spd=%s', displayName, idStr, priorityName,
			fmtNum(safeGet(function() return track.WeightTarget end)),
			fmtNum(safeGet(function() return track.Speed end))))
	else
		if idStr ~= row.loggedId then
			logLine(string.format("[~] id=%s  id: %s -> %s", row.loggedId, row.loggedId, idStr))
			row.loggedId = idStr
		end
		if displayName ~= row.loggedName then
			logLine(string.format('[~] id=%s  name: "%s" -> "%s"', row.loggedId, row.loggedName, displayName))
			row.loggedName = displayName
		end
		if priorityName ~= row.loggedPriority then
			logLine(string.format("[~] id=%s  priority: %s -> %s", row.loggedId, row.loggedPriority, priorityName))
			row.loggedPriority = priorityName
		end
	end
end

local function removeRow(track)
	local row = rows[track]
	if not row then
		return
	end
	if row.loggedId then
		logLine(string.format("[-] id=%s  (stopped) peakwc=%s", row.loggedId, fmtNum(row.peakWC or 0)))
	end
	rows[track] = nil
	rowCount = rowCount - 1
	if row.stoppedConn then
		pcall(function() row.stoppedConn:Disconnect() end)
	end
	if row.frame then
		row.frame:Destroy()
	end
	updateEmptyState()
end

local function addRow(track)
	if rows[track] or rowCount >= MAX_ROWS or not listFrame then
		return
	end

	local frame = mk("Frame", {
		Name = "Row",
		Size = UDim2.new(1, 0, 0, 54),
		BackgroundColor3 = BG,
		BorderSizePixel = 0,
	}, listFrame)
	mk("UICorner", { CornerRadius = UDim.new(0, 4) }, frame)
	mk("UIStroke", { Color = OUTLINE, Thickness = 1, Transparency = 0.4 }, frame)

	local nameLabel = mk("TextLabel", {
		Name = "Name",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 4),
		Size = UDim2.new(1, -12, 0, 15),
		Font = Enum.Font.GothamSemibold,
		Text = "...",
		TextColor3 = FG,
		TextSize = 12,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, frame)

	local propLabel = mk("TextLabel", {
		Name = "Props",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 20),
		Size = UDim2.new(1, -12, 0, 14),
		Font = Enum.Font.Code,
		Text = "",
		TextColor3 = MUTED,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, frame)

	local idLabel = mk("TextLabel", {
		Name = "Id",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 35),
		Size = UDim2.new(1, -12, 0, 13),
		Font = Enum.Font.Code,
		Text = "",
		TextColor3 = ACCENT,
		TextSize = 11,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, frame)

	local anim = safeGet(function() return track.Animation end)
	local assetId = anim and assetIdOf(anim.AnimationId) or nil
	queueName(assetId)

	local row = { frame = frame, nameLabel = nameLabel, propLabel = propLabel, idLabel = idLabel, assetId = assetId, track = track }
	rows[track] = row
	rowCount = rowCount + 1

	-- DELETE the row the instant the animation ends.
	row.stoppedConn = track.Stopped:Connect(function()
		removeRow(track)
	end)

	updateRow(row)
	updateEmptyState()
end

local function clearRows()
	for track in pairs(rows) do
		removeRow(track)
	end
	rowCount = 0
	rows = {}
	updateEmptyState()
end

-- Live refresh loop: repaints visible rows and prunes tracks that stopped without firing .Stopped.
local function startUpdateLoop()
	if updateConn then
		return
	end
	updateConn = RunService.RenderStepped:Connect(function(dt)
		if not running then
			return
		end
		updateAccum = updateAccum + dt
		if updateAccum < UPDATE_INTERVAL then
			return
		end
		updateAccum = 0

		local dead = nil
		for track, row in pairs(rows) do
			if not safeGet(function() return track.IsPlaying end, false) then
				dead = dead or {}
				dead[#dead + 1] = track
			else
				updateRow(row)
			end
		end
		if dead then
			for _, track in ipairs(dead) do
				removeRow(track)
			end
		end

		logFlushAccum = logFlushAccum + UPDATE_INTERVAL
		if logFlushAccum >= LOG_FLUSH_INTERVAL then
			logFlushAccum = 0
			flushLog()
		end
	end)
end

-- Parallel-hook guard (see Game/Hooking.lua): on executors without parallel_hooks_allowed, install via a
-- read-only metatable swap so this __namecall hook can't be dispatched from an Actor parallel phase, which
-- is an illegal cross-phase op the engine Kernel panics on (RSL - panic: ...Kernel).
local parallelHooksAllowed = parallel_hooks_allowed
local hookmetamethod = (not parallelHooksAllowed)
	and function(target, method, hook)
		local metatable = getrawmetatable(target)
		setreadonly(metatable, false)
		local original = metatable[method]
		metatable[method] = hook
		setreadonly(metatable, true)
		return original
	end
	or hookmetamethod

-- Namecall hook -- capture the caller's Play(fade, weight, speed) args.
local function installHook()
	if hookActive then
		return
	end
	if not (hookmetamethod and getnamecallmethod and checkcaller) then
		return -- fade time simply stays "?" without exploit hook support
	end
	local ok = pcall(function()
		oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
			-- NOTE: deliberately NOT skipping checkcaller() calls.
			if not hookActive then
				return oldNamecall(self, ...)
			end
			if getnamecallmethod() == "Play" then
				local okClass, isTrack = pcall(game.IsA, self, "AnimationTrack")
				if okClass and isTrack then
					local a, b, c = ...
					playArgs[self] = {
						fade = type(a) == "number" and a or 0.1,
						weight = type(b) == "number" and b or 1,
						speed = type(c) == "number" and c or 1,
					}
				end
			end
			return oldNamecall(self, ...)
		end)
	end)
	hookActive = ok
end

local function removeHook()
	if not hookActive then
		return
	end
	hookActive = false
	if oldNamecall and hookmetamethod then
		pcall(function()
			hookmetamethod(game, "__namecall", oldNamecall)
		end)
		oldNamecall = nil
	end
end

-- Target binding
local function bindAnimator(animator, character)
	if animatorConn then
		pcall(function() animatorConn:Disconnect() end)
		animatorConn = nil
	end
	if not animator then
		return
	end

	animatorConn = animator.AnimationPlayed:Connect(function(track)
		if running then
			addRow(track)
		end
	end)

	-- Seed with whatever is already playing.
	for _, track in ipairs(safeGet(function() return animator:GetPlayingAnimationTracks() end, {})) do
		addRow(track)
	end
end

local function hookCharacter(character)
	clearRows()
	if not character then
		return
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if animator then
		bindAnimator(animator, character)
		return
	end
	-- Character just spawned; its Animator may not exist yet.
	task.spawn(function()
		local hum = character:WaitForChild("Humanoid", 5)
		local anim = hum and hum:WaitForChild("Animator", 5)
		if anim and running and targetPlayer and targetPlayer.Character == character then
			bindAnimator(anim, character)
		end
	end)
end

local function bindPlayer(player)
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end

	targetPlayer = player
	targetName = player and player.Name or nil

	if titleLabel then
		titleLabel.Text = player and ("Animation Inspector — " .. player.Name) or "Animation Inspector"
	end
	updateEmptyState()

	if not player then
		clearRows()
		return
	end

	charAddedConn = player.CharacterAdded:Connect(function(character)
		if running and targetPlayer == player then
			hookCharacter(character)
		end
	end)
	charRemovingConn = player.CharacterRemoving:Connect(function()
		if running and targetPlayer == player then
			clearRows()
		end
	end)

	hookCharacter(player.Character)
end

local function resolveByName(name)
	if not name or name == "" then
		return nil
	end
	for _, p in ipairs(Players:GetPlayers()) do
		if p.Name == name then
			return p
		end
	end
	local lower = string.lower(name)
	for _, p in ipairs(Players:GetPlayers()) do
		if string.lower(p.Name) == lower or string.lower(p.DisplayName) == lower then
			return p
		end
	end
	return nil
end

-- Public API
function AnimationInspector.startByName(name)
	local player = resolveByName(name)
	if not player then
		pcall(function()
			Library:Notify("Animation Inspector: pick a player first.", 4)
		end)
		pcall(function()
			local toggles = getgenv and getgenv().Toggles
			if toggles and toggles.AnimationInspector then
				toggles.AnimationInspector:SetValue(false)
			end
		end)
		return
	end

	running = true
	if loggingEnabled() then
		logBuffer = {}
		logFlushAccum = 0
		logSessionStart = os.clock()
		pcall(function()
			if writefile then
				writefile(LOG_FILE, string.format(
					"=== Animation Inspector log | target=%s | %s ===\n",
					player.Name, os.date("%Y-%m-%d %H:%M:%S")
				))
			end
		end)
	end
	buildWindow()
	if screenGui then
		screenGui.Enabled = true
	end
	installHook()
	startResolver()
	startUpdateLoop()
	bindPlayer(player)
end

function AnimationInspector.setTargetByName(name)
	if not running then
		return
	end
	local player = resolveByName(name)
	if player then
		bindPlayer(player)
	end
end

function AnimationInspector.stop()
	if not running then
		return
	end
	running = false

	if updateConn then
		pcall(function() updateConn:Disconnect() end)
		updateConn = nil
	end
	if animatorConn then
		pcall(function() animatorConn:Disconnect() end)
		animatorConn = nil
	end
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end

	clearRows()
	removeHook()
	flushLog()

	if screenGui then
		screenGui:Destroy()
		screenGui = nil
		mainFrame, titleLabel, subLabel, listFrame, emptyLabel = nil, nil, nil, nil, nil
	end

	targetPlayer = nil
	targetName = nil
end

-- Full teardown (script detach): tear everything down for good.
function AnimationInspector.detach()
	AnimationInspector.stop()
end

return AnimationInspector
end)()

end)
__bundle_register("@luma/Features/Combat/AutoDustlunge", function(require, _LOADED, __bundle_register, __bundle_modules)
local KeyHandling = require("@luma/Game/KeyHandling")

local InputClient = require("@luma/Game/InputClient")

local Latency = require("@luma/Game/Latency")

local Configuration = require("@luma/Utility/Configuration")

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local UserInputService = game:GetService("UserInputService")

local AutoDustlunge = {}

local HITBOX_SIZE = Vector3.new(2, 6, 10)
local HITBOX_SHIFT_BACK = -5
local TICK_INTERVAL = 1 / 5

local holdKeyPicker = nil
local running = false
local simulationPart = nil

function AutoDustlunge.setHoldKeyPicker(keyPicker)
	holdKeyPicker = keyPicker
end

local function cleanupSimulation()
	if simulationPart then
		simulationPart:Destroy()
		simulationPart = nil
	end
end

local function getEffectModule()
	local effectReplicator = ReplicatedStorage:FindFirstChild("EffectReplicator")
	return effectReplicator and require(effectReplicator)
end

local function setSprinting(state)
	local character = Players.LocalPlayer.Character
	local characterHandler = character and character:FindFirstChild("CharacterHandler")
	local requests = characterHandler and characterHandler:FindFirstChild("Requests")
	local sprintRemote = requests and requests:FindFirstChild("ServerSprint")
	if sprintRemote then
		sprintRemote:FireServer(state)
	end
end

local function runTick()
	local effectReplicatorModule = getEffectModule()
	if not effectReplicatorModule or effectReplicatorModule:FindEffect("GrabCD") then
		cleanupSimulation()
		return
	end

	local character = Players.LocalPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	local usedCFrame = root.CFrame * CFrame.new(0, 0, HITBOX_SHIFT_BACK)

	if not simulationPart or simulationPart.Parent ~= workspace then
		cleanupSimulation()
		simulationPart = Instance.new("Part")
		simulationPart.Name = "AutoDustlungeHitbox"
		simulationPart.Anchored = true
		simulationPart.CanCollide = false
		simulationPart.CanQuery = false
		simulationPart.CanTouch = false
		simulationPart.Material = Enum.Material.ForceField
		simulationPart.CastShadow = false
	end

	simulationPart.Transparency = Configuration.expectToggleValue("AutoDustlungeDebug") and 0.5 or 1.0
	simulationPart.Shape = Enum.PartType.Block
	simulationPart.Size = HITBOX_SIZE
	simulationPart.CFrame = usedCFrame
	simulationPart.Parent = workspace

	local live = workspace:FindFirstChild("Live")
	local instances = {}
	if live then
		for _, child in next, live:GetChildren() do
			if child ~= character then
				table.insert(instances, child)
			end
		end
	end

	if #instances <= 0 then
		return
	end

	local params = OverlapParams.new()
	params.FilterDescendantsInstances = instances
	params.FilterType = Enum.RaycastFilterType.Include

	local ok, parts = pcall(function()
		return workspace:GetPartsInPart(simulationPart, params)
	end)

	if not ok or not parts or #parts <= 0 then
		return
	end

	local targetCharacter = parts[1]:FindFirstAncestorWhichIsA("Model")
	local targetHumanoid = targetCharacter and targetCharacter:FindFirstChild("Humanoid")
	local targetRoot = targetCharacter and targetCharacter:FindFirstChild("HumanoidRootPart")
	if not targetHumanoid or not targetRoot then
		return
	end

	local facingDot = (targetRoot.Position - root.Position):Dot(root.CFrame.LookVector)
	if facingDot <= 0 then
		return
	end

	local sprinting = effectReplicatorModule:FindEffect("Sprinting") ~= nil
	if sprinting then
		setSprinting(false)
		task.wait(1 / 20)
	end

	local scriptCrouched = false
	if not effectReplicatorModule:FindEffect("Crouching") then
		InputClient.crouch()
		scriptCrouched = true
	end

	local start = tick()
	local pingWindow = (Latency.rtt() or 0) * 2
	repeat
		task.wait()
	until effectReplicatorModule:FindEffect("Crouching") or tick() - start > pingWindow

	if tick() - start > pingWindow then
		if scriptCrouched then
			InputClient.uncrouch()
		end
		if sprinting then
			setSprinting(true)
		end
		return
	end

	task.spawn(function()
		local remote = KeyHandling.getRemote("LeftClick")
		if not remote then
			return
		end

		remote:FireServer(false, Players.LocalPlayer:GetMouse().Hit, {
			S = false,
			NOAERIALS = true,
			Space = false,
			Right = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2),
			W = false,
			Left = true,
			ctrl = false,
		})
	end)

	task.wait(1 / 20)

	if scriptCrouched then
		InputClient.uncrouch()
	else
		local vim = Instance.new("VirtualInputManager")
		vim:SendKeyEvent(true, Enum.KeyCode.LeftControl, false, game)
		vim:SendKeyEvent(false, Enum.KeyCode.LeftControl, false, game)
	end

	if sprinting then
		setSprinting(true)
	end
end

local function loop()
	while running do
		if not holdKeyPicker or not holdKeyPicker:GetState() then
			cleanupSimulation()
		else
			local ok, err = pcall(runTick)
			if not ok then
				cleanupSimulation()
			end
		end

		task.wait(TICK_INTERVAL)
	end
end

function AutoDustlunge.enable()
	if running then
		return
	end

	cleanupSimulation()
	running = true
	task.spawn(loop)
end

function AutoDustlunge.disable()
	running = false
	cleanupSimulation()
end

return AutoDustlunge

end)
__bundle_register("@luma/Features/Combat/Defense", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Signal
local Signal = require("@luma/Utility/Signal")

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Features.Combat.Objects.AnimatorDefender
