end)

---@return boolean
StateListener.ccd = LPH_NO_VIRTUALIZE(function()
	return game.PlaceId == CHIME_ARENA_PLACE_ID and workspace.DistributedGameTime < 15
end)

---@param effect table
local onEffectReplicated = LPH_NO_VIRTUALIZE(function(effect)
	if Configuration.expectToggleValue("NoAttackingClientChecks") and table.find(ATTACK_EFFECT_CLASSES, effect.Class) then
		-- Off the dispatch callstack: EffectDispatcher.defer appends to a table here (no scheduler touch) and runs
		-- the removal on the Heartbeat pump, so effect:Remove never fires from inside the EffectAdded dispatch.
		EffectDispatcher.defer(function()
			effect:Remove(true)
		end)
	end

	if effect.Class == "Knocked" or effect.Class == "Ragdoll" then
		if Configuration.expectToggleValue("AutoRagdollRecover") then
			-- feint fires remotes -- run it on the Heartbeat pump, not synchronously on the dispatch callstack.
			EffectDispatcher.defer(InputClient.feint)
		end
	end

	if effect.Class == "MantraCasted" then
		-- Was TaskSpawner.spawn (= task.spawn) fired straight from the dispatch callstack on EVERY MantraCasted
		-- effect, toggle-checked only inside the thread -- an unconditional scheduler touch on the always-on effect
		-- path. Now we only enqueue (a table insert); the Heartbeat pump runs this body on its own thread.
		EffectDispatcher.defer(function()
			---@module Game.QueuedBlocking
			local QueuedBlocking = require("@luma/Game/QueuedBlocking")

			if not Configuration.expectToggleValue("AutoMantraFollowup") then
				return
			end

			local track = StateListener.lAnimationValidTrack
			if not track or not track.IsPlaying then
				return
			end

			local instance = StateListener.lMantraActivated
			if not instance then
				return
			end

			local faction = StateListener.lAnimFaction
			if not faction then
				return
			end

			if not instance.ToolTip:match("Press @Block@") then
				return
			end

			local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
			local effectReplicatorModule = require(effectReplicator)

			if
				Configuration.expectToggleValue("CheckIfMoveHit")
				and not effectReplicatorModule:FindEffect("DamagedAnother")
			then
				return
			end

			QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_NORMAL, "AutoMantraFollowup", nil)

			repeat
				task.wait()
			until os.clock() - StateListener.lAnimTimestamp >= (faction:when() + 0.100) - Latency.rtt()

			QueuedBlocking.stop("AutoMantraFollowup")
		end)
	end

	if effect.Class == "LightAttack" then
		stamps[effect] = os.clock()
	end

	if effect.Class == "Stun" then
		stamps[effect] = os.clock()
	end

	if effect.Class == "DodgeCool" then
		stamps[effect] = os.clock()
	end

	if effect.Class == "ParryCool" then
		stamps[effect] = os.clock()
	end

	if effect.Class == "Vented" then
		StateListener.lastVent = os.clock()
	end

	if effect.Class == "DelayedPayback" then
		StateListener.lastPaybackDelay = tick()
	end

	if effect.Class == "PerfectStack" then
		StateListener.chainStacks = 0
	end

	if effect.Class == "PerfectionCool" and StateListener.chainStacks then
		StateListener.chainStacks = math.min(StateListener.chainStacks + 1, 20)
	end
end)

---@param effect table
local onEffectRemoving = LPH_NO_VIRTUALIZE(function(effect)
	if effect.Class == "PerfectStack" then
		StateListener.chainStacks = nil
	end
end)

-- Disconnect helper that works for both real RBXScriptConnections and Deepwoken's custom signal connections.
-- EffectReplicator.EffectAdded/EffectRemoved are NOT RBXScriptSignals, so their connections are plain tables with
-- a :Disconnect (or :disconnect/:Destroy) method that Maid won't recognise on its own -- wrap them in a cleanup
-- function (which Maid does call) so a reconnect actually drops the old handlers instead of stacking duplicates.
local function markConnection(maid, connection)
	maid:mark(function()
		pcall(function()
			if type(connection) == "function" then
				connection()
			elseif typeof(connection) == "RBXScriptConnection" then
				connection:Disconnect()
			elseif type(connection) == "table" then
				local disconnect = connection.Disconnect or connection.disconnect or connection.Destroy
				if disconnect then
					disconnect(connection)
				end
			end
		end)
	end)

	return connection
end

function StateListener.init()
	-- Effects are handled through the shared EffectDispatcher: one EffectReplicator connection for the whole
	-- script (PR-style -- deferred + identity-8 added dispatch, inline removed, rebuilt on container clear/
	-- updatecontainer). We register our hooks here; EffectDispatcher.init() (called once from Luma.init after
	-- every always-on consumer has registered) does the connect + replay. EffectTimers tracking rides these hooks.
	EffectDispatcher.onReconnect(EffectTimers.clear)

	EffectDispatcher.hook("added", function(effect)
		EffectTimers.track(effect)
		onEffectReplicated(effect)
	end)

	EffectDispatcher.hook("removed", function(effect)
		EffectTimers.untrack(effect)
		onEffectRemoving(effect)
	end)

	-- Local-character animator listening. We only ever want the LOCAL player's OWN Animator -- it drives the
	-- AnimationPlayed timings this module reads -- and it appears once per respawn. This used to watch
	-- workspace.Live.DescendantAdded: a server-wide, recursive firehose (every nested part/bone/particle/sound of
	-- every entity in the server -- hundreds-to-thousands per second in a populated place), with a per-event
	-- IsA("Animator") routed back through our own game.__namecall hook and a setthreadidentity(8)+task.spawn per
	-- Animator. That is pure waste (we discard every descendant that isn't the local Animator) and the single
	-- biggest always-on luma-only engine interaction -- Project Rain runs nothing like it. Scope it to the local
	-- character instead, Project-Rain-style: find its Animator directly and rebind on every respawn, with the only
	-- fallback watch bounded to the local character's own descendants (tiny volume, self-terminating).
	local function bindLocalAnimator(character)
		if not character then
			return
		end

		local function tryBind()
			local animator = character:FindFirstChildWhichIsA("Animator", true)
			if not animator then
				return false
			end

			local animationPlayed = Signal.new(animator.AnimationPlayed)
			stateMaid["LocalPlayerAnimListener"] =
				animationPlayed:connect("StateListener_AnimationPlayed", onLocalAnimationPlayed)

			return true
		end

		if tryBind() then
			return
		end

		-- Animator not parented yet. Watch ONLY this character's own descendants (not the whole Live folder) until
		-- it appears, bind once, then drop the watch. Still inline -- no setthreadidentity, no task.spawn.
		local watch
		watch = character.DescendantAdded:Connect(function(descendant)
			if not descendant:IsA("Animator") then
				return
			end

			if tryBind() then
				pcall(function()
					watch:Disconnect()
				end)
			end
		end)

		stateMaid["LocalAnimatorWatch"] = function()
			pcall(function()
				watch:Disconnect()
			end)
		end
	end

	local localPlayer = players.LocalPlayer
	if localPlayer then
		bindLocalAnimator(localPlayer.Character)
		markConnection(stateMaid, localPlayer.CharacterAdded:Connect(bindLocalAnimator))
	end

	if not LPH_OBFUSCATED or shared.Luma.verbose then
		Logger.warn("StateListener initialized.")
	end
end

function StateListener.detach()
	stateMaid:clean()
	EffectTimers.detach()
end

return StateListener

end)
__bundle_register("@luma/Features/Combat/Targeting", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Glorified extended non-utility Entities file.
local Targeting = {}

local DEFAULT_KEYS = {
	fov = "FOVLimit",
	distance = "DistanceLimit",
	maxTargets = "MaxTargets",
	selectionType = "PlayerSelectionType",
}

---@module Utility.Configuration
local Configuration = require("@luma/Utility/Configuration")

---@module Game.PlayerScanning
local PlayerScanning = require("@luma/Game/PlayerScanning")

---@module Features.Combat.Objects.Target
local Target = require("@luma/Features/Combat/Objects/Target")

---@module Utility.Table
local Table = require("@luma/Utility/Table")

local players = game:GetService("Players")
local userInputService = game:GetService("UserInputService")

---@return Target[]
Targeting.viable = LPH_NO_VIRTUALIZE(function(keys)
	keys = keys or DEFAULT_KEYS

	local live = workspace:FindFirstChild("Live")
	if not live then
		return {}
	end

	local localCharacter = players.LocalPlayer.Character
	if not localCharacter then
		return {}
	end

	local localRootPart = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return {}
	end

	local currentCamera = workspace.CurrentCamera
	if not currentCamera then
		return {}
	end

	local targets = {}

	local fieldOfViewLimit = Configuration.expectOptionValue(keys.fov)
	local distanceLimit = Configuration.expectOptionValue(keys.distance)
	if not fieldOfViewLimit or not distanceLimit or fieldOfViewLimit <= 0 then
		return targets
	end

	local fieldOfViewCos = math.cos(math.rad(fieldOfViewLimit))

	for _, entity in next, live:GetChildren() do
		if entity == localCharacter then
			continue
		end

		local playerFromCharacter = players:GetPlayerFromCharacter(entity)
		if not playerFromCharacter and Configuration.expectToggleValue("IgnoreMobs") then
			continue
		end

		if playerFromCharacter and Configuration.expectToggleValue("IgnorePlayers") then
			continue
		end

		local humanoid = entity:FindFirstChildWhichIsA("Humanoid")
		if not humanoid then
			continue
		end

		local rootPart = entity:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			continue
		end

		if humanoid.Health <= 0 then
			continue
		end

		if
			playerFromCharacter
			and PlayerScanning.isAlly(playerFromCharacter)
			and Configuration.expectToggleValue("IgnoreAllies")
		then
			continue
		end

		local fieldOfViewToEntity =
			currentCamera.CFrame.LookVector:Dot((localRootPart.Position - rootPart.Position).Unit)

		if (fieldOfViewToEntity * -1) <= fieldOfViewCos then
			continue
		end

		local currentDistance = (rootPart.Position - localRootPart.Position).Magnitude
		if currentDistance > distanceLimit then
			continue
		end

		local mousePosition = userInputService:GetMouseLocation()
		local unitRay = workspace.CurrentCamera:ScreenPointToRay(mousePosition.X, mousePosition.Y)
		local distanceToCrosshair = unitRay:Distance(rootPart.Position)

		targets[#targets + 1] =
			Target.new(entity, humanoid, rootPart, distanceToCrosshair, fieldOfViewToEntity, currentDistance)
	end

	return targets
end)

---@return Target[]
Targeting.best = LPH_NO_VIRTUALIZE(function(keys)
	keys = keys or DEFAULT_KEYS

	local targets = Targeting.viable(keys)
	local sortType = Configuration.expectOptionValue(keys.selectionType)
	local sortFunction = nil

	if sortType == "Closest To Crosshair" then
		sortFunction = function(first, second)
			return first.dc < second.dc
		end
	end

	if sortType == "Closest In Distance" then
		sortFunction = function(first, second)
			return first.du < second.du
		end
	end

	if sortType == "Least Health" then
		sortFunction = function(first, second)
			return first.humanoid.Health < second.humanoid.Health
		end
	end

	if sortFunction then
		table.sort(targets, sortFunction)
	end

	return Table.slice(targets, 1, Configuration.expectOptionValue(keys.maxTargets))
end)

---@param model Model
---@return Target?
Targeting.find = LPH_NO_VIRTUALIZE(function(model, keys)
	for _, target in next, Targeting.best(keys) do
		if target.character ~= model then
			continue
		end

		return target
	end
end)

return Targeting

end)
__bundle_register("@luma/Features/Exploits/AnimationFlooder", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
-- Animation Flooder: plays the decoy attack-animation flood on a selected player's character.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

---@module Utility.Configuration
local Configuration = require("@luma/Utility/Configuration")
---@module GUI.Library
local Library = require("@luma/GUI/Library")

local AnimationFlooder = {}

-- Fallback pool if the timing store isn't populated yet (same ids the AP breaker uses).
local FALLBACK_IDS = {
	"rbxassetid://9726608174",
	"rbxassetid://111647546998749",
	"rbxassetid://5064195992",
	"rbxassetid://6607519294",
	"rbxassetid://7600160919",
}
local MOVE_TYPES = { M1 = true, Mantra = true, Critical = true }
local FLOOD_PRIORITY = Enum.AnimationPriority.Action
local MAX_POOL = 200

-- State.
local running = false
local targetPlayer = nil
local targetName = nil
local currentAnimator = nil
local trackPool = {}
local accumulator = 0
local poolCursor = 0
local renderConn = nil
local charAddedConn = nil
local charRemovingConn = nil

-- Helpers
local function getIntensity()
	local value = Configuration.expectOptionValue("AnimationFlooderIntensity")
	if type(value) ~= "number" then
		return 8
	end
	return value
end

-- Attack animation ids straight out of the timing store; fall back to the hard list.
local function collectAttackIds()
	local ids, seen = {}, {}
	pcall(function()
		local TimingStore = require("@luma/Game/Timings/SaveManager")
		local list = TimingStore.as:list()
		for _, entry in ipairs(list) do
			if MOVE_TYPES[entry.tag] then
				local id = entry:id()
				if type(id) == "string" and id:match("%d") and not seen[id] then
					seen[id] = true
					ids[#ids + 1] = id
				end
			end
		end
	end)
	if #ids == 0 then
		ids = FALLBACK_IDS
	end
	return ids
end

local function destroyPool()
	for _, track in ipairs(trackPool) do
		pcall(function() track:Stop(0); track:Destroy() end)
	end
	trackPool = {}
	poolCursor = 0
end

-- Load our decoy pool onto the TARGET's animator.
local function loadPool(animator, idList)
	destroyPool()
	if type(idList) ~= "table" or #idList == 0 then
		return
	end

	local targetSize = math.min(MAX_POOL, math.max(#idList, 20))
	local cursor, attempts, maxAttempts = 0, 0, targetSize + #idList + 8
	while #trackPool < targetSize and attempts < maxAttempts do
		attempts = attempts + 1
		cursor = cursor % #idList + 1
		local id = idList[cursor]
		if not string.find(id, "://", 1, true) then
			id = "rbxassetid://" .. id
		end
		local animation = Instance.new("Animation")
		animation.AnimationId = id
		local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
		if ok and track then
			track.Looped = false
			pcall(function() track.Priority = FLOOD_PRIORITY end)
			trackPool[#trackPool + 1] = track
		end
	end
end

-- Target binding
local function bindCharacter(character)
	currentAnimator = nil
	destroyPool()
	if not character then
		return
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if animator then
		currentAnimator = animator
		loadPool(animator, collectAttackIds())
		return
	end
	-- Character just spawned; wait for its Animator.
	task.spawn(function()
		local hum = character:WaitForChild("Humanoid", 5)
		local anim = hum and hum:WaitForChild("Animator", 5)
		if anim and running and targetPlayer and targetPlayer.Character == character then
			currentAnimator = anim
			loadPool(anim, collectAttackIds())
		end
	end)
end

local function bindPlayer(player)
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end

	targetPlayer = player
	targetName = player and player.Name or nil

	if not player then
		currentAnimator = nil
		destroyPool()
		return
	end

	charAddedConn = player.CharacterAdded:Connect(function(character)
		if running and targetPlayer == player then
			bindCharacter(character)
		end
	end)
	charRemovingConn = player.CharacterRemoving:Connect(function()
		if running and targetPlayer == player then
			currentAnimator = nil
			destroyPool()
		end
	end)

	bindCharacter(player.Character)
end

local function resolveByName(name)
	if not name or name == "" then
		return nil
	end
	for _, p in ipairs(Players:GetPlayers()) do
		if p.Name == name then
			return p
		end
	end
	local lower = string.lower(name)
	for _, p in ipairs(Players:GetPlayers()) do
		if string.lower(p.Name) == lower or string.lower(p.DisplayName) == lower then
			return p
		end
	end
	return nil
end

-- Flood loop
local function startLoop()
	if renderConn then
		return
	end
	renderConn = RunService.RenderStepped:Connect(function(deltaTime)
		if not running then
			return
		end
		local animator = currentAnimator
		if not animator or #trackPool == 0 then
			return
		end

		local interval = 1 / math.max(1, getIntensity())
		accumulator = math.min(accumulator + deltaTime, interval * 2)

		local burstsThisFrame = 0
		while accumulator >= interval and burstsThisFrame < 50 do
			accumulator = accumulator - interval
			burstsThisFrame = burstsThisFrame + 1

			-- Prefer an idle track; if all are mid-play, hard-restart the next one so a fresh AnimationPlayed still fires.
			local chosen = nil
			for _ = 1, #trackPool do
				poolCursor = poolCursor % #trackPool + 1
				local candidate = trackPool[poolCursor]
				if candidate and not candidate.IsPlaying then
					chosen = candidate
					break
				end
			end
			local recycled = false
			if not chosen then
				poolCursor = poolCursor % #trackPool + 1
				chosen = trackPool[poolCursor]
				recycled = chosen ~= nil
			end
			if chosen then
				pcall(function()
					if recycled then
						chosen:Stop(0)
					end
					chosen.Priority = FLOOD_PRIORITY
					chosen:Play(0.1, 1, 1)
				end)
			end
		end
	end)
end

-- Public API
function AnimationFlooder.startByName(name)
	local player = resolveByName(name)
	if not player then
		pcall(function() Library:Notify("Animation Flooder: pick a target player first.", 4) end)
		pcall(function()
			local toggles = getgenv and getgenv().Toggles
			if toggles and toggles.AnimationFlooder then
				toggles.AnimationFlooder:SetValue(false)
			end
		end)
		return
	end
	running = true
	startLoop()
	bindPlayer(player)
end

function AnimationFlooder.setTargetByName(name)
	if not running then
		return
	end
	local player = resolveByName(name)
	if player then
		bindPlayer(player)
	end
end

function AnimationFlooder.stop()
	if not running then
		return
	end
	running = false
	if renderConn then
		pcall(function() renderConn:Disconnect() end)
		renderConn = nil
	end
	if charAddedConn then
		pcall(function() charAddedConn:Disconnect() end)
		charAddedConn = nil
	end
	if charRemovingConn then
		pcall(function() charRemovingConn:Disconnect() end)
		charRemovingConn = nil
	end
	destroyPool()
	currentAnimator = nil
	targetPlayer = nil
	targetName = nil
	accumulator = 0
end

function AnimationFlooder.detach()
	AnimationFlooder.stop()
end

return AnimationFlooder
end)()

end)
__bundle_register("@luma/Features/Exploits/Exploits", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Utility.InstanceWrapper
local InstanceWrapper = require("@luma/Utility/InstanceWrapper")

local voidMaid = Maid.new()

local clientPart = Instance.new('Part')
local peer = gethiddenproperty(clientPart, "NetworkOwnerV3")
clientPart:Destroy()

local originalFPDH = workspace:GetAttribute("OriginalFPDH") or workspace.FallenPartsDestroyHeight
workspace.FallenPartsDestroyHeight = 0/0
workspace:SetAttribute("OriginalFPDH", originalFPDH)

---@param model Model
---@param part Part
local function voidPart(model, part)
    local targetY = (originalFPDH or -500) - 50

    if not part:FindFirstChild("BodyVelocity") then
        local partConstantVelocity = InstanceWrapper.create(voidMaid, part, "BodyVelocity", part)
        partConstantVelocity.MaxForce = Vector3.new(1/0, 1/0, 1/0)
        partConstantVelocity.Velocity = Vector3.new(0, -12500, 0)
        partConstantVelocity.P = 1/0
    end

    local velocityController = part:FindFirstChild("ControlVel")
        or part:FindFirstChild("SafetyBV")
        or part:FindFirstChild("SwimBV")
        or part:FindFirstChild("Holder")

    if velocityController and velocityController:IsA("BodyMover") then
        velocityController:Destroy()
    end

    part.CanCollide = false
    part.AssemblyLinearVelocity = Vector3.new(0, -12500, 0)

    local root = model:FindFirstChild("HumanoidRootPart")
    local posX = root and root.Position.X or part.Position.X
    local posZ = root and root.Position.Z or part.Position.Z
    
    part.CFrame = CFrame.new(posX, targetY, posZ)

    sethiddenproperty(part, "NetworkIsSleeping", false)
end

return LPH_NO_VIRTUALIZE(function()
	local Exploits = { forceVoid = false, ownershipTimestamp = 0, ownershipItem = nil, currentRootPart = nil }

	---@module Utility.Signal
	local Signal = require("@luma/Utility/Signal")

	---@module Utility.Configuration
	local Configuration = require("@luma/Utility/Configuration")

	---@module Utility.OriginalStore
	local OriginalStore = require("@luma/Utility/OriginalStore")

	---@module Features.Game.OwnershipWatcher
	local OwnershipWatcher = require("@luma/Features/Game/OwnershipWatcher")

	---@module Utility.Logger
	local Logger = require("@luma/Utility/Logger")

	---@module Features.Automation.EchoFarm
	local EchoFarm = require("@luma/Features/Automation/EchoFarm")

	local runService = game:GetService("RunService")
	local players = game:GetService("Players")
	local physicsService = game:GetService("PhysicsService")
	local replicatedStorage = game:GetService("ReplicatedStorage")

	local collisionGroupName = tostring(Exploits)

	local exploitsMaid = Maid.new()
	local pathfindBreakerMaid = Maid.new()

	local allowSleep = voidMaid:mark(OriginalStore.new())

	local heartbeat = Signal.new(runService.Heartbeat)
	local preRender = Signal.new(runService.PreRender)

	local lastVelocity = nil

	local lastVector = 1

	local function cleanVoidMobs()
		voidMaid:clean()
		allowSleep:restore()
	end

local function updateVoidMobs()
    local localPlayer = players.LocalPlayer
    sethiddenproperty(localPlayer, "MaxSimulationRadius", 3000)
    sethiddenproperty(localPlayer, "SimulationRadius", 3000)

    allowSleep:set(settings().Physics, "AllowSleep", false)

    for part, data in next, OwnershipWatcher.parts do
        local model = data.model
        if not model or not data.owned then continue end

        local success, ownerID = pcall(function()
            return gethiddenproperty(part, "NetworkOwnerV3")
        end)
        
        local isActuallyOwned = (success and ownerID == peer) or (part.ReceiveAge == 0)

        if isActuallyOwned then
            if model.Parent == workspace.Live and model.Name:sub(1,1) == "." then
                if model.Name:lower():find("chaser") and EchoFarm.voiding then continue end

                for _, instance in pairs(model:GetChildren()) do
                    if instance:IsA("BasePart") then
                        instance.CanCollide = false
                    end
                end
                
                voidPart(model, part)
            end
        end
    end
end

	local function getKnockedOwnershipItem()
		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		local backpack = localPlayer:FindFirstChild("Backpack")
		if not backpack then
			return
		end

		local selected = nil

		for _, item in pairs(backpack:GetChildren()) do
			if item.Name:match("Talent") then
				continue
			end

			if not item:IsA("Tool") then
				continue
			end

			if not item:FindFirstChildOfClass("BasePart") then
				continue
			end

			selected = item
		end

		if not selected then
			selected = localPlayer.Character and localPlayer.Character:FindFirstChild("Weapon")
			selected = selected or backpack:FindFirstChild("Weapon")
		end

		return selected
	end

	local function updateMoveWhileKnocked()
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = require(effectReplicator)

		if not effectReplicatorModule:FindEffect("Knocked") then
			return
		end

		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		local character = localPlayer.Character
		if not character then
			return
		end

		local rootPart = character:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			return
		end

		local humanoid = character:FindFirstChild("Humanoid")
		if not humanoid then
			return
		end

		local backpack = localPlayer:FindFirstChild("Backpack")
		if not backpack then
			return
		end

		local ownershipItem = Exploits.ownershipItem or getKnockedOwnershipItem()
		if not ownershipItem then
			return
		end

		if not Exploits.ownershipItem or not Exploits.ownershipItem:IsDescendantOf(game) then
			Exploits.ownershipItem = ownershipItem
		end

		if tick() - Exploits.ownershipTimestamp <= 0.15 then
			return
		end

		local leftHand = character:FindFirstChild("LeftHand")
		local rightHand = character:FindFirstChild("RightHand")
		local hasHandWeapon = (leftHand and leftHand:FindFirstChild("HandWeapon"))
			or (rightHand and rightHand:FindFirstChild("HandWeapon"))

		if not hasHandWeapon then
			local thrown = workspace:FindFirstChild("Thrown")
			local attach = thrown and thrown:FindFirstChild("Attach_" .. character.Name)
			hasHandWeapon = attach and attach:FindFirstChild("HandWeapon")
		end

		local characterHandler = character:FindFirstChild("CharacterHandler")
		local requests = characterHandler and characterHandler:FindFirstChild("Requests")
		local equipWeapon = requests and requests:FindFirstChild("EquipWeapon")

		if ownershipItem.Name == "Weapon" and hasHandWeapon then
			return equipWeapon and equipWeapon:FireServer(false)
		end

		if ownershipItem.Name == "Weapon" and not hasHandWeapon then
			return equipWeapon and equipWeapon:FireServer(true)
		end

		if ownershipItem.Parent == character then
			return humanoid:UnequipTools()
		end

		if ownershipItem.Parent == backpack then
			humanoid:EquipTool(ownershipItem)
		end

		Exploits.ownershipTimestamp = tick()
	end

	local function updateFlingHeartbeat()
		local character = players.LocalPlayer.Character
		if not character then
			return
		end

		local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
		if not humanoidRootPart then
			return
		end

		-- Reference fling: dump a constant huge downward velocity onto the root every frame. Collision pins
		-- us in place while that replicated velocity launches anyone who touches us. (FallenPartsDestroyHeight
		-- is already forced to NaN globally at the top of this module, so flung players don't void-destroy.)
		-- A farm can crank the fling for one fight (the Titus farms do, on the boss) by setting
		-- shared.Luma.aggressiveFling; otherwise it uses the user's FlingPower slider.
		local power = (shared.Luma and shared.Luma.aggressiveFling)
			or Configuration.expectOptionValue("FlingPower")
			or 100000
		humanoidRootPart.AssemblyLinearVelocity = Vector3.new(16, -power, -16)
	end

	local function updateExploits()
		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		if Configuration.expectToggleValue("VoidMobs") then
			updateVoidMobs()
		else
			cleanVoidMobs()
		end

		if Configuration.expectToggleValue("MoveWhileKnocked") then
			updateMoveWhileKnocked()
		end

		if EchoFarm.voiding or Configuration.expectToggleValue("Fling") then
			updateFlingHeartbeat()
		end
	end

	-- (The old PreRender velocity-restore is gone: Fling keeps a constant velocity each frame instead of
	-- snapshotting + restoring it, which is what makes it actually fling rather than just break pathfinding.)

	function Exploits.init()
		exploitsMaid:add(heartbeat:connect("Exploits_Heartbeat", updateExploits))

		---@note: Wrapped in a PCall to prevent errors.
		pcall(function()
			physicsService:RegisterCollisionGroup(collisionGroupName)
			physicsService:CollisionGroupSetCollidable(collisionGroupName, collisionGroupName, false)
			physicsService:CollisionGroupSetCollidable(collisionGroupName, "Default", false)
			physicsService:CollisionGroupSetCollidable(collisionGroupName, "Player", false)
			physicsService:CollisionGroupSetCollidable(collisionGroupName, "WalkThrough", false)
		end)

		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("Exploits initialized.")
		end
	end

	function Exploits.detach()
		exploitsMaid:clean()
		voidMaid:clean()
		pathfindBreakerMaid:clean()

		Logger.warn("Exploits detached.")
	end

	return Exploits
end)()

end)
