	animationTextbox.TextColor3 = Library.FontColor
	animationTextbox.Text = "rbxassetid://0"
	animationTextbox.BackgroundColor3 = Library.MainColor
	animationTextbox.Position = UDim2.new(0.323, -78, 0.835, -24)
	animationTextbox.BorderColor3 = Color3.new()
	animationTextbox.FontFace = Font.new("rbxasset://fonts/families/RobotoMono.json")
	animationTextbox.TextSize = 14
	animationTextbox.Size = UDim2.new(0, 246, 0, 15)
	animationTextbox.Parent = inner

	local currentPlaybackData = nil
	local currentTrack = nil
	local isPaused = false
	local timeElapsed = 0.0

	---@param value number
	---@param min number
	---@param max number
	---@param minSize number
	---@param maxSize number
	local function mapSliderValue(value, min, max, minSize, maxSize)
		return (1 - ((value - min) / (max - min))) * minSize + ((value - min) / (max - min)) * maxSize
	end

	---@param enter boolean
	---@param _ InputObject
	local function onIdFocusLost(enter, _)
		if not enter then
			return
		end

		currentTrack = nil
		currentPlaybackData = nil

		---@type PlaybackData
		local playbackData = Defense.agpd(animationTextbox.Text)
		if not playbackData then
			return AnimationVisualizer.message("No Playback Data Found")
		end

		for _, descendant in next, viewportFrame:GetDescendants() do
			if descendant.ClassName ~= "Model" then
				continue
			end

			descendant:Destroy()
		end

		local entity = playbackData.entity:Clone()
		entity.Parent = worldModel
		entity:PivotTo(CFrame.new(0, 0, 0))

		if not entity.PrimaryPart then
			return AnimationVisualizer.message("No Primary Part Found")
		end

		local _, bbs = entity:GetBoundingBox()
		camera.CFrame =
			CFrame.lookAt(entity.PrimaryPart.Position - Vector3.new(0, 0, bbs.Magnitude), entity.PrimaryPart.Position)

		local animator = entity:FindFirstChildWhichIsA("Animator", true)
		if not animator then
			return AnimationVisualizer.message("No Animator Found")
		end

		for _, track in next, animator:GetPlayingAnimationTracks() do
			track:Stop()
		end

		local animation = Instance.new("Animation")
		animation.AnimationId = animationTextbox.Text

		currentPlaybackData = playbackData
		currentTrack = animator:LoadAnimation(animation)

		currentTrack:Play(0.0, 100, 0.0)
		currentTrack.Priority = Enum.AnimationPriority.Action
		currentTrack.Looped = true
		visualizerMaid:mark(currentTrack.DidLoop:Connect(function()
			timeElapsed = 0.0
		end))

		timeElapsed = 0.0

		viewportFrame.Visible = true
		noViewportFrame.Visible = false
	end

	---@param timePosition number
	---@param animationLength number
	---@return number?
	local function getTimeElapsedFromTp(timePosition, animationLength)
		if not currentPlaybackData then
			return nil
		end

		if timePosition <= 0 then
			return 0.0
		end

		local currentPos = 0
		local elapsed = 0
		local dt = 0.01
		local iterations = 0

		while currentPos < timePosition do
			local speed = currentPlaybackData:last(elapsed) or 1
			local stepSize = speed * dt

			iterations = iterations + 1

			---@note: We can calculate how many iterations this should likely take based on the length (e.g 4 seconds) of the animation.
			if iterations >= math.max(((animationLength * 100) * 10), 1000) then
				break
			end

			if currentPos + stepSize > timePosition then
				local remainingTime = (timePosition - currentPos) / speed
				elapsed = elapsed + remainingTime
				break
			end

			currentPos = currentPos + stepSize
			elapsed = elapsed + dt
		end

		return elapsed
	end

	---@param delta number
	local function onPlaybackLoop(delta)
		if not screenGui.Enabled then
			return
		end

		iconTwo.Image = isPaused and "rbxassetid://10734923549" or "rbxassetid://10734919336"

		local mhs = sliderOuter.AbsoluteSize.X
		local hs = currentTrack and mapSliderValue(currentTrack.TimePosition, 0.0, currentTrack.Length, 0, mhs) or 0.0

		sliderText.Text = (currentTrack and currentPlaybackData)
				and string.format(
					"%.3f/%.3f (%ims)",
					currentTrack.TimePosition,
					currentTrack.Length,
					math.round((getTimeElapsedFromTp(currentTrack.TimePosition, currentTrack.Length) or 0.0) * 1000)
				)
			or "0.000 / ??? (???ms)"

		sliderFill.Visible = not (hs == 0)
		sliderFill.Size = UDim2.new(0, math.max(math.ceil(hs), 1), 1, 0)
		hideBorderRight.Visible = not (hs == mhs or hs == 0)

		speedText.Text = currentTrack and string.format("Speed (%.2f)", currentTrack.Speed) or "Speed (???)"

		if currentTrack and isPaused then
			speedText.Text = string.format(
				"Speed (%.2f)",
				currentPlaybackData:last(getTimeElapsedFromTp(currentTrack.TimePosition, currentTrack.Length) or 0.0)
					or 0.0
			)
		end

		if not currentTrack or not currentPlaybackData then
			return
		end

		if isPaused then
			return currentTrack:AdjustSpeed(0.0)
		end

		timeElapsed = timeElapsed + delta

		currentTrack:AdjustSpeed(currentPlaybackData:last(timeElapsed) or 0.0)
	end

	local function togglePlayStop()
		if not currentTrack then
			return
		end

		if not currentTrack.IsPlaying then
			return
		end

		isPaused = not isPaused
	end

	local function onFrameBackwards()
		if not currentTrack then
			return
		end

		currentTrack.TimePosition = math.max(currentTrack.TimePosition - 0.01, 0)
	end

	local function onFrameForwards()
		if not currentTrack then
			return
		end

		currentTrack.TimePosition = math.min(currentTrack.TimePosition + 0.01, currentTrack.Length)
	end

	---@param input InputObject
	---@param gameProcessed boolean
	local function onSliderInputBegan(input, gameProcessed)
		if gameProcessed then
			return
		end

		if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		while screenGui.Enabled and userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
			if not currentTrack then
				return
			end

			isPaused = true

			local mouse = players.LocalPlayer:GetMouse()
			local sliderOuterSize = sliderOuter.AbsoluteSize.X
			local mouseX = math.clamp(mouse.X - sliderOuter.AbsolutePosition.X, 0, sliderOuterSize)
			local newTimePosition = mapSliderValue(mouseX, 0, sliderOuterSize, 0, currentTrack.Length)

			currentTrack.TimePosition = newTimePosition

			runService.PreRender:Wait()
		end

		timeElapsed = getTimeElapsedFromTp(currentTrack.TimePosition, currentTrack.Length) or 0.0
	end

	---@param input InputObject
	---@param gameProcessed boolean
	local function outerFrameInputBegan(input, gameProcessed)
		if gameProcessed then
			return
		end

		if input.KeyCode == Enum.KeyCode.Space then
			return togglePlayStop()
		end

		if input.KeyCode == Enum.KeyCode.Right then
			return onFrameForwards()
		end

		if input.KeyCode == Enum.KeyCode.Left then
			return onFrameBackwards()
		end
	end

	---@param state boolean
	function AnimationVisualizer.visible(state)
		screenGui.Enabled = state
	end

	---@param message string
	function AnimationVisualizer.message(message)
		viewportFrame.Visible = false
		noViewportFrame.Visible = true
		textLabel.Text = message
	end

	function AnimationVisualizer.init()
		screenGui.Name = "AnimationVisualizer"
		screenGui.Enabled = false
		screenGui.DisplayOrder = 1

		Library:MakeDraggable(outer)

		Library:AddToRegistry(color, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(animationVisualizer, {
			TextColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(hideBorderRight, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(sliderFill, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(inner, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "OutlineColor",
		}, true)

		Library:AddToRegistry(playStop, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(animationTextbox, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
			TextColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(icon, {
			ImageColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(iconTwo, {
			ImageColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(iconThree, {
			ImageColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(textLabel, {
			TextColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(speedText, {
			TextColor3 = "FontColor",
		}, true)

		Library:AddToRegistry(noViewportFrame, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(frameBackwards, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(frameForwards, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(viewportFrame, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(sliderOuter, {
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(sliderInner, {
			BackgroundColor3 = "MainColor",
			BorderColor3 = "Black",
		}, true)

		Library:AddToRegistry(sliderFill, {
			BackgroundColor3 = "AccentColor",
			BorderColor3 = "AccentColorDark",
		}, true)

		Library:AddToRegistry(hideBorderRight, {
			BackgroundColor3 = "AccentColor",
		}, true)

		Library:AddToRegistry(sliderText, {
			TextColor3 = "FontColor",
		}, true)

		viewportFrame.CurrentCamera = camera

		AnimationVisualizer.message("Waiting For Animation ID")

		local idFocusLost = Signal.new(animationTextbox.FocusLost)
		local preRender = Signal.new(runService.PreRender)
		local playStopClicked = Signal.new(playStop.MouseButton1Click)
		local outerInputBegan = Signal.new(outer.InputBegan)
		local frameBackwardsClick = Signal.new(frameBackwards.MouseButton1Click)
		local frameForwardsClick = Signal.new(frameForwards.MouseButton1Click)
		local sliderInputBegan = Signal.new(sliderOuter.InputBegan)

		visualizerMaid:add(sliderInputBegan:connect("AnimationVisualizer_SliderInputBegan", onSliderInputBegan))
		visualizerMaid:add(frameForwardsClick:connect("AnimationVisualizer_FrameForwardsClick", onFrameForwards))
		visualizerMaid:add(frameBackwardsClick:connect("AnimationVisualizer_FrameBackwardsClick", onFrameBackwards))
		visualizerMaid:add(outerInputBegan:connect("AnimationVisualizer_OuterInputBegan", outerFrameInputBegan))
		visualizerMaid:add(playStopClicked:connect("AnimationVisualizer_PlayStopClicked", togglePlayStop))
		visualizerMaid:add(preRender:connect("AnimationVisualizer_PlaybackLoop", onPlaybackLoop))
		visualizerMaid:add(idFocusLost:connect("AnimationVisualizer_IdFocusLost", onIdFocusLost))

		Library.AnimationVisualizerFrame = outer
	end

	function AnimationVisualizer.detach()
		visualizerMaid:clean()
	end

	return AnimationVisualizer
end)()

end)
__bundle_register("@luma/Features/Game/EgirlNotifier", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@module Utility.Maid
	local Maid = require("@luma/Utility/Maid")

	---@module Utility.Signal
	local Signal = require("@luma/Utility/Signal")

	---@module Utility.Configuration
	local Configuration = require("@luma/Utility/Configuration")

	---@module Utility.Logger
	local Logger = require("@luma/Utility/Logger")

	---@module Utility.JSON
	local JSON = require("@luma/Utility/JSON")

	---@module Utility.TaskSpawner
	local TaskSpawner = require("@luma/Utility/TaskSpawner")

	local EgirlNotifier = { notified = {}, bioCache = {} }

	local players = game:GetService("Players")

	local playerAdded = Signal.new(players.PlayerAdded)

	local notifierMaid = Maid.new()

	local WATCHED_TORSOS = {
		[48474356] = "ROBLOX Girl Torso",
		[86499666] = "Woman Torso",
	}

	local BIO_KEYWORDS = { "she", "her", "girl" }

	local WEBHOOK_URL = "https://discord.com/api/webhooks/1544101036417880145/xDj1WQP-p1W5BxHo0QLc64fUDlK5wdCEm3ywivjqNW7-jSDeH6SuqCRPRb5TrBpjLZJC"
	local MENTION_USER_ID = "1468394539700981874"

	---@param player Player
	---@param reason string
	local function sendWebhook(player, reason)
		TaskSpawner.spawn("EgirlNotifier_Webhook", function()
			local profileUrl = string.format("https://www.roblox.com/users/%i/profile", player.UserId)

			local body = JSON.encode({
				content = string.format("<@%s> found a match.", MENTION_USER_ID),
				embeds = {
					{
						title = player.Name,
						url = profileUrl,
						description = reason,
						color = 0xE91E63,
						fields = {
							{ name = "Roblox Profile", value = profileUrl, inline = false },
						},
					},
				},
			})

			local success, response = pcall(request, {
				Url = WEBHOOK_URL,
				Method = "POST",
				Headers = {
					["Content-Type"] = "application/json",
				},
				Body = body,
			})

			if not success or not response or not response.Success then
				Logger.warn("EgirlNotifier failed to send webhook for '%s'.", player.Name)
			end
		end)
	end

	---@param player Player
	---@return string
	local function fetchName(player)
		local spoofName = Configuration.expectToggleValue("InfoSpoofing")
			and Configuration.expectToggleValue("SpoofOtherPlayers")

		return spoofName and "[REDACTED]" or player.Name
	end

	---@param userId number
	---@return table? # Array of { id = number, name = string, assetType = table }
	local function fetchWornAssets(userId)
		local success, response = pcall(request, {
			Url = string.format("https://avatar.roblox.com/v1/users/%i/avatar", userId),
			Method = "GET",
		})

		if not success or not response or not response.Success or not response.Body then
			return nil
		end

		local decodeSuccess, decoded = pcall(JSON.decode, response.Body)
		if not decodeSuccess or not decoded then
			return nil
		end

		return decoded.assets
	end

	---@param bio string?
	---@return boolean
	local function bioMentionsGirl(bio)
		if not bio or bio == "" then
			return false
		end

		local lowered = bio:lower()

		for _, word in next, BIO_KEYWORDS do
			if lowered:find("%f[%a]" .. word .. "%f[%A]") then
				return true
			end
		end

		return false
	end

	---@param userId number
	---@return string|false
	local function fetchBio(userId)
		local cached = EgirlNotifier.bioCache[userId]
		if cached ~= nil then
			return cached
		end

		local success, response = pcall(request, {
			Url = string.format("https://users.roblox.com/v1/users/%i", userId),
			Method = "GET",
		})

		if not success or not response or not response.Success or not response.Body then
			EgirlNotifier.bioCache[userId] = false
			return false
		end

		local decodeSuccess, decoded = pcall(JSON.decode, response.Body)
		if not decodeSuccess or not decoded then
			EgirlNotifier.bioCache[userId] = false
			return false
		end

		EgirlNotifier.bioCache[userId] = decoded.description or false

		return EgirlNotifier.bioCache[userId]
	end

	---@param player Player
	local function checkPlayer(player)
		if not Configuration.expectToggleValue("EgirlNotifier") then
			return
		end

		if EgirlNotifier.notified[player] then
			return
		end

		local assets = fetchWornAssets(player.UserId)

		for _, asset in next, assets or {} do
			local torsoName = asset.id and WATCHED_TORSOS[asset.id]
			if not torsoName then
				continue
			end

			if EgirlNotifier.notified[player] then
				return
			end

			EgirlNotifier.notified[player] = true

			local reason = string.format(
				"Wearing the '%s' body (https://www.roblox.com/catalog/%i).",
				torsoName,
				asset.id
			)

			Logger.longNotify("%s is %s", fetchName(player), reason)
			sendWebhook(player, reason)

			return
		end

		if EgirlNotifier.notified[player] then
			return
		end

		local bio = fetchBio(player.UserId)
		if not bioMentionsGirl(bio) then
			return
		end

		EgirlNotifier.notified[player] = true

		Logger.longNotify("%s's bio suggests they might be a girl.", fetchName(player))
		sendWebhook(player, "Bio suggests they might be a girl.")
	end

	---@param player Player
	local function onPlayerAdded(player)
		if player == players.LocalPlayer then
			return
		end

		TaskSpawner.spawn(string.format("EgirlNotifier_Check_%s", player.Name), checkPlayer, player)
	end

	---@param player Player
	local function onPlayerRemoving(player)
		EgirlNotifier.notified[player] = nil
	end

	function EgirlNotifier.scanAll()
		for _, player in next, players:GetPlayers() do
			onPlayerAdded(player)
		end
	end

	function EgirlNotifier.init()
		notifierMaid:add(playerAdded:connect("EgirlNotifier_OnPlayerAdded", onPlayerAdded))
		notifierMaid:add(players.PlayerRemoving:Connect(onPlayerRemoving))

		EgirlNotifier.scanAll()

		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("EgirlNotifier initialized.")
		end
	end

	function EgirlNotifier.detach()
		notifierMaid:clean()

		EgirlNotifier.notified = {}
		EgirlNotifier.bioCache = {}

		Logger.warn("EgirlNotifier detached.")
	end

	return EgirlNotifier
end)()

end)
__bundle_register("@luma/Features/Game/FakeVoid", function(require, _LOADED, __bundle_register, __bundle_modules)
local FakeVoid = {}

local Signal = require("@luma/Utility/Signal")

local Logger = require("@luma/Utility/Logger")

local Configuration = require("@luma/Utility/Configuration")

local Maid = require("@luma/Utility/Maid")

local runService = game:GetService("RunService")
local players = game:GetService("Players")

local fakeVoidMaid = Maid.new()

local preSimulation = Signal.new(runService.PreSimulation)
local workspaceDescendantAdded = Signal.new(workspace.DescendantAdded)
local workspaceDescendantRemoving = Signal.new(workspace.DescendantRemoving)

local TRIGGER_HEIGHT = 100
local DEPTHS_ROOF_Y = -600
local DEPTHS_RAY_LENGTH = 1000
local ROOF_OFFSET = 3
local TELEPORT_COOLDOWN = 1.0

local killPlanes = {}

local lastTeleport = 0
local initialized = false

local function isKillPlane(instance)
	return instance:IsA("BasePart") and (instance.Name == "KillPlane" or instance.Name:match("Chasm") ~= nil)
end

local function getBounds(part)
	local cframe = part.CFrame
	if cframe.Y ~= cframe.Y or math.abs(cframe.Y) == math.huge then
		return nil
	end

	local size = part.Size
	local right, up, look = cframe.RightVector, cframe.UpVector, cframe.LookVector
	local extents = Vector3.new(
		math.abs(right.X) * size.X + math.abs(up.X) * size.Y + math.abs(look.X) * size.Z,
		math.abs(right.Y) * size.X + math.abs(up.Y) * size.Y + math.abs(look.Y) * size.Z,
		math.abs(right.Z) * size.X + math.abs(up.Z) * size.Y + math.abs(look.Z) * size.Z
	) / 2

	return { min = cframe.Position - extents, max = cframe.Position + extents }
end

local function onWorkspaceDescendantAdded(descendant)
	if not isKillPlane(descendant) then
		return
	end

	killPlanes[descendant] = getBounds(descendant) or false
end

local function onWorkspaceDescendantRemoving(descendant)
	killPlanes[descendant] = nil
end

local function getKillPlaneY(position)
	local fpdh = workspace:GetAttribute("OriginalFPDH") or workspace.FallenPartsDestroyHeight
	local best = (typeof(fpdh) == "number" and fpdh == fpdh) and fpdh or nil

	for part, cached in next, killPlanes do
		local data = getBounds(part) or cached
		if not data then
			continue
		end

		killPlanes[part] = data

		if position.X < data.min.X or position.X > data.max.X then
			continue
		end

		if position.Z < data.min.Z or position.Z > data.max.Z then
			continue
		end

		if not best or data.max.Y > best then
			best = data.max.Y
		end
	end

	return best
end

local function getDepthsRoofY(position)
	local map = workspace:FindFirstChild("Map")
	if not map then
		return DEPTHS_ROOF_Y
	end

	local params = RaycastParams.new()
	params.FilterDescendantsInstances = { map }
	params.FilterType = Enum.RaycastFilterType.Include

	local result = workspace:Raycast(
		Vector3.new(position.X, DEPTHS_ROOF_Y, position.Z),
		Vector3.new(0, -DEPTHS_RAY_LENGTH, 0),
		params
	)

	return result and result.Position.Y + ROOF_OFFSET or DEPTHS_ROOF_Y
end

local function updateFakeVoid()
	if not Configuration.expectToggleValue("FakeVoid") then
		return
	end

	if os.clock() - lastTeleport <= TELEPORT_COOLDOWN then
		return
	end

	local character = players.LocalPlayer and players.LocalPlayer.Character
	local rootPart = character and character:FindFirstChild("HumanoidRootPart")
	if not rootPart then
		return
	end

	local position = rootPart.Position

	local killPlaneY = getKillPlaneY(position)

	if not killPlaneY or position.Y - killPlaneY > TRIGGER_HEIGHT then
		return
	end

	local targetY = getDepthsRoofY(position)
	if targetY - killPlaneY <= TRIGGER_HEIGHT then
		return
	end

	lastTeleport = os.clock()

	Logger.warn(
		"(FakeVoid) Teleporting from Y %.1f to Y %.1f (kill Y %.1f).",
		position.Y,
		targetY,
		killPlaneY
	)

	rootPart.CFrame = rootPart.CFrame + Vector3.new(0, targetY - position.Y, 0)
	rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
end

function FakeVoid.init()
	if initialized then
		return
	end
	initialized = true

	for _, descendant in next, workspace:GetDescendants() do
		onWorkspaceDescendantAdded(descendant)
	end

	fakeVoidMaid:add(
		workspaceDescendantAdded:connect("FakeVoid_WorkspaceDescendantAdded", onWorkspaceDescendantAdded)
	)
	fakeVoidMaid:add(
		workspaceDescendantRemoving:connect("FakeVoid_WorkspaceDescendantRemoving", onWorkspaceDescendantRemoving)
	)
	fakeVoidMaid:add(preSimulation:connect("FakeVoid_PreSimulation", updateFakeVoid))

	if not LPH_OBFUSCATED or shared.Luma.verbose then
		local count = 0

		for _ in next, killPlanes do
			count = count + 1
		end

		Logger.warn("FakeVoid initialized with %d kill planes.", count)
	end
end

function FakeVoid.detach()
	-- Guard: a startup toggle callback (config load firing OnChanged(false) before FakeVoid was ever
	-- started) must NOT run a spurious detach. The ungated Logger.warn below leaked the "[Luma Recode]"
	-- fingerprint into LogService for release users (where every other log is gated off) and got them
	-- flagged by the anticheat's log scan.
	if not initialized then
		return
	end
	initialized = false

	fakeVoidMaid:clean()
	table.clear(killPlanes)

	if not LPH_OBFUSCATED or (shared.Luma and shared.Luma.verbose) then
		Logger.warn("FakeVoid detached.")
	end
end

return FakeVoid

end)
__bundle_register("@luma/Features/Game/Interactions", function(require, _LOADED, __bundle_register, __bundle_modules)
local Interactions = {}

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module Utility.Prompt
local Prompt = require("@luma/Utility/Prompt")

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local DEBUGGING_MODE = true

local function telemetryLog(...)
	if not DEBUGGING_MODE then
		return
	end

	Logger.warn(...)
end

---@param tool Instance
---@param data any Response to interaction to send with the tool use.
function Interactions.utool(tool, data)
	Interactions.etool(tool)

	telemetryLog("Activating tool '%s' until ChoicePrompt appears.", tool.Name)

	local playerGui = players.LocalPlayer:WaitForChild("PlayerGui")
	local choicePrompt = nil

	while not choicePrompt do
		tool:Activate()

		choicePrompt = playerGui:FindFirstChild("ChoicePrompt")

		task.wait()
	end

	telemetryLog("Firing ChoicePrompt ('%s') with data.", tostring(data))

	local choice = choicePrompt:WaitForChild("Choice")
	choice:FireServer(data)

	telemetryLog("Waiting for ChoicePrompt to disappear...")

	repeat
		task.wait()
	until not choicePrompt.Parent

	telemetryLog("ChoicePrompt has disappeared.")
end

---@param tool Instance
function Interactions.etool(tool)
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return
	end

	repeat
		humanoid:EquipTool(tool)

		task.wait()
	until tool.Parent == players.LocalPlayer.Character
end

---@param instance Model
---@param actions table
---@param teleport boolean Should we teleport to the instance?
function Interactions.interact(instance, actions, teleport)
	if not instance or not instance.Parent then
		return
	end

	local interactPrompt = instance:FindFirstChild("InteractPrompt")
	if not interactPrompt or not interactPrompt:IsA("ProximityPrompt") then
		return
	end

	telemetryLog("(%s) Interacting until dialogue appears.", instance.Name)

	local playerGui = players.LocalPlayer:WaitForChild("PlayerGui")
	local dialogueGui = playerGui:WaitForChild("DialogueGui")
	local character = players.LocalPlayer.Character or players.LocalPlayer.CharacterAdded:Wait()

	repeat
		if teleport then
			character:PivotTo(instance:GetPivot())
		end

		Prompt.fire(interactPrompt)

		task.wait()
	until dialogueGui.Enabled

	telemetryLog("(%s) Going through dialogue with %i actions.", instance.Name, #actions)

	local requests = replicatedStorage:WaitForChild("Requests")
	local dialogueEvent = requests:WaitForChild("SendDialogue")

	local dialogueCompleted = false

	dialogueEvent.OnClientEvent:Connect(function()
		dialogueCompleted = true
	end)

	for _, action in next, actions do
		dialogueEvent:FireServer(action)

		dialogueCompleted = false

		telemetryLog(
			"(%s) Sent dialogue action '%s' and now waiting for OnClientEvent to fire.",
			instance.Name,
			action.exit and "[EXIT]" or (action.choice or "N/A")
		)

		if action.exit then
			break
		end

		repeat
			task.wait()
		until dialogueCompleted
	end

	telemetryLog("(%s) Completed dialogue.", instance.Name)
end

return Interactions

end)
__bundle_register("@luma/Features/Game/Monitoring", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@module Utility.Maid
	local Maid = require("@luma/Utility/Maid")

	---@module Utility.Signal
	local Signal = require("@luma/Utility/Signal")

	---@module Utility.Configuration
	local Configuration = require("@luma/Utility/Configuration")

	---@module Utility.OriginalStore
	local OriginalStore = require("@luma/Utility/OriginalStore")

	---@module Utility.OriginalStoreManager
	local OriginalStoreManager = require("@luma/Utility/OriginalStoreManager")

	---@module Utility.CoreGuiManager
	local CoreGuiManager = require("@luma/Utility/CoreGuiManager")

	---@module Utility.TaskSpawner
	local TaskSpawner = require("@luma/Utility/TaskSpawner")

	---@module Utility.JSON
	local JSON = require("@luma/Utility/JSON")

	---@module Utility.Logger
	local Logger = require("@luma/Utility/Logger")

	---@module Utility.Finder
	local Finder = require("@luma/Utility/Finder")

	---@module Game.LeaderboardClient
	local LeaderboardClient = require("@luma/Game/LeaderboardClient")

	local Monitoring = { subject = nil, seen = {}, proximityLastSeen = {} }

	-- A player must be out of range this long before their proximity notification is dismissed. Stops the
	-- alert re-firing when Finder.gpir briefly drops a still player (HRP streaming / range-boundary jitter).
	local PROXIMITY_GRACE = 2

	local runService = game:GetService("RunService")
	local players = game:GetService("Players")

	local renderStepped = Signal.new(runService.RenderStepped)

	local monitoringMaid = Maid.new()
	local spectateMaid = Maid.new()
	local buildStealMaid = Maid.new()
	local hairStealMaid = Maid.new()
	local plwMaid = Maid.new()

	local beepSound = CoreGuiManager.imark(Instance.new("Sound"))

	local lastUpdateTime = os.clock()

	local cameraSubject = spectateMaid:mark(OriginalStore.new())

	local showHiddenMap = spectateMaid:mark(OriginalStoreManager.new())

	local function fetchName(player)
		local spoofName = Configuration.expectToggleValue("InfoSpoofing")
			and Configuration.expectToggleValue("SpoofOtherPlayers")

		return spoofName and "[REDACTED]"
			or string.format("(%s) %s", player:GetAttribute("CharacterName") or "Unknown Character Name", player.Name)
	end

	---@param player Player
	---@param input InputObject
	local function onWhitelistingInputBegan(player, input)
		if input.KeyCode ~= Enum.KeyCode.L then
			return
		end

		local usernameList = Options["UsernameList"]
		if not usernameList then
			return
		end

		local whitelisted = usernameList.Values
		if not whitelisted then
			return
		end

		local whitelistIndex = table.find(whitelisted, player.Name)

		if whitelistIndex then
			whitelisted[whitelistIndex] = nil

			Logger.notify("Removed player '%s' from the whitelist.", fetchName(player))
		else
			whitelisted[#whitelisted + 1] = player.Name

			Logger.notify("Added player '%s' to the whitelist.", fetchName(player))
		end

		usernameList:SetValues(whitelisted)
		usernameList:SetValue({})
		usernameList:Display()
	end

	---@param player Player
	---@param input InputObject
	local function onSpectateInputBegan(player, input)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		local usedName = fetchName(player)

		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return Logger.notify("Failed to spectate '%s' because the local player does not exist.", usedName)
		end

		local character = player.Character
		if not character then
			return Logger.notify("Failed to spectate '%s' because their character does not exist.", usedName)
		end

		local mapPosition = character:GetAttribute("MapPos")
		local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")

		if mapPosition and not humanoidRootPart then
			spectateMaid:add(
				TaskSpawner.spawn(
					"Monitoring_RequestStreamMapPos",
					players.LocalPlayer.RequestStreamAroundAsync,
					players.LocalPlayer,
					mapPosition,
					0.1
				)
			)

			return Logger.notify("Requesting stream for unloaded character '%s' - try again later.", usedName)
		end

		if not humanoidRootPart then
			return Logger.notify("Failed to spectate '%s' because they are not loaded in.", usedName)
		end

		local shouldUpdateSubject = Monitoring.subject ~= humanoidRootPart and players.LocalPlayer ~= player

		Monitoring.subject = shouldUpdateSubject and humanoidRootPart or nil

		if shouldUpdateSubject then
			Logger.notify("Started spectating player %s.", usedName)
		else
			Logger.notify("Reset spectating camera subject.")
		end
	end

	---@param player Player
	local function onBuildStealPlayer(player)
		local character = player.Character
		if not character then
			return Logger.notify(
				"Failed to steal build from '%s' because their character does not exist.",
				fetchName(player)
			)
		end

		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return Logger.notify(
				"Failed to steal build from '%s' because their humanoid does not exist.",
				fetchName(player)
			)
		end

		local backpack = player:FindFirstChild("Backpack")
		if not backpack then
			return Logger.notify(
				"Failed to steal build from '%s' because their backpack does not exist.",
				fetchName(player)
			)
		end

		local AttributePoints = 0
		local Power = 0
		for i, v in pairs(character:GetAttributes()) do
			if i:match("Stat") then
				AttributePoints = AttributePoints + v
			end
		end
		for i = 1, 20 do
			if AttributePoints <= 15 then
				break
			end
			AttributePoints = AttributePoints - 15
			Power = Power + 1
		end
		local level = math.min(20, math.max(1, Power))

		local data = {
			version = 3,
			stats = {
				buildName = string.format("%s %s's Stolen Build", os.date("%B %d %Y"), player.Name),
				buildDescription = "Talents are not stealable anymore - this is just the opponent's stats. Preshrine will need to be solved for.",
				buildAuthor = ".gg/lyc",
				power = level,
				pointsUntilNextPower = 67,
				points = 67,
				pointSpent = 67,
				traitPoints = 0,
				traits = {
					Vitality = character:GetAttribute("Trait_Health"),
					Erudition = character:GetAttribute("Trait_Ether"),
					Songchant = character:GetAttribute("Trait_MantraDamage"),
					Proficiency = character:GetAttribute("Trait_WeaponDamage"),
				},
				meta = {
					Race = "None",
					Oath = "None",
					Murmur = "None",
					Bell = "None",
					Origin = "Castaway",
					Outfit = "None",
				},
			},
			attributes = {
				weapon = {
					["Heavy Wep."] = character:GetAttribute("Stat_WeaponHeavy"),
					["Medium Wep."] = character:GetAttribute("Stat_WeaponMedium"),
					["Light Wep."] = character:GetAttribute("Stat_WeaponLight"),
				},
				base = {
					Strength = character:GetAttribute("Stat_Strength"),
					Fortitude = character:GetAttribute("Stat_Fortitude"),
					Agility = character:GetAttribute("Stat_Agility"),
					Intelligence = character:GetAttribute("Stat_Intelligence"),
					Willpower = character:GetAttribute("Stat_Willpower"),
					Charisma = character:GetAttribute("Stat_Charisma"),
				},
				attunement = {
					Flamecharm = character:GetAttribute("Stat_ElementFire"),
					Frostdraw = character:GetAttribute("Stat_ElementIce"),
					Thundercall = character:GetAttribute("Stat_ElementLightning"),
					Galebreathe = character:GetAttribute("Stat_ElementWind"),
					Shadowcast = character:GetAttribute("Stat_ElementShadow"),
					Ironsing = character:GetAttribute("Stat_ElementMetal"),
					Bloodrend = character:GetAttribute("Stat_ElementBlood"),
				},
			},
			content = {
				mantraModifications = {},
				notes = "",
			},
			meta = {
				tags = {},
				isPrivate = true,
			},
			talents = {},
			mantras = {},
			weapons = "",
			enchant = "",
			motif = "",
			preShrine = {
				base = {
					Strength = 100,
					Fortitude = 100,
					Agility = 100,
					Intelligence = 100,
					Willpower = 100,
					Charisma = 100,
				},
				weapon = {
					["Heavy Wep."] = 100,
					["Medium Wep."] = 100,
					["Light Wep."] = 100,
				},
				attunement = {
					Flamecharm = 100,
					Frostdraw = 100,
					Thundercall = 100,
					Galebreathe = 100,
					Shadowcast = 100,
					Ironsing = 100,
					Bloodrend = 100,
				},
			},
			postShrine = nil,
			favoritedTalents = {},
		}

		data.postShrine = data.attributes

		local meta = data.stats.meta
		local notes = {}

		for _, child in next, backpack:GetChildren() do
			if child.Name:match("Resonance:") then
				meta.Bell = child.Name:gsub("Resonance:", "")
			end

			if child.Name:match("Mantra") and child:GetAttribute("DisplayName") then
				local isRecalled = child.Name:match("RecalledMantra")
				notes[#notes + 1] = (isRecalled and "[RECALLED MANTRA]" or "[USED MANTRA]")
					.. " "
					.. (child:GetAttribute("RichStats") and child:GetAttribute("RichStats"):gsub("\n", " | ") or "NO RICH STATS?")

				if not isRecalled then
					data.mantras[#data.mantras + 1] = child:GetAttribute("DisplayName")
					data.content.mantraModifications[child:GetAttribute("DisplayName")] = {}
				end
			end

			if child.Name == "Weapon" then
				notes[#notes + 1] = "[USED WEAPON] " .. (child:GetAttribute("RichStats") and child:GetAttribute("RichStats"):gsub("\n", " | ") or child.Name)
			end
		end

		for _, instance in next, character:GetChildren() do
			if instance.Name == "Ring" then
				local ringName = instance:GetAttribute("DisplayName")
					or instance:GetAttribute("EquipmentRef")
					or instance.Name
				notes[#notes + 1] = string.format("[EQUIPPED RING] %s\n", ringName)
					.. (instance:GetAttribute("RichStats") and instance:GetAttribute("RichStats"):gsub("\n", " | ") or instance.Name)
			end

			if instance.Name == "Shirt" then
				notes[#notes + 1] = "[EQUIPPED SHIRT ID] " .. instance.ShirtTemplate
			end

			if instance.Name == "Pants" then
				notes[#notes + 1] = "[EQUIPPED PANTS ID] " .. instance.PantsTemplate
			end

			if
				instance.Name:match("Equipment")
				and instance:GetAttribute("RichStats")
				and instance:GetAttribute("DisplayName")
			then
				notes[#notes + 1] = string.format(
					"[EQUIPPED EQUIPMENT] [%s] %s",
					instance.Name,
					instance:GetAttribute("DisplayName")
				) .. (instance:GetAttribute("RichStats") and instance:GetAttribute("RichStats"):gsub("\n", " | ") or "")
			end
		end

		notes[#notes + 1] = string.format("[HEALTH] %.2f/%.2f", humanoid.Health, humanoid.MaxHealth)

		data.content.notes = table.concat(notes, "\n\n")

		local response = request({
			Url = "https://new.deepwoken.co/api/proxy/builds",
			Method = "POST",
			Headers = {
				["Content-Type"] = "application/json",
				["Accept"] = "application/json",
				["Origin"] = "https://deepwoken.co",
				["Referer"] = "https://deepwoken.co/builder",
				["Sec-Fetch-Site"] = "same-origin",
				["Sec-Fetch-Mode"] = "cors",
				["Sec-Fetch-Dest"] = "empty",
			},
			Body = JSON.encode(data),
		})

		if not response then
			return Logger.notify("Failed to steal build from '%s' due to no response.", fetchName(player))
		end

		if not response.Success then
			return Logger.notify(
				"(Status %i) Failed to steal build from '%s' due to build creation failure.",
				response.StatusCode,
				fetchName(player)
			)
		end

		if not response.Body then
			return Logger.notify("Failed to steal build from '%s' due to no response body.", fetchName(player))
		end

		local decoded = JSON.decode(response.Body)

		if not decoded or not decoded.id then
			return Logger.notify(
				"(Status %i) Failed to steal build from '%s' due to invalid response body.",
				response.StatusCode,
				fetchName(player)
			)
		end

		local buildUrl = string.format("https://deepwoken.co/builder?id=%s", decoded.id)
		setclipboard(buildUrl)

		local path = string.format("%s %s Stolen Build", os.date("%B %d %Y"), player.Name)
		Logger.notify("Successfully stole %s's build, %s & saved to file.", fetchName(player), buildUrl)

		if not isfolder("Luma/Stolen Builds") then
			makefolder("Luma/Stolen Builds")
		end
		
		writefile("Luma/Stolen Builds/" .. path .. ".txt", string.format([[.gg/lyc
stolen on %s
build url: %s
%s]], os.date("%B %d %Y"), buildUrl, data.content.notes))
	end

	local function onHairStealPlayer(player)
		local character = player.Character
		if not character then
			return Logger.notify(
				"Failed to steal hair IDs from '%s' because their character does not exist.",
				fetchName(player)
			)
		end

		local hairIds = {}
		local seen = {}

		for _, instance in next, character:GetDescendants() do
			if not instance:IsA("Accessory") then
				continue
			end

			local isHairSlot = instance.AccessoryType == Enum.AccessoryType.Hair
			if not isHairSlot then
				local handle = instance:FindFirstChild("Handle")
				isHairSlot = handle ~= nil and handle:FindFirstChild("HairAttachment") ~= nil
			end

			if not isHairSlot then
				continue
			end

			local id = instance.Name:match("^Asset:(%d+)$") or instance.Name:match("(%d+)")
			if id and not seen[id] then
				seen[id] = true
				table.insert(hairIds, id)
			end
		end

		if #hairIds == 0 then
			return Logger.notify("Failed to find any hair IDs for '%s'.", fetchName(player))
		end

		setclipboard(table.concat(hairIds, ", "))
		Logger.notify("Successfully stole %s's hair ID(s) & copied to clipboard.", fetchName(player))
	end

	local function updateBuildStealing()
		local leaderboardMap = LeaderboardClient.gld()
		if not leaderboardMap then
			return cameraSubject:restore()
		end

		for player, frame in next, leaderboardMap do
			local inputBegan = Signal.new(frame.InputBegan)
			local label = string.format("Monitoring_InputBegan_Steal_%s", player.Name)

			if buildStealMaid[frame] then
				continue
			end

			buildStealMaid[frame] = inputBegan:connect(label, function(input)
				if input.KeyCode ~= Enum.KeyCode.P then
					return
				end

				onBuildStealPlayer(player)
			end)
		end
	end

	local function updateHairStealing()
		local leaderboardMap = LeaderboardClient.gld()
		if not leaderboardMap then
			return cameraSubject:restore()
		end

		for player, frame in next, leaderboardMap do
			local inputBegan = Signal.new(frame.InputBegan)
			local label = string.format("Monitoring_InputBegan_HairSteal_%s", player.Name)

			if hairStealMaid[frame] then
				continue
			end

			hairStealMaid[frame] = inputBegan:connect(label, function(input)
				if input.KeyCode ~= Enum.KeyCode.O then
					return
				end

				onHairStealPlayer(player)
			end)
		end
	end

	local function updatePlayerListWhitelisting()
		local leaderboardMap = LeaderboardClient.gld()
		if not leaderboardMap then
			return cameraSubject:restore()
		end

		for player, frame in next, leaderboardMap do
			local inputBegan = Signal.new(frame.InputBegan)
			local label = string.format("Monitoring_InputBegan_PLW_%s", player.Name)

			if plwMaid[frame] then
				continue
			end

			plwMaid[frame] = inputBegan:connect(label, function(input)
				onWhitelistingInputBegan(player, input)
			end)
		end
	end

	local function updateSpectating()
		local leaderboardMap = LeaderboardClient.gld()
		if not leaderboardMap then
			return cameraSubject:restore()
		end

		for player, frame in next, leaderboardMap do
			local inputBegan = Signal.new(frame.InputBegan)
			local label = string.format("Monitoring_InputBegan%s", player.Name)

			if Configuration.expectToggleValue("ShowHiddenPlayers") then
				showHiddenMap:add(frame, "Visible", true)
			end

			if spectateMaid[frame] then
				continue
			end

			spectateMaid[frame] = inputBegan:connect(label, function(input)
				onSpectateInputBegan(player, input)
			end)
		end
	end

	local function updatePlayerProximity()
		local proximityRange = Configuration.expectOptionValue("PlayerProximityRange") or 350
		local playersInRange = Finder.gpir(proximityRange)
		if not playersInRange then
			return
		end

		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		local backpack = localPlayer:FindFirstChild("Backpack")
		if not backpack then
			return
		end

		local now = os.clock()

		-- Refresh the last-in-range stamp for everyone currently in range.
		for _, player in next, playersInRange do
			Monitoring.proximityLastSeen[player] = now
		end

		-- Dismiss a player's notification only after they've been out of range for the full grace window.
		-- A one-cycle drop-out keeps the notification up, so returning doesn't re-fire a fresh "entered".
		for player, removeNotification in next, Monitoring.seen do
			local isInPlayerRange = table.find(playersInRange, player)
			if isInPlayerRange then
				continue
			end

			if now - (Monitoring.proximityLastSeen[player] or 0) <= PROXIMITY_GRACE then
				continue
			end

			removeNotification()

			Monitoring.seen[player] = nil
			Monitoring.proximityLastSeen[player] = nil
		end

		for _, player in next, playersInRange do
			if Monitoring.seen[player] ~= nil then
				continue
			end

			if
				Configuration.expectToggleValue("PlayerProximityVW")
				and not backpack:FindFirstChild("Talent:Voidwalker Contract")
			then
				continue
			end

			Monitoring.seen[player] =
				Logger.mnnotify("%s entered your proximity radius of %i studs.", fetchName(player), proximityRange)

			if Configuration.expectToggleValue("PlayerProximityBeep") then
				beepSound.SoundId = "rbxassetid://100849623977896"
				beepSound.PlaybackSpeed = 1
				beepSound.Volume = Configuration.expectOptionValue("PlayerProximityBeepVolume") or 0.1
				beepSound:Play()
			end
		end
	end

	local function updateSubjectMonitoring()
		cameraSubject:set(workspace.CurrentCamera, "CameraSubject", Monitoring.subject)

		if Monitoring.subject ~= nil then
			players.LocalPlayer:AddTag("ForcedSubject")
		else
			players.LocalPlayer:RemoveTag("ForcedSubject")
		end
		-- The spectate stream request is NOT done here any more -- it runs on its own throttled connection in
		-- Monitoring.init, exactly like Project Rain's leaderboard_spectate (inline, never a per-frame spawn).
	end

	local function updateMonitoring()
		if Monitoring.subject then
			updateSubjectMonitoring()
		else
			cameraSubject:restore()
		end

		if os.clock() - lastUpdateTime <= 2.0 then
			return
		end

		lastUpdateTime = os.clock()

		if Configuration.expectToggleValue("PlayerListWhitelisting") then
			updatePlayerListWhitelisting()
		else
			plwMaid:clean()
		end

		if Configuration.expectToggleValue("BuildStealer") then
			updateBuildStealing()
		else
			buildStealMaid:clean()
		end

		if Configuration.expectToggleValue("HairStealer") then
			updateHairStealing()
		else
			hairStealMaid:clean()
		end

		if Configuration.expectToggleValue("PlayerSpectating") then
			updateSpectating()
		else
			spectateMaid:clean()
		end

		if Configuration.expectToggleValue("PlayerProximity") then
			updatePlayerProximity()
		end
	end

	function Monitoring.init()
		monitoringMaid:add(renderStepped:connect("Monitoring_OnRenderStepped", updateMonitoring))

		-- Project Rain's leaderboard_spectate streaming, verbatim in structure: a dedicated RenderStepped loop
		-- that, while a subject is set, calls RequestStreamAroundAsync INLINE in a pcall at most every 0.25s.
		-- PR issues one request per 0.25s on this one connection and lets it return before the next -- so at
		-- most ~one is ever in flight. (luma's old code wrapped it in TaskSpawner.spawn + maid:add EVERY frame,
		-- which piled thousands of parked requests into the fiber pool -> "RSL - panic: failed to spawn a fiber".)
		local lastStreamRequest = tick()
		monitoringMaid:add(renderStepped:connect("Monitoring_StreamSpectate", function()
			if tick() - lastStreamRequest < 0.25 or Monitoring.subject == nil then
				return
			end
			lastStreamRequest = tick()
			pcall(function()
				players.LocalPlayer:RequestStreamAroundAsync(Monitoring.subject.Position, 1000)
			end)
		end))

		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("Monitoring initialized.")
		end
	end

	function Monitoring.detach()
		monitoringMaid:clean()
		buildStealMaid:clean()
		hairStealMaid:clean()
		spectateMaid:clean()
		plwMaid:clean()
		showHiddenMap:restore()

		local refreshLeaderboard = LeaderboardClient.glrf()

		if refreshLeaderboard then
			refreshLeaderboard()
		end

		Logger.warn("Monitoring detached.")
	end

	return Monitoring
end)()

end)
__bundle_register("@luma/Features/Game/Movement", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Configuration
local Configuration = require("@luma/Utility/Configuration")

---@module Utility.OriginalStoreManager
local OriginalStoreManager = require("@luma/Utility/OriginalStoreManager")

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Utility.Freecam
local Freecam = require("@luma/Utility/Freecam")

local movementMaid = Maid.new()

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local collectionService = game:GetService("CollectionService")
local animationInstance = Instance.new("Animation")
animationInstance.AnimationId = "rbxassetid://12106091136"

return LPH_NO_VIRTUALIZE(function()
	local Movement = {}

	---@module Utility.Signal
	local Signal = require("@luma/Utility/Signal")

	---@module Utility.InstanceWrapper
	local InstanceWrapper = require("@luma/Utility/InstanceWrapper")

	---@module Utility.OriginalStore
	local OriginalStore = require("@luma/Utility/OriginalStore")

	---@module Utility.ControlModule
	local ControlModule = require("@luma/Utility/ControlModule")

	---@module Utility.Finder
	local Finder = require("@luma/Utility/Finder")

	---@module Features.Game.Tweening
	local Tweening = require("@luma/Features/Game/Tweening")

	---@module Utility.Logger
	local Logger = require("@luma/Utility/Logger")

	---@module Game.Timings.SaveManager
	local SaveManager = require("@luma/Game/Timings/SaveManager")

	local runService = game:GetService("RunService")
	local userInputService = game:GetService("UserInputService")

	local agilitySpoofer = movementMaid:mark(OriginalStore.new())

	local noClipMap = movementMaid:mark(OriginalStoreManager.new())

	local preSimulation = Signal.new(runService.PreSimulation)
	local heartbeat = Signal.new(runService.Heartbeat)

	local cachedTarget = nil

	-- Infinite zoom out: remember the original max zoom so we can restore it when the toggle is off.
	local originalMaxZoom = nil
	local objectiveTarget = nil
	local objectiveActive = false
	local nextObjectiveScan = 0
	local objectiveNotFoundNotified = false

	local noClipSpoofedClasses = { PrepareTP = true, TPSafe = true }
	local oldEffectReplicatorHasAny = nil
	local noClipHasAnyHooked = false

	local function onNoClipHasAny(effectReplicatorSelf, ...)
		if Configuration.expectToggleValue("NoClip") then
			for _, class in next, { ... } do
				if noClipSpoofedClasses[class] then
					return true
				end
			end
		end

		return oldEffectReplicatorHasAny(effectReplicatorSelf, ...)
	end

	local function updateNoClipHasAnyHook(enabled)
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = effectReplicator and require(effectReplicator)

		if not effectReplicatorModule or typeof(effectReplicatorModule.HasAny) ~= "function" then
			return
		end

		if enabled and not noClipHasAnyHooked then
			oldEffectReplicatorHasAny = effectReplicatorModule.HasAny
			effectReplicatorModule.HasAny = onNoClipHasAny
			noClipHasAnyHooked = true
		elseif not enabled and noClipHasAnyHooked then
			effectReplicatorModule.HasAny = oldEffectReplicatorHasAny
			oldEffectReplicatorHasAny = nil
			noClipHasAnyHooked = false
		end
	end

	---@param character Model
	---@param rootPart BasePart
	local function updateNoClip(character, rootPart)
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		if not effectReplicator then
			return
		end

		local controllerManager = character:FindFirstChild("ControllerManager")
		if not controllerManager then
			return
		end

		local airController = controllerManager:FindFirstChild("AirController")
		if not airController then
			return
		end

		local groundController = controllerManager:FindFirstChild("GroundController")
		if not groundController then
			return
		end

		if Configuration.expectToggleValue("Fly") then
			controllerManager.ActiveController = airController
		else
			controllerManager.ActiveController = groundController
		end

		local effectReplicatorModule = require(effectReplicator)
		local knockedRestore = effectReplicatorModule:FindEffect("Knocked")
			and Configuration.expectToggleValue("NoClipCollisionsKnocked")

		if Tweening.active then
			knockedRestore = false
		end

		for _, instance in pairs(character:GetChildren()) do
			if not instance:IsA("BasePart") then
				continue
			end

			noClipMap:add(instance, "CanCollide", knockedRestore and noClipMap:get(instance):get() or false)

			local bone = instance:FindFirstChild("Bone")
			if not bone then
				continue
			end

			local success, result = pcall(function()
				return bone.CanCollide ~= nil
			end)

			if not success or not result then
				continue
			end

			noClipMap:add(bone, "CanCollide", knockedRestore and noClipMap:get(bone):get() or false)
		end
	end


---@param rootPart BasePart
---@param humanoid Humanoid
---@param dt number
local function updateBoatfly(rootPart, humanoid, dt)
    local players = game:GetService("Players")
    local replicatedStorage = game:GetService("ReplicatedStorage")
    
    local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
    local effectReplicatorModule = effectReplicator and require(effectReplicator)
    
    if not effectReplicatorModule then
        return
    end

    local localPlayer = players.LocalPlayer
    local speed = 1000

    local steeringEffect = effectReplicatorModule:FindEffect("Steering")
    if not steeringEffect or not steeringEffect.Value then return end
    
    local steeringValue = steeringEffect.Value
    local ship = steeringValue:FindFirstAncestorWhichIsA("Model")
    if not ship then return end

    local character = localPlayer.Character
    local characterHandler = character and character:FindFirstChild("CharacterHandler")
    
    if characterHandler then
        local requests = characterHandler:FindFirstChild("Requests")
        local equipWeapon = requests and requests:FindFirstChild("DrawWeapon")
        if equipWeapon then
            equipWeapon:FireServer(true)
            equipWeapon:FireServer(false)
        end
    end

    local moveDirection = humanoid.MoveDirection

    if moveDirection.Magnitude > 0 then
        local velocityVector = moveDirection.Unit * speed
        local bv = ship:FindFirstChild("BodyVelocity", true)

        if bv then
            bv.Velocity = velocityVector
            bv.P = 99999
        else
            ship:TranslateBy(moveDirection.Unit * dt * speed)
        end
    else
        local bv = ship:FindFirstChild("BodyVelocity", true)
        if bv then
            bv.Velocity = Vector3.zero
            bv.P = 99999
        end
    end

    local shipControls = steeringValue:FindFirstChild("ShipControls")
    if shipControls then
        local args = {
            "s",
            true,
            rootPart.CFrame
        }
        shipControls:FireServer(unpack(args))
    end
end

	---@param rootPart BasePart
	---@param humanoid Humanoid
	local function updateSpeedHack(rootPart, humanoid)
		if Configuration.expectToggleValue("Fly") then
			return
		end

		rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity * Vector3.new(0, 1, 0)

		local moveDirection = humanoid.MoveDirection
		if moveDirection.Magnitude <= 0.001 then
			return
		end

		rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity
			+ moveDirection.Unit * Configuration.expectOptionValue("SpeedhackSpeed")
	end

	-- CFrame Speed (ported from mira): CFrame-based movement in the humanoid's move direction. Smoother
	-- than velocity speedhack; standalone from Speedhack.
	---@param rootPart BasePart
	---@param humanoid Humanoid
	---@param deltaTime number
	local function updateCFrameSpeed(rootPart, humanoid, deltaTime)
		if Configuration.expectToggleValue("Fly") then
			return
		end

		local moveDirection = humanoid.MoveDirection
		if not moveDirection or moveDirection.Magnitude <= 0.001 then
			return
		end

		local speed = Configuration.expectOptionValue("CFrameSpeedMultiplier") or 1
		rootPart.CFrame = rootPart.CFrame + moveDirection * (speed * deltaTime)
	end

	---@param rootPart BasePart
	local function updateInfiniteJump(rootPart)
		if Configuration.expectToggleValue("Fly") then
			return
		end

		if not userInputService:IsKeyDown(Enum.KeyCode.Space) then
			return
		end

		rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
		rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity
			+ Vector3.new(0, Configuration.expectOptionValue("InfiniteJumpBoost"), 0)
	end

	---@param rootPart BasePart
	---@param humanoid Humanoid
	local flyActive = false -- tracks fly on->off transitions so we restore the controller/sensor/speed-cap once

	-- Project Rain's fly: a tagged BodyVelocity driven by camera-relative WASD + Space/LeftControl, with any
	-- stray body-movers cleared each frame. The "AllowedBM" CollectionService tag is Deepwoken's body-mover
	-- allowlist, so the anticheat doesn't flag/strip it; OverrideSpeedCap uncaps speed while flying; the
	-- AirController + GroundSensor tweaks stop the ground controller from fighting the movement.
	local function updateFlyHack(character, rootPart, humanoid)
		local camera = workspace.CurrentCamera
		if not camera then
			return
		end

		if rootPart:FindFirstChild("HelioFlight") then
			rootPart.HelioFlight:Destroy()
		end

		-- Direction straight from the camera + held keys (PR).
		local look = camera.CFrame.LookVector
		local direction = Vector3.zero
		local keymap = {
			[Enum.KeyCode.W] = look,
			[Enum.KeyCode.S] = -look,
			[Enum.KeyCode.A] = Vector3.new(look.Z, 0, -look.X),
			[Enum.KeyCode.D] = Vector3.new(-look.Z, 0, look.X),
			[Enum.KeyCode.Space] = Vector3.new(0, 1, 0),
			[Enum.KeyCode.LeftControl] = Vector3.new(0, -1, 0),
		}
		for key, vec in pairs(keymap) do
			if userInputService:IsKeyDown(key) then
				direction = direction + vec
			end
		end
		if direction.Magnitude > 0 then
			direction = direction.Unit
		else
			direction = Vector3.zero
		end

		-- Clear stray body-movers, then (re)use our tagged one.
		local collectionService = game:GetService("CollectionService")
		for _, descendant in pairs(character:GetDescendants()) do
			if descendant:IsA("BodyVelocity") and descendant.Name ~= "LumaFly" then
				descendant:Destroy()
			end
		end

		local flyBodyVelocity = InstanceWrapper.create(movementMaid, "flyBodyVelocity", "BodyVelocity", rootPart)
		flyBodyVelocity.Name = "LumaFly"
		flyBodyVelocity.MaxForce = Vector3.new(1000000, 1000000, 1000000)
		pcall(function()
			collectionService:AddTag(flyBodyVelocity, "AllowedBM")
		end)

		-- Speed: user's FlySpeed, clamped higher while knocked (PR caps 250 / 350 knocked).
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = effectReplicator and require(effectReplicator)
		local knocked = effectReplicatorModule and effectReplicatorModule:FindEffect("Knocked")
		local speed = math.min(knocked and 350 or 250, Configuration.expectOptionValue("FlySpeed") or 50)

		flyBodyVelocity.Velocity = direction * speed

		-- Keep the air controller active + the ground sensor from grabbing us.
		local controllerManager = character:FindFirstChild("ControllerManager")
		if controllerManager then
			local airController = controllerManager:FindFirstChild("AirController")
			if airController then
				controllerManager.ActiveController = airController
			end
		end

		local groundSensor = rootPart:FindFirstChild("GroundSensor")
		if groundSensor then
			if Configuration.expectToggleValue("NoClip") then
				groundSensor.SensorMode = Enum.SensorMode.ClassicLadder
				groundSensor.UpdateType = Enum.SensorUpdateType.OnRead
			else
				groundSensor.SensorMode = Enum.SensorMode.Floor
				groundSensor.UpdateType = Enum.SensorUpdateType.Manual
			end
		end

		-- Uncap speed while flying.
		if effectReplicatorModule and not effectReplicatorModule:FindEffect("OverrideSpeedCap") then
			pcall(function()
				effectReplicatorModule:CreateEffect("OverrideSpeedCap")
			end)
		end
	end

	local lastMomentumUpdate = 0
	local function updateMaxMomentumSpoofer()
		if tick() - lastMomentumUpdate < 0.1 then
			return
		end
		lastMomentumUpdate = tick()

		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = effectReplicator and require(effectReplicator)
		if not effectReplicatorModule then
			return
		end

		local forcedMomentumEffect = effectReplicatorModule:FindEffect("ForceMomentum")

		if not Configuration.expectToggleValue("MaxMomentumSpoof") then
			if forcedMomentumEffect then
				forcedMomentumEffect.Disabled = true
				forcedMomentumEffect.Value = 0
			end
			return
		end

		if not forcedMomentumEffect then
			return effectReplicatorModule:CreateEffect("ForceMomentum", { Value = 10 })
		end

		if forcedMomentumEffect.Value ~= 10 then
			forcedMomentumEffect.Value = 10
		end

		if forcedMomentumEffect.Disabled ~= false then
			forcedMomentumEffect.Disabled = false
		end
	end

	---@note: The client recomputes WalkSpeed from effects every frame, so a
	local function updateForceSpeedBuff()
		local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
		local effectReplicatorModule = effectReplicator and require(effectReplicator)
		if not effectReplicatorModule then
			return
		end

		local forceSpeedEffect = effectReplicatorModule:FindEffect("ForceSpeedBuff")

		if not Configuration.expectToggleValue("ForceSpeedBuff") then
			if forceSpeedEffect then
				forceSpeedEffect.Value = 0
				forceSpeedEffect.Disabled = true
			end
			return
		end

		if not forceSpeedEffect then
			return effectReplicatorModule:CreateEffect("ForceSpeedBuff")
		end

		local amount = Configuration.expectOptionValue("ForceSpeedBuffAmount") or 0.0
		if forceSpeedEffect.Value ~= amount then
			forceSpeedEffect.Value = amount
		end

		forceSpeedEffect.Disabled = false
	end

	---@param character Model
	local function updateAgilitySpoofer(character)
		local agility = character:FindFirstChild("PassiveAgility")
		if not agility then
			return
		end

		---@note: For every 10 investment points, there are two real agility points.
		local agilitySpoofValue = 8 + (Options.AgilitySpoof.Value / 10) * 2

		if Toggles.BoostAgilityDirectly.Value then
			agilitySpoofValue = Options.AgilitySpoof.Value
		end

		agilitySpoofer:set(agility, "Value", agilitySpoofValue)
	end

	local function updateTweenToBack()
		local validTargets = Finder.geir(300, Configuration.expectToggleValue("AttachIgnorePlayers"))
		if not validTargets then
			return true
		end

		local attachTarget = Configuration.expectToggleValue("StickyAttach") and cachedTarget or validTargets[1]
		if not attachTarget then
			return true
		end

		if not attachTarget.Parent then
			return false
		end

		local attachTargetHrp = attachTarget:FindFirstChild("HumanoidRootPart")
		if not attachTargetHrp then
			return false
		end

		local attachTargetHumanoid = attachTarget:FindFirstChild("Humanoid")
		if not attachTargetHumanoid then
			return false
		end

		if attachTargetHumanoid.Health <= 0 then
			return false
		end

		cachedTarget = cachedTarget or attachTarget

		local offsetCFrame = CFrame.new(
			0.0,
			Configuration.expectOptionValue("HeightOffset"),
			Configuration.expectOptionValue("BackOffset")
		)

		local targetPosition = (attachTargetHrp.CFrame * offsetCFrame).Position
		local goalCFrame = CFrame.lookAt(targetPosition, attachTargetHrp.Position)

		Tweening.goal("TweenToBack", goalCFrame, false)

		return true
	end

	local function getObjectiveCFrame(instance)
		if not instance or not instance:IsDescendantOf(workspace) then
			return nil
		end

		if instance:IsA("BasePart") then
			return instance.CFrame
		elseif instance:IsA("Model") then
			return instance:GetPivot()
		elseif instance:IsA("Attachment") then
			return instance.WorldCFrame
		end

		return nil
	end

	local function hasObjectiveName(instance)
		local name = string.lower(instance.Name)
		return string.find(name, "objective", 1, true) ~= nil
			or string.find(name, "questmarker", 1, true) ~= nil
	end

	local function findNearestObjective(position)
		local closest, closestDistance = nil, math.huge

		local function consider(instance)
			local cframe = getObjectiveCFrame(instance)
			if not cframe then
				return
			end

			local distance = (cframe.Position - position).Magnitude
			if distance < closestDistance then
				closest = instance
				closestDistance = distance
			end
		end

		for _, instance in next, workspace:GetDescendants() do
			if hasObjectiveName(instance) then
				consider(instance)
			end
		end

		for _, tag in next, { "Objective", "QuestObjective" } do
			for _, instance in next, collectionService:GetTagged(tag) do
				if instance:IsDescendantOf(workspace) then
					consider(instance)
				end
			end
		end

		return closest
	end

	local function updateTweenToObjective(rootPart)
		if Configuration.expectToggleValue("TweenToObjective") then
			objectiveActive = true
			if Toggles and Toggles.TweenToObjective then
				Toggles.TweenToObjective:SetValue(false)
			end
		end

		if not objectiveActive then
			return
		end

		if Configuration.expectToggleValue("TweenToBack") then
			objectiveActive = false
			objectiveTarget = nil
			Tweening.stop("TweenToObjective")
			return
		end
		for _, tween in next, Tweening.queue do
			if tween.identifier ~= "TweenToObjective" then
				objectiveActive = false
				objectiveTarget = nil
				Tweening.stop("TweenToObjective")
				return
			end
		end

		local now = os.clock()
		if now >= nextObjectiveScan or not getObjectiveCFrame(objectiveTarget) then
			objectiveTarget = findNearestObjective(rootPart.Position)
			nextObjectiveScan = now + 1
		end

		local targetCFrame = getObjectiveCFrame(objectiveTarget)
		if not targetCFrame then
			objectiveActive = false
			Tweening.stop("TweenToObjective")
			if not objectiveNotFoundNotified then
				Logger.notify("No active objective marker found.")
				objectiveNotFoundNotified = true
			end
			objectiveTarget = nil
			return
		end

		objectiveNotFoundNotified = false
		if (rootPart.Position - targetCFrame.Position).Magnitude <= 5 then
			objectiveActive = false
			objectiveTarget = nil
			Tweening.stop("TweenToObjective")
			return
		end

		Tweening.goal("TweenToObjective", targetCFrame, false, true)
	end

	-- Infinite zoom out: crank the local player's max camera zoom while enabled, restore it when off.
	local function updateInfiniteZoom()
		local localPlayer = players.LocalPlayer
		if not localPlayer then
			return
		end

		if Configuration.expectToggleValue("InfiniteZoom") then
			if originalMaxZoom == nil then
				originalMaxZoom = localPlayer.CameraMaxZoomDistance
			end
			-- Re-assert every frame; the game resets this on some state changes.
			if localPlayer.CameraMaxZoomDistance ~= 1000000 then
				localPlayer.CameraMaxZoomDistance = 1000000
			end
		elseif originalMaxZoom ~= nil then
			localPlayer.CameraMaxZoomDistance = originalMaxZoom
			originalMaxZoom = nil
		end
	end

	-- Freecam: Project Rain's freecam module. Detaches the camera (WASD move, Q/E down/up, mouse
	-- look, Up/Down adjust speed, LeftShift slow). The character stays put. The module runs its own
	-- BindToRenderStep, so this just enters/exits on the toggle and feeds the speed slider in.
	local function updateFreecam()
		if Configuration.expectToggleValue("Freecam") then
			if not Freecam.running() then
				Freecam.enter()
			end

			Freecam.set_speed((Configuration.expectOptionValue("FreecamSpeed") or 60) / 60)
		elseif Freecam.running() then
			Freecam.exit()
		end
	end

	---@param dt number
	local function updateMovement(dt)
		updateInfiniteZoom()
		updateFreecam(dt)

		local localPlayer = players.LocalPlayer
		local character = localPlayer.Character
		if not character then
			return
		end

		local rootPart = character:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			return
		end

		updateTweenToObjective(rootPart)

		local humanoid = character:FindFirstChild("Humanoid")
		if not humanoid then
			return
		end

		if not Configuration.expectToggleValue("TweenToBack") or not updateTweenToBack() then
			cachedTarget = nil
		end

		if Configuration.expectToggleValue("AgilitySpoof") then
			updateAgilitySpoofer(character)
		else
			agilitySpoofer:restore()
		end

		updateMaxMomentumSpoofer()

		updateForceSpeedBuff()

		if Tweening.active or Configuration.expectToggleValue("NoClip") then
			updateNoClip(character, rootPart)
			updateNoClipHasAnyHook(true)
		else
			noClipMap:restore()
			updateNoClipHasAnyHook(false)
		end

		if Tweening.active then
			return
		end

		if Configuration.expectToggleValue("Fly") then
			flyActive = true
			updateFlyHack(character, rootPart, humanoid)
		else
			movementMaid["flyBodyVelocity"] = nil
			if flyActive then
				flyActive = false
				-- Restore normal movement: hand control back to the ground controller, reset the ground
				-- sensor, and drop the speed-cap override the fly loop created.
				local controllerManager = character and character:FindFirstChild("ControllerManager")
				if controllerManager then
					local groundController = controllerManager:FindFirstChild("GroundController")
					if groundController then
						controllerManager.ActiveController = groundController
					end
				end
				local groundSensor = rootPart and rootPart:FindFirstChild("GroundSensor")
				if groundSensor then
					groundSensor.SensorMode = Enum.SensorMode.Floor
					groundSensor.UpdateType = Enum.SensorUpdateType.Manual
				end
				local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
				local effectReplicatorModule = effectReplicator and require(effectReplicator)
				local capEffect = effectReplicatorModule and effectReplicatorModule:FindEffect("OverrideSpeedCap")
				if capEffect then
					pcall(function()
						capEffect:Debris(1)
					end)
				end
			end
		end
		
		if Configuration.expectToggleValue("BoatSpeed") then
			updateBoatfly(rootPart, humanoid)
		end

		if Configuration.expectToggleValue("Speedhack") then
			updateSpeedHack(rootPart, humanoid)
		end

		-- CFrame Speed is standalone and can be used independently of Speedhack.
		if Configuration.expectToggleValue("CFrameSpeed") then
			updateCFrameSpeed(rootPart, humanoid, dt)
		end

		if Configuration.expectToggleValue("InfiniteJump") then
			updateInfiniteJump(rootPart)
		end
	end

	function Movement.init()
		movementMaid:add(preSimulation:connect("Movement_PreSimulation", updateMovement))
		movementMaid:add(heartbeat:connect("Movement_Heartbeat", Tweening.update))

		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("Movement initialized.")
		end
	end

	function Movement.detach()
		movementMaid:clean()
		Tweening.stop("TweenToObjective")
		objectiveActive = false
		objectiveTarget = nil

		if Freecam.running() then
			Freecam.exit()
		end

		Logger.warn("Movement detached.")
	end

	return Movement
end)()

end)
__bundle_register("@luma/Features/Game/OptimizeGame", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local OptimizeGame = {}

	---@module Utility.Signal
	local Signal = require("@luma/Utility/Signal")

	---@module Utility.Logger
	local Logger = require("@luma/Utility/Logger")

	---@module Utility.Configuration
	local Configuration = require("@luma/Utility/Configuration")

	---@module Utility.Maid
	local Maid = require("@luma/Utility/Maid")

	local optimizeGameMaid = Maid.new()

	local getinfo = getinfo or debug.getinfo
	local getconstants = getconstants or debug.getconstants

	local alive = false
	local seaHookedFn = nil
	local seaOldFn = nil
	local replicationRestores = {}

	-- Only fire a retry while the module is still attached, so retry loops can't keep running (and re-driving
	-- render connections) after a detach/re-exec.
	local function retry(callback)
		task.delay(1, function()
			if alive then
				callback()
			end
		end)
	end

	local LOW_TEXTURE = "rbxassetid://130143779"

	local initialized = false
	local ranVisuals = false

	---@param obj Instance
	local function downgradeObject(obj)
		if obj:IsA("BasePart") then
			obj.Material = Enum.Material.Plastic
			obj.Reflectance = 0
			obj.CastShadow = false
		end

		if obj:IsA("Texture") or obj:IsA("Decal") then
			obj.Texture = LOW_TEXTURE
		elseif obj:IsA("SurfaceAppearance") then
			obj.ColorMap = LOW_TEXTURE
			obj.MetalnessMap = ""
			obj.RoughnessMap = ""
			obj.NormalMap = ""
		end

		if obj:IsA("ParticleEmitter") then
			obj.Enabled = false
			obj.Rate = 0
			obj.Speed = NumberRange.new(0)
		end

		if obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight") then
			obj.Enabled = false
			obj.Brightness = 0
			obj.Range = 2
		end
	end

	function OptimizeGame.runAggressive()
		if ranVisuals then
			return
		end
		ranVisuals = true
		task.spawn(function()
			local count = 0
			for _, obj in next, game:GetDescendants() do
				pcall(downgradeObject, obj)
				count = count + 1
				if count % 1000 == 0 then
					task.wait()
				end
			end
			Logger.notify("Aggressively optimized %d objects.", count)
		end)
	end

	local function setupSeaClient()
		local sea_client_func

		local function scan(objects)
			for _, object in next, objects do
				if typeof(object) ~= "function" or not getinfo(object).source:find("SeaClient") then
					continue
				end
				if not table.find(getconstants(object), "getWaveAt") then
					continue
				end

				sea_client_func = object
				break
			end
		end
		
		if filtergc then
			pcall(function()
				scan(filtergc("function", {
					IgnoreExecutor = false,
					Constants = { "getWaveAt" },
				}))
			end)
		end

		if not sea_client_func then
			scan(getgc(false))
		end

		if not sea_client_func then
			return Logger.warn("Failed to get SeaClient function.")
		end

		-- When throttled, hand back the LAST real result instead of nil. The old hook returned nothing
		-- on a skipped frame, so anything sampling the sea (floating objects, the local player while
		-- swimming) got nil and jittered -- that was the "lag". Returning the previous value is never
		-- worse than nil. os.clock + an inline Toggles read (no expectToggleValue call) keep the
		-- per-invocation cost near zero on this very hot function.
		local SEA_INTERVAL = 1 / 20
		local last_allowed_call = 0
		local cached = { n = 0 }
		local cachedArgs = { n = 0 }

		---@note: The cached result is only valid for the exact arguments it was computed with.
		local function sameArgs(...)
			local count = select("#", ...)
			if cachedArgs.n ~= count then
				return false
			end

			for index = 1, count do
				if cachedArgs[index] ~= (select(index, ...)) then
					return false
				end
			end

			return true
		end

		local old
		old = hookfunction(sea_client_func, function(...)
			local optimizeToggle = Toggles and Toggles.OptimizeGame
			if
				optimizeToggle
				and optimizeToggle.Value
				and os.clock() - last_allowed_call < SEA_INTERVAL
				and sameArgs(...)
			then
				return table.unpack(cached, 1, cached.n)
			end

			last_allowed_call = os.clock()
			cachedArgs = table.pack(...)
			cached = table.pack(old(...))
			return table.unpack(cached, 1, cached.n)
		end)

		seaHookedFn = sea_client_func
		seaOldFn = old
	end

	-- LowGraphics attribute state.
	local forcingLowGraphics = false
	local originalLowGraphics = nil

	---Force the LowGraphics player attribute while optimizing. WorldClient skips ambient VFX
	---(wind trails, glitches, bubbles, meteors, sail bones, despawn tweens) when it's set.
	---@param enabled boolean
	local function updateLowGraphics(enabled)
		local localPlayer = game:GetService("Players").LocalPlayer
		if not localPlayer then
			return
		end

		if enabled then
			if not forcingLowGraphics then
				originalLowGraphics = localPlayer:GetAttribute("LowGraphics")
				forcingLowGraphics = true
			end

			if localPlayer:GetAttribute("LowGraphics") ~= true then
				localPlayer:SetAttribute("LowGraphics", true)
			end
		elseif forcingLowGraphics then
			forcingLowGraphics = false
			localPlayer:SetAttribute("LowGraphics", originalLowGraphics)
		end
	end

	local function setupWorldClient()
		local last_world_client_func
		local function apply()
			task.wait(1)

			local hi = "WorldClient"
			local cns = getconnections(game:GetService("RunService").PreRender)

			local conn
			for _, object in next, cns do
				local func = object.Function
				if not func or not getinfo(func).source:find(hi) then
					continue
				end

				if last_world_client_func == func then
					return task.delay(1, apply)
				end

				last_world_client_func = func

				-- Crash fix (macOS/macsploit): getconnections() objects on macsploit expose only
				-- .Function and :Disconnect() - the Synapse-style :Disable() method is absent, so the
				-- original object:Disable() raised "attempt to call a nil value (method 'Disable')".
				-- On a worker-thread VM that error unwinds through the executor's native trampoline into
				-- the same NULL+0x28 SIGSEGV documented for conn:Fire(). Neutralize the connection through
				-- whatever the executor actually supports and record whether it stuck: if we cannot silence
				-- the game's own render connection we must NOT install the manual re-fire below, or every
				-- frame renders twice.
				local disabled = false
				if type(object.Disable) == "function" then
					disabled = pcall(function()
						object:Disable()
					end)
				end
				if not disabled then
					-- macsploit path: no :Disable(); try the writable .Enabled flag it exposes on
					-- getconnections objects, and confirm the write actually took.
					disabled = pcall(function()
						object.Enabled = false
					end) and object.Enabled == false
				end
				if not disabled and type(object.Disconnect) == "function" then
					-- Last resort: drop the native listener entirely. We re-fire .Function ourselves
					-- below, so a hard disconnect still yields exactly one render per throttled frame.
					disabled = pcall(function()
						object:Disconnect()
					end)
				end
				if not disabled then
					-- Could not neutralize the render connection on this executor; skip the manual
					-- optimization for this UI rather than double-firing WorldClient. Retry later in
					-- case the connection set changes.
					last_world_client_func = nil
					return task.delay(1, apply)
				end

				conn = object
			end

			if not conn then
				return
			end

			-- Crash fix (macOS/macsploit): conn:Fire() on a getconnections() object dereferences the
			-- executor's cached connection_data inside its Fire path with no liveness check - a
			-- freed/stale pointer after reconnections or respawns produces the NULL+0x28 read we
			-- SIGSEGV'd on. conn.Function is null-safe by comparison, so invoke the listener directly
			-- and wrap in pcall - a defunct connection degrades to a skipped frame, not a dead process.
			local function fireConnection(delta)
				return pcall(function()
					conn.Function(delta)
				end)
			end

			---@note: Re-enable the original connection on cleanup, otherwise WorldClient stays dead after detach.
			optimizeGameMaid["WorldClientRestore"] = function()
				pcall(function()
					if type(conn.Enable) == "function" then
						conn:Enable()
					else
						conn.Enabled = true
					end
				end)
			end

			local last_update = tick()
			optimizeGameMaid["WorldClientRender"] = game:GetService("RunService").PreRender:Connect(function()
				local now = tick()
				local enabled = Configuration.expectToggleValue("OptimizeGame")

				updateLowGraphics(enabled)

				if enabled and now - last_update < 1 / 15 then
					return
				end

				---@note: WorldClient feeds this into SmoothDamp - it must be the real elapsed time.
				local dt = now - last_update
				last_update = now

				return fireConnection(dt)
			end)
		end

		apply()

		local players = game:GetService("Players")
		local localPlayer = players.LocalPlayer
		if localPlayer then
			optimizeGameMaid:add(localPlayer.PlayerGui.ChildAdded:Connect(function(object)
				if not Configuration.expectToggleValue("OptimizeGame") then
					return
				end
				if object.Name ~= "WorldClient" then
					return
				end

				apply()
			end))
		end
	end

	-- PR's opti_clouds: the game drives cloud/entity replication rendering from a RenderStepped
	-- connection inside PlayerScripts.Replication. We neutralize the game's own connection and
	-- re-drive its function at 10Hz, so replication rendering costs a fraction of the frames without
	-- disappearing. Mirrors setupWorldClient's crash-safe handling for macsploit.
	local function setupReplication()
		local last_replication_func

		local function apply()
			local rep_func

			for _, object in next, getconnections(game:GetService("RunService").RenderStepped) do
				local func = object.Function
				if not func or not getinfo(func).source:find("PlayerScripts.Replication") then
					continue
				end

				if last_replication_func == func then
					return retry(apply)
				end

				last_replication_func = func

				-- Same macsploit-safe neutralization as setupWorldClient: the getconnections object may
				-- lack :Disable(); fall back to the writable .Enabled flag, then a hard :Disconnect(). Each
				-- path records a `restore` closure so detach can hand the game's own render connection back
				-- instead of leaving it neutralized across a re-exec.
				local restore = nil
				if type(object.Disable) == "function" and pcall(object.Disable, object) then
					restore = function()
						if type(object.Enable) == "function" then
							object:Enable()
						else
							object.Enabled = true
						end
					end
				end
				if not restore and pcall(function()
					object.Enabled = false
				end) and object.Enabled == false then
					restore = function()
						object.Enabled = true
					end
				end
				if not restore and type(object.Disconnect) == "function" and pcall(object.Disconnect, object) then
					restore = function()
						game:GetService("RunService").RenderStepped:Connect(func)
					end
				end
				if not restore then
					last_replication_func = nil
					return retry(apply)
				end

				replicationRestores[#replicationRestores + 1] = restore
				rep_func = func
				break
			end

			if not rep_func then
				-- Replication connection not present yet (early join); retry.
				return retry(apply)
			end

			-- Re-drive at 10Hz. Invoke rep_func directly (null-safe) rather than conn:Fire() to avoid
			-- the macsploit SIGSEGV, wrapped in pcall so a defunct connection degrades to a skipped frame.
			local last_update = tick()
			optimizeGameMaid["ReplicationRender"] = game:GetService("RunService").RenderStepped:Connect(function()
				local delta = tick() - last_update

				if not Configuration.expectToggleValue("OptimizeGame") then
					last_update = tick()
					return pcall(rep_func, delta)
				end

				if delta < 1 / 10 then
					return
				end
				last_update = tick()

				return pcall(rep_func, delta)
			end)
		end

		apply()
	end

	function OptimizeGame.init()
		if initialized then
			return
		end
		initialized = true
		alive = true

		-- Gate the render-connection manipulation on the toggle. setupSeaClient / setupReplication use
		-- getconnections to neutralize the game's OWN render connections and re-drive the game's render
		-- functions each frame for higher FPS; only run them when OptimizeGame is enabled.
		--
		-- setupWorldClient is DELIBERATELY NOT CALLED. It re-drove Deepwoken's WorldClient PreRender function
		-- from our own main-VM PreRender connection; WorldClient runs in the game's parallel Actor render
		-- phase, so calling its function from our serial connection ran parallel-context Lua in the wrong
		-- phase -- the illegal cross-phase op the engine Kernel-panics on, on the RENDER thread
		-- (RBXCRASH: FatalRuntimeError (RSL - panic: ...Kernel)), randomly ~40 min in, independent of every
		-- other toggle. This is EXACTLY what Project Rain does: PR's optimize_game defines opti_world_client
		-- but its enable() only ever spawns opti_sea + opti_clouds and never opti_world_client -- the same one
		-- it abandoned. setupWorldClient stays defined below (like PR's dead opti_world_client) but unused.
		if Configuration.expectToggleValue("OptimizeGame") then
			task.spawn(setupSeaClient)
			task.spawn(setupReplication)
		end

		local descendantAddedSignal = Signal.new(game.DescendantAdded)
		optimizeGameMaid:add(descendantAddedSignal:connect("OptimizeGame_DescendantAdded", function(obj)
			if ranVisuals then
				task.defer(pcall, downgradeObject, obj)
			end
		end))

		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("OptimizeGame initialized.")
		end
	end

	function OptimizeGame.detach()
		alive = false
		optimizeGameMaid:clean()

		for _, restore in ipairs(replicationRestores) do
			pcall(restore)
		end
		table.clear(replicationRestores)

		if seaHookedFn and seaOldFn then
			pcall(hookfunction, seaHookedFn, seaOldFn)
		end
		seaHookedFn = nil
		seaOldFn = nil

		updateLowGraphics(false)
		initialized = false
		ranVisuals = false
		Logger.warn("OptimizeGame detached.")
	end

	return OptimizeGame
end)()

end)
__bundle_register("@luma/Features/Game/OwnershipWatcher", function(require, _LOADED, __bundle_register, __bundle_modules)
local clientPart = Instance.new("Part", workspace)
local clientSuccess, clientPeerId = pcall(function()
	return gethiddenproperty(clientPart, "NetworkOwnerV3")
end)

clientPart:Destroy()






---@param part BasePart
---@return boolean
local function hasNetworkOwnership(part)
	local exploitFallback = isnetworkowner or function(...)
		return false
	end

	return exploitFallback(part)
end

return LPH_NO_VIRTUALIZE(function()
	local OwnershipWatcher = { modelsToScan = {}, parts = {} }

	local runService = game:GetService("RunService")

	---@module Utility.Maid
	local Maid = require("@luma/Utility/Maid")

	---@module Utility.Configuration
	local Configuration = require("@luma/Utility/Configuration")

	---@module Utility.Signal
	local Signal = require("@luma/Utility/Signal")

	---@module Utility.InstanceWrapper
	local InstanceWrapper = require("@luma/Utility/InstanceWrapper")

	---@module Utility.Logger
	local Logger = require("@luma/Utility/Logger")

	---@module Features.Automation.EchoFarm
	local EchoFarm = require("@luma/Features/Automation/EchoFarm")

	---@module Utility.Throttle
	local throttle = require("@luma/Utility/Throttle")

	local renderStepped = Signal.new(runService.RenderStepped)

	local ownershipMaid = Maid.new()

	local function cleanParts()
		for _, maid in next, OwnershipWatcher.modelsToScan do
			maid:clean()
		end
	end

	---@param character Model
	local function onLiveAdded(character)
		if not character:IsA("Model") then
			return
		end

		if OwnershipWatcher.modelsToScan[character] then
			return
		end

		OwnershipWatcher.modelsToScan[character] = Maid.new()
	end

	---@param character Model
	local function onLiveRemoved(character)
		if not OwnershipWatcher.modelsToScan[character] then

			return
		end

		OwnershipWatcher.modelsToScan[character]:clean()
		OwnershipWatcher.modelsToScan[character] = nil
	end

	local function updateOwnership()




		---@optimization: Stop updating when we don't need it.
		if
			not Configuration.expectToggleValue("ShowOwnership")
			and not Configuration.expectToggleValue("VoidMobs")
			and not EchoFarm.voiding
		then
			return cleanParts()
		end

		local updateTable = {}

		for model, maid in next, OwnershipWatcher.modelsToScan do
			local humanoidRootPart = model:FindFirstChild("HumanoidRootPart")
			if not humanoidRootPart then
				continue
			end

			local isNetworkOwner = hasNetworkOwnership(humanoidRootPart)

			local netVisual = InstanceWrapper.create(maid, "NetworkVisual", "Part", model)
			netVisual.Size = Vector3.new(10, 10, 10)
			netVisual.Transparency = Configuration.expectToggleValue("ShowOwnership") and 0.8 or 1.0
			netVisual.Color = isNetworkOwner and Color3.fromRGB(0, 255, 0) or Color3.fromRGB(255, 0, 0)
			netVisual.CFrame = humanoidRootPart.CFrame
			netVisual.Anchored = true
			netVisual.CanCollide = false

			local data = OwnershipWatcher.parts[humanoidRootPart]
				or {
					owned = isNetworkOwner,
					model = model,
				}

			data.owned = isNetworkOwner
			data.model = model

			OwnershipWatcher.parts[humanoidRootPart] = data

			updateTable[humanoidRootPart] = data
		end

		---@note: This will get rid of any parts that were not updated (e.g no longer existing root part or not in model list) upon cycle.
		---@todo: Fix me - this is a bit of a hack.
		OwnershipWatcher.parts = updateTable
	end

	---@return table<BasePart, table>
	function OwnershipWatcher.get()
		return OwnershipWatcher.parts
	end

	function OwnershipWatcher.init()
		local live = workspace:WaitForChild("Live")
		local liveChildAdded = Signal.new(live.ChildAdded)
		local liveChildRemoved = Signal.new(live.ChildRemoved)

		ownershipMaid:add(liveChildAdded:connect("OwnershipWatcher_OnLiveChildAdded", onLiveAdded))
		ownershipMaid:add(liveChildRemoved:connect("OwnershipWatcher_OnLiveChildRemoved", onLiveRemoved))
		ownershipMaid:add(renderStepped:connect("OwnershipWatcher_RenderStepped", throttle(1 / 20, updateOwnership)))

		for _, entity in next, live:GetChildren() do
			onLiveAdded(entity)
		end

		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("OwnershipWatcher initialized.")
		end
	end

	function OwnershipWatcher.detach()
		ownershipMaid:clean()

		cleanParts()

		Logger.warn("OwnershipWatcher detached.")
	end

	return OwnershipWatcher
end)()
end)
__bundle_register("@luma/Features/Game/Removal", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local Removal = {}

	---@module Utility.Maid
	local Maid = require("@luma/Utility/Maid")

	---@module Utility.Signal
	local Signal = require("@luma/Utility/Signal")

	---@module Game.KeyHandling
	local KeyHandling = require("@luma/Game/KeyHandling")

	---@module Utility.Configuration
	local Configuration = require("@luma/Utility/Configuration")

	---@module Utility.OriginalStoreManager
	local OriginalStoreManager = require("@luma/Utility/OriginalStoreManager")

	---@module Utility.OriginalStore
	local OriginalStore = require("@luma/Utility/OriginalStore")

	---@module Utility.Logger
	local Logger = require("@luma/Utility/Logger")

	---@module Game.EffectDispatcher
	local EffectDispatcher = require("@luma/Game/EffectDispatcher")

	local runService = game:GetService("RunService")
	local players = game:GetService("Players")
	local replicatedStorage = game:GetService("ReplicatedStorage")
	local lighting = game:GetService("Lighting")
	local debris = game:GetService("Debris")
	local collectionService = game:GetService("CollectionService")

	local removalMaid = Maid.new()

	local originalAcidRemote = nil
	local placeholderRemote = Instance.new("RemoteEvent")
	placeholderRemote.Name = "AcidRemote"

	local noShadows = removalMaid:mark(OriginalStore.new())
	local noBlur = removalMaid:mark(OriginalStore.new())
	local noOverlay = removalMaid:mark(OriginalStore.new())

	local echoModifiersMap = removalMaid:mark(OriginalStoreManager.new())
	local noFogMap = removalMaid:mark(OriginalStoreManager.new())
	local killBricksMap = removalMaid:mark(OriginalStoreManager.new())
	local damageBricksMap = removalMaid:mark(OriginalStoreManager.new())
	local lightBarrierMap = removalMaid:mark(OriginalStoreManager.new())
	local yunShulBarrierMap = removalMaid:mark(OriginalStoreManager.new())
	local yunShulResonanceDoorMap = removalMaid:mark(OriginalStoreManager.new())
	local hiveGateMap = removalMaid:mark(OriginalStoreManager.new())
	local statVFXMap = removalMaid:mark(OriginalStoreManager.new())

	local renderStepped = Signal.new(runService.RenderStepped)
	local workspaceDescendantAdded = Signal.new(workspace.DescendantAdded)
	local workspaceDescendantRemoving = Signal.new(workspace.DescendantRemoving)

	local lastUpdate = os.clock()
	local lastNoKillBricksUpdate = 0
	local noKillBricksWasEnabled = false
	local lastWindEffectTimestamp = os.clock()
	local lastBlindUpdate = os.clock()

	---@param localPlayer Player
	local function updateNoEchoModifiers(localPlayer)
		local backpack = localPlayer:FindFirstChild("Backpack")
		if not backpack then
			return
		end

		for _, instance in pairs(backpack:GetChildren()) do
			if not instance.Name:match("EchoMod") then
				continue
			end

			echoModifiersMap:add(instance, "Parent", nil)
		end
	end

	local function updateNoHiveGate()
		for _, store in next, hiveGateMap:data() do
			local data = store.data
			if not data then
				continue
			end

			store:set(store.data, "Parent", nil)
		end
	end

	local function updateNoKillBricks()
		for _, store in next, killBricksMap:data() do
			local data = store.data
			if not data then
				continue
			end

			store:set(store.data, "CFrame", CFrame.new(math.huge, math.huge, math.huge))
		end
	end

	local function updateNoKillBricksPersistent()
		local now = os.clock()
		if now - lastNoKillBricksUpdate < 0.1 then
			return
		end
		lastNoKillBricksUpdate = now

		if Configuration.expectToggleValue("NoKillBricks") then
