__bundle_register("@luma/Features/Visuals/Objects/PlayerESP", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Features.Visuals.Objects.EntityESP
local EntityESP = require("@luma/Features/Visuals/Objects/EntityESP")

---@module Utility.Configuration
local Configuration = require("@luma/Utility/Configuration")

---@module Game.PlayerScanning
local PlayerScanning = require("@luma/Game/PlayerScanning")

---@class PlayerESP: EntityESP
local PlayerESP = setmetatable({}, { __index = EntityESP })
PlayerESP.__index = PlayerESP
PlayerESP.__type = "PlayerESP"

local players = game:GetService("Players")

local ESP_HEALTH = "[%i/%i]"
local ESP_POWER = "[Power %i]"
local ESP_DANGER_TIME = "[%s]"

local BAR_SPECS = {
	{ key = "ArmorBar", field = "abar", vstoreName = "Armor", colorKey = "ArmorBarColor" },
	{ key = "PostureBar", field = "pbar", vstoreName = "BreakMeter", colorKey = "PostureBarColor" },
	{ key = "BloodBar", field = "bbar", vstoreName = "Blood", colorKey = "BloodBarColor" },
	{ key = "TempoBar", field = "tbar", vstoreName = "Tempo", colorKey = "TempoBarColor" },
	{ key = "SanityBar", field = "sbar", vstoreName = "Sanity", colorKey = "SanityBarColor" },
}

---@return boolean
local hasOath = LPH_NO_VIRTUALIZE(function(player)
	local backpack = player:FindFirstChildOfClass("Backpack")
	if not backpack then
		return false
	end

	for _, instance in next, backpack:GetChildren() do
		if not instance.Name:match("Oath") then
			continue
		end

		return true
	end

	return false
end)

---@param self PlayerESP
PlayerESP.update = LPH_NO_VIRTUALIZE(function(self)
	local localPlayer = players.LocalPlayer
	local localCharacter = localPlayer.Character

	local localHumanoid = localCharacter and localCharacter:FindFirstChildOfClass("Humanoid")
	local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")

	if not localRoot then
		return self:visible(false)
	end

	if not localHumanoid then
		return self:visible(false)
	end

	local entity = self.entity
	local player = self.player
	local identifier = self.identifier

	local humanoid = entity:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return self:visible(false)
	end

	local root = entity:FindFirstChild("HumanoidRootPart")
	if not root then
		return self:visible(false)
	end

	if
		PlayerScanning.isAlly(player)
		and Configuration.idToggleValue(identifier, "HideIfAlly")
		and Configuration.idToggleValue(identifier, "MarkAllies")
	then
		return self:visible(false)
	end

	local state = "NEUTRAL"
	local delta = localHumanoid.Health - humanoid.Health
	local color = Color3.new(1, 1, 1)

	if delta < 0 then
		state = "UNDER"
	end

	if delta < -50 then
		color = Color3.new(1, 0, 0)
	end

	if delta > 0 then
		state = "OVER"
	end

	if delta > 50 then
		color = Color3.new(0, 1, 0)
	end

	local fcontainer = self.fcontainer
	local flabel = fcontainer and fcontainer:FindFirstChildOfClass("TextLabel")
	local distance = (localRoot.Position - root.Position).Magnitude

	if fcontainer and flabel then
		self:utext(fcontainer, string.format("%s\n%iHP", state, math.ceil(delta)))

		flabel.Position = UDim2.new(0, 2, 0, flabel.TextSize + 2)
		flabel.TextColor3 = color

		fcontainer.Visible = Configuration.idToggleValue(identifier, "ShowHealthComparison") and distance <= 150
	end

	for _, spec in next, BAR_SPECS do
		local container = self[spec.field]
		if not container then
			continue
		end

		container.Visible = Configuration.idToggleValue(identifier, spec.key)

		local vstore = self.entity:FindFirstChild(spec.vstoreName)
		self.mbs(container, false, vstore and vstore.Value / vstore.MaxValue or 0.0)

		local bar = self.gb(container)
		if not bar then
			continue
		end

		bar.BackgroundColor3 = Configuration.idOptionValue(identifier, spec.colorKey) or Color3.new(0.0, 0.0, 0.0)
	end

	local level = entity:GetAttribute("Level") or -1
	local playerNameType = Configuration.idOptionValue(identifier, "PlayerNameType")
	local playerName = "Unknown Player"

	if playerNameType == "Character Name" then
		playerName = player:GetAttribute("CharacterName")
	elseif playerNameType == "Roblox Display Name" then
		playerName = player.DisplayName
	elseif playerNameType == "Roblox Username" then
		playerName = player.Name
	end

	if Configuration.expectToggleValue("InfoSpoofing") and Configuration.expectToggleValue("SpoofOtherPlayers") then
		playerName = "W Spoof"
	end

	self.label = playerName

	local tags = {
    string.format("[%i/%i] (%i%%)", humanoid.Health or 0, humanoid.MaxHealth or 1, math.floor(((humanoid.Health or 0) / (humanoid.MaxHealth or 1)) * 100)),
    ESP_POWER:format(level)
}

	local dangerTime = humanoid:GetAttribute("DangerExpiration")
	local dangerTimeLeft = dangerTime and math.ceil(dangerTime - workspace:GetServerTimeNow())

	if Configuration.idToggleValue(identifier, "ShowDangerTime") and dangerTimeLeft and dangerTimeLeft >= 0 then
		tags[#tags + 1] = ESP_DANGER_TIME:format(
			dangerTimeLeft >= 60 and os.date("%Mm %Ss", dangerTimeLeft) or os.date("%Ss", dangerTimeLeft)
		)
	end

	EntityESP.update(self, tags)

	local label = self.ncontainer:FindFirstChildOfClass("TextLabel")
	if not label then
		return
	end

	local backpack = player:FindFirstChildOfClass("Backpack")
	if not backpack then
		return
	end

	if Configuration.idToggleValue(identifier, "MarkSackUsers") and entity:FindFirstChild("Sack") then
		label.TextColor3 = Configuration.idOptionValue(identifier, "SackColor")
	end

	if Configuration.idToggleValue(identifier, "MarkOathUsers") and hasOath(player) then
		label.TextColor3 = Configuration.idOptionValue(identifier, "OathColor")
	end

	if Configuration.idToggleValue(identifier, "MarkAllies") and PlayerScanning.isAlly(player) then
		label.TextColor3 = Configuration.idOptionValue(identifier, "AllyColor")
	end

	local dlabel = self.dcontainer:FindFirstChildOfClass("TextLabel")
	if dlabel then
		dlabel.TextColor3 = label.TextColor3
	end
end)

PlayerESP.extra = LPH_NO_VIRTUALIZE(function(self)
	self.abar = self:add("ArmorBar", "left", 6, function(container)
		self:cgb(container, false, true, Color3.new(1, 1, 1))
	end)

	self.pbar = self:add("PostureBar", "bottom", 3, function(container)
		self:cgb(container, false, false, Color3.new(1, 1, 1))
	end)

	self.bbar = self:add("BloodBar", "bottom", 3, function(container)
		self:cgb(container, false, false, Color3.new(1, 1, 1))
	end)

	self.tbar = self:add("TempoBar", "bottom", 3, function(container)
		self:cgb(container, false, false, Color3.new(1, 1, 1))
	end)

	self.sbar = self:add("SanityBar", "bottom", 3, function(container)
		self:cgb(container, false, false, Color3.new(1, 1, 1))
	end)

	self.fcontainer = self:add("Flags", "right", 16, function(container)
		local TextLabel = Instance.new("TextLabel")
		TextLabel.Parent = container
		TextLabel.Text = "NEUTRAL\n0HP"
		TextLabel.Size = UDim2.new(0, 400, 1, 0)
		TextLabel.AnchorPoint = Vector2.new(0.0, 0.5)
		TextLabel.Position = UDim2.new(0, 2, 0, 8 + 2)
		TextLabel.BackgroundTransparency = 1.0
		TextLabel.TextStrokeColor3 = Color3.new(0.0, 0.0, 0.0)
		TextLabel.TextStrokeTransparency = 0.0
		TextLabel.TextColor3 = Color3.new(1.0, 1.0, 1.0)
		TextLabel.TextSize = 8
		TextLabel.TextXAlignment = Enum.TextXAlignment.Left
		TextLabel.TextWrapped = false
		TextLabel.Font = Enum.Font.Code
	end)
end)

---@param identifier string
---@param player Player
---@param character Model
function PlayerESP.new(identifier, player, character)
	local self = setmetatable(EntityESP.new(character, identifier, "Unknown Player"), PlayerESP)
	self.player = player
	self.identifier = identifier

	if character and character:IsA("Model") and not Configuration.expectOptionValue("NoPersisentESP") then
		character.ModelStreamingMode = Enum.ModelStreamingMode.Persistent
	end

	self:setup()
	self:build()
	self:update()

	return self
end

return PlayerESP

end)
__bundle_register("@luma/Game/AntiAFK", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
---@note: You should never leave the service access running here. Use a direct reference because we would want to know if they add any detections targeting this feature.
local AntiAFK = { wanters = {} }

---@module Utility.Signal
local Signal = require("@luma/Utility/Signal")

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

local players = game:GetService("Players")

local afkMaid = Maid.new()

function AntiAFK.start(identifier)
	AntiAFK.wanters[identifier] = true
end

function AntiAFK.stop(identifier)
	AntiAFK.wanters[identifier] = nil
end

function AntiAFK.init()
	local idledSignal = Signal.new(players.LocalPlayer.Idled)

	idledSignal:connect("AntiAFK_OnIdled", function()
		if not AntiAFK.wanters or #AntiAFK.wanters == 0 then
			return
		end

		local virtualUser = game:GetService("VirtualUser")
		virtualUser:CaptureController()
		virtualUser:ClickButton2(Vector2.new())
	end)
end

function AntiAFK.detach()
	afkMaid:clean()
end

return AntiAFK
end)()

end)
__bundle_register("@luma/Game/EffectDispatcher", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Unified EffectReplicator handler -- the whole script's SINGLE connection to the game's EffectReplicator,
---@note: mirroring Project Rain's EffectReplicatorHandler. Consumers register "added"/"removed" hooks via
---@note: EffectDispatcher.hook(...) instead of each opening its own EffectAdded connection.
---@note:
---@note: Added hooks run INLINE (plain xpcall) -- no task.spawn, no task.defer, no setthreadidentity. Both
---@note: scheduler primitives were tried here and both crashed: spawning/deferring a thread from inside the
---@note: deferred-lane scheduler step the game fires EffectAdded from can enter a second guarded job under
---@note: Roblox's 0.742+ STM scheduler and trip its per-thread re-entrancy guard ("RSL - panic ...Kernel,2090").
---@note: Running inline touches the scheduler not at all. Removed hooks already run inline. The whole connection
---@note: is rebuilt when the server clears/rebuilds its effect container
---@note: (Requests.EffectReplication._update "clear"/"updatecontainer"), so nothing ever rides a stale container.

local EffectDispatcher = {}

---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")

local hooks = {}
local reconnectCallbacks = {}
local pendingReactions = {} -- reactions handed over by hook bodies via EffectDispatcher.defer, drained on Heartbeat
local effectMaid = Maid.new() -- EffectAdded/EffectRemoved connections -- torn down and rebuilt on reconnect
local lifecycleMaid = Maid.new() -- the _update reconnect listener -- set up once
local reactionPumpConnection = nil -- Heartbeat drain for pendingReactions -- set up once in init
local connected = false

---@param err string
local function onHookError(err)
	Logger.trace("EffectDispatcher_HookError - %s", err)
end

-- Reaction offloading. Added/removed hooks run INLINE on the game's deferred-lane EffectAdded/EffectRemoved
-- dispatch thread (see header note). A hook body must therefore do ONLY cheap, scheduler-free work on that
-- callstack -- any remote fire, task.wait or follow-up spawn done there can nest a second guarded STM job and trip
-- Roblox 0.742+'s per-thread re-entrancy guard (RSL panic Kernel,2090). When a hook needs to DO such a thing it
-- hands a closure to EffectDispatcher.defer, which only appends to a table (zero scheduler touch); the Heartbeat
-- pump below runs it on its OWN top-level scheduler step -- a fresh scheduler entry, never nested inside the
-- dispatch -- where firing/yielding is safe (the same place Hooking.maintainNoFall already fires remotes). Each
-- reaction runs on its own task.spawn'd thread so one that yields (e.g. a wait-loop) can't block the others;
-- task.spawn is safe HERE precisely because this is NOT a hook callstack -- it is the Heartbeat job itself.
---@param fn fun()
function EffectDispatcher.defer(fn)
	pendingReactions[#pendingReactions + 1] = fn
end

local function drainReactions()
	if #pendingReactions == 0 then
		return
	end
	local batch = pendingReactions
	pendingReactions = {}
	for _, fn in next, batch do
		task.spawn(pcall, fn)
	end
end

-- Disconnect helper for both real RBXScriptConnections and Deepwoken's custom EffectReplicator signal connections
-- (EffectAdded/EffectRemoved are NOT RBXScriptSignals -- their connections are tables/functions Maid won't clean on
-- its own). Wrapping it in a cleanup function makes a reconnect actually drop the old handler, no duplicates.
local function markConnection(maid, connection)
	maid:mark(function()
		pcall(function()
			if type(connection) == "function" then
				connection()
			elseif typeof(connection) == "RBXScriptConnection" then
				connection:Disconnect()
			elseif type(connection) == "table" then
				local disconnect = connection.Disconnect or connection.disconnect or connection.Destroy
				if disconnect then
					disconnect(connection)
				end
			end
		end)
	end)

	return connection
end

---Register an effect hook.
---@param hookType string "added" | "removed"
---@param callback fun(effect: table)
---@return table hook  -- call hook:remove() to unregister
function EffectDispatcher.hook(hookType, callback)
	local hook = { type = hookType, call = callback }

	function hook:remove()
		local at = table.find(hooks, self)
		if at then
			table.remove(hooks, at)
		end
	end

	table.insert(hooks, hook)
	return hook
end

---Run callback (serial, pcall-guarded) on every (re)connect, before existing effects are replayed. Used for
---state that must be wiped when the server rebuilds its container (e.g. EffectTimers.clear).
---@param callback fun()
function EffectDispatcher.onReconnect(callback)
	table.insert(reconnectCallbacks, callback)
end

---@return table effectReplicatorModule
function EffectDispatcher.module()
	return require(replicatedStorage:WaitForChild("EffectReplicator"))
end

---@param effect table
local function dispatchAdded(effect)
	-- Run each added hook INLINE -- no task.spawn, no task.defer, no setthreadidentity. Both scheduler primitives
	-- (spawn AND defer) have been tried here and BOTH crashed: they register/resume a thread with the task
	-- scheduler, and doing that from inside the deferred-lane scheduler step the game fires EffectAdded from is a
	-- candidate for entering a second guarded STM job (Roblox 0.742+ per-thread re-entrancy guard -> RSL panic
	-- Kernel,2090). So we don't touch the scheduler at all: a plain xpcall runs hook.call directly on the thread
	-- the game's own Signal already handed us, with per-hook error isolation but zero new threads. hook.call
	-- (EffectTimers.track + StateListener.onEffectReplicated) never yields on the always-on path -- its reactive
	-- branches defer their own work -- so running inline cannot stall the dispatch.
	for _, hook in next, hooks do
		if hook.type == "added" and hook.call then
			xpcall(hook.call, onHookError, effect)
		end
	end
end

---@param effect table
local function dispatchRemoved(effect)
	for _, hook in next, hooks do
		if hook.type == "removed" and hook.call then
			xpcall(hook.call, onHookError, effect)
		end
	end
end

local function connect()
	effectMaid:clean()

	for _, callback in next, reconnectCallbacks do
		pcall(callback)
	end

	local effectReplicatorModule = EffectDispatcher.module()

	markConnection(effectMaid, effectReplicatorModule.EffectAdded:Connect(dispatchAdded))
	markConnection(effectMaid, effectReplicatorModule.EffectRemoved:Connect(dispatchRemoved))

	-- No replay of already-active effects. Project Rain's EffectReplicatorHandler only wires EffectAdded/
	-- EffectRemoved and never re-dispatches EffectReplicator.Effects on (re)connect -- it takes the inject-time
	-- gap instead of running a synchronous burst of every added hook over every live effect inside connect()
	-- (which, on an _update "clear"/"updatecontainer", fires inline within that OnClientEvent callback). Match it.
end

---Connect (replaying current effects to all registered hooks) and wire the container-rebuild reconnect. Call
---ONCE, after every always-on consumer has registered its hooks.
function EffectDispatcher.init()
	connect()

	if connected then
		return
	end
	connected = true

	if not reactionPumpConnection then
		reactionPumpConnection = runService.Heartbeat:Connect(drainReactions)
	end

	task.spawn(pcall, function()
		local update = replicatedStorage
			:WaitForChild("Requests")
			:WaitForChild("EffectReplication")
			:WaitForChild("_update")

		lifecycleMaid:mark(update.OnClientEvent:Connect(function(payload)
			if type(payload) == "table" and (payload.updateType == "clear" or payload.updateType == "updatecontainer") then
				connect()
			end
		end))
	end)
end

function EffectDispatcher.detach()
	effectMaid:clean()
	lifecycleMaid:clean()
	if reactionPumpConnection then
		pcall(function()
			reactionPumpConnection:Disconnect()
		end)
		reactionPumpConnection = nil
	end
	table.clear(hooks)
	table.clear(reconnectCallbacks)
	table.clear(pendingReactions)
	connected = false
end

return EffectDispatcher

end)
__bundle_register("@luma/Game/EffectTimers", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Answers "what is the server's effect state right now" locally, by mirroring the server's effect
---@note: timestamps into a weak Lua table. Tracking is DRIVEN by StateListener's Project-Rain-style
---@note: EffectReplicator connection (setthreadidentity(8) + task.spawn + reconnect on container rebuild);
---@note: this module no longer connects to EffectAdded/EffectRemoved itself, so the whole script keeps exactly
---@note: one effect connection. StateListener calls track/untrack/clear; everything else just reads `tracked`.

---@module Game.Latency
local Latency = require("@luma/Game/Latency")

local EffectTimers = {}

local tracked = setmetatable({}, { __mode = "k" })

---@param effect table
function EffectTimers.track(effect)
	if not effect then
		return
	end

	tracked[effect] = { at = os.clock(), debris = effect.DebrisTime }
end

---@param effect table
function EffectTimers.untrack(effect)
	if not effect then
		return
	end

	tracked[effect] = nil
end

---Drop every tracked effect (used when the server clears/rebuilds its effect container).
function EffectTimers.clear()
	table.clear(tracked)
end

---@param effect table
---@return number
function EffectTimers.elapsed(effect)
	if not effect then
		return 0
	end

	local info = tracked[effect]
	if not info then
		return 0
	end

	return (os.clock() - info.at) + (Latency.rdelay() or 0)
end

---@param effect table
---@return number?
function EffectTimers.remaining(effect)
	if not effect then
		return nil
	end

	local info = tracked[effect]
	if not info or not info.debris then
		return nil
	end

	return math.max(0, info.debris - (os.clock() - info.at))
end

---@param effectReplicatorModule table
---@param class string
---@return number? elapsed
---@return number? remaining
function EffectTimers.forClass(effectReplicatorModule, class)
	local effect = effectReplicatorModule:FindEffect(class)
	if not effect then
		return nil, nil
	end

	return EffectTimers.elapsed(effect), EffectTimers.remaining(effect)
end

function EffectTimers.detach()
	table.clear(tracked)
end

return EffectTimers

end)
