local onNameCall = LPH_NO_VIRTUALIZE(function(self, ...)
	-- STM firewall: never run our body on an Actor/worker VM (see foreignVM above) -- bail to the original.
	if foreignVM() then
		return oldNameCall(self, ...)
	end

	if not LeaderboardClient.calling and checkcaller() then
		return oldNameCall(self, ...)
	end

	if banRemotes[self] then
		return Logger.warn("(%s) Anticheat is referencing a ban remote.", self.Name)
	end

	if typeof(self) ~= "Instance" then
		return oldNameCall(self, ...)
	end

	local secondArg = ...
	local method = getnamecallmethod()
	local name = self.Name

	-- Silent Aim: drop the game's own UpdateMouse fire so only our redirected mouse position reaches the
	-- server. Our own UpdateMouse fire is checkcaller() == true and short-circuits at the top of this hook,
	-- so it is never caught here -- only the game's (checkcaller() == false) calls reach this point.
	if name == "UpdateMouse" and method == "FireServer" and Configuration.expectToggleValue("SilentAim") then
		return
	end

	if method == "Raycast" then
		local callingScript = getcallingscript()

		if callingScript and callingScript.Name == "ClientPhysics" then
			local _, info = findClientPhysicsLevel()

			if info and info.name == "" then
				return false
			end
		end
	end

	if method == "Create" then
		---@note: Fix object if we're using a lighting template.
		local lightingTemplate = select(3, ...)

		if typeof(lightingTemplate) == "table" then
			if
				lightingTemplate["FogStart"]
				and lightingTemplate["FogEnd"]
				and Configuration.expectToggleValue("NoFog")
			then
				lightingTemplate["FogStart"] = 9e9
				lightingTemplate["FogEnd"] = 9e9
			end

			if lightingTemplate["Ambient"] and Configuration.expectToggleValue("ModifyAmbience") then
				lightingTemplate["Ambient"] = modifyAmbienceColor(lightingTemplate["Ambient"])
			end

			if lightingTemplate["Density"] and Configuration.expectToggleValue("NoFog") then
				lightingTemplate["Density"] = 0
			end

			---@note: lightingTemplate is mutated in place (same table reference), so
			return oldNameCall(self, ...)
		end
	end

	if Configuration.expectToggleValue("InfoSpoofing") then
		if typeof(secondArg) == "string" and method == "GetAttribute" and not Spoofing.force then
			local localPlayer = playersService.LocalPlayer
			local character = localPlayer and localPlayer.Character
			local humanoid = game.FindFirstChild(character, "Humanoid")
			local foreign = true

			if character and humanoid and (self.Parent == character or self.Parent == humanoid) then
				foreign = false
			end

			if foreign and not Configuration.expectToggleValue("SpoofOtherPlayers") then
				return oldNameCall(self, ...)
			end

			if secondArg == "FirstName" then
				return foreign and "Linoria V2" or Configuration.expectOptionValue("SpoofedFirstName")
			end

			if secondArg == "LastName" then
				return foreign and "On Top" or Configuration.expectOptionValue("SpoofedLastName")
			end

			if secondArg == "CharacterName" then
				local characterName = Configuration.expectOptionValue("SpoofedFirstName")
					.. " "
					.. Configuration.expectOptionValue("SpoofedLastName")

				return foreign and "Linoria V2 On Top" or characterName
			end

			if secondArg == "Guild" then
				return foreign and "discord.gg/lyc" or Configuration.expectOptionValue("SpoofedGuild")
			end

			if secondArg == "GuildRich" then
				return foreign and "discord.gg/lyc" or Configuration.expectOptionValue("SpoofedGuildName")
			end
		end
	end

	if name == "ActivateMantra" and method == "FireServer" then
		local blockMantra = false
		if not checkcaller() then
			local ok, result = pcall(Defense.shouldBlockInput, "Mantras")
			blockMantra = ok and result == true
		end

		if blockMantra then
			return
		end

		StateListener.lMantraActivated = secondArg

		onInterceptedInput(INPUT_CAST, INPUT_TYPE_BEFORE)

		if setnamecallmethod then
			setnamecallmethod(method)
		end

		local result = oldNameCall(self, ...)

		onInterceptedInput(INPUT_CAST, INPUT_TYPE_AFTER)

		return result
	end

	if name == "ClientEffectBatch" and method == "FireServer" then
		return
	end

	return oldNameCall(self, ...)
end)

---@return any
local onUnreliableFireServer = LPH_NO_VIRTUALIZE(function(self, ...)
	if foreignVM() then
		return oldUnreliableFireServer(self, ...)
	end

	if banRemotes[self] then
		return Logger.warn("(%s) Anticheat is calling a unreliable ban remote.", self.Name)
	end

	-- PR-style hard gate: our own re-fires skip the reactive hook body entirely, mirroring Project Rain's
	-- `if checkcaller() then return old_fireserver(...)` top guard -- but via SelfFire.active, the reflection-free
	-- boolean (this hook is process-global and runs in the parallel Actor VMs, where checkcaller() itself would be
	-- the Kernel,2090 cross-phase reflection). luma raises SelfFire only around its own InputClient re-fires, so a
	-- real player input is never SelfFire.active here and always runs the full body below.
	if SelfFire.active then
		return oldUnreliableFireServer(self, ...)
	end

	-- getCachedRemote (pure cache read, never the encoder) -- PR resolves these in setup and only pure-reads in
	-- the global fire hooks. The keys are prewarmed once at init (Hooking.init -> KeyHandling.prewarm).
	local leftClickRemote = KeyHandling.getCachedRemote("LeftClick")
	local criticalRemote = KeyHandling.getCachedRemote("CriticalClick")
	local feintClickRemote = KeyHandling.getCachedRemote("FeintClick")
	local offhandAttackRemote = KeyHandling.getCachedRemote("OffhandAttack")

	local inputType = nil

	if criticalRemote and self == criticalRemote then
		inputType = INPUT_CRITICAL
	end

	if leftClickRemote and self == leftClickRemote then
		inputType = INPUT_LEFT_CLICK
	end

	if (feintClickRemote and self == feintClickRemote) or (offhandAttackRemote and self == offhandAttackRemote) then
		inputType = INPUT_RIGHT_CLICK
	end

	if inputType then
		-- SelfFire.active was handled by the top gate, so by here this is always the game's own fire.
		local blockMove = BLOCK_INPUT_MOVE_MAP[inputType]
		local ok, blocked = pcall(Defense.shouldBlockInput, blockMove)
		if ok and blocked then
			return
		end

		if inputType == INPUT_LEFT_CLICK then
			local okMixup, handled = pcall(Defense.tryAutoMixup)
			if okMixup and handled then
				return
			end
		end

		onInterceptedInput(inputType, INPUT_TYPE_BEFORE)

		local result = oldUnreliableFireServer(self, ...)

		onInterceptedInput(inputType, INPUT_TYPE_AFTER)

		return result
	end

	return oldUnreliableFireServer(self, ...)
end)

---@return any
local onFireServer = LPH_NO_VIRTUALIZE(function(self, ...)
	if foreignVM() then
		return oldFireServer(self, ...)
	end

	if banRemotes[self] then
		return Logger.warn("(%s) Anticheat is calling a ban remote.", self.Name)
	end

	-- PR-style hard gate (see onUnreliableFireServer): our own fires skip the reactive body via the reflection-free
	-- SelfFire.active flag, the parallel-safe equivalent of PR's checkcaller() top guard.
	if SelfFire.active then
		return oldFireServer(self, ...)
	end

	local blockRemote = KeyHandling.getCachedRemote("Block")

	local inputType = nil

	if blockRemote and self == blockRemote then
		inputType = INPUT_BLOCK
	end

	if inputType then
		onInterceptedInput(inputType, INPUT_TYPE_BEFORE)

		local result = oldFireServer(self, ...)

		onInterceptedInput(inputType, INPUT_TYPE_AFTER)

		return result
	end

	return oldFireServer(self, ...)
end)

---@return number
local getWalkSpeedMultiplier = LPH_NO_VIRTUALIZE(function()
	if os.clock() - lastWalkSpeedRefresh > WALK_SPEED_REFRESH then
		local min = Configuration.expectOptionValue("WalkSpeedMultiplierMinimum") or 1.0
		local max = Configuration.expectOptionValue("WalkSpeedMultiplierMaximum") or 1.0

		if min > max then
			min, max = max, min
		end

		walkSpeedMultiplier = walkSpeedRandom:NextNumber(min, max)
		lastWalkSpeedRefresh = os.clock()
	end

	return walkSpeedMultiplier
end)

---@return any
local onNewIndex = LPH_NO_VIRTUALIZE(function(self, index, value, ...)
	if foreignVM() then
		return oldNewIndex(self, index, value, ...)
	end

	if checkcaller() then
		return oldNewIndex(self, index, value, ...)
	end

	if typeof(self) ~= "Instance" then
		return oldNewIndex(self, index, value, ...)
	end

	---@note: Only these keys are ever rewritten below, so bail cheaply on anything
	if
		index ~= "Text"
		and index ~= "ActiveController"
		and index ~= "MouseIconEnabled"
		and index ~= "Ambient"
		and index ~= "WalkSpeed"
	then
		return oldNewIndex(self, index, value, ...)
	end

	---@note: Scale the game's own walkspeed writes for our local humanoid. Because
	if index == "WalkSpeed" and Configuration.expectToggleValue("WalkSpeedMultiplier") and typeof(value) == "number" then
		local localPlayer = playersService.LocalPlayer
		local character = localPlayer and localPlayer.Character

		if character and self.Parent == character and isA(self, "Humanoid") then
			return oldNewIndex(self, index, value * getWalkSpeedMultiplier(), ...)
		end
	end

	if Configuration.expectToggleValue("InfoSpoofing") then
		if game.IsA(self, "TextLabel") and index == "Text" and not Spoofing.force then
			if self.Name == "Slot" and self.Parent and self.Parent.Name == "CharacterInfo" then
				return oldNewIndex(self, index, Configuration.expectOptionValue("SpoofedSlotString"))
			end

			if self.Name == "GameVersion" then
				return oldNewIndex(self, index, Configuration.expectOptionValue("SpoofedGameVersion"))
			end

			if self.Name == "Date" then
				return oldNewIndex(self, index, Configuration.expectOptionValue("SpoofedDateString"))
			end
		end
	end

	if Configuration.expectToggleValue("NoClip") and Configuration.expectToggleValue("Fly") then
		if index == "ActiveController" then
			if self.Parent then
				local airController = self:FindFirstChild("AirController")
				return oldNewIndex(self, index, airController or value)
			end
		end
	end

	if index == "MouseIconEnabled" then
		return oldNewIndex(self, index, true)
	end

	if index == "Ambient" then
		if self == lighting and Configuration.expectToggleValue("ModifyAmbience") then
			return oldNewIndex(self, index, modifyAmbienceColor(value))
		end
	end

	return oldNewIndex(self, index, value, ...)
end)

---@return any
-- EXACTLY Project Rain's tostring hook: the crash-string trap and NOTHING else. `tostring` is hooked on the
-- process-global base function, so this runs inside EVERY Luau VM -- including Deepwoken's parallel Actor
-- VMs. The old body walked the Lua stack (a debug.getinfo loop over InputClient frames) and ran
-- InputClient.cache() (getgc / getconnections / LoadAnimation) from right here; whenever a parallel Actor
-- happened to call tostring, all of that main-VM reflection executed mid-parallel-phase -- the illegal
-- cross-phase operation the engine Kernel-panics on (RBXCRASH: FatalRuntimeError (RSL - panic: ...Kernel)).
-- That is THE crash: it fired randomly tens of minutes in, was independent of InfoSpoofing, and survived
-- every hook-SET change because the panic lived in the hook BODY, not the set. PR's tostring is this exact
-- 3-line pass-through. InputClient caching now runs on the main thread off CharacterAdded (InputClient.lua
-- -> InputClient.ensureCached), never again from a cross-VM hook.
local onToString = LPH_NO_VIRTUALIZE(function(str, ...)
	if foreignVM() then
		return oldToString(str, ...)
	end

	if str == "EEKEWAEJIWAJDOIWAJDIOJAWDIOJAWODJOAIW" then
		Logger.warn("Crash was attempted.")
		return coroutine.yield()
	end

	return oldToString(str, ...)
end)

local maintainNoFall = LPH_NO_VIRTUALIZE(function()
	local module = noFallModule
	if not module then
		return
	end

	local on = Configuration.expectToggleValue("NoFallDamage") and true or false

	if on then
		pcall(function()
			if not module:FindEffect("NoFall") then
				module:CreateEffect("NoFall")
			end
		end)
	elseif noFallLastOn then
		pcall(function()
			local effect = module:FindEffect("NoFall")
			if effect then
				effect:Debris(0.1)
			end
		end)
	end

	noFallLastOn = on
end)

---@return string
local generateRandomName = LPH_NO_VIRTUALIZE(function()
	local guid = httpService:GenerateGUID(false):lower():gsub("[%-]*", "")
	local length = math.random(8, 16)
	local built = guid:sub(1, length)
	local capitalizedLast = false

	for i = 1, length do
		local prefix = built:sub(1, i - 1)
		local char = built:sub(i, i)
		local suffix = built:sub(i + 1)

		local asNumber = tonumber(char)
		if asNumber then
			char = string.char(103 + asNumber)
		end

		if i == 1 or (math.random(1, 6) == 1 and not capitalizedLast and i < length) then
			char = char:upper()
			capitalizedLast = true
		else
			capitalizedLast = false
		end

		built = prefix .. char .. suffix
	end

	return built:sub(1, length)
end)

---@param remote any
---@return Instance?
local emulatedGetKey = LPH_NO_VIRTUALIZE(function(remote)
	if typeof(remote) ~= "string" then
		return
	end

	return KeyHandling.getRemote(remote)
end)

---@param remote Instance
local emulatedCreateKey = LPH_NO_VIRTUALIZE(function(remote)
	KeyHandling.registerRemote(remote)
	remote.Name = generateRandomName()
end)

local SPRINT_KEYS = {
	[Enum.KeyCode.W] = true,
	[Enum.KeyCode.A] = true,
	[Enum.KeyCode.S] = true,
	[Enum.KeyCode.D] = true,
}
local autoSprintConnection = nil
local autoSprintActive = false

local onSprintInput = LPH_NO_VIRTUALIZE(function(input, gameProcessed)
	if gameProcessed or not SPRINT_KEYS[input.KeyCode] or autoSprintActive then
		return
	end
	if not Configuration.expectToggleValue("AutoSprint") then
		return
	end
	autoSprintActive = true

	local sprintDelay = 0
	if Configuration.expectToggleValue("AutoSprintDelay") then
		sprintDelay = Configuration.expectOptionValue("AutoSprintDelayTime") or 0
	end

	task.delay(sprintDelay, function()
		if not autoSprintActive or not Configuration.expectToggleValue("AutoSprint") then
			return
		end

		local localPlayer = playersService.LocalPlayer
		local character = localPlayer and localPlayer.Character
		local humanoid = character and character:FindFirstChildWhichIsA("Humanoid")
		local characterHandler = character and character:FindFirstChild("CharacterHandler")
		local requests = characterHandler and characterHandler:FindFirstChild("Requests")
		local stopSprint = requests and requests:FindFirstChild("StopSprint")
		if not humanoid or not stopSprint then
			return
		end

		local effectReplicator = getEffectReplicator()
		local effectReplicatorModule = effectReplicator and require(effectReplicator)

		for _, connection in next, getconnections(stopSprint.OnClientEvent) do
			local func = connection.Function
			local okInfo, info = pcall(debug.getinfo, func)
			if not okInfo or not info or not tostring(info.source):find("InputClient") then
				continue
			end

			local okEnv, env = pcall(getfenv, func)
			local sprintFn = okEnv and env and env.Sprint
			if type(sprintFn) ~= "function" then
				continue
			end

			while humanoid.MoveDirection.Magnitude >= 0.1 and Configuration.expectToggleValue("AutoSprint") do
				local sprinting = effectReplicatorModule and effectReplicatorModule:FindEffect("Sprinting")
				local crouching = effectReplicatorModule and effectReplicatorModule:FindEffect("ClientCrouch")
				if not sprinting and (not crouching or Configuration.expectToggleValue("AutoSprintOnCrouch")) then
					pcall(sprintFn, true)
				end
				task.wait()
			end
		end
	end)

	local localPlayer = playersService.LocalPlayer
	local humanoid = localPlayer and localPlayer.Character and localPlayer.Character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		autoSprintActive = false
		return
	end

	local moveConn
	local destroyConn
	local function release()
		autoSprintActive = false
		if moveConn then
			moveConn:Disconnect()
		end
		if destroyConn then
			destroyConn:Disconnect()
		end
	end

	moveConn = humanoid:GetPropertyChangedSignal("MoveDirection"):Connect(function()
		if humanoid.MoveDirection.Magnitude <= 0.1 then
			release()
		end
	end)
	destroyConn = humanoid.Destroying:Connect(release)
end)

function Hooking.earlyInit()
	if game.PlaceId == LOBBY_PLACE_ID then
		return
	end

	task.spawn(pcall, function()
		local clientManager = playersService.LocalPlayer:WaitForChild("PlayerScripts"):WaitForChild("ClientActor"):WaitForChild("ClientManager")
		clientManager.Enabled = false
	end)

	oldFireServer = hookfunction(Instance.new("RemoteEvent").FireServer, onFireServer)
	oldUnreliableFireServer = hookfunction(Instance.new("UnreliableRemoteEvent").FireServer, onUnreliableFireServer)
	oldToString = hookfunction(tostring, onToString)

	-- EXACTLY Project Rain's game-hook set: only __namecall and __newindex (plus the FireServer / tostring
	-- hooks above). PR hooks NOTHING else on `game` -- no __index, no tick, no warn/print/GetLogHistory --
	-- because any of those dispatched from Deepwoken's parallel Actor VM is the illegal cross-phase op the
	-- engine Kernel-panics on (RSL - panic: ...Kernel). __index especially fires on every property read, so
	-- it was the hottest path to trip it. Dropping them -- what PR does -- is what stops the crash; the
	-- earlier "confine __index via a metatable swap" still crashed. Cost (same trade PR makes): InfoSpoofing
	-- loses its __index read-intercept (the __namecall/__newindex spoofs + Spoofing.rics value-bounce still
	-- work), AutoSprint-via-tick stops, and the print/warn/GetLogHistory log-hiding is gone.
	if hookmetamethod then
		oldNameCall = hookmetamethod(game, "__namecall", onNameCall)
		oldNewIndex = hookmetamethod(game, "__newindex", onNewIndex)
		usingMetaMethodHooks = true
	else
		oldNameCall = hookfunction(getrawmetatable(game).__namecall, onNameCall)
		oldNewIndex = hookfunction(getrawmetatable(game).__newindex, onNewIndex)
		usingMetaMethodHooks = false
	end
end

---@note: Hooking.earlyInit() must have already run before this.
function Hooking.init()
	if game.PlaceId == LOBBY_PLACE_ID then
		return
	end

	local requests = replicatedStorage:WaitForChild("Requests", 30)
	if not requests then
		return error("Requests folder not found.")
	end

	---@note: Dynamically get the ban remotes.
	local banRemoteCount = 0

	for _, request in next, requests:GetChildren() do
		local hasChangedConnection = #getconnections(request.Changed)
		if hasChangedConnection <= 0 then
			continue
		end

		banRemoteCount = banRemoteCount + 1
		banRemotes[request] = true
	end

	-- Resolve the input-remote keys ONCE here, on the main (synchronized) thread, so the process-global
	-- FireServer / UnreliableFireServer hooks can identify them with getCachedRemote (pure table reads) and
	-- never run the game's encoder from the hook body. KeyHandling.init has already run by this point.
	KeyHandling.prewarm({ "LeftClick", "CriticalClick", "FeintClick", "OffhandAttack", "Block" })

	local nulledBanRemotes = {}

	for _, instance in next, getnilinstances() do
		if instance.Name ~= "NulledBanRemote" then
			continue
		end

		nulledBanRemotes[#nulledBanRemotes + 1] = instance
	end

	if #nulledBanRemotes ~= 2 then
		if banRemoteCount ~= 2 then
			return error("Anticheat has less or more than two ban remotes.")
		end
	end

	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator", 30)
	if not effectReplicator then
		return error("EffectReplicator not found.")
	end

	local effectReplicatorModule = require(effectReplicator)

	-- NOTE: luma no longer hooks HasEffect. It was a process-global hookfunction whose body called checkcaller()
	-- (executor reflection) on EVERY HasEffect call -- and the game calls HasEffect constantly, including from its
	-- parallel Actor VMs. Reflection dispatched mid-parallel-phase is the illegal cross-phase op the engine
	-- Kernel-panics on ("RSL - panic ...Kernel,2090") -- the exact crash the old getgc-in-tostring hook caused.
	-- PR never hooks HasEffect; it does NoAttackingClientChecks by REMOVING the attack effects (see
	-- StateListener.onEffectReplicated -> effect:Remove for ATTACK_EFFECT_CLASSES), which luma already does too.
	noFallModule = effectReplicatorModule
	if noFallConnection then
		pcall(function()
			noFallConnection:Disconnect()
		end)
	end
	noFallConnection = runService.Heartbeat:Connect(function()
		maintainNoFall()
	end)

	if actionRollPumpConnection then
		pcall(function()
			actionRollPumpConnection:Disconnect()
		end)
	end
	actionRollPumpConnection = runService.Heartbeat:Connect(drainActionRolls)

	if autoSprintConnection then
		pcall(function()
			autoSprintConnection:Disconnect()
		end)
	end
	autoSprintConnection = userInputService.InputBegan:Connect(onSprintInput)

	-- Auto Flow State (Project Rain's auto_flow_state.lua model): bind to the current character's
	-- Humanoid.AnimationPlayed and rebind on every respawn. The flow-state fire lives entirely on this
	-- engine signal -- never in a remote hook -- so it cannot re-enter a FireServer/__namecall callstack.
	local flowLocalPlayer = playersService.LocalPlayer
	if flowStateCharConnection then
		pcall(function()
			flowStateCharConnection:Disconnect()
		end)
		flowStateCharConnection = nil
	end
	if flowLocalPlayer then
		if flowLocalPlayer.Character then
			bindFlowStateCharacter(flowLocalPlayer.Character)
		end
		flowStateCharConnection = flowLocalPlayer.CharacterAdded:Connect(bindFlowStateCharacter)
	end

	---@note: KeyHandler is now fully emulated (Project Rain style) instead of being

	local replicatedStorage = game:GetService("ReplicatedStorage")
	local modules = replicatedStorage:WaitForChild("Modules", 30)
	local clientManager = modules and modules:WaitForChild("ClientManager", 30)
	local keyHandler = clientManager and clientManager:WaitForChild("KeyHandler", 30)
	if not keyHandler then
		return error("KeyHandler not found.")
	end

	local keyHandlerModule = require(keyHandler)

	---@note: Future require()s of the module now build our emulated table.
	hookedKeyHandlerModule = keyHandlerModule

	oldKeyHandlerModule = hookfunction(
		keyHandlerModule,
		LPH_NO_VIRTUALIZE(function()
			return { emulatedGetKey, emulatedCreateKey, "Luma On Top" }
		end)
	)

	---@note: Replace the already-created get/create pair in memory so existing
	for _, candidate in next, getgc(true) do
		if typeof(candidate) ~= "table" then
			continue
		end

		if getrawmetatable(candidate) then
			continue
		end

		if #candidate ~= 2 then
			continue
		end

		if typeof(candidate[1]) ~= "function" or typeof(candidate[2]) ~= "function" then
			continue
		end

		local getFn = candidate[1]
		local createFn = candidate[2]

		local getOk, getInfo = pcall(debug.getinfo, getFn)
		local createOk, createInfo = pcall(debug.getinfo, createFn)
		if not getOk or not createOk or not getInfo or not createInfo then
			continue
		end

		if not getInfo.source:find("KeyHandler") or not createInfo.source:find("KeyHandler") then
			continue
		end

		hookedGetFn = getFn
		hookedCreateFn = createFn

		oldGetKey = hookfunction(getFn, emulatedGetKey)
		oldCreateKey = hookfunction(createFn, emulatedCreateKey)

		candidate[1] = emulatedGetKey
		candidate[2] = emulatedCreateKey

		break
	end

	if not hookedGetFn then
		Logger.warn("KeyHandler get/create pair not found in getgc; module hook only.")
	end

	if not LPH_OBFUSCATED or shared.Luma.verbose then
		Logger.warn("Client-side anticheat has been penetrated.")
	end
end

function Hooking.detach()
	local localPlayer = playersService.LocalPlayer

	if autoSprintConnection then
		pcall(function()
			autoSprintConnection:Disconnect()
		end)
		autoSprintConnection = nil
	end
	autoSprintActive = false

	if actionRollPumpConnection then
		pcall(function()
			actionRollPumpConnection:Disconnect()
		end)
		actionRollPumpConnection = nil
	end
	table.clear(pendingActionRolls)

	if flowStateAnimConnection then
		pcall(function()
			flowStateAnimConnection:Disconnect()
		end)
		flowStateAnimConnection = nil
	end
	if flowStateCharConnection then
		pcall(function()
			flowStateCharConnection:Disconnect()
		end)
		flowStateCharConnection = nil
	end

	if hookedKeyHandlerModule and oldKeyHandlerModule then
		hookfunction(hookedKeyHandlerModule, oldKeyHandlerModule)
	end

	if hookedGetFn and oldGetKey then
		hookfunction(hookedGetFn, oldGetKey)
	end

	if hookedCreateFn and oldCreateKey then
		hookfunction(hookedCreateFn, oldCreateKey)
	end

	if oldToString then
		hookfunction(tostring, oldToString)
	end

	if oldNameCall then
		if usingMetaMethodHooks and hookmetamethod then
			hookmetamethod(game, "__namecall", oldNameCall)
		else
			hookfunction(getrawmetatable(game).__namecall, oldNameCall)
		end
	end

	if oldNewIndex then
		if usingMetaMethodHooks and hookmetamethod then
			hookmetamethod(game, "__newindex", oldNewIndex)
		else
			hookfunction(getrawmetatable(game).__newindex, oldNewIndex)
		end
	end

	if oldFireServer then
		hookfunction(Instance.new("RemoteEvent").FireServer, oldFireServer)
	end

	if oldUnreliableFireServer then
		hookfunction(Instance.new("UnreliableRemoteEvent").FireServer, oldUnreliableFireServer)
	end

	local effectReplicator = getEffectReplicator()
	local effectReplicatorModule = effectReplicator and require(effectReplicator)


	-- Stop maintaining NoFall and clear any effect we left behind.
	if noFallConnection then
		pcall(function()
			noFallConnection:Disconnect()
		end)
		noFallConnection = nil
	end
	if effectReplicatorModule then
		pcall(function()
			local effect = effectReplicatorModule:FindEffect("NoFall")
			if effect then
				effect:Debris(0.1)
			end
		end)
	end
	noFallModule = nil
	noFallLastOn = false

	usingMetaMethodHooks = false

	Logger.warn("Pulled out of client-side anticheat.")
end

return Hooking
end)
__bundle_register("@luma/Game/InputClient", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Never call the roll function from the cache. We only need this to get the last roll move direction.
local InputClient = {
	sprintFunctionCache = nil,
	rollFunctionCache = nil,
}

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@module Game.KeyHandling
local KeyHandling = require("@luma/Game/KeyHandling")

---@module Game.SelfFire
local SelfFire = require("@luma/Game/SelfFire")

---@module Utility.TaskSpawner
local TaskSpawner = require("@luma/Utility/TaskSpawner")

local runService = game:GetService("RunService")
local replicatedStorage = game:GetService("ReplicatedStorage")
local players = game:GetService("Players")
local tweenService = game:GetService("TweenService")

local unreliableFireServer = Instance.new("UnreliableRemoteEvent").FireServer

local inputDataCache = nil

---@return table?
local getEffectModule = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return nil
	end

	return require(effectReplicator)
end)

local freefallTrack = nil
local slideJumpTrack = nil
local cancelLeftTrack = nil
local cancelRightTrack = nil
local jumpAnimTrack = nil
local crouchTrack = nil
local groundslideTrack = nil

local slideBodyVelocity = nil
local slideActive = false

local crouchActive = false
local crouchSession = 0

---@return boolean
local landedCheck = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local humanController = InputClient.getHumanController()
	if not humanController then
		return
	end

	local sprintSpeed = effectReplicatorModule:FindEffect("SprintSpeed")
	if not sprintSpeed then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	local inputClient = characterHandler and characterHandler:FindFirstChild("InputClient")
	if not inputClient then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return
	end

	local torso = character:FindFirstChild("Torso")
	if not torso then
		return
	end

	local groundSensor = humanController.GroundSensor
	if not groundSensor then
		return
	end

	local stopDodge = KeyHandling.getRemote("StopDodge")
	if not stopDodge then
		return
	end

	local inputData = InputClient.getInputData()
	if not inputData then
		return
	end

	local repDebris = replicatedStorage:FindFirstChild("Debris")
	if not repDebris then
		return
	end

	local sounds = replicatedStorage:FindFirstChild("Sounds")
	local sliding = sounds and sounds:FindFirstChild("Sliding")
	if not sliding then
		return
	end

	local modules = replicatedStorage:FindFirstChild("Modules")
	local vectorMaths = modules and modules:FindFirstChild("VectorMaths")
	local vectorMathModule = vectorMaths and require(vectorMaths)
	if not vectorMathModule then
		return
	end

	local sensedPart = groundSensor.SensedPart

	if not effectReplicatorModule:HasAny("Swimming", "ClientSwim", "Gliding", "Knocked") then
		if not sensedPart then
			return false
		end

		if sensedPart and sensedPart.CollisionGroup == "Ship" then
			effectReplicatorModule:EnsureEffect("OnShip")
		elseif effectReplicatorModule:HasEffect("OnShip") then
			effectReplicatorModule:RemoveEffectsOfClass("OnShip")
		end
	end

	if freefallTrack.IsPlaying then
		freefallTrack:Stop(0.15)
	end

	if not effectReplicatorModule:HasEffect("Falling") then
		return true
	end

	effectReplicatorModule:RemoveEffectsOfClass("Falling")
	effectReplicatorModule:RemoveEffectsOfClass("ShipJump")
	effectReplicatorModule:RemoveEffectsOfClass("WingDashCooldown")

	humanoid.Jump = false

	effectReplicatorModule:CreateEffect("Landed"):Debris(0.05)

	if effectReplicatorModule:HasEffect("SlideJumping") and not effectReplicatorModule:HasEffect("GravityField") then
		effectReplicatorModule:RemoveEffectsOfClass("SlideJumping")

		if sprintSpeed and sprintSpeed.Value >= 9 then
			sprintSpeed.Value = sprintSpeed.Value - 3
		end

		local lookVector = root.CFrame.LookVector * 3
		local slideJump = torso:FindFirstChild("SlideJump")

		if slideJump then
			slideJump:Destroy()
		end

		if effectReplicatorModule:HasEffect("Sprinting") then
			humanoid:LoadAnimation(inputClient.SlideJumpTransition):Play(nil, 0.65)
		else
			humanoid:LoadAnimation(inputClient.LandingAnim):Play(nil, 0.65)
		end

		if slideJumpTrack.IsPlaying and effectReplicatorModule:HasEffect("Equipped") then
			slideJumpTrack:Stop(0.15)
		end

		stopDodge:FireServer(inputData, effectReplicatorModule:HasEffect("LightAttack"), true)

		local lookVectorUnitMulti = lookVector.Unit * 50

		if sensedPart and sensedPart.AssemblyMass > root.AssemblyMass then
			lookVectorUnitMulti = lookVectorUnitMulti
				+ vectorMathModule.getVelocityAtPoint(sensedPart, groundSensor.HitFrame.Position)
		end

		local bodyVelocity = Instance.new("BodyVelocity")
		bodyVelocity.Name = "SlideJump2"
		bodyVelocity.Velocity = lookVectorUnitMulti
		bodyVelocity.MaxForce = Vector3.new(80000, 80000, 80000, 0)
		bodyVelocity:AddTag("AllowedBM")
		bodyVelocity.Parent = torso

		repDebris:Fire(bodyVelocity, 0.2)

		local slidingSound = sliding:Clone()
		slidingSound.Parent = root
		slidingSound:Play()

		repDebris:Fire(slidingSound, 0.25)

		tweenService
			:Create(slidingSound, TweenInfo.new(0.25), {
				Volume = 0,
			})
			:Play()
	end

	task.delay(0.1, function()
		effectReplicatorModule:RemoveEffectsOfClass("WallJumpCD")
		effectReplicatorModule:RemoveEffectsOfClass("BigMomentum")
		task.wait(2)
	end)

	return true
end)

local freefallCheck = LPH_NO_VIRTUALIZE(function()
	if landedCheck() then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	if effectReplicatorModule:HasEffect("OnShip") then
		effectReplicatorModule:RemoveEffectsOfClass("OnShip")
		effectReplicatorModule:EnsureEffect("ShipJump"):Debris(5, true)
	end

	effectReplicatorModule:EnsureEffect("Falling")

	local fallTime = tick() - (effectReplicatorModule:GetEffectEpoch("Falling") or 0)

	if
		effectReplicatorModule:HasAny("DashIt", "Jumped", "UsingAbility", "LightAttack", "Action")
		or root.AssemblyLinearVelocity.Y > 0
	then
		return freefallTrack.IsPlaying and freefallTrack:Stop(0.1)
	end

	if freefallTrack.IsPlaying then
		return
	end

	if fallTime > 0.5 and root.AssemblyLinearVelocity.Y < 0 then
		freefallTrack.Priority = Enum.AnimationPriority.Movement
		freefallTrack:Play(0.3)
	end
end)

---@return boolean
local inAirCheck = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return
	end

	if effectReplicatorModule:HasEffect("Swimming") then
		return false
	elseif humanoid:GetState() == Enum.HumanoidStateType.Freefall then
		return true
	elseif effectReplicatorModule:HasEffect("AirBorne") then
		return true
	else
		return false
	end
end)

---@return boolean
local movementCheck = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if effectReplicatorModule:HasEffect("Action") then
		return false
	elseif effectReplicatorModule:HasEffect("NoParkour") then
		return false
	elseif effectReplicatorModule:HasEffect("Knocked") or effectReplicatorModule:HasEffect("Unconscious") then
		return false
	elseif effectReplicatorModule:HasEffect("Pinned") or effectReplicatorModule:HasEffect("Carried") then
		return false
	else
		return true
	end
end)

---@param tbl table
---@param value any
---@return boolean
local manualTableFind = LPH_NO_VIRTUALIZE(function(tbl, value)
	for _, val in next, tbl do
		if val ~= value then
			continue
		end

		return true
	end
end)

---@param tbl table
---@return boolean
local hasNonBooleans = LPH_NO_VIRTUALIZE(function(tbl)
	for _, value in next, tbl do
		if typeof(value) == "boolean" then
			continue
		end

		return false
	end

	return true
end)

---@param tbl table
local getTableLength = LPH_NO_VIRTUALIZE(function(tbl)
	local count = 0

	for _ in next, tbl do
		count = count + 1
	end

	return count
end)

---@param tbl table
local validateKeys = LPH_NO_VIRTUALIZE(function(tbl)
	local allowedKeys = {
		["Left"] = true,
		["Right"] = true,
		["W"] = true,
		["A"] = true,
		["S"] = true,
		["D"] = true,
		["Thumbstick1"] = true,
		["C"] = true,
		["f"] = true,
		["H"] = true,
		["Space"] = true,
		["ctrl"] = true,
	}

	for key, _ in next, tbl do
		if allowedKeys[key] then
			continue
		end

		return false
	end

	return true
end)

---@return Vector3?
InputClient.getLastRollMoveDirection = LPH_NO_VIRTUALIZE(function()
	local rollFunction = InputClient.rollFunctionCache
	if not rollFunction then
		return nil
	end

	local lastRollMoveDirection = nil

	for _, upvalue in next, debug.getupvalues(rollFunction) do
		if typeof(upvalue) ~= "Vector3" then
			continue
		end

		lastRollMoveDirection = upvalue
		break
	end

	if not lastRollMoveDirection then
		lastRollMoveDirection = Vector3.zero
	end

	if lastRollMoveDirection and typeof(lastRollMoveDirection) ~= "Vector3" then
		return nil
	end

	return lastRollMoveDirection
end)

---@return table?
InputClient.getHumanController = LPH_NO_VIRTUALIZE(function()
	---@note: Shouldn't be too many connections to PreSimulation.
	for _, connection in next, getconnections(runService.PreSimulation) do
		local func = connection.Function
		if not func then
			continue
		end

		if iscclosure(func) or isexecutorclosure(func) then
			continue
		end

		local upvalues = debug.getupvalues(func)
		if not upvalues then
			continue
		end

		for _, upvalue in next, upvalues do
			if typeof(upvalue) ~= "table" then
				continue
			end

			if upvalue.Jumping == nil then
				continue
			end

			return upvalue
		end
	end

	return nil
end)

---@return table?
InputClient.getInputData = LPH_NO_VIRTUALIZE(function()
	return inputDataCache
end)

---@param cframe CFrame
---@param ignoreChecks boolean
InputClient.left = LPH_NO_VIRTUALIZE(function(cframe, ignoreChecks, forceGround)
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return
	end

	if effectReplicatorModule:HasEffect("InDialogue") then
		return
	end

	local inputData = InputClient.getInputData()
	if not inputData then
		return Logger.warn("Cannot left click without input data.")
	end

	local leftClickRemote = KeyHandling.getRemote("LeftClick")
	if not leftClickRemote then
		return
	end

	if not ignoreChecks then
		if
			effectReplicatorModule:HasEffect("LightAttack")
			or effectReplicatorModule:HasEffect("CriticalAttack")
			or effectReplicatorModule:HasEffect("Followup")
			or effectReplicatorModule:HasEffect("Parried")
		then
			return
		end
	end

	---@note: Missing M1-Hold and Input Buffering functionality but I don't think the caller cares about it.
	-- forceGround forces a grounded m1 (no aerial), matching PR's m1_hold no_aerials behavior.
	local aerial = (not forceGround) and inAirCheck() or false
	-- Mark this as our own fire so the UnreliableFireServer hook passes it through (no re-block / re-mixup)
	-- without needing checkcaller() -- see Game/SelfFire.
	SelfFire.wrap(function()
		unreliableFireServer(leftClickRemote, aerial, cframe, inputData)
	end)
end)

---@param tool Tool
InputClient.amantra = LPH_NO_VIRTUALIZE(function(tool)
	local character = players.LocalPlayer.Character
	if not character then
		return Logger.warn("Cannot activate mantra without character.")
	end

	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return Logger.warn("Cannot activate mantra without humanoid root part.")
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	if not characterHandler then
		return Logger.warn("Cannot activate mantra without character handler.")
	end

	local requests = characterHandler:FindFirstChild("Requests")
	if not requests then
		return Logger.warn("Cannot activate mantra without requests.")
	end

	local activateMantraRemote = requests:FindFirstChild("ActivateMantra")
	if not activateMantraRemote then
		return Logger.warn("Cannot activate mantra without ActivateMantra remote.")
	end

	if typeof(tool) ~= "Instance" or not tool:IsA("Tool") then
		return Logger.warn("Cannot activate mantra without valid tool.")
	end

	activateMantraRemote:FireServer(tool)
end)

InputClient.crouch = LPH_NO_VIRTUALIZE(function()
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	local requests = characterHandler and characterHandler:FindFirstChild("Requests")
	if not requests then
		return
	end

	local crouchRemote = requests:FindFirstChild("ServerCrouch")
	if not crouchRemote then
		return
	end

	local effectReplicatorModule = getEffectModule()
	if not effectReplicatorModule then
		return
	end

	local humanoid = character:FindFirstChildOfClass("Humanoid")

	if crouchTrack then
		crouchTrack:Play()
	end

	crouchRemote:FireServer(true)
	effectReplicatorModule:CreateEffect("ClientCrouch")

	crouchActive = true
	crouchSession = crouchSession + 1
	local session = crouchSession

	task.spawn(function()
		while crouchActive and crouchSession == session and crouchTrack do
			if humanoid and humanoid.MoveDirection.Magnitude < 0.1 then
				crouchTrack:AdjustSpeed(0)
			elseif humanoid then
				crouchTrack:AdjustSpeed(humanoid.WalkSpeed / 15.5)
			end

			task.wait()
		end
	end)
end)

InputClient.uncrouch = LPH_NO_VIRTUALIZE(function()
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	local requests = characterHandler and characterHandler:FindFirstChild("Requests")
	if not requests then
		return
	end

	local crouchRemote = requests:FindFirstChild("ServerCrouch")
	if not crouchRemote then
		return
	end

	local effectReplicatorModule = getEffectModule()
	if not effectReplicatorModule then
		return
	end

	crouchActive = false
	crouchRemote:FireServer(false)

	if crouchTrack then
		crouchTrack:Stop()
	end

	effectReplicatorModule:RemoveEffectsOfClass("ClientCrouch")
end)

InputClient.slide = LPH_NO_VIRTUALIZE(function()
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	local serverSlide = KeyHandling.getRemote("ServerSlide")
	if not serverSlide then
		return
	end

	local effectReplicatorModule = getEffectModule()
	if not effectReplicatorModule then
		return
	end

	local characterHashes = replicatedStorage:FindFirstChild("CharacterHashes")
	local characterHashesModule = characterHashes and require(characterHashes)
	local hashData = characterHashesModule and characterHashesModule.Snap(character)

	local healthPercent = humanoid.Health / humanoid.MaxHealth
	if hashData and hashData["Endurance Runner"] then
		healthPercent = 0.25 + healthPercent * 0.75
	end

	local agility = character:FindFirstChild("PassiveAgility")
	local agilityValue = agility and agility.Value or 0
	local isDanger = effectReplicatorModule:HasEffect("DangerPvP")
	local speed = 20 + agilityValue * (isDanger and 0.4 or 0.5) * healthPercent

	if effectReplicatorModule:HasEffect("ClientDodge") then
		speed = speed + (isDanger and 3 or 10)
	end

	if hashData then
		local kongaRing = hashData["Konga's Clutch Ring"]
		local slick = hashData.Slick

		if kongaRing then
			speed = speed + (isDanger and 5 or 15)
		end

		if slick then
			speed = speed + (isDanger and 0 or 15)
		end

		if not kongaRing and not slick and effectReplicatorModule:FindEffect("BigMomentum") then
			speed = speed + 15
		end
	end

	if effectReplicatorModule:HasEffect("AirBorne") then
		speed = speed + 15
	end

	if effectReplicatorModule:HasEffect("SpeedSlide") then
		speed = speed + 10
	elseif effectReplicatorModule:HasEffect("WardingRadiance") then
		speed = speed + (isDanger and 7.5 or 15)
	end

	local slideEffect = effectReplicatorModule:CreateEffect("ClientSlide2")
	slideEffect:Debris(60)

	if groundslideTrack then
		groundslideTrack:Play()
	end

	serverSlide:FireServer(true)

	local rootCollider = character:FindFirstChild("RootCollider")
	local colliderWeld = rootCollider and rootCollider:FindFirstChild("ColliderWeld")
	if colliderWeld then
		colliderWeld.C0 = CFrame.new(0, -1.9, 0)
	end

	local velocity = root.CFrame.LookVector * speed
	root.AssemblyLinearVelocity = velocity

	local bodyVelocity = Instance.new("BodyVelocity")
	bodyVelocity:AddTag("LocalMover")
	bodyVelocity.Name = "SlideVel"
	bodyVelocity.MaxForce = Vector3.new(100000, 0, 100000)
	bodyVelocity.Velocity = velocity
	bodyVelocity:AddTag("AllowedBM")
	bodyVelocity.Parent = root

	slideBodyVelocity = bodyVelocity
	slideActive = true

	task.spawn(function()
		while slideActive and bodyVelocity.Parent do
			task.wait(0.03)

			local isIce = humanoid.FloorMaterial == Enum.Material.Ice
				and not (
					hashData
					and (
						hashData["Steady Footing"]
						or effectReplicatorModule:HasEffect("WardingRadiance")
					)
				)

			speed = speed - (isIce and 0.25 or 1)
			if speed <= 0 then
				break
			end

			bodyVelocity.Velocity = root.CFrame.LookVector * speed
		end
	end)

	task.delay(3, function()
		if slideActive then
			InputClient.unslide()
		end
	end)
end)

InputClient.unslide = LPH_NO_VIRTUALIZE(function()
	slideActive = false

	local serverSlideStop = KeyHandling.getRemote("ServerSlideStop")
	if serverSlideStop then
		serverSlideStop:FireServer()
	end

	if slideBodyVelocity and slideBodyVelocity.Parent then
		slideBodyVelocity:Destroy()
		slideBodyVelocity = nil
	end

	local character = players.LocalPlayer.Character
	if character then
		local rootCollider = character:FindFirstChild("RootCollider")
		local colliderWeld = rootCollider and rootCollider:FindFirstChild("ColliderWeld")
		if colliderWeld then
			colliderWeld.C0 = CFrame.new()
		end
	end

	if groundslideTrack then
		groundslideTrack:Stop()
	end

	local effectReplicatorModule = getEffectModule()
	if effectReplicatorModule then
		effectReplicatorModule:RemoveEffectsOfClass("ClientSlide2")
	end
end)

InputClient.vent = LPH_NO_VIRTUALIZE(function()
	local character = players.LocalPlayer.Character
	if not character then
		return Logger.warn("Cannot vent without character.")
	end

	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return Logger.warn("Cannot vent without humanoid root part.")
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	if not characterHandler then
		return Logger.warn("Cannot vent without character handler.")
	end

	local requests = characterHandler:FindFirstChild("Requests")
	if not requests then
		return Logger.warn("Cannot vent without requests.")
	end

	local ventRemote = requests:FindFirstChild("Vent")
	if not ventRemote then
		return Logger.warn("Cannot vent without vent remote.")
	end

	ventRemote:FireServer()
end)

---@param options DodgeOptions
InputClient.dodge = LPH_NO_VIRTUALIZE(function(options)
	-- Dodge is now a DIRECT remote (no longer keyed via KeyHandler), so getRemote("Dodge") returns nil.
	-- Resolve it by name from CharacterHandler.Requests (where the other combat remotes live), falling
	-- back to the global ReplicatedStorage.Requests.
	local dodgeCharacter = players.LocalPlayer and players.LocalPlayer.Character
	local dodgeHandler = dodgeCharacter and dodgeCharacter:FindFirstChild("CharacterHandler")
	local dodgeRequests = dodgeHandler and dodgeHandler:FindFirstChild("Requests")
	local dodge = dodgeRequests and dodgeRequests:FindFirstChild("Dodge")
	if not dodge then
		local globalRequests = replicatedStorage:FindFirstChild("Requests")
		dodge = globalRequests and globalRequests:FindFirstChild("Dodge")
	end
	if not dodge then
		return Logger.warn("Cannot dodge without dodge remote.")
	end

	local stopDodge = KeyHandling.getRemote("StopDodge")
	if not stopDodge then
		return Logger.warn("Cannot dodge without stop dodge remote.")
	end

	local inputData = InputClient.getInputData()
	if not inputData then
		return Logger.warn("Cannot dodge without input data.")
	end

	local effectReplicatorModule = getEffectModule()
	if not effectReplicatorModule then
		return Logger.warn("Cannot dodge without effect replicator module.")
	end

	if options.direct and not options.full then
		-- New Dodge signature: FireServer(dodgeType, optionsTable). The game passes
		-- { ancient, spin_attack, in_air }; the old (type, nil, nil, false) form is now wrong args.
		dodge:FireServer("roll", { ancient = false, spin_attack = effectReplicatorModule:HasEffect("SpinAttack"), in_air = false })

		task.delay(0.15, function()
			stopDodge:FireServer(inputData, effectReplicatorModule:HasEffect("LightAttack"), true)
		end)

		return
	end

	local keybinds = replicatedStorage:FindFirstChild("KeyBinds")
	local keybindsModule = keybinds and require(keybinds)
	if not keybindsModule or not keybindsModule.ForceActionDown or not keybindsModule.ForceActionUp then
		return Logger.warn("Cannot dodge without keybinds module.")
	end

	keybindsModule.ForceActionDown("Dodge")
	keybindsModule.ForceActionUp("Dodge")

	if options.rollCancel then
		task.wait(options.rollCancelDelay)

		local clientFeint = effectReplicatorModule:CreateEffect("ClientFeint")
		if clientFeint then
			clientFeint:Debris(0.1)
		end
	end
end)

InputClient.ejump = LPH_NO_VIRTUALIZE(function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return Logger.warn("Cannot dodge without effect replicator.")
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return Logger.warn("Cannot dodge without effect replicator module.")
	end

	if not jumpAnimTrack then
		return Logger.warn("Cannot jump without jump animation track.")
	end

	local character = players.LocalPlayer.Character
	if not character then
		return Logger.warn("Cannot jump without character.")
	end

	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return Logger.warn("Cannot jump without humanoid root part.")
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	if not characterHandler then
		return Logger.warn("Cannot jump without character handler.")
	end

	local requests = characterHandler:FindFirstChild("Requests")
	if not requests then
		return Logger.warn("Cannot jump without requests.")
	end

	local jumpRemote = requests:FindFirstChild("Jump")
	if not jumpRemote then
		return Logger.warn("Cannot jump without jump remote.")
	end

	effectReplicatorModule:CreateEffect("Jumped"):Debris(0.1)
	jumpAnimTrack:Play(0.05)

	if effectReplicatorModule:HasEffect("HasWeapon") then
		jumpAnimTrack.Priority = Enum.AnimationPriority.Idle
	else
		jumpAnimTrack.Priority = Enum.AnimationPriority.Movement
	end

	TaskSpawner.delay("InputClient_EJump_Track", function()
		return 0.4
	end, function()
		jumpAnimTrack:AdjustSpeed(0.5)
		jumpAnimTrack:Stop(0.1)
	end)

	TaskSpawner.spawn("InputClient_EJump_Loop", function()
		local start = os.clock()

		while task.wait() do
			if os.clock() - start >= 0.2 then
				break
			end

			if not jumpAnimTrack or not jumpAnimTrack.IsPlaying then
				break
			end

			jumpRemote:FireServer()
		end
	end)
end)

InputClient.feint = LPH_NO_VIRTUALIZE(function()
	local character = players.LocalPlayer.Character
	if not character then
		return Logger.warn("Cannot feint without character.")
	end

	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return Logger.warn("Cannot feint without humanoid root part.")
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	if not characterHandler then
		return Logger.warn("Cannot feint without character handler.")
	end

	local requests = characterHandler:FindFirstChild("Requests")
	if not requests then
		return Logger.warn("Cannot feint without requests.")
	end

	local feintReleaseRemote = requests:FindFirstChild("FeintRelease")
	if not feintReleaseRemote then
		return Logger.warn("Cannot feint without feint release remote.")
	end

	local inputDataTable = InputClient.getInputData()
	if not inputDataTable then
		return Logger.warn("Cannot feint without input data.")
	end

	local feintClickRemote = KeyHandling.getRemote("FeintClick")
	if not feintClickRemote then
		return Logger.warn("Cannot feint without feint click remote.")
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return Logger.warn("Cannot dodge without effect replicator.")
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return Logger.warn("Cannot dodge without effect replicator module.")
	end

	if effectReplicatorModule:HasEffect("ClientDodge") then
		effectReplicatorModule:CreateEffect("ClientFeint"):Debris(0.4)
	end

	if humanoidRootPart:FindFirstChild("ClientRemove") then
		humanoidRootPart.ClientRemove:Destroy()
	end

	inputDataTable["Right"] = true

	-- Our own feint fire -- flag it so the UnreliableFireServer hook passes it through (see Game/SelfFire).
	SelfFire.wrap(function()
		feintClickRemote:FireServer(inputDataTable)
	end)

	-- New FeintRelease signature takes no argument (was: inputDataTable).
	feintReleaseRemote:FireServer()

	inputDataTable["Right"] = false
end)

---@note: I sold my soul to the GC gods because there's no other way. This basically does a ton of intensive stuff. Updates are only done when needed.
InputClient.cache = LPH_NO_VIRTUALIZE(function()
	InputClient.sprintFunctionCache = nil
	InputClient.rollFunctionCache = nil
	inputDataCache = nil

	for _, value in next, getgc() do
		if typeof(value) ~= "function" or iscclosure(value) or isexecutorclosure(value) then
			continue
		end

		local functionName = debug.getinfo(value).name
		if not functionName then
			continue
		end

		if functionName ~= "Sprint" and functionName ~= "Roll" then
			continue
		end

		local upvalues = debug.getupvalues(value)

		if not upvalues or #upvalues <= 0 then
			continue
		end

		if functionName == "Sprint" then
			InputClient.sprintFunctionCache = value

			if not LPH_OBFUSCATED or shared.Luma.verbose then
				Logger.warn("Sprint function (%s) cache successful.", tostring(value))
			end
		end

		if functionName == "Roll" then
			InputClient.rollFunctionCache = value

			if not LPH_OBFUSCATED or shared.Luma.verbose then
				Logger.warn("Roll function (%s) cache successful.", tostring(value))
			end
		end

		if InputClient.sprintFunctionCache and InputClient.rollFunctionCache then
			break
		end
	end

	local inputData = {}

	for _, connection in next, getconnections(runService.RenderStepped) do
		local func = connection.Function
		if not func then
			continue
		end

		if iscclosure(func) then
			continue
		end

		local consts = debug.getconstants(func)
		if not manualTableFind(consts, ".lastHBCheck") then
			continue
		end

		local upvalues = debug.getupvalues(func)

		---@note: Only table with boolean values is the input table. Find a better way to filter this?
		for _, upvalue in next, upvalues do
			if typeof(upvalue) ~= "table" or getrawmetatable(upvalue) then
				continue
			end

			if not hasNonBooleans(upvalue) then
				continue
			end

			if getTableLength(upvalue) >= 1 and not validateKeys(upvalue) then
				continue
			end

			inputData = upvalue
			break
		end
	end

	inputDataCache = inputData

	local assets = replicatedStorage:FindFirstChild("Assets")
	local anims = assets and assets:FindFirstChild("Anims")
	local movement = anims and anims:FindFirstChild("Movement")
	local roll = movement and movement:FindFirstChild("Roll")
	local cancelLeft = roll and roll:FindFirstChild("CancelLeft")
	local cancelRight = roll and roll:FindFirstChild("CancelRight")

	local character = players.LocalPlayer.Character
	local characterHandler = character and character:FindFirstChild("CharacterHandler")
	local inputClient = characterHandler and characterHandler:FindFirstChild("InputClient")
	local freefallAnim = inputClient and inputClient:FindFirstChild("FreefallAnim")
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local slideJumpAnim = inputClient and inputClient:FindFirstChild("SlideJump")
	local jumpAnim = inputClient and inputClient:FindFirstChild("Jump")
	local crouchAnim = movement and movement:FindFirstChild("Crouch")
	local groundslideAnim = movement and movement:FindFirstChild("Groundslide")

	if not slideJumpAnim or not jumpAnim or not humanoid or not cancelLeft or not cancelRight or not freefallAnim then
		return false
	end

	---@note: Tracks are reset on CharacterAdded, so retries must not load a fresh copy each time.
	slideJumpTrack = slideJumpTrack or humanoid:LoadAnimation(slideJumpAnim)
	freefallTrack = freefallTrack or humanoid:LoadAnimation(freefallAnim)
	cancelLeftTrack = cancelLeftTrack or humanoid:LoadAnimation(cancelLeft)
	cancelRightTrack = cancelRightTrack or humanoid:LoadAnimation(cancelRight)
	jumpAnimTrack = jumpAnimTrack or humanoid:LoadAnimation(jumpAnim)

	if crouchAnim then
		crouchTrack = crouchTrack or humanoid:LoadAnimation(crouchAnim)
	end

	if groundslideAnim then
		groundslideTrack = groundslideTrack or humanoid:LoadAnimation(groundslideAnim)
	end

	return InputClient.sprintFunctionCache ~= nil and InputClient.rollFunctionCache ~= nil and inputDataCache ~= nil
end)

-- Re-populate the caches on the MAIN thread (serial phase), bounded + retried. This used to be driven by the
-- global `tostring` hook in Hooking.lua, but that hook is invoked from EVERY Luau VM, so the
-- getgc / getconnections / LoadAnimation work inside cache() could run during Deepwoken's parallel Actor
-- phase and Kernel-panic the client (RSL - panic: ...Kernel). A plain task.spawn keeps all of those main-VM
-- ops in the serial phase, where they're legal. cache() returns true only once the game's Sprint/Roll
-- functions and the inputData table exist, so retry until it succeeds (or a newer character supersedes this
-- run via the session bump), then STOP -- steady-state cost is zero, no periodic getgc scanning.
local cacheSession = 0
InputClient.ensureCached = LPH_NO_VIRTUALIZE(function()
	cacheSession = cacheSession + 1
	local session = cacheSession

	task.spawn(function()
		local attempts = 0
		while cacheSession == session and attempts < 40 do
			local ok, success = pcall(InputClient.cache)
			if ok and success then
				break
			end
			attempts = attempts + 1
			task.wait(0.5)
		end
	end)
end)

local characterAddedConnection = players.LocalPlayer.CharacterAdded:Connect(function()
	InputClient.sprintFunctionCache = nil
	InputClient.rollFunctionCache = nil
	inputDataCache = nil

	freefallTrack = nil
	slideJumpTrack = nil
	cancelLeftTrack = nil
	cancelRightTrack = nil
	jumpAnimTrack = nil
	crouchTrack = nil
	groundslideTrack = nil

	if slideBodyVelocity and slideBodyVelocity.Parent then
		slideBodyVelocity:Destroy()
	end

	slideBodyVelocity = nil
	slideActive = false
	crouchActive = false

	-- Re-grab Sprint/Roll/inputData + animation tracks for the new character, on the main thread.
	InputClient.ensureCached()
end)

-- Prime the cache for a character that already exists at load time (re-exec / late inject), since the
-- CharacterAdded above won't fire for it.
if players.LocalPlayer.Character then
	InputClient.ensureCached()
end

function InputClient.detach()
	cacheSession = cacheSession + 1
	characterAddedConnection:Disconnect()
end

return InputClient

end)
__bundle_register("@luma/Game/KeyHandling", function(require, _LOADED, __bundle_register, __bundle_modules)
local KeyHandling = {}

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

-- KeyHandler bypass, project-rain-oss style. luma used to REIMPLEMENT the game's name-encoder
-- (a full SHA-256) and recompute keys itself -- fragile: the moment the game changes its encoding
-- or keying, every keyed remote silently fails to resolve. Instead we grab the game's OWN encoder
-- and remote table straight out of its live KeyHandler state via getgc, so we always match whatever
-- the game is doing (it's been actively reworking this -- remotes like Dodge/Sprint have left the
-- key system entirely).
--
-- The KeyHandler state table is tagged with a magic constant at index 9 ("heaven key"), and carries
-- the encoded-name -> remote map at [12] and the encoder function at [13]. The heaven_key expression
-- is reproduced verbatim from project-rain-oss so the float value matches the game's byte-for-byte.

local pi = 0.125 + tonumber("3")
local heaven_key = 2754 * (72 % (0.6769230769205024 * 7 * 7 % 5 % 64 % 41 / 66 + 12) / 54 / (4 / 36 + 5.3655660377358485) + 1 * 4 % 52 * 21 / 4 % 35 / 3) / 35 * 38 + (66 + (8 + 4 + 5 + 2 + 19035.52631578947) / 34 + 40 % 41 / 56 % 65 * 57 + 3381) + 420 + 35 * (0.3150684931506849 + 69 + 14 / 56 + 28 + 36) + (pi)

local remotes = nil -- the game's encoded-name -> remote instance table (state[12])
local encf = nil    -- the game's name-encoder function (state[13])
local cache = {}    -- remoteName -> encoded key

---Find the game's KeyHandler state in getgc (identified by the heaven_key tag at index 9) and grab
---its remotes table + encoder.
---@return boolean
local function grabKeyHandler()
	for _, tbl in next, getgc(true) do
		if typeof(tbl) ~= "table" then
			continue
		end
		if getrawmetatable(tbl) then
			continue
		end
		if #tbl ~= 13 or tbl[9] ~= heaven_key then
			continue
		end

		remotes = tbl[12]
		encf = tbl[13]
		return remotes ~= nil and encf ~= nil
	end

	return false
end

---Encode a remote name with the game's own encoder (cached).
---@param remoteName string
---@return any
local function encode(remoteName)
	local encoded = cache[remoteName]
	if encoded == nil then
		local ok, res = pcall(encf, remoteName)
		if not ok then
			return nil
		end
		encoded = res
		cache[remoteName] = encoded
	end
	return encoded
end

KeyHandling.init = LPH_NO_VIRTUALIZE(function()
	local retries = 0

	while true do
		if (remotes and encf) or grabKeyHandler() then
			break
		end

		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("KeyHandler retry (%i attempts) grabbing remotes/enc_f", retries)
		end

		retries = retries + 1

		if retries >= 10 then
			Logger.warn("KeyHandler failed to initialize after 10 attempts.")

			return error("Please report this message to the developers.")
		end

		task.wait(0.5)
	end
end)

---Resolve a keyed remote by its original name via the game's encoder.
---@param remoteName string
---@return Instance|nil
KeyHandling.getRemote = LPH_NO_VIRTUALIZE(function(remoteName)
	if not (remotes and encf) then
		return nil
	end

	local encoded = encode(remoteName)

	return (encoded ~= nil and remotes[encoded]) or nil
end)

---Resolve a keyed remote using ONLY the already-computed key cache -- it never calls the game's encoder.
---This is project-rain-oss's `get_cache`: the process-global FireServer / UnreliableFireServer hooks run on
---every remote fire the game makes, and PR only ever does pure table reads there (cache[name] -> remotes[key]).
---luma used to call getRemote() -> encode() -> pcall(encf, ...) from those hooks, which re-invokes the game's
---grabbed encoder closure on every fire for any name that has left the key system (encode never caches a nil
---result, so it retries forever). That high-frequency game-closure call from the global hook body is the
---always-on divergence from PR. Resolving the keys once up front (KeyHandling.prewarm) and reading the cache
---here keeps the hot path to pure table lookups, exactly like PR. remotes[encoded] stays live, so re-keys are
---still followed; only the encoder call is lifted out of the hook.
---@param remoteName string
---@return Instance|nil
KeyHandling.getCachedRemote = LPH_NO_VIRTUALIZE(function(remoteName)
	if not remotes then
		return nil
	end

	local encoded = cache[remoteName]
	if encoded == nil then
		return nil
	end

	return remotes[encoded] or nil
end)

---Compute and cache the keys for a set of remote names once, from the current (main, synchronized) thread.
---Call this at init so the global fire hooks can resolve those remotes with getCachedRemote without ever
---touching the encoder from the hook context.
---@param names string[]
KeyHandling.prewarm = LPH_NO_VIRTUALIZE(function(names)
	if not (remotes and encf) then
		return
	end

	for _, remoteName in ipairs(names) do
		encode(remoteName)
	end
end)

---Register a remote under its (original) name's key, then it can be renamed by the caller.
---@param remote Instance
KeyHandling.registerRemote = LPH_NO_VIRTUALIZE(function(remote)
	if not (remotes and encf) then
		return
	end

	local encoded = encode(remote.Name)
	if encoded ~= nil then
		remotes[encoded] = remote
	end
end)

return KeyHandling

end)
__bundle_register("@luma/Game/Latency", function(require, _LOADED, __bundle_register, __bundle_modules)
local Latency = {}

local stats = game:GetService("Stats")

---@note: Perhaps one day, we can get better approximations for these.

local smoothedRtt = nil
local EMA_ALPHA = 0.25

local OUTLIER_JUMP_MULTIPLIER = 2.0
local OUTLIER_JUMP_FLOOR = 0.05

---@note: https://devforum.roblox.com/t/in-depth-information-about-robloxs-remoteevents-instance-replication-and-physics-replication-w-sources/1847340
---@note: The forum post above is misleading, not only is it the RTT time, please note that this also takes into account all delays like frame time.
---@return number?
local function rawRtt()
	local network = stats:FindFirstChild("Network")
	if not network then
		return
	end

	local serverStatsItem = network:FindFirstChild("ServerStatsItem")
	if not serverStatsItem then
		return
	end

	local dataPingItem = serverStatsItem:FindFirstChild("Data Ping")
	if not dataPingItem then
		return
	end

	return dataPingItem:GetValue() / 1000
end

---@return number
function Latency.rdelay()
	return math.max(Latency.rtt() / 2, 0.0)
end

---@return number
function Latency.sdelay()
	return math.max(Latency.rtt() / 2, 0.0)
end

---@note: This is our round-trip time (e.g double the ping) since we have a receiving delay (replication) and a sending delay when we send the input to the server.
---@todo: For every usage, the sending delay needs to be continously updated. The receiving one must be calculated once at initial send for AP ping compensation.
---@return number?
function Latency.rtt()
	local raw = rawRtt()
	if not raw then
		return smoothedRtt
	end

	if not smoothedRtt then
		smoothedRtt = raw
		return smoothedRtt
	end

	local deviation = raw - smoothedRtt
	local maxJump = math.max(smoothedRtt * OUTLIER_JUMP_MULTIPLIER, OUTLIER_JUMP_FLOOR)

	if math.abs(deviation) > maxJump then
		deviation = maxJump * (deviation < 0 and -1 or 1)
	end

	smoothedRtt = smoothedRtt + EMA_ALPHA * deviation

	return smoothedRtt
end

return Latency
end)
__bundle_register("@luma/Game/LeaderboardClient", function(require, _LOADED, __bundle_register, __bundle_modules)
local LeaderboardClient = { calling = false }

local players = game:GetService("Players")

local cachedUpvaluesTable = nil
local cachedUpvaluesFunction = nil
local lastDataCacheTime = os.clock()
local lastFunctionCacheTime = os.clock()

---@param func function?
---@return boolean
local function filterFunction(func)
	if not func or not islclosure(func) then
		return false
	end

	local info = debug.getinfo(func)
	if info.name ~= nil and info.name ~= "" then
		return false
	end

	local constants = debug.getconstants(func)
	if #constants ~= 1 or constants[1] ~= "Destroy" then
		return false
	end

	local upvalues = debug.getupvalues(func)
	if not upvalues then
		return false
	end

	return true
end

---@return function?
function LeaderboardClient.glrf()
	if cachedUpvaluesFunction and os.clock() - lastFunctionCacheTime <= 2.0 then
		return cachedUpvaluesFunction
	end

	for _, con in next, getconnections(players.PlayerRemoving) do
		local func = con.Function
		if not filterFunction(func) then
			continue
		end

		local upvalues = debug.getupvalues(func)
		if not upvalues then
			continue
		end

		local upvaluesFunction = upvalues[2]

		cachedUpvaluesFunction = upvaluesFunction
		lastFunctionCacheTime = os.clock()

		return function()
			if LeaderboardClient.calling then
				return
			end

			LeaderboardClient.calling = true

			upvaluesFunction()

			LeaderboardClient.calling = false
		end
	end

	return nil
end

---@return table?
function LeaderboardClient.gld()
	if cachedUpvaluesTable and os.clock() - lastDataCacheTime <= 2.0 then
		return cachedUpvaluesTable
	end

	for _, con in next, getconnections(players.PlayerRemoving) do
		local func = con.Function
		if not filterFunction(func) then
			continue
		end

		local upvalues = debug.getupvalues(func)
		if not upvalues then
			continue
		end

		local upvaluesTable = upvalues[1]

		cachedUpvaluesTable = upvaluesTable
		lastDataCacheTime = os.clock()

		return upvaluesTable
	end

	return nil
end

return LeaderboardClient

end)
