__bundle_register("@luma/Game/Timings/TimingContainer", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class TimingContainer
---@field timings table<string, Timing>
---@field module Timing
---@field scrambled boolean Whether entries passed to :load() come from the baked-in truth data and need one-time decoding.
local TimingContainer = {}
TimingContainer.__index = TimingContainer

---@note: Mirrors Preprocessor.py's `_inline_timings` scrambling 1:1, including the
---@param raw table
---@return table
function TimingContainer.decode(raw)
	local out = {}
	for k, v in next, raw do
		out[k] = v
	end

	local function decodeHitbox(hb)
		return {
			X = PP_SCRAMBLE_NUM(hb.X),
			Y = PP_SCRAMBLE_NUM(hb.Y),
			Z = PP_SCRAMBLE_NUM(hb.Z),
		}
	end

	if typeof(out.name) == "string" then
		out.name = PP_SCRAMBLE_STR(out.name)
	end

	if typeof(out.smod) == "string" then
		out.smod = PP_SCRAMBLE_STR(out.smod)
	end

	if typeof(out._id) == "string" and out._id ~= "" then
		out._id = PP_SCRAMBLE_STR(out._id)
	end

	if typeof(out.pname) == "string" and out.pname ~= "" then
		out.pname = PP_SCRAMBLE_STR(out.pname)
	end

	if typeof(out.ename) == "string" and out.ename ~= "" then
		out.ename = PP_SCRAMBLE_STR(out.ename)
	end

	if typeof(out.imxd) == "number" then
		out.imxd = PP_SCRAMBLE_NUM(out.imxd)
	end

	if typeof(out.imdd) == "number" then
		out.imdd = PP_SCRAMBLE_NUM(out.imdd)
	end

	if typeof(out.rpd) == "number" and out.rpd ~= 0 then
		out.rpd = PP_SCRAMBLE_NUM(out.rpd)
		if typeof(out.rsd) == "number" then
			out.rsd = PP_SCRAMBLE_NUM(out.rsd)
		end
	end

	if typeof(out.hitbox) == "table" then
		out.hitbox = decodeHitbox(out.hitbox)
	end

	if typeof(out.actions) == "table" then
		local actions = {}
		for idx, action in next, out.actions do
			local decoded = {}
			for k, v in next, action do
				decoded[k] = v
			end

			if typeof(decoded._type) == "string" then
				decoded._type = PP_SCRAMBLE_STR(decoded._type)
			end

			if typeof(decoded.name) == "string" then
				decoded.name = PP_SCRAMBLE_STR(decoded.name)
			end

			if typeof(decoded.when) == "number" then
				decoded.when = PP_SCRAMBLE_NUM(decoded.when)
			end

			if typeof(decoded.hitbox) == "table" then
				decoded.hitbox = decodeHitbox(decoded.hitbox)
			end

			actions[idx] = decoded
		end
		out.actions = actions
	end

	return out
end

---@param name string
---@return Timing?
function TimingContainer:find(name)
	for _, timing in next, self.timings do
		if timing.name ~= name then
			continue
		end

		return timing
	end
end

---@return Timing[]
function TimingContainer:list()
	local timings = {}

	for _, timing in next, self.timings do
		timings[#timings + 1] = timing
	end

	return timings
end

---@return string[]
function TimingContainer:names()
	local names = {}

	for _, timing in next, self.timings do
		names[#names + 1] = timing.name
	end

	table.sort(names)

	return names
end

---@param timing Timing
function TimingContainer:remove(timing)
	local id = timing:id()
	if not id then
		return
	end

	self.timings[id] = nil
end

---@param other TimingContainer
---@return boolean
function TimingContainer:equals(other)
	if self:count() ~= other:count() then
		return false
	end

	for id, timing in next, self.timings do
		local otherTiming = other.timings[id]
		if not otherTiming then
			return false
		end

		if not timing:equals(otherTiming) then
			return false
		end
	end

	return true
end

---@return TimingContainer
function TimingContainer:clone()
	local container = TimingContainer.new(self.module)

	for _, timing in next, self.timings do
		container:push(timing:clone())
	end

	return container
end

---@param timing Timing
function TimingContainer:push(timing)
	local id = timing:id()
	if not id then
		return
	end

	---@note: Timing array keys must all be unique.
	if self.timings[id] then
		return error(string.format("Timing identifier '%s' already exists in container.", id))
	end

	---@note: Every timing must have unique names.
	if self:find(timing.name) then
		return error(string.format("Timing name '%s' already exists in container.", timing.name))
	end

	self.timings[id] = timing
end

function TimingContainer:clear()
	self.timings = {}
end

---@return number
function TimingContainer:count()
	local count = 0

	for _ in next, self.timings do
		count = count + 1
	end

	return count
end

---@param values table
function TimingContainer:load(values)
	for _, value in next, values do
		local timing = self.module.new(self.scrambled and TimingContainer.decode(value) or value)
		if not timing then
			continue
		end

		local id = timing:id()
		if not id then
			continue
		end

		---@note: Timing array keys must all be unique.
		if self.timings[id] then
			return error(string.format("Timing identifier '%s' already exists in container.", id))
		end

		---@note: Every timing must have unique names.
		if self:find(timing.name) then
			return error(string.format("Timing name '%s' already exists in container.", timing.name))
		end

		---@note: Why are the stored timing keys different from what's loaded?

		self.timings[id] = timing
	end
end

---@return table
function TimingContainer:serialize()
	local out = {}

	for _, timing in next, self.timings do
		out[#out + 1] = timing:serialize()
	end

	return out
end

---@param module Timing
---@param scrambled boolean? Whether entries passed to :load() are baked-in truth data that needs one-time decoding.
---@return TimingContainer
function TimingContainer.new(module, scrambled)
	local self = setmetatable({}, TimingContainer)
	self.timings = {}
	self.module = module
	self.scrambled = scrambled or false
	return self
end

return TimingContainer

end)
__bundle_register("@luma/Game/Timings/TimingContainerPair", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class TimingContainerPair
---@note The configs are always prioritized over the internal timings.
---@field internal TimingContainer
---@field config TimingContainer
local TimingContainerPair = {}
TimingContainerPair.__index = TimingContainerPair

---@param internal TimingContainer
---@param config TimingContainer
---@return TimingContainerPair
function TimingContainerPair.new(internal, config)
	local self = setmetatable({}, TimingContainerPair)
	self.internal = internal
	self.config = config
	return self
end

---@param key any?
---@return Timing?
function TimingContainerPair:index(key)
	return self.config.timings[key] or self.internal.timings[key]
end

---@param name string
---@return Timing?
function TimingContainerPair:find(name)
	return self.config:find(name) or self.internal:find(name)
end

---@return Timing[]
function TimingContainerPair:list()
	local timings = {}

	for _, timing in next, self.config:list() do
		table.insert(timings, timing)
	end

	for _, timing in next, self.internal:list() do
		table.insert(timings, timing)
	end

	return timings
end

return TimingContainerPair

end)
__bundle_register("@luma/Game/Timings/TimingSave", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Game.Timings.TimingContainer
local TimingContainer = require("@luma/Game/Timings/TimingContainer")

---@module Game.Timings.AnimationTiming
local AnimationTiming = require("@luma/Game/Timings/AnimationTiming")

---@module Game.Timings.EffectTiming
local EffectTiming = require("@luma/Game/Timings/EffectTiming")

---@module Game.Timings.PartTiming
local PartTiming = require("@luma/Game/Timings/PartTiming")

---@module Game.Timings.SoundTiming
local SoundTiming = require("@luma/Game/Timings/SoundTiming")

---@class TimingSave
---@field _data TimingContainer[]
---@field _removals table<string, string[]> For every container, a list of timing IDs that we need to remove from the internal data.
local TimingSave = {}
TimingSave.__index = TimingSave

---@note: Increment me when the data structure changes and we need to add backwards compatibility.
local TIMING_SAVE_VERSION = 1

---@return TimingContainer[]
function TimingSave:get()
	return self._data
end

function TimingSave:clear()
	for _, container in next, self._data do
		container:clear()
	end
end

---@param values table
function TimingSave:load(values)
	local data = self._data

	if typeof(values.animation) == "table" then
		data.animation:load(values.animation)
	end

	if typeof(values.effect) == "table" then
		data.effect:load(values.effect)
	end

	if typeof(values.part) == "table" then
		data.part:load(values.part)
	end

	if typeof(values.sound) == "table" then
		data.sound:load(values.sound)
	end
end

---@return TimingSave
function TimingSave:clone()
	local save = TimingSave.new()

	for idx, container in next, self._data do
		save._data[idx] = container:clone()
	end

	return save
end

---@param other TimingSave
---@return boolean
function TimingSave:equals(other)
	if not other or typeof(other) ~= "table" then
		return false
	end

	for idx, container in next, self._data do
		local otherContainer = other._data[idx]
		if not otherContainer then
			return false
		end

		if not container:equals(otherContainer) then
			return false
		end
	end

	return true
end

---@return number
function TimingSave:count()
	local count = 0

	for _, container in next, self._data do
		count = count + container:count()
	end

	return count
end

---@return table
function TimingSave:serialize()
	local data = self._data

	return {
		version = TIMING_SAVE_VERSION,
		animation = data.animation:serialize(),
		effect = data.effect:serialize(),
		part = data.part:serialize(),
		sound = data.sound:serialize(),
	}
end

---@param values table?
---@return TimingSave
function TimingSave.new(values)
	local self = setmetatable({}, TimingSave)

	self._data = {
		animation = TimingContainer.new(AnimationTiming),
		effect = TimingContainer.new(EffectTiming),
		part = TimingContainer.new(PartTiming),
		sound = TimingContainer.new(SoundTiming),
	}

	if values then
		self:load(values)
	end

	return self
end

return TimingSave

end)
__bundle_register("@luma/Game/Wipe", function(require, _LOADED, __bundle_register, __bundle_modules)
local Wipe = {}

local LOBBY_PLACE_ID = 4111023553
local FRAGMENTS_OF_SELF_POS = Vector3.new(2910.00, 1133.03, 1474.00)

---@module Features.Game.Interactions
local Interactions = require("@luma/Features/Game/Interactions")

---@module Utility.PersistentData
local PersistentData = require("@luma/Utility/PersistentData")

---@module Utility.Finder
local Finder = require("@luma/Utility/Finder")

---@module Game.ServerHop
local ServerHop = require("@luma/Game/ServerHop")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

local DEBUGGING_MODE = true

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")

local function telemetryLog(...)
	if not DEBUGGING_MODE then
		return
	end

	Logger.warn(...)
end

function Wipe.pwait()
	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	local startTimestamp = os.clock()

	while task.wait() do
		if os.clock() - startTimestamp >= 30 then
			return ServerHop.hop(wdata.slot, true)
		end

		if Finder.near(FRAGMENTS_OF_SELF_POS, 200) then
			break
		end
	end
end

function Wipe.pitems()
	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	local npcs = workspace:WaitForChild("NPCs")
	local hippocampusPool = npcs:WaitForChild("Hippocampal Pool")

	for _, name in next, wdata.weapons do
		local weapon = Finder.weweapon(name)
		if not weapon then
			continue
		end

		Interactions.etool(weapon)

		Interactions.interact(hippocampusPool, {
			{ choice = "[Inspect]" },
			{ choice = "[Pass down item]" },
			{ exit = true },
		}, true)
	end
end

function Wipe.depths()
	-- Blow through the loading screen by spamming A while the LoadingGui is up (input-only -- the old
	-- Requests.StartMenu.Start remote is an anticheat honeypot, firing it = instant ban). The server
	-- brings us into the depths on its own.
	local function pressKey(keyCode)
		pcall(function()
			local vim = Instance.new("VirtualInputManager")
			vim:SendKeyEvent(true, keyCode, false, game)
			vim:SendKeyEvent(false, keyCode, false, game)
		end)
	end
	local loadingDeadline = os.clock() + 10
	while os.clock() < loadingDeadline do
		local pg = players.LocalPlayer and players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
		if not (pg and pg:FindFirstChild("LoadingGui")) then
			break
		end
		pressKey(Enum.KeyCode.A)
		task.wait(0.2)
	end

	telemetryLog("(Depths) Waiting for spawn.")

	Wipe.pwait()

	telemetryLog("(Depths) Looking for anyone in the Fragments of Self area.")

	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	if Finder.pnear(FRAGMENTS_OF_SELF_POS, 500) then
		return ServerHop.hop(wdata.slot, true)
	end

	Wipe.pitems()

	local npcs = workspace:WaitForChild("NPCs")
	local selfNpc = npcs:WaitForChild("Self")

	telemetryLog("(Depths) Teleporting and interacting with Self NPC.")

	repeat
		Interactions.interact(selfNpc, {
			{ choice = "[The End]" },
		}, true)

		task.wait()
	until not players.LocalPlayer.Character

	telemetryLog("(Depths) Wiped slot. Removing marker.")

	PersistentData.set("wdata", nil)

	if PersistentData.get("efdata") then
		PersistentData.stf("efdata", "wiped", true)
	end
end

function Wipe.lobby()
	telemetryLog("(Lobby) (Step 1) Wiping slot in lobby.")

	local requests = replicatedStorage:WaitForChild("Requests")
	local wipeSlot = requests:WaitForChild("WipeSlot")

	local wdata = PersistentData.get("wdata")
	if not wdata then
		return error("No wipe data set in PersistentData.")
	end

	repeat
		task.wait()
	until wipeSlot:InvokeServer(wdata.slot)

	telemetryLog("(Lobby) (Step 2) Wiped slot. Server hopping.")

	ServerHop.hop(wdata.slot, false)
end

---@param slot string The data slot to wipe.
---@param weapons string[]? Optional items to keep. Does not handle any validation.
function Wipe.invoke(slot, weapons)
	PersistentData.set("wdata", {
		slot = slot,
		weapons = weapons or {},
	})

	telemetryLog("(Invoke) (Step 1) Marked slot %s in data.", slot)

	if game.PlaceId == LOBBY_PLACE_ID then
		return Wipe.lobby()
	end

	return ServerHop.rlobby()
end

return Wipe

end)
__bundle_register("@luma/GUI/Library", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Адаптер Luma GUI/Library -> UI-библиотека Rain.
--
-- Автоматизация Luma использует из своей Library девять вещей:
-- AddToRegistry, Font, MainColor, FontColor, GetDarkerColor, OutlineColor,
-- AccentColor, MakeDraggable, Notify/NotifyWithSound/ManuallyManagedNotify.
-- Все они уже есть в UI-слое Rain, поэтому тянуть Luma-овскую библиотеку
-- (373 KB, с собственными иконками и окнами) незачем: две библиотеки
-- начали бы драться за CoreGui.
--
-- Здесь только проксирование на getgenv().Library. Если меню ещё не
-- поднято — методы безопасные no-op, чтобы фарма могла стартовать раньше UI.

local Library = {}

local function rain_lib()
    local ok, lib = pcall(function() return getgenv().Library end);
    if ok and lib then return lib end;
    return nil;
end

-- цвета/шрифты живут на самой библиотеке Rain; дефолты — на случай,
-- когда UI ещё не готов
local function prop(name, dflt)
    local lib = rain_lib();
    local v = lib and lib[name];
    if v ~= nil then return v end;
    return dflt;
end

Library.Font = prop("Font", Enum.Font.Gotham);
Library.MainColor = prop("MainColor", Color3.fromRGB(40, 32, 50));
Library.BackgroundColor = prop("BackgroundColor", Color3.fromRGB(28, 22, 36));
Library.FontColor = prop("FontColor", Color3.fromRGB(245, 238, 250));
Library.AccentColor = prop("AccentColor", Color3.fromRGB(243, 168, 214));
Library.OutlineColor = prop("OutlineColor", Color3.fromRGB(110, 86, 132));
Library.RiskColor = prop("RiskColor", Color3.fromRGB(255, 96, 128));

function Library:GetDarkerColor(color)
    local lib = rain_lib();
    if lib and type(lib.GetDarkerColor) == "function" then
        local ok, res = pcall(lib.GetDarkerColor, lib, color);
        if ok and res then return res end;
    end;
    -- тот же приём, что в Luma: масштабируем каналы, но не даём уйти в ноль
    return Color3.new(color.R * 0.7, color.G * 0.7, color.B * 0.7);
end

function Library:Notify(message, duration)
    local lib = rain_lib();
    if not lib or type(lib.Notify) ~= "function" then return end;
    pcall(function() lib:Notify(message, duration or 5) end);
end

function Library:NotifyWithSound(message, duration)
    local lib = rain_lib();
    if not lib then return end;
    if type(lib.NotifyWithSound) == "function" then
        pcall(function() lib:NotifyWithSound(message, duration or 5) end);
    elseif type(lib.Notify) == "function" then
        pcall(function() lib:Notify(message, duration or 5) end);
    end;
end

function Library:ManuallyManagedNotify(message, duration)
    -- в Luma уведомление само не гасится, пока не позовут HideNotification
    local lib = rain_lib();
    if not lib then return end;
    if type(lib.ManuallyManagedNotify) == "function" then
        pcall(function() lib:ManuallyManagedNotify(message, duration) end);
    elseif type(lib.Notify) == "function" then
        pcall(function() lib:Notify(message, duration) end);
    end;
end

function Library:HideNotification()
    local lib = rain_lib();
    if lib and type(lib.HideNotification) == "function" then
        pcall(function() lib:HideNotification() end);
    end;
end

function Library:MakeDraggable(guiObject)
    local lib = rain_lib();
    if lib and type(lib.MakeDraggable) == "function" then
        local ok = pcall(function() lib:MakeDraggable(guiObject) end);
        if ok then return end;
    end;
    -- запасной вариант: перетаскивание мышью вручную
    if type(guiObject) ~= "Instance" then return end;
    local dragging, start_pos, start_input = false, nil, nil;
    guiObject.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true;
            start_pos = guiObject.Position;
            start_input = input.Position;
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then dragging = false end;
            end);
        end;
    end);
    game:GetService("UserInputService").InputChanged:Connect(function(input)
        if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
            local d = input.Position - start_input;
            guiObject.Position = UDim2.new(
                start_pos.X.Scale, start_pos.X.Offset + d.X,
                start_pos.Y.Scale, start_pos.Y.Offset + d.Y
            );
        end;
    end);
end

function Library:AddToRegistry(...) return nil end

-- Luma-овские модули читают shared.*; в Rain этого нет — даём пустой контейнер
local shared = getgenv().Luma_shared;
if type(shared) ~= "table" then
    shared = { verbose = false };
    getgenv().Luma_shared = shared;
end

Library.shared = shared;

return Library
end)
__bundle_register("@luma/Utility/Attributes", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local Attributes = {}

	---@param playerCharacter Model
	---@param attribute string
	---@param cap string
	---@return boolean
	function Attributes.isNotAtCap(playerCharacter, attribute, cap)
		local useDefault = cap == ""
		local maxStat = useDefault and 100 or tonumber(cap)
		local statCap = maxStat == 0 and 100 or maxStat

		local currentStat = tonumber(playerCharacter:GetAttribute(attribute) or 0)
		if not currentStat or currentStat >= statCap then
			return false
		end

		return true
	end

	return Attributes
end)()

end)
__bundle_register("@luma/Utility/Buffer", function(require, _LOADED, __bundle_register, __bundle_modules)
local Buffer = {}

---@param cframe CFrame
local function makeNetworkable(cframe)
	local position = cframe.Position
	local axis, angle = cframe:ToAxisAngle()

	local halfAngle = angle * 0.5
	local sinHalf = math.sin(halfAngle)

	local x = axis.X * sinHalf
	local y = axis.Y * sinHalf
	local z = axis.Z * sinHalf

	return {
		Position = position,
		Rotation = { x = x, y = y, z = z },
	}
end

---@param cframe CFrame
local function makeYawNet(cframe)
	local _, yaw, _ = cframe:ToEulerAnglesYXZ()
	return {
		Position = cframe.Position,
		RotationY = yaw,
	}
end

---@param snapshotBuffer buffer
---@param offset number
---@param timestamp number
---@param cframe CFrame
---@param id number
local function packSnapshot(snapshotBuffer, offset, timestamp, cframe, id)
	buffer.writef32(snapshotBuffer, offset + 0, timestamp)
	buffer.writef32(snapshotBuffer, offset + 4, cframe.Position.X)
	buffer.writef32(snapshotBuffer, offset + 8, cframe.Position.Y)
	buffer.writef32(snapshotBuffer, offset + 12, cframe.Position.Z)

	if false then
		local networkable = makeNetworkable(cframe)

		local mappedX = math.map(networkable.Rotation.x, -1, 1, 0, 2 ^ 16 - 1)
		local mappedY = math.map(networkable.Rotation.y, -1, 1, 0, 2 ^ 16 - 1)
		local mappedZ = math.map(networkable.Rotation.z, -1, 1, 0, 2 ^ 16 - 1)

		buffer.writeu16(snapshotBuffer, offset + 16, mappedX)
		buffer.writeu16(snapshotBuffer, offset + 18, mappedY)
		buffer.writeu16(snapshotBuffer, offset + 20, mappedZ)
		buffer.writeu16(snapshotBuffer, offset + 22, id)
	else
		local networkable = makeYawNet(cframe)
		local mappedRotationY = math.map(networkable.RotationY, -math.pi, math.pi, 0, 2 ^ 16 - 1)
		buffer.writeu16(snapshotBuffer, offset + 16, mappedRotationY)
		buffer.writeu16(snapshotBuffer, offset + 18, id)
	end
end

---@param targetCFrame CFrame
---@return buffer
function Buffer.GetBufferCFrame(targetCFrame)
	local offset = 0
	local snapshotBuffer = packSnapshot(buffer.create(20), offset, os.clock(), targetCFrame, math.random(0, 25555))
	offset = offset + 20

	return snapshotBuffer
end

return Buffer
end)
