---@param name string The name of the tool to find. It is matched.
---@param exact boolean If true, the name must be an exact match.
---@return Tool[]
Finder.tools = LPH_NO_VIRTUALIZE(function(name, exact)
	local backpack = players.LocalPlayer:FindFirstChild("Backpack")
	if not backpack then
		return {}
	end

	local tools = {}

	for _, item in next, backpack:GetChildren() do
		if not item:IsA("Tool") then
			continue
		end

		if exact and (item.Name ~= name) or (not item.Name:match(name)) then
			continue
		end

		tools[#tools + 1] = item
	end

	return tools
end)

---@param position Vector3 The position to check from.
---@param range number The maximum distance to check.
---@return Model?
Finder.chest = LPH_NO_VIRTUALIZE(function(position, range)
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return nil
	end

	local nearestChest = nil
	local nearestDistance = nil

	for _, chest in next, thrown:GetChildren() do
		if not chest:IsA("Model") then
			continue
		end

		local distance = (position - chest:GetPivot().Position).Magnitude

		if range and distance > range then
			continue
		end

		if nearestDistance and distance >= nearestDistance then
			continue
		end

		nearestChest = chest
		nearestDistance = distance
	end

	return nearestChest
end)

---@param instance Instance The instance to check from.
---@param filter fun(part: BasePart): boolean A filter function which returns true if the part should be included.
---@param distance number The maximum distance in studs.
---@return BasePart[]
Finder.sdparts = LPH_NO_VIRTUALIZE(function(instance, filter, distance)
	local localCharacter = players.LocalPlayer.Character
	local localRootPart = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return
	end

	local validParts = {}
	local partsToDistance = {}

	for _, part in next, instance:GetChildren() do
		if not part:IsA("BasePart") then
			continue
		end

		if not filter(part) then
			continue
		end

		local pdistance = (part.Position - instance.Position).Magnitude

		if pdistance > distance then
			continue
		end

		validParts[#validParts + 1] = part
		partsToDistance[part] = pdistance
	end

	table.sort(validParts, function(partOne, partTwo)
		return partsToDistance[partOne] < partsToDistance[partTwo]
	end)

	return validParts
end)

---@param range number
---@return Model[]
Finder.gpir = LPH_NO_VIRTUALIZE(function(range)
	local live = workspace:FindFirstChild("Live")
	if not live then
		return
	end

	local localCharacter = players.LocalPlayer.Character
	local localRootPart = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return
	end

	local playersInRange = {}
	local playersDistance = {}

	for _, player in next, players:GetPlayers() do
		if player == players.LocalPlayer then
			continue
		end

		local character = player.Character
		if not character then
			continue
		end

		local rootPart = character:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			continue
		end

		local playerDistance = (rootPart.Position - localRootPart.Position).Magnitude
		if playerDistance > range then
			continue
		end

		table.insert(playersInRange, player)

		playersDistance[player] = playerDistance
	end

	table.sort(playersInRange, function(playerOne, playerTwo)
		return playersDistance[playerOne] < playersDistance[playerTwo]
	end)

	return playersInRange
end)

---@param range number
---@param pfilter boolean If true, filter out all players from the search.
---@return Model[]
Finder.geir = LPH_NO_VIRTUALIZE(function(range, pfilter)
	local live = workspace:FindFirstChild("Live")
	if not live then
		return
	end

	local localCharacter = players.LocalPlayer.Character
	local localRootPart = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return
	end

	local entitiesInRange = {}
	local entitiesDistance = {}

	for _, entity in next, live:GetChildren() do
		if entity == localCharacter then
			continue
		end

		local rootPart = entity:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			continue
		end

		local entityDistance = (rootPart.Position - localRootPart.Position).Magnitude
		if entityDistance > range then
			continue
		end

		table.insert(entitiesInRange, entity)

		entitiesDistance[entity] = entityDistance
	end

	table.sort(entitiesInRange, function(mobOne, mobTwo)
		return entitiesDistance[mobOne] < entitiesDistance[mobTwo]
	end)

	if not pfilter then
		return entitiesInRange
	end

	local list = {}

	for _, entity in next, entitiesInRange do
		if players:GetPlayerFromCharacter(entity) then
			continue
		end

		table.insert(list, entity)
	end

	return list
end)

return Finder

end)
__bundle_register("@luma/Utility/FiniteState", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Maid
local Maid = require("@luma/Utility/Maid")

---@module Utility.TaskSpawner
local TaskSpawner = require("@luma/Utility/TaskSpawner")

---@class FiniteState
---@field identifier string
---@field callback function(self: FiniteState): any
---@field maid Maid
local FiniteState = {}
FiniteState.__index = FiniteState

function FiniteState:detach()
	self.maid:clean()

	if not self.scallback then
		return
	end

	self.scallback()
end

---@param machine FiniteStateMachine The machine who started us.
function FiniteState:start(machine)
	self.maid:add(
		TaskSpawner.spawn(string.format("FiniteStateCallback_%s", self.identifier), self.callback, self, machine)
	)
end

---@param identifier string
---@param callback function(self: FiniteState): any
---@param scallback function?
---@return any
function FiniteState.new(identifier, callback, scallback)
	local self = setmetatable({}, FiniteState)
	self.identifier = identifier
	self.callback = callback
	self.scallback = scallback
	self.maid = Maid.new()
	return self
end

return FiniteState

end)
__bundle_register("@luma/Utility/FiniteStateMachine", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class FiniteStateMachine
---@field states FiniteState[]
---@field current string Current identifier.
---@field initial string Initial identifier.
---@field started boolean
local FiniteStateMachine = {}
FiniteStateMachine.__index = FiniteStateMachine

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@param states FiniteState[]
---@param initial string
---@return FiniteStateMachine
function FiniteStateMachine.new(states, initial)
	local self = setmetatable({}, FiniteStateMachine)
	self.states = states
	self.current = initial
	self.initial = initial
	self.started = false

	self:get(self.current)

	return self
end

---@param identifier string
---@return FiniteState
function FiniteStateMachine:get(identifier)
	for _, state in next, self.states do
		if state.identifier ~= identifier then
			continue
		end

		return state
	end

	return Logger.warn(string.format("(%s) State does not exist in states table.", identifier))
end

---@param identifier string
---@return boolean
function FiniteStateMachine:has(identifier)
	for _, state in next, self.states do
		if state.identifier ~= identifier then
			continue
		end

		return true
	end

	return false
end

function FiniteStateMachine:stop()
	if not self.started then
		return Logger.warn("Finite state machine has not been started.")
	end

	local current = self:get(self.current)
	current:detach()

	self.started = false
	self.current = self.initial
end

function FiniteStateMachine:start()
	if self.started then
		return Logger.warn("Finite state machine has already been started.")
	end

	self.started = true
	self.current = self.initial

	local current = self:get(self.current)
	current:start(self)
end

---@param identifier string
function FiniteStateMachine:transition(identifier)
	if not self.started then
		return Logger.warn("Finite state machine has not been started.")
	end

	local old = self:get(self.current)
	old:detach()

	self.current = identifier

	local new = self:get(identifier)
	new:start(self)
end

return FiniteStateMachine

end)
__bundle_register("@luma/Utility/Freecam", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class Freecam
--- Project Rain's freecam, adapted for luma. Detaches the camera from the character:
---   WASD  - move (relative to look)      Q / E        - down / up
---   mouse - look                         Up / Down    - adjust speed live
---   LeftShift - move slowly
--- The character stays put. Speed is scaled by the FreecamSpeed slider via set_speed().
local Freecam = {}

local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local ContextActionService = game:GetService("ContextActionService")

local Camera = workspace.CurrentCamera
workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
	local newCamera = workspace.CurrentCamera
	if newCamera then
		Camera = newCamera
	end
end)

local INPUT_PRIORITY = Enum.ContextActionPriority.High.Value

local running = false
local cameraPos = Vector3.new()
local cameraRot = Vector2.new()

local NAV_KEYBOARD_SPEED = Vector3.new(1, 1, 1)
local PAN_MOUSE_SPEED = Vector2.new(1, 1) * (math.pi / 64)
local NAV_ADJ_SPEED = 0.75
local NAV_SHIFT_MUL = 0.25

local navSpeed = 2

local keyboard = { W = 0, A = 0, S = 0, D = 0, E = 0, Q = 0, Up = 0, Down = 0 }
local mouse = { Delta = Vector2.new() }

local function inputVel(dt)
	navSpeed = math.clamp(navSpeed + dt * (keyboard.Up - keyboard.Down) * NAV_ADJ_SPEED, 0.01, 4)

	local kKeyboard = Vector3.new(
		keyboard.D - keyboard.A,
		keyboard.E - keyboard.Q,
		keyboard.S - keyboard.W
	) * NAV_KEYBOARD_SPEED

	local shift = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)

	return kKeyboard * (navSpeed * (shift and NAV_SHIFT_MUL or 1))
end

local function inputPan()
	local kMouse = mouse.Delta * PAN_MOUSE_SPEED
	mouse.Delta = Vector2.new()
	return kMouse
end

local function keypress(_, state, input)
	keyboard[input.KeyCode.Name] = state == Enum.UserInputState.Begin and 1 or 0
	return Enum.ContextActionResult.Sink
end

local function mousePan(_, _, input)
	local delta = input.Delta
	mouse.Delta = Vector2.new(-delta.Y, -delta.X)
	return Enum.ContextActionResult.Sink
end

local function zero(t)
	for k in next, t do
		t[k] = 0
	end
end

local function startCapture()
	ContextActionService:BindActionAtPriority(
		"FreecamKeyboard",
		keypress,
		false,
		INPUT_PRIORITY,
		Enum.KeyCode.W,
		Enum.KeyCode.A,
		Enum.KeyCode.S,
		Enum.KeyCode.D,
		Enum.KeyCode.E,
		Enum.KeyCode.Q,
		Enum.KeyCode.Up,
		Enum.KeyCode.Down
	)
	ContextActionService:BindActionAtPriority(
		"FreecamMousePan",
		mousePan,
		false,
		INPUT_PRIORITY,
		Enum.UserInputType.MouseMovement
	)
end

local function stopCapture()
	navSpeed = 1
	zero(keyboard)
	mouse.Delta = Vector2.new()
	ContextActionService:UnbindAction("FreecamKeyboard")
	ContextActionService:UnbindAction("FreecamMousePan")
end

local function getFocusDistance(cameraFrame)
	local znear = 0.1
	local viewport = Camera.ViewportSize
	local projy = 2 * math.tan(70 / 2)
	local projx = viewport.X / viewport.Y * projy
	local fx = cameraFrame.RightVector
	local fy = cameraFrame.UpVector
	local fz = cameraFrame.LookVector

	local minVect = Vector3.new()
	local minDist = 512

	for x = 0, 1, 0.5 do
		for y = 0, 1, 0.5 do
			local cx = (x - 0.5) * projx
			local cy = (y - 0.5) * projy
			local offset = fx * cx - fy * cy + fz
			local origin = cameraFrame.Position + offset * znear

			local result = workspace:Raycast(origin, offset.Unit * minDist)
			local hitPos = result and result.Position or (origin + offset.Unit * minDist)
			local dist = (hitPos - origin).Magnitude
			if minDist > dist then
				minDist = dist
				minVect = offset.Unit
			end
		end
	end

	return fz:Dot(minVect) * minDist
end

local function stepFreecam(dt)
	local vel = inputVel(dt)
	local pan = inputPan()

	cameraRot = cameraRot + pan * Vector2.new(0.75, 1) * 8 * dt
	cameraRot = Vector2.new(math.clamp(cameraRot.X, -math.rad(90), math.rad(90)), cameraRot.Y % (2 * math.pi))

	local cameraCFrame = CFrame.new(cameraPos)
		* CFrame.fromOrientation(cameraRot.X, cameraRot.Y, 0)
		* CFrame.new(vel * 64 * dt)
	cameraPos = cameraCFrame.Position

	Camera.CFrame = cameraCFrame
	Camera.Focus = cameraCFrame * CFrame.new(0, 0, -getFocusDistance(cameraCFrame))
end

-- Saved player camera + mouse state (restored on exit).
local savedCameraType, savedCFrame, savedFocus, savedMouseIcon, savedMouseBehavior

local function push()
	savedCameraType = Camera.CameraType
	Camera.CameraType = Enum.CameraType.Custom

	savedCFrame = Camera.CFrame
	savedFocus = Camera.Focus

	savedMouseIcon = UserInputService.MouseIconEnabled
	UserInputService.MouseIconEnabled = true

	savedMouseBehavior = UserInputService.MouseBehavior
	UserInputService.MouseBehavior = Enum.MouseBehavior.Default
end

local function pop()
	Camera.CameraType = savedCameraType or Enum.CameraType.Custom
	Camera.CFrame = savedCFrame or Camera.CFrame
	Camera.Focus = savedFocus or Camera.Focus
	UserInputService.MouseIconEnabled = savedMouseIcon
	if savedMouseBehavior then
		UserInputService.MouseBehavior = savedMouseBehavior
	end

	savedCameraType, savedCFrame, savedFocus, savedMouseIcon, savedMouseBehavior = nil, nil, nil, nil, nil
end

---@param pos CFrame? Optional starting camera CFrame.
function Freecam.enter(pos)
	if running then
		Freecam.exit()
	end

	local cameraCFrame = pos or Camera.CFrame
	cameraRot = Vector2.new()
	cameraPos = cameraCFrame.Position

	push()
	RunService:BindToRenderStep("Freecam", Enum.RenderPriority.Camera.Value, stepFreecam)
	startCapture()
	running = true
end

function Freecam.exit()
	if not running then
		return
	end

	stopCapture()
	RunService:UnbindFromRenderStep("Freecam")
	pop()
	running = false
end

---@param speed number Multiplier on the base nav speed (1 = default feel).
function Freecam.set_speed(speed)
	NAV_KEYBOARD_SPEED = Vector3.new(speed, speed, speed)
end

---@return boolean
function Freecam.running()
	return running
end

return Freecam

end)
__bundle_register("@luma/Utility/InstanceWrapper", function(require, _LOADED, __bundle_register, __bundle_modules)
local InstanceWrapper = {}

local collectionService = game:GetService("CollectionService")

---@module Utility.Signal
local Signal = require("@luma/Utility/Signal")

---@param instanceMaid Maid
---@param identifier any
---@param inst Instance
---@return Instance
InstanceWrapper.mark = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, inst)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local onAncestorChange = Signal.new(inst.AncestryChanged)

	if inst:IsA("BodyVelocity") then
		collectionService:AddTag(inst, "AllowedBM")
	end

	instanceMaid[identifier] = inst
	instanceMaid:add(onAncestorChange:connect("Instance_OnAncestorChange", function(_)
		if inst:IsDescendantOf(game) then
			return
		end

		instanceMaid:removeTask(identifier)
	end))

	return inst
end)

---@param instanceMaid Maid
---@param identifier any
---@param type string
---@param parent Instance?
---@return Instance
InstanceWrapper.create = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, type, parent)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local newInstance = Instance.new(type, parent)
	local onAncestorChange = Signal.new(newInstance.AncestryChanged)

	if newInstance:IsA("BodyVelocity") then
		collectionService:AddTag(newInstance, "AllowedBM")
	end

	instanceMaid[identifier] = newInstance
	instanceMaid:add(onAncestorChange:connect("Instance_OnAncestorChange", function(_)
		if newInstance:IsDescendantOf(game) then
			return
		end

		instanceMaid:removeTask(identifier)
	end))

	return newInstance
end)

return InstanceWrapper

end)
__bundle_register("@luma/Utility/JSON", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()

	local json = { _version = "0.1.2" }


	local encode

	local escape_char_map = {
		["\\"] = "\\",
		['"'] = '"',
		["\b"] = "b",
		["\f"] = "f",
		["\n"] = "n",
		["\r"] = "r",
		["\t"] = "t",
	}

	local escape_char_map_inv = { ["/"] = "/" }
	for k, v in pairs(escape_char_map) do
		escape_char_map_inv[v] = k
	end

	local function escape_char(c)
		return "\\" .. (escape_char_map[c] or string.format("u%04x", c:byte()))
	end

	local function encode_nil(val)
		return "null"
	end

	local function encode_table(val, stack)
		local res = {}
		stack = stack or {}

		if stack[val] then
			error("circular reference")
		end

		stack[val] = true

		if rawget(val, 1) ~= nil or next(val) == nil then
			local n = 0
			for k in pairs(val) do
				if type(k) ~= "number" then
					error("invalid table: mixed or invalid key types")
				end
				n = n + 1
			end
			if n ~= #val then
				error("invalid table: sparse array")
			end
			for i, v in ipairs(val) do
				table.insert(res, encode(v, stack))
			end
			stack[val] = nil
			return "[" .. table.concat(res, ",") .. "]"
		else
			for k, v in pairs(val) do
				if type(k) ~= "string" then
					error("invalid table: mixed or invalid key types")
				end
				table.insert(res, encode(k, stack) .. ":" .. encode(v, stack))
			end
			stack[val] = nil
			return "{" .. table.concat(res, ",") .. "}"
		end
	end

	local function encode_string(val)
		return '"' .. val:gsub('[%z\1-\31\\"]', escape_char) .. '"'
	end

	local function encode_number(val)
		if val ~= val or val <= -math.huge or val >= math.huge then
			error("unexpected number value '" .. tostring(val) .. "'")
		end
		return string.format("%.14g", val)
	end

	local type_func_map = {
		["nil"] = encode_nil,
		["table"] = encode_table,
		["string"] = encode_string,
		["number"] = encode_number,
		["boolean"] = tostring,
	}

	encode = function(val, stack)
		local t = type(val)
		local f = type_func_map[t]
		if f then
			return f(val, stack)
		end
		error("unexpected type '" .. t .. "'")
	end

	function json.encode(val)
		return (encode(val))
	end


	local parse

	local function create_set(...)
		local res = {}
		for i = 1, select("#", ...) do
			res[select(i, ...)] = true
		end
		return res
	end

	local space_chars = create_set(" ", "\t", "\r", "\n")
	local delim_chars = create_set(" ", "\t", "\r", "\n", "]", "}", ",")
	local escape_chars = create_set("\\", "/", '"', "b", "f", "n", "r", "t", "u")
	local literals = create_set("true", "false", "null")

	local literal_map = {
		["true"] = true,
		["false"] = false,
		["null"] = nil,
	}

	local function next_char(str, idx, set, negate)
		for i = idx, #str do
			if set[str:sub(i, i)] ~= negate then
				return i
			end
		end
		return #str + 1
	end

	local function decode_error(str, idx, msg)
		local line_count = 1
		local col_count = 1
		for i = 1, idx - 1 do
			col_count = col_count + 1
			if str:sub(i, i) == "\n" then
				line_count = line_count + 1
				col_count = 1
			end
		end
		error(string.format("%s at line %d col %d", msg, line_count, col_count))
	end

	local function codepoint_to_utf8(n)
		local f = math.floor
		if n <= 0x7f then
			return string.char(n)
		elseif n <= 0x7ff then
			return string.char(f(n / 64) + 192, n % 64 + 128)
		elseif n <= 0xffff then
			return string.char(f(n / 4096) + 224, f(n % 4096 / 64) + 128, n % 64 + 128)
		elseif n <= 0x10ffff then
			return string.char(f(n / 262144) + 240, f(n % 262144 / 4096) + 128, f(n % 4096 / 64) + 128, n % 64 + 128)
		end
		error(string.format("invalid unicode codepoint '%x'", n))
	end

	local function parse_unicode_escape(s)
		local n1 = tonumber(s:sub(1, 4), 16)
		local n2 = tonumber(s:sub(7, 10), 16)
		if n2 then
			return codepoint_to_utf8((n1 - 0xd800) * 0x400 + (n2 - 0xdc00) + 0x10000)
		else
			return codepoint_to_utf8(n1)
		end
	end

	local function parse_string(str, i)
		local res = ""
		local j = i + 1
		local k = j

		while j <= #str do
			local x = str:byte(j)

			if x < 32 then
				decode_error(str, j, "control character in string")
			elseif x == 92 then
				res = res .. str:sub(k, j - 1)
				j = j + 1
				local c = str:sub(j, j)
				if c == "u" then
					local hex = str:match("^[dD][89aAbB]%x%x\\u%x%x%x%x", j + 1)
						or str:match("^%x%x%x%x", j + 1)
						or decode_error(str, j - 1, "invalid unicode escape in string")
					res = res .. parse_unicode_escape(hex)
					j = j + #hex
				else
					if not escape_chars[c] then
						decode_error(str, j - 1, "invalid escape char '" .. c .. "' in string")
					end
					res = res .. escape_char_map_inv[c]
				end
				k = j + 1
			elseif x == 34 then
				res = res .. str:sub(k, j - 1)
				return res, j + 1
			end

			j = j + 1
		end

		decode_error(str, i, "expected closing quote for string")
	end

	local function parse_number(str, i)
		local x = next_char(str, i, delim_chars)
		local s = str:sub(i, x - 1)
		local n = tonumber(s)
		if not n then
			decode_error(str, i, "invalid number '" .. s .. "'")
		end
		return n, x
	end

	local function parse_literal(str, i)
		local x = next_char(str, i, delim_chars)
		local word = str:sub(i, x - 1)
		if not literals[word] then
			decode_error(str, i, "invalid literal '" .. word .. "'")
		end
		return literal_map[word], x
	end

	local function parse_array(str, i)
		local res = {}
		local n = 1
		i = i + 1
		while 1 do
			local x
			i = next_char(str, i, space_chars, true)
			if str:sub(i, i) == "]" then
				i = i + 1
				break
			end
			x, i = parse(str, i)
			res[n] = x
			n = n + 1
			i = next_char(str, i, space_chars, true)
			local chr = str:sub(i, i)
			i = i + 1
			if chr == "]" then
				break
			end
			if chr ~= "," then
				decode_error(str, i, "expected ']' or ','")
			end
		end
		return res, i
	end

	local function parse_object(str, i)
		local res = {}
		i = i + 1
		while 1 do
			local key, val
			i = next_char(str, i, space_chars, true)
			if str:sub(i, i) == "}" then
				i = i + 1
				break
			end
			if str:sub(i, i) ~= '"' then
				decode_error(str, i, "expected string for key")
			end
			key, i = parse(str, i)
			i = next_char(str, i, space_chars, true)
			if str:sub(i, i) ~= ":" then
				decode_error(str, i, "expected ':' after key")
			end
			i = next_char(str, i + 1, space_chars, true)
			val, i = parse(str, i)
			res[key] = val
			i = next_char(str, i, space_chars, true)
			local chr = str:sub(i, i)
			i = i + 1
			if chr == "}" then
				break
			end
			if chr ~= "," then
				decode_error(str, i, "expected '}' or ','")
			end
		end
		return res, i
	end

	local char_func_map = {
		['"'] = parse_string,
		["0"] = parse_number,
		["1"] = parse_number,
		["2"] = parse_number,
		["3"] = parse_number,
		["4"] = parse_number,
		["5"] = parse_number,
		["6"] = parse_number,
		["7"] = parse_number,
		["8"] = parse_number,
		["9"] = parse_number,
		["-"] = parse_number,
		["t"] = parse_literal,
		["f"] = parse_literal,
		["n"] = parse_literal,
		["["] = parse_array,
		["{"] = parse_object,
	}

	parse = function(str, idx)
		local chr = str:sub(idx, idx)
		local f = char_func_map[chr]
		if f then
			return f(str, idx)
		end
		decode_error(str, idx, "unexpected character '" .. chr .. "'")
	end

	function json.decode(str)
		if type(str) ~= "string" then
			error("expected argument of type string, got " .. type(str))
		end
		local res, idx = parse(str, next_char(str, 1, space_chars, true))
		idx = next_char(str, idx, space_chars, true)
		if idx <= #str then
			decode_error(str, idx, "trailing garbage")
		end
		return res
	end

	return json
end)()

end)
__bundle_register("@luma/Utility/Logger", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local Logger = {}
	Logger.__index = Logger

	---@module GUI.Library
	local Library = require("@luma/GUI/Library")

	---@module Utility.Configuration
	local Configuration = require("@luma/Utility/Configuration")

	---@param str string
	---@return function
	function Logger.mnnotify(str, ...)
		return Library:ManuallyManagedNotify(string.format(str, ...))
	end

	---@param str string
	function Logger.qnotify(str, ...)
		local quickNotificationSpeed = Configuration.expectOptionValue("QuickNotificationSpeed") or 0.5
		Library:Notify(string.format(str, ...), quickNotificationSpeed)
	end

	---@param str string
	function Logger.notify(str, ...)
		Library:Notify(string.format(str, ...), 3.0)
	end

	---@param str string
	function Logger.longNotify(str, ...)
		Library:Notify(string.format(str, ...), 30.0)
	end

	-- warn/trace are no-ops. They used to emit "[Luma Recode]"-prefixed lines to the Roblox LogService
	-- (via warn/print), which the anticheat exfiltrates from GetLogHistory and bans on. Kept as empty
	-- functions so every existing call site is a cheap no-op. Notifications (notify/qnotify/longNotify/
	-- mnnotify) still work -- they go to luma's own UI, never LogService.
	---@param str string
	function Logger.warn(str, ...) end

	---@param str string
	function Logger.trace(str, ...) end

	return Logger
end)()

end)
__bundle_register("@luma/Utility/Maid", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class Maid
local Maid = {}
Maid.__type = "maid"

---@return Maid
Maid.new = LPH_NO_VIRTUALIZE(function()
	return setmetatable({
		_tasks = {},
	}, Maid)
end)

Maid.__index = LPH_NO_VIRTUALIZE(function(self, index)
	if Maid[index] then
		return Maid[index]
	else
		return self._tasks[index]
	end
end)

---@param index any
---@param newTask any
Maid.__newindex = LPH_NO_VIRTUALIZE(function(self, index, newTask)
	if Maid[index] ~= nil then
		return
	end

	local tasks = self._tasks
	local oldTask = tasks[index]

	if oldTask == newTask then
		return
	end

	tasks[index] = newTask

	if oldTask then
		if typeof(oldTask) == "thread" then
			return coroutine.status(oldTask) == "suspended" and task.cancel(oldTask) or nil
		end

		if type(oldTask) == "function" then
			oldTask()
		elseif typeof(oldTask) == "RBXScriptConnection" then
			oldTask:Disconnect()
		elseif typeof(oldTask) == "Instance" and oldTask:IsA("Tween") then
			oldTask:Pause()
			oldTask:Cancel()
			oldTask:Destroy()
		elseif oldTask.Destroy then
			oldTask:Destroy()
		elseif oldTask.Remove then
			oldTask:Remove()
		elseif oldTask.detach then
			oldTask:detach()
		end
	end
end)

---@param task any
---@return any
Maid.mark = LPH_NO_VIRTUALIZE(function(self, task)
	self:add(task)
	return task
end)

---@param task any
---@return number
Maid.add = LPH_NO_VIRTUALIZE(function(self, task)
	if not task then
		return error("task cannot be false or nil", 2)
	end

	local taskId = #self._tasks + 1
	self[taskId] = task

	return taskId
end)

---@param taskId number
Maid.removeTask = LPH_NO_VIRTUALIZE(function(self, taskId)
	local tasks = self._tasks
	tasks[taskId] = nil
end)

Maid.clean = LPH_NO_VIRTUALIZE(function(self)
	local tasks = self._tasks

	for index, task in pairs(tasks) do
		if typeof(task) == "RBXScriptConnection" then
			tasks[index] = nil
			pcall(task.Disconnect, task)
		end
	end

	local index, _task = next(tasks)

	while _task ~= nil do
		tasks[index] = nil

		if typeof(_task) == "thread" then
			if coroutine.status(_task) == "suspended" then
				pcall(task.cancel, _task)
			end
		else
			pcall(function()
				if type(_task) == "function" then
					_task()
				elseif typeof(_task) == "RBXScriptConnection" then
					_task:Disconnect()
				elseif typeof(_task) == "Instance" and _task:IsA("Tween") then
					_task:Pause()
					_task:Cancel()
					_task:Destroy()
				elseif _task.Destroy then
					_task:Destroy()
				elseif _task.Remove then
					_task:Remove()
				elseif _task.detach then
					_task:detach()
				end
			end)
		end

		index, _task = next(tasks)
	end
end)

return Maid

end)
__bundle_register("@luma/Utility/OriginalStore", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class OriginalStore
---@param data any
---@param index any
---@param value any
---@field stored boolean
local OriginalStore = {}
OriginalStore.__index = OriginalStore

---@return any
OriginalStore.get = LPH_NO_VIRTUALIZE(function(self)
	if not self.stored then
		return nil
	end

	return self.value
end)

---@param data table|Instance
---@param index any
---@param value any
---@param callback fun(): any
OriginalStore.run = LPH_NO_VIRTUALIZE(function(self, data, index, value, callback)
	self:set(data, index, value)

	callback()

	self:restore()
end)

---@param data table|Instance
---@param index any
OriginalStore.mark = LPH_NO_VIRTUALIZE(function(self, data, index)
	if self.stored and self.data ~= data then
		self:restore()
	end

	if not self.stored then
		self.data = data
		self.index = index
		self.value = data[index]
		self.stored = true
	end
end)

---@param data table|Instance
---@param index any
---@param value any
OriginalStore.set = LPH_NO_VIRTUALIZE(function(self, data, index, value)
	self:mark(data, index)

	data[index] = value
end)

OriginalStore.restore = LPH_NO_VIRTUALIZE(function(self)
	if not self.stored then
		return
	end

	pcall(function()
		self.data[self.index] = self.value
	end)

	self.stored = false
end)

OriginalStore.detach = LPH_NO_VIRTUALIZE(function(self)
	self:restore()
	self.data = nil
	self.index = nil
	self.value = nil
	self.stored = false
end)

---@return OriginalStore
OriginalStore.new = LPH_NO_VIRTUALIZE(function()
	local self = setmetatable({}, OriginalStore)
	self.data = nil
	self.index = nil
	self.value = nil
	self.stored = false
	return self
end)

return OriginalStore

end)
__bundle_register("@luma/Utility/OriginalStoreManager", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.OriginalStore
local OriginalStore = require("@luma/Utility/OriginalStore")

---@class OriginalStoreManager
---@param inner OriginalStore[]
local OriginalStoreManager = {}
OriginalStoreManager.__index = OriginalStoreManager

---@param data table|Instance
OriginalStoreManager.forget = LPH_NO_VIRTUALIZE(function(self, data)
	self.inner[data] = nil
end)

---@param data table|Instance
---@param index any
OriginalStoreManager.mark = LPH_NO_VIRTUALIZE(function(self, data, index)
	local object = self.inner[data] or OriginalStore.new()

	object:mark(data, index)

	self.inner[data] = object
end)

---@param data table|Instance
---@param index any
---@param value any
OriginalStoreManager.add = LPH_NO_VIRTUALIZE(function(self, data, index, value)
	local object = self.inner[data] or OriginalStore.new()

	object:set(data, index, value)

	self.inner[data] = object
end)

---@return OriginalStore[]
OriginalStoreManager.data = LPH_NO_VIRTUALIZE(function(self)
	return self.inner
end)

---@param data table|Instance
---@return OriginalStore
OriginalStoreManager.get = LPH_NO_VIRTUALIZE(function(self, data)
	return self.inner[data]
end)

OriginalStoreManager.restore = LPH_NO_VIRTUALIZE(function(self)
	for _, store in next, self.inner do
		store:restore()
	end
end)

OriginalStoreManager.detach = LPH_NO_VIRTUALIZE(function(self)
	for _, store in next, self.inner do
		store:detach()
	end

	self.inner = {}
end)

---@return OriginalStoreManager
OriginalStoreManager.new = LPH_NO_VIRTUALIZE(function()
	local self = setmetatable({}, OriginalStoreManager)
	self.inner = {}
	return self
end)

return OriginalStoreManager

end)
__bundle_register("@luma/Utility/PersistentData", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Utility.Serializer
local Serializer = require("@luma/Utility/Serializer")

---@module Utility.Deserializer
local Deserializer = require("@luma/Utility/Deserializer")

---@module Utility.String
local String = require("@luma/Utility/String")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

local PersistentData = {
	_data = {
		fli = nil,

		shslot = nil,

		sblacklist = {},

		wdata = nil,

		efdata = nil,
	},
}

local memStorageService = game:GetService("MemStorageService")

---@param field string
---@return any
function PersistentData.get(field)
	return PersistentData._data[field]
end

---@param field string
---@param key string
---@param value any
function PersistentData.stf(field, key, value)
	local tbl = PersistentData.get(field)

	if type(tbl) ~= "table" then
		return error(string.format("PersistentData field '%s' is not a table.", tostring(field)))
	end

	tbl[key] = value

	PersistentData.set(field, tbl)
end

---@param field string
---@param value any
function PersistentData.set(field, value)
	PersistentData._data[field] = value

	local marshalSuccess, payload = pcall(Serializer.marshal, PersistentData._data)
	if not marshalSuccess then
		return Logger.warn("(%s) Failed to marshal PersistentData snapshot.", tostring(payload))
	end

	local saveSuccess, saveResult = pcall(memStorageService.SetItem, memStorageService, "LYCORIS_PERSISTENT_DATA", payload)

	if not saveSuccess then
		return Logger.warn("(%s) Failed to set PersistentData snapshot.", tostring(saveResult))
	end

	if not LPH_OBFUSCATED or shared.Luma.verbose then
		Logger.warn("(%s) Successfully set PersistentData snapshot.", tostring(saveResult))
	end
end

function PersistentData.init()
	local hasSuccess, hasResult = pcall(memStorageService.HasItem, memStorageService, "LYCORIS_PERSISTENT_DATA")
	if not hasSuccess then
		return hasResult and Logger.warn("(%s) Failed to check for PersistentData snapshot.", tostring(hasResult))
	end

	local itemSuccess, itemResult = pcall(memStorageService.GetItem, memStorageService, "LYCORIS_PERSISTENT_DATA")
	if not itemSuccess then
		return Logger.warn("(%s) Failed to get PersistentData snapshot", tostring(itemResult))
	end

	if itemResult == nil or itemResult == "" then
		if not LPH_OBFUSCATED or shared.Luma.verbose then
			Logger.warn("PersistentData snapshot is missing or empty.")
		end

		return
	end

	local success, result = pcall(Deserializer.unmarshal_one, String.tba(itemResult))
	if not success then
		return Logger.warn("(%s) Failed to deserialize PersistentData snapshot.", tostring(result))
	end

	if not LPH_OBFUSCATED or shared.Luma.verbose then
		Logger.warn("(%s) Successfully loaded PersistentData snapshot.", tostring(result))
	end

	PersistentData._data = result
end

return PersistentData

end)
__bundle_register("@luma/Utility/Profiler", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	local Profiler = {}

	-- Opt-in: set getgenv().LycorisProfile = true before executing. When off, run/wrap are
	-- pass-throughs with no overhead.
	local enabled = getgenv ~= nil and getgenv().LycorisProfile == true
	local reportInterval = 10.0
	local stats = {}

	local function record(label, start)
		local elapsed = os.clock() - start
		local entry = stats[label]

		if not entry then
			entry = { total = 0, calls = 0, max = 0 }
			stats[label] = entry
		end

		entry.total = entry.total + elapsed
		entry.calls = entry.calls + 1

		if elapsed > entry.max then
			entry.max = elapsed
		end
	end

	---Runs a function, forwarding all return values.
	---@param label string
	---@param functionToProfile function
	function Profiler.run(label, functionToProfile, ...)
		if not enabled then
			return functionToProfile(...)
		end

		local start = os.clock()
		local results = table.pack(functionToProfile(...))
		record(label, start)
		return table.unpack(results, 1, results.n)
	end

	---Wrap function to match Profiler.run signature.
	---@param label string
	---@param functionToProfile function
	---@return function
	function Profiler.wrap(label, functionToProfile)
		if not enabled then
			return functionToProfile
		end

		return function(...)
			return Profiler.run(label, functionToProfile, ...)
		end
	end

	---Print the most expensive labels since the last report, then reset.
	---@param count number?
	function Profiler.report(count)
		local sorted = {}

		for label, entry in next, stats do
			sorted[#sorted + 1] = { label = label, entry = entry }
		end

		table.sort(sorted, function(a, b)
			return a.entry.total > b.entry.total
		end)

		warn(string.format("[Profiler] Top labels over the last %.0fs (total ms / calls / avg ms / max ms):", reportInterval))

		for idx = 1, math.min(count or 15, #sorted) do
			local label = sorted[idx].label
			local entry = sorted[idx].entry

			warn(
				string.format(
					"[Profiler] %2d. %-48s %8.2f / %6d / %6.3f / %6.2f",
					idx,
					label,
					entry.total * 1000,
					entry.calls,
					(entry.total / entry.calls) * 1000,
					entry.max * 1000
				)
			)
		end

		table.clear(stats)
	end

	if enabled then
		task.spawn(function()
			while true do
				task.wait(reportInterval)
				Profiler.report()
			end
		end)
	end

	return Profiler
end)()

end)
__bundle_register("@luma/Utility/Prompt", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Hardened ProximityPrompt firing.
--
-- Why this exists: bare `fireproximityprompt(prompt)` "works for some users and
-- fails for others" on the SAME executor because the failures are game-state, not
-- executor. Deepwoken runs with StreamingEnabled, so a prompt's part may not be
-- streamed in for a given client yet (slower stream = further away / lower memory /
-- lower graphics / fired too soon after a teleport), and firing against a
-- streamed-out part silently no-ops. On top of that the engine enforces
-- RequiresLineOfSight / MaxActivationDistance / Enabled / HoldDuration at trigger
-- time, and whether those bite depends on the player's camera, morph/accessories
-- obstructing the line of sight, and how the executor implements the function.
--
-- Prompt.fire() removes every one of those variables: it requests streaming around
-- the prompt, forces the prompt open (LOS off, huge distance, no hold, enabled),
-- fires, then restores the originals so the game's own UI/logic is untouched.
local Prompt = {}

local players = game:GetService("Players")

---Request the world region around a part to stream in, so the part is resident
---(has physics + a valid trigger) before we fire. No-op on non-streaming games.
---@param part BasePart?
local function ensureStreamedIn(part)
	if not part then
		return
	end
	local localPlayer = players.LocalPlayer
	if not localPlayer then
		return
	end
	pcall(function()
		if localPlayer.RequestStreamingAround then
			localPlayer:RequestStreamingAround(part.Position)
		end
	end)
end

---Fire a ProximityPrompt reliably.
---@param prompt Instance? A ProximityPrompt, or any instance to search under for one.
---@return boolean fired
function Prompt.fire(prompt)
	if not prompt then
		return false
	end

	-- Accept a model/part and dig out the prompt so callers don't have to.
	if not prompt:IsA("ProximityPrompt") then
		local found = prompt:FindFirstChildWhichIsA("ProximityPrompt", true)
		if not found then
			return false
		end
		prompt = found
	end

	local part = prompt:FindFirstAncestorWhichIsA("BasePart") or prompt.Parent
	if typeof(part) == "Instance" and part:IsA("BasePart") then
		ensureStreamedIn(part)
	end

	local fireProx = fireproximityprompt

	local fired = false
	pcall(function()
		-- Snapshot the properties the engine checks at trigger time and force them
		-- into the state that always allows a fire. ProximityPrompt property writes
		-- from the client are local-only (never replicate), so this only affects our
		-- own trigger path and is restored immediately after.
		local origEnabled = prompt.Enabled
		local origLOS = prompt.RequiresLineOfSight
		local origDist = prompt.MaxActivationDistance
		local origHold = prompt.HoldDuration

		prompt.Enabled = true
		prompt.RequiresLineOfSight = false
		prompt.MaxActivationDistance = math.max(origDist, 1000)
		prompt.HoldDuration = 0

		if fireProx then
			fireProx(prompt)
			fired = true
		elseif prompt.InputHoldBegin then
			prompt:InputHoldBegin()
			task.wait(origHold or 0)
			prompt:InputHoldEnd()
			fired = true
		end

		prompt.Enabled = origEnabled
		prompt.RequiresLineOfSight = origLOS
		prompt.MaxActivationDistance = origDist
		prompt.HoldDuration = origHold
	end)

	return fired
end

-- =========================================================================================================
-- Interact-key press (used by the automations instead of firing ProximityPrompts directly).
--
-- Rather than fireproximityprompt(), the automations press the real interact key -- like a human -- after
-- they've tweened to the target. The key is configurable under the Automations panel ("Interact Key",
-- default E). We still stream the target's part in and read its HoldDuration so a hold-prompt registers.
-- =========================================================================================================
local DEFAULT_INTERACT_KEY = Enum.KeyCode.E

local function resolveInteractKey()
	local picker = Options and Options.AutomationInteractKey
	local name = picker and picker.Value
	if type(name) == "string" and name ~= "" and name ~= "None" and name ~= "N/A" then
		local ok, code = pcall(function()
			return Enum.KeyCode[name]
		end)
		if ok and code then
			return code
		end
	end
	return DEFAULT_INTERACT_KEY
end

---Press the configured interact key. `prompt` is optional, used only to stream the target in and read its
---HoldDuration (so a hold-prompt is held long enough); the actual interaction is the key press.
---@param prompt Instance?
---@return boolean pressed
function Prompt.interact(prompt)
	local holdDuration = 0

	if typeof(prompt) == "Instance" then
		local resolved = prompt
		if not resolved:IsA("ProximityPrompt") then
			resolved = resolved:FindFirstChildWhichIsA("ProximityPrompt", true)
		end
		if resolved and resolved:IsA("ProximityPrompt") then
			holdDuration = resolved.HoldDuration or 0
			local part = resolved:FindFirstAncestorWhichIsA("BasePart")
			if part then
				ensureStreamedIn(part)
			end
		elseif prompt:IsA("BasePart") then
			ensureStreamedIn(prompt)
		end
	end

	local key = resolveInteractKey()
	local pressed = false
	pcall(function()
		local vim = Instance.new("VirtualInputManager")
		vim:SendKeyEvent(true, key, false, game)
		task.wait(holdDuration + 0.06)
		vim:SendKeyEvent(false, key, false, game)
		pressed = true
	end)
	return pressed
end

return Prompt

end)
__bundle_register("@luma/Utility/ReferencedMap", function(require, _LOADED, __bundle_register, __bundle_modules)
return LPH_NO_VIRTUALIZE(function()
	---@class ReferencedMap
	---@field _map table
	---@field _references table
	local ReferencedMap = {}
	ReferencedMap.__index = ReferencedMap

	---@param ref any
	---@param element any
	function ReferencedMap:insert(ref, element)
		local key = #self._map + 1
		self._map[key] = element
		self._references[ref] = element
	end

	---@param ref any
	---@return any?
	function ReferencedMap:remove(ref)
		local element = self._references[ref]
		if not element then
			return nil
		end

		self._references[ref] = nil

		local position = table.find(self._map, element)
		if not position then
			return nil
		end

		table.remove(self._map, position)

		return element
	end

	---@return number
	function ReferencedMap:size()
		return #self._map
	end

	---@return table
	function ReferencedMap:data()
		return self._map
	end

	---@return ReferencedMap
	function ReferencedMap.new()
		local self = setmetatable({}, ReferencedMap)
		self._map = {}
		self._references = {}
		return self
	end

	return ReferencedMap
end)()

end)
__bundle_register("@luma/Utility/SafeClick", function(require, _LOADED, __bundle_register, __bundle_modules)
---@note: Click a GuiButton by invoking its MouseButton1Click handlers DIRECTLY (conn.Function()), never via
---@note: firesignal() or conn:Fire(). Both of those are native-crash-prone and a pcall can NOT catch a native
---@note: fault:
---@note:   * conn:Fire() on a getconnections() object dereferences a null pointer on mac/macsploit -- the
---@note:     NULL+0x28 SIGSEGV that OptimizeGame documents and avoids.
---@note:   * firesignal() is in luma's own "these crash" list (see Spoofing.rics).
---@note: getconnections() itself is fine (OptimizeGame uses it); it's the firing that crashes. Every
---@note: getconnections connection exposes .Function (its bound handler) even on macsploit, so calling that
---@note: directly is the safe, cross-executor equivalent of a click.

---@param button Instance A TextButton/ImageButton (anything with MouseButton1Click).
---@return boolean clicked  false if getconnections is unavailable or the button had no handlers.
local function safeClick(button)
	if not button or type(getconnections) ~= "function" then
		return false
	end

	local ok, connections = pcall(getconnections, button.MouseButton1Click)
	if not ok or type(connections) ~= "table" then
		return false
	end

	local fired = false
	for _, connection in ipairs(connections) do
		pcall(function()
			local handler = connection.Function
			if handler then
				handler()
				fired = true
			end
		end)
	end

	return fired
end

return safeClick

end)
__bundle_register("@luma/Utility/Serializer", function(require, _LOADED, __bundle_register, __bundle_modules)

local Serializer = {}

---@param tbl table
---@return boolean
local function isAnArray(tbl)
	local expected = 1

	for k in next, tbl do
		if k ~= expected then
			return false
		end

		expected = expected + 1
	end

	return true
end

---@param value number
---@return string
local function serializeFloat(value)
	local serializedFloat = string.unpack("f", string.pack("f", value))
	if serializedFloat == value then
		return string.pack(">Bf", 0xca, value)
	end

	return string.pack(">Bd", 0xcb, value)
end

---@param value number
---@return string
local function serializeSignedInt(value)
	if value < 128 then
		return string.pack("B", value)
	elseif value <= 0xff then
		return string.pack("BB", 0xcc, value)
	elseif value <= 0xffff then
		return string.pack(">BI2", 0xcd, value)
	elseif value <= 0xffffffff then
		return string.pack(">BI4", 0xce, value)
	end

	return string.pack(">BI8", 0xcf, value)
end

---@param value number
---@return string
local function serializeUnsignedInt(value)
	if value >= -32 then
		return string.pack("B", 0xe0 + (value + 32))
	elseif value >= -128 then
		return string.pack("Bb", 0xd0, value)
	elseif value >= -32768 then
		return string.pack(">Bi2", 0xd1, value)
	elseif value >= -2147483648 then
		return string.pack(">Bi4", 0xd2, value)
	end

	return string.pack(">Bi8", 0xd3, value)
end

---@param value string
---@return string
local function serializeUtf8(value)
	local len = #value

	if len < 32 then
		return string.pack("B", 0xa0 + len) .. value
	elseif len < 256 then
		return string.pack(">Bs1", 0xd9, value)
	elseif len < 65536 then
		return string.pack(">Bs2", 0xda, value)
	end

	return string.pack(">Bs4", 0xdb, value)
end

---@param value string
---@return string
local function serializeStringBytes(value)
	local len = #value

	if len < 256 then
		return string.pack(">Bs1", 0xc4, value)
	elseif len < 65536 then
		return string.pack(">Bs2", 0xc5, value)
	end

	return string.pack(">Bs4", 0xc6, value)
end

local serializable = nil

---@param value table
---@return string
local function serializeArray(value)
	local elements = {}

	for i = 1, #value do
		local v = value[i]
		if serializable(v) then
			elements[#elements + 1] = Serializer.marshal(v)
		end
	end

	local result = table.concat(elements)
	local length = #elements

	if length < 16 then
		return string.pack(">B", 0x90 + length) .. result
	elseif length < 65536 then
		return string.pack(">BI2", 0xdc, length) .. result
	end

	return string.pack(">BI4", 0xdd, length) .. result
end

---@param value table
---@return string
local function serializeMap(value)
	local elements = {}

	for k, v in pairs(value) do
		if serializable(k) and serializable(v) then
			elements[#elements + 1] = Serializer.marshal(k)
			elements[#elements + 1] = Serializer.marshal(v)
		end
	end

	local length = math.floor(#elements / 2)
	if length < 16 then
		return string.pack(">B", 0x80 + length) .. table.concat(elements)
	elseif length < 65536 then
		return string.pack(">BI2", 0xde, length) .. table.concat(elements)
	end

	return string.pack(">BI4", 0xdf, length) .. table.concat(elements)
end

---@return string
local function serializeNil()
	return string.pack("B", 0xc0)
end

---@param value table
---@return string
local function serializeTable(value)
	return isAnArray(value) and serializeArray(value) or serializeMap(value)
end

---@param value boolean
---@return string
local function serializeBoolean(value)
	return string.pack("B", value and 0xc3 or 0xc2)
end

---@param value number
---@return string
local function serializeInt(value)
	return value >= 0 and serializeSignedInt(value) or serializeUnsignedInt(value)
end

---@param value number
---@return string
local function serializeNumber(value)
	return value % 1 == 0 and math.abs(value) < 2 ^ 53 and serializeInt(value) or serializeFloat(value)
end

---@param value number
---@return string
local function serializeString(value)
	return utf8.len(value) and serializeUtf8(value) or serializeStringBytes(value)
end

local typeToSerializeMap = {
	["nil"] = serializeNil,
	["boolean"] = serializeBoolean,
	["number"] = serializeNumber,
	["string"] = serializeString,
	["table"] = serializeTable,
}

serializable = function(value)
	return typeToSerializeMap[type(value)] ~= nil
end

---@param value any
---@return string
function Serializer.marshal(value)
	local serialize = typeToSerializeMap[type(value)]
	if not serialize then
		return serializeNil()
	end

	return serialize(value)
end

return Serializer

end)
__bundle_register("@luma/Utility/Signal", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class Signal
---@field signal RBXScriptSignal Underlying roblox script signal
local Signal = {}
Signal.__index = Signal

---@module Utility.Profiler
local Profiler = require("@luma/Utility/Profiler")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

---@param label string
---@param eventFunction function
---@return RBXScriptConnection
function Signal:connect(label, eventFunction)
	---@param error string
	local function onEventFunctionError(error)
		Logger.trace("onEventFunctionError - (%s) - %s", label, error)
	end

	local connection = self.signal:Connect(Profiler.wrap(
		label,
		LPH_NO_VIRTUALIZE(function(...)
			return xpcall(eventFunction, onEventFunctionError, ...)
		end)
	))

	return connection
end

---@param robloxSignal RBXScriptSignal
---@return Signal
function Signal.new(robloxSignal)
	local self = setmetatable({}, Signal)
	self.signal = robloxSignal

	return self
end

return Signal

end)
__bundle_register("@luma/Utility/SpotifyClient", function(require, _LOADED, __bundle_register, __bundle_modules)
local JSON = require("@luma/Utility/JSON")
local Filesystem = require("@luma/Utility/Filesystem")
local Logger = require("@luma/Utility/Logger")

local storage = Filesystem.new("Luma/Spotify")

local DEBUG = false
local function dbg(fmt, ...)
	if DEBUG then
		Logger.warn("[Spotify] " .. fmt, ...)
	end
end

local SpotifyClient = {}

local CLIENT_ID = "70dfc46fe4294dfcb51b5879f021f9d1"

local REDIRECT_URI = "http://127.0.0.1:8888/callback"
local SCOPES = "user-read-playback-state user-modify-playback-state user-read-currently-playing"
local TOKEN_URL = "https://accounts.spotify.com/api/token"
local API_BASE = "https://api.spotify.com/v1/me/player"

local BASE64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local VERIFIER_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~"

local state = {
	clientId = CLIENT_ID,
	refreshToken = "",
	codeVerifier = nil,
	accessToken = nil,
	accessTokenExpiresAt = 0,
}

local function base64Encode(input)
	local out = {}
	local length = #input

	for i = 1, length, 3 do
		local b1, b2, b3 = string.byte(input, i, i + 2)
		b2 = b2 or 0
		b3 = b3 or 0

		local n = b1 * 65536 + b2 * 256 + b3

		local c1 = math.floor(n / 262144) % 64
		local c2 = math.floor(n / 4096) % 64
		local c3 = math.floor(n / 64) % 64
		local c4 = n % 64

		local chunk = string.sub(BASE64_CHARS, c1 + 1, c1 + 1)
			.. string.sub(BASE64_CHARS, c2 + 1, c2 + 1)
			.. (i + 1 <= length and string.sub(BASE64_CHARS, c3 + 1, c3 + 1) or "=")
			.. (i + 2 <= length and string.sub(BASE64_CHARS, c4 + 1, c4 + 1) or "=")

		table.insert(out, chunk)
	end

	return table.concat(out)
end

local function base64UrlEncode(input)
	return (base64Encode(input):gsub("[+/=]", { ["+"] = "-", ["/"] = "_", ["="] = "" }))
end

local function urlEncode(value)
	return (tostring(value):gsub("[^%w%-%.%_%~]", function(char)
		return string.format("%%%02X", string.byte(char))
	end))
end

local function encodeForm(fields)
	local parts = {}
	for key, value in next, fields do
		table.insert(parts, urlEncode(key) .. "=" .. urlEncode(value))
	end
	return table.concat(parts, "&")
end

local SHA256_K = {
	0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
	0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
	0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
	0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
	0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
	0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
	0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
	0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
}

local function sha256(msg)
	local band, bxor, bnot, rshift, rrotate = bit32.band, bit32.bxor, bit32.bnot, bit32.rshift, bit32.rrotate

	local h0, h1, h2, h3, h4, h5, h6, h7 =
		0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19

	local msgLen = #msg
	local bitLen = msgLen * 8

	msg = msg .. "\128"
	while #msg % 64 ~= 56 do
		msg = msg .. "\0"
	end

	for i = 7, 0, -1 do
		msg = msg .. string.char(band(rshift(bitLen, i * 8), 0xFF))
	end

	for chunkStart = 1, #msg, 64 do
		local w = {}
		for i = 0, 15 do
			local o = chunkStart + i * 4
			local b1, b2, b3, b4 = string.byte(msg, o, o + 3)
			w[i + 1] = b1 * 16777216 + b2 * 65536 + b3 * 256 + b4
		end

		for i = 17, 64 do
			local w15, w2 = w[i - 15], w[i - 2]
			local s0 = bxor(rrotate(w15, 7), rrotate(w15, 18), rshift(w15, 3))
			local s1 = bxor(rrotate(w2, 17), rrotate(w2, 19), rshift(w2, 10))
			w[i] = (w[i - 16] + s0 + w[i - 7] + s1) % 4294967296
		end

		local a, b, c, d, e, f, g, h = h0, h1, h2, h3, h4, h5, h6, h7

		for i = 1, 64 do
			local S1 = bxor(rrotate(e, 6), rrotate(e, 11), rrotate(e, 25))
			local ch = bxor(band(e, f), band(bnot(e), g))
			local temp1 = (h + S1 + ch + SHA256_K[i] + w[i]) % 4294967296
			local S0 = bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
			local maj = bxor(band(a, b), band(a, c), band(b, c))
			local temp2 = (S0 + maj) % 4294967296

			h, g, f = g, f, e
			e = (d + temp1) % 4294967296
			d, c, b = c, b, a
			a = (temp1 + temp2) % 4294967296
		end

		h0 = (h0 + a) % 4294967296
		h1 = (h1 + b) % 4294967296
		h2 = (h2 + c) % 4294967296
		h3 = (h3 + d) % 4294967296
		h4 = (h4 + e) % 4294967296
		h5 = (h5 + f) % 4294967296
		h6 = (h6 + g) % 4294967296
		h7 = (h7 + h) % 4294967296
	end

	local out = {}
	for _, v in next, { h0, h1, h2, h3, h4, h5, h6, h7 } do
		out[#out + 1] = string.char(
			band(rshift(v, 24), 0xFF),
			band(rshift(v, 16), 0xFF),
			band(rshift(v, 8), 0xFF),
			band(v, 0xFF)
		)
	end

	return table.concat(out)
end

local function generateCodeVerifier()
	local rng = Random.new()
	local chars = {}
	for i = 1, 64 do
		local idx = rng:NextInteger(1, #VERIFIER_CHARS)
		chars[i] = VERIFIER_CHARS:sub(idx, idx)
	end
	return table.concat(chars)
end

function SpotifyClient.load()
	if not storage:file("auth.json") then
		return
	end

	local ok, decoded = pcall(JSON.decode, storage:read("auth.json"))
	if not ok or type(decoded) ~= "table" then
		return
	end

	if type(decoded.clientId) == "string" and decoded.clientId ~= "" then
		state.clientId = decoded.clientId
	end
	state.refreshToken = decoded.refreshToken or ""
end

function SpotifyClient.save()
	storage:write(
		"auth.json",
		JSON.encode({
			clientId = state.clientId,
			refreshToken = state.refreshToken,
		})
	)
end

function SpotifyClient.setClientId(clientId)
	if clientId and clientId ~= "" then
		state.clientId = clientId
		SpotifyClient.save()
	end
end

function SpotifyClient.getClientId()
	return state.clientId
end

function SpotifyClient.isAuthorized()
	return state.refreshToken ~= ""
end

function SpotifyClient.getAuthUrl()
	state.codeVerifier = generateCodeVerifier()
	local codeChallenge = base64UrlEncode(sha256(state.codeVerifier))

	return "https://accounts.spotify.com/authorize?"
		.. encodeForm({
			client_id = state.clientId,
			response_type = "code",
			redirect_uri = REDIRECT_URI,
			scope = SCOPES,
			code_challenge_method = "S256",
			code_challenge = codeChallenge,
		})
end

local function extractCode(pastedUrl)
	return pastedUrl:match("[?&]code=([^&#]+)")
end

function SpotifyClient.completeAuth(pastedUrl)
	if not state.codeVerifier then
		return false, "Click 'Copy Auth URL' first -- authorization needs to start from there."
	end

	local code = extractCode(pastedUrl)
	if not code then
		return false, "Couldn't find a 'code' parameter in that URL."
	end

	local response = request({
		Url = TOKEN_URL,
		Method = "POST",
		Headers = {
			["Content-Type"] = "application/x-www-form-urlencoded",
		},
		Body = encodeForm({
			grant_type = "authorization_code",
			code = code,
			redirect_uri = REDIRECT_URI,
			client_id = state.clientId,
			code_verifier = state.codeVerifier,
		}),
	})

	state.codeVerifier = nil

	if not response or not response.Success then
		return false, "Token exchange request failed."
	end

	local ok, decoded = pcall(JSON.decode, response.Body)
	if not ok or not decoded or not decoded.refresh_token then
		return false, "Token exchange returned an unexpected response."
	end

	state.refreshToken = decoded.refresh_token
	state.accessToken = decoded.access_token
	state.accessTokenExpiresAt = os.clock() + (decoded.expires_in or 3600) - 30
	SpotifyClient.save()

	return true
end

local function refreshAccessToken()
	if state.refreshToken == "" then
		return false
	end

	local response = request({
		Url = TOKEN_URL,
		Method = "POST",
		Headers = {
			["Content-Type"] = "application/x-www-form-urlencoded",
		},
		Body = encodeForm({
			grant_type = "refresh_token",
			refresh_token = state.refreshToken,
			client_id = state.clientId,
		}),
	})

	if not response or not response.Success then
		return false
	end

	local ok, decoded = pcall(JSON.decode, response.Body)
	if not ok or not decoded or not decoded.access_token then
		return false
	end

	state.accessToken = decoded.access_token
	state.accessTokenExpiresAt = os.clock() + (decoded.expires_in or 3600) - 30

	if decoded.refresh_token then
		state.refreshToken = decoded.refresh_token
		SpotifyClient.save()
	end

	return true
end

local function ensureToken()
	if state.accessToken and os.clock() < state.accessTokenExpiresAt then
		return true
	end

	return refreshAccessToken()
end

local function authorizedRequest(method, path, body)
	if not ensureToken() then
		dbg("%s %s: ensureToken() failed, no valid access token", method, path)
		return nil
	end

	local response = request({
		Url = API_BASE .. path,
		Method = method,
		Headers = {
			["Authorization"] = "Bearer " .. state.accessToken,
			["Content-Type"] = "application/json",
		},
		Body = body or "{}",
	})

	if not response then
		dbg("%s %s: request() returned nil", method, path)
	elseif not response.Success then
		dbg("%s %s: failed, status=%s body=%s", method, path, tostring(response.StatusCode), tostring(response.Body))
	else
		dbg("%s %s: ok, status=%s", method, path, tostring(response.StatusCode))
	end

	return response
end

function SpotifyClient.getCurrentlyPlaying()
	local response = authorizedRequest("GET", "/currently-playing")
	if not response or not response.Success or response.StatusCode == 204 or not response.Body or response.Body == "" then
		return nil
	end

	local ok, decoded = pcall(JSON.decode, response.Body)
	if not ok or not decoded or not decoded.item then
		return nil
	end

	local images = decoded.item.album and decoded.item.album.images or {}
	local artists = {}
	for _, artist in next, decoded.item.artists or {} do
		table.insert(artists, artist.name)
	end

	return {
		trackId = decoded.item.id,
		trackName = decoded.item.name,
		artistName = table.concat(artists, ", "),
		albumArtUrl = images[1] and images[1].url,
		progressMs = decoded.progress_ms or 0,
		durationMs = decoded.item.duration_ms or 0,
		isPlaying = decoded.is_playing or false,
	}
end

function SpotifyClient.play()
	authorizedRequest("PUT", "/play")
end

function SpotifyClient.pause()
	authorizedRequest("PUT", "/pause")
end

function SpotifyClient.next()
	authorizedRequest("POST", "/next")
end

function SpotifyClient.previous()
	authorizedRequest("POST", "/previous")
end

function SpotifyClient.seek(positionMs)
	authorizedRequest("PUT", "/seek?position_ms=" .. math.floor(positionMs))
end

SpotifyClient.load()

return SpotifyClient

end)
__bundle_register("@luma/Utility/String", function(require, _LOADED, __bundle_register, __bundle_modules)
local String = {}

local charByteMap = {}

for idx = 0, 255 do
	charByteMap[string.char(idx)] = idx
end

---@param str string
---@return table
function String.tba(str)
	local chars = {}
	local idx = 1

	if #str == 0 then
		return {}
	end

	repeat
		chars[idx] = charByteMap[str:sub(idx, idx)]
		idx = idx + 1
	until idx == #str + 1

	return chars
end

return String

end)
__bundle_register("@luma/Utility/Table", function(require, _LOADED, __bundle_register, __bundle_modules)
local Table = {}

---@param input any[]
---@param start number
---@param stop number
---@return any[]
Table.slice = LPH_NO_VIRTUALIZE(function(input, start, stop)
	local out = {}

	if start == nil then
		start = 1
	elseif start < 0 then
		start = #input + start + 1
	end
	if stop == nil then
		stop = #input
	elseif stop < 0 then
		stop = #input + stop + 1
	end

	for idx = start, stop do
		table.insert(out, input[idx])
	end

	return out
end)

---@param input any[]
---@param predicate fun(value: any, index: number): boolean
---@return number, any
Table.find = LPH_NO_VIRTUALIZE(function(input, predicate)
	for idx, value in next, input do
		if not predicate(value, idx) then
			continue
		end

		return idx, value
	end
end)

return Table

end)
__bundle_register("@luma/Utility/TaskSpawner", function(require, _LOADED, __bundle_register, __bundle_modules)
local TaskSpawner = {}

---@module Utility.Profiler
local Profiler = require("@luma/Utility/Profiler")

---@module Utility.Logger
local Logger = require("@luma/Utility/Logger")

local RunService = game:GetService("RunService")

---@param label string
---@param delay function
---@param callback function
---@vararg any
function TaskSpawner.delay(label, delay, callback, ...)
	---@param error string
	local function onTaskFunctionError(error)
		Logger.trace("onTaskFunctionError - (%s) - %s", label, error)
	end

	local taskFunction = Profiler.wrap(
		label,
		LPH_NO_VIRTUALIZE(function(...)
			local timestamp = os.clock()

			while os.clock() - timestamp < delay() do
				RunService.RenderStepped:Wait()
			end

			return xpcall(callback, onTaskFunctionError, ...)
		end)
	)

	return task.spawn(taskFunction, ...)
end

---@param label string
---@param callback function
---@vararg any
function TaskSpawner.spawn(label, callback, ...)
	---@param error string
	local function onTaskFunctionError(error)
		Logger.trace("onTaskFunctionError - (%s) - %s", label, error)
	end

	local taskFunction = Profiler.wrap(
		label,
		LPH_NO_VIRTUALIZE(function(...)
			return xpcall(callback, onTaskFunctionError, ...)
		end)
	)

	return task.spawn(taskFunction, ...)
end

return TaskSpawner

end)
__bundle_register("@luma/Utility/Throttle", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class Throttle
--- Wrap a per-frame callback so it runs at most once per `interval` seconds, forwarding all
--- arguments (e.g. RenderStepped's dt) straight through. Uses os.clock, so it works regardless
--- of whether the driving signal passes a delta.
---
--- Intended for PASSIVE features that don't need full framerate (attribute farms, ownership
--- scan, ...). Do NOT use it on combat/UI/movement loops -- those want every frame.
---
---@param interval number Minimum seconds between calls.
---@param fn fun(...): ...
---@return fun(...): ...?
local function throttle(interval, fn)
	local last = 0

	return function(...)
		local now = os.clock()
		if now - last < interval then
			return
		end
		last = now
		return fn(...)
	end
end

return throttle

end)
